"""Advanced binary-RE helpers — the hardening layer on top of lib/elf.py's header/symbol reads.

Covers what the audit flagged as missing: packer detection + UPX unpacking, stripped-Go function-name
recovery from .gopclntab (names survive stripping there), Mach-O facts (lief), robust constant recovery via
capstone disassembly (replacing the fragile `b8..c3` byte regex), and a Ghidra headless decompile helper
(now that JDK 21 is wired). Everything is static. Pure-stdlib + capstone/lief/pyelftools from the venv.

hcfg_scan() (Day 14 prep) finds the lane's HCFG config blob in ANY of the storage encodings below and crc-gates it;
it is pure stdlib (no subprocess) so in-window solvers can call it on the Homebase VM.
"""
import array
import base64
import binascii
import bisect
import io
import itertools
import json
import math
import os
import re
import shutil
import struct
import subprocess
import tempfile
import time
import zipfile
import zlib
from dataclasses import dataclass, field
from pathlib import Path

GHIDRA_SCRIPT = Path(__file__).resolve().parent / "ghidra_scripts" / "DecompileDump.java"


# --- JVM jars ------------------------------------------------------------------------------------
# Bundled runtime/library packages in a fat jar. Kotlin builds ship the whole kotlin stdlib (~18k classes on Day 7):
# a solver that scans every class constant spent 5.9 s per run there (blind D7 replay: Time Trial "too slow").
JVM_LIBRARY = re.compile(r"(^|/)(kotlinx?|java|javax|androidx?|scala|org/jetbrains|org/intellij|com/google|okhttp3|okio)/")


def jar_app_classes(jar, include_nested=True):
    """[(entry name, class bytes)] for the APPLICATION classes of a jar (bytes or path): bundled library packages
    (JVM_LIBRARY: kotlin, java, androidx, ...) and META-INF are skipped; nested jars are searched too."""
    import zipfile
    data = jar if isinstance(jar, (bytes, bytearray)) else Path(jar).read_bytes()
    out = []
    try:
        z = zipfile.ZipFile(io.BytesIO(data))
    except zipfile.BadZipFile:
        return out
    for n in z.namelist():
        if n.endswith(".class") and not n.startswith("META-INF/") and not JVM_LIBRARY.search(n):
            out.append((n, z.read(n)))
        elif include_nested and n.endswith(".jar") and not JVM_LIBRARY.search(n):
            out += [(f"{n}!{m}", b) for m, b in jar_app_classes(z.read(n), include_nested=False)]
    return out


def class_utf8(cls):
    """Every CONSTANT_Utf8 string of a .class file (names, descriptors, string literals) in constant-pool order --
    a direct parse, ~50x faster than javap. [] if it isn't a class file."""
    b = bytes(cls)
    if b[:4] != b"\xca\xfe\xba\xbe" or len(b) < 10:
        return []
    count, i, k, out = int.from_bytes(b[8:10], "big"), 10, 1, []
    sizes = {3: 4, 4: 4, 5: 8, 6: 8, 7: 2, 8: 2, 9: 4, 10: 4, 11: 4, 12: 4, 15: 3, 16: 2, 17: 4, 18: 4, 19: 2, 20: 2}
    while k < count and i < len(b):
        tag = b[i]
        if tag == 1:
            ln = int.from_bytes(b[i + 1:i + 3], "big")
            out.append(b[i + 3:i + 3 + ln].decode("utf-8", "replace"))
            i += 3 + ln
        elif tag in sizes:
            i += 1 + sizes[tag]
            k += 1 if tag in (5, 6) else 0   # long/double take two pool slots
        else:
            break   # unknown tag: stop rather than misparse
        k += 1
    return out


# JVMS 4: full ClassFile facts (D17 re-asked D6/D7 jars: Main-Class methods in table order incl <init>, access_flags
# decimal 49, method_count incl <init>/<clinit>). Values are answer strings: decimal ints, compact JSON lists in
# table order, internal (slash) class names as javap -v prints them; "none" when the field is absent.
_CP_SIZES = {3: 4, 4: 4, 5: 8, 6: 8, 7: 2, 8: 2, 9: 4, 10: 4, 11: 4, 12: 4, 15: 3, 16: 2, 17: 4, 18: 4, 19: 2, 20: 2}
_CLASS_ACC = ((0x0001, "ACC_PUBLIC"), (0x0010, "ACC_FINAL"), (0x0020, "ACC_SUPER"), (0x0200, "ACC_INTERFACE"),
              (0x0400, "ACC_ABSTRACT"), (0x1000, "ACC_SYNTHETIC"), (0x2000, "ACC_ANNOTATION"), (0x4000, "ACC_ENUM"),
              (0x8000, "ACC_MODULE"))


def _jv(v):
    return json.dumps(v, separators=(",", ":"), ensure_ascii=False)


def _mutf8(raw):
    """JVMS 4.4.7 modified UTF-8: NUL is C0 80, supplementary chars are CESU-8 surrogate pairs (Kotlin d1 strings
    are protobuf bytes stored as chars, full of both)."""
    try:
        s = raw.replace(b"\xc0\x80", b"\0").decode("utf-8", "surrogatepass")
        return s.encode("utf-16-le", "surrogatepass").decode("utf-16-le")
    except UnicodeError:
        return raw.decode("utf-8", "replace")


def classfile_parse(cls):
    """Parse a .class (JVMS 4.1) -> dict of raw structures, or None if it is not a well-formed class file (a Mach-O
    fat header shares 0xcafebabe: its 'major' is a small arch count, rejected by major < 45)."""
    import struct
    b = bytes(cls)
    try:
        if b[:4] != b"\xca\xfe\xba\xbe":
            return None
        minor, major, cpn = struct.unpack_from(">HHH", b, 4)
        if not 45 <= major <= 80:
            return None
        cp, o, k = [None] * cpn, 10, 1
        while k < cpn:
            t = b[o]
            if t == 1:
                ln = struct.unpack_from(">H", b, o + 1)[0]
                if o + 3 + ln > len(b):
                    return None
                cp[k] = (1, _mutf8(b[o + 3:o + 3 + ln]))
                o += 3 + ln
            elif t in _CP_SIZES:
                raw = b[o + 1:o + 1 + _CP_SIZES[t]]
                if len(raw) < _CP_SIZES[t]:
                    return None
                if t == 3:
                    v = struct.unpack(">i", raw)[0]
                elif t == 4:
                    v = struct.unpack(">f", raw)[0]
                elif t == 5:
                    v = struct.unpack(">q", raw)[0]
                elif t == 6:
                    v = struct.unpack(">d", raw)[0]
                elif t == 15:
                    v = (raw[0], struct.unpack(">H", raw[1:])[0])
                elif len(raw) == 2:
                    v = struct.unpack(">H", raw)[0]
                else:
                    v = struct.unpack(">HH", raw)
                cp[k] = (t, v)
                o += 1 + _CP_SIZES[t]
                k += 1 if t in (5, 6) else 0   # long/double take two pool slots
            else:
                return None
            k += 1

        def u(i):
            e = cp[i] if 0 < i < cpn else None
            return e[1] if e and e[0] == 1 else None

        def cname(i):
            e = cp[i] if 0 < i < cpn else None
            return u(e[1]) if e and e[0] == 7 else None

        def attrs(o):
            n = struct.unpack_from(">H", b, o)[0]
            o += 2
            out = []
            for _ in range(n):
                ni, ln = struct.unpack_from(">HI", b, o)
                if o + 6 + ln > len(b):
                    raise ValueError("attr overrun")
                out.append((u(ni), b[o + 6:o + 6 + ln]))
                o += 6 + ln
            return out, o

        acc, this, sup, ni = struct.unpack_from(">HHHH", b, o)
        o += 8
        ifaces = [cname(struct.unpack_from(">H", b, o + 2 * j)[0]) for j in range(ni)]
        o += 2 * ni
        members = []
        for _ in range(2):
            n = struct.unpack_from(">H", b, o)[0]
            o += 2
            ms = []
            for _ in range(n):
                fa, nm, ds = struct.unpack_from(">HHH", b, o)
                at, o = attrs(o + 6)
                ms.append({"access": fa, "name": u(nm), "descriptor": u(ds), "attributes": at})
            members.append(ms)
        cattrs, o = attrs(o)
    except (struct.error, IndexError, ValueError):
        return None
    return {"minor": minor, "major": major, "cp_count": cpn, "cp": cp, "access": acc, "this": cname(this),
            "super": cname(sup) if sup else None, "interfaces": ifaces, "fields": members[0],
            "methods": members[1], "attributes": cattrs, "_u": u, "_cname": cname, "trailing": len(b) - o}


def _annotations(raw, u):
    """RuntimeVisible/InvisibleAnnotations attribute -> [(type descriptor, {element name: value})] (JVMS 4.7.16)."""
    import struct
    pos = [0]

    def u2():
        v = struct.unpack_from(">H", raw, pos[0])[0]
        pos[0] += 2
        return v

    def value(cp):
        tag = chr(raw[pos[0]])
        pos[0] += 1
        if tag in "BCIJSZDF":
            e = cp[u2()]
            return e[1] if e else None
        if tag == "s":
            return u(u2())
        if tag == "e":
            return [u(u2()), u(u2())]
        if tag == "c":
            return u(u2())
        if tag == "@":
            return ann(cp)
        if tag == "[":
            return [value(cp) for _ in range(u2())]
        raise ValueError(tag)

    def ann(cp):
        t = u(u2())
        return t, {u(u2()): value(cp) for _ in range(u2())}
    return ann, u2


def classfile_facts(cls):
    """{field: answer string} for one .class -- javap -v -p parity: minor/major_version, constant_pool_count (header
    value = entries + 1), access_flags (decimal) / _hex / access_flag_names, this_class, super_class, interfaces,
    fields (+descriptors/count), methods (+descriptors/count, table order incl <init>/<clinit>), attributes,
    source_file, signature, string_constants, kotlin metadata (kotlin_k/mv/d1/d2/xi/xs/pn). None if not a class."""
    p = classfile_parse(cls)
    if not p:
        return None
    u = p["_u"]
    acc = p["access"]
    f = {"magic": "0xcafebabe", "minor_version": str(p["minor"]), "major_version": str(p["major"]),
         "class_version": f"{p['major']}.{p['minor']}",
         "java_version": str(p["major"] - 44) if p["major"] >= 49 else "1." + str(p["major"] - 44),
         "constant_pool_count": str(p["cp_count"]),
         "constant_pool_entries": str(sum(1 for e in p["cp"] if e)),
         "access_flags": str(acc), "access_flags_hex": f"0x{acc:04x}",
         "access_flag_names": _jv([n for m, n in _CLASS_ACC if acc & m]),
         "this_class": p["this"] or "none", "this_class_dotted": (p["this"] or "none").replace("/", "."),
         "super_class": p["super"] or "none", "super_class_dotted": (p["super"] or "none").replace("/", "."),
         "interfaces": _jv(p["interfaces"]), "interface_count": str(len(p["interfaces"])),
         "fields": _jv([m["name"] for m in p["fields"]]), "field_count": str(len(p["fields"])),
         "field_descriptors": _jv([m["descriptor"] for m in p["fields"]]),
         "methods": _jv([m["name"] for m in p["methods"]]), "method_count": str(len(p["methods"])),
         "method_descriptors": _jv([m["descriptor"] for m in p["methods"]]),
         "method_signatures": _jv([f"{m['name']}{m['descriptor']}" for m in p["methods"]]),
         "method_access_flags": _jv([m["access"] for m in p["methods"]]),
         "attributes": _jv([a for a, _ in p["attributes"]]), "attribute_count": str(len(p["attributes"])),
         "string_constants": _jv([u(e[1]) for e in p["cp"] if e and e[0] == 8]),
         "has_clinit": _jv(any(m["name"] == "<clinit>" for m in p["methods"])),
         "has_main": _jv(any(m["name"] == "main" and m["descriptor"] == "([Ljava/lang/String;)V"
                             for m in p["methods"]))}
    ca = dict(p["attributes"])
    sf = ca.get("SourceFile")
    f["source_file"] = (u(int.from_bytes(sf[:2], "big")) or "none") if sf and len(sf) >= 2 else "none"
    sg = ca.get("Signature")
    f["signature"] = (u(int.from_bytes(sg[:2], "big")) or "none") if sg and len(sg) >= 2 else "none"
    f["has_kotlin_metadata"] = "false"
    for key in ("kotlin_k", "kotlin_mv", "kotlin_bv", "kotlin_d1", "kotlin_d2", "kotlin_xi", "kotlin_xs", "kotlin_pn"):
        f[key] = "none"
    for an in ("RuntimeVisibleAnnotations", "RuntimeInvisibleAnnotations"):
        raw = ca.get(an)
        if not raw:
            continue
        try:
            ann, u2 = _annotations(raw, u)
            anns = [ann(p["cp"]) for _ in range(u2())]
        except (ValueError, IndexError, TypeError):
            continue
        for t, ev in anns:
            if t == "Lkotlin/Metadata;":
                f["has_kotlin_metadata"] = "true"
                for k, v in ev.items():
                    f[f"kotlin_{k}"] = _jv(v) if isinstance(v, list) else str(v)
    f["is_suspend_lambda"] = _jv(any(m["name"] == "invokeSuspend" for m in p["methods"]))
    f.update(_jvm_lang_facts(p, ca, f))
    return f


# D26 leak "the primary classfile named by that unit": Scala / Clojure / Groovy builds. Markers (javap -v): Scala
# companion class carries ScalaSig attr + @scala.reflect.ScalaSignature, its `X$` module class only ScalaInlineInfo +
# a static MODULE$ field; Clojure AOT emits `<ns>__init.class` (+ `<ns>$fn.class`) calling clojure/lang/RT; groovyc
# classes implement groovy/lang/GroovyObject and define $getStaticMetaClass.
_SCALA_ANN = ("Lscala/reflect/ScalaSignature;", "Lscala/reflect/ScalaLongSignature;")


def _jvm_lang_facts(p, ca, f):
    u, this = p["_u"], p["this"] or ""
    utf = {e[1] for e in p["cp"] if e and e[0] == 1}
    meths = {m["name"] for m in p["methods"]}
    scala_sig = "ScalaSig" in ca or any(a in utf for a in _SCALA_ANN)
    module = this.endswith("$") and any(m["name"] == "MODULE$" and m["access"] & 0x0008 for m in p["fields"])
    scala = scala_sig or "ScalaInlineInfo" in ca or (module and any(x.startswith("scala/") for x in utf))
    groovy = "groovy/lang/GroovyObject" in p["interfaces"] or "$getStaticMetaClass" in meths
    clj_init = this.endswith("__init") and "clojure/lang/RT" in utf
    clojure = clj_init or any(x.startswith("clojure/lang/") for x in utf)
    lang = ("kotlin" if f.get("has_kotlin_metadata") == "true" else "scala" if scala else "groovy" if groovy
            else "clojure" if clojure else "java")
    bsm = ca.get("BootstrapMethods")
    indy = 0
    for m in p["methods"]:
        code = dict(m["attributes"]).get("Code")
        if code and len(code) >= 8:
            try:
                indy += sum(op == 0xba for _, op, _ in jvm_code_decode(code[8:8 + int.from_bytes(code[4:8], "big")]))
            except (ValueError, struct.error, IndexError):
                pass
    names = [m["name"] or "" for m in p["methods"]]
    anon = [n for n in names if "$anonfun$" in n]
    synth = [m["name"] for m in p["methods"] if m["access"] & 0x1000]
    # Scala 3 writes a 16-byte TASTY attribute (UUID of the .tasty) and no ScalaSig/ScalaInlineInfo; Scala 2 the reverse
    smaj = "3" if "TASTY" in ca else "2" if scala_sig or "ScalaInlineInfo" in ca else "none"
    return {"has_tasty_attribute": _jv("TASTY" in ca), "scala_major": smaj,
            "bootstrap_method_count": str(int.from_bytes(bsm[:2], "big")) if bsm and len(bsm) >= 2 else "0",
            "invokedynamic_count": str(indy),
            "invokedynamic_cp_count": str(sum(1 for e in p["cp"] if e and e[0] == 18)),
            "anonfun_methods": _jv(anon), "anonfun_method_count": str(len(anon)),
            "lambda_methods": _jv([n for n in names if n.startswith("lambda$") or "$anonfun$" in n]),
            "synthetic_methods": _jv(synth), "synthetic_method_count": str(len(synth)),
            "has_module_field": _jv(module), "jvm_language": lang, "has_scala_signature": _jv(scala_sig), "has_scala_sig_attribute":
            _jv("ScalaSig" in ca), "is_scala_module": _jv(bool(scala and module)),
            "scala_companion_of": this[:-1] if scala and module else "none",
            "is_groovy_object": _jv("groovy/lang/GroovyObject" in p["interfaces"]),
            "has_groovy_metaclass": _jv("$getStaticMetaClass" in meths),
            "clojure_namespace": _clj_ns(this[:-6]) if clj_init else "none"}


def _clj_ns(internal):
    """Clojure munged class path -> namespace (hello/my_app -> hello.my-app; Compiler.munge maps - to _)."""
    return internal.replace("/", ".").replace("_", "-")


def jvm_member_from_question(question, names):
    """The classfile entry a question names ("... the primary classfile acme/Beacon$.class", "class com.acme.Main",
    "Clojure namespace hello.core init class"): explicit *.class / slash paths first, then dotted class names, in
    question order; an unambiguous basename also matches. None when nothing in `names` is named (-> Main-Class)."""
    if not question or not names:
        return None
    cls = [n for n in names if n.endswith(".class")]
    base = {}
    for n in cls:
        base.setdefault(n.rsplit("/", 1)[-1], []).append(n)
    toks = re.findall(r"[\w$./-]+\.class\b", question)
    toks += [t + ".class" for t in re.findall(r"\b[A-Za-z_$][\w$]*(?:/[A-Za-z_$][\w$-]*)+\b\$*", question)]
    for t in re.findall(r"(?<![\w$./-])[A-Za-z_$][\w$-]*(?:\.[A-Za-z_$][\w$-]*)+\$*", question):
        if not re.search(r"\.(?:class|jar|zip|war|ear|apk|exe|dll|elf|bin|json|clj|scala|groovy|kt|java)$", t):
            path = t.replace(".", "/")
            pair = [path + ".class", path.replace("-", "_") + "__init.class"]
            toks += pair[::-1] if re.search(r"__init|\binit(?:iali[sz]er)?\b", question, re.I) else pair
    for t in toks:
        t = t.lstrip("./")
        if t in cls:
            return t
        hit = [n for n in cls if n.endswith("/" + t)] or ([] if "/" in t else base.get(t, []))
        if len(hit) == 1:
            return hit[0]
    return None


def jar_jvm_facts(data, member=None, question=None):
    """{field: answer string} for a jar (or a bare .class): jar-level main_class (Manifest Main-Class, dotted as
    written), created_by, class_count (.class entries), entry_count (all zip entries incl directories), plus
    classfile_facts of `member` (entry name or dotted class name), else of the class `question` names
    (jvm_member_from_question), else of the Main-Class. None if neither."""
    import zipfile
    b = bytes(data)
    unit = re.search(r"(?<![\w$/.-])([\w$/-]+\.(?:scala|clj|cljc|groovy|kt|java))\b", question or "")
    if b[:4] == b"\xca\xfe\xba\xbe":
        cf = classfile_facts(b)
        hf = classfile_hcfg(b)
        hf["hcfg_classfile"] = cf["this_class"] + ".class" if hf["hcfg_found"] == "true" else "none"
        if not cf:
            return None
        out = {**cf, "container_format": "class", **_jvm_bare_unit(cf, unit and unit.group(1)), **hf}
        return _jvm_niche_merge(out, b, question)
    try:
        z = zipfile.ZipFile(io.BytesIO(b))
        names = z.namelist()
        mf = z.read("META-INF/MANIFEST.MF").decode("utf-8", "replace") if "META-INF/MANIFEST.MF" in names else ""
    except (zipfile.BadZipFile, KeyError, OSError, EOFError, RuntimeError, ValueError):
        return None
    mf = re.sub(r"\r?\n ", "", mf)   # manifest continuation lines (72-byte wrap)
    man = dict(re.findall(r"^([A-Za-z0-9_-]+):\s*(.*?)\s*$", mf, re.M))
    out = {"main_class": man.get("Main-Class") or "none", "created_by": man.get("Created-By") or "none",
           "manifest_version": man.get("Manifest-Version") or "none",
           "class_count": str(sum(n.endswith(".class") for n in names)), "entry_count": str(len(names)),
           "app_class_count": str(sum(n.endswith(".class") and not n.startswith("META-INF/")
                                      and not JVM_LIBRARY.search(n) for n in names)),
           "has_kotlin_runtime": _jv(any(n.startswith("kotlin/") for n in names)),
           "has_coroutine_runtime": _jv(any(n.startswith(("kotlin/coroutines/", "kotlinx/coroutines/"))
                                             for n in names))}   # D7/D17: stdlib kotlin/coroutines/ counts (GM true)
    inits = [n[:-12] for n in names if n.endswith("__init.class") and not n.startswith(("clojure/", "META-INF/"))]
    lang = ("scala" if any(n.startswith("scala/") for n in names) else
            "clojure" if inits or any(n.startswith("clojure/lang/") for n in names) else
            "groovy" if any(n.startswith("groovy/lang/") for n in names) else
            "kotlin" if out["has_kotlin_runtime"] == "true" else "none")
    out.update(container_format="jar", jar_language=lang, clojure_namespaces=_jv([_clj_ns(n) for n in inits]),
               jvm_language=lang)
    main_ent = out["main_class"].replace(".", "/") + ".class" if out["main_class"] != "none" else None
    explicit = member or jvm_member_from_question(question.replace(unit.group(1), " ") if unit else question, names)
    uprim = _jvm_unit_primary(z, names, _jvm_unit_start(z, names, unit.group(1)) if unit else main_ent)
    target = explicit or (uprim[0] if unit and uprim[0] else None) or \
        (uprim[0] if uprim[0] and re.search(r"(?i)\bprimary\s+class", question or "") else None) or \
        (out["main_class"] if out["main_class"] != "none" else None)
    out.update(_jvm_unit_fields(z, names, uprim))
    out["jvm_member"] = "none"
    if target:
        ent = target if target.endswith(".class") else target.replace(".", "/") + ".class"
        try:
            cf = classfile_facts(z.read(ent)) if ent in names else None
        except (zipfile.BadZipFile, OSError, EOFError, RuntimeError, ValueError):
            cf = None
        if cf:
            out = {**cf, **out, "jvm_member": ent, "jvm_language": cf["jvm_language"]}
    # HCFG carrier (D7 rule): the target / unit-primary class's constant pool first, then every application class
    app = [n for n in names if n.endswith(".class") and not n.startswith("META-INF/") and not JVM_LIBRARY.search(n)]
    app.sort(key=lambda n: bool(_NICHE_RT.match(n)))   # bundled jython/jruby/ceylon/... runtime classes last
    for ent in [out["jvm_member"], out.get("primary_classfile")] + app[:512]:
        try:
            hf = classfile_hcfg(z.read(ent)) if ent in names else {}
        except (zipfile.BadZipFile, OSError, EOFError, RuntimeError, ValueError, NotImplementedError):
            hf = {}
        if hf.get("hcfg_found") == "true":
            out.update({**hf, "hcfg_classfile": ent})
            break
    else:
        out.update(classfile_hcfg(b""))
    if lang == "clojure":   # D25 Clojure AOT identity facts: only keys not already answered above (+ clojure_ alias)
        for k, v in (clojure_facts(b) or {}).items():
            out.setdefault(k, v)
            out.setdefault("clojure_" + k, v)
    if "groovy" in (out.get("jvm_language"), out.get("primary_jvm_language")):   # D26 groovyc unit facts (same rule)
        for k, v in (groovy_facts(b, question) or {}).items():
            out.setdefault(k, v)
            out.setdefault("groovy_" + k, v)
    return _jvm_niche_merge(out, b, question)


def _jvm_niche_merge(out, b, question):
    """jvm_niche_facts keys (setdefault) + niche_-stripped aliases; a niche cue relabels a plain "java"/"none"
    jvm_language / jar_language, and a named niche unit (X.py, X.rb, x.main.kts, ...) owns primary_classfile."""
    nf = jvm_niche_facts(b, question) or {}
    for k, v in nf.items():
        out.setdefault(k, v)
    lang = nf.get("niche_language", "none")
    if lang == "none":
        return out
    for k in ("jvm_language", "jar_language"):
        if out.get(k) in ("java", "none", None):
            out[k] = lang
    for k in ("primary_classfile", "primary_class", "primary_class_dotted", "primary_super_class", "unit"):
        v = nf.get("niche_" + k)
        if v is not None and v != "none" and (out.get(k) in (None, "none") or _NICHE_UNIT.search(question or "")):
            out[k] = v
    return out


_CP_B64 = re.compile(r"[A-Za-z0-9+/]{80,}={0,2}")


def classfile_hcfg(cls):
    """HCFG carried in one .class constant pool (D7 rule: each CONSTANT_Utf8 of >= 80 base64-alphabet chars is
    base64-decoded; the first crc-valid HCFG JSON record wins) -> {hcfg_found, hcfg_version, hcfg_key, xor_key_hex,
    hcfg_length, crc32_hex, hcfg_config (compact JSON), config_<top-level key>}; "none" values when absent."""
    out = {"hcfg_found": "false", "hcfg_version": "none", "hcfg_key": "none", "xor_key_hex": "none",
           "hcfg_length": "none", "crc32_hex": "none", "config_crc32_hex": "none", "hcfg_config": "none"}
    try:
        for s in class_utf8(cls)[:4096]:
            if len(s) > (1 << 20) or not _CP_B64.fullmatch(s):
                continue
            try:
                raw = base64.b64decode(s + "=" * (-len(s) % 4))
            except (ValueError, binascii.Error):
                continue
            r = _parse_blob(raw) if raw[:4] == HCFG_MAGIC else None
            if not r or not r[5] or not isinstance(r[6], dict):
                continue
            ver, key, ln, crc, _, _, cfg = r
            out.update(hcfg_found="true", hcfg_version=str(ver), hcfg_key=str(key), xor_key_hex=f"0x{key:02x}",
                       hcfg_length=str(ln), crc32_hex=f"0x{crc:08x}", config_crc32_hex=f"0x{crc:08x}",
                       hcfg_config=json.dumps(cfg, separators=(",", ":"), ensure_ascii=False))
            for k, v in cfg.items():
                out.setdefault(f"config_{k}", v if isinstance(v, str) else _jv(v))
            return out
    except Exception:  # noqa: BLE001
        pass
    return out


def _jvm_bare_unit(cf, unit):
    """primary_/forwarder_ fields for a bare .class: it is the primary classfile when the question names no unit, or
    when its this_class basename (scalac X$ -> X) / SourceFile matches the unit; else primary_* "none"."""
    out = {"forwarder_classfile": "none", "forwarder_class": "none", "forwarder_class_dotted": "none"}
    fn = unit.rsplit("/", 1)[-1] if unit else None
    hit = not unit or cf["source_file"] == fn or \
        cf["this_class"].rsplit("/", 1)[-1].rstrip("$") == fn.rsplit(".", 1)[0].replace("-", "_")
    ent = cf["this_class"] + ".class" if hit else "none"
    out.update(jvm_member=ent, primary_classfile=ent, primary_class=cf["this_class"] if hit else "none",
               primary_class_dotted=cf["this_class_dotted"] if hit else "none")
    out.update({f"primary_{k}": (v if hit else "none") for k, v in cf.items()})
    return out


def _jvm_cf(z, names, ent):
    try:
        return classfile_facts(z.read(ent)) if ent and ent in names else None
    except (zipfile.BadZipFile, OSError, EOFError, RuntimeError, ValueError, KeyError):
        return None


def _jvm_unit_start(z, names, unit):
    """Class entry a source unit names ("Day24Vulnerable000.scala", "hello/core.clj"): app classes whose SourceFile
    is that file name, preferring the one named after it (X / X$ / X__init), then one with main(String[]); falls back to
    the entry whose basename is the unit stem. None when nothing matches."""
    fn = unit.rsplit("/", 1)[-1]
    stem = fn.rsplit(".", 1)[0]
    pre = unit.rsplit(".", 1)[0].replace(".", "/") if "/" in unit else None
    cand = []
    for n in [n for n in names if n.endswith(".class") and not n.startswith("META-INF/")
              and not JVM_LIBRARY.search(n)][:512]:
        cf = _jvm_cf(z, names, n)
        if cf and cf["source_file"] == fn:
            cand.append((n, cf))
    if not cand:
        cand = [(n, None) for n in names if n.rsplit("/", 1)[-1] in (f"{stem}.class", f"{stem}$.class")]
    for suf in (".class", "$.class", "__init.class"):
        hit = [n for n, _ in cand if n.rsplit("/", 1)[-1] == stem.replace("-", "_") + suf
               and (pre is None or n.startswith(pre.replace("-", "_")))]
        if hit:
            return hit[0]
    # Clojure: -main compiles to <ns>$_main (the gen-class stub and <ns>__init carry no SourceFile)
    hit = [n for n, cf in cand if cf and cf["has_main"] == "true"] or [n for n, _ in cand if n.endswith("$_main.class")]
    return (hit or [n for n, _ in cand] or [None])[0]


def _jvm_unit_primary(z, names, ent):
    """(primary entry, forwarder entry) of the unit whose class entry is `ent`: scalac `object X` -> X$.class (the
    module: MODULE$, the logic, the config ldc) is primary and X.class (static forwarders, Main-Class) the forwarder;
    Clojure gen-class X -> X__init.class primary; otherwise X itself, no forwarder. (None, None) when `ent` is absent."""
    if not ent or ent not in names:
        return None, None
    base = ent[:-6]
    if base.endswith("$"):
        cf = _jvm_cf(z, names, ent)
        if cf and cf["has_module_field"] == "true":
            return ent, (base[:-1] + ".class" if base[:-1] + ".class" in names else None)
        return ent, None
    cf = _jvm_cf(z, names, base + "$.class")
    if cf and cf["has_module_field"] == "true":
        return base + "$.class", ent
    if base + "__init.class" in names and not base.endswith("__init"):
        return base + "__init.class", ent
    return ent, None


def _jvm_unit_fields(z, names, prim):
    """primary_/forwarder_ class + classfile fields (each classfile_facts key prefixed) and the jar's scala_major."""
    out = {}
    tasty = [n for n in names if n.endswith(".tasty")]
    for role, ent in zip(("primary", "forwarder"), prim):
        cf = _jvm_cf(z, names, ent) if ent else None
        out[f"{role}_classfile"] = ent if cf else "none"
        out[f"{role}_class"] = cf["this_class"] if cf else "none"
        out[f"{role}_class_dotted"] = cf["this_class_dotted"] if cf else "none"
        for k, v in (cf or {}).items():
            out[f"{role}_{k}"] = v
        out[f"{role}_scala_major"] = out.get(f"{role}_scala_major", "none")
    out["module_class"] = out["primary_class"] if out.get("primary_has_module_field") == "true" else "none"
    majors = {out.get("primary_scala_major"), out.get("forwarder_scala_major")}
    out.update(tasty_entries=_jv(tasty), tasty_count=str(len(tasty)), has_tasty_entries=_jv(bool(tasty)),
               scala_major="3" if tasty or "3" in majors else "2" if "2" in majors else "none")
    return out


def jvm_field(data, field, member=None, question=None):
    """One JVM fact as an answer string; "none" when the container parses but the field is absent, None when the
    bytes are neither a jar nor a class file. `question` may name the classfile (see jar_jvm_facts). Never raises."""
    try:
        f = jar_jvm_facts(data, member, question)
    except Exception:  # noqa: BLE001
        return None
    if f is None:
        return None
    return f.get(field, "none")


# --- Clojure AOT namespace facts (D25 "out of bounds": a gen-class'd Clojure ns, no clojure.jar bundled) -----------
# `<ns>__init.class` __init0..N build every constant in order: RT.var("<ns>","<name>") per Var (own ns = defs, in
# definition order), RT.map(:line L :column C :file F [:arglists ([..])]) right after a def'd Var; load() binds each
# Var root (`new <ns>$<munged>` fn class, or an ldc value: the HCFG blob of `encoded-config`). Class names demunge
# with Compiler.CHAR_MAP (`_` -> `-`, `_main` -> `-main`); `$fn__N` = anonymous fn, `$loading__N__auto____M` = the ns
# loader. Spellings follow javap: classes slash-internal (`day25/vulnerable000$parse_frame`), + *_dotted variants.
_CLJ_MUNGE = {"-": "_", ":": "_COLON_", "+": "_PLUS_", ">": "_GT_", "<": "_LT_", "=": "_EQ_", "~": "_TILDE_",
              "!": "_BANG_", "@": "_CIRCA_", "#": "_SHARP_", "'": "_SINGLEQUOTE_", '"': "_DOUBLEQUOTE_",
              "%": "_PERCENT_", "^": "_CARET_", "&": "_AMPERSAND_", "*": "_STAR_", "|": "_BAR_", "{": "_LBRACE_",
              "}": "_RBRACE_", "[": "_LBRACK_", "]": "_RBRACK_", "/": "_SLASH_", "\\": "_BSLASH_", "?": "_QMARK_"}
_CLJ_DEMUNGE = re.compile("|".join(re.escape(v) for v in sorted(set(_CLJ_MUNGE.values()), key=len, reverse=True)))
_CLJ_HCFG = (b"HCFG", b"SENGR", b"48434647", b"JBBUOR")   # raw / base64 / hex / base32 prefixes of the magic


def _clj_demunge(s):
    inv = {v: k for k, v in _CLJ_MUNGE.items()}
    return _CLJ_DEMUNGE.sub(lambda m: inv[m.group(0)], s)


def _clj_form(v):
    """Simulated constant -> Clojure reader text (symbols bare, keywords :k, vectors [..], lists (..))."""
    if isinstance(v, tuple) and v:
        if v[0] in ("sym", "var"):
            return v[1] + "/" + v[2] if v[1] and v[0] == "sym" else v[2]
        if v[0] == "kw":
            return ":" + (v[1] + "/" if v[1] else "") + v[2]
        if v[0] in ("vec", "list"):
            o, c = "[]" if v[0] == "vec" else "()"
            return o + " ".join(_clj_form(x) for x in v[1]) + c
    if isinstance(v, dict):
        return "{" + ", ".join(f"{_clj_form(k)} {_clj_form(x)}" for k, x in v.items()) + "}"
    return json.dumps(v) if isinstance(v, str) else "nil" if v is None else str(v)


def _clj_sim(p, code, fields, events):
    """Abstract-interpret one __init method: constant-building calls only. putstatic records field -> value; RT.var /
    RT.map results append to `events` in program order. Unknown ops reset the stack (never raises past here)."""
    cp, u = p["cp"], p["_u"]

    def ref(i):
        e = cp[i] if 0 < i < len(cp) else None
        if not e or e[0] not in (9, 10, 11):
            return None, None, None
        c, nt = cp[e[1][0]], cp[e[1][1]]
        return u(c[1]) if c and c[0] == 7 else None, u(nt[1][0]), u(nt[1][1])

    st = []
    for _, op, a in jvm_code_decode(code):
        if op == 0x01:
            st.append(None)
        elif 0x02 <= op <= 0x08:
            st.append(op - 3)
        elif op in (0x10, 0x11):
            st.append(a[0])
        elif op in (0x12, 0x13, 0x14):
            e = cp[a[0]] if 0 < a[0] < len(cp) else None
            st.append(u(e[1]) if e and e[0] == 8 else e[1] if e and e[0] in (3, 4, 5, 6) else None)
        elif op == 0x59 and st:
            st.append(st[-1])
        elif op == 0xc0:
            pass
        elif op == 0xbd and st:
            n = st.pop()
            st.append([None] * n if isinstance(n, int) and 0 <= n < 4096 else [])
        elif op == 0x53 and len(st) >= 3:
            v, i, arr = st.pop(), st.pop(), st.pop()
            if isinstance(arr, list) and isinstance(i, int) and 0 <= i < len(arr):
                arr[i] = v
        elif op == 0xb3 and st:
            fields[ref(a[0])[1]] = st.pop()
        elif op == 0xb8:
            own, name, desc = ref(a[0])
            if not desc:
                st = []
                continue
            n = len(_JT_PARAM.findall(desc[1:desc.index(")")]))
            args = ([None] * n + st)[-n:] if n else []   # underflow after a reset: unknown operands
            del st[max(0, len(st) - n):]
            r = None
            if own == "clojure/lang/RT" and name == "var" and n == 2:
                r = ("var", *args)
                events.append(r)
            elif own == "clojure/lang/Symbol" and name == "intern":
                r = ("sym", *(args if n == 2 else (None, args[0])))
            elif own == "clojure/lang/RT" and name == "keyword" and n == 2:
                r = ("kw", *args)
            elif own in ("java/lang/Integer", "java/lang/Long") and name == "valueOf":
                r = args[0]
            elif own == "clojure/lang/RT" and name == "map" and args and isinstance(args[0], list):
                kv = args[0]
                r = {kv[i]: kv[i + 1] for i in range(0, len(kv) - 1, 2) if isinstance(kv[i], (tuple, str, int))}
                events.append(r)
            elif own == "clojure/lang/Tuple" and name == "create" or own == "clojure/lang/RT" and name == "vector":
                r = ("vec", tuple(args[0] if name == "vector" and args and isinstance(args[0], list) else args))
            elif own == "java/util/Arrays" and name == "asList":
                r = args[0]
            elif own == "clojure/lang/PersistentList" and name == "create":
                r = ("list", tuple(args[0]) if isinstance(args[0], list) else ())
            if desc[-1] != "V":
                st.append(r)
        elif op == 0x57:
            st = st[:-1]
        elif op == 0xb2:
            st.append(fields.get(ref(a[0])[1]))
        elif op != 0xb1:
            st = []


def clojure_facts(data):
    """{field: answer string} for a Clojure AOT jar: namespace, vars (definition order), fn_classes / var_fn_classes
    (Var -> `<ns>$<munged>` class), anon/loader classes, init_class, gen-class stub, source_file (SourceFile attr),
    source_path (:file meta), var_lines/columns/arglists, fn_invoke_static_arity, primary_class (class holding the
    HCFG ldc, else __init), main_class (manifest), has_clojure_runtime (clojure/lang/ entries bundled) vs
    references_clojure_runtime. "none" fields when no `<ns>__init.class`; None when not a zip/jar. Never raises."""
    import zipfile
    try:
        z = zipfile.ZipFile(io.BytesIO(bytes(data)))
        names = z.namelist()
    except Exception:  # noqa: BLE001
        return None
    try:
        return _clojure_facts(z, names)
    except Exception:  # noqa: BLE001
        return {"namespace": "none"}


def _clojure_facts(z, names):
    mf = ""
    if "META-INF/MANIFEST.MF" in names:
        mf = re.sub(r"\r?\n ", "", z.read("META-INF/MANIFEST.MF").decode("utf-8", "replace"))
    main = dict(re.findall(r"^([A-Za-z0-9_-]+):\s*(.*?)\s*$", mf, re.M)).get("Main-Class") or "none"
    inits = [n for n in names if n.endswith("__init.class") and not n.startswith(("clojure/", "META-INF/"))]
    pref = main.replace(".", "/") + "__init.class"
    inits.sort(key=lambda n: n != pref)
    out = {"main_class": main, "has_clojure_runtime": _jv(any(n.startswith("clojure/lang/") for n in names)),
           "clojure_init_classes": _jv([n[:-6] for n in inits])}
    keys = ("namespace", "vars", "var_count", "fn_classes", "fn_classes_dotted", "var_fn_classes", "anon_fn_classes",
            "ns_loader_class", "loader_gensym", "init_class", "init_class_dotted", "gen_class", "gen_class_has_main",
            "source_file", "source_path", "var_lines", "var_columns", "var_arglists", "var_values",
            "fn_invoke_static_arity", "variadic_fns", "primary_class", "primary_class_dotted",
            "references_clojure_runtime", "clojure_class_major")
    out.update({k: "none" for k in keys})
    if not inits:
        return out
    ient = inits[0]
    p = classfile_parse(z.read(ient))
    if not p:
        return out
    base = ient[:-12]
    fields, events = {}, []
    meths = {m["name"]: dict(m["attributes"]).get("Code") for m in p["methods"]}
    for k in sorted((m for m in meths if re.fullmatch(r"__init\d+", m or "")), key=lambda m: int(m[6:])):
        code = meths[k]
        if code and len(code) >= 8:
            try:
                _clj_sim(p, code[8:8 + int.from_bytes(code[4:8], "big")], fields, events)
            except (ValueError, IndexError, KeyError, TypeError, struct.error):
                pass
    own = [e for e in events if isinstance(e, tuple) and e[1] not in (None, "clojure.core")]
    if not own:   # a class merely named *__init (no RT.var constants): not a Clojure namespace
        return out
    ns = own[0][1]
    vars_, meta, last = [], {}, None
    for e in events:
        if isinstance(e, tuple):
            last = e[2] if e[1] == ns else None
            if last is not None and last not in vars_:
                vars_.append(last)
        elif last is not None and last not in meta and any(k[2] == "line" for k in e if isinstance(k, tuple)):
            meta[last] = {k[2]: v for k, v in e.items() if isinstance(k, tuple) and k[0] == "kw"}
    # load(): getstatic <Var const> ... new <ns>$X / ldc "..." ... Var.bindRoot binds that Var's root
    fn, vals, cur, pend = {}, {}, None, None
    code = meths.get("load")
    if code and len(code) >= 8:
        cp, u = p["cp"], p["_u"]
        for _, op, a in jvm_code_decode(code[8:8 + int.from_bytes(code[4:8], "big")]):
            if op == 0xb2:
                e = cp[a[0]]
                v = fields.get(u(cp[e[1][1]][1][0])) if e and e[0] == 9 else None
                if isinstance(v, tuple) and v[0] == "var" and v[1] == ns:
                    cur, pend = v[2], None
            elif op == 0xbb:
                c = p["_cname"](a[0]) or ""
                if c.startswith(base + "$"):
                    pend = c
            elif op in (0x12, 0x13):
                e = cp[a[0]]
                if e and e[0] == 8:
                    pend = ("val", u(e[1]))
            elif op == 0xb6 and cur:
                e = cp[a[0]]
                if e and e[0] == 10 and u(cp[e[1][1]][1][0]) == "bindRoot" and pend:
                    (vals if isinstance(pend, tuple) else fn).setdefault(cur, pend[1] if isinstance(pend, tuple)
                                                                         else pend)
                    pend = None
    subs = [n[:-6] for n in names if n.startswith(base + "$") and n.endswith(".class")]
    anon = [c for c in subs if re.fullmatch(r"fn__\d+", c[len(base) + 1:])]
    loader = [c for c in subs if re.fullmatch(r"loading__\d+__auto____\d+", c[len(base) + 1:])]
    for v in vars_:   # fall back to Compiler.munge naming when load() binding was not seen
        m = base + "$" + "".join(_CLJ_MUNGE.get(ch, ch) for ch in v)
        if v not in fn and v not in vals and m in subs:
            fn[v] = m
    fcls = [fn[v] for v in vars_ if v in fn]
    src, arity, variadic, refs, prim = "none", {}, [], False, None
    for c in [base + "__init"] + subs + [base]:
        ent = c + ".class"
        if ent not in names:
            continue
        b = z.read(ent)
        refs = refs or b"clojure/lang/" in b
        q = classfile_parse(b) if c in fcls or src == "none" or prim is None else None
        if q and src == "none":
            sf = dict(q["attributes"]).get("SourceFile")
            src = q["_u"](int.from_bytes(sf[:2], "big")) if sf and len(sf) >= 2 else "none"
        if q and prim is None:
            if any(e and e[0] == 8 and (q["_u"](e[1]) or "").encode()[:8].startswith(_CLJ_HCFG) for e in q["cp"]):
                prim = c
        if q and c in fcls:
            v = next(k for k, x in fn.items() if x == c)
            ds = [m["descriptor"] for m in q["methods"] if m["name"] == "invokeStatic"]
            if ds:   # multi-arity fns carry one invokeStatic per arity: "1,2"
                arity[v] = ",".join(sorted({str(len(_JT_PARAM.findall(d[1:d.index(")")]))) for d in ds}, key=int))
            if q["super"] == "clojure/lang/RestFn":
                variadic.append(v)
    gp = classfile_parse(z.read(base + ".class")) if base + ".class" in names else None
    prim = prim or base + "__init"
    out.update(namespace=ns, vars=_jv(vars_), var_count=str(len(vars_)), fn_classes=_jv(fcls),
               fn_classes_dotted=_jv([c.replace("/", ".") for c in fcls]),
               var_fn_classes=_jv({v: fn[v] for v in vars_ if v in fn}),
               anon_fn_classes=_jv(anon), ns_loader_class=loader[0] if loader else "none",
               loader_gensym=re.search(r"loading__(\d+)", loader[0]).group(1) if loader else "none",
               init_class=base + "__init", init_class_dotted=(base + "__init").replace("/", "."),
               gen_class=base if gp else "none",
               gen_class_has_main=_jv(bool(gp and any(m["name"] == "main" and m["descriptor"] == "([Ljava/lang/String;)V"
                                                      for m in gp["methods"]))),
               source_file=src, source_path=next((str(m["file"]) for m in meta.values() if "file" in m), "none"),
               var_lines=_jv({v: m["line"] for v, m in meta.items() if "line" in m}),
               var_columns=_jv({v: m["column"] for v, m in meta.items() if "column" in m}),
               var_arglists=_jv({v: _clj_form(m["arglists"]) for v, m in meta.items() if "arglists" in m}),
               var_values=_jv(vals), fn_invoke_static_arity=_jv({v: arity[v] for v in vars_ if v in arity}), variadic_fns=_jv(variadic),
               primary_class=prim, primary_class_dotted=prim.replace("/", "."),
               references_clojure_runtime=_jv(refs), clojure_class_major=str(p["major"]))
    return out


def clojure_field(data, field):
    """One clojure_facts field as an answer string ("none" absent, None not a jar). Never raises."""
    f = clojure_facts(data)
    return None if f is None else f.get(field, "none")


# --- Groovy compiled unit facts (D26 "primary classfile named by that unit": groovyc script/class, no groovy jar) ----
# javap -v -p markers: a script `X.groovy` -> X.class extends groovy/lang/Script (run() holds the body, main() calls
# InvokerHelper.runScript); a class -> implements groovy/lang/GroovyObject + $getStaticMetaClass. Closures compile to
# `X$_run_closure1` / `X$_main_closure2` / nested `X$_run_closure1$_closure4` extending groovy/lang/Closure (doCall),
# listed in X's InnerClasses table. Call-site names: Groovy 4 indy -> first static arg of each IndyInterface bootstrap
# method (table order); Groovy <= 3 -> the strings $createCallSiteArray_1 aastores into the CallSite[] (index order).
_GROOVY_KEYS = ("unit", "groovy_kind", "is_groovy_script", "primary_class", "primary_class_dotted", "primary_classfile",
                "primary_super_class", "source_file", "closures", "closure_count", "closure_names",
                "closure_do_call", "all_closures", "all_closure_count", "call_site_names", "call_site_count",
                "script_body_method", "hcfg_class", "hcfg_in_primary", "hcfg_cp_index", "hcfg_constant",
                "references_groovy_runtime", "has_groovy_runtime", "groovy_class_major", "groovy_indy")
_GROOVY_HCFG = (b"HCFG", b"SENGR", b"48434647", b"JBBUOR")


def _groovy_is(p):
    return (p["super"] == "groovy/lang/Script" or "groovy/lang/GroovyObject" in p["interfaces"]
            or any(m["name"] == "$getStaticMetaClass" for m in p["methods"]))


def _groovy_callsites(p):
    """Call-site method names of one groovyc class (see header), [] when none."""
    cp, u = p["cp"], p["_u"]
    bsm = dict(p["attributes"]).get("BootstrapMethods")
    out = []
    if bsm and len(bsm) >= 2:
        o = 2
        for _ in range(int.from_bytes(bsm[:2], "big")):
            ref, n = struct.unpack_from(">HH", bsm, o)
            args = struct.unpack_from(f">{n}H", bsm, o + 4) if n else ()
            o += 4 + 2 * n
            mh = cp[ref] if 0 < ref < len(cp) else None
            e = cp[mh[1][1]] if mh and mh[0] == 15 and 0 < mh[1][1] < len(cp) else None
            own = p["_cname"](e[1][0]) if e and isinstance(e[1], tuple) else None
            if own and "groovy" in own and args and cp[args[0]] and cp[args[0]][0] == 8:
                out.append(u(cp[args[0]][1]))
    if out:
        return out
    code = next((dict(m["attributes"]).get("Code") for m in p["methods"] if m["name"] == "$createCallSiteArray_1"),
                None)
    if not code or len(code) < 8:
        return []
    names, idx, s = {}, None, None
    for _, op, a in jvm_code_decode(code[8:8 + int.from_bytes(code[4:8], "big")]):
        if 0x02 <= op <= 0x08:
            idx = op - 0x03
        elif op in (0x10, 0x11):
            idx = a[0]
        elif op in (0x12, 0x13):
            e = cp[a[0]]
            s = u(e[1]) if e and e[0] == 8 else None
        elif op == 0x53 and idx is not None and s is not None:
            names[idx] = s
            idx = s = None
    return [names[i] for i in sorted(names)]


def groovy_facts(data, question=None):
    """{field: answer string} for a groovyc-built jar (or bare .class): the unit's primary class (named by the
    `X.groovy` unit in `question` -- class whose name / SourceFile stem is X, never a closure -- else Main-Class, else
    the first groovy class named after its SourceFile), groovy_kind script|class, closures (primary InnerClasses table
    order) + closure_names / closure_do_call {closure: [doCall descriptors]}, all_closures (every Closure subclass
    under the primary, closure-counter order), call_site_names, hcfg_class (class whose constant pool holds the HCFG
    String -- raw/base64/hex/base32 head), hcfg_cp_index (javap #N), references_groovy_runtime vs has_groovy_runtime
    (groovy jar bundled). "none" fields when no groovy class; None when not a jar/class. Never raises."""
    import zipfile
    b = bytes(data)
    try:
        if b[:4] == b"\xca\xfe\xba\xbe":
            p = classfile_parse(b)
            if not p:
                return None
            ents, names, mf = {(p["this"] or "x") + ".class": p}, [(p["this"] or "x") + ".class"], ""
        else:
            z = zipfile.ZipFile(io.BytesIO(b))
            names = z.namelist()
            mf = z.read("META-INF/MANIFEST.MF").decode("utf-8", "replace") if "META-INF/MANIFEST.MF" in names else ""
            ents = None
    except Exception:  # noqa: BLE001
        return None
    try:
        return _groovy_facts(z if ents is None else None, names, mf, ents, question)
    except Exception:  # noqa: BLE001
        return {k: "none" for k in _GROOVY_KEYS}


def _groovy_facts(z, names, mf, ents, question):
    out = {k: "none" for k in _GROOVY_KEYS}
    out["has_groovy_runtime"] = _jv(any(n.startswith("groovy/lang/") for n in names))
    if ents is None:
        ents, raw = {}, 0
        for n in names:
            if (n.endswith(".class") and not n.startswith(("META-INF/", "groovy/", "org/codehaus/groovy/"))
                    and not JVM_LIBRARY.search(n) and len(ents) < 512 and raw < (32 << 20)):
                c = z.read(n)
                raw += len(c)
                p = classfile_parse(c)
                if p:
                    ents[n] = p
    gro = [n for n, p in ents.items() if _groovy_is(p) and p["super"] != "groovy/lang/Closure"]
    clos = [n for n, p in ents.items() if p["super"] == "groovy/lang/Closure"]
    out["references_groovy_runtime"] = _jv(any(
        x.startswith(("groovy/lang/", "org/codehaus/groovy/")) for p in ents.values() for x in
        (p["_cname"](i) or "" for i, e in enumerate(p["cp"]) if e and e[0] == 7)))
    if not gro:
        return out

    def sf(p):
        a = dict(p["attributes"]).get("SourceFile")
        return (p["_u"](int.from_bytes(a[:2], "big")) or "none") if a and len(a) >= 2 else "none"

    unit = re.search(r"(?<![\w$/.-])([\w$/-]+)\.groovy\b", question or "")
    main = dict(re.findall(r"^([A-Za-z0-9_-]+):\s*(.*?)\s*$", re.sub(r"\r?\n ", "", mf), re.M)).get("Main-Class")
    prim = None
    if unit:
        u_ = unit.group(1)
        stem = u_.rsplit("/", 1)[-1]
        hit = [n for n in gro if n[:-6].rsplit("/", 1)[-1] == stem and ("/" not in u_ or n[:-6].endswith(u_))]
        hit = hit or [n for n in gro if sf(ents[n]) == stem + ".groovy" and "$" not in n.rsplit("/", 1)[-1]]
        prim = (hit or [None])[0]
        out["unit"] = stem + ".groovy"
    if prim is None and not unit and main and main.replace(".", "/") + ".class" in gro:
        prim = main.replace(".", "/") + ".class"
    if prim is None and not unit:
        prim = next((n for n in gro if sf(ents[n]) == n[:-6].rsplit("/", 1)[-1] + ".groovy"), gro[0])
    if prim is None:
        return out
    p = ents[prim]
    this = p["this"] or prim[:-6]
    script = p["super"] == "groovy/lang/Script"
    inner, ic = [], dict(p["attributes"]).get("InnerClasses")
    if ic and len(ic) >= 2:
        for j in range(int.from_bytes(ic[:2], "big")):
            ii, oi, ni, _ = struct.unpack_from(">HHHH", ic, 2 + 8 * j)
            c = p["_cname"](ii)
            q = ents.get(f"{c}.class")
            if c and c.startswith(this + "$") and (q["super"] == "groovy/lang/Closure" if q else
                                                   re.search(r"\$_\w*closure\d+$", c)):
                inner.append((c, p["_u"](ni) if ni else c.rsplit("$", 1)[-1]))
    allc = sorted((n[:-6] for n in clos if n.startswith(this + "$")),   # groovyc's closure counter = compile order
                  key=lambda c: int(re.search(r"(\d*)$", c).group(1) or 0))
    calls = _groovy_callsites(p)
    hc = None
    for n in [prim] + [x for x in ents if x != prim]:
        q = ents[n]
        k = next((i for i, e in enumerate(q["cp"]) if e and e[0] == 8 and
                  (q["_u"](e[1]) or "").encode()[:8].startswith(_GROOVY_HCFG)), None)
        if k is not None:
            hc = (q["this"] or n[:-6], k, q["_u"](q["cp"][k][1]))
            break
    out.update(groovy_kind="script" if script else "class", is_groovy_script=_jv(script), primary_class=this,
               primary_class_dotted=this.replace("/", "."), primary_classfile=prim, primary_super_class=p["super"]
               or "none", source_file=sf(p), closures=_jv([c for c, _ in inner]), closure_count=str(len(inner)),
               closure_names=_jv([s for _, s in inner]),
               closure_do_call=_jv({c: [m["descriptor"] for m in ents[c + ".class"]["methods"] if m["name"] == "doCall"]
                                    for c in allc}),
               all_closures=_jv(allc), all_closure_count=str(len(allc)), call_site_names=_jv(calls),
               call_site_count=str(len(calls)), script_body_method="run" if script else "none",
               groovy_class_major=str(p["major"]),
               groovy_indy=_jv(bool(calls) and "$createCallSiteArray_1" not in {m["name"] for m in p["methods"]}))
    if unit is None and out["unit"] == "none" and out["source_file"] != "none":
        out["unit"] = out["source_file"]
    if hc:
        out.update(hcfg_class=hc[0], hcfg_in_primary=_jv(hc[0] == this), hcfg_cp_index=str(hc[1]), hcfg_constant=hc[2])
    else:
        out["hcfg_in_primary"] = "false"
    return out


def groovy_field(data, field, question=None):
    """One groovy_facts field as an answer string ("none" absent, None not a jar/class). Never raises."""
    f = groovy_facts(data, question)
    return None if f is None else f.get(field, "none")


# --- Niche JVM languages (D22-D26 "new language on an old runtime": F#, VB.NET, Scala, Clojure, Groovy -> next?) ----
# Identity cues (javap -v of each compiler's output; runtime jars usually NOT bundled, as the GM's Scala/Clojure jars):
#   kotlin_script  super kotlin/script/templates/standard/ScriptTemplate* or org/jetbrains/kotlin/mainKts/MainKtsScript
#                  (foo.main.kts -> class Foo_main, SourceFile foo.main.kts)
#   jython         foo.py -> foo$py.class extends org/python/core/PyFunctionTable implements PyRunnable; code objects
#                  are methods name$N (f$0 = module body); literals via PyString.fromInterned(ldc "...")
#   jruby          jrubyc AOT: org/jruby/ refs (AbstractScript super), methods RUBY$script / RUBY$method$<name>$N
#   ceylon         com/redhat/ceylon (1.x) or org/eclipse/ceylon (1.3.3+) refs; module descriptor class <pkg>/$module_
#   eta / frege    eta/runtime/ refs; frege/runtime/ or frege/run{7,8}/ refs (@frege.runtime.Meta$FregePackage)
#   beanshell      bsh/ refs (generated classes implement bsh/GeneratedClass)
#   xtend          plain Java + org/eclipse/xtext/xbase/lib/ (InputOutput, Conversions, @Pure) or org/eclipse/xtend/lib/
# HCFG: constant-pool base64 >= 80 chars (classfile_hcfg) in WHICHEVER class holds it: primary first, then every class.
_NICHE_UNIT = re.compile(r"(?<![\w$/.-])([\w$/-]+(?:\.main)?\.(?:rb|py|ceylon|fr|eta|hs|xtend|bsh|java\.bsh|kts))\b")
_NICHE_RT = re.compile(r"^(org/jruby/|org/python/|com/redhat/ceylon/|org/eclipse/ceylon/|ceylon/language/|frege/run|"
                       r"eta/runtime/|org/eclipse/xtext/|org/eclipse/xtend2?/|bsh/|kotlin/script/|org/jetbrains/)")
_NICHE_LANGS = (   # (language, class-ref prefixes, runtime entry prefixes, unit extensions)
    ("kotlin_script", ("kotlin/script/templates/", "kotlin/script/experimental/", "org/jetbrains/kotlin/mainKts/",
                       "org/jetbrains/kotlin/script/"), ("kotlin/script/",), ("kts",)),
    ("jython", ("org/python/core/", "org/python/compiler/"), ("org/python/",), ("py",)),
    ("jruby", ("org/jruby/",), ("org/jruby/",), ("rb",)),
    ("ceylon", ("com/redhat/ceylon/", "org/eclipse/ceylon/", "ceylon/language/"),
     ("com/redhat/ceylon/", "org/eclipse/ceylon/", "ceylon/language/"), ("ceylon",)),
    ("eta", ("eta/runtime/",), ("eta/runtime/",), ("eta", "hs")),
    ("frege", ("frege/runtime/", "frege/run7/", "frege/run8/", "frege/run/"), ("frege/run",), ("fr",)),
    ("beanshell", ("bsh/",), ("bsh/",), ("bsh",)),
    ("xtend", ("org/eclipse/xtext/xbase/lib/", "org/eclipse/xtend/lib/", "org/eclipse/xtend2/lib/"),
     ("org/eclipse/xtext/", "org/eclipse/xtend"), ("xtend",)),
)
_NICHE_CUES = (b"org/jruby/", b"RUBY$", b"org/python/", b"ceylon/", b"eta/runtime/", b"frege/run", b"bsh/",
               b"org/eclipse/xt", b"kotlin/script/", b"org/jetbrains/kotlin/")
_NICHE_KEYS = ("niche_language", "niche_classes", "niche_class_count", "niche_primary_classfile", "niche_primary_class",
               "niche_primary_class_dotted", "niche_primary_super_class", "niche_source_file", "niche_unit",
               "niche_hcfg_classfile", "niche_hcfg_in_primary", "references_niche_runtime", "has_niche_runtime",
               "jython_module", "jython_code_objects", "jruby_methods", "jruby_script_method", "ceylon_module_class",
               "ceylon_module", "kotlin_script_class", "kotlin_script_base")


def _niche_lang_of(p):
    """Niche JVM language of one parsed class (None when none): super/interfaces/class refs/descriptors/annotations."""
    refs = {p["super"] or ""} | set(p["interfaces"])
    lits = {e[1] for e in p["cp"] if e and e[0] == 8}   # String literals are data, not references
    for i, e in enumerate(p["cp"]):
        if e and e[0] == 1 and i not in lits and isinstance(e[1], str) and "/" in e[1] and len(e[1]) < 512:
            refs.add(e[1])
    if p["super"] and p["super"].startswith("kotlin/script/") or \
            any(r.startswith(("org/jetbrains/kotlin/mainKts/", "kotlin/script/templates/")) for r in refs):
        return "kotlin_script"
    if any(m["name"] and m["name"].startswith("RUBY$") for m in p["methods"]):
        return "jruby"
    for lang, pre, _, _ in _NICHE_LANGS[1:]:
        lpre = tuple("L" + x for x in pre)
        if any(r.startswith(pre) or any(lp in r for lp in lpre) for r in refs):
            return lang
    return None


def jvm_niche_facts(data, question=None):
    """{field: answer string} for a jar / bare .class built by a niche JVM language (header cues): niche_language
    (kotlin_script|jython|jruby|ceylon|eta|frege|beanshell|xtend|none), niche_classes (cue-bearing app classfiles),
    niche_primary_classfile (the class the `X.py`/`X.rb`/`X.main.kts`/... unit in `question` names -- SourceFile or
    compiler naming foo$py / Foo_main --, else Main-Class, else the language root: $py module, RUBY$script class),
    niche_hcfg_classfile (class whose constant pool holds the base64 HCFG: primary first, then every class) +
    jython_module/jython_code_objects, jruby_methods, ceylon_module_class, kotlin_script_class. "none" fields when no
    cue; None when not a jar/class. Never raises."""
    import zipfile
    b = bytes(data)
    try:
        if b[:4] == b"\xca\xfe\xba\xbe":
            p = classfile_parse(b)
            if not p:
                return None
            ents, names, mf = {(p["this"] or "x") + ".class": (p, b)}, [(p["this"] or "x") + ".class"], ""
        else:
            z = zipfile.ZipFile(io.BytesIO(b))
            names = z.namelist()
            mf = z.read("META-INF/MANIFEST.MF").decode("utf-8", "replace") if "META-INF/MANIFEST.MF" in names else ""
            ents, raw = {}, 0
            for n in names:
                if (n.endswith(".class") and not n.startswith("META-INF/") and not _NICHE_RT.match(n)
                        and not JVM_LIBRARY.search(n) and len(ents) < 512 and raw < (32 << 20)):
                    c = z.read(n)
                    raw += len(c)
                    ents[n] = (classfile_parse(c) if any(k in c for k in _NICHE_CUES) else None, c)
    except Exception:  # noqa: BLE001
        return None
    try:
        return _niche_facts(names, mf, ents, question)
    except Exception:  # noqa: BLE001
        return {k: "none" for k in _NICHE_KEYS}


def _niche_facts(names, mf, ents, question):
    out = {k: "none" for k in _NICHE_KEYS}
    langs = {n: _niche_lang_of(p) if p else None for n, (p, _) in ents.items()}
    hit = [n for n, lg in langs.items() if lg]
    bundled = [lg for lg, _, rt, _ in _NICHE_LANGS if any(n.startswith(rt) for n in names)]
    out.update(references_niche_runtime=_jv(bool(hit)), has_niche_runtime=_jv(bool(bundled)))
    if not hit:
        return out
    count = {}
    for n in hit:
        count[langs[n]] = count.get(langs[n], 0) + 1
    lang = max(count, key=lambda k: (count[k], -[x[0] for x in _NICHE_LANGS].index(k)))
    mine = [n for n in hit if langs[n] == lang]

    def sf(p):
        a = dict(p["attributes"]).get("SourceFile")
        return (p["_u"](int.from_bytes(a[:2], "big")) or "none") if a and len(a) >= 2 else "none"

    def base(n):
        return n[:-6].rsplit("/", 1)[-1]

    unit = _NICHE_UNIT.search(question or "")
    main = dict(re.findall(r"^([A-Za-z0-9_-]+):\s*(.*?)\s*$", re.sub(r"\r?\n ", "", mf), re.M)).get("Main-Class")
    prim = None
    if unit:
        fn = unit.group(1).rsplit("/", 1)[-1]
        stem = fn.rsplit(".", 1)[0]
        want = {stem.replace(".", "_") + "$py", stem, stem + "_", (stem[:1].upper() + stem[1:]).replace(".", "_"),
                stem.replace(".", "_")}
        srcs = [n for n in mine if sf(ents[n][0]) == fn]
        prim = next((n for n in srcs if base(n) in want), None) or \
            next((n for n in srcs if "$" not in base(n) or base(n).endswith("$py")), None) or \
            next((n for n in mine if base(n) in want), None) or (srcs or [None])[0]
        out["niche_unit"] = fn
    if prim is None and not unit:
        m_ent = main.replace(".", "/") + ".class" if main else None
        root = {"jython": lambda n: base(n).endswith("$py"),
                "jruby": lambda n: ents[n][0]["super"] == "org/jruby/ast/executable/AbstractScript" or
                any(m["name"] == "RUBY$script" for m in ents[n][0]["methods"]),
                "ceylon": lambda n: base(n) != "$module_" and "$" not in base(n)}.get(lang, lambda n: "$" not in base(n))
        prim = m_ent if m_ent in mine else next((n for n in mine if root(n)), mine[0])
    out.update(niche_language=lang, niche_classes=_jv(mine), niche_class_count=str(len(mine)))
    order = ([prim] if prim else []) + [n for n in mine if n != prim] + [n for n in ents if n not in mine]
    for n in order:
        if classfile_hcfg(ents[n][1]).get("hcfg_found") == "true":
            out.update(niche_hcfg_classfile=n, niche_hcfg_in_primary=_jv(n == prim))
            break
    mod = next((n for n in mine if base(n) == "$module_"), None)
    if mod:
        out.update(ceylon_module_class=mod, ceylon_module=mod[:-len("/$module_.class")].replace("/", ".")
                   if "/" in mod else "default")
    if not prim:
        return out
    p = ents[prim][0]
    this = p["this"] or prim[:-6]
    out.update(niche_primary_classfile=prim, niche_primary_class=this, niche_primary_class_dotted=this.replace("/", "."),
               niche_primary_super_class=p["super"] or "none", niche_source_file=sf(p))
    if out["niche_unit"] == "none" and out["niche_source_file"] != "none":
        out["niche_unit"] = out["niche_source_file"]
    ms = [m["name"] or "" for m in p["methods"]]
    if lang == "jython":
        code = sorted(((int(m.group(2)), m.group(1)) for m in map(re.compile(r"^(.+)\$(\d+)$").match, ms) if m))
        out.update(jython_module=this.rsplit("/", 1)[-1][:-3] if this.endswith("$py") else "none",
                   jython_code_objects=_jv([f"{s}${i}" for i, s in code]))
    elif lang == "jruby":
        rm = [m.group(1) for m in map(re.compile(r"^RUBY\$method\$(.+?)\$\d+$").match, ms) if m]
        out.update(jruby_methods=_jv(list(dict.fromkeys(rm))),
                   jruby_script_method="RUBY$script" if "RUBY$script" in ms else "none")
    elif lang == "kotlin_script":
        out.update(kotlin_script_class=this, kotlin_script_base=p["super"] or "none")
    return out


def jvm_niche_field(data, field, question=None):
    """One jvm_niche_facts field as an answer string ("none" absent, None not a jar/class). Never raises."""
    f = jvm_niche_facts(data, question)
    return None if f is None else f.get(field, "none")


# --- JVM twin-jar patch diff (D24 "spot the difference": vulnerable vs corrected Scala jar) --------------------------
# Classes are matched after stripping the role token (Day24Vulnerable000$ ~ Day24Corrected000$, derived from the
# names themselves), methods by name + descriptor; Code is compared with constant-pool operands RESOLVED to symbols
# (raw #indexes shift between builds), branch targets as instruction indexes, ldc_w folded into ldc; LineNumberTable /
# StackMapTable / LocalVariableTable ignored. Lambdas compare by their implementation method (LambdaMetafactory
# handle); LambdaDeserialize's handle list (grows with every new lambda) is ignored, so $deserializeLambda$ only
# changes when its code does. Answer spellings follow javap: `score`, `(Ljava/lang/String;)I`, `scala/Option$.apply`.
_JOPS = ("nop aconst_null iconst_m1 iconst_0 iconst_1 iconst_2 iconst_3 iconst_4 iconst_5 lconst_0 lconst_1 fconst_0 "
         "fconst_1 fconst_2 dconst_0 dconst_1 bipush sipush ldc ldc_w ldc2_w iload lload fload dload aload " +
         " ".join(f"{t}load_{n}" for t in "ilfda" for n in range(4)) +
         " iaload laload faload daload aaload baload caload saload istore lstore fstore dstore astore " +
         " ".join(f"{t}store_{n}" for t in "ilfda" for n in range(4)) +
         " iastore lastore fastore dastore aastore bastore castore sastore pop pop2 dup dup_x1 dup_x2 dup2 dup2_x1 "
         "dup2_x2 swap iadd ladd fadd dadd isub lsub fsub dsub imul lmul fmul dmul idiv ldiv fdiv ddiv irem lrem frem "
         "drem ineg lneg fneg dneg ishl lshl ishr lshr iushr lushr iand land ior lor ixor lxor iinc i2l i2f i2d l2i "
         "l2f l2d f2i f2l f2d d2i d2l d2f i2b i2c i2s lcmp fcmpl fcmpg dcmpl dcmpg ifeq ifne iflt ifge ifgt ifle "
         "if_icmpeq if_icmpne if_icmplt if_icmpge if_icmpgt if_icmple if_acmpeq if_acmpne goto jsr ret tableswitch "
         "lookupswitch ireturn lreturn freturn dreturn areturn return getstatic putstatic getfield putfield "
         "invokevirtual invokespecial invokestatic invokeinterface invokedynamic new newarray anewarray arraylength "
         "athrow checkcast instanceof monitorenter monitorexit wide multianewarray ifnull ifnonnull goto_w "
         "jsr_w").split()
assert len(_JOPS) == 0xca
_JLEN = {**{o: 2 for o in (0x10, 0x12, 0xa9, 0xbc, *range(0x15, 0x1a), *range(0x36, 0x3b))},
         **{o: 3 for o in (0x11, 0x13, 0x14, 0x84, *range(0x99, 0xa9), *range(0xb2, 0xb9), 0xbb, 0xbd, 0xc0, 0xc1,
                           0xc6, 0xc7)},
         0xb9: 5, 0xba: 5, 0xc5: 4, 0xc8: 5, 0xc9: 5}
_JBRANCH = set(range(0x99, 0xa9)) | {0xc6, 0xc7, 0xc8, 0xc9}
_JROLE_HINT = re.compile(r"(?i)vuln|correct|patch|fix|secur|safe|orig|bug|broken|before|after|old|new|good|bad")


def jvm_code_decode(code):
    """JVM bytecode -> [(pc, opcode, operands tuple)] (JVMS 6.5; tableswitch/lookupswitch/wide decoded). Raises
    ValueError on an unknown opcode or a truncated stream."""
    out, pc, n = [], 0, len(code)
    while pc < n:
        op = code[pc]
        if op >= 0xca:
            raise ValueError(f"opcode {op:#x}")
        if op in (0xaa, 0xab):
            q = (pc + 4) & ~3
            default, = struct.unpack_from(">i", code, q)
            if op == 0xaa:
                lo, hi = struct.unpack_from(">ii", code, q + 4)
                if not 0 <= hi - lo < 1 << 16:
                    raise ValueError("tableswitch")
                offs = struct.unpack_from(f">{hi - lo + 1}i", code, q + 12)
                arg, nxt = (default, tuple((lo + k, d) for k, d in enumerate(offs))), q + 12 + 4 * (hi - lo + 1)
            else:
                np_, = struct.unpack_from(">i", code, q + 4)
                if not 0 <= np_ < 1 << 16:
                    raise ValueError("lookupswitch")
                kv = struct.unpack_from(f">{2 * np_}i", code, q + 8)
                arg, nxt = (default, tuple(zip(kv[::2], kv[1::2]))), q + 8 + 8 * np_
            out.append((pc, op, arg))
            pc = nxt
            continue
        if op == 0xc4:   # wide <op> u2 [s2 for iinc]
            sub = code[pc + 1]
            ln = 6 if sub == 0x84 else 4
            raw = code[pc + 2:pc + ln]
            if len(raw) != ln - 2:
                raise ValueError("truncated")
            out.append((pc, sub, struct.unpack(">Hh" if sub == 0x84 else ">H", raw)))
            pc += ln
            continue
        ln = _JLEN.get(op, 1)
        raw = code[pc + 1:pc + ln]
        if len(raw) != ln - 1:
            raise ValueError("truncated")
        if op in _JBRANCH:
            arg = struct.unpack(">i" if ln == 5 else ">h", raw)
        elif op in (0x10,):
            arg = struct.unpack(">b", raw)
        elif op in (0x11,):
            arg = struct.unpack(">h", raw)
        elif op == 0x84:
            arg = (raw[0], struct.unpack(">b", raw[1:])[0])
        elif op in (0xb9, 0xba, 0xc5):
            arg = (struct.unpack(">H", raw[:2])[0], *raw[2:])
        elif ln == 3:
            arg = struct.unpack(">H", raw)
        else:
            arg = tuple(raw)
        out.append((pc, op, arg))
        pc += ln
    return out


def _jpd_cpl(a, b):
    n = 0
    while n < len(a) and n < len(b) and a[n] == b[n]:
        n += 1
    return n


def _jpd_role(names_a, names_b):
    """(token a, token b) that turns A's class names into B's (Day24Vulnerable000$ / Day24Corrected000$ ->
    ('Vulnerable', 'Corrected')), or ('', '') when the names already match."""
    oa, ob = sorted(set(names_a) - set(names_b))[:200], sorted(set(names_b) - set(names_a))[:200]
    votes = {}
    for a in oa:
        for b in ob:
            p = _jpd_cpl(a, b)
            s = _jpd_cpl(a[p:][::-1], b[p:][::-1])
            ta, tb = a[p:len(a) - s], b[p:len(b) - s]
            while p and (ta[:1].islower() or tb[:1].islower()) and a[p - 1].isalpha():   # widen to whole
                p -= 1                                                                    # CamelCase words
                ta, tb = a[p] + ta, b[p] + tb
            while s and a[len(a) - s].islower():   # Unp/P -> Unpatched/Patched
                ta, tb, s = ta + a[len(a) - s], tb + b[len(b) - s], s - 1
            if ta and tb and "/" not in ta + tb:
                k = (ta, tb)
                votes[k] = votes.get(k, 0) + 1 + 2 * bool(_JROLE_HINT.search(ta + tb))
    if not votes:
        return "", ""
    return max(votes, key=lambda k: (votes[k], len(k[0]) + len(k[1])))


# Compiler gensym digits inside class names: Clojure fn__269 / loading__6812__auto____267, Groovy _closure1, Kotlin
# $lambda$0 / $lambda-1, Scala $anonfun$score$1 and javac $1 anonymous classes. Twins agree on them only by accident.
_JGS = re.compile(r"(?:(?<=__)|(?<=_closure)|(?<=\$lambda[$-])|(?<=\$))(\d+)(?=$|[$_])")


def _jpd_gensyms(names):
    """{raw class name: positional canonical name} for every gensym-bearing class name of one side (the k-th
    `fn__N` of a stem by numeric order -> `fn__#~k`), plus the compiled matcher; (None, {}) when there are none."""
    groups = {}
    for n in names:
        nums = _JGS.findall(n)
        if nums:
            groups.setdefault(_JGS.sub("#", n), []).append((tuple(map(int, nums)), n))
    gm = {n: f"{stem}~{k}" for stem, xs in groups.items() for k, (_, n) in enumerate(sorted(xs))}
    gm.update({"L" + n: "L" + v for n, v in list(gm.items())})   # descriptor spelling Lpkg/Cls$fn__1;
    return (_JGS_WORD, gm) if gm else (None, {})


_JGS_WORD = re.compile(r"[\w/$]+")


def _jpd_demunge(s):
    """Clojure Compiler.demunge for a fn class's Var segment (parse_frame -> parse-frame, valid_QMARK_ -> valid?)."""
    for a, b in (("_QMARK_", "?"), ("_BANG_", "!"), ("_STAR_", "*"), ("_GT_", ">"), ("_LT_", "<"), ("_EQ_", "="),
                 ("_PLUS_", "+"), ("_SLASH_", "/"), ("_COLON_", ":"), ("_SINGLEQUOTE_", "'"), ("_PERCENT_", "%"),
                 ("_AMPERSAND_", "&"), ("_CARET_", "^"), ("_BAR_", "|"), ("_SHARP_", "#"), ("_DOT_", "."),
                 ("_", "-")):
        s = s.replace(a, b)
    return s


def _jpd_class(cb, role, gs=(None, {})):
    """One .class -> {"name", "size", "methods": [(name, descriptor, access, code facts | None)]}; None if unparsable.
    `gs` = _jpd_gensyms of the class's own jar: gensym class names in the comparison tokens become positional."""
    p = classfile_parse(cb)
    if not p:
        return None
    cp, u, cname = p["cp"], p["_u"], p["_cname"]
    tok = role
    grx, gmap = gs

    def nm(s, g=False):
        if g and grx and s:
            s = grx.sub(lambda m: gmap.get(m.group(0), m.group(0)), s)
        if not tok or s is None:
            return s
        return s.replace(tok, "\0R").replace(tok.lower(), "\0r")

    def ref(i):   # Field/Method/InterfaceMethodref -> (class, name, desc)
        e = cp[i] if 0 < i < len(cp) else None
        if not e or e[0] not in (9, 10, 11):
            return None, None, None
        nt = cp[e[1][1]]
        return cname(e[1][0]), u(nt[1][0]), u(nt[1][1])

    def mh(i):   # MethodHandle -> class.name:desc
        e = cp[i] if 0 < i < len(cp) else None
        if not e or e[0] != 15:
            return None
        c, n, d = ref(e[1][1])
        return f"{c}.{n}:{d}"

    def const(i):
        e = cp[i] if 0 < i < len(cp) else None
        if not e:
            return "?"
        t, v = e
        return (repr(u(v)) if t == 8 else cname(i) if t == 7 else u(v) if t == 16 else repr(v) if t in (3, 4, 5, 6)
                else mh(i) if t == 15 else f"cp{t}")

    bsms = []
    braw = dict(p["attributes"]).get("BootstrapMethods")
    if braw and len(braw) >= 2:
        o = 2
        for _ in range(struct.unpack_from(">H", braw, 0)[0]):
            bm, na = struct.unpack_from(">HH", braw, o)
            args = struct.unpack_from(f">{na}H", braw, o + 4)
            o += 4 + 2 * na
            bsms.append((mh(bm), args))

    def indy(i):
        e = cp[i] if 0 < i < len(cp) else None
        if not e or e[0] != 18:
            return "?", None
        bi, nti = e[1]
        nt = cp[nti][1]
        bm, args = bsms[bi] if bi < len(bsms) else ("?", ())
        lam = "LambdaMetafactory" in (bm or "")
        impl = next((mh(a) for a in args if cp[a] and cp[a][0] == 15), None) if lam else None
        keep = [const(a) for a in args if cp[a] and cp[a][0] != 15]
        return f"{u(nt[0])}:{u(nt[1])} bsm={bm} impl={impl} args={keep}", impl

    methods = []
    for m in p["methods"]:
        raw = next((b for n, b in m["attributes"] if n == "Code"), None)
        cf = None
        if raw and len(raw) >= 8:
            ln = struct.unpack_from(">I", raw, 4)[0]
            code = raw[8:8 + ln]
            ins = jvm_code_decode(code)
            idx = {pc: k for k, (pc, _, _) in enumerate(ins)}
            toks, invokes, lambdas, ops, consts = [], [], [], [], []
            for pc, op, arg in ins:
                mn = _JOPS[op]
                ops.append(mn)
                if 0x02 <= op <= 0x11:   # iconst_m1..dconst_1, bipush, sipush
                    consts.append(str(arg[0] if op >= 0x10 else op - 3 if op <= 8 else op - 9 if op <= 0x0a
                                      else float(op - 0x0b) if op <= 0x0d else float(op - 0x0e)))
                elif op in (0x12, 0x13, 0x14) and cp[arg[0]] and cp[arg[0]][0] in (3, 4, 5, 6):
                    consts.append(repr(cp[arg[0]][1]))
                if op in _JBRANCH:
                    t = f"{mn} @{idx.get(pc + arg[0], '?')}"
                elif op in (0xaa, 0xab):
                    t = f"{mn} {idx.get(pc + arg[0], '?')} " + ",".join(f"{k}:{idx.get(pc + d, '?')}" for k, d in arg[1])
                elif op in (0x12, 0x13, 0x14):
                    t = f"{'ldc2_w' if op == 0x14 else 'ldc'} {const(arg[0])}"
                elif 0xb2 <= op <= 0xb9:
                    c, n, d = ref(arg[0])
                    t = f"{mn} {c}.{n}:{d}"
                    if op >= 0xb6:
                        invokes.append((f"{c}.{n}", f"{c}.{n}:{d}"))
                elif op == 0xba:
                    s, impl = indy(arg[0])
                    t = f"{mn} {s}"
                    if impl:
                        lambdas.append(impl)
                elif op in (0xbb, 0xbd, 0xc0, 0xc1, 0xc5):
                    t = f"{mn} {cname(arg[0])} {arg[1:]}"
                else:
                    t = f"{mn} {arg}" if arg else mn
                head, sp, rest = t.partition(" ")   # mnemonic kept: a role token "new" must not eat `new`
                toks.append(head + sp + nm(rest, True))
            et, o = [], 8 + ln
            ne = struct.unpack_from(">H", raw, o)[0] if o + 2 <= len(raw) else 0
            for k in range(ne):
                s, e_, h, ct = struct.unpack_from(">HHHH", raw, o + 2 + 8 * k)
                et.append((idx.get(s), idx.get(e_, len(ins)), idx.get(h), nm(cname(ct)) if ct else "any"))
            cf = {"tokens": tuple(toks), "exc": tuple(et), "code_length": ln, "insns": len(ins), "ops": ops,
                  "consts": consts,
                  "invokes": [(nm(a), nm(b)) for a, b in invokes], "lambdas": [nm(x) for x in lambdas],
                  "max_stack": struct.unpack_from(">H", raw, 0)[0], "max_locals": struct.unpack_from(">H", raw, 2)[0]}
        methods.append((m["name"], m["descriptor"], m["access"], cf))
    return {"name": p["this"], "norm": nm(p["this"], True), "size": len(cb), "methods": methods, "nm": nm,
            "super": p["super"] or ""}


def _jpd_classes(blob):
    b = bytes(blob)
    if b[:4] == b"\xca\xfe\xba\xbe":   # a bare .class: its this_class names it (role token derivation)
        p = classfile_parse(b)
        return [((p and p["this"] or "class") + ".class", b)]
    return [(n, c) for n, c in jar_app_classes(b) if c[:4] == b"\xca\xfe\xba\xbe"]


def _jpd_jvm_lang_facts(changed, role):
    """Clojure per-Var view of the changed classes: `ns$var` / `ns$var$fn__N` AFunction/RestFn classes -> demunged
    Var names (changed_vars), plus the changed method list across every changed class (role token stripped)."""
    out, cl, allm = {}, False, []
    for A, _, ch in changed:
        cn = A["name"]
        nr = cn.replace(role, "").replace(role.lower(), "") if role else cn
        allm += [f"{nr.replace('/', '.')}.{n}{d}" for n, d, _, _ in ch]
        if A["super"].startswith("clojure/lang/") and "$" in cn:
            seg = cn.split("$")[1]
            if seg and not _JGS.search("$" + seg) and not seg.startswith(("loading__", "fn__")):
                cl = True
                v = _jpd_demunge(seg)
                if v not in out:
                    out[v] = None
    f = {"changed_methods_all": _jv(_jpd_uniq(allm)), "changed_methods_all_count": str(len(_jpd_uniq(allm)))}
    if cl:
        f.update({"changed_vars": _jv(list(out)), "changed_var": next(iter(out)), "changed_var_count": str(len(out))})
    return f


def _jpd_uniq(xs):
    return list(dict.fromkeys(xs))


def _jpd_fix_kind(ma, mb):
    """Classify the fix from the before/after code facts (vocabulary SPECULATIVE until a GM label is seen)."""
    ta, tb = ma or {"ops": [], "invokes": [], "exc": (), "tokens": ()}, mb or {"ops": [], "invokes": [], "exc": (),
                                                                               "tokens": ()}
    inv_a, inv_b = {x for x, _ in ta["invokes"]}, {x for x, _ in tb["invokes"]}
    add_inv = inv_b - inv_a
    add_ops = {o: tb["ops"].count(o) - ta["ops"].count(o) for o in set(tb["ops"])}
    grew = lambda *os_: any(add_ops.get(o, 0) > 0 for o in os_)   # noqa: E731
    if len(tb["exc"]) > len(ta["exc"]):
        return "exception_handler"
    if grew("ifnull", "ifnonnull") or any(re.search(r"(Option\$\.apply|Optional\.ofNullable|requireNonNull|"
                                                    r"Objects\.(isNull|nonNull)|checkNotNull)$", x) for x in add_inv):
        return "null_guard"
    if grew("arraylength") or any(re.search(r"(checkIndex|checkFromToIndex|isDefinedAt|lift|indices|RT\.count)$", x)
                                  for x in add_inv):
        return "bounds_check"
    if any(re.search(r"\.(length|isEmpty|nonEmpty|size|isBlank)(\$extension)?$", x) for x in add_inv) \
            or grew("if_icmplt", "if_icmpge", "if_icmpgt", "if_icmple"):
        return "length_check"
    if ta["ops"] == tb["ops"] and ta["tokens"] != tb["tokens"]:
        return "constant_change"
    return "logic_change"


def jvm_patch_diff(jar_a, jar_b):
    """Per-class / per-method bytecode diff of twin JVM builds (A = before/vulnerable, B = after/corrected; jar or
    bare .class bytes) -> {field: answer string}; None when either side holds no parsable class. Fields:
    changed_methods / changed_method_names / changed_method(_descriptor/_signature) / changed_method_count,
    changed_class(_a/_b/es), unchanged_methods(_names), added_/removed_methods, method_count_{a,b}, code_length_ /
    instruction_count_ / max_stack_ / max_locals_ / exception_table_count_ / classfile_size_{a,b}, added_/
    removed_invokes (+_signatures), added_/removed_lambdas (+_raw), added_/removed_opcodes, fix_kind, role_a/_b.
    _before/_after and _vulnerable/_corrected alias every _a/_b field."""
    try:
        return _jvm_patch_diff(jar_a, jar_b)
    except Exception:   # noqa: BLE001 -- malformed / decoy input: no answer
        return None


def _jvm_patch_diff(jar_a, jar_b):
    ca, cb = _jpd_classes(jar_a), _jpd_classes(jar_b)
    if not ca or not cb:
        return None

    def names(cl):
        return [n[:-6] if n.endswith(".class") else n for n, _ in cl]
    ra, rb = _jpd_role([_JGS.sub("#", n) for n in names(ca)], [_JGS.sub("#", n) for n in names(cb)])
    ga, gb = _jpd_gensyms(names(ca)), _jpd_gensyms(names(cb))
    pa = [x for x in (_jpd_class(c, ra, ga) for _, c in ca) if x]
    pb = [x for x in (_jpd_class(c, rb, gb) for _, c in cb) if x]
    if not pa or not pb:
        return None
    bmap = {x["norm"]: x for x in pb}
    if len(pa) == len(pb) == 1:
        bmap = {pa[0]["norm"]: pb[0]}
    rows, changed_classes, all_changed = [], [], []
    for A in pa:
        B = bmap.get(A["norm"])
        if not B:
            continue
        mb = {(n, B["nm"](d)): (acc, cf) for n, d, acc, cf in B["methods"]}
        ma = {(n, A["nm"](d)): (acc, cf) for n, d, acc, cf in A["methods"]}
        ch, same = [], []
        for n, d, acc, cf in A["methods"]:
            k = (n, A["nm"](d))
            if k not in mb:
                continue
            acc2, cf2 = mb[k]
            sig = lambda c: c and (c["tokens"], c["exc"])   # noqa: E731
            (ch if acc != acc2 or sig(cf) != sig(cf2) else same).append((n, d, cf, cf2))
        added = [(n, d) for n, d, _, _ in B["methods"] if (n, B["nm"](d)) not in ma]
        removed = [(n, d) for n, d, _, _ in A["methods"] if (n, A["nm"](d)) not in mb]
        if ch or added or removed:
            changed_classes.append(A["name"])
            all_changed.append((A, B, ch))
        rows.append((A, B, ch, same, added, removed))
    if not rows:
        return None
    jf = _jpd_jvm_lang_facts(all_changed, ra)
    rows.sort(key=lambda r: (not r[2], not (r[4] or r[5])))
    A, B, ch, same, added, removed = rows[0]
    f = {"role_a": ra or "none", "role_b": rb or "none", "classes_compared": str(len(rows)),
         "changed_classes": _jv(changed_classes), "changed_class_count": str(len(changed_classes))}
    if not changed_classes:
        f.update({"changed_methods": "[]", "changed_method_names": "[]", "changed_method_count": "0",
                  "fix_kind": "none", "changed_class": "none"})
        f.update(jf)
        return f
    sig = lambda n, d: f"{n}{d}"   # noqa: E731
    first = ch[0] if ch else None
    f.update({
        "changed_class": A["name"], "changed_class_a": A["name"], "changed_class_b": B["name"],
        "changed_class_dotted": A["name"].replace("/", "."),
        "changed_methods": _jv([sig(n, d) for n, d, _, _ in ch]),
        "changed_method_names": _jv([n for n, _, _, _ in ch]), "changed_method_count": str(len(ch)),
        "changed_method": first[0] if first else "none",
        "changed_method_descriptor": first[1] if first else "none",
        "changed_method_signature": sig(first[0], first[1]) if first else "none",
        "unchanged_methods": _jv([sig(n, d) for n, d, _, _ in same]),
        "unchanged_method_names": _jv([n for n, _, _, _ in same]), "unchanged_method_count": str(len(same)),
        "added_methods": _jv([sig(n, d) for n, d in added]), "added_method_names": _jv([n for n, _ in added]),
        "removed_methods": _jv([sig(n, d) for n, d in removed]), "removed_method_names": _jv([n for n, _ in removed]),
        "added_method_count": str(len(added)), "removed_method_count": str(len(removed)),
        "method_count_a": str(len(A["methods"])), "method_count_b": str(len(B["methods"])),
        "classfile_size_a": str(A["size"]), "classfile_size_b": str(B["size"]),
        "jar_size_a": str(len(jar_a)), "jar_size_b": str(len(jar_b)),
    })
    xa, xb = (first[2], first[3]) if first else (None, None)
    for side, c in (("a", xa), ("b", xb)):
        for k, v in (("code_length", "code_length"), ("instruction_count", "insns"), ("max_stack", "max_stack"),
                     ("max_locals", "max_locals")):
            f[f"{k}_{side}"] = str(c[v]) if c else "none"
        f[f"exception_table_count_{side}"] = str(len(c["exc"])) if c else "none"
    unrole = lambda s, r: s.replace("\0R", r).replace("\0r", r.lower())   # noqa: E731
    ia = [x for x, _ in (xa or {}).get("invokes", [])]
    ib = [x for x, _ in (xb or {}).get("invokes", [])]
    sa = [x for _, x in (xa or {}).get("invokes", [])]
    sb = [x for _, x in (xb or {}).get("invokes", [])]
    f["invokes_a"] = _jv(_jpd_uniq(unrole(x, ra) for x in ia)) if xa else "none"
    f["invokes_b"] = _jv(_jpd_uniq(unrole(x, rb) for x in ib)) if xb else "none"
    f["added_invokes"] = _jv(_jpd_uniq(unrole(x, rb) for x in ib if x not in ia))
    f["removed_invokes"] = _jv(_jpd_uniq(unrole(x, ra) for x in ia if x not in ib))
    f["added_invoke_signatures"] = _jv(_jpd_uniq(unrole(x, rb) for x in sb if x not in sa))
    f["removed_invoke_signatures"] = _jv(_jpd_uniq(unrole(x, ra) for x in sa if x not in sb))
    la, lb = (xa or {}).get("lambdas", []), (xb or {}).get("lambdas", [])
    short = lambda x: re.sub(r"\$adapted$", "", x.split(":")[0].rsplit(".", 1)[-1])   # noqa: E731
    f["added_lambdas"] = _jv(_jpd_uniq(short(x) for x in lb if x not in la))
    f["removed_lambdas"] = _jv(_jpd_uniq(short(x) for x in la if x not in lb))
    f["added_lambdas_raw"] = _jv(_jpd_uniq(unrole(x, rb) for x in lb if x not in la))
    f["removed_lambdas_raw"] = _jv(_jpd_uniq(unrole(x, ra) for x in la if x not in lb))
    f["invokedynamic_count_a"] = str((xa or {}).get("ops", []).count("invokedynamic"))
    f["invokedynamic_count_b"] = str((xb or {}).get("ops", []).count("invokedynamic"))
    oa, ob = (xa or {}).get("ops", []), (xb or {}).get("ops", [])
    f["added_opcodes"] = _jv(sorted({o for o in ob if ob.count(o) > oa.count(o)}))
    f["removed_opcodes"] = _jv(sorted({o for o in oa if oa.count(o) > ob.count(o)}))
    f["opcodes_a"], f["opcodes_b"] = _jv(sorted(set(oa))), _jv(sorted(set(ob)))
    f["catch_types_a"] = _jv(_jpd_uniq(unrole(e[3], ra) for e in (xa or {}).get("exc", ())))
    f["catch_types_b"] = _jv(_jpd_uniq(unrole(e[3], rb) for e in (xb or {}).get("exc", ())))
    f["fix_kind"] = _jpd_fix_kind(xa, xb) if first else ("method_added" if added else "method_removed")
    f.update(jf)
    ca_, cb_ = [], []   # constants pushed anywhere in the changed class (ldc/ldc2_w numerics, *const_*, *ipush)
    for _, _, _, c in A["methods"]:
        ca_ += (c or {}).get("consts", [])
    for _, _, _, c in B["methods"]:
        cb_ += (c or {}).get("consts", [])
    f["added_constants"] = _jv(_jpd_uniq(x for x in cb_ if x not in ca_))
    f["removed_constants"] = _jv(_jpd_uniq(x for x in ca_ if x not in cb_))
    guard = re.compile(r"^(if\w*|[lfd]cmp[lg]?|arraylength|athrow|instanceof)$")
    f["added_guard_opcodes"] = _jv(sorted({o for o in ob if guard.match(o) and ob.count(o) > oa.count(o)}))
    gcall = re.compile(r"(RT\.count|\.length|\.size|\.isEmpty|\.nonEmpty(\$extension)?|Option\$\.apply|"
                       r"Optional\.ofNullable|requireNonNull|checkIndex|checkFromToIndex|isDefinedAt|\.lift|"
                       r"Intrinsics\.checkNotNull\w*|Objects\.(isNull|nonNull)|Numbers\.(lt|lte|gt|gte)|"
                       r"\.(contains|containsKey))$")
    f["added_guard_calls"] = _jv(_jpd_uniq(unrole(x, rb) for x in ib if x not in ia and gcall.search(x)))
    f["guard_added"] = _jv(f["added_guard_opcodes"] != "[]" or f["added_guard_calls"] != "[]")
    for k in [k for k in f if k.endswith(("_a", "_b"))]:
        base, s = k[:-2], k[-1]
        f[base + ("_before" if s == "a" else "_after")] = f[k]
        f[base + ("_vulnerable" if s == "a" else "_corrected")] = f[k]
    return f


def jvm_patch_diff_field(jar_a, jar_b, field):
    """One jvm_patch_diff fact as an answer string; "none" when absent, None when the inputs aren't JVM twins."""
    f = jvm_patch_diff(jar_a, jar_b)
    return None if f is None else f.get(field, "none")


# --- Native twin patch diff (ELF x86/x86-64 vulnerable/fixed builds: C/C++/Rust/Go) ------------------------------
# Functions come from .symtab/.dynsym FUNC symbols (sized), else .eh_frame FDEs (stripped -> sub_<hex addr of A>).
# Twins match by name, else by unique normalised-body hash, else by best (calls, strings, mnemonic shape) score.
# capstone-lite instructions are normalised: branch targets -> in-function instruction index / imp:<name> (PLT,
# GOT slot, __x_chk folded to x) / fn:<name>; RIP-relative and absolute image addresses -> str:"..." / obj:<name> /
# fn:<name> / MEM; immediates kept; nop/int3 padding dropped. Vocabulary of fix_kind is SPECULATIVE (no GM label yet).
_NPD_RUNTIME = re.compile(r"^(_init|_fini|_start|deregister_tm_clones|register_tm_clones|__do_global_dtors_aux|"
                          r"frame_dummy|__libc_csu_init|__libc_csu_fini|_dl_relocate_static_pie)$")
_NPD_UNSAFE = {"strcpy": ("strncpy", "strlcpy", "strcpy_s", "stpncpy", "memcpy", "snprintf"),
               "stpcpy": ("stpncpy", "strncpy", "strlcpy"),
               "gets": ("fgets", "gets_s", "getline", "read", "fread"),
               "sprintf": ("snprintf", "sprintf_s", "asprintf"), "vsprintf": ("vsnprintf", "vsprintf_s"),
               "strcat": ("strncat", "strlcat", "strcat_s"), "wcscpy": ("wcsncpy", "wcscpy_s"),
               "scanf": ("fgets", "scanf_s"), "sscanf": ("strtol", "strtoul", "sscanf_s"), "atoi": ("strtol",),
               "memcpy": ("memmove", "memcpy_s"), "system": ("execve", "execv", "execvp", "posix_spawn"),
               "rand": ("getrandom", "arc4random"), "tmpnam": ("mkstemp",), "mktemp": ("mkstemp",),
               "realpath": ("canonicalize_file_name",), "alloca": ("malloc",), "strtok": ("strtok_r",)}
_NPD_SIGNED, _NPD_UNSIGNED = ("jl", "jle", "jg", "jge"), ("jb", "jbe", "ja", "jae")
_NPD_REL = {"jl": "jle", "jle": "jl", "jg": "jge", "jge": "jg", "jb": "jbe", "jbe": "jb", "ja": "jae", "jae": "ja"}
_NPD_JCC = set(_NPD_SIGNED + _NPD_UNSIGNED)
_NPD_HEX = re.compile(r"(?<![\w$])(-?)0x([0-9a-f]+)")
_NPD_RIP = re.compile(r"\[(rip|eip) ([+-]) 0x([0-9a-f]+)\]")


def _npd_imp(n):
    n = n.split("@")[0]
    m = re.fullmatch(r"__(\w+?)_chk", n)
    return m.group(1) if m else n


def _npd_elf(data):
    """ELF x86 -> {"bits", "funcs": [(addr, size, name, named)], "exec": [(lo, hi, bytes)], "secs", "imp", "obj"}."""
    from elftools.elf.elffile import ELFFile
    from elftools.elf.relocation import RelocationSection
    from elftools.elf.sections import SymbolTableSection
    ef = ELFFile(io.BytesIO(data))
    if ef["e_machine"] not in ("EM_X86_64", "EM_386"):
        return None
    bits = 64 if ef.elfclass == 64 else 32
    secs, exe = [], []
    for s in ef.iter_sections():
        if s["sh_addr"] and s["sh_type"] != "SHT_NOBITS" and s["sh_size"]:
            d = s.data()
            secs.append((s["sh_addr"], s["sh_addr"] + len(d), d, s.name))
            if s["sh_flags"] & 4:
                exe.append((s["sh_addr"], s["sh_addr"] + len(d), d, s.name))
    if not exe:
        return None
    slot, slot_raw = {}, {}
    for s in ef.iter_sections():
        if isinstance(s, RelocationSection) and s["sh_link"]:
            st = ef.get_section(s["sh_link"])
            for r in s.iter_relocations():
                if r["r_info_sym"]:
                    nm_ = st.get_symbol(r["r_info_sym"]).name
                    if nm_:
                        slot[r["r_offset"]] = _npd_imp(nm_)
                        slot_raw[r["r_offset"]] = nm_.split("@")[0]
    import capstone
    md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64 if bits == 64 else capstone.CS_MODE_32)
    gotplt = next((lo for lo, _, _, n in secs if n == ".got.plt"), 0) or next((lo for lo, _, _, n in secs
                                                                                if n == ".got"), 0)
    imp, imp_raw = {}, {}
    for lo, hi, d, n in exe:
        if not n.startswith(".plt"):
            continue
        for a, sz, mn, op in md.disasm_lite(d, lo):
            if not mn.endswith("jmp") or "ptr" not in op:
                continue
            m = _NPD_RIP.search(op)
            if m:
                tgt = a + sz + (1 if m.group(2) == "+" else -1) * int(m.group(3), 16)
            else:
                m = re.search(r"\[(?:ebx \+ )?0x([0-9a-f]+)\]", op)
                if not m:
                    continue
                tgt = int(m.group(1), 16) + (gotplt if "ebx" in op else 0)
            if tgt in slot:
                imp[lo + ((a - lo) & ~15)] = slot[tgt]
                imp_raw[lo + ((a - lo) & ~15)] = slot_raw[tgt]
    funcs, obj, obj_size, seen = [], {}, {}, set()
    for s in ef.iter_sections():
        if not isinstance(s, SymbolTableSection):
            continue
        for y in s.iter_symbols():
            t, v, z = y["st_info"]["type"], y["st_value"], y["st_size"]
            if t == "STT_OBJECT" and y.name and v:
                obj.setdefault(v, y.name)
                obj_size.setdefault(v, z)
            if t != "STT_FUNC" or not v or not z or v in seen or not y.name:
                continue
            if any(lo <= v < hi for lo, hi, _, _ in exe):
                seen.add(v)
                funcs.append((v, z, y.name, True))
    if not funcs:   # stripped: .eh_frame FDE ranges (.eh_frame_hdr table first; pyelftools CFI walk is slow)
        try:
            for v, z in (_npd_ehhdr(secs) or [(h["initial_location"], h["address_range"]) for h in
                                              (getattr(e, "header", None) for e in ef.get_dwarf_info().EH_CFI_entries())
                                              if h is not None and "initial_location" in h]):
                if z:
                    if v not in seen and v != ef["e_entry"] and any(lo <= v < hi and n_ not in (".init", ".fini")
                                                                    and not n_.startswith(".plt")
                                                                    for lo, hi, _, n_ in exe):
                        seen.add(v)
                        funcs.append((v, z, f"sub_{v:x}", False))
        except Exception:   # noqa: BLE001 -- no/odd eh_frame
            pass
    funcs.sort()
    return {"bits": bits, "funcs": funcs, "exec": exe, "secs": secs, "imp": imp, "slot": slot, "obj": obj, "md": md,
            "imp_raw": imp_raw, "slot_raw": slot_raw, "obj_size": obj_size}


def _npd_same_raw(x, y):
    """True when two same-size function bodies differ only in 4-byte fields after a rel32 call/jmp/jcc opcode or a
    RIP-relative ModRM (mod=00 rm=101) -- i.e. the code only moved."""
    if len(x) != len(y) or not x:
        return False
    if x == y:
        return True
    k, n = 0, len(x)
    while k < n:
        if x[k] == y[k]:
            k += 1
            continue
        for st in range(max(1, k - 3), k + 1):
            p = x[st - 1]
            if p != y[st - 1] or st + 4 > n:
                continue
            if p in (0xe8, 0xe9) or (st >= 2 and x[st - 2] == 0x0f and 0x80 <= p <= 0x8f) or \
                    (st >= 2 and p & 0xc7 == 0x05 and x[st - 2] in (0x8b, 0x8d, 0x89, 0x3b, 0x39, 0x03, 0x2b, 0xff,
                                                                    0x10, 0x11, 0x28, 0x29, 0x6f, 0x7f, 0xc7, 0x83,
                                                                    0x81, 0x80, 0xc6, 0x0b, 0x33, 0x23, 0x85, 0xb6,
                                                                    0xb7, 0xbe, 0xbf, 0x63, 0x2e, 0x2f, 0x58, 0x59,
                                                                    0x5c, 0x5e, 0x54, 0x57, 0x88, 0x38, 0x3a)):
                k = st + 4
                break
        else:
            return False
    return True


def _npd_ehhdr(secs):
    """[(pc_begin, pc_range)] from .eh_frame_hdr's binary-search table (datarel sdata4) + each FDE's pcrel sdata4
    pc_begin/pc_range (gcc/clang x86 default); [] when the encodings differ (caller falls back to pyelftools)."""
    hdr = next(((lo, d) for lo, _, d, n in secs if n == ".eh_frame_hdr"), None)
    if not hdr or len(hdr[1]) < 12:
        return []
    lo, d = hdr
    ver, pe, ce, te = d[:4]
    if ver != 1 or ce != 0x03 or te != 0x3b or pe != 0x1b:
        return []
    cnt, = struct.unpack_from("<I", d, 8)
    out = []
    for k in range(min(cnt, (len(d) - 12) // 8)):
        _, fo = struct.unpack_from("<ii", d, 12 + 8 * k)
        fa = lo + fo
        fb = _npd_bytes({"secs": secs}, fa, 16)
        if len(fb) < 16:
            return []
        pcb, pcr = struct.unpack_from("<iI", fb, 8)
        out.append((fa + 8 + pcb, pcr))
    return out


def _npd_bytes(img, a, n):
    for lo, hi, d, _ in img["secs"]:
        if lo <= a < hi:
            return d[a - lo:a - lo + n]
    return b""


def _npd_ref(img, t, fnames):
    if t in img["imp"]:
        return f"imp:{img['imp'][t]}"
    if t in img["slot"]:
        return f"imp:{img['slot'][t]}"
    if t in fnames:
        return f"fn:{fnames[t]}"
    if t in img["obj"]:
        return f"obj:{img['obj'][t]}"
    s = _npd_bytes(img, t, 96)
    if s and not any(lo <= t < hi for lo, hi, _, _ in img["exec"]):
        z = s.split(b"\0", 1)
        if len(z) == 2 and z[0] and all(32 <= c < 127 or c in (9, 10, 13) for c in z[0]):
            return "str:" + json.dumps(z[0].decode())
    return "MEM"


def _npd_body(img, fn, fnames):
    """One function -> list of (normalised token, mnemonic, raw op_str)."""
    a0, sz, name, _ = fn
    code = _npd_bytes(img, a0, sz)
    raw = [(a, s, mn, op) for a, s, mn, op in img["md"].disasm_lite(code, a0) if mn not in ("nop", "int3")]
    idx = {a: k for k, (a, _, _, _) in enumerate(raw)}
    lo_img = min(lo for lo, _, _, _ in img["secs"])
    hi_img = max(hi for _, hi, _, _ in img["secs"])
    out = []
    for a, s, mn, op in raw:
        base = mn.split()[-1]
        if (base.startswith("j") or base == "call" or base.startswith("loop")) and re.fullmatch(r"0x[0-9a-f]+", op):
            t = int(op, 16)
            tok = f"{mn} L{idx[t]}" if t in idx else f"{mn} {_npd_ref(img, t, fnames)}"
        else:
            def rip(m, a=a, s=s):
                return "[" + _npd_ref(img, a + s + (1 if m.group(2) == "+" else -1) * int(m.group(3), 16), fnames) + "]"

            def absv(m):
                v = int(m.group(2), 16)
                return _npd_ref(img, v, fnames) if not m.group(1) and v >= 0x1000 and lo_img <= v < hi_img \
                    else m.group(0)
            tok = mn + (" " + _NPD_HEX.sub(absv, _NPD_RIP.sub(rip, op)) if op else "")
        out.append((tok, base, op))
    return out


def _npd_calls(body):
    return [t.split(" ", 1)[1][4:] for t, b, _ in body if b == "call" and " imp:" in t] + \
        [t.split("[imp:", 1)[1].rstrip("]") for t, b, _ in body if b == "call" and "[imp:" in t]


def _npd_pairs(body, kinds, test=False):
    """count of cmp (or test r,r when test) immediately followed by a jcc in kinds -> list of cmp operand strings."""
    out = []
    for (t0, b0, o0), (_, b1, _) in zip(body, body[1:]):
        rr = b0 == "test" and len({x.strip() for x in o0.split(",")}) == 1
        if test:
            if rr and b1 in kinds:
                out.append(o0)
        elif b0 == "cmp" and b1 in kinds or rr and b1 in ("js", "jl", "jns", "jge"):   # + negative-index guard
            out.append(o0)
    return out


def _npd_frame(body):
    for t, b, o in body[:12]:
        m = re.fullmatch(r"[re]?sp, (0x[0-9a-f]+|\d+)", o) if b == "sub" else None
        if m:
            return int(m.group(1), 0)
    return None


def _npd_func_diff(ba, bb):
    import difflib
    ta, tb = [x[0] for x in ba], [x[0] for x in bb]
    sm = difflib.SequenceMatcher(None, ta, tb, autojunk=False)
    added, removed, flips, consts = [], [], [], []
    for op, i1, i2, j1, j2 in sm.get_opcodes():
        if op == "equal":
            continue
        removed += ta[i1:i2]
        added += tb[j1:j2]
        if op == "replace" and i2 - i1 == j2 - j1:
            for x, y in zip(ba[i1:i2], bb[j1:j2]):
                if x[1] != y[1] and x[1] in _NPD_JCC and y[1] in _NPD_JCC:
                    flips.append(f"{x[1]}->{y[1]}")
                elif x[1] == y[1]:
                    va, vb = _NPD_HEX.findall(x[0]), _NPD_HEX.findall(y[0])
                    if len(va) == len(vb) and _NPD_HEX.sub("#", x[0]) == _NPD_HEX.sub("#", y[0]):
                        for p, q in zip(va, vb):
                            if p != q:
                                consts.append(f"{p[0]}0x{p[1]}->{q[0]}0x{q[1]}")
    ca, cb = _npd_calls(ba), _npd_calls(bb)
    rem_c = [c for c in dict.fromkeys(ca) if c not in cb]
    add_c = [c for c in dict.fromkeys(cb) if c not in ca]
    repl = []
    for r in rem_c:
        cand = [x for x in add_c if x in _NPD_UNSAFE.get(r, ()) or x in (r[:3] + "n" + r[3:], r + "_s", "f" + r,
                                                                           "sn" + r[1:], r[:4] + "n" + r[4:])]
        if not cand and len(rem_c) == len(add_c) == 1:
            cand = add_c
        if cand:
            repl.append(f"{r}->{cand[0]}")
    fa, fb = _npd_frame(ba), _npd_frame(bb)
    bnd = (_npd_pairs(ba, _NPD_JCC), _npd_pairs(bb, _NPD_JCC))
    nul = (_npd_pairs(ba, ("je", "jne"), True), _npd_pairs(bb, ("je", "jne"), True))
    nul_cmp = sum(1 for t, b, o in bb if b == "cmp" and o.endswith(", 0")) - \
        sum(1 for t, b, o in ba if b == "cmp" and o.endswith(", 0"))

    def null_after_free(body):
        n = 0
        for k, (t, b, o) in enumerate(body):
            if b == "call" and re.search(r"imp:(free|delete|_ZdlPv\w*|_ZdaPv\w*|g_free|kfree)\b", t):
                n += any(x[1] == "mov" and re.search(r"ptr \[.*\], 0$", x[2]) for x in body[k + 1:k + 4])
        return n
    fmt_a = [t for t in ta if "str:" in t and "%" in t]
    fmt_b = [t for t in tb if "str:" in t and "%" in t]
    pf = re.compile(r"^v?[fsd]?n?printf|^syslog|^err|^warn")
    sign = [x for x in flips if (x.split("->")[0] in _NPD_SIGNED) != (x.split("->")[1] in _NPD_SIGNED)]
    obo = [x for x in flips if _NPD_REL.get(x.split("->")[0]) == x.split("->")[1]]
    obo_c = [x for x in consts if abs(int(x.split("->")[0], 16) - int(x.split("->")[1], 16)) == 1]
    unsafe_repl = [x for x in repl if x.split("->")[0] in _NPD_UNSAFE]
    if unsafe_repl:
        kind = "replaced_unsafe_call"
    elif null_after_free(bb) > null_after_free(ba):
        kind = "null_after_free"
    elif len(fmt_b) > len(fmt_a) and any(pf.search(c) for c in cb) and not add_c:
        kind = "format_string"
    elif len(nul[1]) > len(nul[0]) or nul_cmp > 0 and len(bnd[1]) <= len(bnd[0]):
        kind = "null_check"
    elif len(bnd[1]) > len(bnd[0]):
        kind = "bounds_check"
    elif sign:
        kind = "signedness"
    elif obo or obo_c:
        kind = "off_by_one"
    elif repl:
        kind = "replaced_call"
    elif fa != fb:
        kind = "frame_size_change"
    elif consts:
        kind = "constant_change"
    else:
        kind = "logic_change"
    new_b = [x for x in bnd[1] if x not in bnd[0]] or bnd[1][len(bnd[0]):]
    return {"fix_kind": kind, "added_instructions": added, "removed_instructions": removed,
            "added_instruction_count": len(added), "removed_instruction_count": len(removed),
            "instruction_count_a": len(ta), "instruction_count_b": len(tb),
            "calls_a": list(dict.fromkeys(ca)), "calls_b": list(dict.fromkeys(cb)),
            "removed_calls": rem_c, "added_calls": add_c, "replaced_calls": repl,
            "frame_size_a": fa, "frame_size_b": fb, "comparison_flips": flips, "changed_constants": consts,
            "bounds_checks_a": len(bnd[0]), "bounds_checks_b": len(bnd[1]),
            "inserted_bounds_check": len(bnd[1]) > len(bnd[0]),
            "bounds_check_operands": new_b if len(bnd[1]) > len(bnd[0]) else [],
            "inserted_null_check": len(nul[1]) > len(nul[0]) or nul_cmp > 0,
            "null_after_free": null_after_free(bb) > null_after_free(ba),
            "signedness_change": bool(sign), "off_by_one": bool(obo or obo_c),
            "mnemonics_a": sorted({x[1] for x in ba}), "mnemonics_b": sorted({x[1] for x in bb})}


def _npd_match(fa, fb, ba, bb):
    """[(i, j)] pairs of matched function indexes (fa/fb lists, ba/bb normalised bodies)."""
    pairs, ua, ub = [], set(range(len(fa))), set(range(len(fb)))
    nb = {}
    for j, f in enumerate(fb):
        if f[3]:
            nb.setdefault(f[2], j)
    for i, f in enumerate(fa):
        j = nb.get(f[2]) if f[3] else None
        if j is not None and j in ub:
            pairs.append((i, j))
            ua.discard(i)
            ub.discard(j)
    named = all(f[3] for f in fa) and all(f[3] for f in fb) and fa and fb
    if named:
        return pairs, ua, ub
    h = lambda b: hash(tuple(re.sub(r"fn:\S+", "fn", t) for t, _, _ in b))   # noqa: E731
    ha, hb = {}, {}
    for i in ua:
        ha.setdefault(h(ba[i]), []).append(i)
    for j in ub:
        hb.setdefault(h(bb[j]), []).append(j)
    for k, xs in ha.items():
        if len(xs) == 1 and len(hb.get(k, ())) == 1:
            pairs.append((xs[0], hb[k][0]))
            ua.discard(xs[0])
            ub.discard(hb[k][0])
    import difflib

    def feat(b):
        return ({t for t, _, _ in b if "imp:" in t or "str:" in t or "obj:" in t}, [x[1] for x in b])
    if len(ua) * len(ub) <= 40000:
        fA, fB = {i: feat(ba[i]) for i in ua}, {j: feat(bb[j]) for j in ub}
        cand = []
        for i in ua:
            for j in ub:
                sa, sb = fA[i][0], fB[j][0]
                jac = len(sa & sb) / len(sa | sb) if sa | sb else 0.5
                r = difflib.SequenceMatcher(None, fA[i][1], fB[j][1], autojunk=False).quick_ratio()
                cand.append((jac + r, i, j))
        for sc, i, j in sorted(cand, reverse=True):
            if sc >= 0.9 and i in ua and j in ub:
                pairs.append((i, j))
                ua.discard(i)
                ub.discard(j)
    return pairs, ua, ub


def native_patch_diff(a, b):
    """Per-function diff of twin native builds (A = vulnerable/before, B = fixed/after; ELF x86/x86-64 bytes) ->
    {field: answer string}; None when either side is not a parsable x86 ELF with functions. Fields:
    changed_functions (A address order) / changed_function / changed_function_count / changed_function_address(_a/_b),
    unchanged_function_count, added_/removed_functions, function_count_a/b, fix_kind (replaced_unsafe_call,
    null_after_free, format_string, null_check, bounds_check, signedness, off_by_one, replaced_call,
    frame_size_change, constant_change, logic_change; "none" when nothing changed), added_/removed_instructions(+
    _count), instruction_count_a/b, calls_a/b, added_/removed_calls, replaced_calls / replaced_call ("strcpy->
    strncpy"), unsafe_call / safe_call, frame_size_a/b (+ _hex), comparison_flips / comparison_flip ("jle->jl"),
    changed_constants, inserted_bounds_check / bounds_check_operands, inserted_null_check, null_after_free,
    signedness_change, off_by_one. "<field>:<function>" per changed function; _before/_after, _vulnerable/_fixed/
    _patched alias every _a/_b field."""
    try:
        return _native_patch_diff(bytes(a), bytes(b))
    except Exception:   # noqa: BLE001 -- malformed / decoy input: no answer
        return None


def _native_patch_diff(a, b):
    if a[:4] != b"\x7fELF" or b[:4] != b"\x7fELF":
        return None
    ia, ib = _npd_elf(a), _npd_elf(b)
    if not ia or not ib or not ia["funcs"] or not ib["funcs"]:
        return None
    fa = [f for f in ia["funcs"] if not _NPD_RUNTIME.match(f[2])]
    fb = [f for f in ib["funcs"] if not _NPD_RUNTIME.match(f[2])]
    if max(len(fa), len(fb)) > 3000 and not all(x[3] for x in fa + fb):
        return None   # huge stripped twins: no symbol anchor, too slow to align inside the clock
    deadline = time.monotonic() + 2.5
    na = {f[0]: f[2] for f in ia["funcs"]} if all(f[3] for f in fa) else {f[0]: "?" for f in ia["funcs"]}
    nb = {f[0]: f[2] for f in ib["funcs"]} if all(f[3] for f in fb) else {f[0]: "?" for f in ib["funcs"]}
    same = set()   # name-matched twins whose bytes differ only inside rel32/disp32 fields: unchanged, no disasm
    if all(x[3] for x in fa) and all(x[3] for x in fb):
        ixb = {x[2]: x for x in fb}
        for x in fa:
            y = ixb.get(x[2])
            if y and _npd_same_raw(_npd_bytes(ia, x[0], x[1]), _npd_bytes(ib, y[0], y[1])):
                same.add(x[2])
    ba, bb = [], []
    for fs, img, nm_, out in ((fa, ia, na, ba), (fb, ib, nb, bb)):
        for f in fs:
            if time.monotonic() > deadline:
                return None
            out.append([("=" + f[2], "", "")] if f[2] in same else _npd_body(img, f, nm_))
    pairs, ua, ub = _npd_match(fa, fb, ba, bb)
    pairs.sort()
    changed = [(i, j) for i, j in pairs if [t for t, _, _ in ba[i]] != [t for t, _, _ in bb[j]]]
    f = {"function_count_a": str(len(fa)), "function_count_b": str(len(fb)),
         "matched_function_count": str(len(pairs)),
         "changed_functions": _jv([fa[i][2] for i, _ in changed]), "changed_function_count": str(len(changed)),
         "unchanged_function_count": str(len(pairs) - len(changed)),
         "added_functions": _jv([fb[j][2] for j in sorted(ub)]), "removed_functions": _jv([fa[i][2] for i in sorted(ua)]),
         "stripped_a": str(not all(x[3] for x in fa)).lower(), "stripped_b": str(not all(x[3] for x in fb)).lower()}
    if not changed:
        f.update({"fix_kind": "none", "changed_function": "none"})
        return f
    for n, (i, j) in enumerate(changed):
        d = _npd_func_diff(ba[i], bb[j])
        pre = {"changed_function": fa[i][2], "changed_function_a": fa[i][2], "changed_function_b": fb[j][2],
               "changed_function_address": hex(fa[i][0]), "changed_function_address_a": hex(fa[i][0]),
               "changed_function_address_b": hex(fb[j][0]), "function_size_a": str(fa[i][1]),
               "function_size_b": str(fb[j][1])}
        for k, v in d.items():
            if isinstance(v, bool):
                v = str(v).lower()
            elif isinstance(v, list):
                v = _jv(v)
            elif v is None:
                v = "none"
            pre[k] = str(v)
        for k in ("frame_size_a", "frame_size_b"):
            pre[k + "_hex"] = hex(int(pre[k])) if pre[k] != "none" else "none"
        for k, src in (("replaced_call", "replaced_calls"), ("comparison_flip", "comparison_flips"),
                       ("changed_constant", "changed_constants")):
            pre[k] = d[src][0] if d[src] else "none"
        pre["unsafe_call"] = d["replaced_calls"][0].split("->")[0] if d["replaced_calls"] else "none"
        pre["safe_call"] = d["replaced_calls"][0].split("->")[1] if d["replaced_calls"] else "none"
        for k, v in pre.items():
            f[f"{k}:{fa[i][2]}"] = v
            if n == 0:
                f[k] = v
    for k in [k for k in f if k.endswith(("_a", "_b")) and ":" not in k]:
        base, s = k[:-2], k[-1]
        for al in (("_before", "_after"), ("_vulnerable", "_fixed"), ("_vulnerable", "_patched")):
            f[base + al[s == "b"]] = f[k]
    return f


def native_patch_diff_field(a, b, field):
    """One native_patch_diff fact; "none" when absent, None when the inputs aren't x86 ELF twins."""
    f = native_patch_diff(a, b)
    return None if f is None else f.get(field, "none")


# --- Stripped twin function matching (BinDiff/Diaphora-style, no symbols) --------------------------------------------
# Function starts/ranges = .eh_frame FDEs (_npd_elf), bodies = _npd_body tokens with callees as fn:0x<addr>. Matching
# rounds over the unmatched set: unique strict hash (callees blanked) -> unique register-blind hash -> unique
# strings/imports signature -> call-graph propagation (positional callees of matched pairs) -> last 1:1 leftover ->
# best (mnemonic shape + refs) score >= 0.6. Matched-but-different (callees renamed to their pair) = changed; the
# patched function = the changed pair with the biggest register-blind delta. An optional symbolized twin names it
# (same text bytes -> by address, else by the same matcher). Answer vocabulary is SPECULATIVE (no GM label yet).
_STW_REG = re.compile(r"\b(?:[re]?[a-d]x|[a-d][lh]|[re]?[sd]il?|[re]?[sb]pl?|r(?:[89]|1[0-5])[dwb]?|[xy]mm\d+)\b")
_STW_FN = re.compile(r"fn:0x([0-9a-f]+)")


def _stw_funcs(img, deadline):
    """[{addr, size, toks, strict, loose, refs, callees, mn}] for every function of an _npd_elf image."""
    names = {f[0]: hex(f[0]) for f in img["funcs"]}
    out = []
    for f in img["funcs"]:
        if time.monotonic() > deadline:
            return None
        if _NPD_RUNTIME.match(f[2]):
            continue
        body = _npd_body(img, f, names)
        toks = [t for t, _, _ in body]
        blank = [_STW_FN.sub("fn", t) for t in toks]
        out.append({"addr": f[0], "size": f[1], "name": f[2] if f[3] else None, "toks": toks,
                    "strict": hash(tuple(blank)), "loose": hash(tuple(_STW_REG.sub("r", t) for t in blank)),
                    "refs": frozenset(t.split(" ", 1)[1] for t in toks if " " in t and ("imp:" in t or "str:" in t)),
                    "callees": [int(m, 16) for t in toks for m in _STW_FN.findall(t)],
                    "mn": [b for _, b, _ in body], "bbs": 1 + sum(b.startswith("j") for _, b, _ in body)})
    return out


def _stw_match(A, B):
    """{A index: B index} over two _stw_funcs lists."""
    m, ua, ub = {}, set(range(len(A))), set(range(len(B)))

    def pair(i, j):
        m[i] = j
        ua.discard(i)
        ub.discard(j)

    def uniq(key):
        ka, kb = {}, {}
        for i in ua:
            ka.setdefault(key(A[i]), []).append(i)
        for j in ub:
            kb.setdefault(key(B[j]), []).append(j)
        for k, xs in ka.items():
            if k is not None and len(xs) == 1 and len(kb.get(k, ())) == 1:
                pair(xs[0], kb[k][0])
    ia, ib = {f["addr"]: i for i, f in enumerate(A)}, {f["addr"]: j for j, f in enumerate(B)}

    def propagate():
        grew = True
        while grew:
            grew = False
            for i, j in list(m.items()):
                ca = [ia[c] for c in dict.fromkeys(A[i]["callees"]) if c in ia]
                cb = [ib[c] for c in dict.fromkeys(B[j]["callees"]) if c in ib]
                if len(ca) == len(cb):
                    for x, y in zip(ca, cb):
                        if x in ua and y in ub:
                            pair(x, y)
                            grew = True
    for key in (lambda f: (f["strict"], f["size"]), lambda f: f["strict"], lambda f: f["loose"],
                lambda f: f["refs"] or None):
        uniq(key)
        propagate()
    ka, kb = {}, {}   # duplicate bodies (thunks, wrappers): same count on both sides -> pair in address order
    for i in sorted(ua):
        ka.setdefault(A[i]["strict"], []).append(i)
    for j in sorted(ub):
        kb.setdefault(B[j]["strict"], []).append(j)
    for k, xs in ka.items():
        if len(xs) == len(kb.get(k, ())):
            for i, j in zip(xs, kb[k]):
                pair(i, j)
    propagate()
    if len(ua) == 1 and len(ub) == 1:
        pair(ua.pop(), ub.pop())
    import difflib
    if ua and ub and len(ua) * len(ub) <= 20000:
        cand = []
        for i in ua:
            for j in ub:
                sa, sb = A[i]["refs"], B[j]["refs"]
                jac = len(sa & sb) / len(sa | sb) if sa | sb else 0.5
                r = difflib.SequenceMatcher(None, A[i]["mn"], B[j]["mn"], autojunk=False).quick_ratio()
                cand.append(((jac + r) / 2, -abs(A[i]["addr"] - B[j]["addr"]), i, j))
        for sc, _, i, j in sorted(cand, reverse=True):
            if sc >= 0.6 and i in ua and j in ub:
                pair(i, j)
        propagate()
    return m


def _stw_fde(img, data):
    """{pc_begin: pc_range} from .eh_frame (hdr table first, pyelftools CFI fallback)."""
    out = dict(_npd_ehhdr(img["secs"]))
    if not out:
        from elftools.elf.elffile import ELFFile
        for e in ELFFile(io.BytesIO(data)).get_dwarf_info().EH_CFI_entries():
            h = getattr(e, "header", None)
            if h is not None and "initial_location" in h:
                out[h["initial_location"]] = h["address_range"]
    return out


def _stw_off(data, va):
    from elftools.elf.elffile import ELFFile
    for s in ELFFile(io.BytesIO(data)).iter_segments():
        if s["p_type"] == "PT_LOAD" and s["p_vaddr"] <= va < s["p_vaddr"] + s["p_filesz"]:
            return va - s["p_vaddr"] + s["p_offset"]
    return None


def _stw_sym_names(sym, side, img_side, F_side):
    """{side addr: name} from a symbolized twin: same text bytes -> by address, else by _stw_match."""
    if sym is None or sym[:4] != b"\x7fELF":
        return {}
    ims = _npd_elf(sym)
    if not ims or not all(f[3] for f in ims["funcs"]):
        return {}
    tx = lambda im: [(lo, d) for lo, _, d, n in im["exec"] if n == ".text"]   # noqa: E731
    byaddr = {f[0]: f[2] for f in ims["funcs"]}
    if tx(ims) == tx(img_side):
        return {f["addr"]: byaddr[f["addr"]] for f in F_side if f["addr"] in byaddr}
    S = _stw_funcs(ims, time.monotonic() + 1.5)
    if not S:
        return {}
    return {F_side[i]["addr"]: S[j]["name"] for i, j in _stw_match(F_side, S).items()}


def stripped_twin_match(a, b, sym=None):
    """Match functions of two STRIPPED x86/x86-64 ELF twins (A = vulnerable/before, B = patched/after; bytes) and
    report the changed one -> {field: answer string}; None when either side is not a parsable x86 ELF with functions.
    Optional `sym` = a symbolized build of A or B (names the functions). Fields: function_count_a/b,
    matched_function_count, changed_function_count, changed_functions (sub_<A va> or symbol name, JSON),
    added_functions / removed_functions, patched_function / changed_function (name when sym resolves it, else
    sub_<hex>), changed_function_name ("none" without sym), changed_function_va(_a/_b) (hex),
    changed_function_offset(_a/_b) (file offset hex; _dec decimal), eh_frame_range(_a/_b) ("0xSTART-0xEND", end
    exclusive), eh_frame_start/_end/_size(_a/_b), function_size_a/b, instruction_count_a/b, basic_block_count_a/b.
    _before/_after, _vulnerable/_fixed/_patched alias every _a/_b field. Identical twins -> changed_function "none"."""
    try:
        return _stripped_twin_match(bytes(a), bytes(b), None if sym is None else bytes(sym))
    except Exception:   # noqa: BLE001 -- malformed / decoy input: no answer
        return None


def _stripped_twin_match(a, b, sym):
    if a[:4] != b"\x7fELF" or b[:4] != b"\x7fELF":
        return None
    ia, ib = _npd_elf(a), _npd_elf(b)
    if not ia or not ib or not ia["funcs"] or not ib["funcs"] or max(len(ia["funcs"]), len(ib["funcs"])) > 2500:
        return None   # no anchor at that size: too slow to align inside the clock
    deadline = time.monotonic() + 1.5
    A, B = _stw_funcs(ia, deadline), _stw_funcs(ib, deadline)
    if not A or not B:
        return None
    m = _stw_match(A, B)
    pid_a = {A[i]["addr"]: f"p{k}" for k, (i, _) in enumerate(sorted(m.items()))}
    pid_b = {B[j]["addr"]: f"p{k}" for k, (_, j) in enumerate(sorted(m.items()))}

    def ren(f, pid):
        return [_STW_FN.sub(lambda x: "fn:" + pid.get(int(x.group(1), 16), "u" + x.group(1)), t) for t in f["toks"]]
    changed = []
    for i, j in sorted(m.items()):
        ta, tb = ren(A[i], pid_a), ren(B[j], pid_b)
        if ta != tb:
            la, lb = [_STW_REG.sub("r", t) for t in ta], [_STW_REG.sub("r", t) for t in tb]
            import difflib
            delta = 0 if la == lb else sum(max(i2 - i1, j2 - j1) for op, i1, i2, j1, j2 in difflib.SequenceMatcher(
                None, la, lb, autojunk=False).get_opcodes() if op != "equal")
            changed.append((delta, i, j))
    na, nb = _stw_sym_names(sym, a, ia, A), _stw_sym_names(sym, b, ib, B)
    name_a = {f["addr"]: f["name"] or na.get(f["addr"]) or nb.get(B[m[i]]["addr"] if i in m else -1) or
              f"sub_{f['addr']:x}" for i, f in enumerate(A)}
    inv = {j: i for i, j in m.items()}
    name_b = {f["addr"]: f["name"] or nb.get(f["addr"]) or na.get(A[inv[j]]["addr"] if j in inv else -1) or
              f"sub_{f['addr']:x}" for j, f in enumerate(B)}
    fde_a, fde_b = _stw_fde(ia, a), _stw_fde(ib, b)
    out = {"function_count_a": str(len(A)), "function_count_b": str(len(B)), "matched_function_count": str(len(m)),
           "changed_function_count": str(len(changed)),
           "changed_functions": _jv([name_a[A[i]["addr"]] for _, i, _ in changed]),
           "added_functions": _jv([name_b[f["addr"]] for j, f in enumerate(B) if j not in inv]),
           "removed_functions": _jv([name_a[f["addr"]] for i, f in enumerate(A) if i not in m])}
    if not changed:
        out.update({"changed_function": "none", "patched_function": "none", "changed_function_name": "none"})
        return out
    _, i, j = max(changed, key=lambda c: (c[0], -A[c[1]]["addr"]))
    fa, fb = A[i], B[j]
    nm_ = name_a[fa["addr"]]
    real = nm_ if not nm_.startswith("sub_") or fa["name"] or fa["addr"] in na or fb["addr"] in nb else "none"
    out.update({"changed_function": nm_, "patched_function": nm_, "changed_function_name": real,
                "changed_function_a": nm_, "changed_function_b": name_b[fb["addr"]]})
    for s, f, img, data, fde in (("a", fa, ia, a, fde_a), ("b", fb, ib, b, fde_b)):
        off = _stw_off(data, f["addr"])
        r = fde.get(f["addr"])
        out.update({f"changed_function_va_{s}": hex(f["addr"]), f"function_size_{s}": str(f["size"]),
                    f"changed_function_offset_{s}": hex(off) if off is not None else "none",
                    f"changed_function_offset_dec_{s}": str(off) if off is not None else "none",
                    f"instruction_count_{s}": str(len(f["toks"])), f"basic_block_count_{s}": str(f["bbs"]),
                    f"eh_frame_range_{s}": f"{hex(f['addr'])}-{hex(f['addr'] + r)}" if r else "none",
                    f"eh_frame_start_{s}": hex(f["addr"]) if r else "none",
                    f"eh_frame_end_{s}": hex(f["addr"] + r) if r else "none",
                    f"eh_frame_size_{s}": str(r) if r else "none"})
    for k in ("changed_function_va", "changed_function_offset", "changed_function_offset_dec", "eh_frame_range",
              "eh_frame_start", "eh_frame_end", "eh_frame_size"):
        out[k] = out[k + "_a"]
    out["changed_function_address"] = out["changed_function_va"]
    for k in [k for k in out if k.endswith(("_a", "_b"))]:
        base, s = k[:-2], k[-1]
        for al in (("_before", "_after"), ("_vulnerable", "_fixed"), ("_vulnerable", "_patched")):
            out[base + al[s == "b"]] = out[k]
    return out


def stripped_twin_field(a, b, field, sym=None):
    """One stripped_twin_match fact; "none" when absent, None when the inputs aren't x86 ELF twins."""
    f = stripped_twin_match(a, b, sym)
    return None if f is None else f.get(field, "none")


# --- Bounds-check twins (C manual guard / UBSan / FORTIFY / Rust / Go / Swift) on top of native_patch_diff ----------
# Per changed function: bounds-check sink calls by family, cmp+jcc guards, indexed memory accesses ([base+idx*scale]) and
# how many have no earlier guard in linear order (a dominance PROXY), the guard limit -> buffer length, the indexed
# .data/.bss object (st_size) and which twin carries more checks. Sink families from real gcc/rustc/go 1.26 builds.
_BCK_SINKS = (("ubsan", re.compile(r"^__ubsan_handle_out_of_bounds")),
              ("rust_panic_bounds_check", re.compile(r"panic_bounds_check")),
              ("rust_slice_index_fail", re.compile(r"slice_(?:start_|end_)?index_(?:len|order)_fail|str_index_overflow")),
              ("go_panic_index", re.compile(r"^runtime\.(?:goP|p)anicIndex")),
              ("go_panic_slice", re.compile(r"^runtime\.(?:goP|p)anicSlice")),
              ("go_panic_bounds", re.compile(r"^runtime\.(?:panicBounds|panicExtend|goPanicExtend)")),
              ("swift_index_out_of_range", re.compile(r"fatalErrorMessage|_assertionFailure")),
              ("fortify_chk", re.compile(r"^__(?!stack_chk)\w+_chk$|^__chk_fail$")))
_BCK_LANG = {"ubsan": "c", "fortify_chk": "c", "swift_index_out_of_range": "swift"}
_BCK_MEM = re.compile(r"\[([^\]]+)\]")
_BCK_REG = r"(?:[re]?[a-d]x|[re]?[sd]il?|[re]?[sb]pl?|r\d+[dwb]?|[a-d]l)"
_BCK_IDX = re.compile(rf"^(?:{_BCK_REG}\s*\+\s*)?({_BCK_REG})\*([1248])\b|^{_BCK_REG}\s*\+\s*({_BCK_REG})(?:\s*[+-]|$)")
_BCK_CHK_LEN = {"memcpy": "rcx", "memmove": "rcx", "memset": "rcx", "strncpy": "rcx", "strncat": "rcx",
                "stpncpy": "rcx", "read": "rcx", "fgets": "rcx", "strcpy": "rdx", "strcat": "rdx", "stpcpy": "rdx",
                "snprintf": "rcx", "vsnprintf": "rcx", "sprintf": "rcx", "vsprintf": "rcx", "gets": "rsi"}


def _bck_demangle(n):
    """Rust legacy `_ZN4core9panicking18panic_bounds_check17h..E` -> core::panicking::panic_bounds_check (hash dropped)."""
    if not n.startswith("_ZN"):
        return n
    k, parts = 3, []
    while k < len(n) and n[k].isdigit():
        j = k
        while n[j].isdigit():
            j += 1
        ln = int(n[k:j])
        parts.append(n[j:j + ln])
        k = j + ln
    if parts and re.fullmatch(r"h[0-9a-f]{16}", parts[-1]):
        parts.pop()
    return "::".join(parts) or n


def _bck_reg64(r):
    r = r.strip()
    m = re.fullmatch(r"r(\d+)[dwb]?", r)
    if m:
        return f"r{m.group(1)}"
    return {"eax": "rax", "ebx": "rbx", "ecx": "rcx", "edx": "rdx", "esi": "rsi", "edi": "rdi", "ebp": "rbp",
            "esp": "rsp", "al": "rax", "bl": "rbx", "cl": "rcx", "dl": "rdx", "sil": "rsi", "dil": "rdi"}.get(r, r)


def _bck_func(img, fn, fnames):
    a0, sz, name, _ = fn
    code = _npd_bytes(img, a0, sz)
    ins = [(a, s, mn, op) for a, s, mn, op in img["md"].disasm_lite(code, a0) if mn not in ("nop", "int3")]
    calls, guards, acc, objs, regimm = [], [], [], [], {}
    guarded = False
    for k, (a, s, mn, op) in enumerate(ins):
        base = mn.split()[-1]
        if base == "mov":
            m = re.fullmatch(r"(\w+), (0x[0-9a-f]+|\d+)", op)
            if m:
                regimm[_bck_reg64(m.group(1))] = int(m.group(2), 0)
        rip = _NPD_RIP.search(op)
        if rip:
            t = a + s + (1 if rip.group(2) == "+" else -1) * int(rip.group(3), 16)
            if base == "call" or base == "jmp":
                nm_ = img["slot_raw"].get(t)
                if nm_:
                    calls.append((nm_, dict(regimm)))
                    regimm = {}
                continue
            if t in img["obj"]:
                objs.append((img["obj"][t], img["obj_size"].get(t, 0)))
            elif b"Index out of range" in _npd_bytes(img, t, 64):
                calls.append(("swift:Index out of range", {}))
        if base in ("call", "jmp") and re.fullmatch(r"0x[0-9a-f]+", op):
            t = int(op, 16)
            nm_ = img["imp_raw"].get(t) or (fnames.get(t) if base == "call" or not a0 <= t < a0 + sz else None)
            if nm_:
                calls.append((nm_, dict(regimm)))
                regimm = {}
            continue
        if base == "cmp" and k + 1 < len(ins) and ins[k + 1][2] in _NPD_JCC:
            guards.append((op, ins[k + 1][2]))
            guarded = True
        if base not in ("lea", "nop") and not base.startswith("prefetch"):
            for mm in _BCK_MEM.findall(op):
                m = _BCK_IDX.match(mm.strip())
                if m and "rip" not in mm and "sp" not in (m.group(1) or m.group(3) or ""):
                    acc.append({"scale": int(m.group(2) or 1), "guarded": guarded, "op": f"{mn} {op}"})
    sinks = []
    for nm_, regs in calls:
        for fam, rx in _BCK_SINKS:
            if rx.search(nm_) or rx.search(_bck_demangle(nm_)) or fam.startswith("swift") and nm_.startswith("swift:"):
                ln = None
                if fam.startswith("rust"):
                    ln = regs.get("rsi")
                elif fam == "fortify_chk":
                    ln = regs.get(_BCK_CHK_LEN.get(_npd_imp(nm_), ""))
                sinks.append((fam, _bck_demangle(nm_), ln))
                break
    return {"sinks": sinks, "guards": guards, "acc": acc, "objs": objs, "frame": _npd_frame(_npd_body(img, fn, fnames))}


def bounds_check_facts(a, b):
    """Bounds-check twin facts (A/B = ELF x86 twins, normally A unchecked, B checked) -> {field: answer string}; None
    when the inputs aren't x86 ELF twins. Fields (first differing changed function; "<field>:<function>" for each):
    bounds_check_twin ("a"/"b"/"none" = which twin carries more checks; aliases checked_twin / added_check_twin),
    bounds_check_added (B adds), bounds_check_function, bounds_check_kind (manual_compare / ubsan /
    rust_panic_bounds_check / rust_slice_index_fail / go_panic_index / go_panic_slice / go_panic_bounds /
    swift_index_out_of_range / fortify_chk), bounds_check_language (c/rust/go/swift), bounds_check_sink(s_a/_b),
    bounds_check_calls_a/b, bounds_compares_a/b, bounds_checks_a/b, indexed_accesses_a/b, unchecked_accesses_a/b,
    bounds_limit (guard immediate) / bounds_check_jcc / buffer_length (limit+1 for ja/jbe/jg/jle, else limit; else the
    Rust len / FORTIFY object-size argument; else object size / scale), buffer_object / buffer_object_size,
    access_scale, frame_size_a/b; _before/_after, _vulnerable/_fixed alias every _a/_b."""
    try:
        return _bounds_check_facts(bytes(a), bytes(b))
    except Exception:   # noqa: BLE001 -- malformed / decoy input: no answer
        return None


def _bounds_check_facts(a, b):
    d = _native_patch_diff(a, b)
    if d is None:
        return None
    f = {"bounds_check_twin": "none", "bounds_check_added": "false", "bounds_check_function": "none",
         "bounds_check_kind": "none"}
    names = json.loads(d["changed_functions"]) if d.get("changed_functions", "[]") != "[]" else []
    if not names:
        return _bck_alias(f)
    ia, ib = _npd_elf(a), _npd_elf(b)
    fna, fnb = ({x[0]: x[2] for x in i["funcs"]} for i in (ia, ib))
    first = True
    for nm_ in names:
        aa, ab = (int(d.get(f"changed_function_address_{s}:{nm_}", "-1"), 16) for s in "ab")
        xa = next((x for x in ia["funcs"] if x[0] == aa), None)
        xb = next((x for x in ib["funcs"] if x[0] == ab), None)
        if not xa or not xb:
            continue
        ra, rb = _bck_func(ia, xa, fna), _bck_func(ib, xb, fnb)
        pre = {}
        for s, r in (("a", ra), ("b", rb)):
            pre[f"bounds_check_calls_{s}"] = len(r["sinks"])
            pre[f"bounds_compares_{s}"] = len(r["guards"])
            pre[f"bounds_checks_{s}"] = len(r["sinks"]) + len(r["guards"])
            pre[f"indexed_accesses_{s}"] = len(r["acc"])
            pre[f"unchecked_accesses_{s}"] = sum(1 for x in r["acc"] if not x["guarded"])
            pre[f"bounds_check_sinks_{s}"] = _jv(list(dict.fromkeys(x[1] for x in r["sinks"])))
            pre[f"frame_size_{s}"] = "none" if r["frame"] is None else r["frame"]
        ca, cb = pre["bounds_checks_a"], pre["bounds_checks_b"]
        if ca == cb and pre["unchecked_accesses_a"] != pre["unchecked_accesses_b"]:
            ca, cb = -pre["unchecked_accesses_a"], -pre["unchecked_accesses_b"]
        twin = "b" if cb > ca else "a" if ca > cb else "none"
        chk, unc = (rb, ra) if twin != "a" else (ra, rb)
        new_s = [x for x in chk["sinks"] if (x[0], x[1]) not in {(y[0], y[1]) for y in unc["sinks"]}] or chk["sinks"]
        new_g = [x for x in chk["guards"] if x not in unc["guards"]] or chk["guards"]
        kind = new_s[0][0] if new_s and twin != "none" else "manual_compare" if new_g and twin != "none" else "none"
        lang = _BCK_LANG.get(kind) or (kind.split("_")[0] if kind.startswith(("rust", "go")) else None)
        if not lang:
            allsyms = " ".join(list(img_n for img_n in fnb.values())[:4000])
            lang = "go" if "runtime.gopanic" in allsyms or "runtime.main" in allsyms else \
                "rust" if "_ZN4core" in allsyms or "_RN" in allsyms or "rust_begin_unwind" in allsyms else "c"
        lim = jcc = ln = None
        for op, j in new_g:
            m = re.search(r", (0x[0-9a-f]+|\d+)$", op)
            if m:
                lim, jcc = int(m.group(1), 0), j
                ln = lim + 1 if j in ("ja", "jbe", "jg", "jle") else lim
                break
        if jcc is None and new_g:
            jcc = new_g[0][1]
        if ln is None:
            ln = next((x[2] for x in new_s if x[2] is not None), None)
        ob = next(iter(chk["objs"] or unc["objs"]), None)
        sc = next((x["scale"] for x in chk["acc"] or unc["acc"]), None)
        if ln is None and ob and ob[1] and sc:
            ln = ob[1] // sc
        pre.update({"bounds_check_twin": twin, "checked_twin": twin, "added_check_twin": twin,
                    "bounds_check_added": str(twin == "b").lower(), "bounds_check_function": nm_,
                    "bounds_check_kind": kind, "bounds_check_language": lang,
                    "bounds_check_sink": new_s[0][1] if new_s and twin != "none" else "none",
                    "bounds_limit": "none" if lim is None else lim, "bounds_limit_hex": "none" if lim is None
                    else hex(lim), "bounds_check_jcc": jcc or "none", "buffer_length": "none" if ln is None else ln,
                    "buffer_object": ob[0] if ob else "none", "buffer_object_size": ob[1] if ob else "none",
                    "access_scale": "none" if sc is None else sc})
        pre = {k: str(v) for k, v in pre.items()}
        for k, v in pre.items():
            f[f"{k}:{nm_}"] = v
        if first and (twin != "none" or nm_ == names[-1]):
            f.update(pre)
            first = False
    return _bck_alias(f)


def _bck_alias(f):
    for k in [k for k in f if k.endswith(("_a", "_b")) and ":" not in k]:
        base, s = k[:-2], k[-1]
        for al in (("_before", "_after"), ("_vulnerable", "_fixed"), ("_unchecked", "_checked")):
            f[base + al[s == "b"]] = f[k]
    return f


def bounds_check_field(a, b, field):
    """One bounds_check_facts fact; "none" when absent, None when the inputs aren't x86 ELF twins."""
    f = bounds_check_facts(a, b)
    return None if f is None else f.get(field, "none")


# --- Vulnerability class of a twin-build fix (CWE token + snake_case name) ------------------------------------------
# Rule table over the jvm_patch_diff / native_patch_diff facts (A = vulnerable, B = fixed). The GM spelling is
# UNKNOWN (D24 fixture = CWE-476 null guard): answer "CWE-<n>" / "<n>" / the snake_case name, or hand an enum's
# accepted_values to vuln_class_pick(). Unclassifiable fix -> None (the worker answers), unchanged twins -> "none".
_VC_NAMES = {
    476: ("null_pointer_dereference", "null_dereference", "null_deref", "null_pointer", "null_pointer_deref", "npd"),
    125: ("out_of_bounds_read", "oob_read", "buffer_over_read", "buffer_overread", "out_of_bounds_access"),
    787: ("out_of_bounds_write", "oob_write", "buffer_overflow", "stack_buffer_overflow", "heap_buffer_overflow",
          "buffer_overrun", "classic_buffer_overflow", "buffer_copy_without_checking_size"),
    193: ("off_by_one", "off_by_one_error"),
    190: ("integer_overflow", "integer_overflow_or_wraparound", "int_overflow", "integer_wraparound", "arithmetic_overflow"),
    195: ("signedness_error", "signed_to_unsigned_conversion_error", "signedness", "signed_unsigned_mismatch",
          "integer_signedness", "sign_conversion"),
    134: ("format_string", "use_of_externally_controlled_format_string", "format_string_vulnerability",
          "uncontrolled_format_string", "format_string_injection"),
    416: ("use_after_free", "uaf", "dangling_pointer"),
    415: ("double_free",),
    369: ("divide_by_zero", "division_by_zero", "div_by_zero", "divide_by_zero_error"),
    252: ("unchecked_return_value", "unchecked_return", "unchecked_error_condition"),
    367: ("toctou", "toctou_race_condition", "time_of_check_time_of_use", "race_condition"),
    78: ("command_injection", "os_command_injection", "shell_injection"),
    89: ("sql_injection", "sqli"),
    22: ("path_traversal", "directory_traversal"),
    502: ("unsafe_deserialization", "deserialization_of_untrusted_data", "insecure_deserialization"),
    248: ("uncaught_exception", "unhandled_exception", "improper_exception_handling"),
    338: ("weak_prng", "use_of_cryptographically_weak_prng", "insecure_randomness"),
    377: ("insecure_temporary_file", "insecure_temp_file"),
    457: ("use_of_uninitialized_variable", "uninitialized_variable", "uninitialised_variable", "uninitialized_read",
          "uninitialised_read", "uninitialized_value", "uninit_read", "uninitialized_variable_use"),
    908: ("use_of_uninitialized_resource", "uninitialized_memory", "uninitialised_memory", "uninitialized_buffer",
          "uninitialized_memory_read"),
}
_VC_MEMO = []
_VC_JLOAD = {"iaload", "baload", "caload", "saload", "laload", "faload", "daload", "aaload"}
_VC_JSTORE = {"iastore", "bastore", "castore", "sastore", "lastore", "fastore", "dastore", "aastore"}
_VC_CPY = re.compile(r"^(mem(cpy|move|set)|str(n?cpy|n?cat|lcpy|lcat)|stpn?cpy|w?mem\w*|v?sn?printf|gets|fgets|read|"
                     r"recv\w*|fread|scanf|sscanf|fscanf|wcs\w*cpy)$")
_VC_ZT = re.compile(r"^(?:test (\w+), \1|cmp (\w+|(?:byte|word|dword|qword) ptr \[[^\]]*\]), 0)$")


def _vc_list(f, k):
    try:
        v = json.loads(f.get(k) or "[]")
        return v if isinstance(v, list) else []
    except ValueError:
        return []


def _vc_w32(opnd):
    """Width of a zero-tested operand: True for 32-bit (int: divisor/flag), False for 64-bit (pointer)."""
    return bool(re.fullmatch(r"e\w\w|r\d+d|dword ptr .*|[a-d]l|[sd]il|r\d+b|byte ptr .*|word ptr .*|\w\w", opnd))


def _vc_native(f):
    rem, add = _vc_list(f, "removed_instructions"), _vc_list(f, "added_instructions")
    ca, cb = _vc_list(f, "calls_a"), _vc_list(f, "calls_b")
    rc, ac = _vc_list(f, "removed_calls"), _vc_list(f, "added_calls")
    ma, mb = set(_vc_list(f, "mnemonics_a")), set(_vc_list(f, "mnemonics_b"))
    fk, repl = f.get("fix_kind"), _vc_list(f, "replaced_calls")
    zt = [m.group(1) or m.group(2) for m in (_VC_ZT.match(t) for t in add) if m]
    free_rm = sum("imp:free" in t for t in rem) - sum("imp:free" in t for t in add)
    if any(c in ("access", "faccessat", "stat", "lstat", "__xstat", "__lxstat", "stat64") for c in rc) \
            and any(re.match(r"^(f?open(at)?(64)?|creat|unlink|rename|chmod|chown)$", c) for c in ca):
        return 367, "check-then-use call removed"
    unsafe = repl[0].split("->")[0] if fk == "replaced_unsafe_call" and repl else ""
    if unsafe in ("system", "popen") or any(c in ("system", "popen") for c in rc) and \
            any(re.match(r"^(execv\w*|execl\w*|posix_spawnp?|fork)$", c) for c in ac):
        return 78, "shell call replaced"
    if any(c in ("system", "popen") for c in ca + cb) and any(re.match(r"^(strpbrk|strcspn|strspn|strchr|isalnum|"
                                                                      r"isalpha|isdigit|__ctype_b_loc)$", c) for c in ac):
        return 78, "shell argument sanitised"
    if any(re.match(r"^(sqlite3_exec|mysql_(real_)?query|PQexec)$", c) for c in rc) or \
            any(re.match(r"^(sqlite3_(prepare\w*|bind_\w+)|mysql_stmt_\w+|PQexecParams|PQprepare)$", c) for c in ac):
        return 89, "query built by string -> prepared/bound"
    if unsafe in ("rand", "srand", "random"):
        return 338, "weak PRNG replaced"
    if unsafe in ("tmpnam", "mktemp", "tempnam"):
        return 377, "temp-name call replaced"
    if unsafe:
        return 787, f"unbounded {unsafe} replaced"
    if any(c in ("realpath", "canonicalize_file_name", "basename", "__xpg_basename") for c in ac) or \
            any("str:" in t and re.search(r"\"[^\"]*\.\.[/\\\\]?[^\"]*\"", t) for t in add):
        return 22, "path canonicalised / '..' rejected"
    if fk == "null_after_free":
        return (415, "second free removed") if free_rm > 0 else (416, "pointer nulled after free")
    if free_rm > 0 and fk != "null_check":
        return 415, "free removed"
    if any("imp:free" in t for t in rem) and any("imp:free" in t for t in add):
        return 416, "free moved after the last use"
    if fk == "format_string":
        return 134, "format literal added"
    if (mb - ma) & {"jo", "jno", "seto", "setno", "jc", "setc", "setb"} or \
            any(re.match(r"^__(add|sub|mul|neg)v[sdt]i3$|^__builtin_\w+_overflow$|^__mulodi4$", c) for c in ac):
        return 190, "overflow flag test added"
    if ma & {"div", "idiv"} and any(_vc_w32(z) for z in zt):
        return 369, "divisor zero test added"
    if fk == "null_check" and zt and all(_vc_w32(z) for z in zt) and \
            any(re.match(r"^(set[ug]id|sete[ug]id|setres[ug]id|read|write|recv|send|chdir|chroot|fread|fwrite|fseek|"
                         r"mkdir|pthread_mutex_lock|seteuid|setgroups|close)$", c) for c in ca):
        return 252, "return value now tested"
    if fk == "null_check":
        return 476, "null test added"
    if fk == "signedness":
        return 195, "signed -> unsigned compare"
    if fk == "off_by_one":
        return 193, "comparison/limit tightened by one"
    if fk == "bounds_check":
        if any(_VC_CPY.match(c) for c in ca) or f.get("_st_a"):
            return 787, "bounds check before a write"
        return 125, "bounds check before a read"
    nj = lambda xs: [t for t in xs if not re.match(r"^j\w+ L\d+$", t)]   # noqa: E731 -- drop relabelled jumps
    if fk == "logic_change" and not nj(rem) and nj(add):
        if all(re.match(r"^mov (byte|word|dword|qword) ptr \[[re][bs]p [-+] 0x\w+\], 0$", t) for t in nj(add)):
            return 457, "stack variable now zero-initialised"
        if any(c in ("memset", "bzero", "explicit_bzero") for c in ac) or "stosq" in mb - ma or "stosd" in mb - ma:
            return 908, "buffer now cleared before use"
    sj = {"jl", "jle", "jg", "jge", "setl", "setle", "setg", "setge", "cmovl", "cmovle", "cmovg", "cmovge"}
    uj = {"jb", "jbe", "ja", "jae", "setb", "setbe", "seta", "setae", "cmovb", "cmovbe", "cmova", "cmovae"}
    ci = lambda xs: {m.group(1) for m in (re.match(r"^cmp .*, (0x\w+|\d+)$", t) for t in xs) if m}   # noqa: E731
    if fk == "logic_change" and any(t.split()[0] in sj for t in rem) and any(t.split()[0] in uj for t in add) and \
            not any(t.split()[0] in uj for t in rem) and ci(rem) & ci(add):
        return 195, "signed -> unsigned compare"
    if f.get("_uaf_a") and not f.get("_uaf_b"):
        return 416, "freed pointer no longer used after free"
    if fk == "frame_size_change" and f.get("frame_size_b", "none") != "none" and \
            int(f.get("frame_size_b")) > int(f.get("frame_size_a") if f.get("frame_size_a", "none") != "none" else 0):
        return 787, "buffer enlarged"
    return None, "unclassified " + str(fk)


def _vc_jvm(f):
    ia, ib = _vc_list(f, "invokes_a"), _vc_list(f, "invokes_b")
    ai, ri = _vc_list(f, "added_invokes"), _vc_list(f, "removed_invokes")
    sig = _vc_list(f, "added_invoke_signatures")
    oa, ob = set(_vc_list(f, "opcodes_a")), set(_vc_list(f, "opcodes_b"))
    ao, ro = set(_vc_list(f, "added_opcodes")), set(_vc_list(f, "removed_opcodes"))
    am = _vc_list(f, "added_method_names")
    exc = [x for x in _vc_list(f, "catch_types_b") if x not in _vc_list(f, "catch_types_a")]
    fk = f.get("fix_kind")
    has = lambda xs, rx: any(re.search(rx, x) for x in xs)   # noqa: E731
    if has(ia + ib, r"ObjectInputStream\.readObject|XMLDecoder\.readObject|readUnshared") and (
            has(ai, r"ObjectInputFilter|setObjectInputFilter|resolveClass|ValidatingObjectInputStream|Filter\.") or
            "resolveClass" in am or has(ri, r"\.readObject$|readUnshared$")):
        return 502, "deserialization filtered"
    if has(ri, r"Statement\.(execute\w*)$|Connection\.createStatement$") and \
            has(ai, r"prepareStatement$|PreparedStatement\.set\w+$|PreparedStatement\.execute\w*$"):
        return 89, "string query -> PreparedStatement"
    if has(ia + ib, r"Runtime\.exec$|ProcessBuilder\.(<init>|command|start)$") and (
            has(sig, r"Runtime\.exec:\(\[Ljava/lang/String;") or has(ri, r"Runtime\.exec$") and
            has(ai, r"ProcessBuilder") or
            has(ai, r"String\.(matches|contains|indexOf|replace\w*|chars)$|Pattern\.|Matcher\.|Character\.is")):
        return 78, "command argument sanitised"
    if has(ai, r"File\.getCanonical(Path|File)$|Path\.(normalize|toRealPath|startsWith)$|FilenameUtils\.normalize|"
               r"Paths?\.get.*normalize"):
        return 22, "path canonicalised"
    if has(ri, r"File\.(exists|canRead|canWrite|isFile|isDirectory)$") and \
            has(ia + ib, r"File(Input|Output)Stream\.<init>|Files\.new|RandomAccessFile"):
        return 367, "check-then-use removed"
    if has(ai, r"(Math|StrictMath)\.(add|subtract|multiply|increment|decrement|negate|to)\w*Exact$"):
        return 190, "exact arithmetic"
    if has(ai, r"(Integer|Long)\.(compareUnsigned|toUnsigned\w+|divideUnsigned|remainderUnsigned)$|"
               r"(Byte|Short)\.toUnsigned\w+$"):
        return 195, "unsigned conversion"
    if any(re.search(r"NullPointerException$", x) for x in exc):
        return 476, "NPE caught"
    if any(re.search(r"IndexOutOfBounds\w*$", x) for x in exc):
        return 125, "index exception caught"
    if any(re.search(r"ArithmeticException$", x) for x in exc):
        return 369, "ArithmeticException caught"
    if oa & {"idiv", "irem", "ldiv", "lrem"} and (ao & {"ifeq", "ifne", "lcmp"} or fk == "logic_change"
                                                  and ob & {"ifeq", "ifne"}) and "ifnull" not in ao:
        return 369, "divisor zero test added"
    if fk == "null_guard":
        return 476, "null guard added"
    swaps = {("if_icmpgt", "if_icmpge"), ("if_icmpge", "if_icmpgt"), ("if_icmplt", "if_icmple"),
             ("if_icmple", "if_icmplt"), ("ifgt", "ifge"), ("ifge", "ifgt"), ("iflt", "ifle"), ("ifle", "iflt")}
    if len(ao) == len(ro) == 1 and (next(iter(ro)), next(iter(ao))) in swaps:
        return 193, "relational branch tightened by one"
    if fk in ("bounds_check", "length_check", "exception_handler"):
        if oa & _VC_JSTORE or has(ia, r"System\.arraycopy$|Arrays\.fill$|\.put$|\.set$|\.setCharAt$"):
            return 787, "bounds check before a write"
        if oa & _VC_JLOAD or has(ia, r"\.(charAt|codePointAt|substring|get|apply|getBytes)$") or \
                any(re.search(r"IndexOutOfBounds", x) for x in exc):
            return 125, "bounds check before a read"
    if fk == "exception_handler" and exc:
        return 248, "exception now caught"
    return None, "unclassified " + str(fk)


def vuln_class_from_facts(f, platform=None):
    """(cwe int | None, evidence) from a jvm_patch_diff / native_patch_diff fact dict."""
    if not f:
        return None, "no facts"
    plat = platform or ("jvm" if "role_a" in f else "native")
    return (_vc_jvm if plat == "jvm" else _vc_native)(f)



def patch_vuln_class(a, b):
    """Twin builds (A = vulnerable, B = fixed: jars/.class or x86 ELF) -> {field: answer}; None when neither diff
    parses. Fields: cwe / cwe_id / cwe_token ("CWE-476"), cwe_number ("476"), vulnerability_class / vuln_class /
    bug_class / cwe_name / class_name ("null_pointer_dereference"), cwe_with_name ("CWE-476: null_pointer_dereference"),
    cwe_aliases (JSON), platform, fix_kind, changed_function, evidence. Unchanged twins -> "none"; unclassifiable fix -> field absent."""
    a, b = bytes(a), bytes(b)
    if _VC_MEMO and _VC_MEMO[0] == a and _VC_MEMO[1] == b:   # several fields of one pair: diff once
        return _VC_MEMO[2]
    try:
        r = _patch_vuln_class(a, b)
    except Exception:   # noqa: BLE001 -- malformed / decoy input: no answer
        r = None
    _VC_MEMO[:] = [a, b, r]
    return r


def _vc_indexed_store(body):
    for t, mn, op in body:
        if mn.startswith(("mov", "stos")) and ", " in op:
            dst = op.split(", ")[0]
            m = re.search(r"ptr \[([^\]]*)\]", dst)
            if m and "rip" not in m.group(1):
                regs = [x.strip() for x in re.split(r"[+-]", m.group(1)) if re.match(r"^[a-z]\w*(\*\d)?$", x.strip())]
                if len(regs) >= 2 or any("*" in x for x in regs):
                    return True
    return False


def _vc_uaf(body):
    """-O0 shape: a stack slot's pointer goes to free(), later the slot is reloaded and dereferenced (no reassign)."""
    freed, reg, last = set(), {}, None
    for k, (t, mn, op) in enumerate(body):
        m = re.match(r"^mov (\w+), qword ptr (\[[re][bs]p [-+] [\w]+\])$", t)
        if m:
            reg[m.group(1)] = m.group(2)
            if m.group(2) in freed and any(re.search(rf"ptr \[{m.group(1)}\b", x[0]) and not x[0].startswith("lea")
                                           for x in body[k + 1:k + 4]):
                return True
            continue
        m = re.match(r"^mov (\w+), (\w+)$", t)
        if m:
            if m.group(1) == "rdi":
                last = reg.get(m.group(2))
            reg.pop(m.group(1), None)
            continue
        m = re.match(r"^mov qword ptr (\[[re][bs]p [-+] [\w]+\]), ", t)
        if m:
            freed.discard(m.group(1))
            continue
        if t == "call imp:free" and last:
            freed.add(last)
        if mn == "call":
            reg, last = {}, None
    return False


def _patch_vuln_class(a, b):
    f, plat = None, None
    if a[:4] == b"\x7fELF" and b[:4] == b"\x7fELF":
        f, plat = _native_patch_diff(a, b), "native"
        if f and f.get("fix_kind") == "logic_change" and f.get("changed_function", "none") != "none":
            bodies = []
            for blob, key in ((a, "changed_function_address"), (b, "changed_function_address_b")):
                im = _npd_elf(blob)
                fn = next((x for x in im["funcs"] if x[2] == f["changed_function"] and hex(x[0]) == f.get(key)),
                          None) if im else None
                bodies.append(_vc_uaf(_npd_body(im, fn, {x[0]: x[2] for x in im["funcs"]})) if fn else False)
            f = dict(f, _uaf_a=bodies[0], _uaf_b=bodies[1])
        if f and f.get("fix_kind") == "bounds_check" and f.get("changed_function", "none") != "none":
            ia = _npd_elf(a)
            fn = next((x for x in ia["funcs"] if x[2] == f["changed_function"] and
                       hex(x[0]) == f.get("changed_function_address")), None) if ia else None
            if fn:
                nm_ = {x[0]: x[2] for x in ia["funcs"]} if all(x[3] for x in ia["funcs"]) else \
                    {x[0]: "?" for x in ia["funcs"]}
                f = dict(f, _st_a=_vc_indexed_store(_npd_body(ia, fn, nm_)))
    else:
        f, plat = _jvm_patch_diff(a, b), "jvm"
    if not f:
        return None
    out = {"platform": plat, "fix_kind": f.get("fix_kind", "none"),
           "changed_function": f.get("changed_function", "none")}
    if f.get("fix_kind") in (None, "none"):
        return dict(out, **{k: "none" for k in ("cwe", "cwe_id", "cwe_token", "cwe_number", "vulnerability_class",
                                                "vuln_class", "bug_class", "cwe_name", "class_name", "cwe_with_name")})
    n, ev = vuln_class_from_facts(f, plat)
    out["evidence"] = ev
    if n is None:
        return out
    name = _VC_NAMES[n][0]
    out.update({"cwe": f"CWE-{n}", "cwe_id": f"CWE-{n}", "cwe_token": f"CWE-{n}", "cwe_number": str(n),
                "vulnerability_class": name, "vuln_class": name, "bug_class": name, "cwe_name": name,
                "class_name": name, "cwe_with_name": f"CWE-{n}: {name}", "cwe_aliases": _jv(list(_VC_NAMES[n]))})
    return out


def patch_vuln_class_field(a, b, field):
    """One patch_vuln_class fact; "none" when absent, None when the inputs aren't comparable twins."""
    f = patch_vuln_class(a, b)
    return None if f is None else f.get(field, "none")


def vuln_class_pick(cwe, accepted_values):
    """Map a CWE (int / "CWE-476" / snake name) onto a GM enum's accepted_values spelling; None when no value fits."""
    m = re.search(r"\d+", str(cwe))
    n = int(m.group()) if m else next((k for k, v in _VC_NAMES.items() if str(cwe) in v), None)
    if n is None:
        return None
    norm = lambda s: re.sub(r"[^a-z0-9]+", "_", str(s).lower()).strip("_")   # noqa: E731
    vals = list(accepted_values or ())
    for v in vals:
        if re.search(rf"(?<!\d){n}(?!\d)", str(v)) and re.search(r"cwe|^\W*\d+\W*$", str(v), re.I):
            return v
    al = _VC_NAMES.get(n, ())
    for v in vals:
        if norm(v) in al:
            return v
    for v in vals:
        if any(x in norm(v) or norm(v) in x for x in al if len(norm(v)) > 3):
            return v
    return None


# --- JVM trigger proof: tiny bytecode evaluator over the changed method of twin builds -------------------------
class _JtThrow(Exception):
    def __init__(self, cls):
        super().__init__(cls)
        self.cls = cls


class _JtUnk(Exception):
    pass


class _JtObj:
    def __init__(self, cls):
        self.cls, self.f = cls, {}


class _JtArr(list):
    pass


class _JtOpt:   # scala.Option / java.util.Optional (v is the payload; empty when not some)
    def __init__(self, v, some):
        self.v, self.some = v, some


class _JtLam:
    def __init__(self, kind, owner, name, desc, cap):
        self.kind, self.owner, self.name, self.desc, self.cap = kind, owner, name, desc, cap


_JT_NPE, _JT_SIOOBE, _JT_AIOOBE = ("java/lang/NullPointerException", "java/lang/StringIndexOutOfBoundsException",
                                   "java/lang/ArrayIndexOutOfBoundsException")
_JT_SUPER = {_JT_NPE: "java/lang/RuntimeException", _JT_SIOOBE: "java/lang/IndexOutOfBoundsException",
             _JT_AIOOBE: "java/lang/IndexOutOfBoundsException",
             "java/lang/IndexOutOfBoundsException": "java/lang/RuntimeException",
             "java/lang/ArithmeticException": "java/lang/RuntimeException",
             "java/lang/NumberFormatException": "java/lang/IllegalArgumentException",
             "java/lang/IllegalArgumentException": "java/lang/RuntimeException",
             "java/lang/IllegalStateException": "java/lang/RuntimeException",
             "java/util/NoSuchElementException": "java/lang/RuntimeException",
             "java/lang/NegativeArraySizeException": "java/lang/RuntimeException",
             "java/lang/ClassCastException": "java/lang/RuntimeException",
             "java/lang/UnsupportedOperationException": "java/lang/RuntimeException",
             "java/lang/RuntimeException": "java/lang/Exception", "java/lang/Exception": "java/lang/Throwable",
             "java/lang/Error": "java/lang/Throwable"}
_JT_PARAM = re.compile(r"\[*(?:L[^;]+;|[BCDFIJSZ])")
_JT_I32 = lambda v: ((v + (1 << 31)) & 0xffffffff) - (1 << 31)   # noqa: E731
_JT_I64 = lambda v: ((v + (1 << 63)) & ((1 << 64) - 1)) - (1 << 63)   # noqa: E731


def _jt_isa(cls, want):
    while cls:
        if cls == want:
            return True
        cls = _JT_SUPER.get(cls)
    return False


def _jt_str(v, t="L"):
    if v is None:
        return "null"
    if isinstance(v, str):
        return v
    if t == "C":
        return chr(v & 0xffff)
    if t == "Z":
        return "true" if v else "false"
    if isinstance(v, _JtOpt):
        return f"Some({_jt_str(v.v)})" if v.some else "None"
    if isinstance(v, (int, float)):
        return str(v)
    raise _JtUnk("tostr")


def _jt_parse_int(s, lo=-(1 << 31), hi=(1 << 31) - 1):
    if s is None or not re.fullmatch(r"[+-]?[0-9]+", s) or not lo <= int(s) <= hi:
        raise _JtThrow("java/lang/NumberFormatException")
    return int(s)


def _jt_jhash(s):
    h = 0
    for ch in s.encode("utf-16-be").decode("utf-16-be"):
        h = (31 * h + ord(ch)) & 0xffffffff
    return _JT_I32(h)


class _JtVm:
    def __init__(self, classes, budget=20000, deadline=None):
        self.classes, self.statics, self.inited = classes, {}, set()
        self.steps, self.deadline = budget, deadline

    def method(self, cls, name, desc):
        seen = 0
        while cls in self.classes and seen < 16:
            p = self.classes[cls]
            for m in p["methods"]:
                if m["name"] == name and (desc is None or m["descriptor"] == desc):
                    return cls, p, m
            cls, seen = p.get("super"), seen + 1
        return None

    def clinit(self, cls):
        if cls in self.inited or cls not in self.classes:
            return
        self.inited.add(cls)
        if self.method(cls, "<clinit>", "()V"):
            try:
                self.run(cls, "<clinit>", "()V", [], depth=1)
            except _JtThrow:
                pass

    def call_lam(self, lam, args):
        a = list(lam.cap) + list(args)
        if lam.kind == 8:   # newInvokeSpecial
            o = _JtObj(lam.owner)
            self.invoke("special", lam.owner, "<init>", lam.desc, o, a, 1)
            return o
        if lam.kind == 6:
            return self.invoke("static", lam.owner, lam.name, lam.desc, None, a, 1)
        if not a:
            raise _JtUnk("lam recv")
        return self.invoke("virtual", lam.owner, lam.name, lam.desc, a[0], a[1:], 1)

    def invoke(self, kind, owner, name, desc, recv, args, depth):
        if kind != "static":
            if recv is None:
                raise _JtThrow(_JT_NPE)
            if isinstance(recv, _JtLam) and name not in ("equals", "hashCode", "toString", "getClass"):
                return self.call_lam(recv, args)
            tgt = recv.cls if kind != "special" and isinstance(recv, _JtObj) and recv.cls in self.classes else owner
            hit = self.method(tgt, name, desc) or (self.method(owner, name, desc) if tgt != owner else None)
        else:
            hit = self.method(owner, name, desc)
        if hit and any(n == "Code" for n, _ in hit[2]["attributes"]):
            if name == "<init>" or kind == "static":
                self.clinit(hit[0])
            return self.run(hit[0], name, desc, ([] if kind == "static" else [recv]) + list(args), depth + 1)
        return _jt_stub(self, owner, name, desc, recv, args)

    def run(self, cls, name, desc, args, depth=0):
        if depth > 40:
            raise _JtUnk("depth")
        hit = self.method(cls, name, desc)
        if not hit:
            raise _JtUnk("no method")
        _, p, m = hit
        raw = next((b for n, b in m["attributes"] if n == "Code"), None)
        if not raw:
            raise _JtUnk("no code")
        mstack, mloc, ln = struct.unpack_from(">HHI", raw, 0)
        code = raw[8:8 + ln]
        key = (cls, name, desc)
        ins = p.setdefault("_jt_code", {}).get(key)
        if ins is None:
            ins = jvm_code_decode(code)
            p["_jt_code"][key] = ins
        idx = {pc: k for k, (pc, _, _) in enumerate(ins)}
        o, et = 8 + ln, []
        for k in range(struct.unpack_from(">H", raw, o)[0] if o + 2 <= len(raw) else 0):
            s, e_, h, ct = struct.unpack_from(">HHHH", raw, o + 2 + 8 * k)
            et.append((s, e_, h, p["_cname"](ct) if ct else None))
        loc = [None] * max(mloc, 1)
        j = 0
        for v, t in zip(args, (["L"] if len(args) > len(_JT_PARAM.findall(desc.split(")")[0])) else [])
                        + _JT_PARAM.findall(desc.split(")")[0])):
            if j < len(loc):
                loc[j] = v
            j += 2 if t in ("J", "D") else 1
        rtype = desc.split(")")[1]
        st, k = [], 0
        cp, u, cname = p["cp"], p["_u"], p["_cname"]
        while True:
            self.steps -= 1
            if self.steps < 0 or (self.deadline and not self.steps % 512 and time.monotonic() > self.deadline):
                raise _JtUnk("budget")
            if not 0 <= k < len(ins):
                raise _JtUnk("pc")
            pc, op, arg = ins[k]
            try:
                r = self.step(p, cp, u, cname, pc, op, arg, st, loc, idx, depth)
            except _JtThrow as ex:
                h = next((hh for s, e_, hh, ct in et if s <= pc < e_ and (ct is None or _jt_isa(ex.cls, ct))), None)
                if h is None:
                    raise
                st[:] = [_JtObj(ex.cls)]
                k = idx[h]
                continue
            if r is None:
                k += 1
            elif r[0] == "jmp":
                k = idx[r[1]]
            else:
                return r[1] if rtype != "V" else None

    def ref(self, cp, u, cname, i):
        e = cp[i]
        nt = cp[e[1][1]]
        return cname(e[1][0]), u(nt[1][0]), u(nt[1][1])

    def step(self, p, cp, u, cname, pc, op, arg, st, loc, idx, depth):
        mn = _JOPS[op]
        pop, push = st.pop, st.append
        if mn == "nop" or mn == "checkcast":
            return None
        if mn == "aconst_null":
            push(None)
        elif mn.startswith(("iconst_", "lconst_")):
            push(-1 if mn.endswith("m1") else int(mn[-1]))
        elif mn in ("bipush", "sipush"):
            push(arg[0])
        elif mn in ("ldc", "ldc_w", "ldc2_w"):
            t, v = cp[arg[0]]
            if t == 8:
                push(u(v))
            elif t in (3, 4, 5, 6):
                push(v)
            else:
                raise _JtUnk("ldc")
        elif mn[1:5] == "load" and len(mn) <= 7 and mn[0] in "ilfda":
            push(loc[int(mn[-1]) if "_" in mn else arg[0]])
        elif mn[1:6] == "store" and len(mn) <= 8 and mn[0] in "ilfda":
            loc[int(mn[-1]) if "_" in mn else arg[0]] = pop()
        elif mn == "iinc":
            loc[arg[0]] = _JT_I32(loc[arg[0]] + arg[1])
        elif mn in ("pop",):
            pop()
        elif mn == "dup":
            push(st[-1])
        elif mn == "dup_x1":
            st.insert(-2, st[-1])
        elif mn == "swap":
            st[-1], st[-2] = st[-2], st[-1]
        elif mn[0] in "il" and mn[1:] in ("add", "sub", "mul", "div", "rem", "and", "or", "xor", "shl", "shr", "ushr"):
            b, a = pop(), pop()
            w, bits = (_JT_I32, 32) if mn[0] == "i" else (_JT_I64, 64)
            op_ = mn[1:]
            if op_ in ("div", "rem") and b == 0:
                raise _JtThrow("java/lang/ArithmeticException")
            if op_ == "div":
                r = abs(a) // abs(b) * (1 if (a < 0) == (b < 0) else -1)
            elif op_ == "rem":
                r = a - (abs(a) // abs(b) * (1 if (a < 0) == (b < 0) else -1)) * b
            elif op_ in ("shl", "shr", "ushr"):
                s = b & (bits - 1)
                r = a << s if op_ == "shl" else a >> s if op_ == "shr" else (a & ((1 << bits) - 1)) >> s
            else:
                r = {"add": a + b, "sub": a - b, "mul": a * b, "and": a & b, "or": a | b, "xor": a ^ b}[op_]
            push(w(r))
        elif mn in ("ineg", "lneg"):
            push((_JT_I32 if mn[0] == "i" else _JT_I64)(-pop()))
        elif mn in ("i2l", "l2i", "i2c", "i2b", "i2s"):
            v = pop()
            push(v if mn == "i2l" else _JT_I32(v) if mn == "l2i" else v & 0xffff if mn == "i2c"
                 else ((v + 128) & 0xff) - 128 if mn == "i2b" else ((v + 32768) & 0xffff) - 32768)
        elif mn == "lcmp":
            b, a = pop(), pop()
            push((a > b) - (a < b))
        elif mn in ("ifeq", "ifne", "iflt", "ifge", "ifgt", "ifle"):
            v = pop()
            if isinstance(v, bool):
                v = int(v)
            if not isinstance(v, int):
                raise _JtUnk("if on ref")
            if {"ifeq": v == 0, "ifne": v != 0, "iflt": v < 0, "ifge": v >= 0, "ifgt": v > 0, "ifle": v <= 0}[mn]:
                return "jmp", pc + arg[0]
        elif mn.startswith("if_icmp"):
            b, a = pop(), pop()
            if {"eq": a == b, "ne": a != b, "lt": a < b, "ge": a >= b, "gt": a > b, "le": a <= b}[mn[7:]]:
                return "jmp", pc + arg[0]
        elif mn in ("if_acmpeq", "if_acmpne"):
            b, a = pop(), pop()
            if (a is b) == (mn == "if_acmpeq"):
                return "jmp", pc + arg[0]
        elif mn in ("ifnull", "ifnonnull"):
            if (pop() is None) == (mn == "ifnull"):
                return "jmp", pc + arg[0]
        elif mn in ("goto", "goto_w"):
            return "jmp", pc + arg[0]
        elif mn in ("tableswitch", "lookupswitch"):
            v = pop()
            return "jmp", pc + dict(arg[1]).get(v, arg[0])
        elif mn.endswith("return"):
            return "ret", (pop() if mn != "return" else None)
        elif mn == "athrow":
            v = pop()
            raise _JtThrow(_JT_NPE if v is None else v.cls if isinstance(v, _JtObj) else "java/lang/Throwable")
        elif mn in ("newarray", "anewarray"):
            n = pop()
            if n < 0:
                raise _JtThrow("java/lang/NegativeArraySizeException")
            push(_JtArr([0 if mn == "newarray" else None] * min(n, 1 << 16)))
        elif mn == "arraylength":
            a = pop()
            if a is None:
                raise _JtThrow(_JT_NPE)
            push(len(a))
        elif mn in ("iaload", "laload", "baload", "caload", "saload", "aaload"):
            i, a = pop(), pop()
            if a is None:
                raise _JtThrow(_JT_NPE)
            if not 0 <= i < len(a):
                raise _JtThrow(_JT_AIOOBE)
            push(a[i])
        elif mn in ("iastore", "lastore", "bastore", "castore", "sastore", "aastore"):
            v, i, a = pop(), pop(), pop()
            if a is None:
                raise _JtThrow(_JT_NPE)
            if not 0 <= i < len(a):
                raise _JtThrow(_JT_AIOOBE)
            a[i] = v
        elif mn in ("getstatic", "putstatic"):
            c, n, d = self.ref(cp, u, cname, arg[0])
            if c in self.classes:
                self.clinit(c)
                if mn == "putstatic":
                    self.statics[(c, n)] = pop()
                elif (c, n) in self.statics:
                    push(self.statics[(c, n)])
                elif n == "MODULE$":
                    push(self.statics.setdefault((c, n), _JtObj(c)))
                else:
                    raise _JtUnk("static")
            elif mn == "getstatic" and (n == "MODULE$" or c == "java/lang/System"):
                push(_JtOpt(None, False) if c == "scala/None$" else _JtObj(c))
            else:
                raise _JtUnk("ext static")
        elif mn in ("getfield", "putfield"):
            c, n, d = self.ref(cp, u, cname, arg[0])
            v = pop() if mn == "putfield" else None
            o = pop()
            if o is None:
                raise _JtThrow(_JT_NPE)
            if not isinstance(o, _JtObj):
                raise _JtUnk("field")
            if mn == "putfield":
                o.f[n] = v
            else:
                push(o.f.get(n, None if d[0] in "L[" else 0))
        elif mn == "new":
            push(_JtObj(cname(arg[0])))
        elif mn == "instanceof":
            v, t = pop(), cname(arg[0])
            push(int(v is not None and (t == "java/lang/Object" or (isinstance(v, str) and t in (
                "java/lang/String", "java/lang/CharSequence")) or (isinstance(v, _JtObj) and _jt_isa(v.cls, t)))))
        elif mn.startswith("invoke") and mn != "invokedynamic":
            c, n, d = self.ref(cp, u, cname, arg[0])
            na = len(_JT_PARAM.findall(d.split(")")[0]))
            args = st[len(st) - na:] if na else []
            del st[len(st) - na:]
            kind = mn[6:]
            recv = pop() if kind != "static" else None
            r = self.invoke(kind, c, n, d, recv, args, depth)
            if not d.endswith(")V"):
                push(r)
        elif mn == "invokedynamic":
            push(self.indy(p, cp, u, cname, arg[0], st))
        else:
            raise _JtUnk(mn)
        return None

    def indy(self, p, cp, u, cname, i, st):
        bi, nti = cp[i][1]
        name, d = u(cp[nti][1][0]), u(cp[nti][1][1])
        types = _JT_PARAM.findall(d.split(")")[0])
        cap = st[len(st) - len(types):] if types else []
        del st[len(st) - len(types):]
        braw = p.get("_jt_bsm")
        if braw is None:
            braw = dict(p["attributes"]).get("BootstrapMethods") or b"\0\0"
            bs, o = [], 2
            for _ in range(struct.unpack_from(">H", braw, 0)[0]):
                bm, na = struct.unpack_from(">HH", braw, o)
                bs.append((bm, struct.unpack_from(f">{na}H", braw, o + 4)))
                o += 4 + 2 * na
            p["_jt_bsm"] = braw = bs
        bm, bargs = braw[bi]

        def mh(j):
            e = cp[j]
            if not e or e[0] != 15:
                return None
            kind, r = e[1]
            return (kind, *self.ref(cp, u, cname, r))
        b = mh(bm)
        if b and b[2] == "makeConcatWithConstants":
            recipe = u(cp[bargs[0]][1]) if bargs and cp[bargs[0]][0] == 8 else None
            if recipe is None:
                raise _JtUnk("concat")
            it, out = iter(zip(cap, types)), []
            for ch in recipe:
                if ch == "\1":
                    v, t = next(it)
                    out.append(_jt_str(v, t))
                else:
                    out.append(ch)
            return "".join(out)
        impl = next((mh(a) for a in bargs if cp[a] and cp[a][0] == 15), None)
        if not b or "Metafactory" not in b[1] or not impl:
            raise _JtUnk("indy")
        return _JtLam(impl[0], impl[1], impl[2], impl[3], cap)


def _jt_truthy(v):
    if isinstance(v, (bool, int)):
        return bool(v)
    raise _JtUnk("bool")


def _jt_stub(vm, owner, name, desc, recv, args):
    """Library model: java.lang.String/Integer/Math/Objects/Optional/StringBuilder, scala Predef/StringOps/Option/
    BoxesRunTime. Anything else is unknown (the evaluation is abandoned, never guessed)."""
    a = list(args)
    if name == "<init>":
        if isinstance(recv, _JtObj):
            if recv.cls == "java/lang/StringBuilder":
                recv.f["sb"] = [a[0] if a and isinstance(a[0], str) else ""]
            elif recv.cls == "scala/Some":
                recv.f["v"] = a[0] if a else None
            elif recv.cls not in _JT_SUPER and recv.cls not in vm.classes and recv.cls != "java/lang/Object" \
                    and not recv.cls.endswith(("Exception", "Error")):
                raise _JtUnk("init")
        return None
    if isinstance(recv, str) or (owner == "java/lang/String" and recv is not None):
        s = recv
        if name == "length":
            return len(s)
        if name == "isEmpty":
            return int(not s)
        if name == "isBlank":
            return int(not s.strip())
        if name == "charAt":
            if not 0 <= a[0] < len(s):
                raise _JtThrow(_JT_SIOOBE)
            return ord(s[a[0]])
        if name in ("equals", "contentEquals"):
            return int(isinstance(a[0], str) and a[0] == s)
        if name == "equalsIgnoreCase":
            return int(isinstance(a[0], str) and a[0].lower() == s.lower())
        if name == "hashCode":
            return _jt_jhash(s)
        if name == "substring":
            b, e = a[0], (a[1] if len(a) > 1 else len(s))
            if not 0 <= b <= e <= len(s):
                raise _JtThrow(_JT_SIOOBE)
            return s[b:e]
        if name in ("startsWith", "endsWith", "contains", "indexOf", "concat", "compareTo", "lastIndexOf"):
            if a[0] is None:
                raise _JtThrow(_JT_NPE)
            x = chr(a[0]) if isinstance(a[0], int) else a[0]
            if name == "indexOf":
                return s.find(x, *(a[1:2]))
            if name == "lastIndexOf":
                return s.rfind(x)
            if name == "concat":
                return s + x
            if name == "compareTo":
                d = next((ord(p_) - ord(q) for p_, q in zip(s, x) if p_ != q), len(s) - len(x))
                return d
            return int(getattr(s, {"startsWith": "startswith", "endsWith": "endswith"}.get(name, "__contains__"))(x))
        if name == "trim":
            return s.strip("".join(map(chr, range(33))))
        if name in ("toUpperCase", "toLowerCase"):
            return s.upper() if name == "toUpperCase" else s.lower()
        if name in ("toString", "intern"):
            return s
        if name == "toCharArray":
            return _JtArr(ord(c) for c in s)
        raise _JtUnk(f"String.{name}")
    if owner == "java/lang/String" and recv is None and name == "valueOf":
        return _jt_str(a[0], _JT_PARAM.findall(desc.split(")")[0])[0])
    if owner in ("java/lang/Integer", "java/lang/Long", "java/lang/Short", "java/lang/Byte", "java/lang/Character",
                 "java/lang/Boolean"):
        if name in ("parseInt", "parseLong") or (name == "valueOf" and isinstance(a[0] if a else 0, str)) \
                or a == [] and False:
            return _jt_parse_int(a[0]) if name != "parseLong" else _jt_parse_int(a[0], -(1 << 63), (1 << 63) - 1)
        if name == "valueOf" or name.endswith("Value"):
            if name.endswith("Value") and recv is None:
                raise _JtThrow(_JT_NPE)
            return a[0] if name == "valueOf" else recv
        if name == "isDigit":
            return int(chr(a[0]).isdigit())
        if name == "isLetter":
            return int(chr(a[0]).isalpha())
        if name in ("toUpperCase", "toLowerCase") and isinstance(a[0], int):
            return ord(chr(a[0]).upper() if name == "toUpperCase" else chr(a[0]).lower())
        raise _JtUnk(f"{owner}.{name}")
    if owner == "java/lang/Math" and name in ("abs", "max", "min"):
        w = _JT_I64 if "J" in desc else _JT_I32
        return w(abs(a[0])) if name == "abs" else (max if name == "max" else min)(a[0], a[1])
    if owner == "java/util/Objects":
        if name == "requireNonNull":
            if a[0] is None:
                raise _JtThrow(_JT_NPE)
            return a[0]
        if name in ("isNull", "nonNull"):
            return int((a[0] is None) == (name == "isNull"))
        if name == "equals":
            return int(a[0] is a[1] or (a[0] is not None and a[0] == a[1]))
        raise _JtUnk("Objects")
    if owner == "java/lang/StringBuilder" and isinstance(recv, _JtObj):
        if name == "append":
            recv.f.setdefault("sb", [""]).append(_jt_str(a[0], _JT_PARAM.findall(desc.split(")")[0])[0]))
            return recv
        if name == "toString":
            return "".join(recv.f.get("sb", []))
        if name == "length":
            return len("".join(recv.f.get("sb", [])))
        raise _JtUnk("sb")
    if owner == "java/io/PrintStream":
        return None
    if owner == "scala/Predef$" and name in ("augmentString", "wrapString"):
        return a[0]
    if owner in ("scala/collection/StringOps$", "scala/collection/immutable/StringOps$"):
        s = a[0]
        if s is None:
            raise _JtThrow(_JT_NPE)
        if name in ("nonEmpty$extension", "isEmpty$extension"):
            return int(bool(s) == (name == "nonEmpty$extension"))
        if name in ("size$extension", "length$extension"):
            return len(s)
        if name == "apply$extension":
            if not 0 <= a[1] < len(s):
                raise _JtThrow(_JT_SIOOBE)
            return ord(s[a[1]])
        if name == "head$extension":
            if not s:
                raise _JtThrow("java/util/NoSuchElementException")
            return ord(s[0])
        if name == "toInt$extension":
            return _jt_parse_int(s)
        raise _JtUnk(f"StringOps.{name}")
    if owner == "scala/runtime/BoxesRunTime":
        if name.startswith("boxTo"):
            return a[0]
        if name.startswith("unboxTo"):
            return 0 if a[0] is None else a[0]
        if name == "equals":
            return int(a[0] == a[1])
        raise _JtUnk("Boxes")
    if owner in ("scala/Option$", "java/util/Optional") and recv is None or isinstance(recv, _JtObj) and \
            recv.cls == "scala/Option$":
        if name in ("apply", "ofNullable"):
            return _JtOpt(a[0], a[0] is not None)
        if name == "of":
            if a[0] is None:
                raise _JtThrow(_JT_NPE)
            return _JtOpt(a[0], True)
        if name == "empty":
            return _JtOpt(None, False)
        raise _JtUnk("Option$")
    if isinstance(recv, _JtObj) and recv.cls == "scala/Some":
        recv = _JtOpt(recv.f.get("v"), True)
    if isinstance(recv, _JtOpt):
        o, java = recv, owner.startswith("java/")
        if name in ("isEmpty", "isDefined", "nonEmpty", "isPresent"):
            return int(o.some == (name != "isEmpty"))
        if name == "get":
            if not o.some:
                raise _JtThrow("java/util/NoSuchElementException")
            return o.v
        if name in ("getOrElse", "orElseGet"):
            return o.v if o.some else vm.call_lam(a[0], [])
        if name == "orElse" and java:
            return o.v if o.some else a[0]
        if name == "orNull":
            return o.v if o.some else None
        if name == "orElseThrow":
            if o.some:
                return o.v
            raise _JtThrow("java/util/NoSuchElementException") if not a else _JtThrow(
                getattr(vm.call_lam(a[0], []), "cls", "java/lang/Throwable"))
        if name in ("filter", "filterNot"):
            if not o.some:
                return o
            keep = _jt_truthy(vm.call_lam(a[0], [o.v])) == (name == "filter")
            return o if keep else _JtOpt(None, False)
        if name in ("map", "flatMap"):
            if not o.some:
                return o
            r = vm.call_lam(a[0], [o.v])
            if name == "flatMap":
                return r
            return _JtOpt(r, r is not None or not java)
        if name in ("exists", "forall"):
            return int(_jt_truthy(vm.call_lam(a[0], [o.v]))) if o.some else int(name == "forall")
        raise _JtUnk(f"Option.{name}")
    raise _JtUnk(f"{owner}.{name}")


_JT_STR_SEED = (None, "", "a", "A", "0", " ", "ab", "abc", "-1", "abcd", "abcdefgh")
_JT_INT_SEED = (0, -1, 1, 2, -(1 << 31), (1 << 31) - 1)


def _jt_consts(ms):
    ints, strs = [], []
    for p, m in ms:
        raw = next((b for n, b in m["attributes"] if n == "Code"), b"")
        try:
            ins = jvm_code_decode(raw[8:8 + struct.unpack_from(">I", raw, 4)[0]]) if len(raw) >= 8 else []
        except Exception:   # noqa: BLE001
            continue
        for _, op, arg in ins:
            mn = _JOPS[op]
            if mn.startswith("iconst_"):
                ints.append(-1 if mn.endswith("m1") else int(mn[-1]))
            elif mn in ("bipush", "sipush"):
                ints.append(arg[0])
            elif mn in ("ldc", "ldc_w") and p["cp"][arg[0]]:
                t, v = p["cp"][arg[0]]
                if t == 3:
                    ints.append(v)
                elif t == 8:
                    strs.append(p["_u"](v))
    return _jpd_uniq(ints)[:16], _jpd_uniq(strs)[:8]


def _jt_candidates(types, ints, strs):
    ks = [k for c in ints for k in (c, c + 1, c - 1) if 0 <= k <= 64]
    per = []
    for t in types:
        if t == "Ljava/lang/String;" or t in ("Ljava/lang/Object;", "Ljava/lang/CharSequence;"):
            per.append(_jpd_uniq(list(_JT_STR_SEED) + strs + ["a" * k for k in ks])[:40])
        elif t in ("I", "S", "B", "C", "J"):
            per.append(_jpd_uniq(list(_JT_INT_SEED) + [x for c in ints for x in (c, c + 1, c - 1)]
                                 + list(range(3, 17)))[:48])
        elif t == "Z":
            per.append([0, 1])
        elif t[:1] == "[" and t[1:] in ("I", "B", "C", "S", "J"):
            per.append([None, _JtArr()] + [_JtArr([0] * k) for k in _jpd_uniq([1, 2, *ks])[:12]])
        elif t == "[Ljava/lang/String;":
            per.append([None, _JtArr(), _JtArr([None]), _JtArr([""]), _JtArr(["a"])] +
                       [_JtArr(["a"] * k) for k in _jpd_uniq([2, *ks])[:8]])
        else:
            per.append([None])
    combos = sorted(itertools.product(*(range(len(x)) for x in per)), key=lambda c: (sum(c), c))[:600]
    return [[per[j][i] for j, i in enumerate(c)] for c in combos]


def _jt_lit(v, t):
    if v is None:
        return "null"
    if isinstance(v, str):
        return json.dumps(v, ensure_ascii=False)
    if isinstance(v, _JtArr):
        el = t[1:]
        return "{" + ", ".join(_jt_lit(x, el) for x in v) + "}" if v else "{}"
    if t == "C":
        return repr(chr(v & 0xffff))
    if t == "Z":
        return "true" if v else "false"
    return str(v)


def _jt_jar_classes(blob):
    out = {}
    for _, cb in _jpd_classes(blob):
        p = classfile_parse(cb)
        if p:
            out[p["this"]] = p
    return out


def _jt_eval(classes, cls, name, desc, args, deadline):
    vm = _JtVm(classes, deadline=deadline)
    hit = vm.method(cls, name, desc)
    if not hit:
        return "unknown", None
    static = bool(hit[2]["access"] & 0x0008)
    try:
        vm.clinit(cls)
        recv = None
        if not static:
            recv = vm.statics.get((cls, "MODULE$")) or _JtObj(cls)
        r = vm.run(cls, name, desc, ([] if static else [recv]) + list(args))
        return "return", r
    except _JtThrow as ex:
        return "exception", ex.cls
    except (_JtUnk, RecursionError, IndexError, KeyError, TypeError, ValueError, AttributeError, struct.error):
        return "unknown", None


def jvm_method_eval(jar, cls, name, desc, args):
    """Statically evaluate one method of a jar / .class with the bytecode model -> ("return", value) |
    ("exception", internal class name) | ("unknown", None). Strings are str, null None, ints int."""
    try:
        return _jt_eval(_jt_jar_classes(jar), cls, name, desc, args, time.monotonic() + 0.5)
    except Exception:   # noqa: BLE001
        return "unknown", None


def jvm_trigger_proof(jar_a, jar_b, method=None):
    """'Prove the old one was really broken': run the changed method of twin JVM builds (A = vulnerable / before,
    B = corrected / after) through a tiny bytecode evaluator over candidate inputs derived from the method's
    descriptor and constants (null, "", 1-char strings, index==length strings, 0/-1/1/MIN/MAX, constants +-1),
    in simplicity order; the FIRST input where the builds differ (A throws, B returns preferred) is the trigger.
    Never executes the sample. -> {field: answer string} | None (not JVM twins). Fields: trigger_input (Java
    literal, `null`), trigger_input_raw, trigger_input_type, vulnerable_outcome (dotted exception class or the
    return value), vulnerable_outcome_kind (exception/return), corrected_result / corrected_outcome(_kind),
    exception_class (+_simple/_internal), trigger_found, differing_inputs/_count, candidates_tested, method;
    every vulnerable_/corrected_ fact is aliased as _a/_b, before_/after_, old_/new_, original_/fixed_."""
    try:
        return _jvm_trigger_proof(jar_a, jar_b, method)
    except Exception:   # noqa: BLE001 -- malformed / decoy input: no answer
        return None


def _jvm_trigger_proof(jar_a, jar_b, method):
    d = _jvm_patch_diff(jar_a, jar_b)
    if d is None:
        return None
    ca, cb = _jt_jar_classes(jar_a), _jt_jar_classes(jar_b)
    name = method or d.get("changed_method", "none")
    cls_a, cls_b = d.get("changed_class_a"), d.get("changed_class_b")
    none = {k: "none" for k in ("trigger_input", "trigger_input_raw", "trigger_input_type", "vulnerable_outcome",
                                "vulnerable_outcome_kind", "corrected_result", "corrected_outcome",
                                "corrected_outcome_kind", "vulnerable_result", "exception_class",
                                "exception_class_simple", "exception_class_internal")}
    none.update({"trigger_found": "false", "differing_inputs": "[]", "differing_input_count": "0",
                 "candidates_tested": "0", "method": name})
    if name == "none" or cls_a not in ca or cls_b not in cb:
        return _jt_alias(none)
    ma = [m for m in ca[cls_a]["methods"] if m["name"] == name]
    mb = [m for m in cb[cls_b]["methods"] if m["name"] == name]
    if not ma or not mb:
        return _jt_alias(none)
    da = d.get("changed_method_descriptor") if not method else ma[0]["descriptor"]
    m_a = next((m for m in ma if m["descriptor"] == da), ma[0])
    ra, rb = d.get("role_a", "none"), d.get("role_b", "none")
    want_b = m_a["descriptor"].replace(ra, rb) if ra not in ("", "none") else m_a["descriptor"]
    m_b = next((m for m in mb if m["descriptor"] == want_b), None) or next(
        (m for m in mb if len(_JT_PARAM.findall(m["descriptor"])) == len(_JT_PARAM.findall(m_a["descriptor"]))), None)
    if not m_b:
        return _jt_alias(none)
    desc_a, desc_b = m_a["descriptor"], m_b["descriptor"]
    types = _JT_PARAM.findall(desc_a.split(")")[0])
    rtype = desc_a.split(")")[1]
    lam_ms = [(p, m) for p in (ca[cls_a], cb[cls_b]) for m in p["methods"]
              if m["name"] in (name, "<clinit>") or name in m["name"]]   # + $anonfun$<name>$N lambdas, statics
    ints, strs = _jt_consts(lam_ms)
    cands = _jt_candidates(types, ints, strs)
    deadline = time.monotonic() + 0.6
    first, alt, diffs, tested = None, None, [], 0
    for args in cands:
        if time.monotonic() > deadline:
            break
        tested += 1
        oa = _jt_eval(ca, cls_a, name, desc_a, args, deadline)
        ob = _jt_eval(cb, cls_b, name, desc_b, args, deadline)
        if "unknown" in (oa[0], ob[0]) or oa == ob:
            continue
        diffs.append(", ".join(_jt_lit(v, t) for v, t in zip(args, types)))
        if first is None and oa[0] == "exception" and ob[0] == "return":
            first = (args, oa, ob)
        elif alt is None:
            alt = (args, oa, ob)
        if first and len(diffs) >= 10:
            break
    hit = first or alt
    f = dict(none)
    f.update({"differing_inputs": _jv(diffs[:10]), "differing_input_count": str(len(diffs)),
              "candidates_tested": str(tested), "method": name, "method_descriptor": desc_a})
    if not hit:
        return _jt_alias(f)
    args, oa, ob = hit
    lit = ", ".join(_jt_lit(v, t) for v, t in zip(args, types))
    raw = ", ".join(_jt_str(v, t) if not isinstance(v, _JtArr) else _jt_lit(v, t) for v, t in zip(args, types))
    a0 = args[0] if len(args) == 1 else None
    ttype = ("null" if len(args) == 1 and a0 is None else "empty_string" if a0 == "" else
             "string" if isinstance(a0, str) else "array" if isinstance(a0, _JtArr) else
             "int" if len(args) == 1 else "tuple")

    def show(o):
        return o[1].replace("/", ".") if o[0] == "exception" else _jt_str(o[1], rtype)
    exc = oa if oa[0] == "exception" else ob if ob[0] == "exception" else None
    f.update({"trigger_found": "true", "trigger_input": lit, "trigger_input_raw": raw, "trigger_input_type": ttype,
              "vulnerable_outcome": show(oa), "vulnerable_result": show(oa), "vulnerable_outcome_kind": oa[0],
              "corrected_outcome": show(ob), "corrected_result": show(ob), "corrected_outcome_kind": ob[0],
              "vulnerable_crashes": "true" if oa[0] == "exception" else "false",
              "corrected_crashes": "true" if ob[0] == "exception" else "false"})
    if exc:
        f.update({"exception_class": exc[1].replace("/", "."), "exception_class_simple": exc[1].rsplit("/", 1)[-1],
                  "exception_class_internal": exc[1]})
    return _jt_alias(f)


def _jt_alias(f):
    for k in [k for k in f if k.startswith(("vulnerable_", "corrected_"))]:
        vuln = k.startswith("vulnerable_")
        base = k.split("_", 1)[1]
        for pa, pb in (("before", "after"), ("old", "new"), ("original", "fixed"), ("unpatched", "patched")):
            f.setdefault(f"{pa if vuln else pb}_{base}", f[k])
        f.setdefault(f"{base}_{'a' if vuln else 'b'}", f[k])
        f.setdefault(f"{base}_{'vulnerable' if vuln else 'corrected'}", f[k])
    return f


def jvm_trigger_field(jar_a, jar_b, field, method=None):
    """One jvm_trigger_proof fact; "none" when absent, None when the inputs aren't JVM twins."""
    f = jvm_trigger_proof(jar_a, jar_b, method)
    return None if f is None else f.get(field, "none")


# --- packing -------------------------------------------------------------------------------------
def entropy(data):
    """Shannon entropy (bits/byte, 0-8). Packed/encrypted payloads sit ~7.8+; normal code ~5-6.5."""
    if not data:
        return 0.0
    freq = [0] * 256
    for b in data:
        freq[b] += 1
    n = len(data)
    return -sum((c / n) * math.log2(c / n) for c in freq if c)


def packer_info(data):
    """Detect packing. Returns {packer, entropy, packed(bool)}. Catches UPX by magic and anything else by
    high whole-file entropy (a gate before analysis — a packed binary's symbols/sections are meaningless)."""
    e = round(entropy(data), 2)
    packer = None
    if b"UPX!" in data[:4096] or b"UPX0" in data or b"UPX1" in data or _upx_sniff(data):
        packer = "upx"   # _upx_sniff: the layout alone (scrubbed `UPX!`, renamed UPX0/1); unpack: upx_unpack(data)
    elif b"PEtite" in data[:4096]:
        packer = "petite"
    elif b"ASPack" in data[:4096]:
        packer = "aspack"
    packed = bool(packer) or e >= 7.2
    return {"packer": packer, "entropy": e, "packed": packed}


def unpack_upx(path):
    """Unpack a UPX binary to a sibling file, return its path (or the original if upx is absent/fails)."""
    if not shutil.which("upx"):
        return str(path)
    out = str(path) + ".unpacked"
    shutil.copy(path, out)
    r = subprocess.run(["upx", "-d", "-q", out], capture_output=True, timeout=120)
    return out if r.returncode == 0 else str(path)



# --- UPX, pure Python (in-window: no `upx -d` subprocess) ----------------------------------------------------------
# What answers from which bytes (a UPX'd artifact): sha256 / md5 / size = the PACKED artifact as handed out (that is the
# file the GM hashed); format / machine / has_hcfg_section / section names / the HCFG blob + its offset = the UNPACKED
# image (= `upx -d` output: the packed file has no .hcfg section, only UPX0/UPX1 or bare ELF segments). The magic may
# be scrubbed (`UPX!` zeroed, UPX0/1 renamed): nothing below needs it -- ELF: l_info/p_info/b_info sit right after the
# phdrs; PE: the first section is virtual-only (raw size 0) and the next one starts with the NRV stream.
HCFG_UPX_MAX = int(os.environ.get("HCTF_HCFG_UPX_MAX", str(24 << 20)))   # unpacked bytes (pure-Python NRV ~MB/s)
_NRV = {2: "b", 5: "d", 8: "e"}   # UPX M_NRV2B_LE32 / M_NRV2D_LE32 / M_NRV2E_LE32 (upx -1..-9 default methods)


def _nrv(src, ip, kind, cap, end=None):
    """UCL NRV2B/2D/2E (LE32 bit buffer) from src[ip:] -> (out, ip_after) or None (bad stream / over cap / late)."""
    out, n, bb, bc, last = bytearray(), len(src), 0, 0, 1
    try:
        def gb():
            nonlocal bb, bc, ip
            if not bc:
                if ip + 4 > n:
                    raise IndexError
                bb, bc, ip = int.from_bytes(src[ip:ip + 4], "little"), 32, ip + 4
            bc -= 1
            return (bb >> bc) & 1
        while True:
            while gb():
                out.append(src[ip])
                ip += 1
            off = 1
            while True:
                off = off * 2 + gb()
                if gb():
                    break
                if kind != "b":
                    off = (off - 1) * 2 + gb()
            if off == 2:
                off, ln = last, (gb() if kind != "b" else 0)
            else:
                off = ((off - 3) * 256 + src[ip]) & 0xFFFFFFFF
                ip += 1
                if off == 0xFFFFFFFF:
                    return bytes(out), ip
                if kind == "b":
                    ln, off = 0, off + 1
                else:
                    ln, off = (off ^ 0xFFFFFFFF) & 1, (off >> 1) + 1
                last = off
            if kind == "e":
                if ln:
                    ln = 1 + gb()
                elif gb():
                    ln = 3 + gb()
                else:
                    ln = 1
                    while True:
                        ln = ln * 2 + gb()
                        if gb():
                            break
                    ln += 3
            else:
                ln = ln * 2 + gb() if kind == "d" else gb() * 2 + gb()
                if not ln:
                    ln = 1
                    while True:
                        ln = ln * 2 + gb()
                        if gb():
                            break
                    ln += 2
            ln += 1 + (off > (0xD00 if kind == "b" else 0x500))
            st = len(out) - off
            if st < 0 or len(out) + ln > cap or (end is not None and time.time() > end):
                return None
            if off >= ln:
                out += out[st:st + ln]
            else:
                for k in range(ln):
                    out.append(out[st + k])
    except IndexError:
        return None


def _upx_block(data, p, end, cap):
    """b_info at p: (u_len, c_len, method, filter, cto) + payload -> (plain, next_p) or None."""
    if p + 12 > len(data):
        return None
    u, c, meth, flt, _cto, z = struct.unpack_from("<IIBBBB", data, p)
    if not (0 < c <= u <= cap) or z or p + 12 + c > len(data):
        return None
    if meth == 0 or c == u:   # stored
        return (data[p + 12:p + 12 + u], p + 12 + c) if c == u else None
    if meth not in _NRV:
        return None
    r = _nrv(data, p + 12, _NRV[meth], u, end)
    return (r[0], p + 12 + c) if r and len(r[0]) == u else None


def _upx_elf(data, end, cap):
    """UPX'd ELF64 LE -> the unpacked file bytes (`upx -d` layout; filtered code blocks left filtered) or None."""
    if data[:4] != b"\x7fELF" or data[4] != 2 or data[5] != 1:
        return None
    phoff, = struct.unpack_from("<Q", data, 0x20)
    phent, phnum = struct.unpack_from("<HH", data, 0x36)
    p = phoff + phent * phnum   # l_info (12) + p_info (12)
    if p + 36 > len(data) or phnum > 16:
        return None
    fsize, = struct.unpack_from("<I", data, p + 16)
    if not 64 <= fsize <= cap:
        return None
    r = _upx_block(data, p + 24, end, cap)
    if not r or r[0][:4] != b"\x7fELF" or r[0][4] != 2:
        return None
    hdr, p = r
    img = bytearray(fsize)
    o_phoff, = struct.unpack_from("<Q", hdr, 0x20)
    o_phent, o_phnum = struct.unpack_from("<HH", hdr, 0x36)
    loads = []
    for k in range(o_phnum):
        q = o_phoff + k * o_phent
        if q + 56 > len(hdr):
            return None
        ptype, _fl, off, _va, _pa, filesz = struct.unpack_from("<IIQQQQ", hdr, q)
        if ptype == 1 and filesz:
            loads.append((off, filesz))
    covered, first = [], True
    for off, filesz in loads:
        pos = off
        while pos < off + filesz:
            if first:
                blk, first = hdr, False
            else:
                r = _upx_block(data, p, end, cap)
                if not r:
                    return None
                blk, p = r
            if pos + len(blk) > fsize:
                return None
            img[pos:pos + len(blk)] = blk
            pos += len(blk)
        covered.append((off, pos))
    gaps, cur = [], 0   # non-PT_LOAD pieces (padding, .comment/.symtab/section headers) follow the loader stub
    for a, b in sorted(covered) + [(fsize, fsize)]:
        if a > cur:
            gaps.append((cur, a))
        cur = max(cur, b)
    q, lim = p, min(len(data), p + (64 << 10))
    while gaps and q < lim:
        a, b = gaps[0]
        if struct.unpack_from("<I", data, q)[0] == b - a if q + 4 <= len(data) else False:
            r = _upx_block(data, q, end, cap)
            if r:
                img[a:b] = r[0]
                gaps.pop(0)
                q = r[1]
                continue
        q += 1
    return bytes(img)


def _upx_pe(data, end, cap):
    """UPX'd PE32/PE32+ -> the unpacked file bytes (original headers + sections at their original raw offsets)."""
    if data[:2] != b"MZ" or len(data) < 0x200:
        return None
    e = int.from_bytes(data[0x3C:0x40], "little")
    if data[e:e + 4] != b"PE\0\0":
        return None
    nsec, = struct.unpack_from("<H", data, e + 6)
    opt, = struct.unpack_from("<H", data, e + 20)
    st = e + 24 + opt
    secs = [struct.unpack_from("<8sIIII", data, st + 40 * k) for k in range(min(nsec, 96))]
    if len(secs) < 2 or secs[0][3] or not secs[0][1] or not secs[1][3]:
        return None   # UPX0: virtual only; UPX1: the compressed stream at its raw start
    base, raw1 = secs[0][2], secs[1][4]
    meths = list(_NRV.values())
    ph = data.rfind(b"UPX!", 0, raw1)
    if ph >= 0 and ph + 12 <= len(data) and data[ph + 6] in _NRV:
        meths.remove(_NRV[data[ph + 6]])
        meths.insert(0, _NRV[data[ph + 6]])
    for kind in meths:
        r = _nrv(data, raw1, kind, cap, end)
        if not r:
            continue
        u = r[0]
        k = u.rfind(b"PE\0\0")
        while k >= 0:   # the original PE header + section table ride after the image
            onsec, = struct.unpack_from("<H", u, k + 6) if k + 24 <= len(u) else (0,)
            oopt, = struct.unpack_from("<H", u, k + 20) if k + 24 <= len(u) else (0,)
            ost = k + 24 + oopt
            if 0 < onsec <= 96 and ost + 40 * onsec <= len(u):
                osecs = [struct.unpack_from("<8sIIII", u, ost + 40 * j) for j in range(onsec)]
                size = max(rp + rs for _n, _vs, _va, rs, rp in osecs)
                if size <= cap and all(va >= base for _n, _vs, va, _rs, _rp in osecs):
                    hdr = ost + 40 * onsec - k
                    img = bytearray(max(size, e + hdr))
                    img[:e] = data[:e]
                    img[e:e + hdr] = u[k:k + hdr]
                    for _n, vs, va, rs, rp in osecs:
                        piece = u[va - base:va - base + rs]
                        img[rp:rp + len(piece)] = piece
                    return bytes(img)
            k = u.rfind(b"PE\0\0", 0, k)
    return None


def _upx_sniff(data):
    """Cheap UPX layout check (no decompression): ELF l_info/p_info/b_info after the phdrs, or PE whose first section
    is virtual-only and whose entry point lies in the second."""
    try:
        if data[:4] == b"\x7fELF" and data[4] == 2 and data[5] == 1:
            phoff, = struct.unpack_from("<Q", data, 0x20)
            phent, phnum = struct.unpack_from("<HH", data, 0x36)
            p = phoff + phent * phnum
            fsize, = struct.unpack_from("<I", data, p + 16)
            u, c, meth, _f, _c, z = struct.unpack_from("<IIBBBB", data, p + 24)
            return phnum <= 16 and data[p + 11] in (0x16, 0x17) and 0 < c <= u <= fsize and meth in _NRV and not z
        if data[:2] == b"MZ":
            e = int.from_bytes(data[0x3C:0x40], "little")
            if data[e:e + 4] != b"PE\0\0":
                return False
            opt, = struct.unpack_from("<H", data, e + 20)
            ep, = struct.unpack_from("<I", data, e + 40)
            (_n0, vs0, va0, rs0, _p0), (_n1, vs1, va1, rs1, _p1) = (
                struct.unpack_from("<8sIIII", data, e + 24 + opt + 40 * k) for k in range(2))
            return not rs0 and vs0 > 0 and rs1 > 0 and va1 == va0 + vs0 and va1 <= ep < va1 + vs1
    except (struct.error, IndexError):
        pass
    return False


def upx_unpack(data, *, deadline=None, cap=None):
    """The `upx -d` image of a UPX'd ELF64/PE (NRV2B/2D/2E; magic may be scrubbed) as bytes, or None. Pure Python.
    ELF code blocks under a UPX call/jmp filter stay filtered (data sections -- .hcfg, .rodata -- are exact)."""
    data, cap = bytes(data), cap or HCFG_UPX_MAX
    try:
        return _upx_elf(data, _ends(deadline), cap) or _upx_pe(data, _ends(deadline), cap)
    except (struct.error, IndexError, ValueError, MemoryError):
        return None


def upx_hcfg(data, **kw):
    """(unpacked image, first crc-valid HcfgHit inside it) for a UPX'd artifact, else (None, None). The hit's offset
    is an offset in the UNPACKED image."""
    img = upx_unpack(data, deadline=kw.get("deadline"))
    return (img, hcfg_find(img, **kw)) if img else (None, None)


def _ror8(b, r):
    return ((b >> r) | (b << (8 - r))) & 255


def overlay_unpack(data, magic):
    """Day 19 packed overlay (GM-confirmed on the Single, TT and Mastery): the LAST `magic` ('PK19'; the D19 question
    already names 'RS20' for Day 20) in the file; +5 k1, +6 k2, +8 u32le packed length, +12 sha256(unpacked), +44 packed
    bytes; unpacked[i] = ror8(packed[i] ^ k2, 3) ^ k1, the HCFG record at unpacked offset 0. A mutated rotation/key
    falls back to the (xor, rot, xor) that yields b'HCFG' at 0 and matches the stored sha256. Bytes or None.
    overlay_offset = data.rfind(magic), overlay_size = len(data) - that offset (both GM-confirmed D19)."""
    import hashlib
    if isinstance(magic, dict):   # an overlay_spec(question): the question-driven unpacker (tuple or None)
        return overlay_spec_unpack(data, magic)
    o = data.rfind(magic.encode() if isinstance(magic, str) else magic) if magic else -1
    if o < 0 or o + 44 > len(data):
        return None
    rs = resource_overlay(data, magic)
    if rs and rs["offset"] == o:   # D20 RS20 resource layout (hash-verified): the HCFG resource itself
        return rs["hcfg"]
    k1, k2 = data[o + 5], data[o + 6]
    n, = struct.unpack_from("<I", data, o + 8)
    sha = data[o + 12:o + 44]
    pk = data[o + 44:o + 44 + n] if n else data[o + 44:]
    out = bytes(_ror8(b ^ k2, 3) ^ k1 for b in pk)
    if hashlib.sha256(out).digest() == sha or out[:4] == HCFG_MAGIC:
        return out
    if len(pk) < 4:
        return None
    for r in range(8):
        for a in range(256):
            c = _ror8(pk[0] ^ a, r) ^ HCFG_MAGIC[0]
            if all(_ror8(pk[i] ^ a, r) ^ c == HCFG_MAGIC[i] for i in range(1, 4)):
                out = bytes(_ror8(b ^ a, r) ^ c for b in pk)
                if hashlib.sha256(out).digest() == sha:
                    return out
    return None


OVERLAY_MAGICS = ("PK19", "RS20")   # D19 GM-confirmed; RS20 named by the D19 overlay_offset question for Day 20


def resource_overlay(data, magic="RS20"):
    """Day 20 RS20 resource overlay (GM-confirmed on the Single, TT and 5 Mastery sets): the LAST `magic`; +8 u32le
    HCFG resource length, +12 u16le scratch length, +16..+47 sha256(scratch), HCFG resource at +48, scratch right after
    it, ending exactly at EOF. {offset, hcfg_resource_size, scratch_size, scratch_sha256, hcfg (bytes), scratch} only
    when the end bounds and the scratch sha256 verify, else None. hcfg_resource_size = the +8 field (380 on D20)."""
    import hashlib
    try:
        data = bytes(data)
        mg = magic.encode("latin-1") if isinstance(magic, str) else magic
        o = data.rfind(mg) if mg else -1
        if o < 0 or o + 48 > len(data):
            return None
        n, s = struct.unpack_from("<IH", data, o + 8)
        sha, hcfg = data[o + 16:o + 48], data[o + 48:o + 48 + n]
        scratch = data[o + 48 + n:o + 48 + n + s]
        if o + 48 + n + s != len(data) or hashlib.sha256(scratch).digest() != sha:
            return None
        return {"offset": o, "hcfg_resource_size": n, "scratch_size": s, "scratch_sha256": sha.hex(), "hcfg": hcfg,
                "scratch": scratch}
    except (struct.error, TypeError, ValueError):
        return None


def overlay_header_facts(data, magic=None):
    """Header facts of the packed overlay (D19 PK19 layout: magic +0..3, version u8 +4, k1 +5, k2 +6, pad +7, packed
    length u32le +8, sha256(unpacked) +12..+44, packed bytes +44) at the LAST `magic` (str/bytes; an overlay_spec dict
    unpacks with the question's transform; None = the last of OVERLAY_MAGICS present). Keys: has_overlay / image_end
    (overlay_info: bytes past every header-described region), overlay_magic, overlay_offset, overlay_size,
    overlay_at_image_end, overlay_version, k1/k2 (int) + k1_hex/k2_hex ('0x%02x' like xor_key_hex), pad, packed_length,
    unpacked_sha256 (64 lowercase hex, no prefix), packed_sha256, overlay_entropy / packed_entropy (bits/byte, 4 dp),
    unpacked_length/unpacked_size (len of the hash-verified unpack), unpacked_sha256_ok, hcfg_storage. The overlay
    keys are "none" when no magic lies past the image end with a packed length that fits the file (has_overlay /
    image_end still answer); unpacked_* None when the stored hash
    does not verify. hcfg_storage "raw" is SPECULATIVE (the D17 rule list's catch-all: no section holds a packed
    overlay). None for non-bytes input."""
    try:
        data = bytes(data)
        spec = magic if isinstance(magic, dict) else None
        if spec:
            magic = spec.get("magic")
        if isinstance(magic, str):
            magic = magic.encode("latin-1")
        ov = overlay_info(data)
        facts = {"has_overlay": bool(ov and ov["has_overlay"]),
                 "image_end": (ov["overlay_offset"] if ov["has_overlay"] else len(data)) if ov else "none"}
        cands = [magic] if magic else [m.encode() for m in OVERLAY_MAGICS]
        o, mg = max((data.rfind(m), m) for m in cands if m)
        keys = ("overlay_magic", "overlay_offset", "overlay_size", "overlay_at_image_end", "overlay_version", "k1", "k2",
                "k1_hex", "k2_hex", "pad", "packed_length", "unpacked_sha256", "packed_sha256", "overlay_entropy",
                "packed_entropy", "unpacked_length", "unpacked_size", "unpacked_sha256_ok", "hcfg_storage")
        n = struct.unpack_from("<I", data, o + 8)[0] if 0 <= o and o + 44 <= len(data) else -1
        if n < 0 or o + 44 + n > len(data) or (ov and o < facts["image_end"]):   # a string in .rodata is no overlay
            facts.update(dict.fromkeys(keys, "none"))
            return facts
        import hashlib
        pk = data[o + 44:o + 44 + n] if n else data[o + 44:]
        if spec:
            r = overlay_spec_unpack(data, spec)
            out = r[3] if r and r[0] == o and r[4] else None
        else:
            out = overlay_unpack(data, mg)
            out = out if out is not None and hashlib.sha256(out).digest() == data[o + 12:o + 44] else None
        facts.update({
            "overlay_magic": mg.decode("latin-1"), "overlay_offset": o, "overlay_size": len(data) - o,
            "overlay_at_image_end": bool(ov) and o == facts["image_end"],
            "overlay_version": data[o + 4], "k1": data[o + 5], "k2": data[o + 6],
            "k1_hex": "0x%02x" % data[o + 5], "k2_hex": "0x%02x" % data[o + 6], "pad": data[o + 7],
            "packed_length": n, "unpacked_sha256": data[o + 12:o + 44].hex(),
            "packed_sha256": hashlib.sha256(pk).hexdigest(),
            "overlay_entropy": round(entropy(data[o:]), 4), "packed_entropy": round(entropy(pk), 4),
            "unpacked_length": len(out) if out is not None else None,
            "unpacked_size": len(out) if out is not None else None,
            "unpacked_sha256_ok": out is not None,
            "hcfg_storage": "raw" if out is not None and out[:4] == HCFG_MAGIC else None})
        return facts
    except Exception:  # noqa: BLE001
        return None


def overlay_header_field(data, name, magic=None):
    """One overlay_header_facts value: "none" when absent (no overlay magic / unknown field), None when unanswerable."""
    f = overlay_header_facts(data, magic)
    return None if f is None else f.get(name, "none")


# --- multi-layer / decoy overlay chain ('Find the FINAL PK19 overlay') ------------------------------------------------
# Rule set (SPECULATIVE beyond D19's single PK19): every magic hit is a candidate; in an ELF/PE container a hit before the
# image end (a .rodata string) is no overlay; of the rest the LAST whose D19 header unpacks hash-verified wins (an
# earlier / later bad-hash block is a decoy). The unpacked payload recurses while it starts with a known container:
# PK19/RS20 at 0 (overlay inside the overlay), an ELF/PE (its own overlay), zlib/gzip (inflate) -- depth <= 4.
OVERLAY_CHAIN_DEPTH = 4


def _pk19_at(data, o, budget=None):
    """D19-layout unpack of the overlay at offset `o` (overlay_unpack's transform + fallback): (out, packed_length,
    hash_ok) or None when the header does not fit / the packed length exceeds budget[0] (bytes left, decremented)."""
    import hashlib
    if o < 0 or o + 44 > len(data):
        return None
    n, = struct.unpack_from("<I", data, o + 8)
    if o + 44 + n > len(data):
        return None
    m = n or len(data) - o - 44
    if budget is not None:
        if m > budget[0]:
            return None
        budget[0] -= m
    pk = data[o + 44:o + 44 + m]
    k1, k2, sha = data[o + 5], data[o + 6], data[o + 12:o + 44]
    out = pk.translate(bytes(_ror8(b ^ k2, 3) ^ k1 for b in range(256)))
    if hashlib.sha256(out).digest() == sha:
        return out, n, True
    if len(pk) >= 4:
        for r in range(8):
            for a in range(256):
                c = _ror8(pk[0] ^ a, r) ^ HCFG_MAGIC[0]
                if all(_ror8(pk[i] ^ a, r) ^ c == HCFG_MAGIC[i] for i in range(1, 4)):
                    if budget is not None:
                        if m > budget[0]:
                            return out, n, False
                        budget[0] -= m
                    o2 = pk.translate(bytes(_ror8(b ^ a, r) ^ c for b in range(256)))
                    if hashlib.sha256(o2).digest() == sha:
                        return o2, n, True
    return out, n, False


def _chain_inflate(buf):
    """zlib / gzip payload -> inflated bytes (capped), else None."""
    try:
        if buf[:2] == b"\x1f\x8b":
            d = zlib.decompressobj(31)
        elif len(buf) >= 2 and buf[0] & 15 == 8 and (buf[0] << 8 | buf[1]) % 31 == 0:
            d = zlib.decompressobj()
        else:
            return None
        out = d.decompress(buf, 1 << 24)
        return out if out and d.eof else None
    except Exception:  # noqa: BLE001
        return None


def overlay_chain(data, magic=None, max_depth=OVERLAY_CHAIN_DEPTH):
    """Walk nested / decoy overlays (see the rule set above). `magic` str/bytes or None (= OVERLAY_MAGICS). Keys:
    layer_count (hash-verified overlay layers unpacked), layers [{depth, kind ('overlay'|'zlib'|'gzip'),
    magic, offset (in its container), file_offset (outer file offset; None below depth 0), packed_length,
    unpacked_size}], overlay_offset / overlay_size (OUTERMOST layer, outer-file offset -- same as overlay_header_facts
    when its last magic verifies), final_overlay_offset (offset of the innermost overlay in ITS container),
    final_overlay_depth, final_overlay_magic, decoy_offsets / decoy_count (outer-file hits rejected: bad hash or before
    the image end), magic_hits, payload_kind (innermost payload's container chain, e.g. 'overlay>elf>overlay'),
    hcfg_offset (in the innermost payload), config, unpacked_sha256 (innermost). Absent fields are "none"; None for
    non-bytes / unexpected failure. Never raises."""
    try:
        import hashlib
        data = bytes(data)
        mags = [magic.encode("latin-1") if isinstance(magic, str) else bytes(magic)] if magic else \
            [m.encode() for m in OVERLAY_MAGICS]
        layers, decoys, hits0 = [], [], []
        buf, depth, kinds, final, budget = data, 0, [], None, [96 << 20]   # bytes transformed+hashed over all hits
        while depth <= max_depth and buf:
            if buf[:4] in mags and depth and layers:   # overlay inside the overlay: the record IS the payload
                ov_end = 0
            else:
                info = overlay_info(buf) if buf[:4] in (b"\x7fELF", b"MZ\x90\0") or buf[:2] == b"MZ" else None
                ov_end = info["overlay_offset"] if info and info["has_overlay"] else (len(buf) if info else 0)
            hits = sorted(o for m in mags for o in _find_all(buf, m))
            if depth == 0:
                hits0 = hits
            best = None
            for o in reversed(hits):
                r = _pk19_at(buf, o, budget) if o >= ov_end else None
                if r and r[2]:
                    best = (o, r)
                    break
            if depth == 0:
                decoys = [o for o in hits if not best or o != best[0]]
            if not best:
                z = _chain_inflate(buf) if layers else None
                if z is None:
                    break
                kinds.append("gzip" if buf[:2] == b"\x1f\x8b" else "zlib")
                layers.append({"depth": depth, "kind": kinds[-1], "magic": None, "offset": 0, "file_offset": None,
                               "packed_length": len(buf), "unpacked_size": len(z)})
                buf, depth = z, depth + 1
                continue
            o, (out, n, _) = best
            if depth and buf[:4] not in mags:
                kinds.append("elf" if buf[:4] == b"\x7fELF" else "pe" if buf[:2] == b"MZ" else "blob")
            kinds.append("overlay")
            layers.append({"depth": depth, "kind": "overlay", "magic": buf[o:o + 4].decode("latin-1"), "offset": o,
                           "file_offset": o if depth == 0 else None, "packed_length": n, "unpacked_size": len(out)})
            final = (o, depth, buf[o:o + 4].decode("latin-1"), out)
            buf, depth = out, depth + 1
        ovl = [L for L in layers if L["kind"] == "overlay"]
        none = "none"
        res = {"layer_count": len(ovl), "layers": layers, "magic_hits": hits0, "decoy_offsets": decoys,
               "decoy_count": len(decoys), "overlay_offset": none, "overlay_size": none, "final_overlay_offset": none,
               "final_overlay_depth": none, "final_overlay_magic": none, "payload_kind": none, "hcfg_offset": none,
               "config": none, "unpacked_sha256": none}
        if not ovl:
            return res
        res.update({"overlay_offset": ovl[0]["offset"], "overlay_size": len(data) - ovl[0]["offset"],
                    "final_overlay_offset": final[0], "final_overlay_depth": final[1], "final_overlay_magic": final[2],
                    "payload_kind": ">".join(kinds), "unpacked_sha256": hashlib.sha256(buf).hexdigest()})
        pb = _parse_blob(buf)
        if pb and pb[5] and isinstance(pb[6], dict):
            res.update({"hcfg_offset": 0, "config": pb[6]})
        elif len(buf) <= 1 << 22:
            h = hcfg_find(buf)
            if h:
                res.update({"hcfg_offset": h.offset, "config": h.config})
        return res
    except Exception:  # noqa: BLE001
        return None


def _find_all(buf, m, limit=256):
    out, i = [], buf.find(m)
    while i >= 0 and len(out) < limit:
        out.append(i)
        i = buf.find(m, i + 1)
    return out


def overlay_chain_field(data, name, magic=None):
    """One overlay_chain value: "none" when absent / unknown field, None when unanswerable."""
    f = overlay_chain(data, magic)
    return None if f is None else f.get(name, "none")

# --- question-driven overlay unpacker (D19 PK19, D20 RS20 ...) -------------------------------------------------------
# overlay_spec(question) reads the overlay layout the QUESTION states (magic, `<name> [fmt] at +N` header fields, packed
# bytes offset, stored hash, per-byte transform expression, optional decompressor); overlay_spec_unpack(data, spec)
# applies it and returns only a hash-verified result. Remaining prose ambiguities (reversal side, prev seed, LCG output
# byte, RLE pair order) are resolved ONLY by the stored hash (or HCFG at 0 when the question names no hash).
_OVS_FMT = {"u8": ("<B", 1), "byte": ("<B", 1), "u16le": ("<H", 2), "u16be": (">H", 2), "u16": ("<H", 2),
            "u32le": ("<I", 4), "u32be": (">I", 4), "u32": ("<I", 4), "u64le": ("<Q", 8), "u64be": (">Q", 8),
            "u64": ("<Q", 8)}
_OVS_HASH = (("sha-256", "sha256"), ("sha256", "sha256"), ("sha-1", "sha1"), ("sha1", "sha1"), ("md5", "md5"),
             ("crc-32", "crc32"), ("crc32", "crc32"))
_OVS_STOP = {"read", "the", "a", "an", "and", "then", "byte", "bytes", "value", "field", "stored", "header", "offset",
             "key", "at", "is", "unpacked", "packed", "little", "big", "endian", "little-endian", "big-endian", "with"}


def _ovs_num(s):
    return int(s, 16) if s.lower().startswith("0x") else int(s)


def overlay_spec(question):
    """Parse an overlay-unpack question into {"magic", "which" ('last'|'first'|'any'), "fields" {name: (off, fmt)},
    "data_off", "length" (field name|None), "hash" (algo, field, over) | None, "expr" (AST)|None, "steps" [...],
    "decompress" [names], "reverse" ('in'|'out'|'?'|None), "text"}. fmt: u8/u16le/u16be/u32le/u32be/u64le/u64be/
    bytes[n]. Offsets are relative to the magic. None when the question names no overlay magic / layout."""
    try:
        return _overlay_spec(question)
    except Exception:  # noqa: BLE001 - untrusted prose: unparseable -> no spec
        return None


def _overlay_spec(q):
    q = (q or {}).get("question", "") if isinstance(q, dict) else str(q or "")
    t = re.split(r"\b(?:Locate the unique|bytes 0\.\.3 are)", q)[0]
    m = (re.search(r"\b(?:final|last|first|the)\s+[`'\"]?([A-Z][A-Z0-9]{3})[`'\"]?\s+(?:overlay|trailer|blob|stub|"
                   r"record|header|section)", t)
         or re.search(r"\bmagic\s+(?:bytes\s+)?[`'\"]?([A-Z][A-Z0-9_]{3,7})[`'\"]?", t)
         or re.search(r"\b([A-Z]{2}\d{2})\b", t))
    if not m:
        return None
    magic = m.group(1)
    head = t[max(0, m.start() - 20):m.end() + 5].lower()
    which = "last" if re.search(r"\b(final|last)\b", head) else "first" if "first" in head else "any"
    fields, data_off, length, hsh = {}, None, None, None
    fmtre = r"(u8|u16le|u16be|u32le|u32be|u64le|u64be|u16|u32|u64)"
    for fm in re.finditer(r"([^,;.:]*?)\s+(?:is\s+)?(?:at|@)\s+(?:offset\s+|byte\s+)?\+\s*(0x[0-9a-fA-F]+|\d+)", t):
        desc, off = fm.group(1).strip(), _ovs_num(fm.group(2))
        dl = desc.lower()
        dl = re.sub(r"little[- ]endian\s+(u\d+|uint\d+|dword|word)", lambda x: x.group(1) + "le", dl)
        dl = re.sub(r"big[- ]endian\s+(u\d+|uint\d+|dword|word)", lambda x: x.group(1) + "be", dl)
        dl = re.sub(r"uint(\d+)", r"u\1", dl).replace("dword", "u32").replace("word", "u16")
        fmt = None
        f2 = re.search(r"\b" + fmtre + r"(le|be)?\b", dl)
        if f2:
            fmt = f2.group(1) + ("" if f2.group(1) in ("u8",) or f2.group(1)[-2:] in ("le", "be") else
                                 (f2.group(2) or "le"))
        nb = re.search(r"\b(\d+)-byte\b", dl)
        algo = next((a for k, a in _OVS_HASH if k in dl), None)
        if algo and not re.search(r"\b(length|size)\b", dl):
            n = {"sha256": 32, "sha1": 20, "md5": 16, "crc32": 4}[algo]
            if algo == "crc32" and fmt is None:
                fmt = "u32be" if "big" in dl else "u32le"
            fields["hash"] = (off, fmt or "bytes[%d]" % (int(nb.group(1)) if nb else n))
            over = "packed" if re.search(r"\b(packed|encrypted|encoded|cipher\w*|compressed)\b", dl) and \
                not re.search(r"\b(unpacked|decrypted|decoded|decompressed|plain\w*|original)\b", dl) else "out"
            hsh = (algo, "hash", over)
            continue
        if re.search(r"\b(packed|encrypted|encoded|cipher|compressed)?\s*(bytes|data|payload|ciphertext|body|blob|"
                     r"stream)\b", dl) and not re.search(r"\b(length|size|count|key)\b", dl) and fmt is None and not nb:
            data_off = off
            continue
        if re.search(r"\b(block|segment|chunk)", dl):   # 'block size u8 at +5' (a shuffle width, not the length)
            fields["block"] = (off, fmt or "u8")
            continue
        if re.search(r"\b(length|size|count)\b", dl):
            nm = "unpacked_length" if re.search(r"\b(unpacked|decompressed|original|plain)\b", dl) else "length"
            fields[nm] = (off, fmt or "u32le")
            if nm == "length":
                length = nm
            continue
        words = [w for w in re.findall(r"[a-z_][a-z0-9_]*", dl) if w not in _OVS_STOP and not re.fullmatch(fmtre, w)
                 and not re.fullmatch(r"(le|be|\d+)", w)]
        name = words[-1] if words else ("key" if "key" in dl else None)
        if not name:
            continue
        fields[name] = (off, "bytes[%d]" % int(nb.group(1)) if nb and fmt is None else fmt or "u8")
    expr, steps = None, []
    em = re.search(r"(?:compute|computes?|=|becomes|is)\s+((?:ro[rl]8?|rot[lr]|swap\w*|nib\w*|not|~|\(|[a-z_]\w*\s*"
                   r"(?:xor|\^|\+|-|add|sub|plus|minus|\[))[^;]*?)(?:;|\.\s|\.$|,\s*(?:then\s+)?(?:verify|check|"
                   r"decompress|inflate|use|and\s+verify)|,\s*(?:where|with|using|starting)\b)", t, re.I)
    if em:   # drop prose asides: '(the first byte uses iv)'
        expr = _ovs_parse(re.sub(r"\s*\((?:the|with|where|starting|initial|first|seeded|i\.e\.)\b[^)]*\)", "",
                                 em.group(1), flags=re.I))
    if expr is None:
        sm = re.search(r"for each (?:packed |encrypted |encoded )?byte[^,]*,\s*(.*?)(?:;|\.\s|\.$|,\s*(?:then\s+)?"
                       r"(?:verify|check|use))", t, re.I)
        if sm:
            steps = _ovs_steps(sm.group(1))
            expr = _ovs_from_steps(steps) if steps else None
    if expr is None and re.search(r"\b(?:rc4|arc4)\b", t, re.I):   # 'RC4-decrypt the packed bytes with the key at +8'
        kf = next((k for k, (_, fmt) in fields.items() if fmt.startswith("bytes[") and k != "hash"), None)
        expr = ("^", ("v", "byte"), ("f", "rc4", [("v", kf)])) if kf else None
    tl = t.lower()
    dec = [d for d, k in (("zlib", r"\bzlib\b|\binflate\b"), ("deflate", r"raw deflate|\bdeflate\b"),
                          ("gzip", r"\bgzip\b"), ("lzma", r"\blzma\b|\bxz\b"), ("bz2", r"\bbz(?:ip)?2\b"),
                          ("rle", r"\brle\b|run[- ]length"), ("lz4", r"\blz4\b"), ("zstd", r"\bzstd\b|zstandard"))
           if re.search(k, tl)]
    if re.search(r"pack\s?bits", tl):
        dec.append("packbits")
    dec += [d for d, k in (("aplib", r"\bap-?lib\b"), ("lznt1", r"\blznt1?\b"), ("lzss", r"\blzss\b|\blz77\b"),
                           ("lzma-raw", r"raw lzma|lzma1?[- ]raw|headerless lzma|lzma86|lzma1\b"))
            if re.search(k, tl)]
    # rolling key: 'key = (key * mul + inc) mod 256 after each byte' / 'key ^= previous packed byte'
    upd, init = None, None
    um = re.search(r"\b(key|k|state|st|s|r|kk|rk|x)\s*(\^|\+|-|\*|xor\s*)?(?:=|:=|becomes|is updated to|is set to)"
                   r"\s*(?!=)(.+?)(?=\s*(?:after (?:each|every)|per byte|for (?:each|the next)|before (?:each|the next)|"
                   r"each byte|;|,|\.\s|\.$))", t, re.I)
    if um and (em is None or um.start() > em.end()):
        rhs = _ovs_parse(re.sub(r"\s*\((?:the|with|where|i\.e\.)\b[^)]*\)", "", um.group(3), flags=re.I))
        if rhs is not None:
            op = (um.group(2) or "").strip().lower()
            vn = um.group(1).lower()
            upd = (vn, (_OVS_WORDOP.get(op, op), ("v", vn), rhs) if op else rhs)
            im = re.search(r"\b(?:starts?|starting|begins?|beginning|initiali[sz]ed|initially|seeded)\s+(?:at|as|with|"
                           r"to|from|by)?\s*(?:the\s+)?(?:value\s+)?(0x[0-9a-fA-F]+|\d+|[a-z_]\w*)", t, re.I)
            if im:
                init = _ovs_num(im.group(1)) if re.fullmatch(r"0x[0-9a-fA-F]+|\d+", im.group(1)) else im.group(1).lower()
    blocks = None   # 'reverse each 16-byte block' / 'block size u8 at +5 ... reverse each block'
    bm = re.search(r"revers\w*\s+(?:the\s+bytes\s+(?:of|in|within)\s+)?each\s+(?:(\d+)-byte\s+)?(?:block|segment|chunk)"
                   r"|(?:each|every)\s+(?:(\d+)-byte\s+)?(?:block|segment|chunk)\w*\s+(?:is\s+)?revers", tl)
    if bm:
        bn = bm.group(1) or bm.group(2) or (re.search(r"(\d+)-byte\s+(?:block|segment|chunk)", tl) or [None, None])[1]
        blocks = int(bn) if bn else "block" if "block" in fields else None
    rev = None
    if blocks is None and re.search(r"\brevers", tl):
        rev = "in" if re.search(r"revers\w*[^.;]{0,40}\b(packed|encrypted|input|cipher)", tl) else \
            "out" if re.search(r"revers\w*[^.;]{0,40}\b(unpacked|output|result|decoded|plain)", tl) else "?"
    return {"magic": magic, "which": which, "fields": fields, "data_off": data_off, "length": length, "hash": hsh,
            "expr": expr, "steps": steps, "decompress": dec, "reverse": rev, "update": upd, "init": init, "blocks": blocks, "text": t}


_OVS_TOK = re.compile(r"\s*(0x[0-9a-fA-F]+|\d+|<<|>>|\*\*|[A-Za-z_][A-Za-z0-9_]*|[-+*/%^&|~()\[\],])")
_OVS_WORDOP = {"xor": "^", "add": "+", "plus": "+", "sub": "-", "minus": "-", "mod": "%", "and": "&", "or": "|",
               "times": "*", "shl": "<<", "shr": ">>", "not": "~"}


def _ovs_parse(s):
    """Tiny precedence-climbing parser for the question's byte expression -> nested tuples. None on any doubt."""
    s = re.sub(r"(?i)previous\s+(packed|encrypted|cipher\w*|input)\s+byte", "prev_cipher", s)
    s = re.sub(r"(?i)previous\s+(unpacked|decrypted|plain\w*|output|decoded)\s+byte", "prev_plain", s)
    s = re.sub(r"(?i)previous\s+byte", "prev", s)
    s = re.sub(r"(?i)\blen\s*\(\s*(\w+)\s*\)", r"len_\1", s)
    toks, pos = [], 0
    s = s.strip().rstrip(".")
    while pos < len(s):
        mt = _OVS_TOK.match(s, pos)
        if not mt:
            return None
        tk = mt.group(1)
        toks.append(_OVS_WORDOP.get(tk.lower(), tk) if re.fullmatch(r"[A-Za-z]+", tk) else tk)
        pos = mt.end()
    prec = {"|": 1, "^": 2, "&": 3, "<<": 4, ">>": 4, "+": 5, "-": 5, "*": 6, "%": 6, "/": 6}
    i = [0]

    def peek():
        return toks[i[0]] if i[0] < len(toks) else None

    def take():
        i[0] += 1
        return toks[i[0] - 1]

    def atom():
        tk = take()
        if tk == "(":
            v = expr(0)
            if take() != ")":
                raise ValueError
            return v
        if tk == "~":
            return ("~", atom())
        if tk == "-":
            return ("neg", atom())
        if re.fullmatch(r"0x[0-9a-fA-F]+|\d+", tk):
            return ("n", _ovs_num(tk))
        if re.fullmatch(r"[A-Za-z_]\w*", tk):
            nm = tk.lower()
            if peek() == "(":
                take()
                args = []
                while peek() != ")":
                    args.append(expr(0))
                    if peek() == ",":
                        take()
                take()
                return ("f", nm, args)
            if peek() == "[":
                take()
                ix = expr(0)
                if take() != "]":
                    raise ValueError
                return ("idx", nm, ix)
            return ("v", nm)
        raise ValueError(tk)

    def expr(mp):
        lhs = atom()
        while peek() in prec and prec[peek()] >= mp:
            op = take()
            lhs = (op, lhs, expr(prec[op] + 1))
        return lhs

    try:
        v = expr(0)
        return v if i[0] == len(toks) else None
    except Exception:  # noqa: BLE001
        return None


def _ovs_steps(s):
    """Sequential prose steps ('XOR with k1, rotate right by 3, then subtract k2') -> [(op, operand-AST)]."""
    out = []
    for part in re.split(r",\s*(?:and\s+)?(?:then\s+)?|\bthen\b|;", s):
        p = part.strip().lower()
        if not p:
            continue
        m = re.match(r"(xor|add|subtract|sub|plus|minus)\s+(?:it\s+)?(?:with\s+|by\s+|from\s+)?(.+)$", p)
        if m:
            op = {"xor": "^", "add": "+", "plus": "+"}.get(m.group(1), "-")
            a = _ovs_parse(m.group(2))
            if a is None:
                return []
            out.append((op, a))
            continue
        m = re.match(r"rotate\s+(?:it\s+)?(left|right)\s+(?:by\s+)?(.+)$", p) or \
            re.match(r"(ror|rol)8?\s+(?:by\s+)?(.+)$", p)
        if m:
            a = _ovs_parse(re.sub(r"\s*bits?$", "", m.group(2)))
            if a is None:
                return []
            out.append(("ror8" if m.group(1) in ("right", "ror") else "rol8", a))
            continue
        if re.match(r"(swap (the )?nibbles|nibble[- ]swap)", p):
            out.append(("swap", None))
            continue
        if re.match(r"(not|invert|bitwise not|complement)", p):
            out.append(("~", None))
            continue
        return []
    return out


def _ovs_from_steps(steps):
    x = ("v", "byte")
    for op, a in steps:
        x = ("f", op, [x, a]) if op in ("ror8", "rol8") else ("f", "swap", [x]) if op == "swap" else \
            ("~", x) if op == "~" else (op, x, a)
    return x


def _ovs_rc4(key, n):
    S, j = list(range(256)), 0
    key = key or b"\0"
    for k in range(256):
        j = (j + S[k] + key[k % len(key)]) & 255
        S[k], S[j] = S[j], S[k]
    out, a, b = bytearray(n), 0, 0
    for k in range(n):
        a = (a + 1) & 255
        b = (b + S[a]) & 255
        S[a], S[b] = S[b], S[a]
        out[k] = S[(S[a] + S[b]) & 255]
    return bytes(out)


def _ovs_lcg(seed, a, c, n, mod, shift, pre):
    st, out = seed % mod, [0] * n
    for k in range(n):
        if pre:
            st = (a * st + c) % mod
        out[k] = st if shift is None else (st >> shift) & 255
        if not pre:
            st = (a * st + c) % mod
    return out


def _ovs_vars(node, acc):
    if not isinstance(node, tuple):
        return acc
    if node[0] == "v":
        acc.add(node[1])
    elif node[0] == "f":
        acc.add("f:" + node[1])
        for a in node[2]:
            _ovs_vars(a, acc)
    elif node[0] == "idx":
        acc.update({node[1], "idx"})
        _ovs_vars(node[2], acc)
    else:
        for a in node[1:]:
            _ovs_vars(a, acc)
    return acc


_OVS_BYTE = {"byte", "b", "x", "c", "p", "packed", "in", "cipher", "input", "enc", "ch", "packed_byte", "data"}
_OVS_IDX = {"i", "idx", "index", "pos", "n", "j"}


def _ovs_eval(node, env):
    k = node[0]
    if k == "n":
        return node[1]
    if k == "v":
        return env[node[1]]
    if k == "~":
        return ~_ovs_eval(node[1], env) & 255
    if k == "neg":
        return -_ovs_eval(node[1], env)
    if k == "idx":
        seq = env[node[1]]
        seq = seq if isinstance(seq, (bytes, bytearray, list)) else bytes([seq & 255])
        return seq[_ovs_eval(node[2], env) % len(seq)]
    if k == "f":
        nm, a = node[1], node[2]
        if nm in ("ror8", "ror", "rotr", "rotr8", "rol8", "rol", "rotl", "rotl8"):
            x, r = _ovs_eval(a[0], env) & 255, _ovs_eval(a[1], env) & 7
            return _ror8(x, r) if "r" == nm[2] or nm.startswith("rotr") else _ror8(x, (8 - r) & 7)
        if nm in ("swap", "nibswap", "swap_nibbles", "nibble_swap", "swapnib", "nswap"):
            x = _ovs_eval(a[0], env) & 255
            return ((x << 4) | (x >> 4)) & 255
        if nm == "not":
            return ~_ovs_eval(a[0], env) & 255
        if nm in ("rc4", "lcg", "ks", "keystream"):
            return env["_ks:" + repr(node)][env["i"]]
        if nm in ("u8", "byte", "low8", "lo8"):
            return _ovs_eval(a[0], env) & 255
        raise KeyError(nm)
    x, y = _ovs_eval(node[1], env), _ovs_eval(node[2], env)
    if k == "^":
        return x ^ y
    if k == "+":
        return x + y
    if k == "-":
        return x - y
    if k == "*":
        return x * y
    if k == "%":
        return x % y if y else 0
    if k == "/":
        return x // y if y else 0
    if k == "&":
        return x & y
    if k == "|":
        return x | y
    if k == "<<":
        return x << (y & 63)
    if k == ">>":
        return x >> (y & 63)
    raise KeyError(k)


def _ovs_ks_nodes(node, acc, parent=None):
    if isinstance(node, tuple):
        if node[0] == "f" and node[1] in ("rc4", "lcg", "ks", "keystream"):
            acc.append((node, parent))
        for a in (node[2] if node[0] == "f" else node[1:]):
            _ovs_ks_nodes(a, acc, node)
    return acc


def _ovs_rle(b, swap):
    out = bytearray()
    if len(b) % 2:
        return None
    for k in range(0, len(b), 2):
        cnt, v = (b[k + 1], b[k]) if swap else (b[k], b[k + 1])
        out += bytes([v]) * cnt
        if len(out) > 1 << 24:
            return None
    return bytes(out)


def _ovs_packbits(b):
    """Apple/TIFF PackBits: n in 0..127 -> copy n+1 literals, 129..255 -> repeat the next byte 257-n times, 128 nop."""
    out, k = bytearray(), 0
    while k < len(b):
        n = b[k]
        k += 1
        if n < 128:
            if k + n + 1 > len(b):
                return None
            out += b[k:k + n + 1]
            k += n + 1
        elif n > 128:
            if k >= len(b):
                return None
            out += bytes([b[k]]) * (257 - n)
            k += 1
        if len(out) > 1 << 24:
            return None
    return bytes(out)


def _ovs_decomp(name, b):
    import lzma, bz2
    try:
        if name == "zlib":
            return [zlib.decompress(b)]
        if name == "deflate":
            return [zlib.decompress(b, -15)]
        if name == "gzip":
            return [zlib.decompress(b, 31)]
        if name == "lzma":
            return [x for x in (_lzma_any(b), lzma86_decompress(b), lzma_raw_decompress(b)) if x][:1]
        if name == "bz2":
            return [bz2.decompress(b)]
        if name == "rle":
            return [x for x in (_ovs_rle(b, False), _ovs_rle(b, True), _ovs_packbits(b)) if x]
        if name == "packbits":
            return [x for x in (_ovs_packbits(b),) if x]
        if name == "lz4":
            return [x for x in (_lz4_frame(b), lz4_block_decompress(b)) if x]
        if name in ("lzma-raw", "lzma86"):
            return [x for x in (lzma86_decompress(b), lzma_raw_decompress(b)) if x]
        if name in PACKER_DECODERS:
            return [x for x in (PACKER_DECODERS[name](b),) if x]
        if name == "zstd":
            import zstandard
            return [zstandard.ZstdDecompressor().decompress(b, max_output_size=1 << 24)]
    except Exception:  # noqa: BLE001
        pass
    return []


# --- packer decompressors (aPLib / LZNT1 / LZSS / LZ4 block / raw LZMA / LZMA86) -------------------------------------
# Pure-Python decoders for the compressors real packers put in front of (or behind) an overlay's byte transform. Each
# takes bytes and returns bytes (capped at `cap`) or None on a malformed / truncated stream -- never raises.
# packer_decompress(data) tries them in magic order (AP32 header / LZNT1 chunk signature / xz / LZMA-alone / LZMA86 /
# lz4 frame first, then the headerless ones); packer_hcfg(data) keeps the first output holding a crc-valid HCFG.
PACKER_CAP = 1 << 24


def aplib_depack(b, cap=PACKER_CAP):
    """aPLib depack (Joergen Ibsen's depack.c); an 'AP32' safe header (24 B: tag, hdr size, packed size/crc, orig
    size/crc) is skipped and its packed size honoured."""
    try:
        b = bytes(b)
        if b[:4] == b"AP32" and len(b) >= 24:
            hs, ps = struct.unpack_from("<II", b, 4)
            b = b[hs:hs + ps] if 24 <= hs <= len(b) else b[24:]
        out = bytearray(b[:1])
        if not b:
            return None
        st = [1, 0, 0]   # src index, tag, bits left

        def bit():
            if not st[2]:
                st[1], st[0], st[2] = b[st[0]], st[0] + 1, 8
            st[2] -= 1
            return (st[1] >> st[2]) & 1

        def gamma():
            v = 1
            while True:
                v = (v << 1) + bit()
                if not bit():
                    return v

        def copy(off, n):
            if not 0 < off <= len(out) or len(out) + n > cap:
                raise ValueError
            for _ in range(n):
                out.append(out[-off])

        r0, lwm = 0, 0
        while True:
            if not bit():
                out.append(b[st[0]])
                st[0] += 1
                lwm = 0
            elif not bit():
                off = gamma()
                if not lwm and off == 2:
                    copy(r0, gamma())
                else:
                    off = ((off - (2 if lwm else 3)) << 8) + b[st[0]]
                    st[0] += 1
                    n = gamma() + (off >= 32000) + (off >= 1280) + (2 if off < 128 else 0)
                    copy(off, n)
                    r0 = off
                lwm = 1
            elif not bit():
                c = b[st[0]]
                st[0] += 1
                if not c >> 1:
                    return bytes(out)
                copy(c >> 1, 2 + (c & 1))
                r0, lwm = c >> 1, 1
            else:
                off = 0
                for _ in range(4):
                    off = (off << 1) + bit()
                if off:
                    copy(off, 1)
                else:
                    out.append(0)
                lwm = 0
            if len(out) > cap:
                return None
    except Exception:  # noqa: BLE001 - truncated / not aPLib
        return None


def lznt1_decompress(b, cap=PACKER_CAP):
    """Windows LZNT1 (RtlDecompressBuffer COMPRESSION_FORMAT_LZNT1): 4 KiB chunks behind a u16 header
    (size-1 in bits 0-11, signature 3 in bits 12-14, compressed flag bit 15); a 0 header ends the stream."""
    try:
        b, out, i = bytes(b), bytearray(), 0
        while i + 2 <= len(b):
            h = b[i] | b[i + 1] << 8
            i += 2
            if not h:
                break
            if (h >> 12) & 7 != 3:
                return None
            ch = b[i:i + (h & 0xFFF) + 1]
            i += (h & 0xFFF) + 1
            if not h & 0x8000:
                out += ch
                continue
            cs, j = len(out), 0
            while j < len(ch):
                fl = ch[j]
                j += 1
                for _ in range(8):
                    if j >= len(ch):
                        break
                    if not fl & 1:
                        out.append(ch[j])
                        j += 1
                    else:
                        tok = ch[j] | ch[j + 1] << 8
                        j += 2
                        p, sh = len(out) - cs - 1, 12
                        while p >= 0x10:
                            p >>= 1
                            sh -= 1
                        off, n = (tok >> sh) + 1, (tok & ((1 << sh) - 1)) + 3
                        if off > len(out) - cs:
                            return None
                        for _ in range(n):
                            out.append(out[-off])
                    fl >>= 1
            if len(out) > cap:
                return None
        return bytes(out) if out else None
    except Exception:  # noqa: BLE001
        return None


def lzss_decompress(b, cap=PACKER_CAP, n=4096, f=18, threshold=2, fill=0x20):
    """Okumura LZSS (lzss.c): 4096-byte ring pre-filled with `fill` (0x20), r = N-F; flag byte LSB first, bit 1 =
    literal, bit 0 = 2-byte ref (pos = b0 | (b1 & 0xF0) << 4, len = (b1 & 0x0F) + threshold + 1)."""
    try:
        b, out, ring, r, i = bytes(b), bytearray(), bytearray([fill]) * n, n - f, 0
        while i < len(b):
            fl = b[i]
            i += 1
            for _ in range(8):
                if i >= len(b):
                    break
                if fl & 1:
                    c = b[i]
                    i += 1
                    out.append(c)
                    ring[r] = c
                    r = (r + 1) & (n - 1)
                else:
                    if i + 1 >= len(b):
                        break
                    p, k = b[i] | (b[i + 1] & 0xF0) << 4, (b[i + 1] & 0x0F) + threshold + 1
                    i += 2
                    for x in range(k):
                        c = ring[(p + x) & (n - 1)]
                        out.append(c)
                        ring[r] = c
                        r = (r + 1) & (n - 1)
                fl >>= 1
            if len(out) > cap:
                return None
        return bytes(out) if out else None
    except Exception:  # noqa: BLE001
        return None


def lz4_block_decompress(b, cap=PACKER_CAP):
    """LZ4 block format (no frame): token hi nibble = literal count, lo = match len - 4 (15 -> +255-run bytes),
    u16le offset; the last sequence is literals only."""
    try:
        b, out, i = bytes(b), bytearray(), 0
        if b[:4] == b"\x04\x22\x4d\x18":
            return None
        while i < len(b):
            t = b[i]
            i += 1
            n = t >> 4
            if n == 15:
                while True:
                    n += b[i]
                    i += 1
                    if b[i - 1] != 255:
                        break
            if i + n > len(b):
                return None
            out += b[i:i + n]
            i += n
            if i >= len(b):
                break
            off = b[i] | b[i + 1] << 8
            i += 2
            m = (t & 15) + 4
            if (t & 15) == 15:
                while True:
                    m += b[i]
                    i += 1
                    if b[i - 1] != 255:
                        break
            if not 0 < off <= len(out) or len(out) + m > cap:
                return None
            if off >= m:
                out += out[-off:len(out) - off + m]
            else:
                for _ in range(m):
                    out.append(out[-off])
        return bytes(out) if out else None
    except Exception:  # noqa: BLE001
        return None


def lzma_raw_decompress(b, cap=PACKER_CAP, lc=3, lp=0, pb=2, dict_size=1 << 16):
    """Headerless LZMA1 (FORMAT_RAW, lc3/lp0/pb2, 64 KiB dictionary by default); the stream may lack an end marker."""
    import lzma
    try:
        d = lzma.LZMADecompressor(lzma.FORMAT_RAW, filters=[{"id": lzma.FILTER_LZMA1, "lc": lc, "lp": lp, "pb": pb,
                                                              "dict_size": dict_size}])
        out = d.decompress(bytes(b), cap)
        return out or None
    except Exception:  # noqa: BLE001
        return None


def lzma86_decompress(b, cap=PACKER_CAP):
    """LZMA86 (7-Zip's Lzma86Enc): u8 filter flag (0 none / 1 BCJ x86) | 5 props | u64le unpacked size | LZMA1."""
    import lzma
    try:
        b = bytes(b)
        if len(b) < 14 or b[0] > 1 or b[1] >= 225:
            return None
        size = struct.unpack_from("<Q", b, 6)[0]
        if size > cap and size != (1 << 64) - 1:
            return None
        lz = lzma._decode_filter_properties(lzma.FILTER_LZMA1, b[1:6])
        filters = ([{"id": lzma.FILTER_X86}] if b[0] else []) + [lz]
        out = lzma.LZMADecompressor(lzma.FORMAT_RAW, filters=filters).decompress(b[14:], min(size, cap))
        return out if out and (size == (1 << 64) - 1 or len(out) == size) else None
    except Exception:  # noqa: BLE001
        return None


def _lzma_any(b, cap=PACKER_CAP):
    import lzma
    try:
        d = lzma.LZMADecompressor()
        return d.decompress(bytes(b), cap) or None
    except Exception:  # noqa: BLE001
        return None


def _lz4_frame(b, cap=PACKER_CAP):
    try:
        import lz4.frame
        out = lz4.frame.decompress(bytes(b))
        return out if len(out) <= cap else None
    except Exception:  # noqa: BLE001
        return None


PACKER_DECODERS = {"aplib": aplib_depack, "lznt1": lznt1_decompress, "lzss": lzss_decompress,
                   "lz4block": lz4_block_decompress, "lz4": _lz4_frame, "lzma": _lzma_any, "lzma-raw": lzma_raw_decompress,
                   "lzma86": lzma86_decompress, "packbits": lambda b, cap=PACKER_CAP: _ovs_packbits(bytes(b))}


def packer_order(b):
    """Decoder names for `b`, most likely first: magic-identified formats, then the headerless ones."""
    b = bytes(b[:16])
    first = []
    if b[:4] == b"AP32":
        first.append("aplib")
    if b[:4] == b"\x04\x22\x4d\x18":
        first.append("lz4")
    if b[:6] == b"\xfd7zXZ\0" or (b[:1] == b"\x5d" and len(b) >= 13):
        first.append("lzma")
    if len(b) >= 14 and b[0] <= 1 and b[1] == 0x5d:
        first.append("lzma86")
    if len(b) >= 2 and (b[1] >> 4) & 7 == 3:
        first.append("lznt1")
    if b[:1] == b"H":   # aPLib copies the first byte verbatim: an HCFG record starts with 'H'
        first.append("aplib")
    if b[:1] == b"\x5d":
        first.append("lzma-raw")
    rest = ["lz4block", "aplib", "lzss", "lzma-raw", "lznt1", "packbits"]
    return list(dict.fromkeys(first + rest))


def packer_decompress(data, name=None, cap=PACKER_CAP):
    """[(decoder name, output)] for every decoder (or just `name`) that decodes `data`, in packer_order. Never raises."""
    try:
        names = [name] if name else packer_order(data)
        res = []
        for nm in names:
            fn = PACKER_DECODERS.get(nm)
            out = fn(data, cap) if fn else None
            if out:
                res.append((nm, out))
        return res
    except Exception:  # noqa: BLE001
        return []


def packer_hcfg(data, name=None):
    """(decoder name, decompressed bytes, HcfgHit) for the first decoder whose output holds a crc-valid HCFG record
    (hcfg_find on outputs up to 4 MiB that contain the magic), else None."""
    try:
        for nm, out in packer_decompress(data, name):
            if out.find(HCFG_MAGIC) >= 0 and len(out) <= 1 << 22:
                h = hcfg_find(out)
                if h:
                    return nm, out, h
        return None
    except Exception:  # noqa: BLE001
        return None


def overlay_spec_unpack(data, spec, *, max_bytes=1 << 22):
    """Apply an overlay_spec() to `data`: (offset, size, header {name: value}, out, hash_ok) for the first magic
    occurrence (per spec['which'], newest first for 'any') whose output verifies the stored hash (or, when the question
    names no hash, starts with b'HCFG'); size = len(data) - offset. None when nothing verifies -- never a guess."""
    try:
        return _overlay_spec_unpack(data, spec, max_bytes)
    except Exception:  # noqa: BLE001 - truncated / hostile input
        return None


def _ovs_read(data, o, fmt):
    if fmt.startswith("bytes["):
        n = int(fmt[6:-1])
        if o + n > len(data):
            raise ValueError
        return data[o:o + n]
    st, n = _OVS_FMT[fmt]
    return struct.unpack_from(st, data, o)[0]


def _overlay_spec_unpack(data, spec, max_bytes):
    import hashlib
    if not spec or not spec.get("magic") or (spec.get("expr") is None and not spec.get("decompress")):
        return None
    mg = spec["magic"].encode()
    occ, o = [], data.rfind(mg)
    while o >= 0 and len(occ) < 64:
        occ.append(o)
        o = data.rfind(mg, 0, o)
    if spec.get("which") == "last":
        occ = occ[:1]
    elif spec.get("which") == "first":
        f = data.find(mg)
        occ = [f] if f >= 0 else []
    for o in occ:
        r = _ovs_try(data, o, spec, max_bytes, hashlib)
        if r:
            return r
    return None


def _ovs_try(data, o, spec, max_bytes, hashlib):
    try:
        hdr = {k: _ovs_read(data, o + off, fmt) for k, (off, fmt) in spec["fields"].items()}
    except Exception:  # noqa: BLE001 - header past EOF
        return None
    ends = [off + (int(fmt[6:-1]) if fmt.startswith("bytes[") else _OVS_FMT[fmt][1])
            for off, fmt in spec["fields"].values()]
    d0 = o + (spec["data_off"] if spec.get("data_off") is not None else max(ends + [len(spec["magic"])]))
    n = hdr.get(spec["length"]) if spec.get("length") else None
    if n is not None and (n > max_bytes or d0 + n > len(data)):
        return None
    pk = data[d0:d0 + n] if n is not None else data[d0:d0 + max_bytes]
    hs = spec.get("hash")
    want = hdr.get("hash") if hs else None

    def ok(b):
        if hs is None:
            return b[:4] == HCFG_MAGIC
        a = hs[0]
        if a == "crc32":
            return (zlib.crc32(b) & 0xFFFFFFFF) == (want if isinstance(want, int) else int.from_bytes(want, "little"))
        return getattr(hashlib, a)(b).digest() == want

    if hs and hs[2] == "packed" and not ok(pk):
        return None
    for out in _ovs_candidates(pk, hdr, spec):
        dec = [d for nm in spec.get("decompress") or () for d in _ovs_decomp(nm, out)]
        if hs and hs[2] == "packed":    # the hash vouches for the packed bytes only: the record must sit at 0
            fin = next((f for f in dec + [out] if f[:4] == HCFG_MAGIC), None)
        elif dec and ok(out):           # hash over the transformed (still compressed) bytes
            fin = dec[0]
        else:
            fin = next((f for f in dec + [out] if ok(f)), None)
        if fin is not None:
            return (o, len(data) - o, hdr, fin, True if hs else None)
    return None


def _ovs_candidates(pk, hdr, spec):
    """Every hash-gated reading of the spec's transform over the packed bytes (generator; bounded). A per-block
    reversal ('reverse each 16-byte block') is undone either before or after the byte transform."""
    bl = spec.get("blocks")
    bs = (hdr.get(bl) if isinstance(bl, str) else bl) if bl else None
    if not isinstance(bs, int) or not 1 < bs <= 1 << 16:
        yield from _ovs_cands(pk, hdr, spec)
        return

    def rb(b):
        return b"".join(b[k:k + bs][::-1] for k in range(0, len(b), bs))
    yield from _ovs_cands(rb(pk), hdr, spec)
    for out in _ovs_cands(pk, hdr, spec):
        yield rb(out)


_OVS_OUT = {"plain", "out", "unpacked", "result", "dec", "decoded", "o", "plain_byte", "out_byte"}
_OVS_PFX = {"zlib": lambda b: len(b) > 1 and b[0] & 15 == 8 and ((b[0] << 8) | b[1]) % 31 == 0,
            "gzip": lambda b: b[:2] == b"\x1f\x8b", "lzma": lambda b: b[:1] == b"\x5d" or b[:6] == b"\xfd7zXZ\0",
            "bz2": lambda b: b[:3] == b"BZh", "zstd": lambda b: b[:4] == b"\x28\xb5\x2f\xfd",
            "lz4": lambda b: b[:4] == b"\x04\x22\x4d\x18", "aplib": lambda b: b[:1] == b"H" or b[:4] == b"AP32",
            "lznt1": lambda b: len(b) > 1 and (b[1] >> 4) & 7 == 3, "lzma-raw": lambda b: b[:1] in (b"\0", b"\1")}


def _ovs_cands(pk, hdr, spec):
    expr = spec.get("expr")
    revs = {None: [False], "in": ["in"], "out": ["out"], "?": [False, "in", "out"]}[spec.get("reverse")]
    if expr is None:
        for rv in revs:
            yield pk[::-1] if rv else pk
        return
    upd = spec.get("update")
    stv = upd[0] if upd else None
    vs = _ovs_vars(expr, set()) | (_ovs_vars(upd[1], set()) if upd else set())
    env0 = {}
    for k, v in hdr.items():
        env0[k] = v
        if isinstance(v, (bytes, bytearray)):
            env0["len_" + k] = len(v)
    keyf = next((k for k, v in hdr.items() if isinstance(v, (bytes, bytearray)) and k != "hash"), None)
    for nm in ("len", "keylen", "klen", "key_len", "key_length"):
        env0.setdefault(nm, len(hdr[keyf]) if keyf else 1)
    if "key" not in env0 and keyf and stv != "key":
        env0["key"] = hdr[keyf]
    unknown = {v for v in vs if not v.startswith("f:") and v != "idx" and v not in env0 and v not in _OVS_BYTE
               and v not in _OVS_IDX and not v.startswith("prev") and v != stv and v not in _OVS_OUT}
    # known-plaintext fallback: ONE unstated byte value (a key/seed the question names but no header field holds,
    # or a rolling key's unstated start) is recovered from out[:4] == b'HCFG', ver 1 -- the hash still gates it.
    inits = [None]
    guess = None
    if stv:
        ini = spec.get("init")
        iv = ini if isinstance(ini, int) else env0.get(ini) if ini else env0.get(stv)
        if isinstance(iv, int):
            inits = [iv]
        else:
            inits = list(dict.fromkeys([v for v in hdr.values() if isinstance(v, int)] + list(range(256))))
            guess = stv
    if unknown:
        if len(unknown) > 1 or guess:
            return
        guess = unknown.pop()
    if guess and len(pk) > 1 << 16:
        return
    ksn = _ovs_ks_nodes(expr, [])
    chain = any(v.startswith("prev") for v in vs)
    simple = not ksn and not chain and not (vs & _OVS_IDX) and "idx" not in vs and not stv
    # keystream variants (LCG output byte is the only prose ambiguity; RC4 is fixed)
    ksv = [{}]
    for node, parent in ksn:
        try:
            args = [_ovs_eval(a, env0) for a in node[2]]
        except KeyError:
            return
        nn = len(pk)
        if node[1] == "rc4" or (node[1] in ("ks", "keystream") and args and isinstance(args[0], bytes)):
            key = args[0] if isinstance(args[0], (bytes, bytearray)) else int(args[0]).to_bytes(
                max(1, (int(args[0]).bit_length() + 7) // 8), "little")
            alts = [_ovs_rc4(bytes(key), nn)]
        elif node[1] == "lcg" and len(args) >= 3:
            seed, a, c = (int(x) for x in args[:3])
            mod = int(args[3]) if len(args) > 3 else 1 << 32
            raw = parent is not None and parent[0] in (">>", "&", "%")
            alts = [_ovs_lcg(seed, a, c, nn, mod, None, pre) for pre in (True, False)] if raw else \
                [_ovs_lcg(seed, a, c, nn, mod, sh, pre) for sh in (24, 16, 0, 8) for pre in (True, False)
                 if sh < mod.bit_length()]
        else:
            return
        ksv = [dict(d, **{"_ks:" + repr(node): s}) for d in ksv for s in alts][:16]
    prevs = [None]
    if chain:
        prevs = list(dict.fromkeys([hdr[k] & 255 for k in ("iv", "init", "prev", "seed") if isinstance(
            hdr.get(k), int)] + [0] + [v & 255 for v in hdr.values() if isinstance(v, int)]))[:6]
    if len(pk) > (1 << 22 if simple else 1 << 18):
        return
    masks = [None] if not upd or upd[1][0] in ("%", "&") else [255, 0xFFFFFFFF]
    pfx = [_OVS_PFX[d] for d in spec.get("decompress") or () if d in _OVS_PFX]
    hcfg_len = not spec.get("decompress")

    def plausible(b, full):
        if pfx:
            return any(f(b) for f in pfx)
        if spec.get("decompress"):
            return True
        return b[:4] == HCFG_MAGIC and b[4:5] == b"\x01" and (
            not full or not hcfg_len or struct.unpack_from("<H", b, 6)[0] == len(b) - 12)

    def run(src, env, pv, st, mask, cprev, lim):
        out = bytearray(min(len(src), lim))
        pc = pp = pv if pv is not None else 0
        for i in range(len(out)):
            b = src[i]
            for nm in _OVS_BYTE:
                env[nm] = b
            for nm in _OVS_IDX:
                env[nm] = i
            if cprev:
                env["prev"] = env["prev_cipher"] = pc
                env["prev_plain"] = env["prev_out"] = 0
            else:
                env["prev_cipher"] = env["prev_in"] = env["prev_packed"] = env["prev_enc"] = pc
                env["prev_plain"] = env["prev_out"] = env["prev"] = pp
            if stv:
                env[stv] = st
            out[i] = _ovs_eval(expr, env) & 255
            pc, pp = b, out[i]
            if stv:   # the rolling key steps AFTER the byte; 'previous' there is the byte just processed
                for nm in _OVS_OUT:
                    env[nm] = pp
                env["prev_cipher"] = env["prev_in"] = env["prev_packed"] = env["prev_enc"] = pc
                env["prev_plain"] = env["prev_out"] = env["prev"] = pc if cprev else pp
                st = _ovs_eval(upd[1], env)
                st = st & mask if mask else st & ((1 << 64) - 1)
        return bytes(out)

    gvals = range(256) if guess and guess != stv else [None]
    for rv in revs:
        src = pk[::-1] if rv == "in" else pk
        for gv in gvals:
            e0 = dict(env0, **({guess: gv} if gv is not None else {}))
            if simple:
                if gv is not None and not plausible(run(src, dict(e0), None, None, None, False, 12), False):
                    continue
                env = dict(e0)
                tab = bytearray(256)
                for b in range(256):
                    for nm in _OVS_BYTE:
                        env[nm] = b
                    tab[b] = _ovs_eval(expr, env) & 255
                out = src.translate(bytes(tab))
                yield out[::-1] if rv == "out" else out
                continue
            for ks in ksv:
                for pv in prevs:
                    for cprev in ([False, True] if "prev" in vs else [False]):
                        for st0 in inits:
                            for mask in masks:
                                if (guess and rv != "out" and not plausible(run(src, dict(e0, **ks), pv, st0, mask,
                                                                                 cprev, 12), False)):
                                    continue
                                out = run(src, dict(e0, **ks), pv, st0, mask, cprev, len(src))
                                yield out[::-1] if rv == "out" else out


# --- Go / Rust symbol recovery -------------------------------------------------------------------
def go_buildinfo(data):
    """Go version string from the `\\xff Go buildinf:` blob (present even when stripped), or None."""
    m = re.search(rb"go1\.\d+(\.\d+)?", data)
    return m.group(0).decode() if m else None


def go_pclntab_funcs(data, limit=4000):
    """Recover Go function names from .gopclntab — they survive symbol stripping. Version-agnostic: pulls
    the section (or scans for the pclntab magic) and extracts Go-symbol-shaped null-terminated strings
    (package-qualified: main.*, runtime.*, path/pkg.*). Returns a sorted de-duped list."""
    from elftools.elf.elffile import ELFFile
    blob = b""
    try:
        elf = ELFFile(io.BytesIO(data))
        for sname in (".gopclntab", ".data.rel.ro.gopclntab", ".data.rel.ro"):
            s = elf.get_section_by_name(sname)
            if s:
                blob += s.data()
    except Exception:  # noqa: BLE001 - not an ELF / no sections: fall back to a raw magic scan
        pass
    if not blob:
        for magic in (b"\xf0\xff\xff\xff", b"\xf1\xff\xff\xff", b"\xfa\xff\xff\xff", b"\xfb\xff\xff\xff"):
            i = data.find(magic)
            if i >= 0:
                blob = data[i:i + 4_000_000]
                break
    names = set()
    # Go symbol names: package-path-qualified, ASCII, contain a '.', may carry * ( ) [ ] / and digits.
    for m in re.finditer(rb"[A-Za-z_][\w./*()\[\]<>,;$-]{2,120}", blob):
        s = m.group(0)
        try:
            t = s.decode("ascii")
        except UnicodeDecodeError:
            continue
        if "." in t and ("/" in t or t.split(".")[0] in ("main", "runtime", "fmt", "os", "net", "sync",
                                                          "internal", "crypto", "encoding", "reflect")
                         or re.match(r"^[a-z][\w]*\.[A-Za-z]", t)):
            names.add(t)
    return sorted(names)[:limit]


def rustfilt(symbol):
    """Demangle a Rust v0/legacy symbol if `rustfilt` is on PATH, else return it unchanged."""
    if not shutil.which("rustfilt"):
        return symbol
    r = subprocess.run(["rustfilt"], input=symbol, capture_output=True, text=True, timeout=10)
    return r.stdout.strip() or symbol


# --- Mach-O --------------------------------------------------------------------------------------
def macho_facts(data):
    """Header facts for a Mach-O (fat or thin): macho_layout() (pure struct: machine(s), sections, has_hcfg_section,
    every slice) enriched by lief (first slice: cpu type, file type, flags, dylibs, entry). {} if not a Mach-O."""
    lay = macho_layout(data)
    if not lay:
        return {}
    out = dict(lay)
    try:
        import lief
        try:
            lief.logging.disable()
        except Exception:  # noqa: BLE001
            pass
        fat = lief.MachO.parse(bytes(data))
        if fat is not None and fat.size:
            b = fat.at(0)
            h = b.header
            out.update({
                "cpu_type": str(h.cpu_type).split(".")[-1].lower(),
                "file_type": str(h.file_type).split(".")[-1].lower(),
                "nb_cmds": h.nb_cmds,
                "pie": bool(h.has(lief.MachO.Header.FLAGS.PIE)) if hasattr(h, "has") else None,
                "libraries": [lib.name for lib in b.libraries][:40],
                "entrypoint": hex(b.entrypoint) if hasattr(b, "entrypoint") else None,
            })
    except Exception:  # noqa: BLE001  (lief missing / API drift / malformed: keep the struct facts)
        pass
    return out


_MO_MAGIC = {b"\xce\xfa\xed\xfe": ("little", 32), b"\xcf\xfa\xed\xfe": ("little", 64),
             b"\xfe\xed\xfa\xce": ("big", 32), b"\xfe\xed\xfa\xcf": ("big", 64)}


def _macho_thin(data, base=0):
    """One thin Mach-O slice at data[base:] -> {machine, machine_num, cputype, endian, bits, slice_offset, sections:
    [{segment, section, name "SEG,sect", offset (file offset, fat-absolute), size}]} or None. Pure struct, bounded."""
    mo = _MO_MAGIC.get(bytes(data[base:base + 4]))
    if not mo or len(data) < base + 28:
        return None
    end, bits = mo
    u32 = lambda o: int.from_bytes(data[o:o + 4], end)   # noqa: E731
    cpu, ncmds, sizeofcmds = u32(base + 4), u32(base + 16), u32(base + 20)
    p = base + (32 if bits == 64 else 28)
    stop = min(len(data), p + sizeofcmds)
    secs = []
    for _ in range(min(ncmds, 4096)):
        if p + 8 > stop:
            break
        cmd, size = u32(p), u32(p + 4)
        if size < 8:
            break
        if cmd in (0x1, 0x19):   # LC_SEGMENT / LC_SEGMENT_64
            w = 8 if cmd == 0x19 else 4
            nsects = u32(p + 24 + 4 * w + 8)
            q, ssz = p + 24 + 4 * w + 16, 80 if w == 8 else 68   # section_64 / section
            for _ in range(min(nsects, 1024)):
                if q + ssz > min(stop, p + size):
                    break
                sect = bytes(data[q:q + 16]).split(b"\0")[0].decode("latin-1")
                seg = bytes(data[q + 16:q + 32]).split(b"\0")[0].decode("latin-1")
                sz = int.from_bytes(data[q + 32 + w:q + 32 + 2 * w], end)
                off = u32(q + 32 + 2 * w)
                secs.append({"segment": seg, "section": sect, "name": f"{seg},{sect}",
                             "offset": base + off if off else 0, "size": sz, "flags": u32(q + 48 + 2 * w)})
                q += ssz
        p += size
    return {"machine": MACHO_CPU_LABEL.get(cpu, str(cpu)), "machine_num": str(cpu), "cputype": f"0x{cpu:08x}",
            "endian": end, "bits": bits, "slice_offset": base, "sections": secs}


def macho_layout(data):
    """Pure-struct Mach-O facts for thin AND fat/universal files: {format "mach-o", fat, slices [_macho_thin...],
    machine / machine_num / bits (first slice), machines (every slice), section_names ["__DATA,__hcfg", ...] and
    section_names_short ["__hcfg", ...] over all slices, has_hcfg_section "true"/"false" (a section whose sectname is
    __hcfg / .hcfg / hcfg, any segment)}; None if not a Mach-O. A Java .class shares the fat magic 0xcafebabe: it is
    rejected because its u32 at +4 (minor<<16|major, major >= 45) is not a small slice count and/or its "fat_arch"
    entries do not point inside the file at a thin Mach-O."""
    try:
        data = memoryview(data) if not isinstance(data, memoryview) else data
        slices, fat = [], False
        head = bytes(data[:4])
        if head in (b"\xca\xfe\xba\xbe", b"\xca\xfe\xba\xbf"):
            n = int.from_bytes(data[4:8], "big")
            if not 0 < n < 32:
                return None
            w = 32 if head[3] == 0xbf else 20   # fat_arch_64 / fat_arch
            for k in range(n):
                e = 8 + k * w
                if e + w > len(data):
                    return None
                off = int.from_bytes(data[e + 8:e + 16] if w == 32 else data[e + 8:e + 12], "big")
                s = _macho_thin(data, off) if 0 < off < len(data) else None
                if s is not None:   # a truncated tail slice is skipped; no thin slice at all -> not fat (Java)
                    slices.append(s)
            if not slices:
                return None
            fat = True
        else:
            s = _macho_thin(data)
            if s is None:
                return None
            slices.append(s)
        names = [x["name"] for s in slices for x in s["sections"]]
        short = [x["section"] for s in slices for x in s["sections"]]
        return {"format": "mach-o", "fat": fat, "slices": slices, "machine": slices[0]["machine"],
                "machine_num": slices[0]["machine_num"], "bits": slices[0]["bits"],
                "machines": [s["machine"] for s in slices],
                "section_names": list(dict.fromkeys(names)), "section_names_short": list(dict.fromkeys(short)),
                "has_hcfg_section": "true" if any(x.lstrip("_.").lower() == "hcfg" for x in short) else "false"}
    except (IndexError, ValueError, TypeError):
        return None


def macho_hcfg_section(data):
    """[(slice machine, file offset, bytes)] of every __hcfg-named section in a thin/fat Mach-O ([] if none)."""
    lay = macho_layout(data) or {}
    out = []
    for s in lay.get("slices", ()):
        for x in s["sections"]:
            if x["section"].lstrip("_.").lower() == "hcfg" and x["offset"]:
                out.append((s["machine"], x["offset"], bytes(data[x["offset"]:x["offset"] + x["size"]])))
    return out


_MO_LC_NAMES = {0xc: "LC_LOAD_DYLIB", 0x80000018: "LC_LOAD_WEAK_DYLIB", 0x8000001f: "LC_REEXPORT_DYLIB",
                0x20: "LC_LAZY_LOAD_DYLIB", 0x80000023: "LC_LOAD_UPWARD_DYLIB"}
_MO_FILETYPE = {1: "object", 2: "execute", 3: "fvmlib", 4: "core", 5: "preload", 6: "dylib", 7: "dylinker",
                8: "bundle", 9: "dylib_stub", 10: "dsym", 11: "kext_bundle", 12: "fileset"}


def _mo_arch(cpu, sub):
    """lipo/otool arch name of (cputype, cpusubtype): x86_64 / x86_64h / i386 / arm64 / arm64e / armv7 / ppc ..."""
    sub &= 0xffffff
    if cpu == 0x01000007:
        return "x86_64h" if sub == 8 else "x86_64"
    if cpu == 0x0100000c:
        return "arm64e" if sub == 2 else "arm64"
    if cpu == 0x0200000c:
        return "arm64_32"
    if cpu == 12:
        return {9: "armv7", 11: "armv7s", 12: "armv7k", 6: "armv6"}.get(sub, "arm")
    return {7: "i386", 18: "ppc", 0x01000012: "ppc64"}.get(cpu, str(cpu))


def _mo_ver(v):
    """dylib_command packed version xxxx.yy.zz -> "x.y.z" (otool -L spelling)."""
    return f"{v >> 16}.{(v >> 8) & 0xff}.{v & 0xff}"


def _mo_exports_trie(data, start, size, cap=20000):
    """Exported names of a dyld exports trie (LC_DYLD_INFO export_off / LC_DYLD_EXPORTS_TRIE), preorder DFS in edge
    order = `llvm-objdump --macho --exports-trie` order. Bounded: cyclic / out-of-range nodes are skipped."""
    end, out, seen = start + size, [], set()
    stack = [(0, "")]
    while stack and len(out) < cap and len(seen) < 4 * cap:
        off, pre = stack.pop()
        if off in seen or not 0 <= off < size:
            continue
        seen.add(off)
        p = start + off
        tsz, p = _leb(data, p)
        if tsz:
            out.append(pre)
        p += tsz
        if p >= end:
            continue
        kids, q = [], p + 1
        for _ in range(data[p]):
            e = bytes(data[q:min(end, q + 4096)]).find(b"\0")
            if e < 0:
                break
            edge = bytes(data[q:q + e]).decode("utf-8", "replace")
            nxt, q = _leb(data, q + e + 1)
            kids.append((nxt, pre + edge))
        stack.extend(reversed(kids))
    return out


def macho_link_facts(data):
    """Dynamic-link facts of a thin / fat Mach-O (fat: first slice in fat_arch order, like `otool -L`), pure struct:
    cputype (decimal str "16777223"), cputype_hex, cpusubtype, arch (lipo name x86_64 / arm64 / arm64e ...), machine
    (MACHO_CPU_LABEL x86-64 / AArch64), filetype (execute / dylib / bundle / object ...), dylibs (every dylib-loading
    command in load-command order: LC_LOAD_DYLIB / LC_LOAD_WEAK_DYLIB / LC_REEXPORT_DYLIB / LC_LAZY_LOAD_DYLIB /
    LC_LOAD_UPWARD_DYLIB), dylib_commands ["LC_LOAD_WEAK_DYLIB:@rpath/x.dylib", ...], load_dylibs / weak_dylibs /
    reexport_dylibs, dylib_versions ["path current compat"], rpaths (LC_RPATH order), rpath_dylibs / loader_path_dylibs /
    executable_path_dylibs (dylibs naming @rpath / @loader_path / @executable_path), install_name + current_version /
    compatibility_version (LC_ID_DYLIB), dylinker, exports (exports trie order = llvm-objdump --exports-trie, from
    LC_DYLD_EXPORTS_TRIE or LC_DYLD_INFO[_ONLY]), has_chained_fixups / has_exports_trie / has_dyld_info "true"/"false",
    chained_imports (LC_DYLD_CHAINED_FIXUPS import table order) + chained_weak_imports + chained_imports_qualified
    "lib!sym", has_hcfg_section. Lists also as *_count / *_sorted / *_csv; empty list / absent -> "none". Not a
    Mach-O or unparseable -> None."""
    try:
        lay = macho_layout(data)
        if not lay:
            return None
        base = lay["slices"][0]["slice_offset"]
        end, bits = _MO_MAGIC[bytes(data[base:base + 4])]
        u32 = lambda o: int.from_bytes(data[o:o + 4], end)   # noqa: E731
        cpu, sub, ftype, ncmds, sizeofcmds = (u32(base + k) for k in (4, 8, 12, 16, 20))
        p = base + (32 if bits == 64 else 28)
        stop = min(len(data), p + sizeofcmds)

        def lcstr(lc, size, at):
            o = u32(lc + at)
            return bytes(data[lc + o:lc + size]).split(b"\0")[0].decode("utf-8", "replace") if 0 < o < size else ""
        f = {"format": "mach-o", "cputype": str(cpu), "cputype_hex": f"0x{cpu:08x}", "cpusubtype": str(sub & 0xffffff),
             "arch": _mo_arch(cpu, sub), "machine": MACHO_CPU_LABEL.get(cpu, str(cpu)),
             "archs": [_mo_arch(int(s["machine_num"]), u32(s["slice_offset"] + 8)) for s in lay["slices"]],
             "fat": "true" if lay["fat"] else "false", "filetype": _MO_FILETYPE.get(ftype, str(ftype)),
             "has_hcfg_section": lay["has_hcfg_section"], "install_name": "none", "current_version": "none",
             "compatibility_version": "none", "dylinker": "none"}
        dyl, cmds, vers, rp = [], [], [], []
        by = {v: [] for v in _MO_LC_NAMES.values()}
        trie = info = chained = None
        for _ in range(min(ncmds, 4096)):
            if p + 8 > stop:
                break
            cmd, size = u32(p), u32(p + 4)
            if size < 8:
                break
            if cmd in _MO_LC_NAMES:
                n = lcstr(p, size, 8)
                dyl.append(n)
                cmds.append(f"{_MO_LC_NAMES[cmd]}:{n}")
                by[_MO_LC_NAMES[cmd]].append(n)
                vers.append(f"{n} {_mo_ver(u32(p + 16))} {_mo_ver(u32(p + 20))}")
            elif cmd == 0xd:
                f["install_name"] = lcstr(p, size, 8) or "none"
                f["current_version"], f["compatibility_version"] = _mo_ver(u32(p + 16)), _mo_ver(u32(p + 20))
            elif cmd == 0xe:
                f["dylinker"] = lcstr(p, size, 8) or "none"
            elif cmd == 0x8000001c:
                rp.append(lcstr(p, size, 8))
            elif cmd == 0x80000033:   # LC_DYLD_EXPORTS_TRIE (linkedit_data_command)
                trie = (u32(p + 8), u32(p + 12))
            elif cmd in (0x22, 0x80000022):   # LC_DYLD_INFO[_ONLY]: export_off / export_size at +40
                info = (u32(p + 40), u32(p + 44))
            elif cmd == 0x80000034:   # LC_DYLD_CHAINED_FIXUPS
                chained = (u32(p + 8), u32(p + 12))
            p += size
        f.update({"dylibs": dyl, "dylib_commands": cmds, "load_dylibs": by["LC_LOAD_DYLIB"],
                  "weak_dylibs": by["LC_LOAD_WEAK_DYLIB"], "reexport_dylibs": by["LC_REEXPORT_DYLIB"],
                  "lazy_dylibs": by["LC_LAZY_LOAD_DYLIB"], "upward_dylibs": by["LC_LOAD_UPWARD_DYLIB"],
                  "dylib_versions": vers, "rpaths": rp,
                  "rpath_dylibs": [d for d in dyl if d.startswith("@rpath/")],
                  "loader_path_dylibs": [d for d in dyl if d.startswith("@loader_path/")],
                  "executable_path_dylibs": [d for d in dyl if d.startswith("@executable_path/")],
                  "has_exports_trie": "true" if trie else "false", "has_dyld_info": "true" if info else "false",
                  "has_chained_fixups": "true" if chained else "false"})
        ex, src = [], trie or info
        if src and src[1] and base + src[0] + src[1] <= len(data):
            try:
                ex = _mo_exports_trie(data, base + src[0], src[1])
            except (IndexError, ValueError):
                ex = []
        f["exports"] = ex
        imps, weak, qual = [], [], []
        if chained and chained[1] >= 28 and base + chained[0] + chained[1] <= len(data):
            h = base + chained[0]
            iof, sof, cnt, fmt = u32(h + 8), u32(h + 12), u32(h + 16), u32(h + 20)
            w = {1: 4, 2: 8, 3: 16}.get(fmt)
            for k in range(min(cnt, 100_000) if w else 0):
                o = h + iof + k * w
                if o + w > h + chained[1]:
                    break
                if fmt == 3:
                    v = int.from_bytes(data[o:o + 8], end)
                    lo, wk, no = v & 0xffff, (v >> 16) & 1, v >> 32
                    lo = lo - 0x10000 if lo >= 0xfff0 else lo
                else:
                    v = u32(o)
                    lo, wk, no = v & 0xff, (v >> 8) & 1, v >> 9
                    lo = lo - 0x100 if lo >= 0xf0 else lo
                s = h + sof + no
                e = bytes(data[s:h + chained[1]]).find(b"\0")
                n = bytes(data[s:s + e if e >= 0 else s]).decode("utf-8", "replace")
                imps.append(n)
                if wk:
                    weak.append(n)
                lib = dyl[lo - 1] if 0 < lo <= len(dyl) else {0: "self", -1: "main_executable",
                                                              -2: "flat_lookup", -3: "weak_lookup"}.get(lo, str(lo))
                qual.append(f"{lib}!{n}")
        f.update({"chained_imports": imps, "chained_weak_imports": weak, "chained_imports_qualified": qual})
        for k in [k for k, v in f.items() if isinstance(v, list)]:
            v = f[k]
            f[k + "_count"] = str(len(v))
            f[k + "_sorted"] = sorted(v) or "none"
            f[k + "_csv"] = ",".join(v) or "none"
            f[k] = v or "none"
        for a, b in (("cpu_type", "cputype"), ("libraries", "dylibs"), ("needed", "dylibs"), ("id_dylib", "install_name"),
                     ("exported_symbols", "exports"), ("lc_rpath", "rpaths"), ("file_type", "filetype")):
            f.setdefault(a, f[b])
        return f
    except Exception:  # noqa: BLE001 -- truncated / hostile load commands: cannot answer
        return None


def macho_link_field(data, name):
    """One macho_link_facts value; "none" when the input is not a Mach-O or the field is unknown/absent."""
    try:
        return (macho_link_facts(data) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


WASM_SECTION_NAMES = {0: "custom", 1: "type", 2: "import", 3: "function", 4: "table", 5: "memory", 6: "global",
                      7: "export", 8: "start", 9: "element", 10: "code", 11: "data", 12: "datacount", 13: "tag"}


def _leb(data, p, signed=False, cap=10):
    """(value, next position) of the (s)LEB128 at p; IndexError past the end / ValueError when longer than cap bytes."""
    v = sh = 0
    for _ in range(cap):
        b = data[p]
        p += 1
        v |= (b & 0x7f) << sh
        sh += 7
        if not b & 0x80:
            if signed and b & 0x40:
                v -= 1 << sh
            return v, p
    raise ValueError("leb128 too long")


def wasm_layout(data):
    """Pure-struct WebAssembly module facts: {format "wasm", machine "wasm32" ("wasm64" when a defined/imported
    memory has the memory64 limits flag 0x04; SPECULATIVE label, not GM-verified), version, sections [{id, name,
    offset (payload file offset), size}], section_names (custom sections by their own name), memories [{index,
    memory64, min, max, imported}], data_segments [{index, mode active/passive, memory, mem_offset (int, None when
    the init expr is a global.get e.g. Emscripten __memory_base), file_offset (first payload byte), size}]}; None if
    not a version-1 wasm binary (the '\\0asm' magic alone does not count: every section must parse to the end).
    Plus the _wasm_inventory keys (imports/exports/tables/elems/start/globals/custom_names/...; see wasm_fields)."""
    try:
        data = memoryview(data) if not isinstance(data, memoryview) else data
        if bytes(data[:4]) != b"\0asm" or len(data) < 8 or int.from_bytes(data[4:8], "little") != 1:
            return None
        p, end = 8, len(data)
        secs, mems, segs = [], [], []

        def limits(q):
            fl, q = _leb(data, q)
            mn, q = _leb(data, q)
            mx = None
            if fl & 1:
                mx, q = _leb(data, q)
            if fl & 8:   # custom-page-sizes proposal: page size log2
                q = _leb(data, q)[1]
            return fl, mn, mx, q

        while p < end:
            sid = data[p]
            size, q = _leb(data, p + 1, cap=5)
            if sid > 13 or q + size > end:
                return None
            e = q + size
            name = WASM_SECTION_NAMES[sid]
            if sid == 0:
                n, r = _leb(data, q, cap=5)
                if r + n > e:
                    return None
                name = bytes(data[r:r + n]).decode("utf-8", "replace")
            secs.append({"id": sid, "name": name, "offset": q, "size": size})
            if sid == 2:     # imports: only memory imports matter (memory index space starts with them)
                n, r = _leb(data, q, cap=5)
                for _ in range(n):
                    for _f in range(2):
                        ln, r = _leb(data, r, cap=5)
                        r += ln
                    kind = data[r]
                    r += 1
                    if kind == 0:
                        r = _leb(data, r)[1]
                    elif kind == 1:
                        r = limits(r + 1)[3]
                    elif kind == 2:
                        fl, mn, mx, r = limits(r)
                        mems.append({"index": len(mems), "memory64": bool(fl & 4), "min": mn, "max": mx,
                                     "imported": True, "shared": bool(fl & 2)})
                    elif kind == 3:
                        r += 2
                    elif kind == 4:
                        r = _leb(data, r + 1)[1]
                    else:
                        return None
            elif sid == 5:
                n, r = _leb(data, q, cap=5)
                for _ in range(n):
                    fl, mn, mx, r = limits(r)
                    mems.append({"index": len(mems), "memory64": bool(fl & 4), "min": mn, "max": mx,
                                 "imported": False, "shared": bool(fl & 2)})
            elif sid == 11:
                n, r = _leb(data, q, cap=5)
                for k in range(n):
                    fl, r = _leb(data, r, cap=5)
                    mem, moff = 0, None
                    if fl == 2:
                        mem, r = _leb(data, r, cap=5)
                    if fl in (0, 2):   # active: constant init expr, then 0x0b
                        op = data[r]
                        if op in (0x41, 0x42):          # i32.const / i64.const (sLEB; addresses are unsigned)
                            moff, r = _leb(data, r + 1, signed=True)
                            moff &= (1 << (32 if op == 0x41 else 64)) - 1
                        elif op == 0x23:                # global.get
                            r = _leb(data, r + 1)[1]
                        else:
                            return None
                        while data[r] != 0x0b:          # extended-const tails (i32.add ...): offset unknown
                            moff, r = None, r + 1
                        r += 1
                    elif fl != 1:
                        return None
                    ln, r = _leb(data, r, cap=5)
                    if r + ln > e:
                        return None
                    segs.append({"index": k, "mode": "passive" if fl == 1 else "active", "memory": mem,
                                 "mem_offset": moff, "file_offset": r, "size": ln})
                    r += ln
            p = e
        out = {"format": "wasm", "machine": "wasm64" if any(m["memory64"] for m in mems) else "wasm32",
               "version": 1, "sections": secs, "section_names": [s["name"] for s in secs], "memories": mems,
               "data_segments": segs}
    except (IndexError, ValueError, TypeError):
        return None
    out.update(_wasm_inventory(data, secs))
    return out


WASM_EXTERN_KINDS = {0: "func", 1: "table", 2: "memory", 3: "global", 4: "tag"}
WASM_VALTYPES = {0x7f: "i32", 0x7e: "i64", 0x7d: "f32", 0x7c: "f64", 0x7b: "v128", 0x70: "funcref",
                 0x6f: "externref"}


def _wasm_const(data, q):
    """(value, next position after the 0x0b) of a constant init expr: int for i32/i64.const, ('global', i) for
    global.get, ('func', i) for ref.func, None for ref.null / floats / extended-const arithmetic."""
    val, ops = None, 0
    while True:
        op = data[q]
        q += 1
        if op == 0x0b:
            return (val if ops == 1 else None), q
        ops += 1
        if op in (0x41, 0x42):
            v, q = _leb(data, q, signed=True)
            val = v & ((1 << (32 if op == 0x41 else 64)) - 1)
        elif op == 0x23:
            v, q = _leb(data, q)
            val = ("global", v)
        elif op == 0xd2:
            v, q = _leb(data, q)
            val = ("func", v)
        elif op == 0xd0:
            q = _leb(data, q, signed=True)[1]    # heap type (0x70 / 0x6f or a type index)
            val = None
        elif op == 0x43:
            q += 4
        elif op == 0x44:
            q += 8
        elif op == 0xfd:                          # v128.const
            q = _leb(data, q)[1] + 16
        elif op in (0x6a, 0x6b, 0x6c, 0x7c, 0x7d, 0x7e):   # extended-const add/sub/mul
            pass
        else:
            raise ValueError("init expr op %#x" % op)


def _wasm_name(data, q):
    n, q = _leb(data, q, cap=5)
    return bytes(data[q:q + n]).decode("utf-8", "replace"), q + n


def _wasm_inventory(data, secs):
    """The module's 'doors' (wasm_layout extras): imports [{module, name, kind, index}] (index in its kind's index
    space), import_names ["module.name"] in section order, exports [{name, kind, index}], export_names, tables
    [{index, reftype, min, max, imported}], elems [{index, mode active/passive/declarative, table, offset,
    func_indices (None = ref.null)}], start (func index or None), globals [{index, valtype, mutable, imported,
    init}], type_count, function_count (defined), code_count, data_count (DataCount section or None),
    custom_names, func_names {index: name} (name section, else the linking symbol table), module_name, producers
    {field: [[name, version]]}, inventory_ok (False when some section failed to parse -> fields partial)."""
    imps, exps, tabs, elems, globs, fnames, prod = [], [], [], [], [], {}, {}
    inv = {"imports": imps, "import_names": [], "exports": exps, "export_names": [], "tables": tabs, "elems": elems,
           "start": None, "globals": globs, "type_count": 0, "function_count": 0, "code_count": 0, "data_count": None,
           "custom_names": [s["name"] for s in secs if s["id"] == 0], "func_names": fnames, "module_name": None,
           "producers": prod, "inventory_ok": True}
    cnt = {k: 0 for k in WASM_EXTERN_KINDS.values()}

    def limits(q):
        fl, q = _leb(data, q)
        mn, q = _leb(data, q)
        mx = None
        if fl & 1:
            mx, q = _leb(data, q)
        if fl & 8:
            q = _leb(data, q)[1]
        return mn, mx, q

    def reftype(q):
        b = data[q]
        if b in (0x63, 0x64):                       # (ref null? ht) typed reference
            return "ref", _leb(data, q + 1, signed=True)[1]
        return WASM_VALTYPES.get(b, "0x%02x" % b), q + 1

    for s in secs:
        sid, q = s["id"], s["offset"]
        e = q + s["size"]
        try:
            if sid == 1:
                inv["type_count"] = _leb(data, q, cap=5)[0]
            elif sid == 3:
                inv["function_count"] = _leb(data, q, cap=5)[0]
            elif sid == 10:
                inv["code_count"] = _leb(data, q, cap=5)[0]
            elif sid == 12:
                inv["data_count"] = _leb(data, q, cap=5)[0]
            elif sid == 8:
                inv["start"] = _leb(data, q, cap=5)[0]
            elif sid == 2:
                n, r = _leb(data, q, cap=5)
                for _ in range(n):
                    mod, r = _wasm_name(data, r)
                    nm, r = _wasm_name(data, r)
                    kind = WASM_EXTERN_KINDS.get(data[r], None)
                    r += 1
                    if kind == "func":
                        r = _leb(data, r)[1]
                    elif kind == "table":
                        rt, r = reftype(r)
                        mn, mx, r = limits(r)
                        tabs.append({"index": cnt["table"], "reftype": rt, "min": mn, "max": mx, "imported": True})
                    elif kind == "memory":
                        r = limits(r)[2]
                    elif kind == "global":
                        vt = WASM_VALTYPES.get(data[r], "0x%02x" % data[r])
                        globs.append({"index": cnt["global"], "valtype": vt, "mutable": bool(data[r + 1] & 1),
                                      "imported": True, "init": None})
                        r += 2
                    elif kind == "tag":
                        r = _leb(data, r + 1)[1]
                    else:
                        raise ValueError("import kind")
                    imps.append({"module": mod, "name": nm, "kind": kind, "index": cnt[kind]})
                    inv["import_names"].append(mod + "." + nm)
                    cnt[kind] += 1
            elif sid == 4:
                n, r = _leb(data, q, cap=5)
                for _ in range(n):
                    init = None
                    if data[r] == 0x40 and data[r + 1] == 0:   # function-references: table with an init expr
                        rt, r = reftype(r + 2)
                        mn, mx, r = limits(r)
                        init, r = _wasm_const(data, r)
                    else:
                        rt, r = reftype(r)
                        mn, mx, r = limits(r)
                    tabs.append({"index": len(tabs), "reftype": rt, "min": mn, "max": mx, "imported": False})
            elif sid == 6:
                n, r = _leb(data, q, cap=5)
                for _ in range(n):
                    b = data[r]
                    if b in (0x63, 0x64):
                        vt, r = reftype(r)
                    else:
                        vt, r = WASM_VALTYPES.get(b, "0x%02x" % b), r + 1
                    mut = bool(data[r] & 1)
                    init, r = _wasm_const(data, r + 1)
                    globs.append({"index": len(globs), "valtype": vt, "mutable": mut, "imported": False,
                                  "init": init if isinstance(init, int) else None})
            elif sid == 7:
                n, r = _leb(data, q, cap=5)
                for _ in range(n):
                    nm, r = _wasm_name(data, r)
                    kind = WASM_EXTERN_KINDS.get(data[r], "0x%02x" % data[r])
                    idx, r = _leb(data, r + 1, cap=5)
                    exps.append({"name": nm, "kind": kind, "index": idx})
                    inv["export_names"].append(nm)
            elif sid == 9:
                n, r = _leb(data, q, cap=5)
                for k in range(n):
                    fl, r = _leb(data, r, cap=5)
                    tab, off = 0, None
                    mode = "passive" if fl & 3 == 1 else "declarative" if fl & 3 == 3 else "active"
                    if fl & 2 and not fl & 1:
                        tab, r = _leb(data, r, cap=5)
                    if mode == "active":
                        off, r = _wasm_const(data, r)
                        off = off if isinstance(off, int) else None
                    if fl & 3:                       # elemkind (0x00) / reftype byte
                        r = reftype(r)[1] if fl & 4 else r + 1
                    m, r = _leb(data, r, cap=5)
                    fi = []
                    for _i in range(m):
                        if fl & 4:
                            v, r = _wasm_const(data, r)
                            fi.append(v[1] if isinstance(v, tuple) and v[0] == "func" else None)
                        else:
                            v, r = _leb(data, r, cap=5)
                            fi.append(v)
                    elems.append({"index": k, "mode": mode, "table": tab, "offset": off, "func_indices": fi})
            elif sid == 0 and s["name"] == "name":
                r = _wasm_name(data, q)[1]
                while r < e:
                    sub = data[r]
                    sz, r = _leb(data, r + 1, cap=5)
                    if sub == 0:
                        inv["module_name"] = _wasm_name(data, r)[0]
                    elif sub == 1:
                        n, t = _leb(data, r, cap=5)
                        for _ in range(n):
                            i, t = _leb(data, t, cap=5)
                            fnames[i], t = _wasm_name(data, t)
                    r += sz
            elif sid == 0 and s["name"] == "producers":
                r = _wasm_name(data, q)[1]
                n, r = _leb(data, r, cap=5)
                for _ in range(n):
                    fld, r = _wasm_name(data, r)
                    m, r = _leb(data, r, cap=5)
                    vals = []
                    for _i in range(m):
                        a, r = _wasm_name(data, r)
                        b, r = _wasm_name(data, r)
                        vals.append([a, b])
                    prod[fld] = vals
            elif sid == 0 and s["name"] == "linking" and not fnames:
                r = _leb(data, _wasm_name(data, q)[1], cap=5)[1]          # version
                while r < e:
                    sub = data[r]
                    sz, r = _leb(data, r + 1, cap=5)
                    if sub == 8:                                          # WASM_SYMBOL_TABLE
                        n, t = _leb(data, r, cap=5)
                        for _ in range(n):
                            kind = data[t]
                            fl, t = _leb(data, t + 1, cap=5)
                            if kind in (0, 2, 4, 5):                      # func / global / tag / table
                                idx, t = _leb(data, t, cap=5)
                                nm = None
                                if not fl & 0x10 or fl & 0x40:            # defined, or explicit name
                                    nm, t = _wasm_name(data, t)
                                if kind == 0 and nm is not None:
                                    fnames.setdefault(idx, nm)
                            elif kind == 1:                               # data
                                t = _wasm_name(data, t)[1]
                                if not fl & 0x10:
                                    for _i in range(3):
                                        t = _leb(data, t)[1]
                            elif kind == 3:                               # section
                                t = _leb(data, t, cap=5)[1]
                            else:
                                break
                    r += sz
        except (IndexError, ValueError, TypeError, KeyError):
            inv["inventory_ok"] = False
    return inv


def wasm_fields(data):
    """Flat answer-field candidates for a wasm module's 'doors' (None if not wasm). Lists are in section order
    (render as JSON); absent singletons are "none"; counts are ints; booleans are True/False. Imports render as
    "module.name"; functions by their name-section / linking-symbol name, else "module.name" for imports, else the
    index. *_count = entries of that section (defined), total_*_count = the index space incl. imports; has_table
    counts an imported table too. memory_* = memory 0 (pages, 64 KiB each). indirect_targets = the funcs placed in tables by active elem
    segments (call_indirect targets) in segment/slot order. hcfg_offset = FILE offset of the 'H' of the first crc-valid
    blob in a data segment (else a custom section, else the wasm-split/init/store hcfg_scan hit), hcfg_mem_offset = its
    linear-memory address (passive segments: where memory.init copies it; "none" if never / custom section);
    has_hcfg_section = a custom section named hcfg/.hcfg exists; hcfg_section = the custom section holding the blob;
    hcfg_storage = active/passive/custom/split/init/store (SPECULATIVE names)."""
    lay = wasm_layout(data)
    if not lay:
        return None
    imps, fn = lay["imports"], lay["func_names"]
    nimpf = sum(1 for i in imps if i["kind"] == "func")
    impf = {i["index"]: i["module"] + "." + i["name"] for i in imps if i["kind"] == "func"}

    def fname(i):
        return fn.get(i) or impf.get(i) or i

    def nz(v):
        return "none" if v is None or v == [] or v == {} else v

    mem = (lay["memories"] or [None])[0]
    tab = (lay["tables"] or [None])[0]
    act = [e for e in lay["elems"] if e["mode"] == "active"]
    tgt = [fname(i) for e in act for i in e["func_indices"] if i is not None]
    segs = lay["data_segments"]
    hc = next(iter(wasm_hcfg_segment(data)), {})
    st = lay["start"]
    return {
        "format": "wasm", "machine": lay["machine"],
        "import_count": len(imps), "imports": nz(lay["import_names"]),
        "import_modules": nz(list(dict.fromkeys(i["module"] for i in imps))),
        "imported_functions": nz([i["module"] + "." + i["name"] for i in imps if i["kind"] == "func"]),
        "imported_function_count": nimpf,
        "export_count": len(lay["exports"]), "exports": nz(lay["export_names"]),
        "exported_functions": nz([e["name"] for e in lay["exports"] if e["kind"] == "func"]),
        "function_count": lay["function_count"], "total_function_count": nimpf + lay["function_count"],
        "type_count": lay["type_count"],
        "memory_count": len(lay["memories"]), "has_memory": bool(lay["memories"]),
        "memory_min": nz(mem and mem["min"]), "memory_max": nz(mem and mem["max"]),
        "memory_shared": bool(mem and mem["shared"]), "memory64": bool(mem and mem["memory64"]),
        "memory_imported": bool(mem and mem["imported"]),
        "has_table": bool(lay["tables"]), "total_table_count": len(lay["tables"]),
        "table_count": sum(1 for t in lay["tables"] if not t["imported"]),
        "table_min": nz(tab and tab["min"]), "table_max": nz(tab and tab["max"]),
        "table_reftype": nz(tab and tab["reftype"]), "table_imported": bool(tab and tab["imported"]),
        "elem_count": len(lay["elems"]), "active_elem_count": len(act),
        "indirect_targets": nz(tgt), "indirect_target_count": len(tgt),
        "has_start": st is not None, "start_index": nz(st), "start_function": nz(None if st is None else fname(st)),
        "global_count": sum(1 for g in lay["globals"] if not g["imported"]), "total_global_count": len(lay["globals"]),
        "mutable_global_count": sum(1 for g in lay["globals"] if g["mutable"]),
        "imported_global_count": sum(1 for g in lay["globals"] if g["imported"]),
        "data_segment_count": len(segs),
        "active_data_segment_count": sum(1 for d in segs if d["mode"] == "active"),
        "passive_data_segment_count": sum(1 for d in segs if d["mode"] == "passive"),
        "data_offsets": nz([d["mem_offset"] for d in segs if d["mode"] == "active"]),
        "data_count": nz(lay["data_count"]),
        "custom_sections": nz(lay["custom_names"]), "custom_section_count": len(lay["custom_names"]),
        "has_name_section": "name" in lay["custom_names"], "module_name": nz(lay["module_name"]),
        "producers": nz(lay["producers"]),
        "hcfg_offset": nz(hc.get("file_offset")), "hcfg_mem_offset": nz(hc.get("mem_offset")),
        "hcfg_segment": nz(hc.get("segment")),
        "has_hcfg_section": any(n.lower().lstrip(".") == "hcfg" for n in lay["custom_names"]),
        "hcfg_section": nz(hc.get("section")), "hcfg_storage": nz(hc.get("mode")),
    }


def wasm_field(data, name):
    """One wasm_fields value; "none" when the input is not wasm or the field is unknown/absent."""
    try:
        return (wasm_fields(data) or {}).get(name, "none")
    except Exception:  # noqa: BLE001 -- untrusted bytes: never raise past the field
        return "none"


def wasm_hcfg_segment(data):
    """[{segment, mode, file_offset, mem_offset, segment_file_offset, segment_mem_offset}] for every crc-valid raw
    HCFG blob inside a wasm data segment ([] if none / not wasm). file_offset = the 'H' in the file (= hcfg_scan's raw
    offset); mem_offset = segment memory offset + the blob's position in the segment (linear-memory address, None for
    passive / global-based segments)."""
    lay = wasm_layout(data) or {}
    out = []
    inits = {}   # passive segment file offset -> linear address it is memory.init'ed to (first such copy)
    if any(s["mode"] == "passive" for s in lay.get("data_segments", ())):
        for a, _b, fo, k in wasm_memory_writes(data, lay):
            if k == "init":
                inits.setdefault(fo, a)
    for s in lay.get("data_segments", ()):
        lo = s["file_offset"]
        seg = bytes(data[lo:lo + s["size"]])
        i = seg.find(HCFG_MAGIC)
        while i >= 0:
            blob = seg[i:]
            r = _parse_blob(blob[:_need(blob[:8])]) if len(blob) >= 12 else None
            if r and r[5]:
                mo = s["mem_offset"]
                if mo is None and s["mode"] == "passive":   # memory.init'ed copy covering the blob start
                    mo = next((a - (f - lo) for f, a in inits.items() if lo <= f <= lo + i), None)
                out.append({"segment": s["index"], "mode": s["mode"], "file_offset": lo + i,
                            "mem_offset": None if mo is None else mo + i, "segment_file_offset": lo,
                            "segment_mem_offset": mo})
            i = seg.find(HCFG_MAGIC, i + 1)
    for s in lay.get("sections", ()):   # custom section (e.g. `hcfg`): no linear-memory address
        if s["id"] == 0:
            lo, e = s["offset"], s["offset"] + s["size"]
            i = bytes(data[lo:e]).find(HCFG_MAGIC)
            while i >= 0:
                blob = bytes(data[lo + i:e])
                r = _parse_blob(blob[:_need(blob[:8])]) if len(blob) >= 12 else None
                if r and r[5]:
                    out.append({"segment": None, "mode": "custom", "section": s["name"], "file_offset": lo + i,
                                "mem_offset": None, "segment_file_offset": lo, "segment_mem_offset": None})
                i = bytes(data[lo:e]).find(HCFG_MAGIC, i + 1)
    if not out:   # not contiguous in the file: split over segments / memory.init'ed / built by const stores
        got = []
        _wasm_mem_scan(bytes(data), lambda off, enc, blob, det="": got.append((off, enc, det)), None, 0)
        for off, enc, det in got[:1]:
            out.append({"segment": None, "mode": enc.split("-")[1], "file_offset": off,
                        "mem_offset": int(det.split("mem=")[1].split()[0]), "segment_file_offset": None,
                        "segment_mem_offset": None})
    return out


def bpf_layout(data):
    """Pure-struct eBPF ELF object facts (clang -target bpf -c; e_machine 247 EM_BPF, either byte order), None if not
    an ELF with e_machine 247 or its section table does not parse. {format "elf", elf_type ET_* (readelf constant),
    machine "Linux BPF" (GNU readelf spelling), machine_num "247", entry_point hex, bits, endian, section_names
    (header order, NULL section skipped), sections [{name, type, flags, offset, size}], programs (non-empty
    SHF_EXECINSTR PROGBITS sections except .text = libbpf's SEC() names, e.g. "xdp", "kprobe/do_sys_openat2"),
    program_names (the GLOBAL FUNC symbols defined in them, program order), license (the `license` section string),
    maps (OBJECT symbols in `.maps` (BTF-defined) then legacy `maps`), has_btf (.BTF section)}."""
    if data[:4] != b"\x7fELF" or data[4:5] not in (b"\x01", b"\x02") or data[5:6] not in (b"\x01", b"\x02"):
        return None
    b64, E = data[4] == 2, "<" if data[5] == 1 else ">"
    u16 = lambda o: struct.unpack_from(E + "H", data, o)[0]
    u32 = lambda o: struct.unpack_from(E + "I", data, o)[0]
    uw = (lambda o: struct.unpack_from(E + "Q", data, o)[0]) if b64 else u32
    if len(data) < (64 if b64 else 52) or u16(18) != 247:
        return None
    et, entry = u16(16), uw(24)
    shoff = uw(40) if b64 else u32(32)
    p = 52 if b64 else 40
    shes, shnum, shstr = u16(p + 6), u16(p + 8), u16(p + 10)
    if not shoff or shes < (64 if b64 else 40) or not 0 < shnum <= 4096 or shoff + shes * shnum > len(data):
        return None
    raw = []   # (name_off, type, flags, offset, size, link, info, entsize)
    for k in range(shnum):
        o = shoff + k * shes
        if b64:
            raw.append((u32(o), u32(o + 4), uw(o + 8), uw(o + 24), uw(o + 32), u32(o + 40), u32(o + 44), uw(o + 56)))
        else:
            raw.append((u32(o), u32(o + 4), u32(o + 8), u32(o + 16), u32(o + 20), u32(o + 24), u32(o + 28),
                        u32(o + 36)))

    def cstr(i, off):
        if not 0 <= i < len(raw) or raw[i][1] == 8:
            return ""
        s = raw[i][3] + off
        e = data.find(b"\0", s, s + 4096)
        return bytes(data[s:e]).decode("utf-8", "replace") if s < len(data) and e >= s else ""

    names = [cstr(shstr, r[0]) for r in raw]
    progs = [i for i, r in enumerate(raw) if r[1] == 1 and r[2] & 4 and r[4] and names[i] != ".text"]
    pnames, maps = {i: [] for i in progs}, {}
    mapsec = [i for n in (".maps", "maps") for i, m in enumerate(names) if m == n]
    for t, off, size, link, ent in ((r[1], r[3], r[4], r[5], r[7]) for r in raw):
        if t != 2 or not ent:   # SHT_SYMTAB
            continue
        for k in range(1, min(size // ent, 50000)):
            o = off + k * ent
            if o + ent > len(data):
                break
            nm, info, shndx = (u32(o), data[o + 4], u16(o + 6)) if b64 else (u32(o), data[o + 12], u16(o + 14))
            if shndx in pnames and info & 15 == 2 and info >> 4 == 1:
                pnames[shndx].append(cstr(link, nm))
            elif shndx in mapsec and info & 15 == 1:
                maps.setdefault(shndx, []).append(cstr(link, nm))
        break
    lic = next((bytes(data[r[3]:r[3] + r[4]]).split(b"\0")[0].decode("utf-8", "replace")
                for r, n in zip(raw, names) if n == "license" and r[1] != 8), None)
    return {"format": "elf", "elf_type": ELF_TYPE_NAME.get(et, str(et)), "machine": "Linux BPF",
            "machine_num": "247", "entry_point": hex(entry), "bits": 64 if b64 else 32,
            "endian": "little" if E == "<" else "big", "section_names": names[1:],
            "sections": [{"name": n, "type": r[1], "flags": r[2], "offset": r[3], "size": r[4]}
                         for n, r in zip(names[1:], raw[1:])],
            "programs": [names[i] for i in progs], "program_names": [x for i in progs for x in pnames[i] if x],
            "license": lic, "maps": [x for i in mapsec for x in maps.get(i, []) if x],
            "has_btf": ".BTF" in names}


def bpf_fields(data):
    """Flat answer-field candidates for an eBPF object (None if not EM_BPF). Lists in header order (render as JSON);
    absent singletons "none". program_types = the SEC() prefix before the first '/' (xdp, kprobe, tracepoint, ...).
    hcfg_offset = FILE offset of the 'H' of the first crc-valid raw blob inside a section (= hcfg_scan raw offset),
    hcfg_section = that section's name (".hcfg", ".rodata", ...), hcfg_section_offset = the blob's offset inside it;
    has_hcfg_section = a section named hcfg/.hcfg exists. Field names other than format/elf_type/machine/entry_point
    are SPECULATIVE (GM vocabulary for BPF not seen)."""
    try:
        lay = bpf_layout(data)
    except (struct.error, IndexError, ValueError, TypeError):   # truncated / hostile header: cannot answer
        return None
    if not lay:
        return None

    def nz(v):
        return "none" if v is None or v == [] else v

    hc = {}
    for s in lay["sections"]:
        if s["type"] == 8 or hc:
            continue
        lo, e = s["offset"], s["offset"] + s["size"]
        seg = bytes(data[lo:e])
        i = seg.find(HCFG_MAGIC)
        while i >= 0 and not hc:
            blob = seg[i:]
            r = _parse_blob(blob[:_need(blob[:8])]) if len(blob) >= 12 else None
            if r and r[5]:
                hc = {"hcfg_offset": lo + i, "hcfg_section": s["name"], "hcfg_section_offset": i}
            i = seg.find(HCFG_MAGIC, i + 1)
    out = {k: lay[k] for k in ("format", "elf_type", "machine", "machine_num", "entry_point", "bits", "endian")}
    out.update({
        "section_names": lay["section_names"], "section_count": len(lay["section_names"]),
        "programs": nz(lay["programs"]), "program_count": len(lay["programs"]),
        "program_types": nz(list(dict.fromkeys(p.split("/")[0] for p in lay["programs"]))),
        "program_names": nz(lay["program_names"]), "license": nz(lay["license"]),
        "maps": nz(lay["maps"]), "map_count": len(lay["maps"]), "has_btf": lay["has_btf"],
        "has_hcfg_section": any(n.lower().lstrip(".") == "hcfg" for n in lay["section_names"]),
        "hcfg_offset": hc.get("hcfg_offset", "none"), "hcfg_section": hc.get("hcfg_section", "none"),
        "hcfg_section_offset": hc.get("hcfg_section_offset", "none")})
    return out


def bpf_field(data, name):
    """One bpf_fields value; "none" when the input is not an eBPF object or the field is unknown/absent."""
    try:
        return (bpf_fields(data) or {}).get(name, "none")
    except Exception:  # noqa: BLE001 -- untrusted bytes: never raise past the field
        return "none"


def kmod_layout(data):
    """Pure-struct Linux kernel module facts (.ko = ELF ET_REL, any arch / byte order), None if not an ELF whose section
    table parses and that carries a .modinfo or .gnu.linkonce.this_module section. {format, elf_type, machine (label),
    machine_num, entry_point hex, bits, endian, section_names (header order, NULL skipped), sections [{name, type, flags,
    offset, size}], modinfo_entries [(key, value)] (.modinfo NUL-separated key=value strings, SECTION order -- kmod's
    `modinfo` prints them reversed), versions [(symbol, crc)] (__versions = struct modversion_info {unsigned long crc;
    char name[64 - sizeof(long)]}), this_module_name (struct module.name in .gnu.linkonce.this_module: after
    state + list_head = offset 24 on 64-bit, 12 on 32-bit), exports [(symbol, gpl)] (`__ksymtab_<sym>` symbols, symtab
    order; gpl = the symbol's section name contains "gpl"), init_function / exit_function (the other FUNC symbol at the
    init_module / cleanup_module address -- module_init(fn) aliases it -- else that name, None if absent)}."""
    if data[:4] != b"\x7fELF" or data[4:5] not in (b"\x01", b"\x02") or data[5:6] not in (b"\x01", b"\x02"):
        return None
    b64, E = data[4] == 2, "<" if data[5] == 1 else ">"
    u16 = lambda o: struct.unpack_from(E + "H", data, o)[0]
    u32 = lambda o: struct.unpack_from(E + "I", data, o)[0]
    uw = (lambda o: struct.unpack_from(E + "Q", data, o)[0]) if b64 else u32
    if len(data) < (64 if b64 else 52):
        return None
    et, mach, entry = u16(16), u16(18), uw(24)
    shoff = uw(40) if b64 else u32(32)
    p = 52 if b64 else 40
    shes, shnum, shstr = u16(p + 6), u16(p + 8), u16(p + 10)
    if not shoff or shes < (64 if b64 else 40) or not 0 < shnum <= 4096 or shoff + shes * shnum > len(data):
        return None
    raw = []   # (name_off, type, flags, offset, size, link, info, entsize)
    for k in range(shnum):
        o = shoff + k * shes
        if b64:
            raw.append((u32(o), u32(o + 4), uw(o + 8), uw(o + 24), uw(o + 32), u32(o + 40), u32(o + 44), uw(o + 56)))
        else:
            raw.append((u32(o), u32(o + 4), u32(o + 8), u32(o + 16), u32(o + 20), u32(o + 24), u32(o + 28),
                        u32(o + 36)))

    def body(i):
        r = raw[i]
        return b"" if r[1] == 8 or r[3] >= len(data) else bytes(data[r[3]:min(r[3] + r[4], len(data))])

    def cstr(i, off):
        if not 0 <= i < len(raw) or raw[i][1] == 8:
            return ""
        s = raw[i][3] + off
        e = data.find(b"\0", s, s + 4096)
        return bytes(data[s:e]).decode("utf-8", "replace") if s < len(data) and e >= s else ""

    names = [cstr(shstr, r[0]) for r in raw]
    if ".modinfo" not in names and ".gnu.linkonce.this_module" not in names:
        return None
    mi, vers, tname = [], [], None
    for i, n in enumerate(names):
        if n == ".modinfo":
            for s in body(i).split(b"\0"):
                if b"=" in s:
                    k, v = s.decode("utf-8", "replace").split("=", 1)
                    mi.append((k, v))
        elif n == "__versions":
            w, b = 8 if b64 else 4, body(i)
            for o in range(0, len(b) - 63, 64):
                crc = int.from_bytes(b[o:o + w], "little" if E == "<" else "big") & 0xFFFFFFFF
                nm = b[o + w:o + 64].split(b"\0")[0].decode("utf-8", "replace")
                if nm:
                    vers.append((nm, crc))
        elif n == ".gnu.linkonce.this_module" and tname is None:
            b = body(i)[24 if b64 else 12:][:64 - (8 if b64 else 4)]
            tname = b.split(b"\0")[0].decode("utf-8", "replace") or None
    exports, funcs = [], {}
    for t, off, size, link, ent in ((r[1], r[3], r[4], r[5], r[7]) for r in raw):
        if t != 2 or not ent:   # SHT_SYMTAB
            continue
        for k in range(1, min(size // ent, 200000)):
            o = off + k * ent
            if o + ent > len(data):
                break
            if b64:
                nm, info, shndx, val = u32(o), data[o + 4], u16(o + 6), uw(o + 8)
            else:
                nm, info, val, shndx = u32(o), data[o + 12], u32(o + 4), u16(o + 14)
            if info & 15 == 3:   # STT_SECTION
                continue
            s = cstr(link, nm)
            if s.startswith("__ksymtab_") and s != "__ksymtab_strings":
                exports.append((s[10:], "gpl" in (names[shndx] if shndx < len(names) else "")))
            elif info & 15 == 2 and s:
                funcs.setdefault((shndx, val), []).append(s)
        break

    def entry_fn(name):
        at = next((ns for ns in funcs.values() if name in ns), None)
        return None if at is None else next((x for x in at if x != name), name)

    return {"format": "elf", "elf_type": ELF_TYPE_NAME.get(et, str(et)), "machine": ELF_MACHINE_LABEL.get(mach, str(mach)),
            "machine_num": str(mach), "entry_point": hex(entry), "bits": 64 if b64 else 32,
            "endian": "little" if E == "<" else "big", "section_names": names[1:],
            "sections": [{"name": n, "type": r[1], "flags": r[2], "offset": r[3], "size": r[4]}
                         for n, r in zip(names[1:], raw[1:])],
            "modinfo_entries": mi, "versions": vers, "this_module_name": tname, "exports": exports,
            "init_function": entry_fn("init_module"), "exit_function": entry_fn("cleanup_module")}


KMOD_SINGLE_KEYS = ("license", "author", "description", "version", "vermagic", "srcversion", "name", "retpoline",
                    "intree", "import_ns", "softdep", "staging", "livepatch", "scmversion")


def kmod_fields(data):
    """Flat answer-field candidates for a Linux kernel module (None if not a .ko; see kmod_layout). Lists in file
    order (render as JSON); absent singletons "none". modinfo = {key: value} in .modinfo section order (first value
    of a repeated key; modinfo_entries keeps every "key=value"), modinfo_keys; license/author/description/version/
    vermagic/srcversion/name/... = the .modinfo value (vermagic trailing blank stripped -- vermagic_raw keeps it;
    kernel_version = its first token); depends = the depends= value split on "," ("none" when empty, as kbuild writes
    `depends=` for a module with no deps); aliases / authors / parms (parm= values) / firmware lists; versions =
    [{symbol, crc "0x%08x"}] of __versions, version_symbols, version_crcs {symbol: crc}; this_module_name;
    module_name = name= else this_module_name; exported_symbols / exported_gpl_symbols (__ksymtab_*); init_function /
    exit_function; hcfg_offset = FILE offset of the 'H' of the first crc-valid raw blob in a section (= hcfg_scan raw),
    hcfg_section, hcfg_section_offset. Field names beyond the ELF header ones are SPECULATIVE (GM .ko vocabulary
    not seen)."""
    try:
        lay = kmod_layout(data)
    except (struct.error, IndexError, ValueError, TypeError):   # truncated / hostile header: cannot answer
        return None
    if not lay:
        return None

    def nz(v):
        return "none" if v is None or v == [] or v == {} or v == "" else v

    mi = lay["modinfo_entries"]
    d = {}
    for k, v in mi:
        d.setdefault(k, v)
    every = lambda key: [v for k, v in mi if k == key]
    hc = {}
    for s in lay["sections"]:
        if s["type"] == 8 or hc:
            continue
        lo = s["offset"]
        seg = bytes(data[lo:lo + s["size"]])
        i = seg.find(HCFG_MAGIC)
        while i >= 0 and not hc:
            blob = seg[i:]
            r = _parse_blob(blob[:_need(blob[:8])]) if len(blob) >= 12 else None
            if r and r[5]:
                hc = {"hcfg_offset": lo + i, "hcfg_section": s["name"], "hcfg_section_offset": i}
            i = seg.find(HCFG_MAGIC, i + 1)
    vm = d.get("vermagic")
    deps = [x for x in (d.get("depends") or "").split(",") if x]
    out = {k: lay[k] for k in ("format", "elf_type", "machine", "machine_num", "entry_point", "bits", "endian")}
    out.update({k: nz(d.get(k)) for k in KMOD_SINGLE_KEYS})
    out.update({
        "is_kernel_module": True, "section_names": lay["section_names"], "section_count": len(lay["section_names"]),
        "modinfo": nz(d), "modinfo_keys": nz(list(d)), "modinfo_entries": nz([f"{k}={v}" for k, v in mi]),
        "modinfo_count": len(mi), "vermagic": nz(vm.rstrip() if vm else None), "vermagic_raw": nz(vm),
        "kernel_version": nz(vm.split()[0] if vm and vm.split() else None),
        "depends": nz(deps), "depends_count": len(deps), "aliases": nz(every("alias")),
        "authors": nz(every("author")), "parms": nz(every("parm")), "firmware": nz(every("firmware")),
        "versions": nz([{"symbol": n, "crc": f"0x{c:08x}"} for n, c in lay["versions"]]),
        "version_symbols": nz([n for n, _ in lay["versions"]]), "version_count": len(lay["versions"]),
        "version_crcs": nz({n: f"0x{c:08x}" for n, c in lay["versions"]}), "has_modversions": bool(lay["versions"]),
        "this_module_name": nz(lay["this_module_name"]),
        "module_name": nz(d.get("name") or lay["this_module_name"]),
        "exported_symbols": nz([n for n, _ in lay["exports"]]),
        "exported_gpl_symbols": nz([n for n, g in lay["exports"] if g]), "export_count": len(lay["exports"]),
        "has_init": lay["init_function"] is not None, "has_cleanup": lay["exit_function"] is not None,
        "init_function": nz(lay["init_function"]), "exit_function": nz(lay["exit_function"]),
        "hcfg_offset": hc.get("hcfg_offset", "none"), "hcfg_section": hc.get("hcfg_section", "none"),
        "hcfg_section_offset": hc.get("hcfg_section_offset", "none")})
    return out


def kmod_field(data, name):
    """One kmod_fields value; "none" when the input is not a kernel module or the field is unknown/absent."""
    try:
        return (kmod_fields(data) or {}).get(name, "none")
    except Exception:  # noqa: BLE001 -- untrusted bytes: never raise past the field
        return "none"

def elf_header_facts(data, hcfg=True):
    """ELF facts from the raw header structs only, for sstrip'd / corrupted images that make pyelftools / readelf -S
    fail (e_shnum 0, e_shoff past EOF, garbage e_shstrndx, renamed sections). None if the 52/64-byte ELF header is not
    all there. Header fields always come from the ELF header: format, elf_class ELF32/ELF64 (+ elf_class_int),
    endianness little/big, machine label (+ machine_num / machine_int decimal), elf_type ET_*, entry_point hex,
    program_header_count, has_interp. Section table: has_section_headers "true" only when e_shoff/e_shentsize/e_shnum
    describe a table inside the file (SHN_UNDEF count / SHN_XINDEX index read from section 0); section_names = header
    order, NULL section skipped, [] when there is no table OR no usable name table (e_shstrndx out of range / not
    SHT_STRTAB / past EOF: readelf's "<no-strings>"); section_count = table entries minus the NULL one; has_symtab =
    an SHT_SYMTAB section (by type, like readelf -S); has_hcfg_section = a section literally named hcfg/.hcfg (a renamed
    impostor counts; the blob need not be in it). hcfg_* = the first crc-valid blob of hcfg_find (raw scan over the
    whole file, independent of sections): hcfg_offset, hcfg_encoding, hcfg_config, hcfg_section = the named section
    whose file range holds it ("none" without names); hcfg=False skips that scan (header fields only). Never raises on
    malformed input."""
    try:
        if data[:4] != b"\x7fELF" or data[4:5] not in (b"\x01", b"\x02") or data[5:6] not in (b"\x01", b"\x02"):
            return None
        b64, E = data[4] == 2, "<" if data[5] == 1 else ">"
        if len(data) < (64 if b64 else 52):
            return None
        u16 = lambda o: struct.unpack_from(E + "H", data, o)[0]
        u32 = lambda o: struct.unpack_from(E + "I", data, o)[0]
        uw = (lambda o: struct.unpack_from(E + "Q", data, o)[0]) if b64 else u32
        et, m, entry = u16(16), u16(18), uw(24)
        phoff, shoff = (uw(32), uw(40)) if b64 else (u32(28), u32(32))
        p = 52 if b64 else 40
        phes, phn, shes, shn, shstr = u16(p + 2), u16(p + 4), u16(p + 6), u16(p + 8), u16(p + 10)
        ptypes = []
        if phoff and phes >= (56 if b64 else 32):
            for k in range(min(phn, 4096)):
                o = phoff + k * phes
                if o + phes > len(data):
                    break
                ptypes.append(u32(o))
        sw = 64 if b64 else 40
        secs = []   # (name_off, type, offset, size)

        def sec(o):
            return (u32(o), u32(o + 4), uw(o + 24), uw(o + 32)) if b64 else (u32(o), u32(o + 4), u32(o + 16),
                                                                               u32(o + 20))
        if shoff and shes >= sw and shoff + shes <= len(data):
            s0 = sec(shoff)
            n = shn or s0[3]                                  # e_shnum 0 + table: real count in section 0 sh_size
            if shstr == 0xffff:                               # SHN_XINDEX: real index in section 0 sh_link
                shstr = u32(shoff + (40 if b64 else 24))
            if 0 < n <= 65535 and shoff + n * shes <= len(data):
                secs = [sec(shoff + k * shes) for k in range(n)]
        names = []
        if secs and 0 < shstr < len(secs) and secs[shstr][1] == 3 and secs[shstr][2] + secs[shstr][3] <= len(data):
            so, sn = secs[shstr][2], secs[shstr][3]
            tab = bytes(data[so:so + sn])
            names = [tab[s[0]:tab.find(b"\0", s[0]) if tab.find(b"\0", s[0]) >= 0 else sn].decode("utf-8", "replace")
                     if s[0] < sn else "" for s in secs[1:]]
        hit = hcfg_find(data) if hcfg else None
        hsec = "none"
        if hit is not None and names:
            hsec = next((nm for nm, s in zip(names, secs[1:]) if s[1] != 8 and s[2] <= hit.offset < s[2] + s[3]),
                        "none")
        cls = "ELF64" if b64 else "ELF32"
        return {"format": "elf", "elf_class": cls, "elf_class_int": "64" if b64 else "32", "bits": 64 if b64 else 32,
                "endianness": "little" if E == "<" else "big", "endian": "little" if E == "<" else "big",
                "machine": ELF_MACHINE_LABEL.get(m, str(m)), "machine_num": str(m), "machine_int": str(m),
                "elf_type": ELF_TYPE_NAME.get(et, str(et)), "entry_point": hex(entry),
                "program_header_count": len(ptypes), "has_interp": "true" if 3 in ptypes else "false",
                "has_section_headers": "true" if secs else "false", "section_count": max(len(secs) - 1, 0),
                "section_names": names, "has_symtab": "true" if any(s[1] == 2 for s in secs) else "false",
                "has_hcfg_section": "true" if any(x.lower().lstrip(".") == "hcfg" for x in names) else "false",
                "hcfg_offset": hit.offset if hit else "none", "hcfg_encoding": hit.encoding if hit else "none",
                "hcfg_config": hit.config if hit else "none", "hcfg_section": hsec,
                **_elf_segment_facts(data, b64, E, et, phoff, phes, phn, shn, shstr)}
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


ELF_OSABI = {0: ("ELFOSABI_SYSV", "UNIX - System V"), 1: ("ELFOSABI_HPUX", "UNIX - HP-UX"),
             2: ("ELFOSABI_NETBSD", "UNIX - NetBSD"), 3: ("ELFOSABI_LINUX", "UNIX - GNU"),
             4: ("ELFOSABI_HURD", "GNU/Hurd"), 6: ("ELFOSABI_SOLARIS", "UNIX - Solaris"),
             7: ("ELFOSABI_AIX", "UNIX - AIX"), 8: ("ELFOSABI_IRIX", "UNIX - IRIX"),
             9: ("ELFOSABI_FREEBSD", "UNIX - FreeBSD"), 10: ("ELFOSABI_TRU64", "UNIX - TRU64"),
             11: ("ELFOSABI_MODESTO", "Novell - Modesto"), 12: ("ELFOSABI_OPENBSD", "UNIX - OpenBSD"),
             13: ("ELFOSABI_OPENVMS", "VMS - OpenVMS"), 14: ("ELFOSABI_NSK", "HP - Non-Stop Kernel"),
             15: ("ELFOSABI_AROS", "AROS"), 16: ("ELFOSABI_FENIXOS", "FenixOS"), 17: ("ELFOSABI_CLOUD", "Nuxi CloudABI"),
             97: ("ELFOSABI_ARM", "ARM"), 255: ("ELFOSABI_STANDALONE", "Standalone App")}   # pyelftools / readelf -h
ELF_PT = {0: "NULL", 1: "LOAD", 2: "DYNAMIC", 3: "INTERP", 4: "NOTE", 5: "SHLIB", 6: "PHDR", 7: "TLS",
          0x6474e550: "GNU_EH_FRAME", 0x6474e551: "GNU_STACK", 0x6474e552: "GNU_RELRO", 0x6474e553: "GNU_PROPERTY",
          0x6474e554: "GNU_SFRAME", 0x65a3dbe6: "OPENBSD_RANDOMIZE", 0x65a3dbe7: "OPENBSD_WXNEEDED",
          0x70000000: "PROC0", 0x70000001: "EXIDX", 0x70000003: "ABIFLAGS"}   # readelf -l Type column


def _elf_segment_facts(data, b64, E, et, phoff, phes, phn, shn, shstr):
    """Program-header / ABI facts merged into elf_header_facts (raw structs, no pyelftools): e_flags (lowercase hex),
    os_abi ELFOSABI_* (+ os_abi_label readelf "UNIX - System V", os_abi_num decimal), abi_version, e_phnum / e_shnum /
    e_shstrndx (raw header ints), segments ["PT_LOAD", ...] in table order (segments_short readelf "LOAD"; unknown
    types "0x..."), segment_count, interpreter (PT_INTERP string, "none"), needed (DT_NEEDED in order), bind_now,
    has_gnu_stack, has_nx / execstack (GNU_STACK without / with PF_X; no GNU_STACK = NX off, like checksec), relro
    full/partial/none (GNU_RELRO + BIND_NOW via DT_BIND_NOW / DF_BIND_NOW / DF_1_NOW, checksec rules), is_pie (ET_DYN
    with DF_1_PIE or an interpreter, like file(1)), is_static (EXEC/DYN without PT_INTERP and without DT_NEEDED)."""
    U = lambda f, o: struct.unpack_from(E + f, data, o)[0]
    w = "Q" if b64 else "I"
    eflags, osabi = U("I", 48 if b64 else 36), data[7]
    phs = []   # (type, flags, offset, vaddr, filesz)
    if phoff and phes >= (56 if b64 else 32):
        for k in range(min(phn, 4096)):
            o = phoff + k * phes
            if o + phes > len(data):
                break
            phs.append((U("I", o), U("I", o + 4), U("Q", o + 8), U("Q", o + 16), U("Q", o + 32)) if b64 else
                       (U("I", o), U("I", o + 24), U("I", o + 4), U("I", o + 8), U("I", o + 16)))
    short = [ELF_PT.get(t, hex(t)) for t, *_ in phs]
    interp = "none"
    for t, _, off, _, sz in phs:
        if t == 3 and off + sz <= len(data):
            interp = bytes(data[off:off + sz]).split(b"\0")[0].decode("utf-8", "replace")
            break
    dyn = {}   # tag -> [values]
    for t, _, off, _, sz in phs:
        if t == 2:
            es = 16 if b64 else 8
            for o in range(off, min(off + sz, len(data) - es + 1, off + es * 4096), es):
                tag, val = U(w, o), U(w, o + es // 2)
                if tag == 0:
                    break
                dyn.setdefault(tag, []).append(val)
            break

    def v2o(va):
        return next((off + va - vaddr for t, _, off, vaddr, sz in phs if t == 1 and vaddr <= va < vaddr + sz), None)
    needed = []
    stro = v2o(dyn[5][0]) if 5 in dyn else None
    if stro is not None:
        for v in dyn.get(1, [])[:256]:
            a = stro + v
            e = data.find(b"\0", a, a + 4096)
            if 0 <= a < len(data) and e > 0:
                needed.append(bytes(data[a:e]).decode("utf-8", "replace"))
    f1 = dyn.get(0x6ffffffb, [0])[0]
    now = 24 in dyn or bool(dyn.get(30, [0])[0] & 0x8) or bool(f1 & 0x1)
    stack = next((f for t, f, *_ in phs if t == 0x6474e551), None)
    relro = ("full" if now else "partial") if any(t == 0x6474e552 for t, *_ in phs) else "none"
    tf = lambda b: "true" if b else "false"
    exe = et in (2, 3)
    return {"e_flags": hex(eflags), "os_abi": ELF_OSABI.get(osabi, (str(osabi),))[0],
            "os_abi_label": ELF_OSABI.get(osabi, (0, "<unknown: %x>" % osabi))[1], "os_abi_num": str(osabi),
            "abi_version": str(data[8]), "e_phnum": phn, "e_shnum": shn, "e_shstrndx": shstr,
            "segments": ["PT_" + x if not x.startswith("0x") else x for x in short], "segments_short": short,
            "segment_count": len(phs), "interpreter": interp, "needed": needed, "bind_now": tf(now),
            "has_gnu_stack": tf(stack is not None),
            "has_nx": tf(stack is not None and not stack & 1) if exe else "none",
            "execstack": tf(stack is None or stack & 1) if exe else "none", "relro": relro, "has_relro": tf(relro != "none"),
            "is_pie": tf(et == 3 and (bool(f1 & 0x08000000) or interp != "none")) if exe else "none",
            "is_static": tf(interp == "none" and not needed) if exe else "none"}


def elf_header_field(data, name):
    """One elf_header_facts value; "none" when the input is no (complete-header) ELF or the field is unknown."""
    try:
        return (elf_header_facts(data, hcfg=name.startswith("hcfg")) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


PE_SUBSYSTEM = {1: ("native", "IMAGE_SUBSYSTEM_NATIVE"), 2: ("gui", "IMAGE_SUBSYSTEM_WINDOWS_GUI"),
                3: ("console", "IMAGE_SUBSYSTEM_WINDOWS_CUI"), 5: ("os2_console", "IMAGE_SUBSYSTEM_OS2_CUI"),
                7: ("posix_console", "IMAGE_SUBSYSTEM_POSIX_CUI"), 9: ("wince_gui", "IMAGE_SUBSYSTEM_WINDOWS_CE_GUI"),
                10: ("efi_application", "IMAGE_SUBSYSTEM_EFI_APPLICATION"),
                11: ("efi_boot_service_driver", "IMAGE_SUBSYSTEM_EFI_BOOT_SERVICE_DRIVER"),
                12: ("efi_runtime_driver", "IMAGE_SUBSYSTEM_EFI_RUNTIME_DRIVER"), 13: ("efi_rom", "IMAGE_SUBSYSTEM_EFI_ROM"),
                14: ("xbox", "IMAGE_SUBSYSTEM_XBOX"), 16: ("windows_boot_application",
                                                         "IMAGE_SUBSYSTEM_WINDOWS_BOOT_APPLICATION")}
PE_FILE_CHAR = {0x1: "RELOCS_STRIPPED", 0x2: "EXECUTABLE_IMAGE", 0x4: "LINE_NUMS_STRIPPED", 0x8: "LOCAL_SYMS_STRIPPED",
                0x10: "AGGRESIVE_WS_TRIM", 0x20: "LARGE_ADDRESS_AWARE", 0x80: "BYTES_REVERSED_LO", 0x100: "32BIT_MACHINE",
                0x200: "DEBUG_STRIPPED", 0x400: "REMOVABLE_RUN_FROM_SWAP", 0x800: "NET_RUN_FROM_SWAP", 0x1000: "SYSTEM",
                0x2000: "DLL", 0x4000: "UP_SYSTEM_ONLY", 0x8000: "BYTES_REVERSED_HI"}   # IMAGE_FILE_* (pefile names)
PE_DLL_CHAR = {0x20: "HIGH_ENTROPY_VA", 0x40: "DYNAMIC_BASE", 0x80: "FORCE_INTEGRITY", 0x100: "NX_COMPAT",
               0x200: "NO_ISOLATION", 0x400: "NO_SEH", 0x800: "NO_BIND", 0x1000: "APPCONTAINER", 0x2000: "WDM_DRIVER",
               0x4000: "GUARD_CF", 0x8000: "TERMINAL_SERVER_AWARE"}   # IMAGE_DLLCHARACTERISTICS_* (pefile names)


def pe_header_facts(data):
    """PE/COFF facts from the raw MZ/PE/optional/section headers (no pefile; MinGW, Go, Zig, .NET, MSVC alike), the
    PE counterpart of elf_header_facts. None if the DOS header / PE signature / COFF header / optional-header magic is
    not there. format "pe", pe_type PE32/PE32+ (+ bits), machine (PE_MACHINE_LABEL) / machine_num (decimal) /
    machine_hex, entry_point = hex(ImageBase + AddressOfEntryPoint) (+ entry_rva hex, entry_point_int decimal),
    image_base hex (+ image_base_int), timestamp = TimeDateStamp decimal (+ timestamp_hex), characteristics /
    dll_characteristics hex (+ *_int decimal, *_flags = pefile-style IMAGE_FILE_* / IMAGE_DLLCHARACTERISTICS_* names in
    bit order), subsystem short label console/gui/native/efi_* (+ subsystem_const IMAGE_SUBSYSTEM_*, subsystem_int
    decimal), is_dll, section_names (header order, NUL-trimmed, "/N" long names resolved through the COFF string table
    like objdump/pefile do), section_count, has_symtab ("true" when PointerToSymbolTable and NumberOfSymbols are set;
    Go/MinGW keep one, MSVC/.NET/stripped don't) + number_of_symbols, size_of_image / checksum / linker_version /
    os_version / subsystem_version, is_dotnet (CLR data directory), import_dlls (import-directory order). Never raises."""
    try:
        if data[:2] != b"MZ" or len(data) < 0x40:
            return None
        pe = int.from_bytes(data[0x3c:0x40], "little")
        if data[pe:pe + 4] != b"PE\0\0" or len(data) < pe + 26:
            return None
        m, nsec, ts, symp, nsym, optsz, ch = struct.unpack_from("<HHIIIHH", data, pe + 4)
        opt = pe + 24
        magic = struct.unpack_from("<H", data, opt)[0]
        if magic not in (0x10b, 0x20b) or len(data) < opt + (112 if magic == 0x20b else 96):
            return None
        p64 = magic == 0x20b
        lmaj, lmin = data[opt + 2], data[opt + 3]
        aep = struct.unpack_from("<I", data, opt + 16)[0]
        base = struct.unpack_from("<Q", data, opt + 24)[0] if p64 else struct.unpack_from("<I", data, opt + 28)[0]
        osmaj, osmin, _, _, ssmaj, ssmin = struct.unpack_from("<6H", data, opt + 40)
        soi, _, csum, sub, dch = struct.unpack_from("<IIIHH", data, opt + 56)
        strtab = symp + 18 * nsym if symp and nsym else 0

        def secname(raw):
            nm = raw.split(b"\0", 1)[0]
            if nm[:1] == b"/" and nm[1:].isdigit() and strtab and strtab + int(nm[1:]) < len(data):
                o = strtab + int(nm[1:])
                e = data.find(b"\0", o, o + 4096)
                nm = bytes(data[o:e if e >= 0 else o + 4096])
            return nm.decode("utf-8", "replace")
        secs = []   # (name, va, vsize, raw_ptr, raw_size)
        for k in range(min(nsec, 96)):
            o = opt + optsz + 40 * k
            if o + 40 > len(data):
                break
            vsize, va, rsize, rptr = struct.unpack_from("<IIII", data, o + 8)
            secs.append((secname(bytes(data[o:o + 8])), va, vsize, rptr, rsize))
        dd = opt + (112 if p64 else 96)
        ndd = min(16, struct.unpack_from("<I", data, dd - 4)[0])
        dirs = [struct.unpack_from("<II", data, dd + 8 * k) for k in range(ndd)
                if dd + 8 * k + 8 <= min(opt + optsz, len(data))]
        dlls = []
        if len(dirs) > 1 and dirs[1][0]:
            o = _pe_rva(secs, dirs[1][0])
            while o is not None and o + 20 <= len(data) and len(dlls) < 4096:
                ilt, _, _, nrva, iat = struct.unpack_from("<5I", data, o)
                if not (ilt or nrva or iat):
                    break
                no = _pe_rva(secs, nrva)
                if no is None or no >= len(data):
                    break
                e = data.find(b"\0", no, no + 512)
                dlls.append(bytes(data[no:e if e >= 0 else no + 512]).decode("utf-8", "replace"))
                o += 20
        sl, sc = PE_SUBSYSTEM.get(sub, (str(sub), str(sub)))
        flags = lambda v, tab, pre: [pre + n for b, n in sorted(tab.items()) if v & b]
        return {"format": "pe", "pe_type": "PE32+" if p64 else "PE32", "bits": 64 if p64 else 32,
                "machine": PE_MACHINE_LABEL.get(m, f"0x{m:x}"), "machine_num": str(m), "machine_hex": f"0x{m:x}",
                "entry_point": hex(base + aep), "entry_point_int": str(base + aep), "entry_rva": hex(aep),
                "image_base": hex(base), "image_base_int": str(base), "timestamp": str(ts), "timestamp_hex": hex(ts),
                "characteristics": hex(ch), "characteristics_int": str(ch),
                "characteristics_flags": flags(ch, PE_FILE_CHAR, "IMAGE_FILE_"),
                "dll_characteristics": hex(dch), "dll_characteristics_int": str(dch),
                "dll_characteristics_flags": flags(dch, PE_DLL_CHAR, "IMAGE_DLLCHARACTERISTICS_"),
                "subsystem": sl, "subsystem_const": sc, "subsystem_int": str(sub),
                "is_dll": "true" if ch & 0x2000 else "false", "section_names": [s[0] for s in secs],
                "section_count": len(secs), "has_symtab": "true" if symp and nsym else "false",
                "number_of_symbols": nsym, "size_of_image": hex(soi), "checksum": hex(csum),
                "linker_version": f"{lmaj}.{lmin}", "os_version": f"{osmaj}.{osmin}",
                "subsystem_version": f"{ssmaj}.{ssmin}",
                "is_dotnet": "true" if len(dirs) > 14 and dirs[14][0] else "false", "import_dlls": dlls}
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def pe_header_field(data, name):
    """One pe_header_facts value; "none" when the input is no (complete-header) PE or the field is unknown."""
    try:
        return (pe_header_facts(data) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


def header_field(data, name):
    """elf_header_field for ELF input, pe_header_field for PE input, else "none" (same field names where shared:
    format, machine, machine_num, bits, entry_point, section_names, section_count, has_symtab)."""
    try:
        if data[:2] == b"MZ":
            return pe_header_field(data, name)
        return elf_header_field(data, name)
    except Exception:  # noqa: BLE001
        return "none"


# --- ELF relocation tables (.rela.dyn / .rela.plt / .relr.dyn): facts + RELATIVE-addend pointer tables ---------------
_RT_X64 = {0: "NONE", 1: "64", 2: "PC32", 3: "GOT32", 4: "PLT32", 5: "COPY", 6: "GLOB_DAT", 7: "JUMP_SLOT", 8: "RELATIVE",
           9: "GOTPCREL", 10: "32", 11: "32S", 12: "16", 13: "PC16", 14: "8", 15: "PC8", 16: "DTPMOD64", 17: "DTPOFF64",
           18: "TPOFF64", 19: "TLSGD", 20: "TLSLD", 21: "DTPOFF32", 22: "GOTTPOFF", 23: "TPOFF32", 24: "PC64",
           25: "GOTOFF64", 26: "GOTPC32", 27: "GOT64", 28: "GOTPCREL64", 29: "GOTPC64", 30: "GOTPLT64", 31: "PLTOFF64",
           32: "SIZE32", 33: "SIZE64", 34: "GOTPC32_TLSDESC", 35: "TLSDESC_CALL", 36: "TLSDESC", 37: "IRELATIVE",
           38: "RELATIVE64", 41: "GOTPCRELX", 42: "REX_GOTPCRELX"}
_RT_386 = {0: "NONE", 1: "32", 2: "PC32", 3: "GOT32", 4: "PLT32", 5: "COPY", 6: "GLOB_DAT", 7: "JUMP_SLOT", 8: "RELATIVE",
           9: "GOTOFF", 10: "GOTPC", 14: "TLS_TPOFF", 35: "TLS_DTPMOD32", 36: "TLS_DTPOFF32", 37: "TLS_TPOFF32",
           42: "IRELATIVE", 43: "GOT32X"}
_RT_A64 = {0: "NONE", 257: "ABS64", 258: "ABS32", 1024: "COPY", 1025: "GLOB_DAT", 1026: "JUMP_SLOT", 1027: "RELATIVE",
           1028: "TLS_DTPMOD", 1029: "TLS_DTPREL", 1030: "TLS_TPREL", 1031: "TLSDESC", 1032: "IRELATIVE"}
_RT_ARCH = {62: ("R_X86_64_", _RT_X64), 3: ("R_386_", _RT_386), 183: ("R_AARCH64_", _RT_A64)}
_RT_KINDS = ("JUMP_SLOT", "GLOB_DAT", "RELATIVE", "IRELATIVE", "COPY")
ELF_RELOC_MAX = 1 << 20   # relocation entries parsed per image (a 70 MB C++ PIE has ~10^5)


def _elf_relocs(data):
    """Pure-struct walk of an ELF's dynamic relocations, else None. {'bits', 'E' (struct prefix), 'mach', 'type'
    (e_type), 'loads' [(vaddr, off, filesz, flags)], 'phs' [p_type], 'dyn' {tag: first value}, 'secs' {name: (addr,
    off, size)}, 'tables' [(section name, [(r_offset, type, sym_index, addend|None, symbol name, sym value, defined)])]}.
    Section headers first (sh_link -> dynsym -> dynstr); an sstripped image falls back to PT_DYNAMIC (DT_RELA /
    DT_JMPREL / DT_REL / DT_RELR, names .rela.dyn/.rela.plt/.rel.dyn/.rel.plt/.relr.dyn)."""
    if len(data) < 52 or data[:4] != b"\x7fELF" or data[4] not in (1, 2) or data[5] not in (1, 2):
        return None
    b64, E = data[4] == 2, "<" if data[5] == 1 else ">"
    psz = 8 if b64 else 4
    et, mach = struct.unpack_from(E + "HH", data, 16)
    if b64:
        phoff, shoff = struct.unpack_from(E + "QQ", data, 32)
        phes, phn, shes, shn, shstr = struct.unpack_from(E + "HHHHH", data, 54)
    else:
        phoff, shoff = struct.unpack_from(E + "II", data, 28)
        phes, phn, shes, shn, shstr = struct.unpack_from(E + "HHHHH", data, 42)
    n_ = len(data)
    loads, phs, dynseg = [], [], None
    for k in range(min(phn, 256)):
        p = phoff + k * phes
        if p + (56 if b64 else 32) > n_:
            break
        if b64:
            typ, flg, off, va, _pa, fsz, msz = struct.unpack_from(E + "IIQQQQQ", data, p)
        else:
            typ, off, va, _pa, fsz, msz, flg = struct.unpack_from(E + "IIIIIII", data, p)
        phs.append(typ)
        if typ == 1:
            loads.append((va, off, fsz, flg))
        elif typ == 2:
            dynseg = (off, fsz)

    def v2o(va):
        for lva, off, fsz, _f in loads:
            if lva <= va < lva + fsz:
                return off + va - lva
        return None

    secs, shs = {}, []
    if shoff and shes == (64 if b64 else 40) and shoff + shn * shes <= n_:
        fm = E + ("IIQQQQIIQQ" if b64 else "IIIIIIIIII")
        shs = [struct.unpack_from(fm, data, shoff + k * shes) for k in range(min(shn, 8192))]
    strt = shs[shstr] if shs and shstr < len(shs) else None

    def cstr(o, lim=512):
        if o is None or not 0 <= o < n_:
            return ""
        e = data.find(b"\0", o, o + lim)
        return data[o:e if e >= 0 else o].decode("latin-1")
    names = [cstr(strt[4] + s[0]) if strt else "" for s in shs]
    for nm, s in zip(names, shs):
        if nm:
            secs.setdefault(nm, (s[3], s[4], s[5]))
    dyn = {}
    if dynseg:
        de = 16 if b64 else 8
        for q in range(dynseg[0], min(dynseg[0] + dynseg[1], n_ - de + 1, dynseg[0] + (de << 12)), de):
            t, v = struct.unpack_from(E + ("qQ" if b64 else "iI"), data, q)
            if t == 0:
                break
            dyn.setdefault(t, v)

    def symtab(off, cnt, stroff, strsz):
        memo, es = {}, (24 if b64 else 16)

        def get(j):   # lazy: only the referenced symbols are decoded (a big .so exports 10^5 of them)
            if j in memo:
                return memo[j]
            q = off + j * es
            r = ("", 0, False)
            if 0 < j < cnt and q + es <= n_:
                if b64:
                    nm, _i, _o, shx, val = struct.unpack_from(E + "IBBHQ", data, q)
                else:
                    nm, val, _s, _i, _o, shx = struct.unpack_from(E + "IIIBBH", data, q)
                r = (cstr(stroff + nm, 256) if nm < max(strsz, 1) else "", val, shx != 0)
            memo[j] = r
            return r
        return get
    raw = []   # (name, off, size, rela?, relr?, syms)
    cache = {}
    for nm, s in zip(names, shs):
        if s[1] in (4, 9, 19) and s[5] and s[4] + s[5] <= n_ and (s[2] & 2 or s[1] == 19 or et != 1):
            syms = None
            if s[1] != 19 and 0 < s[6] < len(shs):
                ls = shs[s[6]]
                if ls[1] in (2, 11) and ls[6] < len(shs):
                    if s[6] not in cache:
                        st = shs[ls[6]]
                        cache[s[6]] = symtab(ls[4], ls[5] // (24 if b64 else 16), st[4], st[5])
                    syms = cache[s[6]]
            raw.append((nm or "?", s[4], s[5], s[1] == 4, s[1] == 19, syms))
    if not shs and dyn:
        syms = None
        so, sto = v2o(dyn.get(6, -1)), v2o(dyn.get(5, -1))
        if so is not None and sto is not None:
            cnt = max((sto - so) // (24 if b64 else 16), 0) if sto > so else 4096
            syms = symtab(so, cnt, sto, dyn.get(10, 1 << 20))
        pre = ".rela" if dyn.get(20, 7 if b64 else 17) == 7 else ".rel"
        for a, z, nm, isa in ((7, 8, ".rela.dyn", True), (17, 18, ".rel.dyn", False), (23, 2, pre + ".plt", pre == ".rela")):
            o = v2o(dyn.get(a, -1))
            if o is not None and dyn.get(z):
                raw.append((nm, o, dyn[z], isa, False, syms))
        o = v2o(dyn.get(36, -1))
        if o is not None and dyn.get(35):
            raw.append((".relr.dyn", o, dyn[35], False, True, None))
    tables, total = [], 0
    rd = (lambda o: struct.unpack_from(E + ("Q" if b64 else "I"), data, o)[0])
    for nm, off, size, isa, isr, syms in raw:
        ents = []
        if isr:   # DT_RELR: address entry, then bitmaps of the following 63 / 31 words (implicit addend on disk)
            base, bits = 0, psz * 8 - 1
            for q in range(off, min(off + size, n_ - psz + 1), psz):
                w = rd(q)
                if not w & 1:
                    ents.append(w)
                    base = w + psz
                else:
                    for k in range(bits):
                        if w >> (k + 1) & 1:
                            ents.append(base + k * psz)
                    base += bits * psz
                if len(ents) > ELF_RELOC_MAX:
                    break
            rel = {62: 8, 3: 8, 183: 1027}.get(mach, 8)
            ents = [(r, rel, 0, None, "", 0, False) for r in ents]
        else:
            es = (24 if isa else 16) if b64 else (12 if isa else 8)
            fm = E + (("QQq" if isa else "QQ") if b64 else ("IIi" if isa else "II"))
            cnt = min(size, n_ - off, es * (ELF_RELOC_MAX - total + 1)) // es
            sh, lo = (32, 0xffffffff) if b64 else (8, 0xff)
            nosym = ("", 0, False)
            for t in struct.iter_unpack(fm, data[off:off + cnt * es]):
                si = t[1] >> sh
                sn, sv, sd = syms(si) if si and syms else nosym
                ents.append((t[0], t[1] & lo, si, t[2] if isa else None, sn, sv, sd))
        total += len(ents)
        tables.append((nm, ents))
        if total > ELF_RELOC_MAX:
            break
    return {"bits": 64 if b64 else 32, "E": E, "mach": mach, "type": et, "loads": loads, "phs": phs, "dyn": dyn,
            "secs": secs, "tables": tables, "v2o": v2o, "psz": psz}


def _reloc_target(R, data, r):
    """Link-time value the loader stores at r_offset (base 0) for RELATIVE / IRELATIVE (the resolver) / absolute /
    GLOB_DAT / JUMP_SLOT of a DEFINED symbol, else None. REL / RELR addends are read from the slot on disk."""
    ro, typ, _si, add, _sn, sv, sd = r
    nm = _RT_ARCH.get(R["mach"], ("", {}))[1].get(typ, "")
    if add is None:
        o = R["v2o"](ro)
        if o is None or o + R["psz"] > len(data):
            return None
        add = struct.unpack_from(R["E"] + ("Q" if R["psz"] == 8 else "I"), data, o)[0]
        if nm in ("GLOB_DAT", "JUMP_SLOT"):
            add = 0
    if nm in ("RELATIVE", "IRELATIVE", "RELATIVE64"):
        return add & ((1 << R["bits"]) - 1)
    if nm in ("64", "32", "ABS64", "ABS32", "GLOB_DAT", "JUMP_SLOT") and sd:
        return (sv + add) & ((1 << R["bits"]) - 1)
    return None


def elf_relocated_image(data):
    """A copy of the ELF bytes with every resolvable dynamic relocation applied at base 0 (RELATIVE addend, defined
    GLOB_DAT/JUMP_SLOT/ABS symbol value + addend; imports and IRELATIVE left as on disk), else None. Feed it to
    hcfg_scan / string tools when a pointer table is zero in the file (lld, -z nopack: RELA addends not in place)."""
    try:
        R = _elf_relocs(bytes(data))
        if R is None:
            return None
        out = bytearray(data)
        fm = R["E"] + ("Q" if R["psz"] == 8 else "I")
        for _nm, ents in R["tables"]:
            for r in ents:
                v = _reloc_target(R, data, r)
                o = R["v2o"](r[0])
                if v is not None and o is not None and o + R["psz"] <= len(out) and \
                        _RT_ARCH.get(R["mach"], ("", {}))[1].get(r[1]) != "IRELATIVE":
                    struct.pack_into(fm, out, o, v)
        return bytes(out)
    except Exception:  # noqa: BLE001 - hostile bytes
        return None


def elf_reloc_facts(data):
    """Dynamic-relocation facts of an ELF (pure struct walk; no subprocess), None when not a readable ELF. Keys
    (SPECULATIVE names, values as readelf -rW / checksec print them):
      relocation_sections  JSON list of reloc section names in file order ('.rela.dyn', '.rela.plt', '.relr.dyn')
      relocations          {section: [{offset '0x..', type 'R_X86_64_JUMP_SLOT', symbol (unversioned, '' none),
                            addend int|None}]}
      counts               {type name: n} over every section; relocation_count (total), <section>_count
                            ('rela_dyn_count', 'rela_plt_count', ...), jump_slot_count / glob_dat_count /
                            relative_count / irelative_count / copy_count
      plt_imports          JSON list of .rela.plt / .rel.plt symbols in table order ('*ABS*+0x..' for IRELATIVE)
      plt_import_count, got_slots {'0x<GOT r_offset>': name} (JUMP_SLOT + GLOB_DAT), plt_stubs {'0x<stub>': name}
                            (x86-64: .plt.sec[i] or .plt[i+1] for the i-th GOT slot, the objdump '<name@plt>' labels)
      copy_symbols         JSON list of R_*_COPY symbols; glob_dat_symbols JSON list
      bind_now             'true' iff DT_BIND_NOW / DT_FLAGS BIND_NOW / DT_FLAGS_1 NOW; lazy_binding = PLT relocs
                            present and not bind_now ('true'/'false')
      relro                full / partial / none (GNU_RELRO + bind_now, checksec rules); has_relro
      config_pointer       '0x<r_offset>' of the first relocation whose target is an HCFG blob ('none')."""
    try:
        data = bytes(data)
        R = _elf_relocs(data)
        if R is None:
            return None
        pre, tab = _RT_ARCH.get(R["mach"], ("R_", {}))
        tn = (lambda t: pre + tab[t] if t in tab else f"unrecognized: {t:x}")
        rels, counts, kinds = {}, {}, {k: 0 for k in _RT_KINDS}
        plt, got, cps, gds, stubs, pslot = [], {}, [], [], {}, []
        cfg_ptr = "none"
        for nm, ents in R["tables"]:
            lst = rels.setdefault(nm, [])
            for r in ents:
                t = tn(r[1])
                short = tab.get(r[1], "")
                lst.append({"offset": f"0x{r[0]:x}", "type": t, "symbol": r[4], "addend": r[3]})
                counts[t] = counts.get(t, 0) + 1
                if short in kinds:
                    kinds[short] += 1
                if nm.endswith(".plt"):
                    plt.append(r[4] if r[4] or short != "IRELATIVE" else f"*ABS*+0x{(r[3] or 0):x}")
                    pslot.append((r[0], plt[-1]))
                if short in ("JUMP_SLOT", "GLOB_DAT") and r[4]:
                    got[f"0x{r[0]:x}"] = r[4]
                if short == "COPY":
                    cps.append(r[4])
                elif short == "GLOB_DAT":
                    gds.append(r[4])
                if cfg_ptr == "none":
                    v = _reloc_target(R, data, r)
                    o = R["v2o"](v) if v is not None else None
                    if o is not None and data[o:o + 4] == HCFG_MAGIC:
                        cfg_ptr = f"0x{r[0]:x}"
        if R["mach"] == 62 and plt:
            sec = R["secs"].get(".plt.sec")
            first, s = (0, sec) if sec else (1, R["secs"].get(".plt"))
            if s and s[0]:
                for i, (_g, n) in enumerate(sorted(pslot)):   # stub i <-> i-th GOT slot (ld sorts IRELATIVE last in .rela.plt)
                    stubs[f"0x{s[0] + 16 * (i + first):x}"] = n
        d = R["dyn"]
        now = 24 in d or bool(d.get(30, 0) & 8) or bool(d.get(0x6ffffffb, 0) & 1)
        relro = ("full" if now else "partial") if 0x6474e552 in R["phs"] else "none"
        tf = (lambda v: "true" if v else "false")
        out = {"relocation_sections": json.dumps([nm for nm, _ in R["tables"]]), "relocations": rels,
               "counts": counts, "relocation_count": sum(counts.values()),
               "plt_imports": json.dumps(plt), "plt_import_count": len(plt), "got_slots": got, "plt_stubs": stubs,
               "copy_symbols": json.dumps(cps), "glob_dat_symbols": json.dumps(gds),
               "bind_now": tf(now), "lazy_binding": tf(plt and not now), "relro": relro, "has_relro": tf(relro != "none"),
               "config_pointer": cfg_ptr}
        for k, v in kinds.items():
            out[k.lower() + "_count"] = v
        for nm, ents in R["tables"]:
            out[nm.strip(".").replace(".", "_") + "_count"] = len(ents)
        return out
    except Exception:  # noqa: BLE001 - truncated / hostile ELF
        return None


def elf_reloc_field(data, name):
    """One elf_reloc_facts value ('none' for an absent field); None when the input is not a readable ELF."""
    f = elf_reloc_facts(data)
    if f is None:
        return None
    k = name.strip().lower().replace("-", "_").replace(" ", "_")
    if k in f:
        return f[k]
    for t, n in f["counts"].items():   # 'R_X86_64_JUMP_SLOT' / 'jump_slot' -> its count
        if k in (t.lower(), t.lower().split("_", 3)[-1], t.lower() + "_count"):
            return n
    return "none"


# libc names an LD_PRELOAD shim typically re-exports (defined dynsym with one of these names == interposition)
LIBC_INTERPOSE_NAMES = frozenset((
    "__libc_start_main open open64 openat openat64 creat fopen fopen64 freopen fdopen close fclose read write pread "
    "pwrite readv writev fread fwrite fgets fputs puts printf fprintf vprintf vfprintf sprintf snprintf dprintf "
    "putchar fputc getc fgetc getchar ungetc perror stat stat64 lstat lstat64 fstat fstat64 __xstat __xstat64 "
    "__lxstat __lxstat64 __fxstat __fxstat64 fstatat statx access faccessat unlink unlinkat rename renameat "
    "mkdir rmdir chdir getcwd opendir readdir readdir64 closedir scandir readlink readlinkat realpath chmod chown "
    "truncate ftruncate lseek lseek64 dup dup2 pipe mmap mmap64 munmap mprotect brk sbrk malloc calloc realloc "
    "free memalign posix_memalign aligned_alloc valloc memcpy memmove memset memcmp strcmp strncmp strcasecmp "
    "strlen strcpy strncpy strcat strdup strstr strchr strrchr getenv setenv unsetenv putenv secure_getenv "
    "clearenv dlopen dlsym dlvsym dlclose dlerror dladdr fork vfork clone execve execv execvp execvpe execl "
    "execlp execle system popen pclose posix_spawn posix_spawnp kill raise signal sigaction exit _exit abort "
    "atexit getpid getppid getuid geteuid getgid getegid setuid setgid getlogin getpwnam getpwuid gethostname "
    "uname sysinfo time gettimeofday clock_gettime sleep usleep nanosleep rand srand random srandom ptrace "
    "prctl ioctl fcntl syscall socket connect bind listen accept accept4 send sendto sendmsg recv recvfrom "
    "recvmsg getaddrinfo gethostbyname inet_ntoa inet_pton select poll epoll_wait pthread_create "
    "pthread_mutex_lock SSL_read SSL_write SSL_connect PAM_authenticate pam_authenticate").split())

_VD_FLAGS = ((1, "BASE"), (2, "WEAK"), (4, "INFO"))
_ST_BIND = {0: "LOCAL", 1: "GLOBAL", 2: "WEAK", 10: "UNIQUE"}
_ST_TYPE = {0: "NOTYPE", 1: "OBJECT", 2: "FUNC", 3: "SECTION", 4: "FILE", 5: "COMMON", 6: "TLS", 10: "IFUNC"}
_ST_VIS = {0: "DEFAULT", 1: "INTERNAL", 2: "HIDDEN", 3: "PROTECTED"}
SYMVER_MAX_SYMS = 1 << 17      # dynsym entries decoded per image
SYMVER_DISASM_FUNCS = 64       # functions disassembled (RTLD_NEXT / returned-string checks)
_SV_MEMO = [None, None]


def _vd_flags(f):
    s = [n for b, n in _VD_FLAGS if f & b]
    return " | ".join(s) if s else "none"


def elf_version_facts(data):
    """GNU symbol versioning + interposition facts of an ELF .so/executable (pure struct walk + capstone), None when
    not a readable ELF. Labels as readelf -VW / --dyn-syms -W print them. Keys (SPECULATIVE names):
      verdefs           [{index, flags ('BASE'/'WEAK'/'none'), name, parents [..]}] in .gnu.version_d order ("none")
      verdef_names      [names] (base = soname first); base_version; version_count (non-base verdefs)
      verneeds          {file: [version names]} in .gnu.version_r order ("none"); verneed_files; needed_versions
      dynsyms           [{index, name, label ('cfg_get@@V2' / 'cfg_get@V1' / 'puts@GLIBC_2.2.5'), version, default
                         ('@@' defined default, '@' hidden/needed, '' none), hidden, versym, bind, type, vis, ndx,
                         value '0x..', size}] (index 0 skipped)
      versioned_symbols [labels with @/@@]; default_versions {sym: ver}; hidden_versions [sym@ver];
      symbol_versions   {sym: [ver, ..]} (defined, default first); multi_version_symbols [sym]
      weak_symbols / unique_symbols / local_symbols / protected_symbols / hidden_symbols [names] ("none")
      exported_symbols  [defined non-LOCAL names]; imports [undefined names]
      interposed        [defined FUNC dynsyms named like libc (open, getenv, dlsym, __libc_start_main ...)]
      rtld_next_callers [defined functions calling dlsym/dlvsym(RTLD_NEXT=-1, ..)]; calls_rtld_next 'true'/'false'
      interposed_rtld_next {name: 'true'/'false'}; returns {label: C string a versioned function returns}
      default_return    string returned by the '@@' version of a multi-version symbol ("none")."""
    try:
        if _SV_MEMO[0] is data:
            return _SV_MEMO[1]
        f = _elf_version_facts(bytes(data))
        _SV_MEMO[:] = [data, f]
        return f
    except Exception:  # noqa: BLE001 - truncated / hostile ELF
        return None


def _elf_version_facts(data):
    R = _elf_relocs(data)
    if R is None:
        return None
    E, b64, n_ = R["E"], R["bits"] == 64, len(data)
    secs, dyn, v2o = R["secs"], R["dyn"], R["v2o"]
    es = 24 if b64 else 16

    def loc(sec, tag):   # (file offset, size|None) from the section header, else the PT_DYNAMIC tag
        s = secs.get(sec)
        if s and s[1] and s[1] < n_:
            return s[1], s[2]
        o = v2o(dyn[tag]) if tag in dyn else None
        return (o, None) if o is not None else (None, None)
    so, ssz = loc(".dynsym", 6)
    sto, stsz = loc(".dynstr", 5)
    stsz = stsz or dyn.get(10) or (n_ - sto if sto is not None else 0)

    def cstr(o, lim=512):
        if sto is None or not 0 <= o < stsz or sto + o >= n_:
            return ""
        e = data.find(b"\0", sto + o, sto + o + lim)
        return data[sto + o:e if e >= 0 else sto + o].decode("latin-1")
    if so is None or sto is None:
        nsym = 0
    elif ssz:
        nsym = ssz // es
    else:
        nsym = (sto - so) // es if sto > so else 4096
    nsym = max(0, min(nsym, (n_ - so) // es if so is not None else 0, SYMVER_MAX_SYMS))
    syms = []
    for j in range(nsym):
        q = so + j * es
        if b64:
            nm, info, oth, shx, val, sz = struct.unpack_from(E + "IBBHQQ", data, q)
        else:
            nm, val, sz, info, oth, shx = struct.unpack_from(E + "IIIBBH", data, q)
        syms.append((cstr(nm, 256), info >> 4, info & 15, oth & 3, shx, val, sz))
    # .gnu.version_d: Verdef {vd_version u16, vd_flags u16, vd_ndx u16, vd_cnt u16, vd_hash u32, vd_aux u32, vd_next}
    verdefs, vdname = [], {}
    o, _ = loc(".gnu.version_d", 0x6ffffffc)
    seen = set()
    while o is not None and o + 20 <= n_ and len(verdefs) < 4096 and o not in seen:
        seen.add(o)
        _v, fl, ndx, cnt, _h, aux, nxt = struct.unpack_from(E + "HHHHIII", data, o)
        names, a = [], o + aux
        for _k in range(min(cnt, 64)):
            if a + 8 > n_:
                break
            vn, an = struct.unpack_from(E + "II", data, a)
            names.append(cstr(vn))
            if not an:
                break
            a += an
        if names:
            verdefs.append({"index": ndx, "flags": _vd_flags(fl), "name": names[0], "parents": names[1:]})
            vdname[ndx] = names[0]
        if not nxt:
            break
        o += nxt
    # .gnu.version_r: Verneed {vn_version u16, vn_cnt u16, vn_file u32, vn_aux u32, vn_next u32};
    #                 Vernaux {vna_hash u32, vna_flags u16, vna_other u16, vna_name u32, vna_next u32}
    verneeds, vnname = {}, {}
    o, _ = loc(".gnu.version_r", 0x6ffffffe)
    seen = set()
    while o is not None and o + 16 <= n_ and len(verneeds) < 4096 and o not in seen:
        seen.add(o)
        _v, cnt, fil, aux, nxt = struct.unpack_from(E + "HHIII", data, o)
        lst, a = verneeds.setdefault(cstr(fil), []), o + aux
        for _k in range(min(cnt, 256)):
            if a + 16 > n_:
                break
            _h, _fl, oth, vn, an = struct.unpack_from(E + "IHHII", data, a)
            lst.append(cstr(vn))
            vnname[oth] = lst[-1]
            if not an:
                break
            a += an
        if not nxt:
            break
        o += nxt
    vo, _ = loc(".gnu.version", 0x6ffffff0)
    maxdef = max(vdname) if vdname else 0
    dsy, symvers = [], {}
    for j, (nm, bind, typ, vis, shx, val, sz) in enumerate(syms):
        if j == 0:
            continue
        vs = struct.unpack_from(E + "H", data, vo + 2 * j)[0] if vo is not None and vo + 2 * j + 2 <= n_ else 0
        idx, hid = vs & 0x7fff, bool(vs & 0x8000)
        ver, how = "", ""
        if idx > 1:   # readelf get_symbol_version_string: defined & visible -> verdef, else verneed
            if shx != 0 and not hid and idx <= maxdef and idx in vdname:
                ver, how = vdname[idx], "@@"
            elif idx in vnname:
                ver, how = vnname[idx], "@"
            elif idx in vdname:
                ver, how = vdname[idx], "@"
        lab = nm
        if ver and not (shx == 0xfff1 and nm == ver):   # the version's own ABS symbol prints bare
            lab = f"{nm}{how}{ver}"
        d = {"index": j, "name": nm, "label": lab, "version": ver or "none", "default": how, "hidden": hid,
             "versym": idx, "bind": _ST_BIND.get(bind, str(bind)), "type": _ST_TYPE.get(typ, str(typ)),
             "vis": _ST_VIS[vis], "ndx": "UND" if shx == 0 else "ABS" if shx == 0xfff1 else shx,
             "value": f"0x{val:x}", "size": sz, "_va": val}
        dsy.append(d)
        if ver and shx != 0 and shx != 0xfff1:
            symvers.setdefault(nm, []).append((how != "@@", ver))
    nz = (lambda v: v if v else "none")
    defd = [d for d in dsy if d["ndx"] != "UND"]
    names_of = (lambda pred: nz(list(dict.fromkeys(d["name"] for d in dsy if d["name"] and pred(d)))))
    sv = {k: [v for _h, v in sorted(vs)] for k, vs in symvers.items()}
    interposed = list(dict.fromkeys(d["name"] for d in defd if d["name"] in LIBC_INTERPOSE_NAMES
                                    and d["type"] in ("FUNC", "IFUNC", "NOTYPE") and d["bind"] != "LOCAL"))
    multi = [k for k, v in sv.items() if len(v) > 1]
    rtl, rets = _symver_code(data, R, defd, interposed, multi)
    dret = "none"
    for k in multi:
        lab = f"{k}@@{sv[k][0]}"
        if rets.get(lab):
            dret = rets[lab]
            break
    for d in dsy:
        d.pop("_va", None)
    return {
        "verdefs": nz(verdefs), "verdef_names": nz([v["name"] for v in verdefs]),
        "base_version": next((v["name"] for v in verdefs if v["flags"].startswith("BASE")), "none"),
        "version_count": len([v for v in verdefs if not v["flags"].startswith("BASE")]),
        "verneeds": nz(verneeds), "verneed_files": nz(list(verneeds)),
        "needed_versions": nz([v for vs in verneeds.values() for v in vs]),
        "dynsyms": nz(dsy), "versioned_symbols": nz([d["label"] for d in dsy if d["label"] != d["name"]]),
        "default_versions": nz({d["name"]: d["version"] for d in dsy if d["default"] == "@@" and d["label"] != d["name"]}),
        "hidden_versions": nz([d["label"] for d in dsy if d["hidden"] and d["ndx"] != "UND" and d["version"] != "none"]),
        "symbol_versions": nz(sv), "multi_version_symbols": nz(multi),
        "weak_symbols": names_of(lambda d: d["bind"] == "WEAK"),
        "unique_symbols": names_of(lambda d: d["bind"] == "UNIQUE"),
        "local_symbols": names_of(lambda d: d["bind"] == "LOCAL"),
        "protected_symbols": names_of(lambda d: d["vis"] == "PROTECTED"),
        "hidden_symbols": names_of(lambda d: d["vis"] in ("HIDDEN", "INTERNAL")),
        "exported_symbols": names_of(lambda d: d["ndx"] != "UND" and d["bind"] != "LOCAL"),
        "imports": names_of(lambda d: d["ndx"] == "UND"),
        "interposed": nz(interposed), "rtld_next_callers": nz(rtl),
        "calls_rtld_next": "true" if rtl else "false",
        "interposed_rtld_next": nz({k: "true" if k in rtl else "false" for k in interposed}),
        "returns": nz(rets), "default_return": dret,
    }


def _symver_code(data, R, defd, interposed, multi):
    """(functions calling dlsym/dlvsym with RTLD_NEXT (-1) as 1st arg, {label: string a short versioned function
    returns}) via capstone over x86 / x86-64 function bodies (dynsym st_size); helpers they call directly are followed
    one level (a lazy `real_open = dlsym(RTLD_NEXT, ..)` resolver)."""
    if R["mach"] not in (62, 3):
        return [], {}
    import capstone
    b64, v2o = R["mach"] == 62, R["v2o"]
    md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64 if b64 else capstone.CS_MODE_32)
    dls = set()   # dlsym call targets: PLT stubs + GOT slots (call [rip+X] under -fno-plt)
    f = elf_reloc_facts(data) or {}
    for k, v in (f.get("plt_stubs") or {}).items():
        if v in ("dlsym", "dlvsym"):
            dls.add(int(k, 16))
    for k, v in (f.get("got_slots") or {}).items():
        if v in ("dlsym", "dlvsym"):
            dls.add(int(k, 16))
    if not b64:   # i386 PLT: .plt[i+1] <-> i-th .rel.plt entry
        s = R["secs"].get(".plt")
        for nm, ents in R["tables"]:
            if nm.endswith(".plt") and s:
                for i, r in enumerate(ents):
                    if r[4] in ("dlsym", "dlvsym"):
                        dls.add(s[0] + 16 * (i + 1))
    budget = [SYMVER_DISASM_FUNCS * 4]
    ts = R["secs"].get(".text")
    text = (ts[0], ts[0] + ts[2]) if ts else (0, 1 << 64)

    def body(va, size):
        o = v2o(va)
        if o is None or budget[0] <= 0:
            return []
        budget[0] -= 1
        return list(md.disasm_lite(data[o:o + (size if 0 < size <= 1 << 16 else 2048)], va))

    def tgt(a, sz, op):
        m = re.fullmatch(r"(?:(?:qword|dword) ptr )?\[rip ([+-]) (0x[0-9a-f]+|\d+)\]", op)
        if m:
            return a + sz + int(m.group(2), 0) * (1 if m.group(1) == "+" else -1)
        try:
            return int(op, 0)
        except ValueError:
            return None

    def rtld(insns, depth):
        neg, pushes = False, []
        for a, sz, mn, op in insns:
            if mn in ("call", "jmp"):
                t = tgt(a, sz, op)
                if t in dls and (neg or "0xffffffff" in pushes[-3:]):
                    return True
                if mn == "call" and depth and t is not None and text[0] <= t < text[1]:
                    if rtld(body(t, 0), depth - 1):
                        return True
                neg, pushes = False, []
                if mn == "jmp" and t is None and depth == 0:
                    break
                continue
            if mn in ("ret", "hlt", "ud2"):
                if depth == 0:
                    break
                continue
            if op.startswith(("rdi,", "edi,", "dil,", "di,")) and mn not in ("cmp", "test", "push"):
                neg = mn in ("mov", "or") and op.split(",", 1)[1].strip() in ("0xffffffffffffffff", "-1")
            elif mn == "push":
                pushes.append(op)
            elif mn == "mov" and op.startswith("dword ptr [esp],"):
                pushes.append(op.split(",", 1)[1].strip())
        return False
    rtl = []
    for d in defd:
        # every interposed libc name; other exports only in a small (shim-sized) .so
        if d["type"] in ("FUNC", "IFUNC") and (d["name"] in interposed or len(defd) <= SYMVER_DISASM_FUNCS):
            if rtld(body(d["_va"], d["size"]), 1):
                rtl.append(d["name"])
    rets = {}
    for d in defd:
        if d["name"] in multi and d["type"] == "FUNC" and 0 < d["size"] <= 256:
            for a, sz, mn, op in body(d["_va"], d["size"]):
                if mn == "lea" and op.startswith(("rax,", "eax,")):
                    t = tgt(a, sz, op.split(",", 1)[1].strip())
                    o = v2o(t) if t is not None else None
                    if o is not None:
                        e = data.find(b"\0", o, o + 4096)
                        s = data[o:e] if e > o else b""
                        if s and all(32 <= c < 127 for c in s):
                            rets[d["label"]] = s.decode()
                    break
                if mn == "ret":
                    break
    return list(dict.fromkeys(rtl)), rets


def elf_version_field(data, name):
    """One elf_version_facts value by key ("none" for an absent field / unknown key; None when not a readable ELF).
    Per-symbol keys: version:<sym> (default '@@' version first, else the needed/hidden one), versions:<sym>,
    label:<sym>, binding:<sym>, visibility:<sym>, type:<sym>, interposed:<sym> / rtld_next:<sym> ('true'/'false'),
    returns:<sym|label> (the '@@' one for a bare multi-version name), verneed:<file>, flags:<ver>, index:<ver>."""
    try:
        f = elf_version_facts(data)
        if not isinstance(f, dict):
            return f
        k, _, arg = name.strip().partition(":")
        k, arg = k.strip().lower().replace("-", "_").replace(" ", "_"), arg.strip()
        if not arg:
            return f.get(k, "none")
        ds = [d for d in f["dynsyms"] if d["name"] == arg or d["label"] == arg] if f["dynsyms"] != "none" else []
        ds.sort(key=lambda d: (d["label"] != arg, d["default"] != "@@", d["ndx"] == "UND"))
        if k in ("version", "versions", "label", "binding", "bind", "visibility", "vis", "type"):
            if not ds:
                return "none"
            if k == "versions":
                return [d["version"] for d in ds if d["version"] != "none"] or "none"
            return ds[0][{"version": "version", "label": "label", "binding": "bind", "bind": "bind",
                          "visibility": "vis", "vis": "vis", "type": "type"}[k]]
        if k in ("interposed", "rtld_next", "calls_rtld_next"):
            lst = f["interposed"] if k == "interposed" else f["rtld_next_callers"]
            return "true" if lst != "none" and arg in lst else "false"
        if k == "returns":
            r = f["returns"] if f["returns"] != "none" else {}
            for d in ds:
                if d["label"] in r:
                    return r[d["label"]]
            return r.get(arg, "none")
        if k == "verneed":
            return (f["verneeds"] if f["verneeds"] != "none" else {}).get(arg, "none")
        if k in ("flags", "index", "parents"):
            v = next((v for v in (f["verdefs"] if f["verdefs"] != "none" else []) if v["name"] == arg), None)
            return "none" if v is None else (v[k] or "none") if k == "parents" else v[k]
        return "none"
    except Exception:  # noqa: BLE001
        return None


RELOC_TABLE_RUNS = 4096   # pointer-table runs looked at per image; nested scans capped separately


def _reloc_ptr_scan(data, emit, late, deadline):
    """HCFG pieces reachable only through relocations: a table of pointers (bytes 0 on disk under lld / RELA, or the
    addend written in place by GNU ld) filled by RELATIVE (or defined-symbol ABS/GLOB_DAT) relocations at a constant
    stride. stride = pointer size: NUL-terminated chunks; stride = 2 pointers: {ptr, len} pairs (len read on disk at
    slot + ptr size, else NUL-terminated). Chunks are joined in TABLE order (not file order) and the join is scanned;
    only crc-valid blobs are emitted: 'reloc-ptrtable' (raw) / 'reloc-ptrtable-<inner encoding>', offset = file
    offset of the chunk holding the blob's first byte, detail table=0x<vaddr> chunks=N."""
    R = _elf_relocs(data)
    if R is None:
        return
    psz, v2o, E = R["psz"], R["v2o"], R["E"]
    slots = {}
    for _nm, ents in R["tables"]:
        for r in ents:
            v = _reloc_target(R, data, r)
            if v is not None:
                slots.setdefault(r[0], v)
    if len(slots) < 2:
        return
    offs = sorted(slots)
    runs = []
    for stride in (psz, 2 * psz):
        i = 0
        while i < len(offs) and len(runs) < RELOC_TABLE_RUNS:
            j = i
            while j + 1 < len(offs) and offs[j + 1] - offs[j] == stride:
                j += 1
            if j > i:   # {ptr, len} tables: the len words are not relocated -> consecutive at 2*psz
                runs.append((stride, offs[i:j + 1]))
            i = j + 1
    rd = (lambda o: struct.unpack_from(E + ("Q" if psz == 8 else "I"), data, o)[0])
    nested = [64]
    groups = []   # each run split at entries that are not a readable chunk (a junk/NUL target ends a sub-table)
    for stride, run in runs:
        parts, total = [], 0
        for so in run + [None]:
            o = v2o(slots[so]) if so is not None else None
            n = None
            if o is not None and stride == 2 * psz:
                lo = v2o(so + psz)
                n = rd(lo) if lo is not None and lo + psz <= len(data) else None
                n = n if n and n <= 4096 else None
            if o is not None and n is None:
                e = data.find(b"\0", o, o + 4096)
                n = e - o if e >= 0 else 0
            if o is None or n <= 0 or o + n > len(data) or total + n > 1 << 16:
                if len(parts) >= 2:
                    groups.append(parts)
                parts, total = [], 0
                continue
            parts.append((o, data[o:o + n]))
            total += n
    for parts in groups:
        if late() or nested[0] <= 0:
            return
        cat = b"".join(p for _, p in parts)
        if not _ANCHORS.search(cat):
            continue
        nested[0] -= 1
        for h in hcfg_scan(cat, deadline=deadline, stop_on_valid=True, _depth=1):
            if not h.valid:
                continue
            at, pos = h.offset, parts[0][0]
            for o, p in parts:
                if at < len(p):
                    pos = o + at
                    break
                at -= len(p)
            blob = HCFG_MAGIC + struct.pack("<BBHI", h.version, h.key, h.length, h.crc) + bytes(c ^ h.key for c in h.plain)
            emit(pos, "reloc-ptrtable" + ("" if h.encoding == "raw" else "-" + h.encoding), blob,
                 f"chunks={len(parts)}")
            return


_WASM_MEMARG = set(range(0x28, 0x3f))            # loads/stores: memarg (align [+memidx], offset)
_WASM_STORE = {0x36: 4, 0x37: 8, 0x38: 4, 0x39: 8, 0x3a: 1, 0x3b: 2, 0x3c: 1, 0x3d: 2, 0x3e: 4}
_WASM_LEB1 = {0x0c, 0x0d, 0x10, 0x12, 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x3f, 0x40, 0xd2, 0xd0}
_WASM_LEB2 = {0x11, 0x13}
_WASM_FC = {8: 2, 9: 1, 10: 2, 11: 1, 12: 2, 13: 1, 14: 2, 15: 1, 16: 1, 17: 1}   # 0xfc sub-op -> LEB immediates


def wasm_memory_writes(data, lay=None, max_ops=500_000):
    """What instantiating + running the module's const-address code would put in linear memory, WITHOUT executing it:
    [(mem_addr, bytes, file_offset, kind)] in application order. kind "segment" = an active data segment at a constant
    offset (file_offset = its first payload byte); "init" = a passive segment copied by `i32.const dst; i32.const src;
    i32.const n; memory.init seg` (file_offset = the copied segment byte); "store" = `<const addr>; <const imm>;
    iNN.store[8/16/32] offset=k` (file_offset = the address const's opcode). A tiny const-only stack tracker over
    every function body: any non-const op forgets the tracked consts (no locals/globals/branches are modeled)."""
    lay = lay or wasm_layout(data)
    if not lay:
        return []
    segs = lay["data_segments"]
    out = [(s["mem_offset"], bytes(data[s["file_offset"]:s["file_offset"] + s["size"]]), s["file_offset"], "segment")
           for s in segs if s["mode"] == "active" and s["mem_offset"] is not None and s["size"]]
    code = next((s for s in lay["sections"] if s["id"] == 10), None)
    if not code:
        return out
    ops = 0
    try:
        n, p = _leb(data, code["offset"], cap=5)
        for _ in range(n):
            sz, p = _leb(data, p, cap=5)
            fe = p + sz
            nl, q = _leb(data, p, cap=5)
            for _l in range(nl):
                q = _leb(data, q, cap=5)[1] + 1
            st = []   # (value, opcode file offset) of the consecutive consts just pushed
            while q < fe and ops < max_ops:
                ops += 1
                op, at = data[q], q
                q += 1
                if op in (0x41, 0x42):
                    v, q = _leb(data, q, signed=True)
                    st.append((v & ((1 << (32 if op == 0x41 else 64)) - 1), at))
                    continue
                if op in _WASM_MEMARG:
                    al, q = _leb(data, q, cap=5)
                    if al & 0x40:
                        q = _leb(data, q, cap=5)[1]
                    mo, q = _leb(data, q)
                    w = _WASM_STORE.get(op)
                    if w and len(st) >= 2:
                        (a, aat), (v, _) = st[-2], st[-1]
                        out.append((a + mo, (v & ((1 << 8 * w) - 1)).to_bytes(w, "little"), aat, "store"))
                elif op in _WASM_LEB1:
                    q = _leb(data, q)[1]
                elif op in _WASM_LEB2:
                    q = _leb(data, _leb(data, q)[1])[1]
                elif op in (0x02, 0x03, 0x04):
                    q = _leb(data, q, signed=True, cap=5)[1]
                elif op == 0x0e:
                    k, q = _leb(data, q, cap=5)
                    for _b in range(k + 1):
                        q = _leb(data, q, cap=5)[1]
                elif op == 0x1c:
                    k, q = _leb(data, q, cap=5)
                    q += k
                elif op == 0x43:
                    q += 4
                elif op == 0x44:
                    q += 8
                elif op == 0xfc:
                    sub, q = _leb(data, q, cap=5)
                    imm = []
                    for _b in range(_WASM_FC.get(sub, 0) if sub <= 17 else -1):
                        v, q = _leb(data, q)
                        imm.append(v)
                    if sub > 17:
                        break
                    if sub == 8 and len(st) >= 3 and imm[0] < len(segs):   # memory.init seg: dst src n
                        s, d, src, ln = segs[imm[0]], st[-3][0], st[-2][0], st[-1][0]
                        if src + ln <= s["size"] and ln:
                            fo = s["file_offset"] + src
                            out.append((d, bytes(data[fo:fo + ln]), fo, "init"))
                elif not (op in (0x00, 0x01, 0x05, 0x0b, 0x0f, 0x1a, 0x1b, 0xd1) or 0x45 <= op <= 0xc4):
                    break   # SIMD/atomics/GC/unknown: stop this body (immediates not modeled)
                st = []
            p = fe
    except (IndexError, ValueError):
        pass
    return out


def wasm_memory_runs(data, lay=None, max_bytes=64 << 20):
    """The reassembled linear-memory image as contiguous runs [(base_addr, bytes, writes)] (writes = the
    wasm_memory_writes entries that built the run, application order: later writes win). Runs touching/adjacent
    writes are merged, so a blob split over adjacent segments or built by stores reads back contiguous."""
    ws = [w for w in wasm_memory_writes(data, lay) if w[1]]
    if sum(len(w[1]) for w in ws) > max_bytes:
        return []
    runs, cur = [], None
    for w in sorted(ws, key=lambda w: w[0]):
        if cur and w[0] <= cur[1]:
            cur[1] = max(cur[1], w[0] + len(w[1]))
            cur[2].append(w)
        else:
            cur = [w[0], w[0] + len(w[1]), [w]]
            runs.append(cur)
    out = []
    for lo, hi, mem in runs:
        mem.sort(key=ws.index) if len(mem) > 1 else None
        img = bytearray(hi - lo)
        for a, b, _fo, _k in mem:
            img[a - lo:a - lo + len(b)] = b
        out.append((lo, bytes(img), mem))
    return out


def _wasm_mem_src(writes, addr):
    """(file offset, kind) of the byte at linear-memory `addr` per the last write covering it."""
    for a, b, fo, k in reversed(writes):
        if a <= addr < a + len(b):
            return (fo + addr - a if k != "store" else fo), k
    return None, None


def _wasm_mem_scan(data, emit, deadline, _depth):
    """hcfg_scan pass for wasm: a blob not contiguous in the file (split over adjacent active segments, a passive
    segment placed by memory.init next to another, or built by const stores in code) -> scan every COMPOSITE run of the
    reassembled linear memory. Encoding wasm-<split|init|store>-<inner>; offset = the file byte that the blob's first
    stored byte came from (store: the address i32.const opcode); detail mem=<linear address>."""
    for lo, img, ws in wasm_memory_runs(data):
        if len(ws) < 2 or len(img) > 8 << 20:
            continue   # a single-source run is already plain bytes in the file
        for h in hcfg_scan(img, deadline=deadline, stop_on_valid=True, _depth=_depth + 1):
            if h.valid:
                fo, k = _wasm_mem_src(ws, lo + h.offset)
                if fo is not None:
                    kind = {"segment": "split"}.get(k, k)
                    emit(fo, f"wasm-{kind}-{h.encoding}", struct.pack("<4sBBHI", HCFG_MAGIC, h.version, h.key, h.length, h.crc) +
                         bytes(c ^ h.key for c in h.plain), (f"mem={lo + h.offset} " + h.detail).strip())
                return


# ------------------------------------------------------------------ LLVM bitcode string constants
_BC_MAGIC = b"BC\xc0\xde"
_BC_WRAPPER = b"\xde\xc0\x17\x0b"   # 0x0B17C0DE LE: {magic, version, offset, size, cputype} then the raw bitcode
_BC_CHAR6 = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._"
_BC_ENTER = {0, 8, 11}   # BLOCKINFO, MODULE, module-level CONSTANTS (global strings): every other block skipped by length


def bitcode_strings(data, start=0, max_ops=2_000_000):
    """[(bit offset of the first element, bytes, element bit width or None for vbr)] of every i8 string constant (CST_CODE_STRING 8 / CSTRING 9 / DATA 22
    with all elements < 256) in the LLVM bitstream at data[start:] ('BC' 0xC0DE magic). Pure Python LLVM bitstream
    reader (abbrevs + BLOCKINFO); [] if it does not parse. Bit offsets are absolute in `data`."""
    out = []
    n_bits = len(data) * 8
    pos = [start * 8 + 32]
    budget = [max_ops]

    def rd(w):
        p = pos[0]
        if w == 0:
            return 0
        if p + w > n_bits:
            raise IndexError
        pos[0] = p + w
        return (int.from_bytes(data[p >> 3:(p + w + 7 >> 3) + 1], "little") >> (p & 7)) & ((1 << w) - 1)

    def vbr(w):
        hi, v, s = 1 << (w - 1), 0, 0
        while True:
            c = rd(w)
            v |= (c & (hi - 1)) << s
            if not c & hi:
                return v
            s += w - 1
            if s > 64:
                raise ValueError

    def align():
        pos[0] = (pos[0] + 31) & ~31

    def scalar(op):
        kind, w = op
        return rd(w) if kind == 1 else vbr(w) if kind == 2 else _BC_CHAR6[rd(6)] if kind == 4 else None

    blockinfo = {}

    def block(bid, width, end):
        abbrevs = list(blockinfo.get(bid, ()))
        cur = None   # BLOCKINFO SETBID target
        while pos[0] < end:
            budget[0] -= 1
            if budget[0] < 0:
                raise ValueError
            a = rd(width)
            if a == 0:
                align()
                return
            if a == 1:
                sub, w2 = vbr(8), vbr(4)
                align()
                n = rd(32)
                e2 = pos[0] + 32 * n
                if e2 > n_bits or not w2:
                    raise ValueError
                if sub in _BC_ENTER:
                    block(sub, w2, e2)
                pos[0] = e2
                continue
            if a == 2:
                ops = []
                for _ in range(vbr(5)):
                    if rd(1):
                        ops.append((0, vbr(8)))
                    else:
                        k = rd(3)
                        if k not in (1, 2, 3, 4, 5):
                            raise ValueError
                        ops.append((k, vbr(5) if k in (1, 2) else 0))
                (blockinfo.setdefault(cur, []) if bid == 0 else abbrevs).append(ops)
                continue
            first, ew = None, None
            if a == 3:
                code, n = vbr(6), vbr(6)
                first = pos[0]
                vals = [vbr(6) for _ in range(n)]
            else:
                if a - 4 >= len(abbrevs):
                    raise ValueError
                ops, vals, i = abbrevs[a - 4], [], 0
                while i < len(ops):
                    kind, v = ops[i]
                    if kind == 0:
                        vals.append(v)
                    elif kind == 3:
                        n, el = vbr(6), ops[i + 1]
                        first, ew = pos[0], {0: 0, 1: el[1], 4: 6}.get(el[0])
                        vals.extend(el[1] if el[0] == 0 else scalar(el) for _ in range(n))
                        budget[0] -= n
                        i += 1
                    elif kind == 5:
                        n = vbr(6)
                        align()
                        first, ew = pos[0], 8
                        vals.extend(data[pos[0] >> 3:(pos[0] >> 3) + n])
                        pos[0] += 8 * n
                        align()
                    else:
                        vals.append(scalar(ops[i]))
                    i += 1
                code, vals = vals[0], vals[1:]
            if bid == 0 and code == 1 and vals:
                cur = vals[0]
            elif bid == 11 and code in (8, 9, 22) and vals and all(0 <= c < 256 for c in vals):
                out.append((first if first is not None else pos[0], bytes(vals), ew))

    try:
        while pos[0] + 36 <= n_bits:
            if rd(2) != 1:
                break
            sub, w2 = vbr(8), vbr(4)
            align()
            n = rd(32)
            e2 = pos[0] + 32 * n
            if e2 > n_bits or not w2:
                break
            if sub in _BC_ENTER:
                block(sub, w2, e2)
            pos[0] = e2
    except (IndexError, ValueError, TypeError, RecursionError):
        pass
    return out


def _bitcode_scan(data, emit, deadline, _depth):
    """hcfg_scan pass for LLVM bitcode (raw 'BC' 0xC0DE, the 0x0B17C0DE wrapper, or an embedded .llvmbc copy):
    decode every i8 string constant and scan them. Encoding bitcode-<inner> (bitcode-raw = the blob bytes are the
    string); offset (SPECULATIVE) = the file byte holding the first bit of the blob's first stored element."""
    i, n = data.find(_BC_MAGIC), 0
    while i >= 0 and n < 8:
        strs = bitcode_strings(data, i)
        if strs:
            buf, marks, p = bytearray(), [], 0
            for bit, s, w in strs:
                marks.append((p, bit, w))
                buf += s + b"\n"
                p += len(s) + 1
            for h in hcfg_scan(bytes(buf), deadline=deadline, stop_on_valid=True, _depth=_depth + 1):
                if h.valid:
                    for p0, bit, w in reversed(marks):
                        if p0 <= h.offset:
                            break
                    # fixed-width elements (Fixed 8/7, char6, blob 8): exact; vbr6: the string's first element
                    emit((bit + (h.offset - p0) * (w or 0)) // 8, f"bitcode-{h.encoding}",
                         struct.pack("<4sBBHI", HCFG_MAGIC, h.version, h.key, h.length, h.crc) +
                         bytes(c ^ h.key for c in h.plain), (f"str+{h.offset - p0} " + h.detail).strip())
                    return
        i, n = data.find(_BC_MAGIC, i + 4), n + 1


# --- robust constant recovery (replaces the fragile b8..c3 regex) --------------------------------
def recover_return_constants(data, max_funcs=400):
    """Find functions that return an immediate constant, via capstone linear disassembly from the ELF's
    symbol/section entry points — robust where the old `\\xb8(.{4})\\xc3` whole-.text regex went ambiguous.
    Returns {addr: const} for `mov eax/rax, imm; ret` leaves. Works stripped (scans .text) and unstripped."""
    try:
        import capstone
        from elftools.elf.elffile import ELFFile
    except ImportError:
        return {}
    try:
        elf = ELFFile(io.BytesIO(data))
    except Exception:  # noqa: BLE001
        return {}
    text = elf.get_section_by_name(".text")
    if not text:
        return {}
    code, base = text.data(), text["sh_addr"]
    bits = 64 if elf.elfclass == 64 else 32
    md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64 if bits == 64 else capstone.CS_MODE_32)
    out = {}
    last_imm = None
    last_addr = None
    for ins in md.disasm(code, base):
        if ins.mnemonic == "mov" and ins.op_str.split(",")[0].strip() in ("eax", "rax", "al", "ax"):
            m = re.search(r",\s*(?:0x[0-9a-fA-F]+|\d+)$", ins.op_str)
            if m:
                last_imm = int(m.group(0).lstrip(", ").strip(), 0)
                last_addr = ins.address
        elif ins.mnemonic == "ret" and last_imm is not None and last_addr is not None:
            out[hex(last_addr)] = last_imm
            last_imm = last_addr = None
            if len(out) >= max_funcs:
                break
        elif ins.mnemonic not in ("nop",):
            # only a mov-imm immediately followed by ret counts as a return-constant leaf
            if ins.mnemonic != "mov":
                last_imm = last_addr = None
    return out


_EMU_RELATIVE = {62: 8, 183: 1027, 3: 8}   # e_machine -> R_*_RELATIVE (x86-64, AArch64, i386 REL)


def emulate_return_value(data, symbol="recover_code", *, signed=False, max_insns=200_000, timeout_ms=300):
    """Return value of ELF function `symbol` (FUNC symbol name or vaddr int) by emulation, for computed returns that
    are not a `mov eax, imm; ret` leaf (xor of immediates, table lookup, flattened switch, internal helper calls).
    unicorn x86-64 / i386 / AArch64: PT_LOADs mapped at their vaddrs (ET_DYN rebased, R_*_RELATIVE applied), scratch
    stack, return address = sentinel page; eax / w0 at the sentinel (unsigned 32-bit unless signed=True).
    -> int; "none" if the ELF has no such FUNC symbol; None if not an ELF / unsupported arch / refused (syscall,
    int/svc, call through the PLT or an unrelocated GOT slot into libc, fetch outside an executable segment,
    instruction cap or timeout)."""
    try:
        import unicorn as U
        from elftools.elf.elffile import ELFFile
    except ImportError:
        return None
    try:
        elf = ELFFile(io.BytesIO(data))
        mach = elf["e_machine"]
        mach = {"EM_X86_64": 62, "EM_AARCH64": 183, "EM_386": 3}.get(mach, mach)
        if mach not in _EMU_RELATIVE or (mach == 3) != (elf.elfclass == 32):
            return None
        e = "<" if elf.little_endian else ">"
        b64 = elf.elfclass == 64
        secs = list(elf.iter_sections())
        if isinstance(symbol, int):
            addr = symbol
        else:
            addr, want = None, symbol.encode()
            for sec in secs:   # raw structs: pyelftools symbol iteration is seconds on a 50k-symbol Go/Rust binary
                if sec["sh_type"] not in ("SHT_SYMTAB", "SHT_DYNSYM") or addr is not None:
                    continue
                strs = secs[sec["sh_link"]].data() if 0 <= sec["sh_link"] < len(secs) else b""
                hits, i = set(), strs.find(b"\0" + want + b"\0")
                while i >= 0:
                    hits.add(i + 1)
                    i = strs.find(b"\0" + want + b"\0", i + 1)
                if strs.startswith(want + b"\0"):
                    hits.add(0)
                if not hits:
                    continue
                fmt, ent = (e + "IBxHQQ", 24) if b64 else (e + "IIIBxH", 16)
                raw = sec.data()
                for t in struct.iter_unpack(fmt, raw[:len(raw) // ent * ent]):
                    nm, val, info, shndx = (t[0], t[3], t[1], t[2]) if b64 else (t[0], t[1], t[3], t[4])
                    if nm in hits and info & 0xF == 2 and val and shndx:
                        addr = val
                        break
            if addr is None:
                return "none"
        base = 0x10000000 if elf["e_type"] == "ET_DYN" else 0
        pages = {}   # page -> prot
        loads = []
        for seg in elf.iter_segments():
            if seg["p_type"] != "PT_LOAD" or not seg["p_memsz"]:
                continue
            va, msz = seg["p_vaddr"] + base, seg["p_memsz"]
            if msz > 64 << 20:
                return None
            prot = U.UC_PROT_READ | U.UC_PROT_WRITE | (U.UC_PROT_EXEC if seg["p_flags"] & 1 else 0)
            for p in range(va & ~0xfff, (va + msz + 0xfff) & ~0xfff, 0x1000):
                pages[p] = pages.get(p, 0) | prot
            off, fsz = seg["p_offset"], min(seg["p_filesz"], max(0, len(data) - seg["p_offset"]))
            loads.append((va, data[off:off + fsz]))
        if not pages or len(pages) > 32768:
            return None
        rel_type = _EMU_RELATIVE[mach]
        rels = []
        if base:
            for sec in secs:
                rela = sec["sh_type"] == "SHT_RELA"
                if not rela and sec["sh_type"] != "SHT_REL":
                    continue
                fmt = e + ("QQq" if b64 else "Iii") if rela else e + ("QQ" if b64 else "II")
                ent = struct.calcsize(fmt)
                raw = sec.data()
                for t in struct.iter_unpack(fmt, raw[:len(raw) // ent * ent]):
                    if (t[1] & 0xffffffff if b64 else t[1] & 0xff) == rel_type:
                        rels.append((t[0] + base, t[2] if rela else None))
                        if len(rels) >= 500_000:
                            return None
        plt = [(s["sh_addr"] + base, s["sh_addr"] + base + s["sh_size"]) for s in secs
               if s.name.startswith(".plt") and s["sh_size"]]
    except Exception:  # noqa: BLE001 -- hostile / truncated ELF
        return None
    if mach == 183:
        uc = U.Uc(U.UC_ARCH_ARM64, U.UC_MODE_ARM)
        A = U.arm64_const
        SP, RET = A.UC_ARM64_REG_SP, A.UC_ARM64_REG_W0
    else:
        uc = U.Uc(U.UC_ARCH_X86, U.UC_MODE_64 if mach == 62 else U.UC_MODE_32)
        X = U.x86_const
        SP, RET = (X.UC_X86_REG_RSP, X.UC_X86_REG_EAX) if mach == 62 else (X.UC_X86_REG_ESP, X.UC_X86_REG_EAX)
    w = 4 if mach == 3 else 8
    bad = []
    try:
        run = []
        for p in sorted(pages):
            if run and p == run[-1][0] + run[-1][1] and pages[p] == run[-1][2]:
                run[-1][1] += 0x1000
            else:
                run.append([p, 0x1000, pages[p]])
        for p, n, prot in run:
            uc.mem_map(p, n, prot)
        for va, blob in loads:
            uc.mem_write(va, blob)
        for off, add in rels:
            if add is None:   # REL (i386): addend in place
                add = int.from_bytes(uc.mem_read(off, w), "little")
            uc.mem_write(off, ((add + base) & ((1 << (8 * w)) - 1)).to_bytes(w, "little"))
        top = (max(pages) + 0x100000 + 0xfffff) & ~0xfffff
        stk, sent = top, top + 0x40000
        uc.mem_map(stk, 0x40000)
        uc.mem_map(sent, 0x1000, U.UC_PROT_READ | U.UC_PROT_EXEC)
        sp = stk + 0x30000
        if mach == 183:
            uc.reg_write(A.UC_ARM64_REG_X30, sent)
            uc.reg_write(A.UC_ARM64_REG_X29, sp)
        else:
            sp -= w
            uc.mem_write(sp, sent.to_bytes(w, "little"))
        uc.reg_write(SP, sp)

        def refuse(why):
            def cb(uc, *a):
                bad.append(why)
                uc.emu_stop()
            return cb
        uc.hook_add(U.UC_HOOK_INTR, refuse("int/svc"))
        if mach == 62:
            uc.hook_add(U.UC_HOOK_INSN, refuse("syscall"), None, 1, 0, U.x86_const.UC_X86_INS_SYSCALL)
            uc.hook_add(U.UC_HOOK_INSN, refuse("sysenter"), None, 1, 0, U.x86_const.UC_X86_INS_SYSENTER)
        for lo, hi in plt:
            uc.hook_add(U.UC_HOOK_CODE, refuse("plt"), None, lo, hi - 1)
        uc.hook_add(U.UC_HOOK_MEM_INVALID, refuse("mem"))
        uc.emu_start(addr + base, sent, timeout=timeout_ms * 1000, count=max_insns)
        if bad or uc.reg_read(U.arm64_const.UC_ARM64_REG_PC if mach == 183 else
                              (X.UC_X86_REG_RIP if mach == 62 else X.UC_X86_REG_EIP)) != sent:
            return None
        v = uc.reg_read(RET) & 0xffffffff
    except Exception:  # noqa: BLE001 -- unicorn on hostile bytes: never raise past the caller
        return None
    return v - (1 << 32) if signed and v >> 31 else v


# --- Ghidra headless decompile -------------------------------------------------------------------
def ghidra_decompile(path, timeout=300):
    """Decompile every function with Ghidra headless (JDK 21 wired in launch.properties) and return the C
    text. Empty string on failure. Heavy (~minutes) — use only when symbol/pattern reads don't suffice."""
    headless = Path(__file__).resolve().parents[1] / "bin" / "analyzeHeadless"
    if not headless.exists() or not GHIDRA_SCRIPT.exists():
        return ""
    with tempfile.TemporaryDirectory() as proj, tempfile.NamedTemporaryFile(suffix=".c") as outf:
        # Output must live OUTSIDE the project dir: -deleteProject wipes the project tree on exit.
        subprocess.run(
            [str(headless), proj, "P", "-import", str(path), "-scriptPath", str(GHIDRA_SCRIPT.parent),
             "-postScript", GHIDRA_SCRIPT.name, outf.name, "-deleteProject"],
            capture_output=True, text=True, timeout=timeout)
        return Path(outf.name).read_text(errors="replace")


# --- HCFG config blob: every storage encoding -----------------------------------------------------
# Blob layout (D2-D13, every language): b'HCFG' | u8 version | u8 xor_key | u16 len (LE) | u32 crc32 (LE) | len bytes
# of JSON ^ xor_key; crc32 is over the PLAIN JSON. Storage seen so far: raw (.hcfg section, .NET FieldRVA, rodata, FPC
# .data) and base64 text (jar constant pool, Swift/Nim/D/Crystal string literals). hcfg_scan() also covers the next
# plausible mutations: hex (plain / with separators / \x / 0x), base64url, base32, base85, ascii85, UTF-16LE/BE text of
# raw/base64/hex/base32/base85, reversed raw / reversed base64, single-byte-xor'd base64 / raw, zlib/gzip/raw-deflate,
# multi-byte xor: multixor-body (plain header, body ^ repeating 1-16 B key) / multixor-raw (whole blob ^ 2-16 B key
# stored right before it; offset = first xor'd byte, detail key@<key offset>), base64-custom (base64 under a shuffled
# 64-char alphabet stored as a literal in the binary; offset = first char of the text, detail alphabet@<its offset>).
# rot13-/swapcase-/rot13-swapcase-base64 (letters transformed), linerev-[<x>-]base64 / reversed-<x>-base64 (each line of
# the wrapped text reversed; offset = first stored char). split-base64/-base64url/-base32/-hex: the text cut into several
# string literals in FILE order (NUL/padding/short separators between; offset = first char of the first chunk).
# int arrays: u32le-/u32be-/u64le-/u64be-array (one blob byte per 32/64-bit element; offset = first byte of the first
# element, BE: its leading 0x00), u16be-/u32be-/u64be-packed (blob packed big-endian into 16/32/64-bit words that a LE
# compiler stored byte-swapped, e.g. uint32_t a[] = {0x48434647, ...}; offset = first stored byte), decimal-list
# ('72,67,70,71,...' / '72 67 70 71' char codes, signed bytes -128..-1 allowed; offset = the '7' of '72').
# byte maps: nibswap-/rolN-/add-raw, nibswap-/rolN-/add-base64 (base64 text then mapped), base64-nibswap/-rolN/-not/
# -add (base64 of the mapped blob); add detail add=0xNN (a sub k is add 256-k); offset = first stored byte/char.
#
# OFFSET LAW (Hit.offset, decimal FILE offset -- what `hcfg_offset` asks for):
#   raw              the 'H' of the magic                          GM-confirmed (D12 FPC 82928)
#   base64           the first base64 char ('S' of 'SENGR...')     GM-confirmed (D9 30696, D11 368272, D13 560188)
#   everything else  the first byte of the STORED encoded form, i.e. the lowest file offset the stored bytes occupy:
#                    hex -> first char of the text (the '\' of '\x48' / the '0' of '0x48'); base32/base85/base64url ->
#                    first char; ascii85 -> the '<' of a '<~' prefix if present; UTF-16 -> first byte of the first code
#                    unit (BE: its 0x00 byte); reversed -> lowest byte of the reversed region (= where the blob's LAST
#                    byte sits); xor'd/RC4 -> first stored byte; zlib/gzip/deflate -> first byte of the compressed stream
#                    (0x78 CMF / 0x1f gzip magic; a zlib/gzip stream that holds the blob further in: still the
#                    stream start, detail "at+N"). These are SPECULATIVE (Hit.speculative=True): not GM-verified yet.
#   container slots  (D16 prep) a blob in a PE RT_RCDATA resource, a .NET manifest resource, a STORED zip/jar entry or
#                    an overlay is plain bytes in the file -> still "raw" at the magic; hcfg_locate(data, off) names the
#                    slot and its start (resource data start / overlay start) so a resource-relative ask can use delta.
#                    A DEFLATED jar/zip entry -> "deflate" at the entry's compressed-data start, detail "at+N zip=<name>"
#                    (= what the fixed-Huffman anchor reports); a text form inside an entry -> "zip-<enc>" at the
#                    offset INSIDE the inflated entry (like upx-<enc>), detail "zip=<name> data@<compressed start>".
#                    .NET single-file bundle: a stored entry is plain bytes (raw at the magic; hcfg_locate -> container
#                    "dotnet-bundle", slot = the embedded dll's offset); a COMPRESSED entry -> "deflate" / "bundle-<enc>"
#                    exactly like a zip entry (detail "bundle=<path>").
HCFG_MAGIC = b"HCFG"
HCFG_SCAN_EXT = os.environ.get("HCTF_HCFG_SCAN_EXT", "1") != "0"   # 0: only the D13 encodings (_LEGACY)
HCFG_DEFLATE_BRUTE_MAX = int(os.environ.get("HCTF_HCFG_DEFLATE_MAX", str(1 << 20)))   # headerless deflate brute cap
HCFG_B64ALPHA_MAX = int(os.environ.get("HCTF_HCFG_B64ALPHA_MAX", str(32 << 20)))   # alphabet-run chars examined
HCFG_MXOR_MAX = int(os.environ.get("HCTF_HCFG_MXOR_MAX", str(8 << 20)))   # whole-blob multi-byte xor cap (~65 ms/MiB)
HCFG_RC4_KEYS = int(os.environ.get("HCTF_HCFG_RC4_KEYS", "100000"))   # C-string RC4 keys tried (~6 us each)
_CONFIRMED = ("raw", "base64")
_LEGACY = ("raw", "base64", "base64url", "hex")   # what the D13 solver's native scan already decodes


@dataclass
class HcfgHit:
    offset: int              # file offset per the OFFSET LAW above
    encoding: str            # raw/base64/base64url/hex/hex-sep/base32/base85/ascii85/reversed-raw/zlib/... (+utf16le-)
    version: int
    key: int
    length: int
    crc: int                 # header crc32
    crc_ok: bool             # crc32(plain) == header crc: the TRUE blob (decoys / truncated copies fail)
    config: "dict | None"    # json.loads(plain), None if it does not parse
    plain: bytes = field(repr=False, default=b"")
    speculative: bool = True  # offset semantics not GM-confirmed (everything but raw/base64)
    detail: str = ""          # e.g. "xor=0x5a", "altchars"

    @property
    def valid(self):
        return self.crc_ok and isinstance(self.config, dict)

    def as_solver(self):
        """The binary solvers' hcfg() dict shape."""
        return {"key": self.key, "crc": zlib.crc32(self.plain), "config": self.config, "version": self.version,
                "offset": self.offset, "encoding": self.encoding, "speculative": self.speculative}


Hit = HcfgHit


def _parse_blob(blob):
    """(version, key, length, crc, plain, crc_ok, config) for bytes starting with the magic, else None."""
    if len(blob) < 12 or blob[:4] != HCFG_MAGIC:
        return None
    ver, key, n, crc = struct.unpack_from("<BBHI", blob, 4)
    plain = bytes(b ^ key for b in blob[12:12 + n])
    ok = 0 < n == len(plain) and zlib.crc32(plain) == crc   # n=0: a bare magic string ("HCFG"\0...) is no blob
    try:
        cfg = json.loads(plain.decode())
    except (ValueError, UnicodeDecodeError):
        cfg = None
    return ver, key, n, crc, plain, ok, cfg


def _need(blob_head):
    """Total blob size (12-byte header + body) from its first 8 bytes."""
    return 12 + int.from_bytes(blob_head[6:8], "little")


class _Text:
    """Character-count codec for one text encoding: chars(nbytes) -> characters encoding the first nbytes; dec(text)."""
    def __init__(self, name, alphabet, chars, dec):
        self.name, self.rx, self.chars, self.dec = name, re.compile(alphabet), chars, dec


def _b64dec(t):
    t = t.replace(b"-", b"+").replace(b"_", b"/").rstrip(b"=")
    return binascii.a2b_base64(t + b"=" * (-len(t) % 4))


def _b32dec(t):
    t = t.rstrip(b"=").upper()
    return base64.b32decode(t + b"=" * (-len(t) % 8))


_B64 = _Text("base64", rb"[A-Za-z0-9+/_\-\r\n]+={0,2}", lambda n: -(-n * 4 // 3), _b64dec)
_B32 = _Text("base32", rb"(?:[A-Z2-7]+|[a-z2-7]+)={0,6}", lambda n: -(-n * 8 // 5), _b32dec)
_G85 = lambda n: n // 4 * 5 + (n % 4 + 1 if n % 4 else 0)   # noqa: E731 - base85/ascii85 chars for n bytes
_B85 = _Text("base85", rb"[0-9A-Za-z!#$%&()*+\-;<=>?@^_`{|}~]+", _G85, base64.b85decode)
_A85 = _Text("ascii85", rb"[!-u]+", _G85, lambda t: base64.a85decode(t))
# anchors: the encoded form of the 4 magic bytes alone (base64 30 bits = 5 chars, base32 6 chars, base85 1 group)
_TEXT_ANCHORS = ((b"SENGR", _B64), (b"JBBUMR", _B32), (b"jbbumr", _B32), (base64.b85encode(HCFG_MAGIC), _B85),
                 (base64.a85encode(HCFG_MAGIC), _A85))
_HEX_ANCHOR = re.compile(rb"48[ \t:,;\-]*(?:\\[xX]|0[xX])?43[ \t:,;\-]*(?:\\[xX]|0[xX])?46[ \t:,;\-]*"
                         rb"(?:\\[xX]|0[xX])?47")
_HEX_RUN = re.compile(rb"(?:(?:\\[xX]|0[xX])?[0-9A-Fa-f]{2}[ \t\r\n:,;\-]*)+")
_HEX_PAIR = re.compile(rb"(?:\\[xX]|0[xX])?([0-9A-Fa-f]{2})")
_U16LE = re.compile(rb"(?:[\x09-\x7e]\x00)+")
_U16BE = re.compile(rb"(?:\x00[\x09-\x7e])+")
_B64REV = re.compile(rb"[A-Za-z0-9+/_\-]+={0,2}")


def _widen(s, be=False):
    return b"".join((b"\0" + bytes([c])) if be else (bytes([c]) + b"\0") for c in s)


def _decode_text(codec, run):
    """(blob, chars consumed) decoding the blob at the start of `run` (whitespace already stripped), or None."""
    try:
        head = codec.dec(run[:codec.chars(12)])
        if head[:4] != HCFG_MAGIC or len(head) < 8:
            return None
        k = codec.chars(_need(head))
        return codec.dec(run[:k]), k
    except (binascii.Error, ValueError):
        return None


def _text_at(buf, i, codec, emit, prefix=""):
    """Decode the `codec` text whose magic anchor sits at buf[i]; emit(pos, encoding, blob, detail)."""
    m = codec.rx.match(buf, i)
    run = re.sub(rb"[\r\n]", b"", m.group(0)) if m else b""
    r = _decode_text(codec, run)
    if r:
        name, pos = codec.name, i
        if codec is _B64 and re.search(rb"[-_]", run[:r[1]]):
            name = "base64url"
        if codec is _A85 and buf[max(0, i - 2):i] == b"<~":
            pos = i - 2
        emit(pos, prefix + name, r[0], "")


def _hex_at(buf, s, emit, prefix=""):
    """Decode the hex text (plain, or separated / \\x / 0x) whose '48' sits at buf[s]."""
    if buf[max(0, s - 2):s] in (b"\\x", b"\\X", b"0x", b"0X"):
        s -= 2
    pairs = _HEX_PAIR.findall(_HEX_RUN.match(buf, s).group(0))
    if len(pairs) < 12:
        return
    head = bytes.fromhex(b"".join(pairs[:12]).decode())
    blob = bytes.fromhex(b"".join(pairs[:_need(head)]).decode())
    sep = not re.fullmatch(rb"[0-9A-Fa-f]+", buf[s:s + 2 * len(blob)])
    emit(s, prefix + ("hex-sep" if sep else "hex"), blob, "")


def _text_hits(buf, emit, prefix=""):
    """Every text encoding (base64/url, base32, base85, ascii85, hex) inside a SMALL buffer (a narrowed UTF-16 run)."""
    for anchor, codec in _TEXT_ANCHORS:
        i = buf.find(anchor)
        while i >= 0:
            _text_at(buf, i, codec, emit, prefix)
            i = buf.find(anchor, i + 1)
    for m in _HEX_ANCHOR.finditer(buf):
        _hex_at(buf, m.start(), emit, prefix)


def _ends(deadline):
    ends = [d for d in (deadline,) if d]
    try:
        ends.append(float(os.environ["HCTF_SOLVE_DEADLINE"]))   # set by the timed runner (lib.decode.solve_deadline)
    except (KeyError, ValueError):
        pass
    return min(ends) if ends else None


def _fixed_deflate_anchors():
    """First 4 bytes of a fixed-Huffman deflate block that starts with literals 'HCFG' (BFINAL=1 and BFINAL=0)."""
    c = zlib.compressobj(6, zlib.DEFLATED, -15, 8, zlib.Z_FIXED)
    z = (c.compress(HCFG_MAGIC + bytes(8)) + c.flush())[:4]
    return (z, bytes([z[0] & 0xFE]) + z[1:])


_DEFLATE_FIXED = _fixed_deflate_anchors()
# dynamic-Huffman final block: low 3 bits 101 (BFINAL=1, BTYPE=10) and HLIT (bits 3-7) <= 29
_DEFLATE_DYN = re.compile(b"[" + b"".join(re.escape(bytes([5 + 8 * h])) for h in range(30)) + b"]")


def _trie(words):
    """Regex alternation of literal byte strings, factored by first byte (no word may be a prefix of another)."""
    groups = {}
    for w in words:
        groups.setdefault(w[:1], []).append(w[1:])
    parts = []
    for c, rests in sorted(groups.items()):
        parts.append(re.escape(c) + (b"(?:" + _trie(rests) + b")" if len(rests) > 1 else re.escape(rests[0])))
    return b"|".join(parts)


_UP, _LO = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ", b"abcdefghijklmnopqrstuvwxyz"
_ROT13 = bytes.maketrans(_UP + _LO, _UP[13:] + _UP[:13] + _LO[13:] + _LO[:13])
_SWAPC = bytes.maketrans(_UP + _LO, _LO + _UP)
# letter-only transforms of base64 text (involutions: the same table decodes); anchor -> (name, table, line-reversed)
_ROTB64 = {b"RGNES": ("", None, True)}   # plain base64 reversed per line: shares the rev-b64 anchor
for _n, _t in (("rot13", _ROT13), ("swapcase", _SWAPC), ("rot13-swapcase", _ROT13.translate(_SWAPC))):
    _ROTB64[b"SENGR".translate(_t)] = (_n, _t, False)
    _ROTB64[b"SENGR".translate(_t)[::-1]] = (_n, _t, True)
_B64LINES = re.compile(rb"[A-Za-z0-9+/_\-=\r\n]+")


def _rotb64_at(data, i, a, emit):
    """ROT13 / case-swapped base64 (any line wrapping) whose transformed 'SENGR' sits at data[i]; or the same text --
    plain base64 too -- with EVERY LINE reversed (anchor = the reversed 'SENGR' ending the first stored line). Offset =
    first stored char (the first line's first char); one-line reversal is 'reversed-<x>', multi-line 'linerev-<x>'
    (plain one-line = the existing 'reversed-base64', not re-emitted)."""
    name, tbl, rev = _ROTB64[a]
    if not rev:
        m = _B64.rx.match(data, i, i + 90000)
        r = _decode_text(_B64, re.sub(rb"[\r\n]", b"", m.group(0)).translate(tbl)) if m else None
        if r:
            emit(i, name + "-base64", r[0], "")
        return
    e = i + 5
    mm = _B64REV.match(data[max(0, e - 90000):e][::-1])   # back to the start of the first stored line
    s = e - len(mm.group(0)) if mm else e
    m = _B64LINES.match(data, s, s + 90000)
    lines = re.findall(rb"[^\r\n]+", m.group(0)) if m else []
    if not lines or s + len(lines[0]) != e:
        return
    text = b"".join(ln[::-1] for ln in lines)
    r = _decode_text(_B64, text.translate(tbl) if tbl else text)
    if r and (r[1] > len(lines[0].strip(b"=")) or name):
        multi = r[1] > len(lines[0].strip(b"="))
        emit(s, ("linerev-" if multi else "reversed-") + (name + "-" if name else "") + "base64", r[0], "")


_HEXT = _Text("hex", rb"[0-9A-Fa-f]+", lambda n: 2 * n, binascii.unhexlify)
# split literals: anchor -> codec; chunks = maximal alphabet runs joined across gaps of <= _SPLIT_GAP non-alphabet bytes
_SPLIT = ((b"SENGR", _B64), (b"JBBUMR", _B32), (b"jbbumr", _B32), (b"48434647", _HEXT))
_SPLIT_GAP = 32


def _split_at(data, i, codec, emit):
    """Encoded text cut into several string literals laid out in FILE ORDER (C `const char *parts[]` / char[][N]
    tables: NUL terminators + alignment padding, or any short non-alphabet separator between chunks) whose first chunk
    holds the magic anchor at data[i]. Joins up to 512 chunks until the header's length is covered; only multi-chunk
    texts are emitted ('split-<codec>', offset = first char of the first chunk, detail chunks=N)."""
    parts, need, p = [], None, i
    while len(parts) < 512:
        m = codec.rx.match(data, p, p + 90000)
        if not m:
            break
        parts.append(re.sub(rb"[\r\n]", b"", m.group(0)))
        text = b"".join(parts)
        if need is None and len(text) >= codec.chars(12):
            try:
                head = codec.dec(text[:codec.chars(12)])
            except (binascii.Error, ValueError):
                return
            if head[:4] != HCFG_MAGIC:
                return
            need = codec.chars(_need(head))
        if need is not None and len(text) >= need:
            break
        nxt = codec.rx.search(data, m.end(), m.end() + _SPLIT_GAP + 1)
        if not nxt:
            break
        p = nxt.start()
    if len(parts) < 2 or need is None or len(b"".join(parts[:-1])) >= need:
        return
    r = _decode_text(codec, b"".join(parts))
    if r:
        name = codec.name
        if codec is _B64 and re.search(rb"[-_]", b"".join(parts)[:r[1]]):
            name = "base64url"
        emit(i, "split-" + name, r[0], f"chunks={len(parts)}")


def _split_raw_at(data, i, emit, left):
    """RAW blob cut into consecutive NUL-terminated literals (GnuCOBOL WORKING-STORAGE `05 F-n PIC X(k) VALUE X"..."`
    fields at cobc -O0 = memcpy sources in .rodata; C `char p[][k]`): the NUL runs between chunks are terminators +
    alignment, but the blob itself holds NULs too (length high byte, crc, key-equal chars) -> DFS over how many NULs of
    each run (<= _SPLIT_GAP) are gap, body bytes must xor to printable JSON text, crc decides. 'split-raw', offset =
    first byte of the first chunk (the magic), detail chunks=N. Bounded: blobs <= 16 KiB, `left` = [DFS nodes] shared
    by every anchor of one scan."""
    win = data[i:i + 0x4000 + 64 * _SPLIT_GAP]

    def walk(p, out, gaps):
        left[0] -= 1
        if left[0] < 0:
            return None
        while True:
            if len(out) >= 12:
                n = _need(out)
                if n > 0x4000:
                    return None
                if len(out) >= n:
                    r = _parse_blob(bytes(out[:n]))
                    return (bytes(out[:n]), gaps) if r and r[5] and gaps else None
            if p >= len(win):
                return None
            c = win[p]
            if c:
                if len(out) >= 12 and not (0x20 <= c ^ out[5] <= 0x7e or c ^ out[5] in (9, 10, 13)):
                    return None
                out.append(c)
                p += 1
                continue
            q = p
            while q < len(win) and not win[q]:
                q += 1
            r_ = q - p
            for s in range(min(r_, _SPLIT_GAP) + 1):   # s NULs of this run are gap, the rest is blob content
                nxt = out + b"\0" * (r_ - s)
                if len(nxt) > 12 and not 0x20 <= nxt[5] <= 0x7e and max(len(out), 12) < len(nxt):
                    continue   # a NUL in the body xors to the key: only printable keys allow body NULs
                got = walk(q, nxt, gaps + (s > 0))
                if got or left[0] < 0:
                    return got
            return None

    got = walk(4, bytearray(win[:4]), 0)
    if got:
        emit(i, "split-raw", got[0], f"chunks={got[1] + 1}")


def _wide_at(data, i, w, emit, budget):
    """One blob byte per w-byte array element ('H' + (w-1) NULs + 'C'... at i): LE starts at i, BE at i-(w-1). A run
    of such elements reads both ways with the same bytes -- keep the w-aligned start (compilers align int arrays),
    LE when both/neither are."""
    cands = [(False, i), (True, i - w + 1)]
    cands.sort(key=lambda c: (c[1] % w != 0, c[0]))
    for be, st in cands:
        off = w - 1 if be else 0
        if st < 0 or budget[0] <= 0:
            continue
        budget[0] -= 1
        n = _need(data[st + off:st + off + 8 * w:w])
        span = data[st:st + n * w]
        lo = span[off::w]
        if len(lo) == n and span.count(0) == len(span) - n + lo.count(0):   # every non-value byte is 0x00
            emit(st, f"u{8 * w}{'be' if be else 'le'}-array", lo)
            return


_SWAP_TC = {2: "H", 4: "I", 8: "Q"}


def _swapped_at(data, st, w, emit, budget):
    """Blob packed big-endian into w-byte words stored little-endian (each word's bytes reversed) starting at st.
    budget: [candidates left] -- 'GFCH'/'CHGF' floods (decoy tables) stay bounded."""
    tc = _SWAP_TC[w]
    if st < 0 or budget[0] <= 0 or array.array(tc).itemsize != w:
        return
    def unswap(buf):
        a = array.array(tc, buf[:len(buf) // w * w])
        a.byteswap()
        return a.tobytes()
    head = unswap(data[st:st + 16])
    if head[:4] != HCFG_MAGIC:
        return
    n = _need(head)
    budget[0] -= 1
    emit(st, f"u{8 * w}be-packed", unswap(data[st:st + -(-n // w) * w])[:n])


_DEC_SEP = rb"(?:[ \t\r\n]*[,;][ \t\r\n]*|[ \t\r\n]+)"
_DEC_ANCHOR = re.compile(rb"72" + _DEC_SEP + rb"67" + _DEC_SEP + rb"70" + _DEC_SEP + rb"71(?![0-9])")
_DEC_RUN = re.compile(rb"-?[0-9]{1,3}(?:" + _DEC_SEP + rb"-?[0-9]{1,3})*")
_DEC_NUM = re.compile(rb"-?[0-9]+")


def _decimal_at(data, s, emit):
    """Decode the decimal char-code list whose '72' sits at data[s] (not preceded by a digit / '-')."""
    if s and data[s - 1] in b"0123456789-":
        return
    nums = _DEC_NUM.findall(_DEC_RUN.match(data, s, s + 256).group(0))
    if len(nums) < 12:
        return
    n = _need(bytes(int(x) & 0xFF for x in nums[:8]))
    nums = _DEC_NUM.findall(_DEC_RUN.match(data, s, s + 16 * n + 64).group(0))[:n]
    vals = [int(x) for x in nums]
    if len(vals) == n and all(-128 <= v <= 255 for v in vals):
        emit(s, "decimal-list", bytes(v & 0xFF for v in vals))


def _anchor_table():
    lit = {HCFG_MAGIC: ("raw", None), b"GFCH": ("rev-raw", None), b"RGNES": ("rev-b64", None)}
    for a, codec in _TEXT_ANCHORS:
        lit[a] = ("text", codec)
        lit[_widen(a)[:-1]] = ("u16text", None)   # 'S\0E\0N\0G\0R': LE at i, BE at i-1
    lit[_widen(b"48")[:-1]] = ("u16text", None)
    lit[_widen(HCFG_MAGIC)[:-1]] = ("u16raw", None)
    for w in (4, 8):
        lit[(b"\0" * (w - 1)).join(bytes([c]) for c in HCFG_MAGIC)] = ("wide", None)   # 'H\0\0\0C\0\0\0F\0\0\0G'
    lit[b"CHGF"] = ("swap16", None)
    z = {b"\x78\x01": (15, "zlib"), b"\x78\x5e": (15, "zlib"), b"\x78\x9c": (15, "zlib"), b"\x78\xda": (15, "zlib"),
         b"\x1f\x8b\x08": (31, "gzip"), _DEFLATE_FIXED[0]: (-15, "deflate"), _DEFLATE_FIXED[1]: (-15, "deflate")}
    for a in z:
        lit[a] = ("z", None)
    # first-byte trie (H(?:CFG|\0C\0F\0G)|S(?:...)...): one branch per position, ~20% faster than a flat alternation;
    # NO named groups (8x slower: 135 vs 16 ms on 1.8 MB) -- the matched bytes identify the anchor
    rx = re.compile(_HEX_ANCHOR.pattern + b"|" + _trie(list(lit)))
    return rx, {a: k for a, (k, _) in lit.items()}, {a: c for a, (_, c) in lit.items() if c}, z


_ANCHORS, _ANCHOR_KIND, _ANCHOR_CODEC, _ANCHOR_Z = _anchor_table()


def _inflate(mv, p, wbits, budget=None):
    """(decompressed bytes from the 'HCFG' on, its position in the stream's output) for the stream at p, or None.
    Raw deflate must START with the magic; a zlib/gzip stream may also CONTAIN it (a compressed section/resource): those
    are inflated up to 1 MiB each, charged to budget[0] (bytes left for the whole scan)."""
    try:
        d = zlib.decompressobj(wbits)
        head = d.decompress(mv[p:p + 512], 4)
        if len(head) < 4 and not d.eof:
            head += d.decompress(mv[p + 512:p + (64 << 10)], 4 - len(head))
    except zlib.error:
        return None
    if head == HCFG_MAGIC:
        at = 0
    elif wbits < 0 or len(head) < 4 or not budget or budget[0] <= 0:
        return None
    else:
        at = -1
    try:
        d = zlib.decompressobj(wbits)
        out = d.decompress(mv[p:p + (2 << 20)], 70000 if at == 0 else (1 << 20))
    except zlib.error:
        return None
    if at < 0:
        budget[0] -= len(out)
        at = out.find(HCFG_MAGIC)
        if at < 0:
            return None
        out = out[at:at + 70000]
    return out, at


# compressed stream (zlib/gzip/xz/bz2/lzma-alone) stored as base64 / plain hex text, or xz/bz2/lzma raw in the file
# (zlib/gzip/deflate raw are anchors above). One bytes.find per needle (~0.5 ms/MiB each; a regex alternation was 20 ms/
# MiB): base64 of the stream header 78 9c -> eJ[w-z], 78 da -> eN[o-r], 1f 8b 08 -> H4sI, xz -> /Td6WFoA, 'BZh' ->
# Qlpo, 5d 00 00 -> XQAA; lowercase+uppercase hex of zlib/gzip; raw xz magic, bz2 block magic (4 bytes past 'BZh9'),
# lzma-alone props 5d 00 00 (header-checked before inflating); zstd (28 b5 2f fd -> KLUv/) and LZ4 frame (04 22 4d 18 ->
# BCJNG) raw / base64 / hex (speculative: offset = first stored byte). (needle, bytes before the stream start, form)
_ZPACK = ((b"eJ", 0, "b64"), (b"eN", 0, "b64"), (b"H4sI", 0, "b64"), (b"/Td6WFoA", 0, "b64"), (b"Qlpo", 0, "b64"),
          (b"XQAA", 0, "b64"), (b"789c", 0, "hex"), (b"78da", 0, "hex"), (b"1f8b08", 0, "hex"), (b"789C", 0, "hex"),
          (b"1F8B08", 0, "hex"), (b"\xfd7zXZ\x00", 0, "raw"), (b"1AY&SY", 4, "raw"), (b"]\x00\x00", 0, "raw"),
          (b"\x28\xb5\x2f\xfd", 0, "raw"), (b"KLUv/", 0, "b64"), (b"28b52ffd", 0, "hex"),
          (b"\x04\x22\x4d\x18", 0, "raw"), (b"BCJNG", 0, "b64"), (b"04224d18", 0, "hex"))
_ZPACK_B64 = re.compile(rb"[A-Za-z0-9+/_\-\r\n]+")
_ZPACK_HEX = re.compile(rb"[0-9A-Fa-f]+")


def _zpack_kind(head):
    """Container name for decoded stream bytes, or None."""
    if head[:2] in (b"\x78\x9c", b"\x78\xda", b"\x78\x01", b"\x78\x5e"):
        return "zlib"
    if head[:3] == b"\x1f\x8b\x08":
        return "gzip"
    if head[:6] == b"\xfd7zXZ\x00":
        return "xz"
    if re.match(rb"BZh[1-9]1AY&SY", head):
        return "bz2"
    if head[:3] == b"\x5d\x00\x00" and len(head) >= 13:   # lzma-alone: props, dict size, u64 size (-1 or sane)
        dic, size = int.from_bytes(head[1:5], "little"), int.from_bytes(head[5:13], "little")
        if dic >= 1 << 16 and (dic & (dic - 1) == 0 or dic & (dic - 1) & (dic - 2) == 0) and (
                size == (1 << 64) - 1 or 12 <= size < 64 << 20):
            return "lzma"
    if head[:4] == b"\x28\xb5\x2f\xfd" and len(head) > 4 and not head[4] & 0x08:   # frame header reserved bit 0
        return "zstd"
    if head[:4] == b"\x04\x22\x4d\x18" and len(head) > 5 and head[4] >> 6 == 1 and not head[4] & 0x02:   # FLG v01
        return "lz4"
    return None


def _zpack_open(kind, buf, budget):
    """(output from the 'HCFG' on, its position) for the `kind` stream at buf[0], or None; output charged to budget."""
    import bz2
    import lzma
    if kind in ("zstd", "lz4"):
        try:
            if kind == "zstd":
                import zstandard
                out = zstandard.ZstdDecompressor().stream_reader(io.BytesIO(bytes(buf)), read_across_frames=False).read(
                    1 << 20)
            else:
                import lz4.frame
                out = lz4.frame.LZ4FrameDecompressor().decompress(bytes(buf), max_length=1 << 20)
        except Exception:   # noqa: BLE001 - ImportError / ZstdError / LZ4 RuntimeError on a truncated or fake frame
            return None
        budget[0] -= len(out)
        at = out.find(HCFG_MAGIC)
        return (out[at:at + 70000], at) if at >= 0 else None
    if kind in ("zlib", "gzip"):
        d = zlib.decompressobj(15 if kind == "zlib" else 31)
    elif kind == "bz2":
        d = bz2.BZ2Decompressor()
    else:
        d = lzma.LZMADecompressor(lzma.FORMAT_XZ if kind == "xz" else lzma.FORMAT_ALONE)
    try:
        out = d.decompress(bytes(buf), 1 << 20)
    except (zlib.error, OSError, EOFError, ValueError, lzma.LZMAError):
        return None
    budget[0] -= len(out)
    at = out.find(HCFG_MAGIC)
    return (out[at:at + 70000], at) if at >= 0 else None


def _zpack_at(data, i, form, emit, budget):
    """Decode the compressed stream stored at data[i] as `form` (b64 / hex text, or raw) and emit its blob."""
    if form == "raw":
        stream, pre = data[i:i + 16], ""
    else:
        m = (_ZPACK_HEX if form == "hex" else _ZPACK_B64).match(data, i, i + 32)
        if not m or len(m.group(0)) < 32:   # a 12-byte blob compresses to >= 20 bytes (>= 27 b64 chars)
            return
        head = m.group(0).replace(b"\r", b"").replace(b"\n", b"")
        try:
            stream = bytes.fromhex(head[:24].decode()) if form == "hex" else _b64dec(head[:24])
        except (binascii.Error, ValueError):
            return
        pre = "hex-" if form == "hex" else "base64-"
    kind = _zpack_kind(stream)
    if not kind or budget[0] <= 0:
        return
    if form == "raw":
        stream = data[i:i + (2 << 20)]
    else:
        run = (_ZPACK_HEX if form == "hex" else _ZPACK_B64).match(data, i, i + (3 << 20)).group(0)
        try:
            if form == "hex":
                stream = bytes.fromhex(run[:len(run) & ~1].decode())
            else:
                run = run.replace(b"\r", b"").replace(b"\n", b"")
                stream = _b64dec(run[:len(run) & ~3] if len(run) % 4 == 1 else run)
        except (binascii.Error, ValueError):
            return
    r = _zpack_open(kind, stream, budget)
    if r:
        emit(i, pre + kind, r[0], f"at+{r[1]}" if r[1] else "")


_PRINTABLE = frozenset(range(0x20, 0x7f)) | {9, 10, 13}
_PMASK = [sum(1 << k for k in range(256) if b ^ k in _PRINTABLE) for b in range(256)]   # keys keeping b printable
_JSONW = {**{c: 2 for c in b"bcfgkmpquvwxyz0123456789:,._-/ "}, **{c: 4 for c in b'etaoinsrhld"'},
          **{c: 1 for c in b"ABCDEFGHIJKLMNOPQRSTUVWXYZ{}[]\\\n"}}   # JSON config byte weights (key ranking)


def _xor_rep(buf, key):
    """buf ^ key repeated from buf[0]."""
    k = (key * (len(buf) // len(key) + 1))[:len(buf)]
    return (int.from_bytes(buf, "little") ^ int.from_bytes(k, "little")).to_bytes(len(buf), "little")


def _rc4(key, buf):
    """RC4(key) applied to buf (pycryptodome when present, else pure Python)."""
    try:
        from Crypto.Cipher import ARC4
        return ARC4.new(key).encrypt(bytes(buf))
    except Exception:  # noqa: BLE001 - missing module / unsupported key length: pure-Python fallback
        S, j, kl = list(range(256)), 0, len(key)
        for i in range(256):
            j = (j + S[i] + key[i % kl]) & 255
            S[i], S[j] = S[j], S[i]
        out, i, j = bytearray(buf), 0, 0
        for n in range(len(out)):
            i = (i + 1) & 255
            j = (j + S[i]) & 255
            S[i], S[j] = S[j], S[i]
            out[n] ^= S[(S[i] + S[j]) & 255]
        return bytes(out)


_RC4_KEY = re.compile(rb"\0([\x21-\x7e][\x20-\x7e]{3,63})(?=\0)")   # NUL-delimited 4-64 char C string (~0.1 s / 48 MiB)

# --- environment-keyed config ('Force the truth out'): the blob (or only its body / header xor byte) is xor'd with a
# key DERIVED from a literal the program compares the env value / host model / hostname against. Keyspace = the file's
# OWN literals (NUL-delimited C strings, UTF-16 #US / wchar strings) x the KDFs below, each tried within +-16 KB of the
# literal; accepted only crc-valid + JSON. Offset = first stored (encrypted) byte, like rc4.
HCFG_ENVKEY_KEYS = 768       # distinct literals tried (~0.2 ms each; env-name neighbours first)
HCFG_ENVKEY_WIN = 1 << 14     # +-16 KB: .rodata literal -> .data / FieldRVA blob of a small program
_ENVKEY_C = re.compile(rb"\0([A-Za-z0-9][\x20-\x7e]{2,47})(?=\0)")
_ENVKEY_W = re.compile(rb"(?:[A-Za-z0-9]\x00)(?:[\x20-\x7e]\x00){2,47}")
_ENVKEY_NAME = re.compile(rb"[A-Z][A-Z0-9]*_[A-Z0-9_]+|COMPUTERNAME|HOSTNAME|USERDOMAIN|USERNAME")


def _fnv1a32(b):
    h = 0x811C9DC5
    for c in b:
        h = ((h ^ c) * 0x01000193) & 0xFFFFFFFF
    return h


def _envkey_kdfs(lit):
    """[(name, repeating key bytes)] derived from one literal."""
    import hashlib
    s2, c, f = hashlib.sha256(lit).digest(), zlib.crc32(lit), _fnv1a32(lit)
    return [("xor", lit), ("sha256", s2), ("sha256[:16]", s2[:16]), ("sha256[:8]", s2[:8]), ("sha256[:4]", s2[:4]),
            ("md5", hashlib.md5(lit).digest()), ("sha1", hashlib.sha1(lit).digest()),
            ("crc32le", c.to_bytes(4, "little")), ("crc32be", c.to_bytes(4, "big")),
            ("fnv1a32le", f.to_bytes(4, "little")), ("fnv1a32be", f.to_bytes(4, "big"))]


def _envkey_scan(data, hits, emit, late):
    """Environment-keyed HCFG: whole blob ^ kdf(literal) ('envkey-xor'), plain header over a body ^ kdf(literal)
    ('envkey-body'), or a plain blob whose header xor byte is stored ^ a literal-derived byte ('envkey-hdrkey')."""
    lits, seen, envs = [], set(), []
    for rx, wide in ((_ENVKEY_C, False), (_ENVKEY_W, True))[:2 if data[:2] == b"MZ" else 1]:   # wide: PE / .NET #US
        for n, m in enumerate(rx.finditer(data)):
            if n >= 1 << 15 or late():
                break
            s, at = (m.group(0)[::2], m.start()) if wide else (m.group(1), m.start(1))
            if _ENVKEY_NAME.fullmatch(s):
                envs.append(at)
            if s not in seen:
                seen.add(s)
                lits.append((s, at))
    # literals within 4 KB of an env-var-like name (HUNTRESS_HOST_MODEL, COMPUTERNAME) first, then file order
    envs.sort()

    def near(at):
        j = bisect.bisect_left(envs, at)
        return any(abs(envs[x] - at) <= 4096 for x in (j - 1, j) if 0 <= x < len(envs))
    lits = sorted(lits, key=lambda la: not near(la[1]))[:HCFG_ENVKEY_KEYS]
    bodies = [h for h in hits if h.encoding == "raw" and not h.crc_ok][:64]
    for lit, at in lits:
        if late():
            return
        lo, hi, sh = max(0, at - HCFG_ENVKEY_WIN), at + len(lit) + HCFG_ENVKEY_WIN, repr(lit.decode("latin-1"))
        kdfs = _envkey_kdfs(lit)
        for name, key in kdfs:
            ks = (key * (12 // len(key) + 1))[:12]
            t = data.find(bytes(a ^ b for a, b in zip(HCFG_MAGIC, ks)), lo, hi)
            while t >= 0:
                head = _xor_rep(data[t:t + 12], key)
                blob = _xor_rep(data[t:t + _need(head)], key)
                r = _parse_blob(blob)
                if r and r[5] and isinstance(r[6], dict):
                    emit(t, "envkey-xor", blob, f"kdf={name} key={sh} key@{at}")
                    return
                t = data.find(bytes(a ^ b for a, b in zip(HCFG_MAGIC, ks)), t + 1, hi)
        for h in bodies:
            if not lo <= h.offset < hi:
                continue
            head, body = data[h.offset:h.offset + 12], data[h.offset + 12:h.offset + 12 + h.length]
            if len(body) != h.length:
                continue
            # (encoding, kdf, plain, header key byte to report): body ^ stream (header byte applied after / not at all)
            cands = []
            for name, key in kdfs:
                dec = _xor_rep(body, key)
                cands += [("envkey-body", name, dec, h.key), ("envkey-body", name, bytes(b ^ h.key for b in dec), h.key)]
            for name, d in (("first", lit[0]), ("len", len(lit) & 255), ("sha256[0]", kdfs[1][1][0]),
                            ("crc32", kdfs[7][1][0]), ("fnv1a32", kdfs[9][1][0])):
                if d:
                    cands.append(("envkey-hdrkey", name, bytes(b ^ h.key ^ d for b in body), h.key ^ d))
            for enc, name, plain, k in cands:
                if zlib.crc32(plain) != h.crc:
                    continue
                try:
                    ok = isinstance(json.loads(plain.decode()), dict)
                except (ValueError, UnicodeDecodeError):
                    ok = False
                if ok:
                    blob = head[:5] + bytes([k]) + head[6:12] + bytes(b ^ k for b in plain)
                    emit(h.offset, enc, blob, f"kdf={name} key={sh} key@{at}")
                    return


def _mxor_body(data, i):
    """(blob, key) for a plain HCFG header at data[i] whose body is JSON ^ a repeating 1-16 byte key (any header xor
    byte folded in), body at +12 or after the key stored at +12; crc-confirmed. Key per column: the bytes that keep the
    whole column printable, best JSON-looking first (top pick, then one-column swaps). None if nothing checks out."""
    head = data[i:i + 12]
    if len(head) < 12 or not head[6:8].strip(b"\0"):
        return None
    n, crc, k1 = int.from_bytes(head[6:8], "little"), int.from_bytes(head[8:12], "little"), head[5]

    def ok(body, key):
        if len(key) != kl:
            return None
        x = _xor_rep(body, key)   # body = JSON ^ key, or JSON ^ header xor byte ^ key (stored key, k1 not folded in)
        for plain in (x, x.translate(bytes(c ^ k1 for c in range(256)))):
            if len(plain) == n and zlib.crc32(plain) == crc:
                return head + bytes(p ^ k1 for p in plain), key
        return None

    for kl in range(1, 17):
        for kat, bat in ((i + 12, i + 12 + kl), (i - kl, i + 12), (i + 12 + n, i + 12)):   # key stored next to it:
            r = ok(data[bat:bat + n], data[max(0, kat):kat + kl])   # between header and body / before magic / after
            if r:
                return r
        body, cols = data[i + 12:i + 12 + n], []
        if len(body) < max(n, 2 * kl):
            continue
        for j in range(kl):
            col, m = body[j::kl], -1
            for b in set(col):
                m &= _PMASK[b]
            # known plaintext of a JSON object: '{' first, '}' last, '"' second (compact) -- pinned / preferred
            pin = [x for x, at in ((body[0] ^ 0x7B, 0), (body[-1] ^ 0x7D, (n - 1) % kl)) if at == j]
            if pin:
                m &= 1 << pin[0] if all(x == pin[0] for x in pin) else 0
            if not m:
                break
            cand = sorted((k for k in range(256) if m >> k & 1),
                          key=lambda k, col=col: -sum(_JSONW.get(b ^ k, 0) for b in col))[:4]
            q = body[1] ^ 0x22
            if j == 1 % kl and q in cand[1:]:
                cand.remove(q)
                cand.insert(0, q)
            cols.append(cand)
        else:
            best = bytes(c[0] for c in cols)
            alts = [(j, alt) for j, c in enumerate(cols) for alt in c[1:]]
            tries = [best] + [best[:j] + bytes([alt]) + best[j + 1:] for j, alt in alts]
            tries += [bytes(alt if j == a else alt2 if j == a2 else c for j, c in enumerate(best))
                      for x, (a, alt) in enumerate(alts) for a2, alt2 in alts[x + 1:] if a2 != a][:400]
            for key in tries:
                r = ok(body, key)
                if r:
                    return r
    return None


_B64STD = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
_B64ALPHA_CLS = bytes(int(c in b"+/-_.!~*$@#%&?:;," or chr(c).isalnum() and c < 0x80) for c in range(256))


def _b64_alphabets(data, budget, late):
    """64-char windows of 64 DISTINCT characters (custom base64 alphabets) in `data`: [(offset, alphabet)], at most 4 per
    run and 32 overall, skipping standard / url-safe ones (and their rotations); examines at most `budget` run characters. Runs of
    alphabet-class bytes via translate + find (a {64,} regex was 1.2 s / 67 MB); every 64-window contains a whole
    aligned 32-block, so only blocks of 32 distinct chars get the per-char sliding check."""
    out, seen = [], {_B64STD, _B64STD[:62] + b"-_"}
    t, ones = data.translate(_B64ALPHA_CLS), b"\x01" * 64
    p = t.find(ones)
    while p >= 0 and len(out) < 32:
        e = t.find(b"\0", p)
        e = len(data) if e < 0 else e
        run, wins = data[p:e], []
        budget -= len(run)
        if budget < 0 or late():
            break
        for k in range(0, len(run) - 31, 32):
            if len(set(run[k:k + 32])) < 32:
                continue
            base, last, lo = max(0, k - 32), {}, 0   # sliding window without repeats over [k-32, k+64)
            for j, c in enumerate(run[base:k + 64]):
                lo = max(lo, last.get(c, -1) + 1)
                last[c] = j
                if j - lo >= 63 and base + j - 63 not in wins:
                    wins.append(base + j - 63)
            if len(wins) >= 4:
                break
        for w in wins[:4]:
            a = run[w:w + 64]
            if a not in seen and a not in _B64STD * 2 and a not in (_B64STD[:62] + b"-_") * 2:   # std rotations
                seen.add(a)
                out.append((p + w, a))
        p = t.find(ones, e)
    return out[:32]


# byte-map transforms of the stored form: stored = t(x) for x = the raw blob ('<t>-raw'), its base64 text
# ('<t>-base64', transform AFTER base64) or base64 of t(blob) ('base64-<t>', transform BEFORE base64). t = nibswap,
# rol1-3/5-7 (rotate each byte left; rorN = rol(8-N), nibswap = rol4), not (raw/after-base64 NOT is xor 0xff: the
# single-byte xor pass reports those), add (stored = x + k mod 256, a 'sub k' = add 256-k; detail add=0xNN).
# Offset = first stored byte / char.
def _rolb(b, r):
    return ((b << r) | (b >> (8 - r))) & 0xFF


_BYTEID = bytes(range(256))
_BYTEMAPS = {"nibswap": bytes(_rolb(b, 4) for b in range(256)), "not": bytes(b ^ 0xFF for b in range(256))}
_BYTEMAPS.update((f"rol{r}", bytes(_rolb(b, r) for b in range(256))) for r in (1, 2, 3, 5, 6, 7))
_BYTEMAP_ANCHORS = {}   # stored anchor -> (name, inverse table, form)
for _n, _t in _BYTEMAPS.items():
    _inv = bytes.maketrans(_t, _BYTEID)
    if _n != "not":
        _BYTEMAP_ANCHORS[HCFG_MAGIC.translate(_t)] = (_n, _inv, "raw")
        _BYTEMAP_ANCHORS[b"SENGR".translate(_t)] = (_n, _inv, "after")
    _BYTEMAP_ANCHORS[base64.b64encode(HCFG_MAGIC.translate(_t))[:5]] = (_n, _inv, "before")
_BYTEMAP_RX = re.compile(_trie(list(_BYTEMAP_ANCHORS)))
HCFG_ADDK_MAX = int(os.environ.get("HCTF_HCFG_ADDK_MAX", str(96 << 20)))   # add-constant passes (~1 s / 67 MB)
_B64RUN = re.compile(rb"[A-Za-z0-9+/]{32,}")   # a header (16 chars) + any JSON body


def _subdiff(buf):
    """D with D[i] = (buf[i] - buf[i+1]) % 256 (key-free under a per-byte add): SWAR big-int lane subtraction."""
    n = len(buf)
    x, h = int.from_bytes(buf, "little"), int.from_bytes(b"\x80" * n, "little")
    y = x >> 8
    return ((((x | h) - (y & ~h)) ^ ((x ^ ~y) & h)) & ((1 << 8 * n) - 1)).to_bytes(n, "little")


def _diffpat(plain):
    return bytes((a - b) % 256 for a, b in zip(plain, plain[1:]))


def _bytemap_at(data, i, form, inv, name, emit, detail=""):
    """Undo the byte map `inv` on the stored form at data[i] (form raw / after / before base64) and emit the blob."""
    if form == "raw":
        emit(i, name + "-raw", data[i:i + _need(data[i:i + 8].translate(inv))].translate(inv), detail)
    elif form == "after":
        m = _B64.rx.match(data[i:i + 90000].translate(inv))
        r = _decode_text(_B64, re.sub(rb"[\r\n]", b"", m.group(0))) if m else None
        if r:
            emit(i, name + "-base64", r[0], detail)
    else:
        m = _B64.rx.match(data, i, i + 90000)
        run = re.sub(rb"[\r\n]", b"", m.group(0)) if m else b""
        try:
            head = _b64dec(run[:16]).translate(inv)
            blob = _b64dec(run[:_B64.chars(_need(head))]).translate(inv)
        except (binascii.Error, ValueError):
            return
        emit(i, "base64-" + name, blob, detail)


def _addk_scan(data, emit, late):
    """add/sub-constant stored forms: raw + after-base64 via the key-free byte difference of the file, before-base64 via
    the difference of every base64 run decoded at each of its 4 phases (runs joined per phase: one decode)."""
    diff = _subdiff(data)
    for plain, form in ((HCFG_MAGIC, "raw"), (b"SENGR", "after")):
        pat, i, n = _diffpat(plain), 0, 0
        i = diff.find(pat)
        while i >= 0 and n < 4096 and not late():
            k = (data[i] - plain[0]) % 256
            if k:
                _bytemap_at(data, i, form, bytes((b - k) % 256 for b in range(256)), "add", emit, f"add={k:#04x}")
            i, n = diff.find(pat, i + 1), n + 1
    runs = [m.span() for m in _B64RUN.finditer(data)]
    pat = _diffpat(HCFG_MAGIC)
    for ph in range(4):
        if late():
            return
        starts, segs, at = [], [], 0
        for a, b in runs:
            seg = (b - a - ph) // 4 * 4
            if seg >= 16:
                starts.append((at, a + ph))
                segs.append(data[a + ph:a + ph + seg])
                at += seg // 4 * 3
        dec = binascii.a2b_base64(b"".join(segs))
        diff = _subdiff(dec)
        j, n = diff.find(pat), 0
        while j >= 0 and n < 4096 and not late():
            if j % 3 == 0 and dec[j] != HCFG_MAGIC[0]:
                at, a = starts[bisect.bisect_right(starts, (j, float("inf"))) - 1]
                k = (dec[j] - HCFG_MAGIC[0]) % 256
                _bytemap_at(data, a + (j - at) // 3 * 4, "before", bytes((b - k) % 256 for b in range(256)), "add",
                            emit, f"add={k:#04x}")
            j, n = diff.find(pat, j + 1), n + 1


# Index-dependent xor of the whole stored blob (key from the known plaintext 'HCFG'; offset = first stored byte;
# crc-valid hits only): rollxor-raw stored[j] = blob[j] ^ (k0 + step*j) (key+i, key-i, any step != 0; detail
# key=0xNN step=0xNN), xoridx-raw stored[j] = blob[j] ^ k0 ^ j, xorcbc-raw stored[j] = blob[j] ^ stored[j-1] (ciphertext
# feedback, stored[-1] = k0), xorchain-raw stored[j] = blob[j] ^ blob[j-1] (plaintext feedback, blob[-1] = k0).
HCFG_ROLLXOR_MAX = int(os.environ.get("HCTF_HCFG_ROLLXOR_MAX", str(96 << 20)))   # rolling-xor pass (~0.6 s / 64 MB)
_XORIDX_PAT = bytes(HCFG_MAGIC[j] ^ HCFG_MAGIC[j + 1] ^ j ^ (j + 1) for j in range(3))
_XTBL = [bytes(c ^ k for c in range(256)) for k in range(256)]


def _crc_fast(blob):
    """_parse_blob's crc_ok via translate (no per-byte Python loop): random-candidate filter."""
    if len(blob) < 12 or blob[:4] != HCFG_MAGIC:
        return False
    _, key, n, crc = struct.unpack_from("<BBHI", blob, 4)
    return 0 < n == len(blob) - 12 and zlib.crc32(blob[12:].translate(_XTBL[key])) == crc


def _rollxor_scan(data, emit, late):
    def ks_try(s, ks, enc, detail):   # ks: the 256-periodic keystream from s
        need = _need(_xor_rep(data[s:s + 8], ks[:8]))
        blob = _xor_rep(data[s:s + need], ks) if s + need <= len(data) else b""
        if _crc_fast(blob):
            emit(s, enc, blob, detail)

    def fb_try(s, enc, cbc):   # feedback modes: blob[0] = 'H' fixes k0
        k0, head = data[s] ^ HCFG_MAGIC[0], data[s:s + 12]
        if len(head) < 12:
            return
        if cbc:
            dec = lambda c: bytes([c[0] ^ k0]) + _xorb(c[1:], c[:-1])
        else:   # prefix xor of k0 + stored: lane-wise doubling (xor carries nothing across bytes)
            def dec(c):
                x, sh = int.from_bytes(c, "little") ^ k0, 8
                while sh < 8 * len(c):
                    x, sh = x ^ (x << sh), sh * 2
                return (x & ((1 << 8 * len(c)) - 1)).to_bytes(len(c), "little")
        need = _need(dec(head))
        blob = dec(data[s:s + need]) if s + need <= len(data) else b""
        if _crc_fast(blob):
            emit(s, enc, blob, f"iv={k0:#04x}")

    pat = bytes(a ^ b for a, b in zip(HCFG_MAGIC, HCFG_MAGIC[1:]))   # plaintext feedback: stored[s+1..s+3]
    t, n = data.find(pat, 1), 0
    while t >= 1 and n < 4096 and not late():
        fb_try(t - 1, "xorchain-raw", False)
        t, n = data.find(pat, t + 1), n + 1
    # 1 MiB chunks (+3 bytes overlap), one big int each: diff[i] = stored[i] ^ stored[i+1] for xorcbc ('CFG') / xoridx;
    # rolling add key: k_j = stored[s+j] ^ 'HCFG'[j] has equal first differences (SWAR lane subtraction)
    size, cache, cand = 1 << 20, {}, [0, 0, 0]
    for lo in range(0, max(0, len(data) - 3), size):
        if late():
            return
        n = min(size, len(data) - 3 - lo)
        if n not in cache:
            m, h = (1 << 8 * n) - 1, int.from_bytes(b"\x80" * n, "little")
            cache[n] = m, h, m ^ h, [int.from_bytes(bytes([c]) * n, "little") for c in HCFG_MAGIC]
        m, h, nh, C = cache[n]
        x = int.from_bytes(data[lo:lo + n + 3], "little")
        diff = ((x ^ (x >> 8)) & (m << 16 | 0xFFFF)).to_bytes(n + 2, "little")   # patterns STARTING in the chunk
        for k, pat in enumerate((b"CFG", _XORIDX_PAT)):
            t = diff.find(pat, 0, n + 2)
            while 0 <= t < n and cand[k] < 4096:
                s, cand[k] = lo + t, cand[k] + 1
                if k == 0:
                    fb_try(s, "xorcbc-raw", True)
                else:
                    k0 = data[s] ^ HCFG_MAGIC[0]
                    ks_try(s, bytes(k0 ^ j for j in range(256)), "xoridx-raw", f"key={k0:#04x}")
                t = diff.find(pat, t + 1)
        X = [((x >> 8 * j) & m) ^ C[j] for j in range(4)]

        def sub(a, b):
            return ((a | h) - (b & nh)) ^ ((a ^ b ^ m) & h)
        d2 = sub(X[2], X[1])
        e = ((sub(X[1], X[0]) ^ d2) | (d2 ^ sub(X[3], X[2]))).to_bytes(n, "little")
        i = e.find(b"\0")
        while i >= 0 and cand[2] < 4096:
            s = lo + i
            k0, st = data[s] ^ HCFG_MAGIC[0], ((data[s + 1] ^ HCFG_MAGIC[1]) - (data[s] ^ HCFG_MAGIC[0])) & 255
            if st:   # step 0 = the single-byte xor pass
                cand[2] += 1
                ks_try(s, bytes((k0 + st * j) & 255 for j in range(256)), "rollxor-raw", f"key={k0:#04x} step={st:#04x}")
            i = e.find(b"\0", i + 1)


# Block / stream ciphers (D16 prep): AES-128/192/256 ECB/CBC/CTR, ChaCha20/Salsa20, XTEA ECB/CBC -- run only when the
# cipher's constants are in the file (AES S-box / inv S-box / Te0, TEA delta 0x9e3779b9 / -delta, 'expand 32-byte k').
# Keys: NUL-delimited strings (the string itself when 16/24/32 chars, its hex when 32/64 hex digits, sha256 / sha256[:16]
# / md5 of it; far from every constant hit: literal keys before derived ones), plus raw 16/32-byte keys (8-aligned)
# within 4 KB of a constant hit with the ciphertext right after them (or after a 16-byte IV after them). AES/ChaCha:
# ciphertext anywhere within 4 KB of a string key; XTEA: right after the key (or after an 8-byte IV). IV / nonce: zero,
# prepended to the ciphertext (CBC / CTR), the string or 16 raw bytes next to the key. crc-valid hits only; offset =
# first ciphertext byte (after a prepended IV); detail key=.. iv=.. / nonce=..
HCFG_BLOCK_KEYS = int(os.environ.get("HCTF_HCFG_BLOCK_KEYS", "500"))   # AES/ChaCha string keys tried (~0.6 ms each)
HCFG_XTEA_KEYS = int(os.environ.get("HCTF_HCFG_XTEA_KEYS", "150"))   # XTEA string keys tried (pure Python, ~0.2 ms each)
HCFG_BLOCK_SECS = float(os.environ.get("HCTF_HCFG_BLOCK_SECS", "1.5"))   # time box of the whole cipher pass
_BLK_WIN = 4096
_BLK_CONST = {bytes.fromhex("637c777bf26b6fc5"): "aes", bytes.fromhex("52096ad53036a538"): "aes",   # S-box, inv S-box
              bytes.fromhex("c66363a5f87c7c84"): "aes", bytes.fromhex("a56363c6847c7cf8"): "aes",   # Te0 BE / LE
              b"\xb9\x79\x37\x9e": "tea", b"\x9e\x37\x79\xb9": "tea", b"\x47\x86\xc8\x61": "tea",   # delta / -delta
              b"\x61\xc8\x86\x47": "tea", b"expand 32-byte k": "chacha", b"expand 16-byte k": "chacha"}
_BLK_HEX = re.compile(rb"(?:[0-9a-fA-F]{32}){1,2}")


def _xorb(a, b):
    n = min(len(a), len(b))
    return (int.from_bytes(a[:n], "little") ^ int.from_bytes(b[:n], "little")).to_bytes(n, "little")


def _find16(buf, pat, n, shift=0):
    """(alignment, block offset) of every block-aligned buf[p:p+len(pat)] == pat in a concatenation of n-byte segments
    (alignment a = segment index); shift=16: buf is xor'd against the previous block (skip segment-crossing pairs)."""
    p = buf.find(pat)
    while p >= 0:
        q = p + shift
        if p % 16 == 0 and not (shift and q % n == 0):
            yield q // n, q % n
        p = buf.find(pat, p + 1)


def _blk_crc_ok(blob):
    r = _parse_blob(blob)
    return bool(r and r[5])


def _aes_try(AES, data, key, lo, hi, ivs, emit, tag, aligns=tuple(range(16))):
    """AES ECB / CBC / CTR under `key`, ciphertext starting in [lo, hi); ivs = candidate 16-byte IVs / counter blocks.
    The window is decrypted / encrypted at every byte alignment in ONE call (segments concatenated)."""
    E, Z = AES.new(key, AES.MODE_ECB), bytes(16)
    ivs = [iv for iv in ivs if len(iv) == 16]
    cands = []   # (t, mode, iv)
    n = (min(hi + 32, len(data)) - lo - max(aligns)) // 16 * 16   # blocks starting in the window
    if n >= 16:
        segs = b"".join(data[lo + a:lo + a + n] for a in aligns)
        D, X = E.decrypt(segs), E.encrypt(segs)
        at = (lambda a, o: lo + aligns[a] + o)
        for a, o in _find16(D, HCFG_MAGIC, n):   # ECB / CBC with a zero IV
            cands += [(at(a, o), "ecb", Z), (at(a, o), "cbc", Z)]
        for iv in ivs:   # CBC with a stored IV
            if iv != Z:
                cands += [(at(a, o), "cbc", iv) for a, o in _find16(D, _xorb(HCFG_MAGIC, iv), n)]
        for a, o in _find16(_xorb(D[16:], segs), HCFG_MAGIC, n, 16):   # CBC, IV prepended to the ciphertext
            cands.append((at(a, o), "cbc", data[at(a, o) - 16:at(a, o)]))
        for a, o in _find16(_xorb(X, segs[16:]), HCFG_MAGIC, n, 16):   # CTR, initial counter block prepended
            cands.append((at(a, o), "ctr", data[at(a, o) - 16:at(a, o)]))
        cands = [c for c in cands if c[0] < hi]
    for iv in ivs:   # CTR with a stored / zero counter block (16-byte IV, or 8-byte nonce || 0 / 12-byte nonce || 1)
        pat = _xorb(HCFG_MAGIC, E.encrypt(iv))
        t = data.find(pat, lo, hi + 3)
        while 0 <= t < hi:
            cands.append((t, "ctr", iv))
            t = data.find(pat, t + 1, hi + 3)
    for t, mode, iv in cands:
        if mode == "ecb":
            head = E.decrypt(data[t:t + 16])
        elif mode == "cbc":
            head = _xorb(E.decrypt(data[t:t + 16]), iv)
        else:
            head = _xorb(data[t:t + 16], E.encrypt(iv))
        need = _need(head)
        ct = data[t:t + (need + 15) // 16 * 16]
        if len(ct) % 16 or len(ct) < need:
            continue
        if mode == "ecb":
            blob = E.decrypt(ct)
        elif mode == "cbc":
            blob = AES.new(key, AES.MODE_CBC, iv=iv).decrypt(ct)
        else:
            blob = AES.new(key, AES.MODE_CTR, nonce=b"", initial_value=iv).decrypt(ct)
        if _blk_crc_ok(blob[:need]):
            emit(t, "aes-" + mode, blob[:need], f"{tag} iv={iv.hex()}")
            return True
    return False


def _chacha_try(mods, data, key, lo, hi, nonces, emit, tag):
    """ChaCha20 (8/12-byte nonce, block counter 0 or 1; a 16-byte nonce = RFC 7539 LE counter || 12-byte nonce) and
    Salsa20 (8-byte nonce) under a 32-byte key: keystream 'HCFG' -> one find in the window."""
    ChaCha20, Salsa20 = mods
    for nz in nonces:
        for name, mk in (("chacha20", lambda nz=nz: ChaCha20.new(key=key, nonce=nz)),
                         ("salsa20", lambda nz=nz: Salsa20.new(key=key, nonce=nz))):
            if (name == "salsa20" and len(nz) != 8) or len(nz) not in (8, 12, 16):
                continue
            for ctr in ((int.from_bytes(nz[:4], "little"),) if len(nz) == 16 else (0, 1)):
                def stream(n, ctr=ctr, nz=nz, mk=mk):
                    c = ChaCha20.new(key=key, nonce=nz[4:]) if len(nz) == 16 else mk()
                    if ctr:
                        c.seek(64 * ctr)
                    return c.encrypt(bytes(n))
                if name == "salsa20" and ctr:
                    continue
                ks = stream(8)
                pat = _xorb(HCFG_MAGIC, ks)
                t = data.find(pat, lo, hi + 3)
                while 0 <= t < hi:
                    need = _need(_xorb(data[t:t + 8], ks))
                    blob = _xorb(data[t:t + need], stream(need))
                    if len(blob) == need and _blk_crc_ok(blob):
                        emit(t, name, blob, f"{tag} nonce={nz.hex()} ctr={ctr}")
                        return True
                    t = data.find(pat, t + 1, hi + 3)
    return False


def _xtea_dec(key, blk, be):
    f = ">" if be else "<"
    k = struct.unpack(f + "4I", key)
    v0, v1 = struct.unpack(f + "2I", blk)
    s, d, m = (0x9E3779B9 * 32) & 0xFFFFFFFF, 0x9E3779B9, 0xFFFFFFFF
    for _ in range(32):
        v1 = (v1 - ((((v0 << 4) ^ (v0 >> 5)) + v0) ^ (s + k[(s >> 11) & 3]))) & m
        s = (s - d) & m
        v0 = (v0 - ((((v1 << 4) ^ (v1 >> 5)) + v1) ^ (s + k[s & 3]))) & m
    return struct.pack(f + "2I", v0, v1)


def _xtea_try(data, key, starts, emit, tag):
    """XTEA (32 cycles, LE or BE words) ECB / CBC (zero or prepended 8-byte IV) at the candidate ciphertext starts."""
    for t in starts:
        blk = data[t:t + 8]
        if len(blk) < 8:
            continue
        for be in (False, True):
            d0 = _xtea_dec(key, blk, be)
            for mode, iv in (("ecb", bytes(8)), ("cbc", data[max(0, t - 8):t])):
                if len(iv) < 8 or _xorb(d0, iv)[:4] != HCFG_MAGIC:
                    continue
                need = _need(_xorb(d0, iv))
                ct = data[t:t + (need + 7) // 8 * 8]
                if len(ct) % 8 or len(ct) < need:
                    continue
                out, prev = bytearray(), iv
                for j in range(0, len(ct), 8):
                    c = ct[j:j + 8]
                    out += _xorb(_xtea_dec(key, c, be), prev if mode == "cbc" else bytes(8))
                    prev = c
                if _blk_crc_ok(bytes(out[:need])):
                    emit(t, "xtea-" + mode, bytes(out[:need]), f"{tag} {'be' if be else 'le'}"
                         + (f" iv={iv.hex()}" if mode == "cbc" else ""))
                    return True
    return False


def _block_scan(data, emit, late):
    """AES / ChaCha20 / Salsa20 / XTEA pass (see the block comment above); True once a crc-valid blob was emitted."""
    import hashlib
    try:
        from Crypto.Cipher import AES, ChaCha20, Salsa20
    except Exception:  # noqa: BLE001 - no pycryptodome: XTEA only
        AES = ChaCha20 = Salsa20 = None
    hits = {}
    for c, kind in _BLK_CONST.items():   # one bytes.find per constant (~10 ms / 40 MB; a regex alternation was 0.5 s)
        i, n = data.find(c), 0
        while i >= 0 and n < 64:
            hits.setdefault(kind, []).append(i)
            i, n = data.find(c, i + 1), n + 1
    for v in hits.values():
        v.sort()
    if not hits or (AES is None and "tea" not in hits):
        return False
    box, outer = time.time() + HCFG_BLOCK_SECS, late
    late = (lambda: outer() or time.time() > box)
    near = sorted(o for v in hits.values() for o in v[:16])
    strs = []
    for m in _RC4_KEY.finditer(data):
        s, o = m.group(1), m.start(1)
        j = bisect.bisect_left(near, o - 2 * _BLK_WIN)
        strs.append((not (j < len(near) and near[j] <= o + 2 * _BLK_WIN), len(strs), s, o, m.end() + 1))
    strs.sort()
    by_off = sorted((o, s) for _, _, s, o, _ in strs)
    offs = [o for o, _ in by_off]
    nkeys = nxtea = 0

    def jobs():   # strings near a constant hit: every key; then far strings' literal keys; then their derived keys
        for tier in (0, 1, 2):
            for far, _, s, o, e in strs:
                if far != (tier > 0):
                    continue
                keys = []
                if tier < 2 and len(s) in (16, 24, 32):
                    keys.append(("str", s))
                if tier < 2 and _BLK_HEX.fullmatch(s):
                    keys.append(("hex", binascii.unhexlify(s)))
                if tier != 1:
                    h = hashlib.sha256(s).digest()
                    keys += [("sha256", h), ("sha256[:16]", h[:16]), ("md5", hashlib.md5(s).digest())]
                if keys:
                    yield s, o, e, keys

    for s, o, e, keys in jobs():
        if late() or (nkeys >= HCFG_BLOCK_KEYS and nxtea >= HCFG_XTEA_KEYS):
            break
        lo, hi = max(0, o - _BLK_WIN), min(len(data), e + _BLK_WIN)
        j = bisect.bisect_left(offs, o)
        neigh = [by_off[x][1] for x in (j - 1, j + 1) if 0 <= x < len(by_off) and abs(by_off[x][0] - o) <= 256]
        raw16 = [data[e:e + 16], data[max(0, o - 17):o - 1]]
        for how, key in keys:
            tag = f"key={how}({s.decode('latin-1')!r}) key@{o}"
            if AES is not None and "aes" in hits and nkeys < HCFG_BLOCK_KEYS:
                nkeys += 1
                ivs = [bytes(16)] + [v for v in neigh + raw16 if len(v) == 16]
                ivs += [v + bytes(8) for v in neigh if len(v) == 8] + [v + b"\0\0\0\1" for v in neigh if len(v) == 12]
                if _aes_try(AES, data, key, lo, hi, list(dict.fromkeys(ivs)), emit, tag):
                    return True
            if AES is not None and "chacha" in hits and len(key) == 32 and nkeys < HCFG_BLOCK_KEYS:
                nkeys += 1
                nz = [bytes(8), bytes(12)] + [v for v in neigh + raw16 if len(v) in (8, 12, 16)]
                nz += [v[:12] for v in raw16] + [v[:8] for v in raw16]
                if _chacha_try((ChaCha20, Salsa20), data, key, lo, hi, list(dict.fromkeys(nz)), emit, tag):
                    return True
            if "tea" in hits and len(key) == 16 and nxtea < HCFG_XTEA_KEYS:
                nxtea += 1
                starts = {e, (e + 7) & ~7, e + 8, ((e + 7) & ~7) + 8}
                if _xtea_try(data, key, sorted(starts), emit, tag):
                    return True
    # raw 16/32-byte keys stored next to the ciphertext, within 4 KB of a constant hit
    for kind, offs_ in hits.items():
        if kind == "aes" and AES is None:
            continue
        for c in offs_[:2 if kind == "tea" else 4]:
            for k in range(max(0, c - _BLK_WIN) & ~7, min(len(data), c + _BLK_WIN), 8):
                if late():
                    return False
                for kl in ((16,) if kind == "tea" else (32,) if kind == "chacha" else (16, 32)):
                    key = data[k:k + kl]
                    if len(key) < kl or len(set(key)) < kl * 5 // 8:
                        continue
                    e, tag = k + kl, f"key=raw key@{k}"
                    if kind == "aes":
                        iv = data[e:e + 16]
                        if _aes_try(AES, data, key, e, e + 17, [bytes(16), iv], emit, tag, (0,)):   # [key][iv?][ct]
                            return True
                    elif kind == "chacha":
                        if any(_chacha_try((ChaCha20, Salsa20), data, key, e + d, e + d + 1, [data[e:e + d]], emit, tag)
                               for d in (12, 8)) or \
                                _chacha_try((ChaCha20, Salsa20), data, key, e, e + 1, [bytes(12)], emit, tag):
                            return True
                    elif _xtea_try(data, key, [e, e + 8], emit, tag):
                        return True
    return False


def hcfg_scan(data, *, deadline=None, ext=None, stop_on_valid=False, _depth=0):
    """Every HCFG blob in `data` (any storage encoding), best first: crc-valid + parsed JSON, then GM-confirmed
    encodings (raw, base64), then file order. Decoys (bad crc, truncated, unparsable JSON) are returned too with
    crc_ok/valid False -- callers take `next(h for h in hits if h.valid)`. Offsets follow the OFFSET LAW above.

    Bounded: cheap anchor finds first (encoded forms of the magic), then -- only while no valid blob was found -- the
    xor'd base64/raw pass (one big-int xor of the file, ~10 ms / 4 MB) and the headerless raw-deflate brute force
    (files <= HCTF_HCFG_DEFLATE_MAX, default 1 MiB). `deadline` (epoch seconds; HCTF_SOLVE_DEADLINE also honoured)
    stops the expensive passes early. ext=False (or HCTF_HCFG_SCAN_EXT=0): raw/base64/base64url/plain hex only (= the
    D13 solver's encodings)."""
    data = bytes(data)
    ext = HCFG_SCAN_EXT if ext is None else ext
    end = _ends(deadline)
    late = (lambda: end is not None and time.time() > end)
    hits, seen = [], set()

    def emit(off, enc, blob, detail=""):
        r = _parse_blob(blob)
        if r and (off, enc) not in seen and (ext or enc in _LEGACY):
            seen.add((off, enc))
            ver, key, n, crc, plain, ok, cfg = r
            hits.append(HcfgHit(off, enc, ver, key, n, crc, ok, cfg, plain, enc not in _CONFIRMED, detail))

    def valid():
        return any(h.valid for h in hits)

    def done():
        return stop_on_valid and valid()

    # ONE regex pass over the file finds every anchor (one bytes.find per anchor was ~2 ms / 4 MB each, ~38 ms total)
    mv = memoryview(data)
    u16_runs, zbudget = set(), [16 << 20]   # zbudget: total inflate output for streams that merely CONTAIN the blob
    ibudget = [256]   # int-array / word-swap candidates decoded
    u8budget = [64]   # utf8-raw re-decodes of crc-failing raw anchors (<= 128 KiB each)
    for m in _ANCHORS.finditer(data):
        i, a = m.start(), m.group(0)
        kind = _ANCHOR_KIND.get(a, "hex")
        if not ext and kind not in ("raw", "hex") and _ANCHOR_CODEC.get(a) is not _B64:
            continue   # kill-switch: the D13 solver's encodings only (raw, base64/url, hex)
        if kind == "raw":
            blob = data[i:i + _need(data[i:i + 8])]
            emit(i, "raw", blob)
            if ext and not (_parse_blob(blob) or (0,) * 6)[5]:   # big-endian len/crc header (BE target's C struct)
                be = _be_raw_at(data, i)
                if be:
                    emit(i, "raw-be", be)
                u8budget[0] -= 1
                u8 = u8budget[0] >= 0 and _utf8_raw_at(data, i)   # HashLink-style UTF-8 string of a latin-1 blob
                if u8 and (_parse_blob(u8) or (0,) * 6)[5]:   # crc-valid only: never a new decoy hit
                    emit(i, "utf8-raw", u8)
        elif kind == "hex":
            _hex_at(data, i, emit)
        elif kind == "text":
            _text_at(data, i, _ANCHOR_CODEC[a], emit)
        elif kind == "rev-raw":   # 'GFCH' = the last 4 bytes of the reversed blob
            e = i + 4
            if e >= 12:
                st = max(0, e - _need(data[e - 12:e][::-1]))
                emit(st, "reversed-raw", data[st:e][::-1])
            _swapped_at(data, i, 4, emit, ibudget)       # uint32 words 0x48434647 stored LE
            _swapped_at(data, i - 4, 8, emit, ibudget)   # uint64 words 0x48434647vvkkllll stored LE
        elif kind == "wide":      # uint32/uint64 element per blob byte
            _wide_at(data, i, (len(a) - 1) // 3, emit, ibudget)
        elif kind == "swap16":    # uint16 words 0x4843 0x4647 stored LE
            _swapped_at(data, i, 2, emit, ibudget)
        elif kind == "rev-b64":   # 'RGNES' = the last 5 chars of the reversed base64 text
            e = i + 5
            mm = _B64REV.match(data[max(0, e - 90000):e][::-1])   # reversed window: a linear forward match
            run = mm.group(0) if mm else b""
            r = _decode_text(_B64, run)
            if r:   # stored text starts with the '=' padding that ends the (un-reversed) base64
                tail = run[r[1]:r[1] + 2]
                emit(e - r[1] - (len(tail) - len(tail.lstrip(b"="))), "reversed-base64", r[0])
            _rotb64_at(data, i, a, emit)   # the same text reversed per LINE (multi-line only)
        elif kind == "u16raw":    # 'H\0C\0F\0G' (LE at i, BE at i-1): latin-1 widened raw blob
            for be, st in ((False, i), (True, i - 1)):
                if st < 0 or (be and data[st] != 0) or (not be and data[i + 7:i + 8] != b"\0"):
                    continue
                head = data[st:st + 24][1::2] if be else data[st:st + 24][0::2]
                span = data[st:st + 2 * _need(head)]
                hi, lo = (span[0::2], span[1::2]) if be else (span[1::2], span[0::2])
                if not hi.strip(b"\0"):
                    emit(st, ("utf16be-" if be else "utf16le-") + "raw", lo)
        elif kind == "u16text":   # widened text anchor: narrow the whole UTF-16 run, decode it as text
            for be, st in ((False, i), (True, i - 1)):
                if st < 0 or (be and data[st] != 0):
                    continue
