_SC_TABS = {}
_SC_EXTRA_INTENT = {"exit": "runtime", "exit_group": "runtime", "clone3": "process_exec", "write": "output",
                    "pwrite64": "output", "process_madvise": "process_access"}


def _sc_table(abi):
    if abi not in _SC_TABS:
        t, n = {}, 0
        for tok in {"x86_64": _SC_X64, "i386": _SC_I386, "aarch64": _SC_A64}[abi].split():
            if tok[0] == "@":
                n = int(tok[1:])
                continue
            if tok != "-":
                t[n] = tok
            n += 1
        _SC_TABS[abi] = t
    return _SC_TABS[abi]


def _sc_intent(name):
    it = _api_intent_of(name)
    return _SC_EXTRA_INTENT.get(name, "other") if it == "other" else it


def _sc_elf(data):
    """(arch, little-endian exec regions [(va, off, size)], sorted FUNC symbols [(va, size, name)]) or None."""
    if data[:4] != b"\x7fELF" or len(data) < 64 or data[4] not in (1, 2) or data[5] != 1:
        return None
    b64 = data[4] == 2
    mach = struct.unpack_from("<H", data, 18)[0]
    arch = {62: "x86_64", 3: "i386", 183: "aarch64"}.get(mach)
    if arch is None or (arch == "i386") == b64:
        return None
    if b64:
        phoff, shoff = struct.unpack_from("<QQ", data, 32)
        phes, phn, shes, shn = struct.unpack_from("<HHHH", data, 54)
    else:
        phoff, shoff = struct.unpack_from("<II", data, 28)
        phes, phn, shes, shn = struct.unpack_from("<HHHH", data, 42)
    regs, secs = [], []
    if shoff and shes >= (64 if b64 else 40) and shoff + shn * shes <= len(data):
        for k in range(min(shn, 4096)):
            o = shoff + k * shes
            if b64:
                nm, ty, fl, ad, of, sz, ln = struct.unpack_from("<IIQQQQI", data, o)
            else:
                nm, ty, fl, ad, of, sz, ln = struct.unpack_from("<IIIIIII", data, o)
            secs.append((ty, fl, ad, of, sz, ln))
            if ty == 1 and fl & 4 and of < len(data):
                regs.append((ad, of, min(sz, len(data) - of)))
    if not regs and phoff and phes >= (56 if b64 else 32):
        for k in range(min(phn, 256)):
            o = phoff + k * phes
            if o + phes > len(data):
                break
            if b64:
                ty, fl, of, va, _pa, fsz = struct.unpack_from("<IIQQQQ", data, o)
            else:
                ty, of, va, _pa, fsz, _msz, fl = struct.unpack_from("<IIIIIII", data, o)
            if ty == 1 and fl & 1 and of < len(data):
                regs.append((va, of, min(fsz, len(data) - of)))
    funcs = []
    es = 24 if b64 else 16
    for ty, fl, ad, of, sz, ln in secs:
        if ty not in (2, 11) or ln >= len(secs):
            continue
        st = secs[ln][3]
        for o in range(of, min(of + sz, len(data) - es + 1, of + es * 200000), es):
            if b64:
                nm, info, _oth, shx, val, fsz = struct.unpack_from("<IBBHQQ", data, o)
            else:
                nm, val, fsz, info, _oth, shx = struct.unpack_from("<IIIBBH", data, o)
            if info & 15 == 2 and shx and val:
                e = data.find(b"\0", st + nm, st + nm + 512)
                funcs.append((val, fsz, bytes(data[st + nm:e if e >= 0 else st + nm]).decode("latin-1")))
    funcs.sort()
    return arch, regs, funcs


_SC_FAM = {}
for _r in ("ax", "bx", "cx", "dx", "si", "di", "bp", "sp"):
    for _v in ("r" + _r, "e" + _r, _r):
        _SC_FAM[_v] = "r" + _r
for _r in ("al", "bl", "cl", "dl", "sil", "dil"):
    _SC_FAM[_r] = "r" + (_r[:-1] + "x" if len(_r) == 2 else _r[:-1])
for _k in range(8, 16):
    for _s in ("", "d", "w", "b"):
        _SC_FAM[f"r{_k}{_s}"] = f"r{_k}"
for _k in range(31):
    _SC_FAM[f"x{_k}"] = _SC_FAM[f"w{_k}"] = f"x{_k}"
_SC_NOWRITE = {"cmp", "test", "push", "bt", "cmn", "tst", "str", "stp", "strb", "strh", "stur", "nop", "endbr64",
               "endbr32", "prfm"}


def _sc_resolve(ins, fam, a64, ret_fam):
    """Value written to register family `fam` by the instructions before ins[-1] (the syscall) in its block, or None.
    `mov fam, imm` / `xor fam, fam` / `push imm; pop fam` / one `mov fam, reg` copy followed back."""
    copies = 0
    for k in range(len(ins) - 2, -1, -1):
        i = ins[k]
        m = i.mnemonic
        if m in ("call", "ret", "jmp", "loop", "hlt", "bl", "blr", "br", "b", "cbz", "cbnz", "tbz", "tbnz") \
                or m.startswith("j") or m.startswith("b."):
            return None
        if m in ("syscall", "int", "svc", "sysenter"):
            if fam == ret_fam:
                return None
            continue
        ops = [o.strip() for o in i.op_str.split(",")]
        if m in _SC_NOWRITE or not ops or _SC_FAM.get(ops[0]) != fam:
            continue
        src = ",".join(ops[1:]).strip().lstrip("#")
        if m in ("mov", "movz", "movabs") and len(ops) == 2:
            try:
                return int(src, 0) & 0xFFFFFFFF
            except ValueError:
                pass
            if src in _SC_FAM and copies == 0 and src not in ("xzr", "wzr"):
                fam, copies = _SC_FAM[src], 1
                continue
            return 0 if src in ("xzr", "wzr") else None
        if m in ("xor", "sub", "eor") and len(ops) == 2 and _SC_FAM.get(ops[1]) == fam:
            return 0
        if m == "pop" and k and ins[k - 1].mnemonic == "push":
            try:
                return int(ins[k - 1].op_str, 0) & 0xFFFFFFFF
            except ValueError:
                return None
        return None
    return None


def syscall_facts(data, deadline_s=0.4, max_sites=3000):
    """Raw syscall instructions of an ELF (x86-64 `syscall`, `int 0x80` -> i386 ABI, AArch64 `svc #0`) resolved to
    numbers and names (embedded uapi tables) and classified with the api_intent vocabulary. Facts: arch, syscall_abi,
    syscall_sites (count), syscall_numbers (per site, address order, "unknown" unresolved), syscalls (unique names in
    address order), syscall_count, unresolved_syscall_sites, syscall_intents {name: intent}, syscall_edges
    [[function, name, intent]] (FUNC symbol containing the site, "?" stripped), ptrace_requests (arg0 of raw ptrace,
    PTRACE_* names), ptrace_request_values (ints), *_csv. Not an ELF of those arches -> "none"; a supported ELF with
    no raw syscall -> lists "none"."""
    import time
    import capstone
    try:
        info = _sc_elf(data)
    except struct.error:
        return None
    if info is None:
        return "none"
    arch, regs, funcs = info
    a64 = arch == "aarch64"
    if a64:
        md = capstone.Cs(capstone.CS_ARCH_ARM64, capstone.CS_MODE_ARM)
    else:
        md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64 if arch == "x86_64" else capstone.CS_MODE_32)
    t_end = time.time() + deadline_s
    sites = []   # (va, abi, decoded block ending at the site)
    for va, off, sz in regs:
        buf = bytes(data[off:off + sz])
        if a64:
            pats = [(b"\x01\x00\x00\xd4", "aarch64")]
        else:
            pats = [(b"\xcd\x80", "i386")] + ([(b"\x0f\x05", "x86_64")] if arch == "x86_64" else [])
        hits = []
        for pat, abi in pats:
            p = buf.find(pat)
            while p >= 0 and len(hits) < max_sites:
                if not a64 or p % 4 == 0:
                    hits.append((p, abi))
                p = buf.find(pat, p + 1)
        for p, abi in sorted(hits):
            if time.time() > t_end or len(sites) >= max_sites:
                break
            ins = None
            if a64:
                lo = max(0, p - 64)
                ins = list(md.disasm(buf[lo:p + 4], va + lo))
                if not ins or ins[-1].address != va + p:
                    ins = None
            else:
                for back in range(min(64, p), -1, -1):   # longest decode chain that lands exactly on the site
                    cand = list(md.disasm(buf[p - back:p + 2], va + p - back))
                    if cand and cand[-1].address == va + p and \
                            sum(i.size for i in cand) == back + 2:
                        ins = cand if back or p < 16 else None   # nothing decodes into it: opcode bytes inside data
                        break
            if ins and ins[-1].mnemonic in ("syscall", "int", "svc"):
                sites.append((va + p, abi, ins))
    sites.sort(key=lambda s: s[0])
    num_fam, arg_fam = {"x86_64": ("rax", "rdi"), "i386": ("rax", "rbx"), "aarch64": ("x8", "x0")}, {}
    ret_fam = "x0" if a64 else "rax"
    starts = [f[0] for f in funcs]
    nums, names, edges, reqs = [], [], [], []
    for va, abi, ins in sites:
        nf, af = num_fam[abi]
        n = _sc_resolve(ins, nf, a64, ret_fam)
        nums.append(str(n) if n is not None else "unknown")
        if n is None:
            continue
        nm = _sc_table(abi).get(n, f"syscall_{n}")
        names.append(nm)
        j = bisect.bisect_right(starts, va) - 1
        fn = funcs[j][2] if j >= 0 and (va < funcs[j][0] + max(funcs[j][1], 1) or not funcs[j][1]) else "?"
        edges.append([fn, nm, _sc_intent(nm)])
        if nm == "ptrace":
            reqs.append(_sc_resolve(ins, af, a64, ret_fam))
    uniq = list(dict.fromkeys(names))
    f = {"arch": arch, "syscall_abi": ",".join(dict.fromkeys(s[1] for s in sites)) or "none",
         "syscall_sites": str(len(sites)), "syscall_numbers": nums or "none", "syscalls": uniq or "none",
         "syscall_count": str(len(uniq)), "unresolved_syscall_sites": str(nums.count("unknown")),
         "syscall_intents": {n: _sc_intent(n) for n in uniq} or "none", "syscall_edges": edges or "none",
         "ptrace_requests": [_PTRACE_REQ.get(r, str(r)) if r is not None else "unknown" for r in reqs] or "none",
         "ptrace_request_values": reqs}
    for k in ("syscall_numbers", "syscalls", "ptrace_requests"):
        f[k + "_csv"] = ",".join(f[k]) if isinstance(f[k], list) else "none"
    return f


_SC_MEMO = [None, None]


def _sc_memo(data):
    if _SC_MEMO[0] is not data:
        try:
            f = syscall_facts(data)
        except Exception:  # noqa: BLE001
            f = None
        _SC_MEMO[:] = [data, f]
    return _SC_MEMO[1]


def syscall_field(data, name):
    """One syscall_facts value: any key, or `intent:<syscall>` ("none" when the program makes no such raw syscall).
    "none" for a non-ELF / unsupported arch / unknown key; None if unparseable."""
    try:
        f = _sc_memo(data)
        if not isinstance(f, dict):
            return f
        k, _, arg = name.strip().partition(":")
        if k == "intent":
            return f["syscall_intents"].get(arg.strip(), "none") if isinstance(f["syscall_intents"], dict) else "none"
        v = f.get(k, "none")
        return "none" if v == [] else v
    except Exception:  # noqa: BLE001
        return None


DTRACE_SCHEMA = b"huntress.binary.dynamic_trace.v1"
DTRACE_MODELS = ("analysis", "sandbox", "workstation")   # HUNTRESS_HOST_MODEL options seen D10-D18
# Generator invariant: every D10-D18 member run under bwrap with HUNTRESS_HOST_MODEL=<m> printed this branch (gcc/zig/
# ldc/fpc/gfortran/gnat; tests/data/binary_fixtures/dtrace_*). Event counts differ per member and are NOT modeled.
DTRACE_BRANCH = {"analysis": "decoy", "sandbox": "failure", "workstation": "success"}
_DT_KEY = re.compile(rb'"([A-Za-z_][A-Za-z0-9_]{0,40})"\s*:')
_DT_LIT = re.compile(rb'"([A-Za-z_][A-Za-z0-9_]{0,40})"\s*:\s*"([\x20\x21\x23\x24\x26-\x7e]{0,120})"')
_DT_ENV = re.compile(rb"HUNTRESS_[A-Z0-9_]{2,40}")


def _dt_text(data):
    """Bytes to scan: the program itself, or for a jar the application classes' constant-pool strings NUL-joined."""
    if data[:2] == b"PK":
        try:
            return b"\x00".join(s.encode("utf-8", "replace") if isinstance(s, str) else bytes(s)
                                for _, c in jar_app_classes(bytes(data)) for s in class_utf8(c))
        except Exception:  # noqa: BLE001
            return b""
    return bytes(data)


def dynamic_trace_facts(data):
    """The embedded `huntress.binary.dynamic_trace.v1` trace template (D2-D18 members: ELF/PE rodata, jar constant
    pool, wasm data segment) -> {trace_schema, trace_family, trace_effects, trace_network, trace_campaign,
    trace_keys (static key list in template order; split fragments like `","event_count":` slot in after branch),
    trace_runtime_keys (keys with no literal value), host_model_env, host_models (sorted), trace_branches,
    branch_for_<model>}. Absent fields are "none"; None only if the input is not bytes."""
    try:
        buf = _dt_text(data)
    except Exception:  # noqa: BLE001
        return None
    try:
        f = {"trace_schema": "none", "trace_family": "none", "trace_effects": "none", "trace_network": "none",
             "trace_campaign": "none", "trace_keys": "none", "trace_runtime_keys": "none", "host_model_env": "none",
             "host_models": "none", "trace_branches": "none"}
        f.update({f"branch_for_{m}": "none" for m in DTRACE_MODELS})
        f.update({k + "_csv": "none" for k in ("trace_keys", "host_models", "trace_branches")})
        i = buf.find(DTRACE_SCHEMA)
        if i < 0:
            return f
        f["trace_schema"] = DTRACE_SCHEMA.decode()
        lo = buf.rfind(b"{", max(0, i - 16), i)
        if lo >= 0 and re.match(rb'\{\s*"schema"\s*:\s*"$', buf[lo:i]):
            hi = buf.find(b"}", i, i + 2048)
            tpl = buf[lo:hi + 1 if hi > 0 else i + 2048]
            keys = [k.decode() for k in _DT_KEY.findall(tpl)]
            lits = {k.decode(): v.decode() for k, v in _DT_LIT.findall(tpl)}
            # keys split into their own string (`","event_count":` before/after the template, gfortran/fpc/ldc)
            around = buf[max(0, i - 512):lo] + b"\x00" + buf[hi + 1:hi + 257] if hi > 0 else buf[max(0, i - 512):lo]
            for frag in re.findall(rb'(?:^|\x00)[^\x00]{0,6}?("[A-Za-z_][A-Za-z0-9_]{0,40}"\s*:[^\x00]{0,4})(?=\x00)',
                                   around):
                k = _DT_KEY.match(frag).group(1).decode()
                if k not in keys:
                    keys.insert(keys.index("branch") + 1 if "branch" in keys else len(keys), k)
            f["trace_keys"] = keys or "none"
            f["trace_runtime_keys"] = [k for k in keys if k not in lits] or "none"
            for k in ("family", "effects", "network", "campaign"):
                if lits.get(k):
                    f["trace_" + k] = lits[k]
        else:   # bare schema string (wasm D16): the family is the next NUL/length-delimited snake_case token
            m = re.match(rb"[\x00-\x1f]{1,4}([a-z][a-z0-9]*(?:_[a-z0-9]+)+)(?![A-Za-z0-9_])",
                         buf[i + len(DTRACE_SCHEMA):i + len(DTRACE_SCHEMA) + 80])
            if m:
                f["trace_family"] = m.group(1).decode()
        near = buf[max(0, i - (256 << 10)):i + (256 << 10)]   # bounded: a 67 MB member costs ~1 ms, not seconds
        envs = list(dict.fromkeys(e.decode() for e in _DT_ENV.findall(near)))
        if envs:
            f["host_model_env"] = next((e for e in envs if "HOST" in e or "MODEL" in e), envs[0])
        tok = lambda w, sep=b"_": re.search(rb"(?<![A-Za-z0-9%s])%s(?![A-Za-z0-9%s])" % (sep, w.encode(), sep),
                                           near) is not None
        models = [m for m in DTRACE_MODELS if tok(m)]
        branches = [b for b in ("success", "decoy", "failure") if tok(b, b"")]   # also `event_success.3` (gfortran)
        f["host_models"] = models or "none"
        f["trace_branches"] = branches or "none"
        if f["host_model_env"] != "none":
            for m in models:
                if DTRACE_BRANCH[m] in branches:
                    f[f"branch_for_{m}"] = DTRACE_BRANCH[m]
        for k in ("trace_keys", "host_models", "trace_branches"):
            f[k + "_csv"] = ",".join(f[k]) if isinstance(f[k], list) else "none"
        return f
    except Exception:  # noqa: BLE001
        return None


_DT_MEMO = [None, None]


def dynamic_trace_field(data, name):
    """One dynamic_trace_facts value by key (`branch_for_<model>` for any model; "none" for an unknown key/model)."""
    try:
        if _DT_MEMO[0] is data:
            f = _DT_MEMO[1]
        else:
            f = dynamic_trace_facts(data)
            _DT_MEMO[:] = [data, f]
        return f if not isinstance(f, dict) else f.get(name.strip(), "none")
    except Exception:  # noqa: BLE001
        return None


# --- Static predicate/branch evaluator (D23 "Trust Issues": "spot every predicate and force the truth out"). Never a
# real run: main() of a dynamically linked x86-64 ELF is emulated in unicorn with every libc import bound to a Python
# model -- getenv(<gate>) returns each host-model literal (others NULL), ptrace -> 0, clocks advance 1 ms per call (and
# by the requested amount over sleep/usleep/nanosleep), printf-family/puts/write captured -- and the printed trace record
# (`"branch"`, `"event_count"`, `"analysis_detected"`) is read per model. Host models = literals the program compares
# the env value against (strcmp/strncmp/memcmp/strcasecmp/strstr operands) plus the D10-D23 options.

_PB_NONE = "none"


def _pb_cstr(uc, a, cap=4096):
    if not a:
        return None
    out = b""
    try:
        while len(out) < cap:
            ch = bytes(uc.mem_read(a + len(out), 256))
            z = ch.find(b"\0")
            if z >= 0:
                return out + ch[:z]
            out += ch
    except Exception:  # noqa: BLE001
        k = len(out)
        while k < cap:   # page edge: byte-wise
            try:
                c = bytes(uc.mem_read(a + k, 1))
            except Exception:  # noqa: BLE001
                return out
            if c == b"\0":
                return out
            out += c
            k += 1
    return out


def _pb_fmt(fmt, nxt_i, nxt_f, rd):
    out = []
    pat = re.compile(rb"%([-+ #0]*)(\*|\d+)?(?:\.(\*|\d+))?(hh|h|ll|l|z|j|t|L|q)?([diouxXcspfFgGeEn%])")
    i = 0
    while i < len(fmt):
        m = pat.match(fmt, i) if fmt[i:i + 1] == b"%" else None
        if not m:
            out.append(fmt[i:i + 1])
            i += 1
            continue
        i = m.end()
        fl, wd, pr, ln, cv = m.groups()
        if cv == b"%":
            out.append(b"%")
            continue
        wd = nxt_i() & 0xffffffff if wd == b"*" else int(wd or 0)
        pr = (nxt_i() & 0xffffffff) if pr == b"*" else (int(pr) if pr is not None else None)
        if cv in b"fFgGeE":
            s = (("%" + fl.decode() + (str(wd) if wd else "") + (("." + str(pr)) if pr is not None else "") +
                  cv.decode()) % nxt_f()).encode()
        elif cv == b"s":
            s = rd(nxt_i()) or b"(null)"
            s = s[:pr] if pr is not None else s
        elif cv == b"c":
            s = bytes([nxt_i() & 0xff])
        elif cv == b"p":
            s = b"0x%x" % nxt_i()
        elif cv == b"n":
            nxt_i()
            s = b""
        else:
            v = nxt_i()
            bits = 64 if ln in (b"l", b"ll", b"z", b"j", b"t", b"q") else (8 if ln == b"hh" else 16 if ln == b"h" else 32)
            v &= (1 << bits) - 1
            if cv in b"di" and v >> (bits - 1):
                v -= 1 << bits
            s = (("%" + fl.decode().replace("#", "#" if cv in b"xXo" else "") + (str(wd) if wd else "") +
                  (("." + str(pr)) if pr is not None else "") + ("d" if cv in b"iu" else cv.decode())) % v).encode()
        if wd and len(s) < wd and cv in b"sc":
            s = s.ljust(wd) if b"-" in fl else s.rjust(wd)
        out.append(s)
    return b"".join(out)


def _pb_image(data):
    """-> dict(segs, base, main, stubs{got_va: name}, objs{got_va: name}, rel[(va, addend)], imports) or None."""
    from elftools.elf.elffile import ELFFile
    import capstone
    elf = ELFFile(io.BytesIO(data))
    if elf["e_machine"] != "EM_X86_64" or elf.elfclass != 64 or not elf.little_endian:
        return None
    base = 0x10000000 if elf["e_type"] == "ET_DYN" else 0
    segs = []
    for s in elf.iter_segments():
        if s["p_type"] == "PT_LOAD" and s["p_memsz"]:
            if s["p_memsz"] > 64 << 20:
                return None
            off, fsz = s["p_offset"], min(s["p_filesz"], max(0, len(data) - s["p_offset"]))
            segs.append((s["p_vaddr"] + base, s["p_memsz"], data[off:off + fsz], s["p_flags"]))
    if not segs:
        return None
    dsym = elf.get_section_by_name(".dynsym")
    if dsym is None:
        return None
    names = [(sym.name, sym["st_info"]["type"]) for sym in dsym.iter_symbols()]
    imports = {n for n, _ in names if n}
    if not imports & {"getenv", "secure_getenv"}:
        return {"imports": imports}
    slots, rel = {}, []
    for sec in elf.iter_sections():
        if sec["sh_type"] != "SHT_RELA":
            continue
        raw = sec.data()
        for off, info, add in struct.iter_unpack("<QQq", raw[:len(raw) // 24 * 24]):
            t, si = info & 0xffffffff, info >> 32
            if t == 8:
                rel.append((off + base, add + base))
            elif t in (6, 7, 1) and 0 < si < len(names) and names[si][0]:
                slots[off + base] = (names[si][0], names[si][1] == "STT_OBJECT", add if t == 1 else 0)
    main = None
    sym = elf.get_section_by_name(".symtab")
    if sym is not None:
        for s in sym.iter_symbols():
            if s.name == "main" and s["st_info"]["type"] == "STT_FUNC" and s["st_value"]:
                main = s["st_value"] + base
                break
    if main is None:   # stripped: rdi at _start's call to __libc_start_main
        ent = elf["e_entry"] + base
        seg = next((g for g in segs if g[0] <= ent < g[0] + len(g[2])), None)
        if seg is None:
            return None
        md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64)
        for ins in md.disasm(seg[2][ent - seg[0]:ent - seg[0] + 96], ent):
            o = ins.op_str.replace(" ", "")
            if ins.mnemonic in ("lea", "mov") and o.startswith("rdi,"):
                mm = re.fullmatch(r"rdi,(?:qwordptr)?\[rip([+-]0x[0-9a-f]+)\]", o)
                if ins.mnemonic == "lea" and mm:
                    main = ins.address + ins.size + int(mm.group(1), 16)
                elif ins.mnemonic == "mov" and re.fullmatch(r"rdi,0x[0-9a-f]+", o):
                    main = int(o[4:], 16) + base
            elif ins.mnemonic in ("call", "hlt"):
                break
    if main is None:
        return None
    return {"segs": segs, "base": base, "main": main, "slots": slots, "rel": rel, "imports": imports}


def _pb_run(img, model, gate=None, max_insns=3_000_000, timeout_ms=400):
    """Emulate main with HUNTRESS_HOST_MODEL (or `gate`) = model (None = unset). -> (stdout bytes, getenv names,
    compared literals vs the env value, unmodeled import names) or None if refused / did not finish."""
    import unicorn as U
    X = U.x86_const
    uc = U.Uc(U.UC_ARCH_X86, U.UC_MODE_64)
    pages = {}
    for va, msz, _, fl in img["segs"]:
        for p in range(va & ~0xfff, (va + msz + 0xfff) & ~0xfff, 0x1000):
            pages[p] = pages.get(p, 0) | U.UC_PROT_READ | U.UC_PROT_WRITE | (U.UC_PROT_EXEC if fl & 1 else 0)
    if len(pages) > 32768:
        return None
    run = []
    for p in sorted(pages):
        if run and p == run[-1][0] + run[-1][1] and pages[p] == run[-1][2]:
            run[-1][1] += 0x1000
        else:
            run.append([p, 0x1000, pages[p]])
    for p, n, prot in run:
        uc.mem_map(p, n, prot)
    for va, _, blob, _ in img["segs"]:
        uc.mem_write(va, blob)
    for off, add in img["rel"]:
        try:
            uc.mem_write(off, (add & (1 << 64) - 1).to_bytes(8, "little"))
        except Exception:  # noqa: BLE001
            pass
    top = (max(pages) + 0x1100000) & ~0xfffff
    STK, HEAP, STUB, TLS, SENT = top, top + 0x100000, top + 0x500000, top + 0x600000, top + 0x700000
    uc.mem_map(STK, 0x100000)
    uc.mem_map(HEAP, 0x400000)
    uc.mem_map(STUB, 0x100000, U.UC_PROT_READ | U.UC_PROT_EXEC)
    uc.mem_map(TLS, 0x10000)
    uc.mem_map(SENT, 0x1000, U.UC_PROT_READ | U.UC_PROT_EXEC)
    uc.mem_write(STUB, b"\xc3" * 0x100000)
    uc.reg_write(X.UC_X86_REG_FS_BASE, TLS + 0x8000)
    uc.mem_write(TLS + 0x8000, (TLS + 0x8000).to_bytes(8, "little"))
    uc.mem_write(TLS + 0x8028, (0x2f8c4a1e9b3d0000).to_bytes(8, "little"))   # stack-protector canary
    st = {"heap": HEAP + 0x1000, "objs": HEAP + 0x300000, "clk": 1_700_000_000_000_000, "out": [], "envs": [],
          "cmp": [], "unk": [], "env": None, "stop": None, "fd": 3}
    stub_name = {}
    for slot, (nm, obj, add) in img["slots"].items():
        if obj:
            a = st["objs"]
            st["objs"] += 0x400
            uc.mem_write(a, a.to_bytes(8, "little"))   # e.g. stdout/stderr FILE*: self-pointing scratch
        else:
            a = STUB + 16 * len(stub_name)
            stub_name[a] = nm
        try:
            uc.mem_write(slot, (a + add).to_bytes(8, "little"))
        except Exception:  # noqa: BLE001
            pass

    def alloc(n):
        a = st["heap"]
        st["heap"] += (max(1, n) + 15) & ~15
        if st["heap"] >= HEAP + 0x300000:
            raise MemoryError
        return a

    def put(b):
        a = alloc(len(b) + 1)
        uc.mem_write(a, b + b"\0")
        return a

    rd = lambda a: _pb_cstr(uc, a)
    R = [X.UC_X86_REG_RDI, X.UC_X86_REG_RSI, X.UC_X86_REG_RDX, X.UC_X86_REG_RCX, X.UC_X86_REG_R8, X.UC_X86_REG_R9]
    XM = [getattr(X, f"UC_X86_REG_XMM{k}") for k in range(8)]

    def args(start=0):
        sp = uc.reg_read(X.UC_X86_REG_RSP)
        st_i = [start, 0]
        st_f = [0]

        def ni():
            k = st_i[0]
            st_i[0] += 1
            if k < 6:
                return uc.reg_read(R[k])
            v = int.from_bytes(uc.mem_read(sp + 8 + 8 * st_i[1], 8), "little")
            st_i[1] += 1
            return v

        def nf():
            k = st_f[0]
            st_f[0] += 1
            if k < 8:
                return struct.unpack("<d", (uc.reg_read(XM[k]) & (1 << 64) - 1).to_bytes(8, "little"))[0]
            v = struct.unpack("<d", bytes(uc.mem_read(sp + 8 + 8 * st_i[1], 8)))[0]
            st_i[1] += 1
            return v
        return ni, nf

    def in_env(a):
        e = st["env"]
        return e is not None and e[0] <= a < e[1]

    def note_cmp(a, b, n=None):
        for x, y in ((a, b), (b, a)):
            if in_env(x) and not in_env(y):
                s = rd(y)
                if s is not None:
                    st["cmp"].append(s[:n] if n is not None else s)

    def tick(us=1000):
        st["clk"] += us
        return st["clk"]

    def sgn(v):
        return (v & (1 << 64) - 1)

    def cmpres(x, y):
        return sgn(-1 if x < y else 1 if x > y else 0)

    def f_printf(ni, nf, fmt_arg_first=True):
        return _pb_fmt(rd(ni()) or b"", ni, nf, rd)

    def call(name):
        a = [uc.reg_read(r) for r in R]
        nm = name.split("@")[0]
        if nm.startswith("__") and nm.endswith("_chk"):
            nm = nm[2:-4]
        if nm in ("getenv", "secure_getenv"):
            k = rd(a[0]) or b""
            st["envs"].append(k.decode("latin-1"))
            want = gate if gate is not None else ("HOST" in k.decode("latin-1") or "MODEL" in k.decode("latin-1"))
            if (k.decode("latin-1") == gate if gate is not None else want) and model is not None:
                p = put(model.encode("latin-1"))
                st["env"] = (p, p + len(model) + 1)
                return p
            return 0
        if nm in ("strcmp", "strcasecmp", "strcoll"):
            x, y = rd(a[0]) or b"", rd(a[1]) or b""
            note_cmp(a[0], a[1])
            if nm == "strcasecmp":
                x, y = x.lower(), y.lower()
            return cmpres(x, y)
        if nm in ("strncmp", "strncasecmp"):
            n = a[2] & 0xffffffff
            x, y = (rd(a[0]) or b"")[:n], (rd(a[1]) or b"")[:n]
            note_cmp(a[0], a[1], n)
            if nm == "strncasecmp":
                x, y = x.lower(), y.lower()
            return cmpres(x, y)
        if nm in ("memcmp", "bcmp"):
            n = min(a[2], 1 << 20)
            x, y = bytes(uc.mem_read(a[0], n)), bytes(uc.mem_read(a[1], n))
            note_cmp(a[0], a[1], n)
            return cmpres(x, y)
        if nm in ("strstr", "strcasestr"):
            h, n_ = rd(a[0]) or b"", rd(a[1]) or b""
            note_cmp(a[0], a[1])
            i = (h.lower().find(n_.lower()) if nm == "strcasestr" else h.find(n_))
            return a[0] + i if i >= 0 else 0
        if nm == "strlen":
            return len(rd(a[0]) or b"")
        if nm == "strnlen":
            return min(len(rd(a[0]) or b""), a[1])
        if nm in ("strchr", "strrchr"):
            s = rd(a[0]) or b""
            c = a[1] & 0xff
            if c == 0:
                return a[0] + len(s)
            i = s.find(bytes([c])) if nm == "strchr" else s.rfind(bytes([c]))
            return a[0] + i if i >= 0 else 0
        if nm in ("memcpy", "memmove"):
            uc.mem_write(a[0], bytes(uc.mem_read(a[1], min(a[2], 1 << 20))))
            return a[0]
        if nm == "memset":
            uc.mem_write(a[0], bytes([a[1] & 0xff]) * min(a[2], 1 << 20))
            return a[0]
        if nm in ("strcpy", "stpcpy"):
            s = rd(a[1]) or b""
            uc.mem_write(a[0], s + b"\0")
            return a[0] + (len(s) if nm == "stpcpy" else 0)
        if nm == "strncpy":
            s = (rd(a[1]) or b"")[:a[2]]
            uc.mem_write(a[0], s.ljust(a[2], b"\0")[:a[2]])
            return a[0]
        if nm == "strcat":
            d = rd(a[0]) or b""
            uc.mem_write(a[0] + len(d), (rd(a[1]) or b"") + b"\0")
            return a[0]
        if nm in ("malloc", "calloc", "realloc"):
            n = a[0] * a[1] if nm == "calloc" else (a[1] if nm == "realloc" else a[0])
            p = alloc(min(n, 1 << 20))
            if nm == "realloc" and a[0]:
                uc.mem_write(p, bytes(uc.mem_read(a[0], min(n, 4096))))
            return p
        if nm in ("strdup", "strndup"):
            s = rd(a[0]) or b""
            return put(s[:a[1]] if nm == "strndup" else s)
        if nm in ("atoi", "atol", "strtol", "strtoul", "strtoll", "strtoull"):
            m = re.match(rb"\s*([+-]?\d+)", rd(a[0]) or b"")
            return sgn(int(m.group(1)) if m else 0)
        if nm in ("toupper", "tolower"):
            c = a[0] & 0xff
            return ord(chr(c).upper() if nm == "toupper" else chr(c).lower()) if c < 128 else c
        if nm in ("printf", "vprintf_unsupported"):
            ni, nf = args(1 if name.endswith("_chk") else 0)
            st["out"].append(f_printf(ni, nf))
            return len(st["out"][-1])
        if nm in ("fprintf", "dprintf"):
            ni, nf = args(2 if name.endswith("_chk") else 1)
            st["out"].append(f_printf(ni, nf))
            return len(st["out"][-1])
        if nm in ("sprintf", "snprintf"):
            if nm == "sprintf":
                ni, nf = args(3 if name.endswith("_chk") else 1)
                cap = 1 << 16
            else:
                ni, nf = args(4 if name.endswith("_chk") else 2)
                cap = a[1]
            s = f_printf(ni, nf)
            if cap:
                uc.mem_write(a[0], s[:cap - 1] + b"\0")
            return len(s)
        if nm in ("puts",):
            st["out"].append((rd(a[0]) or b"") + b"\n")
            return 1
        if nm in ("fputs",):
            st["out"].append(rd(a[0]) or b"")
            return 1
        if nm in ("putchar", "fputc", "putc", "_IO_putc"):
            st["out"].append(bytes([a[0] & 0xff]))
            return a[0] & 0xff
        if nm in ("fwrite",):
            n = min(a[1] * a[2], 1 << 20)
            st["out"].append(bytes(uc.mem_read(a[0], n)))
            return a[2]
        if nm == "write":
            n = min(a[2], 1 << 20)
            if a[0] in (1, 2):
                st["out"].append(bytes(uc.mem_read(a[1], n)))
            return n
        if nm in ("exit", "_exit", "_Exit", "abort", "stack_chk_fail", "__stack_chk_fail", "quick_exit"):
            st["stop"] = nm
            uc.emu_stop()
            return 0
        if nm in ("ptrace", "prctl", "fflush", "setvbuf", "free", "close", "fclose", "setlocale", "srand",
                  "signal", "sigaction", "raise", "alarm", "pause", "atexit", "__cxa_atexit", "isatty",
                  "__cxa_finalize", "personality", "mlock", "madvise"):
            return 0
        if nm == "time":
            v = tick() // 1_000_000
            if a[0]:
                uc.mem_write(a[0], v.to_bytes(8, "little"))
            return v
        if nm in ("clock_gettime", "timespec_get"):
            v = tick()
            if nm == "timespec_get":
                a = [0, a[0]]
            uc.mem_write(a[1], struct.pack("<qq", v // 1_000_000, v % 1_000_000 * 1000))
            return 0 if nm == "clock_gettime" else 1
        if nm == "gettimeofday":
            v = tick()
            uc.mem_write(a[0], struct.pack("<qq", v // 1_000_000, v % 1_000_000))
            return 0
        if nm == "clock":
            return (tick() - 1_700_000_000_000_000)
        if nm == "sleep":
            tick((a[0] & 0xffffffff) * 1_000_000)
            return 0
        if nm == "usleep":
            tick(a[0] & 0xffffffff)
            return 0
        if nm in ("nanosleep", "clock_nanosleep"):
            p = a[0] if nm == "nanosleep" else a[2]
            s_, ns = struct.unpack("<qq", bytes(uc.mem_read(p, 16)))
            tick(s_ * 1_000_000 + ns // 1000)
            return 0
        if nm in ("getpid", "gettid"):
            return 4242
        if nm == "getppid":
            return 4241
        if nm in ("getuid", "geteuid", "getgid", "getegid"):
            return 1000
        if nm in ("sysconf", "get_nprocs", "get_nprocs_conf"):
            return 4
        if nm in ("fopen", "fopen64", "opendir", "popen", "dlopen"):
            return 0
        if nm in ("open", "open64", "openat", "access", "stat", "lstat", "readlink"):
            return sgn(-1)
        st["unk"].append(nm)
        return 0

    def on_stub(uc_, addr, size, _):
        nm = stub_name.get(addr)
        if nm is None:
            return
        try:
            uc.reg_write(X.UC_X86_REG_RAX, call(nm) & (1 << 64) - 1)
        except Exception:  # noqa: BLE001
            st["stop"] = "model:" + nm
            uc.emu_stop()

    def refuse(why):
        def cb(uc_, *a_):
            st["stop"] = why
            uc.emu_stop()
        return cb

    sp = STK + 0xf0000
    argv = HEAP + 0x200
    uc.mem_write(HEAP + 0x100, b"/x\0")
    uc.mem_write(argv, struct.pack("<QQQ", HEAP + 0x100, 0, 0))
    sp -= 8
    uc.mem_write(sp, SENT.to_bytes(8, "little"))
    uc.reg_write(X.UC_X86_REG_RSP, sp)
    uc.reg_write(X.UC_X86_REG_RDI, 1)
    uc.reg_write(X.UC_X86_REG_RSI, argv)
    uc.reg_write(X.UC_X86_REG_RDX, argv + 16)
    uc.hook_add(U.UC_HOOK_CODE, on_stub, None, STUB, STUB + 16 * max(1, len(stub_name)))
    uc.hook_add(U.UC_HOOK_INTR, refuse("int"))
    uc.hook_add(U.UC_HOOK_INSN, refuse("syscall"), None, 1, 0, X.UC_X86_INS_SYSCALL)
    uc.hook_add(U.UC_HOOK_MEM_INVALID, refuse("mem"))
    try:
        uc.emu_start(img["main"], SENT, timeout=timeout_ms * 1000, count=max_insns)
    except Exception:  # noqa: BLE001
        if st["stop"] is None:
            st["stop"] = "fault"
    pc = uc.reg_read(X.UC_X86_REG_RIP)
    if st["stop"] not in (None, "exit", "_exit", "_Exit", "quick_exit") or (st["stop"] is None and pc != SENT):
        return None
    return b"".join(st["out"]), st["envs"], st["cmp"], st["unk"]


def _pb_record(out):
    for line in reversed(re.findall(rb"\{[^\n{}]*\"branch\"[^\n{}]*\}", out or b"")):
        try:
            j = json.loads(line.decode("utf-8", "replace"))
        except ValueError:
            continue
        if isinstance(j, dict):
            return j
    return None


def _pb_trio(j):
    if not j:
        return _PB_NONE, _PB_NONE, _PB_NONE
    ad = j.get("analysis_detected", _PB_NONE)
    ec = j.get("event_count", _PB_NONE)
    return (str(j.get("branch", _PB_NONE)), ec if isinstance(ec, int) and not isinstance(ec, bool) else _PB_NONE,
            ("true" if ad else "false") if isinstance(ad, bool) else (str(ad) if ad is not None else _PB_NONE))


def predicate_branch_facts(data, deadline_s=0.8, models=()):
    """Branch / event_count / analysis_detected per host model of a dynamically linked x86-64 ELF, by emulating main()
    (unicorn) with libc imports modelled in Python -- never a real run. getenv(<gate>) returns the model literal (the
    gate = the getenv name holding HOST/MODEL; others NULL), ptrace/prctl -> 0, clocks +1 ms per call (+ the requested
    sleep), cpu count 4, file opens fail. Facts: host_model_env, host_models (sorted literals the env value is compared
    against via strcmp/strncmp/memcmp/strcasecmp/strstr; host_models_csv), for every model in host_models + analysis/
    sandbox/workstation + `models`: branch_for_<m>, event_count_for_<m> (int), analysis_detected_for_<m> ("true"/
    "false"), trace_for_<m> (compact JSON record); *_unset for the env var absent; branch_map (JSON {model: branch}).
    Not an ELF / no getenv import / not x86-64 -> every key "none"; unparseable ELF -> None."""
    f = {"host_model_env": _PB_NONE, "host_models": _PB_NONE, "host_models_csv": _PB_NONE, "branch_map": _PB_NONE}
    want = list(dict.fromkeys(list(DTRACE_MODELS) + [str(m) for m in models]))

    def blank(m):
        f.update({f"branch_for_{m}": _PB_NONE, f"event_count_for_{m}": _PB_NONE,
                  f"analysis_detected_for_{m}": _PB_NONE, f"trace_for_{m}": _PB_NONE})
    for m in want:
        blank(m)
    f.update({"branch_unset": _PB_NONE, "event_count_unset": _PB_NONE, "analysis_detected_unset": _PB_NONE,
              "trace_unset": _PB_NONE})
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    if data[:4] != b"\x7fELF" or b"getenv\0" not in data or len(data) > 24 << 20:   # bounded: 64 MB Swift = no-op
        return f
    try:
        img = _pb_image(data)
    except Exception:  # noqa: BLE001 -- truncated / hostile ELF: nothing to evaluate
        return f
    if img is None or "main" not in img:
        return f
    t_end = time.time() + deadline_s
    try:
        probe = _pb_run(img, "zz-hb-probe-model")
        if probe is None:
            return f
        envs = list(dict.fromkeys(probe[1]))
        gate = next((e for e in envs if "HOST" in e or "MODEL" in e), None)
        if gate is None:
            return f
        f["host_model_env"] = gate
        found = list(dict.fromkeys(s.decode("latin-1") for s in probe[2] if s and all(0x20 < c < 0x7f for c in s)))
        # length-gated dispatch (`strlen(m) == 8 && memcmp(...)`, Roslyn-style): probe each length of a lowercase
        # rodata token so the compare is reached; only literals the program really compares are kept
        lens = sorted({len(t) for t in re.findall(rb"(?<![\x21-\x7e])[a-z][a-z0-9_-]{2,23}(?=\x00)", data)})
        for n in (lens[:24] if not found else ()):
            if time.time() > t_end - deadline_s / 2:
                break
            r = _pb_run(img, "z" * n, gate)
            for s in (r[2] if r else ()):
                s = s.decode("latin-1")
                if s and s not in found and all(0x20 < ord(c) < 0x7f for c in s):
                    found.append(s)
        rounds = 0
        while rounds < 3 and time.time() < t_end:   # literals only reached after an earlier match (nested gates)
            rounds += 1
            new = []
            for m in list(found):
                r = _pb_run(img, m, gate)
                for s in (r[2] if r else ()):
                    s = s.decode("latin-1")
                    if s and s not in found and s not in new and all(0x20 < ord(c) < 0x7f for c in s):
                        new.append(s)
            if not new:
                break
            found += new
        base_rec = _pb_record(probe[0])
        bmap = {}
        for m in list(dict.fromkeys(want + sorted(found))) + [None]:
            if time.time() > t_end:
                break
            r = _pb_run(img, m, gate)
            j = _pb_record(r[0]) if r else None
            b, n, ad = _pb_trio(j)
            sfx = "unset" if m is None else f"for_{m}"
            f.update({f"branch_{sfx}": b, f"event_count_{sfx}": n, f"analysis_detected_{sfx}": ad,
                      f"trace_{sfx}": json.dumps(j, separators=(",", ":")) if j else _PB_NONE})
            if m is not None and b != _PB_NONE:
                bmap[m] = b
            if m is not None and m not in found and j and j != base_rec:   # inlined compare (movabs/cmp qword)
                found.append(m)
        f["host_models"] = sorted(found) or _PB_NONE
        f["host_models_csv"] = ",".join(f["host_models"]) if found else _PB_NONE
        f["branch_map"] = json.dumps(bmap, separators=(",", ":"), sort_keys=True) if bmap else _PB_NONE
        return f
    except Exception:  # noqa: BLE001
        return None


_PB_MEMO = [None, None]


def predicate_branch_field(data, name):
    """One predicate_branch_facts value by key; `branch_for_<x>` / `event_count_for_<x>` / `analysis_detected_for_<x>` /
    `trace_for_<x>` for any literal x (emulated on demand). "none" for an unknown key."""
    try:
        name = name.strip()
        if _PB_MEMO[0] is data:
            f = _PB_MEMO[1]
        else:
            f = predicate_branch_facts(data)
            _PB_MEMO[:] = [data, f]
        if not isinstance(f, dict):
            return f
        m = re.fullmatch(r"(?:branch|event_count|analysis_detected|trace)_for_(.+)", name)
        if m and name not in f and f["host_model_env"] != _PB_NONE:
            f.update({k: v for k, v in (predicate_branch_facts(data, models=(m.group(1),)) or {}).items()
                      if k not in f})
        return f.get(name, _PB_NONE)
    except Exception:  # noqa: BLE001
        return None


# --- Anti-analysis / sandbox gating facts (MITRE T1622 debugger evasion, T1497 virtualization/sandbox evasion; D18 had
# event_sandbox/event_decoy branches keyed by HUNTRESS_HOST_MODEL). Static only: imports, strings, and capstone context
# around rdtsc/cpuid opcodes and getenv/strcmp call sites. Vocabulary SPECULATIVE until the GM names it.

_AA_DBG_APIS = (("isdebuggerpresent", ("IsDebuggerPresent",)),
                ("checkremotedebuggerpresent", ("CheckRemoteDebuggerPresent",)),
                ("ntqueryinformationprocess", ("NtQueryInformationProcess", "ZwQueryInformationProcess")),
                ("ntsetinformationthread", ("NtSetInformationThread", "ZwSetInformationThread")))
_AA_VM_TOKENS = re.compile(rb"VMware|VMWARE|vmware|VirtualBox|VIRTUALBOX|virtualbox|VBox|VBOX|vbox|innotek|QEMU|qemu"
                           rb"|KVMKVMKVM|Microsoft Hv|XenVMMXenVMM|prl hyperv|bhyve bhyve|Parallels|Hyper-V|TCGTCGTCGTCG"
                           rb"|ACRNACRNACRN|VMwareVMware|vmtoolsd|VBoxService|/\.dockerenv|/sys/hypervisor")
_AA_VENDOR = (("vmware", (b"vmware",)), ("virtualbox", (b"virtualbox", b"vbox", b"innotek")), ("qemu", (b"qemu", b"tcgtcg")),
              ("kvm", (b"kvmkvm",)), ("hyperv", (b"microsoft hv", b"hyper-v")), ("xen", (b"xenvmm", b"/sys/hypervisor")),
              ("parallels", (b"prl hyperv", b"parallels")), ("bhyve", (b"bhyve",)), ("acrn", (b"acrnacrn",)),
              ("docker", (b"/.dockerenv",)))
_AA_DMI = re.compile(rb"/sys/(?:class/dmi/id|devices/virtual/dmi/id)/?[a-z_]{0,24}|/proc/scsi/scsi|/proc/sysinfo")
_AA_ENV_API = {"getenv", "secure_getenv", "__secure_getenv", "GetEnvironmentVariableA", "GetEnvironmentVariableW"}
_AA_CMP_API = {"strcmp", "strncmp", "strcasecmp", "strncasecmp", "strstr", "memcmp", "lstrcmpA", "lstrcmpiA"}
_AA_R64 = {"e" + r[1:]: r for r in ("rax", "rbx", "rcx", "rdx", "rsi", "rdi", "rbp", "rsp")}
_AA_R64.update({f"r{n}d": f"r{n}" for n in range(8, 16)})


def _aa_cstr(data, img, va, cap=200):
    off = next((o + va - a for a, sz, o, x in img["maps"] if a <= va < a + sz), None)
    if off is None or not 0 <= off < len(data):
        return None
    end = data.find(b"\0", off, off + cap)
    s = bytes(data[off:end if end >= 0 else off])
    return s.decode() if 1 <= len(s) and all(0x20 <= c < 0x7f for c in s) else None


def _aa_window(data, img, md, va, back=96, fwd=0):
    """Instructions of the decode chain that lands exactly on `va` (longest of <= `back` bytes), plus the instruction
    at `va` and `fwd` bytes after it; [] when no chain lands on it (not an instruction boundary)."""
    m = next(((a, sz, o) for a, sz, o, x in img["maps"] if x and a <= va < a + sz), None)
    if m is None:
        return []
    a, sz, o = m
    off = o + va - a
    for b in range(min(back, va - a), -1, -1):
        ins = list(md.disasm(bytes(data[off - b:off + fwd + 16]), va - b))
        k = next((j for j, i in enumerate(ins) if i.address >= va), None)
        if k is not None and ins[k].address == va:
            return ins[:k + 1 + sum(1 for i in ins[k + 1:] if i.address < va + fwd)], k
    return []


def _aa_reg_string(data, img, ins, k, reg):
    """C-string value of `reg` at instruction k (backward in the block: mov reg, reg2 / lea reg, [rip+d] / mov reg, imm
    / push imm for i386 arg 0)."""
    for i in reversed(ins[:k]):
        if i.mnemonic in ("call", "ret", "jmp") or i.mnemonic.startswith("j"):
            return None
        o = i.op_str.replace(" ", "")
        dst, _, src = o.partition(",")
        if reg == "push" and i.mnemonic == "push":
            try:
                return _aa_cstr(data, img, int(o, 0))
            except ValueError:
                return None
        if _AA_R64.get(dst, dst) != reg:
            continue
        if i.mnemonic == "lea":
            mm = re.fullmatch(r"(?:qword ptr )?\[rip([+-]0x[0-9a-f]+)\]", src.replace("qwordptr", ""))
            return _aa_cstr(data, img, i.address + i.size + int(mm.group(1), 16)) if mm else None
        if i.mnemonic == "mov":
            if src.startswith("0x") or src.isdigit():
                return _aa_cstr(data, img, int(src, 0))
            if _AA_R64.get(src, src) in _AA_R64.values() or re.fullmatch(r"r\d+", src):
                reg = _AA_R64.get(src, src)
                continue
        return None
    return None


def anti_analysis_facts(data, deadline_s=0.4):
    """Anti-debug / anti-VM / sandbox-gating evidence of an ELF / PE (x86, x86-64). Facts: anti_debug, anti_vm,
    evasion ("true"/"false"); anti_debug_techniques [ptrace_traceme, tracerpid, isdebuggerpresent,
    checkremotedebuggerpresent, ntqueryinformationprocess, ntsetinformationthread, timing] (timing = rdtsc/rdtscp in a
    named user function or twice in one function); anti_vm_techniques [cpuid_hypervisor (CPUID.1:ECX bit 31 tested),
    cpuid_hypervisor_vendor (leaf 0x4000000x), dmi, vm_strings, cpuinfo_hypervisor]; vm_strings (literal strings
    holding a VM vendor / artefact token, file order), vm_vendors, dmi_paths; env_gates (getenv/GetEnvironmentVariable
    names, call order), env_gate_values (string literals compared via strcmp-family in the functions that read them);
    decoy_functions (defined symbols containing "decoy"); evasion_functions (functions holding rdtsc/cpuid evidence);
    mitre_techniques (T1622, T1497.001, T1497.003, T1480), mitre_technique (first); *_csv twins. Lists are "none"
    when empty; not ELF/PE -> every key "none" (dict); unparseable ELF/PE -> None."""
    keys = ("anti_debug_techniques", "anti_vm_techniques", "vm_strings", "vm_vendors", "dmi_paths", "env_gates",
            "env_gate_values", "decoy_functions", "evasion_functions", "mitre_techniques")
    is_pe = data[:2] == b"MZ" and len(data) >= 0x40 and data[int.from_bytes(data[0x3c:0x40], "little"):][:4] == b"PE\0\0"
    if not (data[:4] == b"\x7fELF" or is_pe):
        f = {k: "none" for k in keys + ("anti_debug", "anti_vm", "evasion", "mitre_technique")}
        f.update({k + "_csv": "none" for k in keys})
        return f
    import capstone
    try:
        img = _cg_img_elf(data) if not is_pe else _cg_img_pe(data)
    except Exception:  # noqa: BLE001
        img = None
    if not isinstance(img, dict):
        return None
    t_end = time.time() + deadline_s
    blob = bytes(data)
    md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64 if img["bits"] == 64 else capstone.CS_MODE_32)
    imps = {n.split("@")[0] for n in (img["imports"].values() if isinstance(img["imports"], dict) else
                                     [n for _, n in img["imports"]])}
    funcs = img.get("funcs") or {}
    starts = sorted(funcs)
    fn_of = lambda va: (funcs[starts[bisect.bisect_right(starts, va) - 1]][0]   # noqa: E731
                        if starts and bisect.bisect_right(starts, va) else "sub_%x" % va)
    dbg, vm = [], []
    g_static = not imps   # static libc carries its own rdtsc/cpuid sites: stripped ones cannot be told apart
    g = None   # call graph only when ptrace / getenv is imported or (static) a symbol of that name exists
    if imps & ({"ptrace"} | _AA_ENV_API) or b"\0ptrace\0" in blob or b"\0getenv\0" in blob:
        try:
            g = _CG_MEMO[1] if _CG_MEMO[0] is data else call_graph(data, deadline_s=0.4)
        except Exception:  # noqa: BLE001
            g = None
    # ptrace(PTRACE_TRACEME): request resolved at the call site
    if isinstance(g, dict):
        try:
            sites = [int(a, 16) for a, c, t, k in g["call_sites"] if t == "ptrace"] if isinstance(g, dict) else []
            if 0 in _ptrace_requests(data, sites):
                dbg.append("ptrace_traceme")
        except Exception:  # noqa: BLE001
            pass
    if b"TracerPid" in blob:
        dbg.append("tracerpid")
    for tech, apis in _AA_DBG_APIS:
        if any(a in imps or a.encode() + b"\0" in blob for a in apis):
            dbg.append(tech)
    # rdtsc / rdtscp / cpuid at verified instruction boundaries in executable maps (bounded)
    rd, hv, hvv = {}, [], []
    for a, sz, o, x in img["maps"]:
        if not x:
            continue
        for pat in (b"\x0f\x31", b"\x0f\x01\xf9", b"\x0f\xa2"):
            p, n = blob.find(pat, o, o + sz), 0
            while p >= 0 and n < 64 and time.time() < t_end:
                n += 1
                va = a + p - o
                w = _aa_window(blob, img, md, va, fwd=96 if pat == b"\x0f\xa2" else 0)
                if w:
                    ins, k = w
                    fn = fn_of(va)
                    if pat != b"\x0f\xa2":
                        rd.setdefault(fn, []).append(va)
                    else:
                        leaf = None
                        for i in reversed(ins[:k]):
                            dst, _, src = i.op_str.replace(" ", "").partition(",")
                            if i.mnemonic == "mov" and dst == "eax":
                                leaf = int(src, 0) if src.startswith("0x") or src.isdigit() else None
                                break
                            if i.mnemonic == "xor" and dst == "eax" == src:
                                leaf = 0
                                break
                        after = " ".join(f"{i.mnemonic} {i.op_str}" for i in ins[k + 1:] if i.mnemonic != "ret")
                        if leaf is not None and 0x40000000 <= leaf <= 0x400000ff:
                            hvv.append(fn)
                        elif leaf == 1 and re.search(r"\b(?:shr|sar|bt|btr|bts|rol)\s+\w+,\s*0x1f\b|0x80000000\b",
                                                     after):
                            hv.append(fn)
                p = blob.find(pat, p + 1, o + sz)
    user = lambda fn: not fn.startswith(("_", "sub_", "do_lookup", "init_cpu", "dl_", "intel_", "handle_"))  # noqa: E731
    tfn = [fn for fn, v in rd.items() if user(fn) or fn.startswith("sub_") and len(v) >= 2 and not g_static]
    if tfn:
        dbg.append("timing")
    hv, hvv = [fn for fn in hv if user(fn) or fn.startswith("sub_")], [fn for fn in hvv]
    if hv:
        vm.append("cpuid_hypervisor")
    if hvv:
        vm.append("cpuid_hypervisor_vendor")
    dmi = list(dict.fromkeys(m.group().decode() for m in _AA_DMI.finditer(blob)))
    if dmi:
        vm.append("dmi")
    vstr = []
    for m in _AA_VM_TOKENS.finditer(blob):
        lo, hi = blob.rfind(b"\0", max(0, m.start() - 200), m.start()), blob.find(b"\0", m.end(), m.end() + 200)
        s = blob[lo + 1 if lo >= 0 else max(0, m.start() - 200):hi if hi > 0 else m.end()]
        if s and all(0x20 <= c < 0x7f for c in s) and s.decode() not in vstr:
            vstr.append(s.decode())
    if vstr:
        vm.append("vm_strings")
    low = b"\0".join(s.encode().lower() for s in vstr)
    vend = [v for v, toks in _AA_VENDOR if any(t in low for t in toks)]
    if b"/proc/cpuinfo" in blob and re.search(rb"(?<![A-Za-z_])hypervisor\0", blob):
        vm.append("cpuinfo_hypervisor")
    # env gates: getenv-family call sites -> name; strcmp-family literals in the same functions -> values
    gates, vals = [], []
    if isinstance(g, dict):
        try:
            cs = g["call_sites"] if isinstance(g, dict) else []
            gfn = {}   # function -> first getenv-family call site: only later comparisons gate on it
            for want, regs in ((_AA_ENV_API, ("rdi",) if img["bits"] == 64 else ("push",)),
                               (_AA_CMP_API, ("rsi", "rdi") if img["bits"] == 64 else ())):
                for av, c, t, kind in cs:
                    if t.split("@")[0] not in want or (want is _AA_CMP_API and int(av, 16) < gfn.get(c, 1 << 64)) \
                            or time.time() > t_end:
                        continue
                    w = _aa_window(blob, img, md, int(av, 16))
                    for r in regs:
                        s = _aa_reg_string(blob, img, *w, r) if w else None
                        if s and want is _AA_ENV_API:
                            gfn.setdefault(c, int(av, 16))
                            gates.append(s)
                        elif s:
                            vals.append(s)
                            break
        except Exception:  # noqa: BLE001
            pass
    if is_pe and not gates and imps & _AA_ENV_API:
        gates = [e.decode() for e in _DT_ENV.findall(blob)]
    gates, vals = list(dict.fromkeys(gates)), list(dict.fromkeys(vals))
    decoys = []
    try:
        names = [n for n, ty, d in _elf_symbols(data) if ty == 2 and d] if not is_pe else [v[0] for v in funcs.values()]
        decoys = list(dict.fromkeys(n for n in names if "decoy" in n.lower()))
    except Exception:  # noqa: BLE001
        pass
    mitre = (["T1622"] if dbg else []) + (["T1497.001"] if vm else []) + (["T1497.003"] if "timing" in dbg else []) \
        + (["T1480"] if gates and vals else [])
    f = {"anti_debug": "true" if dbg else "false", "anti_vm": "true" if vm else "false",
         "evasion": "true" if dbg or vm else "false", "anti_debug_techniques": dbg, "anti_vm_techniques": vm,
         "vm_strings": vstr, "vm_vendors": vend, "dmi_paths": dmi, "env_gates": gates, "env_gate_values": vals,
         "decoy_functions": decoys, "evasion_functions": list(dict.fromkeys(tfn + hv + hvv)), "mitre_techniques": mitre,
         "mitre_technique": mitre[0] if mitre else "none"}
    for k in keys:
        f[k] = f[k] or "none"
        f[k + "_csv"] = ",".join(f[k]) if isinstance(f[k], list) else "none"
    return f


_AA_MEMO = [None, None]


def anti_analysis_field(data, name):
    """One anti_analysis_facts value by key; `uses:<technique>` -> "true"/"false" (anti-debug or anti-VM technique);
    "none" for an unknown key; None when unparseable."""
    try:
        if _AA_MEMO[0] is data:
            f = _AA_MEMO[1]
        else:
            f = anti_analysis_facts(data)
            _AA_MEMO[:] = [data, f]
        if not isinstance(f, dict):
            return f
        k, _, arg = name.strip().partition(":")
        if k == "uses":
            if f["anti_debug"] == "none":
                return "none"
            ts = [t for v in (f["anti_debug_techniques"], f["anti_vm_techniques"]) if isinstance(v, list) for t in v]
            return "true" if arg.strip().lower() in ts else "false"
        return f.get(k, "none")
    except Exception:  # noqa: BLE001
        return None


_AD_OPP = {"je": "jne", "jne": "je", "jb": "jae", "jae": "jb", "jbe": "ja", "ja": "jbe", "jl": "jge", "jge": "jl",
           "jle": "jg", "jg": "jle", "js": "jns", "jns": "js", "jo": "jno", "jno": "jo", "jp": "jnp", "jnp": "jp"}
AD_TECHNIQUES = ("junk_bytes", "opposite_jcc_pair", "constant_jcc", "jmp_into_instruction", "overlapping_instructions",
                 "call_pop", "push_ret")
_AD_MEMO = [None, None]


def _ad_funcs(data):
    """(bits, [(name, va, file_off, size, sec_va, sec_off, sec_size, reloc_vas)]) for the FUNC/NOTYPE symbols of an
    x86 / x86-64 ELF (ET_REL: section-relative VAs, like objdump), or the exports + entry of a PE; None otherwise."""
    if data[:4] == b"\x7fELF" and len(data) >= 64 and data[5] == 1:
        b64 = data[4] == 2
        et, mach = struct.unpack_from("<HH", data, 16)
        if mach not in (3, 62):
            return None
        shoff = struct.unpack_from("<Q" if b64 else "<I", data, 40 if b64 else 32)[0]
        shes, shn = struct.unpack_from("<HH", data, 58 if b64 else 46)
        if not shoff or shn > 8192 or shes < (64 if b64 else 40) or shoff + shn * shes > len(data):
            return None
        fmt = "<IIQQQQIIQQ" if b64 else "<IIIIIIIIII"
        secs = [struct.unpack_from(fmt, data, shoff + k * shes) for k in range(shn)]
        relocs = {}
        for nm, ty, fl, ad, of, sz, ln, inf, al, es in secs:
            if ty in (4, 9) and inf < shn and of + sz <= len(data):   # SHT_RELA / SHT_REL applying to section inf
                es = es or ((24 if ty == 4 else 16) if b64 else (12 if ty == 4 else 8))
                rs = relocs.setdefault(inf, set())
                for o in range(of, of + min(sz, es * 200_000), es):
                    rs.add(struct.unpack_from("<Q" if b64 else "<I", data, o)[0])
        fns = []
        for nm, ty, fl, ad, of, sz, ln, inf, al, es in secs:
            if ty not in (2, 11) or ln >= shn or of + sz > len(data):
                continue
            so = secs[ln][4]
            es = es or (24 if b64 else 16)
            for o in range(of, of + min(sz, es * 400_000) - es + 1, es):
                if b64:
                    n, info, oth, sx, val, ssz = struct.unpack_from("<IBBHQQ", data, o)
                else:
                    n, val, ssz, info, oth, sx = struct.unpack_from("<IIIBBH", data, o)
                if info & 15 not in (0, 2) or not 0 < sx < shn or secs[sx][1] != 1 or not secs[sx][2] & 4:
                    continue
                e = data.find(b"\0", so + n, so + n + 512)
                name = data[so + n:e].decode("latin-1") if e > 0 else ""
                if not name or name.startswith((".L", "$")) or (info & 15 == 0 and info >> 4 == 0 and not ssz):
                    continue
                s = secs[sx]
                va = val + (s[3] if et == 1 else 0)
                if s[3] <= va < s[3] + s[5]:
                    fns.append((name, va, s[4] + va - s[3], ssz, s[3], s[4], s[5], relocs.get(sx, ())))
        out, seen = [], set()
        for f in sorted(fns, key=lambda f: (f[1], -f[3])):
            if f[1] not in seen:
                seen.add(f[1])
                out.append(f)
        return 64 if b64 else 32, out
    if data[:2] == b"MZ":
        import pefile
        pe = pefile.PE(data=bytes(data), fast_load=True)
        pe.parse_data_directories(directories=[pefile.DIRECTORY_ENTRY["IMAGE_DIRECTORY_ENTRY_EXPORT"]])
        b64 = pe.FILE_HEADER.Machine == 0x8664
        if pe.FILE_HEADER.Machine not in (0x14c, 0x8664):
            return None
        ib = pe.OPTIONAL_HEADER.ImageBase
        rv = [(e.name.decode("latin-1") if e.name else "ord_%d" % e.ordinal, e.address)
              for e in getattr(getattr(pe, "DIRECTORY_ENTRY_EXPORT", None), "symbols", []) or [] if e.address]
        if pe.OPTIONAL_HEADER.AddressOfEntryPoint:
            rv.append(("entry", pe.OPTIONAL_HEADER.AddressOfEntryPoint))
        out = []
        for name, rva in rv:
            s = pe.get_section_by_rva(rva)
            if s is None or not s.Characteristics & 0x20000000:
                continue
            sz = min(s.SizeOfRawData, s.Misc_VirtualSize or s.SizeOfRawData)
            out.append((name, ib + rva, s.PointerToRawData + rva - s.VirtualAddress, 0, ib + s.VirtualAddress,
                        s.PointerToRawData, sz, ()))
        return 64 if b64 else 32, sorted(out, key=lambda f: f[1])
    return None


def _ad_imm(op):
    return int(op, 0) if re.fullmatch(r"-?(0x[0-9a-f]+|\d+)", op) else None


def _ad_walk(md, code, lo, hi, relocs, limit=4000):
    """Recursive descent over code (code[0] at VA lo, function bytes [lo, hi)): both jcc edges, an opposite-condition
    jcc pair (or a jcc on a constant flag after `xor r, r`) as one unconditional jump, call $+5 + pop / push + ret
    tracked as a computed jump, stop at ret / jmp / hlt / ud2. -> (ins {va: (size, text)}, techniques, resolved)."""
    ins, tech, resolved = {}, set(), True
    starts = []
    work = [(lo, {}, [])]
    zf = None   # constant ZF state at the current path point (after xor r, r: 1)

    def dec(a):
        if not lo <= a < hi:
            return None
        return next(md.disasm(code[a - lo:a - lo + 16], a, 1), None)
    while work and len(ins) < limit:
        a, regs, stack = work.pop()
        zf = None
        while lo <= a < hi and len(ins) < limit:
            if a in ins:
                break
            k = bisect.bisect_right(starts, a) - 1
            if k >= 0 and a < starts[k] + ins[starts[k]][0]:
                tech.add("overlapping_instructions")
            i = dec(a)
            if i is None:
                resolved = False
                break
            mn, op = i.mnemonic, i.op_str
            nxt = a + i.size
            if bisect.bisect_left(starts, nxt) > bisect.bisect_left(starts, a) or \
                    (bisect.bisect_left(starts, a) < len(starts) and starts[bisect.bisect_left(starts, a)] < nxt):
                tech.add("overlapping_instructions")
            bisect.insort(starts, a)
            ins[a] = (i.size, mn, op)
            rel = any(r in relocs for r in range(a + 1, nxt))
            dst, _, src = op.partition(", ")
            if mn in ("ret", "retn"):
                if stack and isinstance(stack[-1], int):
                    tech.add("push_ret")
                    a = stack.pop()
                    continue
                break
            if mn in ("hlt", "ud2", "int3"):
                break
            if mn == "jmp":
                t = _ad_imm(op)
                if t is None or rel:
                    resolved = resolved and rel
                    break
                if a < t < nxt:
                    tech.add("jmp_into_instruction")
                a = t
                continue
            if mn in _AD_OPP or mn in ("jcxz", "jecxz", "jrcxz", "loop", "loope", "loopne"):
                t = _ad_imm(op)
                if t is None:
                    break
                j = dec(nxt)
                if mn in _AD_OPP and j is not None and j.mnemonic == _AD_OPP[mn] and _ad_imm(j.op_str) == t:
                    tech.add("opposite_jcc_pair")
                    if nxt not in ins:
                        bisect.insort(starts, nxt)
                        ins[nxt] = (j.size, j.mnemonic, j.op_str)
                    a = t
                    continue
                if zf is not None and mn in ("je", "jne"):
                    tech.add("constant_jcc")
                    a = t if (mn == "je") == (zf == 1) else nxt
                    continue
                work.append((t, dict(regs), list(stack)))
                a = nxt
                continue
            zf = None
            if mn == "call":
                t = _ad_imm(op)
                j = dec(nxt) if t == nxt and not rel else None
                if j is not None and j.mnemonic == "pop":
                    tech.add("call_pop")
                    stack.append(nxt)
                a = nxt
                continue
            if mn == "xor" and dst == src and not dst.startswith(("x", "y", "z", "m")):
                zf = 1
            if mn == "push":
                v = _ad_imm(op)
                stack.append(v if v is not None else regs.get(op))
            elif mn == "pop":
                regs[op] = stack.pop() if stack else None
            elif mn in ("add", "sub") and dst in regs and isinstance(regs[dst], int) and _ad_imm(src) is not None:
                regs[dst] += _ad_imm(src) * (1 if mn == "add" else -1)
            elif mn in ("add", "sub") and re.fullmatch(r"[dq]word ptr \[[er]sp\]", dst) and stack and \
                    isinstance(stack[-1], int) and _ad_imm(src) is not None:
                stack[-1] += _ad_imm(src) * (1 if mn == "add" else -1)
            elif mn == "lea" and re.fullmatch(r"\[rip [+-] 0x[0-9a-f]+\]", src):
                regs[dst] = nxt + int(src[5:-1].replace(" ", ""), 16)
            elif mn == "mov" and _ad_imm(src) is not None:
                regs[dst] = _ad_imm(src)
            elif mn in ("leave",) or dst in ("rsp", "esp"):
                stack = []
            elif dst in regs:
                regs[dst] = None
            a = nxt
    return ins, tech, resolved


def _ad_text(mn, op):
    """capstone text with bare single-digit immediates in 0x form (objdump / gdb / rizin-hex style)."""
    op = ", ".join(("0x" + p if re.fullmatch(r"\d", p) else p) for p in op.split(", ")) if op else ""
    return (mn + " " + op).strip()


def anti_disasm_facts(data, deadline_s=0.6):
    """Anti-disassembly constructs that break a linear sweep, per function of an x86 / x86-64 ELF (ET_REL objects
    too: VAs are section offsets like objdump) or PE (exports + entry): junk bytes after an unconditional jump,
    a jz+jnz (any opposite-condition) pair to one target, a jcc on a constant flag (xor r, r; jz), a jump into the
    middle of an instruction (`eb ff c0`), overlapping instructions, call $+5; pop, a push + ret computed jump.
    A recursive-descent capstone walk (both jcc edges, opposite pairs as unconditional, stop at ret / jmp) recovers
    the real code. Facts: has_anti_disassembly true|false, anti_disassembly_techniques (order of AD_TECHNIQUES),
    technique (first), anti_disassembly_functions (address order), protected_function (first); for the first
    protected function (and per function via anti_disasm_field "key:<fn>"): disassembly / recover_code (["mnemonic
    op"] address order), instruction_count, leaf_constant (eax at return by unicorn, "0x%x"), return_value (int32
    decimal), junk_bytes (count of unreached non-padding bytes), linear_sweep_desync true|false, techniques (list).
    Lists "none" when empty. Not ELF/PE -> every key "none"; unparseable x86 ELF/PE -> None."""
    keys = ("has_anti_disassembly", "anti_disassembly_techniques", "technique", "anti_disassembly_functions",
            "protected_function") + _AD_FN_KEYS
    if not (data[:4] == b"\x7fELF" or data[:2] == b"MZ"):
        return {k: "none" for k in keys}
    try:
        r = _ad_funcs(data)
    except Exception:  # noqa: BLE001
        r = None
    if r is None:
        return None
    import capstone
    bits, fns = r
    md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64 if bits == 64 else capstone.CS_MODE_32)
    t_end = time.time() + deadline_s
    per, prot, allt = {}, [], set()
    for k, (name, va, fo, sz, sva, so, ssz, rel) in enumerate(fns):
        if time.time() > t_end:
            break
        nxt_va = next((f[1] for f in fns[k + 1:] if f[1] > va), sva + ssz)
        end = min(va + sz if sz else nxt_va, sva + ssz, va + (1 << 16))
        if end <= va or fo < 0 or fo + (end - va) > len(data):
            continue
        code = bytes(data[fo:fo + end - va])
        ins, tech, ok = _ad_walk(md, code, va, end, rel)
        cov = bytearray(end - va)
        for a, (s, _, _) in ins.items():
            cov[a - va:a - va + s] = b"\1" * min(s, end - a)
        junk, p = 0, 0
        while p < len(cov):   # unreached runs that desync a linear sweep (landing pads / padding tile cleanly)
            if cov[p]:
                p += 1
                continue
            q = p
            while q < len(cov) and not cov[q]:
                q += 1
            if sum(x.size for x in md.disasm(code[p:q], 0)) != q - p:
                junk += q - p
            p = q
        if junk and ok and (bits == 64 or tech):
            tech.add("junk_bytes")
        if "call_pop" in tech and bits == 32 and "push_ret" not in tech:
            tech.discard("call_pop")   # i386 PIC: call 1f; 1: pop ebx is the compiler's own GOT idiom
        lin = set()
        for x in md.disasm(code, va):
            lin.add(x.address)
        desync = not set(ins) <= lin
        t = [x for x in AD_TECHNIQUES if x in tech]
        f = {"disassembly": [_ad_text(ins[a][1], ins[a][2]) for a in sorted(ins)], "instruction_count": str(len(ins)),
             "junk_bytes": str(junk), "linear_sweep_desync": "true" if desync else "false", "techniques": t or "none",
             "leaf_constant": "none", "return_value": "none", "address": "0x%x" % va}
        f["recover_code"] = f["disassembly"]
        if t:
            prot.append(name)
            allt.update(t)
            if not any(ins[a][1] == "call" and not (a + ins[a][0] in ins and ins[a + ins[a][0]][1] == "pop")
                       for a in ins):
                e = _sc_emulate(code + bytes(16), "x86-64" if bits == 64 else "x86")
                if e:
                    f["leaf_constant"], f["return_value"] = "0x%x" % (e[0] & 0xffffffff), str(e[0])
        per[name] = f
    first = per[prot[0]] if prot else {}
    out = {"has_anti_disassembly": "true" if prot else "false",
           "anti_disassembly_techniques": [x for x in AD_TECHNIQUES if x in allt] or "none",
           "anti_disassembly_functions": prot or "none", "protected_function": prot[0] if prot else "none"}
    out["technique"] = out["anti_disassembly_techniques"][0] if prot else "none"
    for k in _AD_FN_KEYS:
        out[k] = first.get(k, "none")
    out["functions"] = per
    return out


_AD_FN_KEYS = ("disassembly", "recover_code", "instruction_count", "leaf_constant", "return_value", "junk_bytes",
               "linear_sweep_desync", "techniques")


def anti_disasm_field(data, name):
    """One anti_disasm_facts value; "key:<function>" picks a function's own value (disassembly, recover_code,
    instruction_count, leaf_constant, return_value, junk_bytes, linear_sweep_desync, techniques, address);
    `uses:<technique>` -> "true"/"false"; "none" for an unknown key / function; None when unparseable."""
    try:
        if _AD_MEMO[0] is data:
            f = _AD_MEMO[1]
        else:
            f = anti_disasm_facts(data)
            _AD_MEMO[:] = [data, f]
        if not isinstance(f, dict):
            return f
        k, _, arg = name.strip().partition(":")
        k, arg = k.strip(), arg.strip()
        if k == "uses":
            ts = f["anti_disassembly_techniques"]
            return "none" if f["has_anti_disassembly"] == "none" else ("true" if arg in ts else "false")
        if arg:
            return f.get("functions", {}).get(arg, {}).get(k, "none")
        return f.get(k, "none") if k != "functions" else "none"
    except Exception:  # noqa: BLE001
        return None


def _u8prefix(b):
    try:
        return b.decode("utf-8")
    except UnicodeDecodeError as e:
        return b[:e.start].decode("utf-8")


def _utf8_raw_at(data, i):
    """Raw blob at i stored as the UTF-8 text of its latin-1 bytes (Haxe "\\u00NN" literal in a HashLink string table:
    bytes >= 0x80 -> C2/C3 xx): the decoded blob bytes, or None (not mangled / not latin-1 / truncated)."""
    h = _u8prefix(data[i:i + 24])[:12]
    if len(h) < 12 or max(map(ord, h)) > 255:
        return None
    n = 12 + int.from_bytes(h[6:8].encode("latin-1"), "little")
    s = _u8prefix(data[i:i + 2 * n])[:n]
    try:
        blob = s.encode("latin-1")
    except UnicodeEncodeError:
        return None
    return blob if len(blob) == n and blob != data[i:i + n] else None


def _be_raw_at(data, i):
    """Raw blob at i whose len/crc header fields are BIG-endian (a C struct compiled for mips/ppc/sparc/s390): the
    blob re-packed with an LE header (so _parse_blob reads it), only when crc32(plain) matches; else None."""
    if len(data) < i + 12:
        return None
    n, crc = struct.unpack_from(">HI", data, i + 6)
    body = data[i + 12:i + 12 + n]
    if not n or len(body) != n or zlib.crc32(body.translate(_XOR_TBL[data[i + 5]])) != crc:
        return None
    return data[i:i + 6] + struct.pack("<HI", n, crc) + body


_XOR_TBL = [bytes(b ^ k for b in range(256)) for k in range(256)]


def _func_start(data, s):
    """Best-effort start of the AArch64 function holding file offset `s` (-O2 hoists the builder's constants into
    registers there): the nearest prologue (sub sp,sp,#n / stp x29,x30,[sp,#-n]!), else just past a ret / br xN."""
    lo = max(0, s - 0x4000)
    t = s - 4
    while t >= lo:
        w = int.from_bytes(data[t:t + 4], "little")
        if w & 0xff8003ff == 0xd10003ff or w & 0xffc07fff == 0xa9807bfd:
            return t
        if w & 0xfffffc1f == 0xd61f0000 or w == 0xd65f03c0:
            break
        t -= 4
    t += 4
    while t < s and data[t:t + 4] in (b"\x1f\x20\x03\xd5", b"\0\0\0\0"):   # nop / zero padding
        t += 4
    return t if t >= lo + 4 else None


def _stack_emu(data, start, arch, upto=None):
    """Emulate (unicorn, no syscalls, unmapped data -> zero pages) the code at file offset `start` mapped at vaddr =
    file offset with sp/fp mid-stack; a call that leaves the window returns 0 to its caller. Every crc-valid HCFG blob
    left in memory."""
    import unicorn as U
    if arch == "aarch64":
        uc = U.Uc(U.UC_ARCH_ARM64, U.UC_MODE_ARM)
        regs = (U.arm64_const.UC_ARM64_REG_SP, U.arm64_const.UC_ARM64_REG_X29)
    else:
        uc = U.Uc(U.UC_ARCH_X86, U.UC_MODE_32 if arch == "x86" else U.UC_MODE_64)
        x = U.x86_const
        regs = (x.UC_X86_REG_ESP, x.UC_X86_REG_EBP) if arch == "x86" else (x.UC_X86_REG_RSP, x.UC_X86_REG_RBP)
    lo, hi = max(0, (start - 0x1000) & ~0xfff), min(len(data), max(start, upto or 0) + 0x10000)
    hi_pg = (hi + 0xfff) & ~0xfff
    stk = 0x7ff00000 if hi_pg <= 0x7ff00000 else (hi_pg + 0xfffff) & ~0xfffff   # 256 KB, sp/fp in the middle
    uc.mem_map(lo, hi_pg - lo)
    uc.mem_write(lo, data[lo:hi])
    uc.mem_map(stk, 0x40000)
    for r in regs:
        uc.reg_write(r, stk + 0x20000)
    extra = [0]

    def unmapped(uc, access, addr, size, value, ud):
        if access == U.UC_MEM_FETCH_UNMAPPED or extra[0] >= 32:
            return False
        extra[0] += 1
        try:
            uc.mem_map(addr & ~0xfff, 0x2000 if (addr & 0xfff) + size > 0x1000 else 0x1000)
        except U.UcError:
            return False
        return True
    uc.hook_add(U.UC_HOOK_MEM_UNMAPPED, unmapped)
    uc.hook_add(U.UC_HOOK_INTR, lambda uc, n, ud: uc.emu_stop())
    if arch == "x86-64":
        uc.hook_add(U.UC_HOOK_INSN, lambda uc, ud: uc.emu_stop(), None, 1, 0, U.x86_const.UC_X86_INS_SYSCALL)
    pc, left = start, 30000
    for _ in range(8):
        try:
            uc.emu_start(pc, hi_pg, timeout=50000, count=left)
            break
        except U.UcError as e:
            if e.errno != U.UC_ERR_FETCH_UNMAPPED:
                break
        left -= 2000   # (count is not reported back: charge each resume)
        if arch == "aarch64":   # bl / PLT stub out of the window: return 0 to the caller
            pc = uc.reg_read(U.arm64_const.UC_ARM64_REG_X30)
            uc.reg_write(U.arm64_const.UC_ARM64_REG_X0, 0)
        else:
            w = 4 if arch == "x86" else 8
            sp = uc.reg_read(regs[0])
            try:
                pc = int.from_bytes(uc.mem_read(sp, w), "little")
            except U.UcError:
                break
            uc.reg_write(regs[0], sp + w)
            uc.reg_write(U.x86_const.UC_X86_REG_EAX if arch == "x86" else U.x86_const.UC_X86_REG_RAX, 0)
        if not lo <= pc < hi or left <= 0:
            break
    out = []
    for b, e, _ in uc.mem_regions():
        buf = bytes(uc.mem_read(b, e - b + 1))
        i = buf.find(HCFG_MAGIC)
        while i >= 0 and len(out) < 8:
            blob = buf[i:i + _need(buf[i:i + 8])]
            if (_parse_blob(blob) or (0,) * 6)[5]:
                out.append(blob)
            i = buf.find(HCFG_MAGIC, i + 1)
    return out


def _stack_scan(data, emit, late):
    """Blob built at runtime from immediates (C `volatile char b[N]; b[0]='H'; ...`, stack strings): x86 movb/movw/movl
    $imm stores, movabs+push / push imm32 runs, AArch64 movz+strb. Emulate from the first instruction that puts 'H'
    (walking back over a push run), crc-valid hits only; offset = that instruction's file offset (speculative)."""
    try:
        import unicorn   # noqa: F401
    except ImportError:
        return
    arch = _arch_of(data)
    sites = []

    def back(rx, i, a):   # instruction start(s) for an immediate at offset i
        for k in range(2, 10):
            if i >= k and rx.match(data, i - k, i):
                st = i - k
                sites.append((st, a))
                if 0x40 <= data[st] <= 0x4f and data[st + 1] in (0xc6, 0xc7):
                    sites.append((st + 1, a))   # that 0x4X may be the previous instruction's last byte
                return
    if arch in (None, "x86-64", "x86"):
        a = arch or "x86-64"
        for pat in (b"H\xc6", b"H\x41\xc6"):
            i, n = data.find(pat), 0
            while i >= 0 and n < 1 << 16 and len(sites) < 4 * HCFG_STACK_SITES and not late():
                if _STK_X86N.match(data, i + 1):
                    back(_STK_X86B, i, a)
                i, n = data.find(pat, i + 1), n + 1
        i, n = data.find(HCFG_MAGIC), 0
        while i >= 0 and n < 4096 and len(sites) < 4 * HCFG_STACK_SITES and not late():
            if i >= 1 and data[i - 1] == 0x68:   # i386 push 'HCFG' is the LAST push: walk back over the push imm32 run
                s = i - 1
                while s >= 5 and data[s - 5] == 0x68 and i - s < 0x4000:
                    s -= 5
                sites.append((s, "x86"))
            elif i >= 2 and data[i - 2] in (0x48, 0x49) and 0xb8 <= data[i - 1] <= 0xbf:   # movabs r64 ; push r64
                s = i - 2
                while s >= 11 and data[s - 11] in (0x48, 0x49) and 0xb8 <= data[s - 10] <= 0xbf \
                        and 0x50 <= data[s - 1] <= 0x57 and i - s < 0x4000:
                    s -= 11
                sites.append((s, a))
            else:                                # movl $0x47464348 / movq $imm32 to memory
                back(_STK_X86L, i, a)
            i, n = data.find(HCFG_MAGIC, i + 1), n + 1
    if arch in (None, "aarch64"):
        for pat in _STK_A64:
            i, n = data.find(pat), 0
            while i >= 0 and n < 1 << 16 and len(sites) < 4 * HCFG_STACK_SITES and not late():
                s = i - 1
                if s % 4 == 0 and data[s] < 0x1f and (pat[0] == 0x69 or _STK_A64_C.search(data, s + 4, s + 48)):
                    sites.append((s, "aarch64"))
                i, n = data.find(pat, i + 1), n + 1
    sites = sorted(set(sites))
    done = set()
    for s, a in sites[:HCFG_STACK_SITES]:
        if late():
            return
        blobs = []
        for st in (s, _func_start(data, s) if a == "aarch64" else None):   # then the function (hoisted consts)
            if st is None or blobs or late():
                continue
            try:
                blobs = _stack_emu(data, st, a, s)
            except Exception:   # noqa: BLE001 -- unicorn on hostile bytes: never raise past the scan
                pass
        for blob in blobs:
            if blob not in done:
                done.add(blob)
                emit(s, "stack-built", blob, f"{a} emu@{s}")
        if done:
            return


_COB_LD = re.compile(rb"(?:[\x66\xf3]|[\x40-\x4f])?\x0f[\x10\x28\x6f][\x05\x0d\x15\x1d\x25\x2d\x35\x3d]"
                     rb"|\xc5[\xf8-\xfa\xfc-\xfe]\x10|\xc5[\xf8-\xfa\xfc-\xfe][\x28\x6f]", re.S)


def _cob_store_scan(data, emit, late):
    """GnuCOBOL module init (x86-64 ELF64 LE, libcob cue): WORKING-STORAGE VALUE literals are copied into the static
    b_N storage by gcc-expanded memcpy = movabs/movl immediates (cobc -O0) or movdqa/movups loads of 16-byte .rodata
    constants interleaved with movabs (cobc -O2), in any order. Sites: a movabs/movl immediate starting 'HCFG', or a
    rip-relative SSE/AVX load of a .rodata 'HCFG'. Emulate (unicorn, PT_LOAD-mapped, zero pages elsewhere) from just
    after the last PLT call before the site up to the next call/ret (<= 4096 insns); crc-valid blobs only -> encoding
    'stack-built', offset = the site instruction (speculative)."""
    if data[:4] != b"\x7fELF" or data[4:6] != b"\x02\x01" or data[18:20] != b"\x3e\x00" or len(data) < 64:
        return
    if b"cob_init" not in data and b"libcob" not in data:
        return
    try:
        import unicorn as U
    except ImportError:
        return
    phoff = struct.unpack_from("<Q", data, 32)[0]
    phentsz, phnum = struct.unpack_from("<HH", data, 54)
    loads = []
    for k in range(min(phnum, 64)):
        p = phoff + k * phentsz
        if p + 56 <= len(data):
            typ, flg, off, va, _pa, fsz, msz = struct.unpack_from("<IIQQQQQ", data, p)
            if typ == 1 and 0 < msz < 1 << 30:
                loads.append((va, off, fsz, msz, flg))
    if not loads:
        return
    o2v = lambda o: next((va + o - off for va, off, fsz, _m, _f in loads if off <= o < off + fsz), None)  # noqa: E731
    x = [(va, off, fsz) for va, off, fsz, _m, f in loads if f & 1]
    sites = []
    i, n = data.find(HCFG_MAGIC), 0
    while i >= 0 and n < 256 and len(sites) < 16:
        if i >= 2 and data[i - 2] in (0x48, 0x49) and 0xb8 <= data[i - 1] <= 0xbf:
            sites.append(i - 2)                              # movabs $'HCFG....', r64
        elif i >= 6 and data[i - 6] == 0xc7 and data[i - 5] == 0x05:
            sites.append(i - 6)                              # movl $'HCFG', disp(%rip)
        else:
            v = o2v(i)
            for va, off, fsz in x if v is not None else ():  # rip-relative 16-byte load of a .rodata HCFG
                for m in _COB_LD.finditer(data, off, min(off + fsz, off + (16 << 20))):
                    e = m.end()
                    if e + 4 <= len(data) and va + e + 4 - off + struct.unpack_from("<i", data, e)[0] == v:
                        sites.append(m.start())
                    if late():
                        return
        i, n = data.find(HCFG_MAGIC, i + 1), n + 1
    done = set()
    for s in sites[:16]:
        if late():
            return
        st = s
        for k in range(s - 5, max(0, s - 4096), -1):   # just after the last `call rel32` into code before the site
            if data[k] == 0xe8:
                t = k + 5 + struct.unpack_from("<i", data, k + 1)[0]   # same exec segment: file delta = va delta
                if any(off <= t < off + fsz for _va, off, fsz in x) and (
                        data[t:t + 4] == b"\xf3\x0f\x1e\xfa" or data[t:t + 2] == b"\xff\x25" or
                        data[t:t + 3] == b"\xf2\xff\x25"):   # PLT / .plt.sec stub (endbr64 / jmp *GOT)
                    st = k + 5
                    break
        try:
            uc = U.Uc(U.UC_ARCH_X86, U.UC_MODE_64)
            mapped = set()

            def page(addr):
                pg = addr & ~0xfff
                if pg in mapped or len(mapped) > 512:
                    return pg in mapped
                uc.mem_map(pg, 0x1000)
                mapped.add(pg)
                for va, off, fsz, msz, _f in loads:
                    a, b = max(pg, va), min(pg + 0x1000, va + fsz)
                    if a < b:
                        uc.mem_write(a, data[off + a - va:off + b - va])
                return True

            def unmapped(uc, access, addr, size, value, ud):
                if access == U.UC_MEM_FETCH_UNMAPPED:
                    return False
                return page(addr) and page(addr + size - 1)

            def code(uc, addr, size, ud):
                b = bytes(uc.mem_read(addr, min(size, 3)))
                if b[:1] in (b"\xe8", b"\xc3") or b[:2] in (b"\xff\x15", b"\xf2\xc3") or \
                        (b[:1] == b"\xff" and len(b) > 1 and 0xd0 <= b[1] <= 0xd7):
                    uc.emu_stop()
            pva = o2v(st)
            if pva is None:
                continue
            page(pva), page(pva + 0x1000)
            uc.mem_map(0x7ff00000, 0x40000)
            uc.reg_write(U.x86_const.UC_X86_REG_RSP, 0x7ff20000)
            uc.reg_write(U.x86_const.UC_X86_REG_RBP, 0x7ff20000)
            uc.hook_add(U.UC_HOOK_MEM_UNMAPPED, unmapped)
            uc.hook_add(U.UC_HOOK_CODE, code)
            try:
                uc.emu_start(pva, 0, timeout=100000, count=4096)
            except U.UcError:
                pass
            for b, e, _ in uc.mem_regions():
                buf = bytes(uc.mem_read(b, e - b + 1))
                j = buf.find(HCFG_MAGIC)
                while j >= 0:
                    blob = buf[j:j + _need(buf[j:j + 8])]
                    if blob not in done and (_parse_blob(blob) or (0,) * 6)[5]:
                        done.add(blob)
                        emit(s, "stack-built", blob, f"x86-64 cob-init emu@{s}")
                    j = buf.find(HCFG_MAGIC, j + 1)
        except Exception:   # noqa: BLE001 -- unicorn on hostile bytes: never raise past the scan
            continue
        if done:
            return


HCFG_CTOR_MAX = int(os.environ.get("HCTF_HCFG_CTOR_MAX", "16"))   # .init_array targets emulated (~2-20 ms each)
# ELF relocation types: RELATIVE / GLOB_DAT / JUMP_SLOT per machine (x86-64 62, AArch64 183)
_CTOR_ARCH = {62: ("x86-64", 8, (6, 7)), 183: ("aarch64", 1027, (1025, 1026))}
_CTOR_STUBS = ("malloc", "calloc", "free", "memcpy", "memmove", "memset", "strlen", "strcpy", "__memcpy_chk",
               "__memset_chk", "__memmove_chk")


def _elf_ctors(data):
    """(arch, base, loads, init_targets, relocs, imports, v2o) of a little-endian ELF64 x86-64/AArch64 image, else None.
    loads = [(vaddr, offset, filesz, memsz, flags)]; init_targets = .init_array function vaddrs (RELATIVE addends for a
    PIE whose slots are 0 in the file); relocs = [(r_offset, type, sym_index, addend)]; imports = {sym_index: name}."""
    if data[:4] != b"\x7fELF" or data[4] != 2 or data[5] != 1 or len(data) < 64:
        return None
    mach = struct.unpack_from("<H", data, 18)[0]
    if mach not in _CTOR_ARCH:
        return None
    phoff, shoff = struct.unpack_from("<QQ", data, 32)
    phentsz, phnum, shentsz, shnum = struct.unpack_from("<HHHH", data, 54)
    loads, dyn = [], None
    for k in range(min(phnum, 64)):
        p = phoff + k * phentsz
        if p + 56 > len(data):
            break
        typ, flg, off, va, _pa, fsz, msz = struct.unpack_from("<IIQQQQQ", data, p)
        if typ == 1 and msz and msz < 1 << 30:
            loads.append((va, off, fsz, msz, flg))
        elif typ == 2:
            dyn = (off, fsz)
    if not loads:
        return None
    base = 0x400000 if min(l[0] for l in loads) < 0x10000 else 0   # PIE: rebase off page 0

    def v2o(va):
        for lva, off, fsz, _m, _f in loads:
            if lva <= va < lva + fsz:
                return off + va - lva
        return None
    init, rels, syms = None, [], {}
    # section headers first (sh_link of a RELA section -> its symtab -> strtab), PT_DYNAMIC when stripped of them
    secs = []
    if shoff and shentsz == 64 and shoff + shnum * 64 <= len(data):
        secs = [struct.unpack_from("<IIQQQQIIQQ", data, shoff + k * 64) for k in range(min(shnum, 4096))]
    tabs = []
    for s in secs:
        if s[1] == 14 and init is None:                       # SHT_INIT_ARRAY
            init = (s[3], s[4], s[5])
        elif s[1] == 4 and s[9] == 24:                        # SHT_RELA
            tabs.append((s[4], s[5], s[6]))
    if not secs and dyn:
        d = {}
        for k in range(0, min(dyn[1], 8192), 16):
            t, v = struct.unpack_from("<qQ", data, dyn[0] + k) if dyn[0] + k + 16 <= len(data) else (0, 0)
            if t == 0:
                break
            d.setdefault(t, v)
        if 25 in d and 27 in d:
            init = (d[25], v2o(d[25]), d[27])
        for a, n in ((7, 8), (23, 2)):                        # DT_RELA/RELASZ, DT_JMPREL/PLTRELSZ
            if a in d and n in d and v2o(d[a]) is not None:
                tabs.append((v2o(d[a]), d[n], None))
    if not init or init[1] is None or not init[2]:
        return None
    for off, sz, link in tabs[:16]:
        for q in range(off, min(off + sz, len(data) - 23, off + (24 << 16)), 24):
            ro, info, add = struct.unpack_from("<QQq", data, q)
            rels.append((ro, info & 0xffffffff, info >> 32, add))
        if link is not None and link < len(secs) and not syms:   # dynsym -> dynstr names (import stubs)
            sy = secs[link]
            st = secs[sy[6]] if sy[6] < len(secs) else None
            if sy[9] == 24 and st:
                for j in range(1, min(sy[5] // 24, 1 << 14)):
                    nm = struct.unpack_from("<I", data, sy[4] + j * 24)[0]
                    e = data.find(b"\0", st[4] + nm, st[4] + nm + 128)
                    if e > 0:
                        syms[j] = data[st[4] + nm:e].decode("latin-1")
    rmap = {r[0]: r[3] for r in rels if r[1] == _CTOR_ARCH[mach][1]}
    tg = []
    for k in range(min(init[2] // 8, HCFG_CTOR_MAX * 2)):
        va = init[0] + 8 * k
        f = struct.unpack_from("<Q", data, init[1] + 8 * k)[0] if init[1] + 8 * k + 8 <= len(data) else 0
        f = f or rmap.get(va, 0)
        if f and f not in (0xffffffffffffffff,) and v2o(f) is not None:
            tg.append(f)
    return _CTOR_ARCH[mach][0], base, loads, tg, rels, syms, v2o


def _ctor_emu(info, fns, end, srcs=None):
    """Emulate the .init_array targets `fns` IN ORDER in one address space (= what the loader does: unicorn, image mapped
    once at its link address + base, RELATIVE relocs applied, GOT imports -> stubs for malloc/mem*/str*, anything else
    returns 0) until `end` (epoch s). (index, blobs): crc-valid HCFG blobs NOT stored verbatim in the file that sit in
    writable memory after the last target (index None: none). srcs (a set; the re-run after a hit): memory is checked
    after EVERY target, index = the first that left a blob, srcs = the file offsets of the bytes THAT target read (a
    Python hook per read, and a 37 MB .bss copy per check on a Go/Rust image: only worth it once something hit)."""
    import unicorn as U
    arch, base, loads, _tg, rels, syms, v2o, data = info
    a64 = arch == "aarch64"
    uc = U.Uc(U.UC_ARCH_ARM64, U.UC_MODE_ARM) if a64 else U.Uc(U.UC_ARCH_X86, U.UC_MODE_64)
    if a64:
        R = U.arm64_const
        SP, RET, ARGS, PC = R.UC_ARM64_REG_SP, R.UC_ARM64_REG_X0, (R.UC_ARM64_REG_X0, R.UC_ARM64_REG_X1,
                                                                     R.UC_ARM64_REG_X2), R.UC_ARM64_REG_PC
    else:
        R = U.x86_const
        SP, RET, ARGS, PC = R.UC_X86_REG_RSP, R.UC_X86_REG_RAX, (R.UC_X86_REG_RDI, R.UC_X86_REG_RSI,
                                                                   R.UC_X86_REG_RDX), R.UC_X86_REG_RIP
    spans = {}
    for va, off, fsz, msz, flg in loads:
        lo, hi = (base + va) & ~0xfff, (base + va + msz + 0xfff) & ~0xfff
        for pg in range(lo, hi, 0x1000):
            spans[pg] = flg
    pages = sorted(spans)
    if len(pages) > (96 << 20) >> 12:
        return []
    run = [pages[0]]
    for pg in pages[1:] + [None]:
        if pg is not None and pg == run[-1] + 0x1000:
            run.append(pg)
            continue
        uc.mem_map(run[0], len(run) * 0x1000)
        if pg is not None:
            run = [pg]
    for va, off, fsz, msz, flg in loads:
        uc.mem_write(base + va, data[off:off + fsz])
    STUB, STK, HEAP, DONE = 0x7e000000, 0x7f000000, 0x7c000000, 0x7dfff000
    uc.mem_map(STK, 0x40000)
    uc.mem_map(HEAP, 0x100000)
    uc.mem_map(STUB, 0x10000, U.UC_PROT_READ)   # not executable: a jump there = fetch-protected -> stub
    uc.mem_map(DONE, 0x1000, U.UC_PROT_READ)
    stubs = {}
    rel_t, imp_t = _CTOR_ARCH[183 if a64 else 62][1:]
    for ro, t, si, add in rels:
        try:
            if t == rel_t:
                uc.mem_write(base + ro, struct.pack("<Q", base + add))
            elif t in imp_t:
                slot = STUB + 16 * (len(stubs) % 0x1000)
                stubs[slot] = syms.get(si, "")
                uc.mem_write(base + ro, struct.pack("<Q", slot))
        except U.UcError:
            pass
    heap, extra = [HEAP], [0]
    exe = [(base + va, base + va + fsz, off) for va, off, fsz, msz, flg in loads]

    def unmapped(uc, access, addr, size, value, ud):
        if access == U.UC_MEM_FETCH_UNMAPPED or extra[0] >= 64:
            return False
        extra[0] += 1
        try:
            uc.mem_map(addr & ~0xfff, 0x2000 if (addr & 0xfff) + size > 0x1000 else 0x1000)
        except U.UcError:
            return False
        return True

    def rd(uc, access, addr, size, value, ud):
        for lo, hi, off in exe:
            if lo <= addr < hi and len(srcs) < 1 << 16:
                srcs.update(range(off + addr - lo, off + addr - lo + size))
                return
    uc.hook_add(U.UC_HOOK_MEM_UNMAPPED, unmapped)
    uc.hook_add(U.UC_HOOK_INTR, lambda uc, n, ud: uc.emu_stop())
    if not a64:
        uc.hook_add(U.UC_HOOK_INSN, lambda uc, ud: uc.emu_stop(), None, 1, 0, U.x86_const.UC_X86_INS_SYSCALL)
    for idx, fn in enumerate(fns):
        if time.time() > end:
            break
        if srcs is not None:
            srcs.clear()
            hk = uc.hook_add(U.UC_HOOK_MEM_READ, rd, None, min(e[0] for e in exe), max(e[1] for e in exe))
        sp = STK + 0x30000
        if a64:
            uc.reg_write(R.UC_ARM64_REG_X30, DONE)
        else:
            sp -= 8
            uc.mem_write(sp, struct.pack("<Q", DONE))
        uc.reg_write(SP, sp)
        _ctor_run(uc, U, R, a64, fn + base, stubs, heap, HEAP, DONE, SP, RET, ARGS, PC, end)
        if srcs is not None:
            uc.hook_del(hk)
        elif idx < len(fns) - 1 and time.time() <= end:
            continue
        out = []
        for b, e, perm in uc.mem_regions():
            if not perm & U.UC_PROT_WRITE or b == STUB or e - b > 96 << 20:
                continue
            buf = bytes(uc.mem_read(b, e - b + 1))
            i = buf.find(HCFG_MAGIC)
            while i >= 0 and len(out) < 8:
                blob = buf[i:i + _need(buf[i:i + 8])]
                if (_parse_blob(blob) or (0,) * 6)[5] and blob not in data:
                    out.append(blob)
                i = buf.find(HCFG_MAGIC, i + 1)
        if out:
            return idx, out
    return None, []


def _ctor_run(uc, U, R, a64, pc, stubs, heap, HEAP, DONE, SP, RET, ARGS, PC, end, smc=False):
    """Run one constructor from pc to the DONE return address; a call into an import stub is served here (malloc/
    calloc bump heap, memcpy/memmove/memset, strlen/strcpy; anything else returns 0) and resumed at the caller."""
    left = 300000
    for _ in range(64):
        try:
            uc.emu_start(pc, DONE, timeout=max(1000, int((end - time.time()) * 1e6)), count=left)
            break
        except U.UcError as e:
            if e.errno not in (U.UC_ERR_FETCH_UNMAPPED, U.UC_ERR_FETCH_PROT):
                break
        left -= 3000
        cur = uc.reg_read(PC)
        if cur == DONE or left <= 0 or time.time() > end:
            break
        a = [uc.reg_read(r) for r in ARGS]
        name, rv = stubs.get(cur & ~0xf, ""), 0
        try:
            if smc and name in ("getpagesize", "sysconf"):   # smc_decrypt: page-align arithmetic before mprotect
                rv = 4096
            elif name in ("malloc", "calloc"):
                n = (a[0] * (a[1] if name == "calloc" else 1) + 15) & ~15
                if n < 0x80000 and heap[0] + n < HEAP + 0x100000:
                    rv, heap[0] = heap[0], heap[0] + n
            elif name in ("memcpy", "memmove", "__memcpy_chk", "__memmove_chk") and a[2] < 1 << 20:
                uc.mem_write(a[0], bytes(uc.mem_read(a[1], a[2])))
                rv = a[0]
            elif name in ("memset", "__memset_chk") and a[2] < 1 << 20:
                uc.mem_write(a[0], bytes([a[1] & 0xff]) * a[2])
                rv = a[0]
            elif name in ("strlen", "strcpy"):
                q, s = a[1] if name == "strcpy" else a[0], b""
                while b"\0" not in s and len(s) < 1 << 16:   # page by page: a string near a mapping's end
                    s += bytes(uc.mem_read(q + len(s), 0x1000 - ((q + len(s)) & 0xfff)))
                n = s.find(b"\0")
                if name == "strcpy":
                    uc.mem_write(a[0], s[:n + 1])
                rv = a[0] if name == "strcpy" else n
        except U.UcError:
            rv = 0
        uc.reg_write(RET, rv)
        if a64:
            pc = uc.reg_read(R.UC_ARM64_REG_X30)
        else:
            sp = uc.reg_read(SP)
            pc = struct.unpack("<Q", bytes(uc.mem_read(sp, 8)))[0]
            uc.reg_write(SP, sp + 8)
        if pc == DONE:
            break


HCFG_CTOR_SECS = float(os.environ.get("HCTF_HCFG_CTOR_SECS", "0.4"))   # wall budget of the whole constructor pass


def _ctor_scan(data, emit, late):
    """Blob DECODED at load time by an ELF constructor (C __attribute__((constructor)), C++ static initialiser: the
    .init_array targets, x86-64/AArch64 ELF64) into a global/heap buffer under any per-binary scheme (LCG keystream,
    keyed tables, ...): emulate the targets in order, crc-valid blobs absent from the file bytes only. Offset = the
    first file byte of the longest contiguous run of file bytes the hitting constructor READ (= the stored encoded
    blob; speculative), else the constructor's own file offset; detail names the init_array slot."""
    try:
        import unicorn   # noqa: F401
        info = _elf_ctors(data)
    except Exception:   # noqa: BLE001 -- hostile headers
        return
    if not info or not info[3]:
        return
    info = info + (data,)
    fns = info[3][:HCFG_CTOR_MAX]
    end = time.time() + HCFG_CTOR_SECS
    try:
        k, blobs = _ctor_emu(info, fns, end)
    except Exception:   # noqa: BLE001 -- unicorn on hostile bytes: never raise past the scan
        return
    if k is None or late():
        return
    srcs = set()
    try:   # re-run checking after each constructor, reads hooked: which one decoded it, where the stored form sits
        k2, b2 = _ctor_emu(info, fns[:k + 1], time.time() + HCFG_CTOR_SECS, srcs=srcs)
        if k2 is not None:
            k, blobs = k2, b2
        else:
            srcs.clear()
    except Exception:   # noqa: BLE001
        srcs.clear()
    best, cur = (0, info[6](fns[k])), None
    for o in sorted(srcs):
        cur = (cur[0], o) if cur and o == cur[1] + 1 else (o, o)
        if cur[1] - cur[0] + 1 > best[0]:
            best = (cur[1] - cur[0] + 1, cur[0])
    for blob in blobs:
        emit(best[1], "init-decoded", blob, f"{info[0]} init_array[{k}] fn@{info[6](fns[k])} src={best[0]}B")


# --- self-modifying / runtime-decrypted code or data (mprotect RWX + xor loop over a function body or a data section,
# then call): main() is emulated ONCE in the constructor-pass address space (_ctor_emu's mapping, imports -> stubs,
# mprotect / pkey_mprotect (libc or inline syscall) -> 0, getpagesize / sysconf -> 4096), stopping the moment execution
# enters a page main itself wrote (the decrypted function, before it runs / re-encrypts) or at main's return. Bytes of
# the file-backed image that differ from the relocated load image are patched back at their FILE offsets, so every
# static extractor (hcfg_scan, emulate_return_value, disassembly) runs on the decrypted copy with unchanged offsets.
HCFG_SMC_SECS = float(os.environ.get("HCTF_HCFG_SMC_SECS", "0.4"))   # wall budget of the main() emulation
SMC_MAX_PATCH = 1 << 20   # decrypted bytes patched back per image
_SMC_PROTECT = ("mprotect", "pkey_mprotect", "__mprotect")
_SMC_SYSCALL = re.compile(rb"(?:\xb8|\x48\xc7\xc0)(?:\x0a|\x49\x01)\x00\x00\x00")   # mov eax/rax, 10 (mprotect) / 329


def _smc_main(data, info):
    """vaddr of main(): FUNC symbol 'main' (symtab / dynsym), else the `lea rdi, [rip+d]` / `mov rdi, imm32` that
    _start hands __libc_start_main (x86-64), else None."""
    arch, _base, _loads, _tg, _rels, _syms, v2o = info[:7]
    shoff, = struct.unpack_from("<Q", data, 40)
    shentsz, shnum = struct.unpack_from("<HH", data, 58)
    if shoff and shentsz == 64 and shoff + shnum * 64 <= len(data):
        secs = [struct.unpack_from("<IIQQQQIIQQ", data, shoff + k * 64) for k in range(min(shnum, 4096))]
        for s in secs:
            if s[1] not in (2, 11) or s[9] != 24 or s[6] >= len(secs):
                continue
            st = secs[s[6]]
            strs = data[st[4]:st[4] + st[5]]
            j = strs.find(b"\0main\0")
            if j < 0:
                continue
            for q in range(s[4], min(s[4] + s[5], len(data) - 23, s[4] + (24 << 18)), 24):
                nm, inf, _o, _sh, va = struct.unpack_from("<IBBHQ", data, q)
                if nm == j + 1 and inf & 15 == 2 and va:
                    return va
    if arch != "x86-64":
        return None
    ent, = struct.unpack_from("<Q", data, 24)
    o = v2o(ent)
    if o is None:
        return None
    win = data[o:o + 64]
    m = re.search(rb"\x48\x8d\x3d(....)|\x48\xc7\xc7(....)", win, re.S)
    if not m:
        return None
    if m.group(1):
        return ent + m.end() + struct.unpack("<i", m.group(1))[0]
    return struct.unpack("<I", m.group(2))[0]


def smc_decrypt(data, *, budget=None):
    """Runtime self-decryption replayed statically (x86-64 / AArch64 little-endian ELF64 with a cue: an mprotect /
    pkey_mprotect import, an inline mprotect syscall, or a W+X PT_LOAD). -> {"image": file bytes with the decrypted
    ranges patched in, "ranges": [(file_offset, size, vaddr)], "main": vaddr, "stopped": "exec-written" | "return",
    "keys": [repeating xor key bytes per range or None]} when main() rewrote file-backed bytes, else None (no cue, no
    main, nothing rewritten, refused). Never raises."""
    try:
        import unicorn as U
        info = _elf_ctors(data)
        if not info:
            return None
        arch, base, loads, _tg, rels, syms, v2o = info
        names = set(syms.values())
        if not (names & set(_SMC_PROTECT) or any(l[4] & 3 == 3 for l in loads)
                or (arch == "x86-64" and b"\x0f\x05" in data and _SMC_SYSCALL.search(data))):
            return None
        main = _smc_main(data, info)
        if main is None or v2o(main) is None:
            return None
        return _smc_emu(data, info + (data,), main, time.time() + (HCFG_SMC_SECS if budget is None else budget))
    except Exception:   # noqa: BLE001 -- unicorn / hostile headers: never raise past the caller
        return None


def _smc_emu(data, info, main, end):
    import unicorn as U
    arch, base, loads, _tg, rels, syms, v2o, _d = info
    a64 = arch == "aarch64"
    uc = U.Uc(U.UC_ARCH_ARM64, U.UC_MODE_ARM) if a64 else U.Uc(U.UC_ARCH_X86, U.UC_MODE_64)
    if a64:
        R = U.arm64_const
        SP, RET, ARGS, PC = R.UC_ARM64_REG_SP, R.UC_ARM64_REG_X0, (R.UC_ARM64_REG_X0, R.UC_ARM64_REG_X1,
                                                                     R.UC_ARM64_REG_X2), R.UC_ARM64_REG_PC
    else:
        R = U.x86_const
        SP, RET, ARGS, PC = R.UC_X86_REG_RSP, R.UC_X86_REG_RAX, (R.UC_X86_REG_RDI, R.UC_X86_REG_RSI,
                                                                   R.UC_X86_REG_RDX), R.UC_X86_REG_RIP
    pages = sorted({pg for va, off, fsz, msz, flg in loads
                    for pg in range((base + va) & ~0xfff, (base + va + msz + 0xfff) & ~0xfff, 0x1000)})
    if not pages or len(pages) > (96 << 20) >> 12:
        return None
    run = [pages[0]]
    for pg in pages[1:] + [None]:
        if pg is not None and pg == run[-1] + 0x1000:
            run.append(pg)
            continue
        uc.mem_map(run[0], len(run) * 0x1000)
        if pg is not None:
            run = [pg]
    for va, off, fsz, msz, flg in loads:
        uc.mem_write(base + va, data[off:off + fsz])
    STUB, STK, HEAP, DONE = 0x7e000000, 0x7f000000, 0x7c000000, 0x7dfff000
    uc.mem_map(STK, 0x40000)
    uc.mem_map(HEAP, 0x100000)
    uc.mem_map(STUB, 0x10000, U.UC_PROT_READ)
    uc.mem_map(DONE, 0x1000, U.UC_PROT_READ)
    stubs = {}
    rel_t, imp_t = _CTOR_ARCH[183 if a64 else 62][1:]
    for ro, t, si, add in rels:
        try:
            if t == rel_t:
                uc.mem_write(base + ro, struct.pack("<Q", base + add))
            elif t in imp_t:
                slot = STUB + 16 * (len(stubs) % 0x1000)
                stubs[slot] = syms.get(si, "")
                uc.mem_write(base + ro, struct.pack("<Q", slot))
        except U.UcError:
            pass
    fb = [(base + va, fsz, off, flg) for va, off, fsz, msz, flg in loads if fsz]
    before = [bytes(uc.mem_read(a, n)) for a, n, _o, _f in fb]   # relocated load image: the diff baseline
    lo, hi = min(a for a, *_ in fb), max(a + n for a, n, *_ in fb)
    xlo, xhi = min(a for a, n, o, f in fb if f & 1), max(a + n for a, n, o, f in fb if f & 1)
    wrote, wpages, state = set(), set(), {"stop": "return", "extra": 0}

    def unmapped(uc, access, addr, size, value, ud):
        if access == U.UC_MEM_FETCH_UNMAPPED or state["extra"] >= 64:
            return False
        state["extra"] += 1
        try:
            uc.mem_map(addr & ~0xfff, 0x2000 if (addr & 0xfff) + size > 0x1000 else 0x1000)
        except U.UcError:
            return False
        return True

    def wr(uc, access, addr, size, value, ud):
        if len(wrote) < 1 << 20:
            wrote.update(range(addr, addr + size))
            wpages.add(addr & ~0xfff)

    def blk(uc, addr, size, ud):   # entering bytes main rewrote: the decrypted code, about to run
        if (addr & ~0xfff in wpages or (addr + size - 1) & ~0xfff in wpages) and \
                any(q in wrote for q in range(addr, addr + size)):
            state["stop"] = "exec-written"
            uc.emu_stop()

    def sysc(uc, ud):
        if uc.reg_read(R.UC_X86_REG_RAX) in (10, 329):   # mprotect / pkey_mprotect: granted
            uc.reg_write(R.UC_X86_REG_RAX, 0)
        else:
            uc.emu_stop()
    uc.hook_add(U.UC_HOOK_MEM_UNMAPPED, unmapped)
    uc.hook_add(U.UC_HOOK_MEM_WRITE, wr, None, lo, hi)
    uc.hook_add(U.UC_HOOK_BLOCK, blk, None, xlo, xhi)
    uc.hook_add(U.UC_HOOK_INTR, lambda uc, n, ud: uc.emu_stop())
    if not a64:
        uc.hook_add(U.UC_HOOK_INSN, sysc, None, 1, 0, U.x86_const.UC_X86_INS_SYSCALL)
        sp = STK + 0x30000 - 8
        uc.mem_write(sp, struct.pack("<Q", DONE))
    else:
        sp = STK + 0x30000
        uc.reg_write(R.UC_ARM64_REG_X30, DONE)
    uc.reg_write(SP, sp)
    _ctor_run(uc, U, R, a64, base + main, stubs, [HEAP], HEAP, DONE, SP, RET, ARGS, PC, end, smc=True)
    img, ranges, keys, total = bytearray(data), [], [], 0
    for (a, n, off, _f), old in zip(fb, before):
        new = bytes(uc.mem_read(a, n))
        if new == old:
            continue
        i = 0
        while i < n and total < SMC_MAX_PATCH:
            if new[i:i + 4096] == old[i:i + 4096]:
                i += 4096
                continue
            if new[i] == old[i]:
                i += 1
                continue
            j, gap = i, 0
            while j < n and gap < 16:   # one range across gaps < 16 unchanged bytes
                gap = gap + 1 if new[j] == old[j] else 0
                j += 1
            j -= gap
            img[off + i:off + j] = new[i:j]
            ranges.append((off + i, j - i, a + i - base))
            d = bytes(p ^ q for p, q in zip(new[i:j], data[off + i:off + j]))
            keys.append(next((d[:p] for p in range(1, 17)
                              if len(d) >= 2 * p and d == (d[:p] * (len(d) // p + 1))[:len(d)]), None))
            total += j - i
            i = j
    if not ranges:
        return None
    return {"image": bytes(img), "ranges": ranges, "main": main, "stopped": state["stop"], "keys": keys}


# --- custom bytecode VM (VMProtect-lite: an interpreter loop + opcode handlers + a bytecode blob whose program STORES the
# config) -----------------------------------------------------------------------------------------------------------
# No handler semantics are guessed: main() is emulated (unicorn, the smc_decrypt / constructor plumbing: import stubs
# malloc/memcpy/memset/strlen, others return 0) with every memory WRITE logged. The VM's output is recovered twice, from
# (a) a shadow of all written bytes where a later zero never erases an earlier non-zero (a wipe loop / memset after
# use), split into contiguous runs, and (b) the in-order log of single-byte stores (a buffer overwritten with junk).
# Each is scanned for a crc-valid HCFG (raw -> "vm-raw", any other encoding the program emitted -> "vm-<inner>").
# Cue (checked after the run): some basic block executed >= HCFG_VM_LOOP times (the dispatch loop) while main fetched a
# run of >= 16 file bytes one BYTE at a time (gaps < 16) from a non-exec segment (the bytecode). Offset = the first file byte of the longest
# such run (= the bytecode blob; SPECULATIVE), detail "vm program@<off>+<len> main@<va> loop=<max block hits>".
# Not covered: a VM that never runs from main() (gated on argv / input / a predicate) -- the day's worker handles it.
HCFG_VM_SECS = float(os.environ.get("HCTF_HCFG_VM_SECS", "0.3"))   # wall budget of the main() emulation
HCFG_VM_LOOP = 32
HCFG_VM_WRITES = 1 << 18   # logged write events per run


def vm_trace(data, *, budget=None):
    """Emulate main() of an x86-64 / AArch64 ELF64 and log what it stores. -> {"main", "program_offset",
    "program_size", "loop", "buffers": [bytes], "log": bytes} or None (not an ELF, no main, refused). Never raises."""
    try:
        import unicorn   # noqa: F401
        info = _elf_ctors(data)
        if not info:
            return None
        main = _smc_main(data, info)
        if main is None or info[6](main) is None:
            return None
        return _vm_emu(data, info, main, time.time() + (HCFG_VM_SECS if budget is None else budget))
    except Exception:   # noqa: BLE001 -- unicorn / hostile headers: never raise past the caller
        return None


def _vm_emu(data, info, main, end):
    import unicorn as U
    arch, base, loads, _tg, rels, syms, v2o = info[:7]
    a64 = arch == "aarch64"
    uc = U.Uc(U.UC_ARCH_ARM64, U.UC_MODE_ARM) if a64 else U.Uc(U.UC_ARCH_X86, U.UC_MODE_64)
    if a64:
        R = U.arm64_const
        SP, RET, ARGS, PC = R.UC_ARM64_REG_SP, R.UC_ARM64_REG_X0, (R.UC_ARM64_REG_X0, R.UC_ARM64_REG_X1,
                                                                     R.UC_ARM64_REG_X2), R.UC_ARM64_REG_PC
    else:
        R = U.x86_const
        SP, RET, ARGS, PC = R.UC_X86_REG_RSP, R.UC_X86_REG_RAX, (R.UC_X86_REG_RDI, R.UC_X86_REG_RSI,
                                                                   R.UC_X86_REG_RDX), R.UC_X86_REG_RIP
    pages = sorted({pg for va, off, fsz, msz, flg in loads
                    for pg in range((base + va) & ~0xfff, (base + va + msz + 0xfff) & ~0xfff, 0x1000)})
    if not pages or len(pages) > (96 << 20) >> 12:
        return None
    run = [pages[0]]
    for pg in pages[1:] + [None]:
        if pg is not None and pg == run[-1] + 0x1000:
            run.append(pg)
            continue
        uc.mem_map(run[0], len(run) * 0x1000)
        if pg is not None:
            run = [pg]
    for va, off, fsz, msz, flg in loads:
        uc.mem_write(base + va, data[off:off + fsz])
    STUB, STK, HEAP, DONE = 0x7e000000, 0x7f000000, 0x7c000000, 0x7dfff000
    uc.mem_map(STK, 0x40000)
    uc.mem_map(HEAP, 0x100000)
    uc.mem_map(STUB, 0x10000, U.UC_PROT_READ)
    uc.mem_map(DONE, 0x1000, U.UC_PROT_READ)
    stubs = {}
    rel_t, imp_t = _CTOR_ARCH[183 if a64 else 62][1:]
    for ro, t, si, add in rels:
        try:
            if t == rel_t:
                uc.mem_write(base + ro, struct.pack("<Q", base + add))
            elif t in imp_t:
                slot = STUB + 16 * (len(stubs) % 0x1000)
                stubs[slot] = syms.get(si, "")
                uc.mem_write(base + ro, struct.pack("<Q", slot))
        except U.UcError:
            pass
    ro = [(base + va, fsz, off) for va, off, fsz, msz, flg in loads if fsz and not flg & 1]
    xs = [(base + va, base + va + msz) for va, off, fsz, msz, flg in loads if flg & 1]
    shadow, log, reads, blocks, st = {}, bytearray(), set(), {}, {"n": 0, "extra": 0}

    def unmapped(uc, access, addr, size, value, ud):
        if access == U.UC_MEM_FETCH_UNMAPPED or st["extra"] >= 64:
            return False
        st["extra"] += 1
        try:
            uc.mem_map(addr & ~0xfff, 0x2000 if (addr & 0xfff) + size > 0x1000 else 0x1000)
        except U.UcError:
            return False
        return True

    def wr(uc, access, addr, size, value, ud):
        if st["n"] >= HCFG_VM_WRITES:
            return
        st["n"] += 1
        if size == 1:
            log.append(value & 0xff)
        for i in range(min(size, 16)):
            b = (value >> 8 * i) & 0xff
            if b or addr + i not in shadow:
                shadow[addr + i] = b

    def rd(uc, access, addr, size, value, ud):   # byte fetches only: the opcode stream, not a jump table's slots
        if size == 1 and len(reads) < 1 << 20:
            reads.update(range(addr, addr + size))

    def blk(uc, addr, size, ud):
        blocks[addr] = blocks.get(addr, 0) + 1

    uc.hook_add(U.UC_HOOK_MEM_UNMAPPED, unmapped)
    uc.hook_add(U.UC_HOOK_MEM_WRITE, wr)
    for a, n, _o in ro:
        uc.hook_add(U.UC_HOOK_MEM_READ, rd, None, a, a + n - 1)
    for lo, hi in xs:
        uc.hook_add(U.UC_HOOK_BLOCK, blk, None, lo, hi - 1)
    uc.hook_add(U.UC_HOOK_INTR, lambda uc, n, ud: uc.emu_stop())
    if not a64:
        uc.hook_add(U.UC_HOOK_INSN, lambda uc, ud: uc.emu_stop(), None, 1, 0, U.x86_const.UC_X86_INS_SYSCALL)
        sp = STK + 0x30000 - 8
        uc.mem_write(sp, struct.pack("<Q", DONE))
    else:
        sp = STK + 0x30000
        uc.reg_write(R.UC_ARM64_REG_X30, DONE)
    uc.reg_write(SP, sp)
    _ctor_run(uc, U, R, a64, base + main, stubs, [HEAP], HEAP, DONE, SP, RET, ARGS, PC, end)
    best, cur = (0, None), None
    for a in sorted(reads):   # one run across gaps < 16 unread bytes (operands / junk the program jumps over)
        cur = (cur[0], a) if cur and a - cur[1] <= 16 else (a, a)
        if cur[1] - cur[0] + 1 > best[0]:
            best = (cur[1] - cur[0] + 1, cur[0])
    prog = next((o + best[1] - a for a, n, o in ro if best[1] is not None and a <= best[1] < a + n), None)
    if prog is not None and 0 < prog & 15 <= 3 and all(data[prog & ~15:prog]):   # -O2 folded the first fetch(es) of
        best, prog = (best[0] + (prog & 15), best[1]), prog & ~15                  # a 16/32-aligned const array
    bufs, cur = [], None
    for a in sorted(shadow):
        if cur is not None and a == cur[0] + len(cur[1]):
            cur[1].append(shadow[a])
            continue
        if cur and len(cur[1]) >= 16:
            bufs.append(bytes(cur[1]))
        cur = (a, bytearray([shadow[a]]))
    if cur and len(cur[1]) >= 16:
        bufs.append(bytes(cur[1]))
    return {"main": main, "program_offset": prog, "program_size": best[0], "loop": max(blocks.values(), default=0),
            "buffers": bufs, "log": bytes(log)}


def _vm_scan(data, hits, emit, late):
    """hcfg_scan branch: config stored by a bytecode VM run from main() (see vm_trace)."""
    if data[:4] != b"\x7fELF" or late():
        return
    r = vm_trace(data)
    if not r or r["loop"] < HCFG_VM_LOOP or r["program_offset"] is None or r["program_size"] < 16:
        return
    det = f"vm program@{r['program_offset']}+{r['program_size']} main@{r['main']:#x} loop={r['loop']}"
    budget = 1 << 20
    for buf in sorted(r["buffers"], key=len, reverse=True) + [r["log"]]:
        if late() or budget <= 0:
            break
        budget -= len(buf)
        i = buf.find(HCFG_MAGIC)
        while i >= 0:
            blob = buf[i:i + _need(buf[i:i + 12])]
            if (_parse_blob(blob) or (0,) * 6)[5]:   # crc-valid only
                return emit(r["program_offset"], "vm-raw", blob, det)
            i = buf.find(HCFG_MAGIC, i + 1)
        if len(buf) > 1 << 18:
            continue
        for h in hcfg_scan(buf, stop_on_valid=True, _depth=1):
            if h.valid:
                h.offset, h.encoding = r["program_offset"], "vm-" + h.encoding
                h.detail = (det + " " + h.detail).strip()
                hits.append(h)
                return


def smc_facts(data):
    """Runtime-decryption facts (see smc_decrypt): decrypted_offset / decrypted_size / decrypted_vaddr (the largest
    rewritten range; "0x%x" vaddr), range_count, xor_key (repeating key hex of that range, "none" if not a plain
    repeating xor), stopped, main ("0x%x") -- all "none" when the image has no runtime self-decryption; None if not an
    ELF."""
    if data[:4] != b"\x7fELF":
        return None
    r = smc_decrypt(data)
    keys = ("decrypted_offset", "decrypted_size", "decrypted_vaddr", "range_count", "xor_key", "stopped", "main")
    if not r:
        return dict.fromkeys(keys, "none")
    k = max(range(len(r["ranges"])), key=lambda q: r["ranges"][q][1])
    off, n, va = r["ranges"][k]
    return {"decrypted_offset": off, "decrypted_size": n, "decrypted_vaddr": "0x%x" % va,
            "range_count": len(r["ranges"]), "xor_key": r["keys"][k].hex() if r["keys"][k] else "none",
            "stopped": r["stopped"], "main": "0x%x" % r["main"]}


def smc_field(data, name):
    try:
        f = smc_facts(data)
        return None if f is None else f.get(name.strip(), "none")
    except Exception:  # noqa: BLE001
        return None


def _rank(hits):
    """Best first. A NUL-delimited UTF-16 string reads as BOTH LE (at o) and BE (at o-1) with the same text: keep the
    reading that starts 2-byte aligned (compilers align wide strings), LE when both/neither are; the loser is dropped
    and named in the winner's detail."""
    by = {(h.offset, h.encoding): h for h in hits}
    for h in list(hits):
        if h.encoding.startswith("utf16le-"):
            be = by.get((h.offset - 1, "utf16be-" + h.encoding[8:]))
            if be is not None and be.plain == h.plain and be in hits:
                win, lose = (be, h) if (be.offset % 2 == 0 and h.offset % 2) else (h, be)
                hits.remove(lose)
                win.detail = (win.detail + " " if win.detail else "") + f"alt={lose.encoding}@{lose.offset}"
    return sorted(hits, key=lambda h: (not h.valid, h.speculative, h.offset))


def hcfg_find(data, **kw):
    """The first crc-valid HCFG blob (HcfgHit) in `data`, or None."""
    return next((h for h in hcfg_scan(data, stop_on_valid=True, **kw) if h.valid), None)


HCFG_ZIP_MAX = int(os.environ.get("HCTF_HCFG_ZIP_MAX", str(32 << 20)))   # inflated bytes over all zip entries
_ZIP_METHOD = {8: "deflate", 12: "bz2", 14: "lzma"}


def _zip_scan(data, emit, hits, deadline, late, depth):
    """Inflate every compressed non-.class entry of the zip in `data` and report an HCFG inside (see OFFSET LAW)."""
    try:
        zf = zipfile.ZipFile(io.BytesIO(data))
        infos = zf.infolist()[:20000]
    except Exception:  # noqa: BLE001 - not a (readable) zip
        return
    budget = HCFG_ZIP_MAX
    for zi in infos:
        if late() or budget <= 0:
            break
        if (zi.compress_type not in _ZIP_METHOD or zi.filename.endswith(("/", ".class")) or zi.file_size > budget
                or zi.file_size < 12):
            continue
        budget -= zi.file_size
        p = zi.header_offset
        if data[p:p + 4] != b"PK\x03\x04":
            continue
        dstart = p + 30 + int.from_bytes(data[p + 26:p + 28], "little") + int.from_bytes(data[p + 28:p + 30], "little")
        try:
            buf = zf.read(zi)
        except Exception:  # noqa: BLE001 - encrypted / corrupt / unsupported entry
            continue
        tag = f"zip={zi.filename}"
        i, n = buf.find(HCFG_MAGIC), 0
        while i >= 0 and n < 64:
            emit(dstart, _ZIP_METHOD[zi.compress_type], buf[i:i + _need(buf[i:i + 8])], f"at+{i} {tag}" if i else tag)
            i, n = buf.find(HCFG_MAGIC, i + 1), n + 1
        if any(h.valid for h in hits):
            return
        if len(buf) <= 4 << 20:
            for h in hcfg_scan(buf, deadline=deadline, stop_on_valid=True, _depth=depth + 1):
                if h.valid and h.encoding != "raw":
                    h.encoding, h.detail = "zip-" + h.encoding, f"{tag} data@{dstart} {h.detail}".strip()
                    hits.append(h)
                    return


# Erlang/Elixir BEAM (erts beam_file.c / beam_lib): 'FOR1' u32be size 'BEAM', then IFF chunks = 4-byte id, u32be size,
# data padded to 4. AtU8/Atom: u32be count (negative in OTP 28+ AtU8 = 16-bit-length atoms) + len-prefixed atoms
# (atom 1 = module name); ExpT/ImpT/LocT: u32be count + 3 x u32be each; LitT: u32be uncompressed size + zlib of
# [u32be count, (u32be len, external term format '\x83...')*] (size 0 = stored uncompressed); StrT: raw bytes.
def beam_chunks(data, base=0):
    """[(id str, data offset, size)] of the BEAM module at data[base:], or None (no FOR1/BEAM, chunk past end)."""
    try:
        if data[base:base + 4] != b"FOR1" or data[base + 8:base + 12] != b"BEAM":
            return None
        end = min(len(data), base + 8 + int.from_bytes(data[base + 4:base + 8], "big"))
        p, out = base + 12, []
        while p + 8 <= end and len(out) < 256:
            cid, n = bytes(data[p:p + 4]), int.from_bytes(data[p + 4:p + 8], "big")
            if not re.fullmatch(rb"[ -~]{4}", cid) or p + 8 + n > end:
                return out or None
            out.append((cid.decode(), p + 8, n))
            p += 8 + ((n + 3) & ~3)
        return out or None
    except _PARSE_ERR:
        return None


def beam_atoms(data, chunks=None, limit=100000):
    """Atom table of a BEAM module (atom 1 first = the module name), [] if absent/garbled."""
    chunks = chunks or beam_chunks(data) or []
    for cid, o, n in chunks:
        if cid in ("AtU8", "Atom"):
            try:
                cnt = int.from_bytes(data[o:o + 4], "big", signed=True)
                wide, cnt = cnt < 0, min(abs(cnt), limit)
                p, out = o + 4, []
                for _ in range(cnt):
                    ln = int.from_bytes(data[p:p + 2], "big") if wide else data[p]
                    p += 2 if wide else 1
                    if p + ln > o + n:
                        break
                    out.append(bytes(data[p:p + ln]).decode("utf-8", "replace"))
                    p += ln
                return out
            except _PARSE_ERR:
                return []
    return []


def beam_literals(data, chunks=None, cap=8 << 20):
    """(LitT data offset, decoded literal table bytes, compressed?) of a BEAM module, None without a LitT chunk."""
    for cid, o, n in chunks or beam_chunks(data) or []:
        if cid == "LitT" and n >= 4:
            usize = int.from_bytes(data[o:o + 4], "big")
            if usize == 0:
                return o, bytes(data[o + 4:o + n]), False
            try:
                d = zlib.decompressobj()
                return o, d.decompress(bytes(data[o + 4:o + n]), min(usize, cap)), True
            except zlib.error:
                return None
    return None


def beam_facts(data):
    """{format "beam", module, language erlang/elixir, atom_count, chunks, exports_count, imports_count,
    literals_count} for a BEAM module; escript (shebang + %%/%%! lines + zip/beam): {format "escript",
    archive_offset, emu_args, members}. None otherwise. Labels SPECULATIVE (not in the GM format enum yet)."""
    try:
        if data[:2] == b"#!" and b"escript" in bytes(data[:256]).split(b"\n", 1)[0]:
            p, emu = 0, "none"
            for _ in range(4):   # escript header: shebang, optional %% comment, optional %%! emu args
                q = data.find(b"\n", p)
                if q < 0:
                    return None
                line = bytes(data[p:q])
                if line.startswith(b"%%!"):
                    emu = line[3:].decode("utf-8", "replace").strip()
                p = q + 1
                if data[p:p + 4] in (b"PK\x03\x04", b"FOR1") or data[p:p + 1] not in (b"%", b"#"):
                    break
            kind = {b"PK\x03\x04": "zip", b"FOR1": "beam"}.get(bytes(data[p:p + 4]), "source")
            mem = []
            if kind == "zip":
                with zipfile.ZipFile(io.BytesIO(bytes(data))) as zf:
                    mem = [z.filename for z in zf.infolist()[:2000]]
            return {"format": "escript", "format_candidates": ["escript", "erlang_escript", "erlang"],
                    "machine": "none", "machine_num": "none", "endian": "none", "bits": "none",
                    "archive_kind": kind, "archive_offset": str(p), "emu_args": emu, "members": mem}
        ch = beam_chunks(data)
        if not ch:
            return None
        ids = {c[0]: c for c in ch}
        atoms = beam_atoms(data, ch)
        if not atoms:
            return None
        lit = beam_literals(data, ch)
        cnt = lambda k: str(int.from_bytes(data[ids[k][1]:ids[k][1] + 4], "big")) if k in ids else "none"
        return {"format": "beam", "format_candidates": ["beam", "erlang_beam", "erlang", "elixir"], "machine": "none",
                "machine_num": "none", "endian": "big", "bits": "none", "module": atoms[0],
                "language": "elixir" if atoms[0].startswith("Elixir.") or "ExCk" in ids or "Docs" in ids else "erlang",
                "atom_count": str(len(atoms)), "atoms": atoms[:5000], "chunks": [c[0] for c in ch],
                "exports_count": cnt("ExpT"), "imports_count": cnt("ImpT"), "locals_count": cnt("LocT"),
                "literals_count": str(int.from_bytes(lit[1][:4], "big")) if lit and len(lit[1]) >= 4 else "none",
                "litt_compressed": ("true" if lit[2] else "false") if lit else "none",
                "has_strt": "true" if "StrT" in ids else "false"}
    except (zipfile.BadZipFile, *_PARSE_ERR):
        return None


def _beam_scan(data, hits, deadline, late, depth):
    """Re-scan the inflated LitT literal table of every BEAM module in `data` (whole file or embedded) with the full
    hcfg_scan; a non-raw hit is reported as beam-<enc> at the LitT zlib stream start (first stored byte, OFFSET LAW),
    detail "litt+<offset in the inflated table> module=<name>". Stored (size 0) tables are plain bytes: already seen."""
    i, n = data.find(b"BEAM", 8), 0
    while i >= 8 and n < 64 and not late():
        n += 1
        ch = beam_chunks(data, i - 8)
        lit = beam_literals(data, ch) if ch else None
        if lit and lit[2] and len(lit[1]) >= 12:
            mod = (beam_atoms(data, ch) or ["?"])[0]
            for h in hcfg_scan(lit[1], deadline=deadline, stop_on_valid=True, _depth=depth + 1):
                if h.valid and h.encoding != "raw":
                    h.detail = f"litt+{h.offset} module={mod} {h.detail}".strip()
                    h.encoding, h.offset = "beam-" + h.encoding, lit[0] + 4
                    hits.append(h)
                    return
        i = data.find(b"BEAM", i + 1)


# .NET single-file bundle (`dotnet publish -p:PublishSingleFile=true`): an apphost (ELF / PE / Mach-O) whose data holds
# [i64 manifest offset][the 32-byte '.net core bundle' sha256 signature]; offset 0 = an unbundled apphost. Manifest (.NET
# runtime src/native/corehost/bundle/header.cpp): u32 major, u32 minor, i32 count, str bundle id, v2+: i64 deps offset/size,
# i64 runtimeconfig offset/size, u64 flags; then per file i64 offset, i64 size, v6+: i64 compressed size (0 = stored),
# u8 type, str path (str = 7-bit varint length + UTF-8). Compressed entries (EnableCompressionInSingleFile) = raw deflate.
_BUNDLE_SIG = bytes.fromhex("8b1202b96a612038727b930214d7a03213f5b9e6efae3318ee3b2dce24b36aae")
_BUNDLE_TYPES = {0: "unknown", 1: "assembly", 2: "native", 3: "deps_json", 4: "runtimeconfig_json", 5: "symbols"}
_BUNDLE_FW = re.compile(r"(System|Microsoft|netstandard|mscorlib|WindowsBase)[./]|.*\.(so|dylib|pdb)$")   # no deep scan
HCFG_BUNDLE_MAX = int(os.environ.get("HCTF_HCFG_BUNDLE_MAX", str(32 << 20)))   # inflated bytes over all bundle entries


def dotnet_bundle(data, limit=20000):
    """{"header_offset", "version" ("6.0"), "bundle_id", "flags", "files": [{path, type, offset, size, compressed_size}]}
    of a .NET single-file bundle (offset = file offset of the entry's stored bytes; compressed_size 0 = stored as is),
    None when `data` is no bundle (no signature / unbundled apphost placeholder / manifest out of range)."""
    data = bytes(data)
    s = data.find(_BUNDLE_SIG)
    while s >= 8:
        hdr = int.from_bytes(data[s - 8:s], "little")
        if 0 < hdr < len(data) - 12:
            break
        s = data.find(_BUNDLE_SIG, s + 1)
    else:
        return None
    p = [hdr]

    def u(fmt):
        v = struct.unpack_from(fmt, data, p[0])
        p[0] += struct.calcsize(fmt)
        return v[0] if len(v) == 1 else v

    def s7():
        n = sh = 0
        while True:
            b = data[p[0]]
            p[0] += 1
            n |= (b & 0x7f) << sh
            sh += 7
            if b < 0x80 or sh > 28:
                break
        if p[0] + n > len(data):
            raise ValueError("string past end")
        p[0] += n
        return data[p[0] - n:p[0]].decode("utf-8", "replace")

    try:
        major, minor, count = u("<IIi")
        if not 1 <= major <= 64 or not 0 <= count <= limit:
            return None
        out = {"header_offset": hdr, "version": f"{major}.{minor}", "bundle_id": s7(), "flags": 0, "files": []}
        if major >= 2:
            u("<qqqq")
            out["flags"] = u("<Q")
        for _ in range(count):
            off, size = u("<qq")
            csize = u("<q") if major >= 6 else 0
            typ = u("<B")
            path = s7()
            stored = csize or size
            if off < 0 or size < 0 or csize < 0 or off + stored > len(data):
                return None
            out["files"].append({"path": path, "type": _BUNDLE_TYPES.get(typ, str(typ)), "offset": off, "size": size,
                                 "compressed_size": csize})
        return out
    except _PARSE_ERR:
        return None


# ------------------------------------------------------------------ managed string decryptors (.NET IL / JVM bytecode)
# A static decryptor (ConfuserEx-style <Module> method, Base64+XOR, xor'd char/byte arrays, VB ChrW/AscW arithmetic;
# JVM static String a(String|int), ZKM-style xor tables) is called in place of ldstr/ldc, so the plain text (here: an
# HCFG blob in any text form) never sits in the file. managed_decrypted_strings() finds every static method taking
# string/int/byte[]/char[] and returning string, evaluates its body with a tiny bounded interpreter on each call site's
# constant arguments (static key tables come from running the owner's .cctor/<clinit> the same way), and returns
# [(stored offset, decryptor name, plain str)]; stored offset = the ciphertext's first stored byte (#US char data /
# FieldRVA array / CONSTANT_Utf8 bytes; the call instruction's file offset for int-only arguments).
MSDEC_MAX = 16 << 20        # input cap (class / jar: every app class is read before the sweep)
MSDEC_DOTNET_MAX = 4 << 20  # .NET PE cap: dnfile's full metadata parse is ~0.5 s/MB (18 MB Roslyn dll: 9.6 s)
MSDEC_TIME = 0.6            # wall-clock cap of one managed_decrypted_strings call (s)
MSDEC_DECRYPTORS = 16       # candidate decryptors evaluated (most call sites first)
MSDEC_STEPS = 400000        # interpreter steps over ALL call sites of one file
MSDEC_CALL_STEPS = 120000   # steps per decryptor call


class _MsArr(list):
    """A managed array: element size (bytes) + signedness drive stelem/ldelem truncation."""
    esz, sgn = 4, True


class _MsCh(int):
    """A char value (string concatenation renders it as the character, not its code)."""


class _MsAbort(Exception):
    pass


def _ms_w(v, bits=32, signed=True):
    v &= (1 << bits) - 1
    return v - (1 << bits) if signed and v >> (bits - 1) else v


def _ms_str(v):
    if isinstance(v, str):
        return v
    if isinstance(v, _MsCh):
        return chr(v)
    if v is None:
        return ""
    if isinstance(v, bool):
        return "True" if v else "False"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, list) and v and isinstance(v[0], str):   # StringBuilder
        return "".join(v)
    raise _MsAbort("str")


def _ms_copy(a):
    if not isinstance(a, _MsArr):
        return a
    r = _MsArr(a)
    r.esz, r.sgn = a.esz, a.sgn
    return r


def _ms_bytes(a):
    return bytes(x & 0xFF for x in a)


def _ms_chars(s):
    return _MsArr(_MsCh(ord(c)) for c in s)


_MS_ENC = {"get_UTF8": "utf-8", "get_ASCII": "ascii", "get_Unicode": "utf-16-le", "get_BigEndianUnicode": "utf-16-be",
           "get_Default": "utf-8", "get_Latin1": "latin-1", "get_UTF32": "utf-32-le"}


def _ms_extern(name, args, ptypes):
    """Known BCL / VB runtime / JDK calls (args in call order, `this` first). Returns (value, has_result)."""
    t, _, m = name.rpartition("::") if "::" in name else name.rpartition(".")
    a0 = args[0] if args else None
    if m in _MS_ENC and "Encoding" in t:
        return ("enc", _MS_ENC[m]), True
    if m == "GetString" and isinstance(a0, tuple):
        b = _ms_bytes(args[1])
        if len(args) == 4:
            b = b[args[2]:args[2] + args[3]]
        return b.decode(a0[1], "replace"), True
    if m == "GetBytes" and isinstance(a0, tuple):
        return _MsArr(_ms_str(args[1]).encode(a0[1], "replace")), True
    if m in ("FromBase64String", "decode") and ("Convert" in t or "Base64" in t):
        s = args[-1]
        s = _ms_bytes(s) if isinstance(s, list) else _ms_str(s).encode("latin-1", "replace")
        r = _MsArr(base64.b64decode(s + b"=" * (-len(s.rstrip(b"=")) % 4), validate=False))
        r.esz, r.sgn = 1, "java" in t
        return r, True
    if m in ("getDecoder", "getMimeDecoder", "getUrlDecoder") and "Base64" in t:
        return ("b64",), True
    if m in ("get_Length", "length", "Len") and isinstance(a0, (str, list)):
        return len(a0), True
    if m in ("get_Chars", "charAt"):
        return _MsCh(ord(_ms_str(a0)[args[1]])), True
    if m in ("ToCharArray", "toCharArray"):
        r = _ms_chars(_ms_str(a0))
        r.esz, r.sgn = 2, False
        return r, True
    if m == "getBytes" and isinstance(a0, str):
        r = _MsArr(a0.encode("utf-8"))
        r.esz = 1
        return r, True
    if m in ("Substring", "substring"):
        s = _ms_str(a0)
        if len(args) == 2:
            return s[args[1]:], True
        return (s[args[1]:args[1] + args[2]] if m == "Substring" else s[args[1]:args[2]]), True
    if m in ("ChrW", "Chr"):
        return _MsCh(args[0] & 0xFFFF), True
    if m in ("AscW", "Asc"):
        v = a0
        return (ord(v[0]) if isinstance(v, str) else int(v)), True
    if m == "StrReverse":
        return _ms_str(a0)[::-1], True
    if m in ("ToString", "valueOf", "toString", "intern", "copyValueOf") or (m == "Concat" and len(args) == 1):
        if isinstance(a0, list) and not (a0 and isinstance(a0[0], str)):
            return "".join(chr(c & 0xFFFF) for c in a0), True   # String.valueOf(char[])
        if ptypes and ptypes[0] in ("char", "C") and isinstance(a0, int):
            return chr(a0 & 0xFFFF), True
        return _ms_str(a0), True
    if m in ("Concat", "concat"):
        if len(args) == 1 and isinstance(a0, list):
            return "".join(_ms_str(x) for x in a0), True
        return "".join(chr(v & 0xFFFF) if p in ("char", "C") and isinstance(v, int) else _ms_str(v)
                       for v, p in zip(args, list(ptypes) + [""] * len(args))), True
    if m in ("Append", "append") and isinstance(a0, list):
        v = args[1]
        a0.append(chr(v & 0xFFFF) if ptypes and ptypes[0] in ("char", "C") and isinstance(v, int) else _ms_str(v))
        return a0, True
    if m in ("Reverse",) and isinstance(a0, list):
        a0.reverse()
        return None, False
    if m in ("InitializeArray",):
        arr, raw = args[0], args[1]
        if not (isinstance(arr, _MsArr) and isinstance(raw, bytes)):
            raise _MsAbort("initarr")
        w = arr.esz
        for i in range(min(len(arr), len(raw) // w)):
            arr[i] = int.from_bytes(raw[i * w:i * w + w], "little", signed=arr.sgn)
        return None, False
    raise _MsAbort(name)


class _MsVm:
    """Shared step budget + static-field store for one file."""
    def __init__(self, budget=MSDEC_STEPS, end=None):
        self.left, self.statics, self.inited = budget, {}, set()
        self.end = time.time() + MSDEC_TIME if end is None else end

    def tick(self, n=1):
        self.left -= n
        if self.left < 0 or time.time() > self.end:
            self.left = -1
            raise _MsAbort("budget")


# ----- .NET -----
_MS_ETYPE = {0x01: "void", 0x02: "bool", 0x03: "char", 0x04: "sbyte", 0x05: "byte", 0x06: "short", 0x07: "ushort", 0x08: "int",
             0x09: "uint", 0x0A: "long", 0x0B: "ulong", 0x0E: "string", 0x1C: "object", 0x18: "nint", 0x19: "nuint"}
_MS_ESZ = {"System.Byte": (1, False), "System.SByte": (1, True), "System.Char": (2, False), "System.Int16": (2, True),
           "System.UInt16": (2, False), "System.Int32": (4, True), "System.UInt32": (4, False),
           "System.Int64": (8, True), "System.UInt64": (8, False), "System.Boolean": (1, False)}


def _ms_sig_types(b):
    """Method sig blob -> (hasthis, [param type names], ret type name); arrays 'T[]', other types '?'."""
    p, cc = 1, b[0]
    n, p = _ms_cu(b, p)

    def one(p):
        e = b[p]
        if e == 0x1D:
            t, p = one(p + 1)
            return t + "[]", p
        if e in _MS_ETYPE:
            return _MS_ETYPE[e], p + 1
        if e in (0x11, 0x12):
            return "?", _ms_cu(b, p + 1)[1]
        raise _MsAbort("sig")
    ret, p = one(p)
    ps = []
    for _ in range(n):
        t, p = one(p)
        ps.append(t)
    return bool(cc & 0x20), ps, ret


def _ms_cu(b, p):
    x = b[p]
    if x < 0x80:
        return x, p + 1
    if x < 0xC0:
        return (x & 0x3F) << 8 | b[p + 1], p + 2
    return (x & 0x1F) << 24 | b[p + 1] << 16 | b[p + 2] << 8 | b[p + 3], p + 4


_MS_DEC_PARAMS = {"string", "int", "uint", "byte[]", "char[]", "long", "int[]"}


def _ms_dotnet(data, out, vm):
    import dnfile
    pe = dnfile.dnPE(data=data, fast_load=False)
    net = pe.net
    if net is None or net.mdtables is None:
        return
    t = net.mdtables
    rows = lambda tab: list(getattr(t, tab, None) or ())   # noqa: E731
    nm = lambda x: "" if x is None else str(x)   # noqa: E731
    blob = lambda x: bytes(getattr(x, "value", x) or b"")   # noqa: E731
    mds, tds, trs, flds, mrs = rows("MethodDef"), rows("TypeDef"), rows("TypeRef"), rows("Field"), rows("MemberRef")
    mowner, fowner = {}, {}
    for own, attr, total in ((mowner, "MethodList_Index", len(mds)), (fowner, "FieldList_Index", len(flds))):
        st = [int(getattr(r.struct, attr)) for r in tds]
        for k in range(len(tds)):
            for i in range(st[k], min(st[k + 1] if k + 1 < len(st) else total + 1, total + 1)):
                own[i] = k + 1

    def tname(c, tag_bits):
        tag, i = c & ((1 << tag_bits) - 1), c >> tag_bits
        if tag == 0 and 0 < i <= len(tds):
            r = tds[i - 1]
        elif tag == 1 and 0 < i <= len(trs):
            r = trs[i - 1]
        else:
            return "?"
        return (nm(r.TypeNamespace) + "." if nm(r.TypeNamespace) else "") + nm(r.TypeName)
    frva = {}
    for r in rows("FieldRva"):
        try:
            frva[int(r.struct.Field_Index)] = int(r.struct.Rva)
        except Exception:   # noqa: BLE001
            continue
    us = bytes(getattr(net.user_strings, "__data__", b"") or b"") if net.user_strings else b""
    us_off = data.find(us) if us else -1
    try:
        sigs = {i + 1: _ms_sig_types(blob(r.Signature)) for i, r in enumerate(mds) if blob(r.Signature)}
    except Exception:   # noqa: BLE001
        sigs = {}
    msig = {}

    def callee(tok):
        tab, i = tok >> 24, tok & 0xFFFFFF
        if tab == 0x06 and 0 < i <= len(mds):
            return ("md", i), sigs.get(i)
        if tab == 0x0A and 0 < i <= len(mrs):
            r = mrs[i - 1]
            c = int(r.struct.Class_CodedIndex)
            if c & 7 == 3:
                return callee(0x06000000 | c >> 3)
            if i not in msig:
                try:
                    msig[i] = _ms_sig_types(blob(r.Signature))
                except Exception:   # noqa: BLE001
                    msig[i] = None
            return tname(c, 3) + "::" + nm(r.Name), msig[i]
        return None, None

    def us_str(tok):
        i = tok & 0xFFFFFF
        n, p = _ms_cu(us, i)
        return us[p:p + (n & ~1)].decode("utf-16-le", "replace"), (us_off + p if us_off >= 0 else -1)

    def fdata(fi, n):
        rva = frva.get(fi)
        if rva is None:
            raise _MsAbort("fieldrva")
        return bytes(pe.get_data(rva, n)), pe.get_offset_from_rva(rva)
    bodies = {}

    def body(i, pats=None):
        if i not in bodies:
            rva = int(mds[i - 1].struct.Rva or 0) if 0 < i <= len(mds) else 0
            b = _il_body(pe, rva) if rva else None
            if b and pats is not None and not any(x in b["code"] for x in pats):
                return None   # sweep prefilter: no call to a candidate decryptor in this body
            if b:
                ins = il_decode(b["code"])
                b["ins"], b["at"] = ins, {o: k for k, (o, _, _) in enumerate(ins)}
                b["foff"] = pe.get_offset_from_rva(rva) + b["header_size"]
            bodies[i] = b
        return bodies[i]

    def newarr(tok, n):
        tab, i = tok >> 24, tok & 0xFFFFFF
        nmx = tname(i << 2 | (0 if tab == 2 else 1), 2) if tab in (1, 2) else "?"
        if not 0 <= n <= 1 << 20:
            raise _MsAbort("newarr")
        a = _MsArr([0] * n)
        a.esz, a.sgn = _MS_ESZ.get(nmx, (4, True))
        if nmx not in _MS_ESZ:
            a[:] = [None] * n
        return a

    def cctor(fi):
        k = fowner.get(fi)
        if not k or k in vm.inited:
            return
        vm.inited.add(k)
        for mi, own in mowner.items():
            if own == k and nm(mds[mi - 1].Name) == ".cctor":
                try:
                    run(mi, [], 0)
                except _MsAbort:
                    pass

    def run(mi, args, depth):
        b = body(mi)
        if not b or depth > 4:
            raise _MsAbort("body")
        ins, at = b["ins"], b["at"]
        loc, st, k, steps = {}, [], 0, MSDEC_CALL_STEPS
        args = list(args)
        pop = st.pop
        while True:
            steps -= 1
            if steps < 0 or k >= len(ins):
                raise _MsAbort("steps")
            if not steps & 255:
                vm.tick(256)
            o, op, arg = ins[k]
            k += 1
            if op == 0x00 or op in (0xFE16, 0xFE14):   # nop / constrained. / tail.
                continue
            if 0x02 <= op <= 0x05:
                st.append(args[op - 2])
            elif 0x06 <= op <= 0x09:
                st.append(loc.get(op - 6))
            elif 0x0A <= op <= 0x0D:
                loc[op - 0x0A] = pop()
            elif op in (0x0E, 0xFE09):
                st.append(args[arg])
            elif op in (0x10, 0xFE0B):
                args[arg] = pop()
            elif op in (0x11, 0xFE0C):
                st.append(loc.get(arg))
            elif op in (0x13, 0xFE0E):
                loc[arg] = pop()
            elif op == 0x14:
                st.append(None)
            elif 0x15 <= op <= 0x1E:
                st.append(op - 0x16)
            elif op in (0x1F, 0x20, 0x21):
                st.append(arg)
            elif op == 0x25:
                st.append(st[-1])
            elif op == 0x26:
                pop()
            elif op == 0x2A:
                return pop() if st else None
            elif 0x2B <= op <= 0x44:
                s = op - 0x2B if op < 0x38 else op - 0x38
                if s == 0:
                    go = True
                elif s in (1, 2):
                    v = pop()
                    go = bool(v) == (s == 2)
                else:
                    y, x = pop(), pop()
                    if s in (3, 8):
                        go = x == y if s == 3 else x != y
                    else:
                        if s >= 9:
                            x, y = x & 0xFFFFFFFFFFFFFFFF, y & 0xFFFFFFFFFFFFFFFF
                        go = {4: x >= y, 5: x > y, 6: x <= y, 7: x < y}[s - 5 if s >= 9 else s]
                if go:
                    tgt = ins[k][0] + arg if k < len(ins) else o + arg
                    if tgt not in at:
                        raise _MsAbort("branch")
                    k = at[tgt]
            elif op == 0x45:
                v = pop()
                if 0 <= v < len(arg):
                    tgt = (ins[k][0] if k < len(ins) else o) + arg[v]
                    k = at.get(tgt, -1)
                    if k < 0:
                        raise _MsAbort("switch")
            elif 0x46 <= op <= 0x4C or op == 0x71:   # ldind.* / ldobj on an element reference
                ref = pop()
                if not (isinstance(ref, tuple) and ref[0] == "ref"):
                    raise _MsAbort("ldind")
                st.append(ref[1][ref[2]])
            elif 0x52 <= op <= 0x55 or op == 0x81:   # stind.i1..i8 / stobj
                v, ref = pop(), pop()
                if not (isinstance(ref, tuple) and ref[0] == "ref"):
                    raise _MsAbort("stind")
                a = ref[1]
                a[ref[2]] = _ms_w(v, 8 * a.esz, a.sgn) if isinstance(v, int) else v
            elif 0x58 <= op <= 0x64 or 0xD6 <= op <= 0xDB:
                y, x = pop(), pop()
                if not (isinstance(x, int) and isinstance(y, int)):
                    raise _MsAbort("arith")
                b64 = abs(x) >= 1 << 32 or abs(y) >= 1 << 32
                bits = 64 if b64 else 32
                o2 = {0xD6: 0x58, 0xD7: 0x58, 0xD8: 0x5A, 0xD9: 0x5A, 0xDA: 0x59, 0xDB: 0x59}.get(op, op)
                if o2 == 0x58:
                    r = x + y
                elif o2 == 0x59:
                    r = x - y
                elif o2 == 0x5A:
                    r = x * y
                elif o2 in (0x5B, 0x5D, 0x5C, 0x5E):
                    if o2 in (0x5C, 0x5E):
                        x, y = x & ((1 << bits) - 1), y & ((1 << bits) - 1)
                    if y == 0:
                        raise _MsAbort("div0")
                    q = abs(x) // abs(y) * (1 if (x < 0) == (y < 0) else -1)
                    r = q if o2 in (0x5B, 0x5C) else x - q * y
                elif o2 == 0x5F:
                    r = x & y
                elif o2 == 0x60:
                    r = x | y
                elif o2 == 0x61:
                    r = x ^ y
                elif o2 == 0x62:
                    r = x << (y & (bits - 1))
                elif o2 == 0x63:
                    r = _ms_w(x, bits) >> (y & (bits - 1))
                else:
                    r = (x & ((1 << bits) - 1)) >> (y & (bits - 1))
                st.append(_ms_w(r, bits))
            elif op in (0x65, 0x66):
                x = pop()
                st.append(_ms_w(-x if op == 0x65 else ~x, 32 if abs(x) < 1 << 31 else 64))
            elif op in (0x67, 0x68, 0x69, 0x6A, 0x6D, 0x6E, 0xD1, 0xD2, 0xD3, 0xE0) or 0x82 <= op <= 0x8B or \
                    0xB3 <= op <= 0xBA or op in (0xD4, 0xD5):
                x = pop()
                if not isinstance(x, int):
                    raise _MsAbort("conv")
                cv = {0x67: (8, 1), 0x68: (16, 1), 0x69: (32, 1), 0x6A: (64, 1), 0x6D: (32, 0), 0x6E: (64, 0),
                      0xD1: (16, 0), 0xD2: (8, 0), 0xD3: (64, 1), 0xE0: (64, 0), 0xB3: (8, 1), 0xB4: (8, 0),
                      0xB5: (16, 1), 0xB6: (16, 0), 0xB7: (32, 1), 0xB8: (32, 0), 0xB9: (64, 1), 0xBA: (64, 0),
                      0x82: (8, 1), 0x83: (16, 1), 0x84: (32, 1), 0x85: (64, 1), 0x86: (8, 0), 0x87: (16, 0),
                      0x88: (32, 0), 0x89: (64, 0), 0x8A: (64, 1), 0x8B: (64, 0), 0xD4: (64, 1), 0xD5: (64, 0)}[op]
                st.append(_ms_w(x, cv[0], bool(cv[1])))
            elif op in (0x28, 0x6F, 0x73):
                c, sg = callee(arg)
                if sg is None:
                    raise _MsAbort("callsig")
                hasthis, ps, ret = sg
                n = len(ps) + (1 if hasthis and op != 0x73 else 0)
                cargs = st[len(st) - n:] if n else []
                del st[len(st) - n:]
                if isinstance(c, tuple):
                    v = run(c[1], cargs, depth + 1)
                    if ret != "void" and op != 0x73:
                        st.append(v)
                    continue
                if op == 0x73:
                    if c.endswith("String::.ctor") and cargs:
                        a = cargs[0]
                        if isinstance(a, list):
                            if len(cargs) == 3:
                                a = a[cargs[1]:cargs[1] + cargs[2]]
                            st.append("".join(chr(x & 0xFFFF) for x in a))
                        else:
                            st.append(chr(a & 0xFFFF) * cargs[1])
                    elif c.endswith("StringBuilder::.ctor"):
                        st.append([_ms_str(cargs[0])] if cargs and isinstance(cargs[0], str) else [])
                    else:
                        raise _MsAbort(c)
                    continue
                if c.endswith("::InitializeArray") and len(cargs) == 2 and isinstance(cargs[1], tuple):
                    a = cargs[0]
                    cargs = [a, fdata(cargs[1][1] & 0xFFFFFF, len(a) * a.esz)[0]]
                v, has = _ms_extern(c, cargs, ps)
                if ret == "char" and isinstance(v, int):
                    v = _MsCh(v)
                if has and ret != "void":
                    st.append(v)
            elif op == 0x72:
                st.append(us_str(arg)[0])
            elif op in (0x7E, 0x7F):
                fi = arg & 0xFFFFFF
                if fi not in vm.statics:
                    cctor(fi)
                if fi not in vm.statics:
                    raise _MsAbort("static")
                st.append(vm.statics[fi])
            elif op == 0x80:
                vm.statics[arg & 0xFFFFFF] = pop()
            elif op == 0x8D:
                st.append(newarr(arg, pop()))
            elif op == 0x8E:
                st.append(len(pop()))
            elif 0x90 <= op <= 0x9A or op == 0xA3:
                i, a = pop(), pop()
                v = a[i]
                if op in (0x91, 0x93, 0x95):
                    v = _ms_w(v, (8, 16, 32)[(op - 0x91) // 2], False)
                elif op in (0x90, 0x92, 0x94):
                    v = _ms_w(v, (8, 16, 32)[(op - 0x90) // 2], True)
                st.append(_MsCh(v) if op == 0x93 and a.esz == 2 and not a.sgn else v)
            elif 0x9C <= op <= 0xA2 or op == 0xA4:
                v, i, a = pop(), pop(), pop()
                a[i] = _ms_w(v, 8 * a.esz, a.sgn) if isinstance(v, int) and isinstance(a, _MsArr) and a[i] is not None \
                    else v
            elif op == 0x8F:
                i, a = pop(), pop()
                st.append(("ref", a, i))
            elif op == 0xD0:
                st.append(("tok", arg))
            elif op in (0x8C, 0xA5):   # box / unbox.any: values are untyped here
                continue
            elif 0xFE01 <= op <= 0xFE05:
                y, x = pop(), pop()
                if op in (0xFE03, 0xFE05) and isinstance(x, int) and isinstance(y, int):
                    x, y = x & 0xFFFFFFFFFFFFFFFF, y & 0xFFFFFFFFFFFFFFFF
                st.append(int(x == y if op == 0xFE01 else x > y if op in (0xFE02, 0xFE03) else x < y))
            else:
                raise _MsAbort(f"op {op:#x}")

    decs = {i for i, sg in sigs.items() if sg and not sg[0] and sg[2] == "string" and 1 <= len(sg[1]) <= 3
            and all(p in _MS_DEC_PARAMS for p in sg[1]) and int(mds[i - 1].struct.Rva or 0)}
    calls = {i: data.count(b"\x28" + (0x06000000 | i).to_bytes(4, "little")) for i in sorted(decs)[:4096]}
    decs = set(sorted((i for i in calls if calls[i]), key=lambda i: -calls[i])[:MSDEC_DECRYPTORS])
    pats = [b"\x28" + (0x06000000 | i).to_bytes(4, "little") for i in decs]
    if not decs:
        return
    for mi in range(1, len(mds) + 1):
        if vm.left <= 0 or time.time() > vm.end:
            break
        try:
            b = bodies[mi] if mi in bodies else body(mi, pats)
        except Exception:   # noqa: BLE001
            continue
        if not b:
            continue
        cs = []   # [(value, stored offset)] of the constant-argument producers seen so far (straight line)
        for o, op, arg in b["ins"]:
            try:
                if op == 0x72:
                    cs.append(us_str(arg))
                elif 0x15 <= op <= 0x1E or op in (0x1F, 0x20, 0x21):
                    cs.append((op - 0x16 if op <= 0x1E else arg, b["foff"] + o))
                elif op == 0x8D and cs and isinstance(cs[-1][0], int):
                    cs[-1] = (newarr(arg, cs[-1][0]), cs[-1][1])
                elif op == 0x25 and cs:
                    cs.append(cs[-1])
                elif op == 0xD0 and cs and isinstance(cs[-1][0], _MsArr):
                    a = cs[-1][0]
                    raw, foff = fdata(arg & 0xFFFFFF, len(a) * a.esz)
                    for j in range(min(len(a), len(raw) // a.esz)):
                        a[j] = int.from_bytes(raw[j * a.esz:j * a.esz + a.esz], "little", signed=a.sgn)
                    cs = [(v, foff if v is a else f) for v, f in cs]   # the dup'd copies too
                    cs.append(("tok", foff))
                elif op == 0x28 and cs and cs[-1][0] == "tok":
                    cs[-2:] = []   # InitializeArray(dup'd array, token): array filled above
                elif 0x9C <= op <= 0xA2 and len(cs) >= 3 and isinstance(cs[-3][0], _MsArr):
                    (v, _), (i, _) = cs.pop(), cs.pop()
                    a = cs.pop()[0]
                    a[i] = _ms_w(v, 8 * a.esz, a.sgn)
                elif op == 0x28 and (arg >> 24 == 6 and (arg & 0xFFFFFF) in decs):
                    n = len(sigs[arg & 0xFFFFFF][1])
                    if len(cs) < n:
                        cs = []
                        continue
                    args = [v for v, _ in cs[len(cs) - n:]]
                    off = next((f for v, f in cs[len(cs) - n:] if not isinstance(v, int)), cs[-n][1])
                    del cs[len(cs) - n:]
                    r = run(arg & 0xFFFFFF, [_ms_copy(a) for a in args], 0)
                    if isinstance(r, str) and r:
                        out.append((off, nm(mds[(arg & 0xFFFFFF) - 1].Name), r))
                        cs.append((r, off))
                else:
                    cs = []
            except (_MsAbort, IndexError, KeyError, TypeError, ValueError, OverflowError, AttributeError):
                cs = []


# ----- JVM -----
_MS_JDESC = re.compile(r"\[*(?:[BCDFIJSZV]|L[^;]+;)")


def _ms_jtypes(desc):
    """'(Ljava/lang/String;I)Ljava/lang/String;' -> (['String', 'I'], 'String')."""
    i = desc.index(")")
    nm = lambda t: t[t.rfind("/") + 1:-1] if t.startswith("L") else t   # noqa: E731
    return [nm(t) for t in _MS_JDESC.findall(desc[1:i])], nm(desc[i + 1:])


def _ms_jvm(data, cls, out, vm):
    cp, u = cls["cp"], cls["_u"]
    me = cls["this"]

    def ref(i):   # Fieldref/Methodref/InterfaceMethodref -> (class, name, descriptor)
        e = cp[i]
        c, nt = e[1]
        n, d = cp[nt][1]
        return u(cp[c][1]), u(n), u(d)
    meths = {}
    for m in cls["methods"]:
        code = next((b for n, b in m["attributes"] if n == "Code"), None)
        if code and len(code) >= 8:
            ln = struct.unpack_from(">I", code, 4)[0]
            meths[(m["name"], m["descriptor"])] = (m["access"], code[8:8 + ln])

    def const(i):
        e = cp[i] if 0 < i < len(cp) else None
        if not e:
            raise _MsAbort("cp")
        if e[0] == 8:
            return u(e[1])
        if e[0] in (3, 5):
            return e[1]
        raise _MsAbort("ldc")

    def clinit():
        if me in vm.inited:
            return
        vm.inited.add(me)
        if ("<clinit>", "()V") in meths:
            try:
                run(("<clinit>", "()V"), [], 0)
            except (_MsAbort, IndexError, KeyError, TypeError, ValueError, struct.error):
                pass

    def run(key, args, depth):
        if depth > 4 or key not in meths:
            raise _MsAbort("jbody")
        code = meths[key][1]
        loc = dict(enumerate(args))
        st, pc, steps = [], 0, MSDEC_CALL_STEPS
        pop = st.pop
        while True:
            steps -= 1
            if steps < 0:
                raise _MsAbort("steps")
            if not steps & 255:
                vm.tick(256)
            at, op = pc, code[pc]
            pc += 1
            if op == 0x00:
                continue
            if op == 0x01:
                st.append(None)
            elif 0x02 <= op <= 0x08:
                st.append(op - 3)
            elif op in (0x09, 0x0A):
                st.append(op - 9)
            elif op == 0x10:
                st.append(_ms_w(code[pc], 8))
                pc += 1
            elif op == 0x11:
                st.append(_ms_w(code[pc] << 8 | code[pc + 1], 16))
                pc += 2
            elif op == 0x12:
                st.append(const(code[pc]))
                pc += 1
            elif op in (0x13, 0x14):
                st.append(const(code[pc] << 8 | code[pc + 1]))
                pc += 2
            elif 0x15 <= op <= 0x19:
                st.append(loc.get(code[pc]))
                pc += 1
            elif 0x1A <= op <= 0x2D:
                st.append(loc.get((op - 0x1A) % 4))
            elif 0x2E <= op <= 0x35:
                i, a = pop(), pop()
                v = a[i]
                st.append(_MsCh(v) if op == 0x34 else v)
            elif 0x36 <= op <= 0x3A:
                loc[code[pc]] = pop()
                pc += 1
            elif 0x3B <= op <= 0x4E:
                loc[(op - 0x3B) % 4] = pop()
            elif 0x4F <= op <= 0x56:
                v, i, a = pop(), pop(), pop()
                a[i] = _ms_w(v, 8 * a.esz, a.sgn) if isinstance(v, int) and isinstance(a, _MsArr) else v
            elif op == 0x57:
                pop()
            elif op == 0x59:
                st.append(st[-1])
            elif op == 0x5C:
                st.extend(st[-2:])
            elif op == 0x5F:
                st[-1], st[-2] = st[-2], st[-1]
            elif 0x60 <= op <= 0x83 and op not in (0x74, 0x75, 0x76, 0x77):
                y, x = pop(), pop()
                bits = 64 if (op - 0x60) % 2 or (op >= 0x78 and (op - 0x78) % 2) else 32
                g = (op - 0x60) // 4 if op < 0x74 else None
                if g == 0:
                    r = x + y
                elif g == 1:
                    r = x - y
                elif g == 2:
                    r = x * y
                elif g in (3, 4):
                    if y == 0:
                        raise _MsAbort("div0")
                    q = abs(x) // abs(y) * (1 if (x < 0) == (y < 0) else -1)
                    r = q if g == 3 else x - q * y
                elif op in (0x78, 0x79):
                    r = x << (y & (bits - 1))
                elif op in (0x7A, 0x7B):
                    r = x >> (y & (bits - 1))
                elif op in (0x7C, 0x7D):
                    r = (x & ((1 << bits) - 1)) >> (y & (bits - 1))
                elif op in (0x7E, 0x7F):
                    r = x & y
                elif op in (0x80, 0x81):
                    r = x | y
                else:
                    r = x ^ y
                st.append(_ms_w(r, bits))
            elif op in (0x74, 0x75):
                st.append(_ms_w(-pop(), 32 if op == 0x74 else 64))
            elif op == 0x84:
                loc[code[pc]] = _ms_w(loc.get(code[pc], 0) + _ms_w(code[pc + 1], 8))
                pc += 2
            elif op in (0x85, 0x88):   # i2l / l2i
                st.append(_ms_w(pop(), 64 if op == 0x85 else 32))
            elif 0x91 <= op <= 0x93:
                v = pop()
                st.append(_ms_w(v, 8) if op == 0x91 else _MsCh(v & 0xFFFF) if op == 0x92 else _ms_w(v, 16))
            elif 0x99 <= op <= 0xA7 or op in (0xC6, 0xC7):
                d = _ms_w(code[pc] << 8 | code[pc + 1], 16)
                pc += 2
                if op == 0xA7:
                    go = True
                elif op in (0xC6, 0xC7):
                    go = (pop() is None) == (op == 0xC6)
                elif op <= 0x9E:
                    x = pop()
                    go = [x == 0, x != 0, x < 0, x >= 0, x > 0, x <= 0][op - 0x99]
                else:
                    y, x = pop(), pop()
                    go = [x == y, x != y, x < y, x >= y, x > y, x <= y, x is y, x is not y][op - 0x9F]
                if go:
                    pc = at + d
            elif 0xAC <= op <= 0xB0:
                return pop()
            elif op == 0xB1:
                return None
            elif op in (0xB2, 0xB3):
                c, n, d = ref(code[pc] << 8 | code[pc + 1])
                pc += 2
                k = (c, n)
                if op == 0xB3:
                    vm.statics[k] = pop()
                else:
                    if k not in vm.statics and c == me:
                        clinit()
                    if k not in vm.statics:
                        raise _MsAbort("jstatic")
                    st.append(vm.statics[k])
            elif op in (0xB6, 0xB7, 0xB8, 0xB9):
                c, n, d = ref(code[pc] << 8 | code[pc + 1])
                pc += 4 if op == 0xB9 else 2
                ps, ret = _ms_jtypes(d)
                cnt = len(ps) + (op != 0xB8)
                cargs = st[len(st) - cnt:] if cnt else []
                del st[len(st) - cnt:]
                if c == me and op == 0xB8 and (n, d) in meths:
                    v = run((n, d), cargs, depth + 1)
                elif n == "<init>":
                    obj = cargs[0]
                    if isinstance(obj, tuple) and obj[0] == "new":
                        v = ("".join(chr(x & 0xFFFF) for x in cargs[1]) if c == "java/lang/String" and ps == ["[C"]
                             else _ms_bytes(cargs[1]).decode("utf-8", "replace")
                             if c == "java/lang/String" and ps[:1] == ["[B"]
                             else [_ms_str(cargs[1])] if c == "java/lang/StringBuilder" and ps == ["String"]
                             else [] if c == "java/lang/StringBuilder" and not ps else _MsAbort)
                        if v is _MsAbort:
                            raise _MsAbort(c)
                        st[:] = [v if x is obj else x for x in st]
                    continue
                else:
                    v, has = _ms_extern(c.replace("/", ".") + "::" + n, cargs, ps)
                    if ret == "C" and isinstance(v, int):
                        v = _MsCh(v)
                if ret != "V":
                    st.append(v)
            elif op == 0xBB:
                pc += 2
                st.append(("new", at))
            elif op == 0xBC:
                n = pop()
                if not 0 <= n <= 1 << 20:
                    raise _MsAbort("newarray")
                a = _MsArr([0] * n)
                a.esz, a.sgn = {4: (1, False), 5: (2, False), 8: (1, True), 9: (2, True), 10: (4, True),
                                11: (8, True)}.get(code[pc], (4, True))
                pc += 1
                st.append(a)
            elif op == 0xBD:
                pc += 2
                n = pop()
                if not 0 <= n <= 1 << 20:
                    raise _MsAbort("anewarray")
                st.append(_MsArr([None] * n))
            elif op == 0xBE:
                st.append(len(pop()))
            elif op == 0xC0:   # checkcast
                pc += 2
            else:
                raise _MsAbort(f"jop {op:#x}")

    decs = {k for k, (acc, _) in meths.items() if acc & 0x8 and k[1].endswith(")Ljava/lang/String;")
            and 1 <= len(_ms_jtypes(k[1])[0]) <= 3 and all(t in ("String", "I", "[B", "[C", "J", "[I")
                                                           for t in _ms_jtypes(k[1])[0])}
    if not decs:
        return
    for key, (acc, code) in meths.items():
        if vm.left <= 0:
            break
        cs, pc = [], 0
        try:
            while pc < len(code) and vm.left > 0:
                op = code[pc]
                if op in (0x12, 0x13):
                    i = code[pc + 1] if op == 0x12 else code[pc + 1] << 8 | code[pc + 2]
                    v = const(i)
                    raw = _jmutf8(v) if isinstance(v, str) else b""
                    f = data.find(len(raw).to_bytes(2, "big") + raw) if raw else -1
                    cs.append((v, f + 2 if f >= 0 else -1))
                elif 0x02 <= op <= 0x08 or op in (0x10, 0x11):
                    cs.append((op - 3 if op <= 8 else _ms_w(code[pc + 1], 8) if op == 0x10
                               else _ms_w(code[pc + 1] << 8 | code[pc + 2], 16), -1))
                elif op == 0xB8:
                    c, n, d = ref(code[pc + 1] << 8 | code[pc + 2])
                    if c == me and (n, d) in decs:
                        k = len(_ms_jtypes(d)[0])
                        if len(cs) >= k:
                            args = [v for v, _ in cs[len(cs) - k:]]
                            off = next((f for v, f in cs[len(cs) - k:] if f >= 0), -1)
                            del cs[len(cs) - k:]
                            try:
                                r = run((n, d), args, 0)
                            except (_MsAbort, IndexError, KeyError, TypeError, ValueError, AttributeError):
                                r = None
                            if isinstance(r, str) and r:
                                out.append((off, n, r))
                                cs.append((r, off))
                        else:
                            cs = []
                    else:
                        cs = []
                else:
                    cs = []
                pc += _jop_len(code, pc)
        except (_MsAbort, IndexError, KeyError, TypeError, ValueError, struct.error):
            continue


def _jmutf8(s):
    """Modified UTF-8 (JVMS 4.4.7) of a str."""
    out = bytearray()
    for c in s:
        o = ord(c)
        units = [o] if o < 0x10000 else [0xD800 + ((o - 0x10000) >> 10), 0xDC00 + ((o - 0x10000) & 0x3FF)]
        for x in units:
            if 0 < x < 0x80:
                out.append(x)
            elif x < 0x800:
                out += bytes((0xC0 | x >> 6, 0x80 | x & 0x3F))
            else:
                out += bytes((0xE0 | x >> 12, 0x80 | x >> 6 & 0x3F, 0x80 | x & 0x3F))
    return bytes(out)


_JOP_LEN = {**{o: 2 for o in (0x10, 0x12, 0x15, 0x16, 0x17, 0x18, 0x19, 0x36, 0x37, 0x38, 0x39, 0x3A, 0xA9, 0xBC)},
            **{o: 3 for o in (0x11, 0x13, 0x14, 0x84, *range(0x99, 0xA9), 0xB2, 0xB3, 0xB4, 0xB5, 0xB6, 0xB7, 0xB8,
                              0xBB, 0xBD, 0xC0, 0xC1, 0xC6, 0xC7)},
            0xC5: 4, 0xB9: 5, 0xBA: 5, 0xC8: 5, 0xC9: 5}


def _jop_len(code, pc):
    op = code[pc]
    if op in (0xAA, 0xAB):   # tableswitch / lookupswitch: 4-byte aligned
        p = (pc + 4) & ~3
        if op == 0xAA:
            lo, hi = struct.unpack_from(">ii", code, p + 4)
            return p + 12 + 4 * (hi - lo + 1) - pc
        n = struct.unpack_from(">i", code, p + 4)[0]
        return p + 8 + 8 * n - pc
    if op == 0xC4:
        return 6 if code[pc + 1] == 0x84 else 4
    return _JOP_LEN.get(op, 1)


def managed_decrypted_strings(data, *, budget=MSDEC_STEPS, deadline=None):
    """[(stored offset, decryptor method name, plain str)] for every call of a static string decryptor in a .NET PE,
    a .class or a jar's application classes (see the section comment). [] when none / not managed / unreadable."""
    out = []
    try:
        data = bytes(data)
        if len(data) > MSDEC_MAX:
            return out
        vm = _MsVm(budget)
        if deadline is not None:
            vm.end = min(vm.end, deadline)
        if data[:4] == b"\xca\xfe\xba\xbe":
            cls = classfile_parse(data)
            if cls:
                _ms_jvm(data, cls, out, vm)
        elif data[:2] == b"MZ" and len(data) <= MSDEC_DOTNET_MAX and b"BSJB" in data:
            _ms_dotnet(data, out, vm)
        elif data[:2] == b"PK" and b".class" in data:
            for name, cb in jar_app_classes(data)[:4096]:
                if vm.left <= 0 or time.time() > vm.end:
                    break
                if b")Ljava/lang/String;" not in cb:
                    continue
                cls = classfile_parse(cb)
                if cls:
                    sub = []
                    _ms_jvm(cb, cls, sub, vm)
                    out += [(o, f"{name}:{n}", r) for o, n, r in sub]   # o: offset inside the class entry
    except Exception:   # noqa: BLE001 -- hostile tables / truncated input: whatever decoded so far
        pass
    return out


def _msdec_scan(data, hits, deadline, depth):
    """hcfg_scan branch: HCFG text/raw forms inside the strings a managed decryptor returns (encoding 'managed-<inner>',
    offset = the ciphertext's first stored byte, detail = 'decryptor=<method>')."""
    for off, name, s in managed_decrypted_strings(data, deadline=_ends(deadline)):
        try:
            b = s.encode("latin-1")
        except UnicodeEncodeError:
            b = s.encode("utf-8")
        if b"HCFG" not in b and len(b) < 16:
            continue
        for h in hcfg_scan(b, deadline=deadline, stop_on_valid=True, _depth=depth + 1):
            h.offset, h.encoding = off, "managed-" + h.encoding
            h.detail, h.speculative = (f"decryptor={name} " + h.detail).strip(), True
            hits.append(h)
            if h.valid:
                return


def _bundle_scan(data, emit, hits, deadline, late, depth):
    """Inflate every compressed entry of the .NET single-file bundle in `data` and report an HCFG inside: raw -> "deflate"
    at the entry's compressed-data start, detail "at+N bundle=<path>"; any other form -> "bundle-<enc>" at the offset
    INSIDE the inflated entry, detail "bundle=<path> data@<compressed start>" (the zip-entry convention, OFFSET LAW)."""
    b = dotnet_bundle(data)
    budget = HCFG_BUNDLE_MAX
    for f in (b or {}).get("files", ()):
        if late() or budget <= 0:
            break
        if not f["compressed_size"] or f["size"] < 12 or f["size"] > budget:
            continue
        budget -= f["size"]
        try:
            d = zlib.decompressobj(-15)
            buf = d.decompress(data[f["offset"]:f["offset"] + f["compressed_size"]], f["size"])
        except zlib.error:
            continue
        tag, dstart = f"bundle={f['path']}", f["offset"]
        i, n = buf.find(HCFG_MAGIC), 0
        while i >= 0 and n < 64:
            emit(dstart, "deflate", buf[i:i + _need(buf[i:i + 8])], f"at+{i} {tag}" if i else tag)
            i, n = buf.find(HCFG_MAGIC, i + 1), n + 1
        if any(h.valid for h in hits):
            return
        if len(buf) <= 8 << 20 and f["type"] != "native" and not _BUNDLE_FW.match(f["path"]):   # app entries only
            for h in hcfg_scan(buf, deadline=deadline, stop_on_valid=True, _depth=depth + 1):
                if h.valid and h.encoding != "raw":
                    h.encoding, h.detail = "bundle-" + h.encoding, f"{tag} data@{dstart} {h.detail}".strip()
                    hits.append(h)
                    return


_R2R_OS_XOR = {"windows": 0, "linux": 0x7B79, "osx": 0x4644, "freebsd": 0xADC4, "netbsd": 0x1993, "sunos": 0x1992}
_AOT_SECTIONS = {"__managedcode", ".managedcode", "__modules", ".dotnet_eh_table", ".hydrated", "hydrated", ".managed"}


def dotnet_build_facts(data):
    """How a .NET program was published, from the bytes alone: {"format" (container label: "elf" / "pe" / "mach-o", or
    "pe_cli" for a CLI assembly -- a ReadyToRun dll is still pe_cli), "dotnet_build": "singlefile" (apphost + bundle) |
    "apphost" (unbundled host) | "readytorun" (CLI header flag IL_LIBRARY + ManagedNativeHeader 'RTR') | "il" (plain CLI)
    | "nativeaot" (native image: __managedcode/__modules/hydrated sections, no CLI header) | "none"; R2R adds r2r_os +
    the real machine/machine_num (the header's Machine is xor'd with an OS cookie); "main_assembly" /
    "main_assembly_offset" / "bundle_version" / "bundle_files" for a bundle}; None when not an ELF / PE / Mach-O."""
    data = bytes(data)
    mf = machine_facts(data)
    if not mf or mf.get("format") not in ("elf", "pe", "mach-o"):
        return None
    out = {"format": mf["format"], "dotnet_build": "none"}
    pe = _pe_layout(data) if mf["format"] == "pe" else None
    if pe and len(pe[2]) > 14 and pe[2][14][0]:
        out["format"] = "pe_cli"
        try:
            cli = _pe_rva(pe[1], pe[2][14][0])
            flags = struct.unpack_from("<I", data, cli + 16)[0]
            mnh = struct.unpack_from("<I", data, cli + 64)[0]
            mo = _pe_rva(pe[1], mnh) if mnh else None
            r2r = mo is not None and data[mo:mo + 4] == b"RTR\0"
        except _PARSE_ERR:
            flags, r2r = 0, False
        out["dotnet_build"] = "readytorun" if r2r or flags & 0x4 else "il"
        if out["dotnet_build"] == "readytorun":   # crossgen2 stores Machine ^ per-OS cookie (Windows: plain Machine)
            m = int(mf["machine_num"])
            for osn, x in _R2R_OS_XOR.items():
                if (m ^ x) in PE_MACHINE_LABEL:
                    out.update({"r2r_os": osn, "machine": PE_MACHINE_LABEL[m ^ x], "machine_num": str(m ^ x)})
                    break
        return out
    b = dotnet_bundle(data)
    if b:
        asm = [f for f in b["files"] if f["type"] == "assembly"]
        main = b["bundle_id"] and asm and asm[0]
        for f in asm:   # the app's own dll is named like the runtimeconfig.json/deps.json entries
            stem = f["path"].rsplit(".", 1)[0]
            if any(g["path"] in (stem + ".runtimeconfig.json", stem + ".deps.json") for g in b["files"]):
                main = f
                break
        out.update({"dotnet_build": "singlefile", "bundle_version": b["version"], "bundle_files": len(b["files"]),
                    "main_assembly": main["path"] if main else "none",
                    "main_assembly_offset": main["offset"] if main else None,
                    "main_assembly_compressed": bool(main and main["compressed_size"])})
        return out
    if _BUNDLE_SIG in data:
        out["dotnet_build"] = "apphost"
        return out
    if pe:
        names = {n for n, *_ in pe[1]}
    elif mf["format"] == "elf":
        names = {n for n, _, _ in (_elf_layout(data) or (0, []))[1]}
    else:
        names = set((macho_layout(data) or {}).get("section_names_short") or ())
    if names & _AOT_SECTIONS:
        out["dotnet_build"] = "nativeaot"
    return out


# .NET metadata facts (d03 family: a plain IL dll/exe). Lists are compact JSON in metadata TABLE order, names exactly as
# stored (`<Module>`, `<PrivateImplementationDetails>`, nested `__StaticArrayInitTypeSize=N`, `.ctor`/`.cctor` kept).
_DN_ATTR_FACTS = {"TargetFrameworkAttribute": "target_framework", "AssemblyFileVersionAttribute": "file_version",
                  "AssemblyInformationalVersionAttribute": "informational_version", "AssemblyTitleAttribute": "title",
                  "AssemblyCompanyAttribute": "company", "AssemblyProductAttribute": "product",
                  "AssemblyConfigurationAttribute": "configuration", "AssemblyDescriptionAttribute": "description",
                  "AssemblyCopyrightAttribute": "copyright", "GuidAttribute": "guid_attribute"}
_DN_TFM = {".NETCoreApp": "net", ".NETFramework": "net", ".NETStandard": "netstandard"}


def _dn_serstr(blob):
    """First fixed arg of a custom-attribute blob when it is a SerString (prolog 01 00, compressed len, UTF-8)."""
    if len(blob) < 3 or blob[:2] != b"\x01\x00" or blob[2] == 0xFF:
        return None
    n, p = blob[2], 3
    if n & 0x80:
        n, p = (((n & 0x3F) << 8) | blob[3], 4) if not n & 0x40 else (((n & 0x1F) << 24) | int.from_bytes(blob[3:6], "big"), 6)
    return blob[p:p + n].decode("utf-8", "replace") if p + n <= len(blob) else None


def _dn_tfm(tf):
    """'.NETCoreApp,Version=v10.0' -> 'net10.0'; '.NETFramework,Version=v4.7.2' -> 'net472'; netstandard2.0."""
    m = re.match(r"(\.NET\w+),Version=v(\d+(?:\.\d+)*)$", tf or "")
    if not m or m.group(1) not in _DN_TFM:
        return "none"
    v = m.group(2)
    return "net" + v.replace(".", "") if m.group(1) == ".NETFramework" else _DN_TFM[m.group(1)] + v


def dotnet_meta_facts(data):
    """ECMA-335 metadata facts of a .NET (CLI) PE via dnfile: assembly_name / assembly_version (a.b.c.d) / assembly_culture,
    module_name, mvid (lowercase dashed guid), runtime_version (metadata 'v4.0.30319'), typedefs / typedefs_full
    (Namespace.Name) / typedef_count, methods / method_count, fields / field_count, field_rva_count / has_field_rva
    ("true"/"false"), entry_point_token ("0x06000001", "none" for a library), entry_point (Namespace.Type.Method),
    assembly_refs, target_framework ('.NETCoreApp,Version=v10.0') + tfm ('net10.0', the runtimeconfig form), and the
    assembly-level string attributes (file_version, informational_version, title, company, product, configuration, ...).
    All values are strings; absent -> "none". None when the bytes are not a CLI assembly."""
    try:
        import dnfile
        pe = dnfile.dnPE(data=bytes(data), fast_load=False)
        net = pe.net
        if net is None or net.mdtables is None:
            return None
        t = net.mdtables
    except Exception:   # noqa: BLE001 -- hostile/truncated PE: cannot answer
        return None
    out = {}
    js = lambda xs: json.dumps(list(xs), separators=(",", ":"), ensure_ascii=False)   # noqa: E731
    rows = lambda tab: list(getattr(t, tab, None) or ())   # noqa: E731

    def nm(x):
        return "" if x is None else str(x)

    def step(key, fn):
        try:
            out[key] = fn()
        except Exception:   # noqa: BLE001 -- one broken table must not hide the others
            out.setdefault(key, "none")
    asm = rows("Assembly")
    a = asm[0] if asm else None
    step("assembly_name", lambda: nm(a.Name) if a else "none")
    step("assembly_version", lambda: f"{a.MajorVersion}.{a.MinorVersion}.{a.BuildNumber}.{a.RevisionNumber}" if a else "none")
    step("assembly_culture", lambda: (nm(a.Culture) or "none") if a else "none")
    mods = rows("Module")
    step("module_name", lambda: nm(mods[0].Name) if mods else "none")
    step("mvid", lambda: str(mods[0].Mvid).lower() if mods and mods[0].Mvid is not None else "none")
    step("runtime_version", lambda: bytes(net.metadata.struct.Version).split(b"\0")[0].decode("ascii", "replace") or "none")
    tds = rows("TypeDef")
    full = [(nm(r.TypeNamespace) + "." if nm(r.TypeNamespace) else "") + nm(r.TypeName) for r in tds]
    step("typedefs", lambda: js(nm(r.TypeName) for r in tds))
    step("typedefs_full", lambda: js(full))
    out["typedef_count"] = str(len(tds))
    mds = rows("MethodDef")
    step("methods", lambda: js(nm(r.Name) for r in mds))
    out["method_count"] = str(len(mds))
    fds = rows("Field")
    step("fields", lambda: js(nm(r.Name) for r in fds))
    out["field_count"] = str(len(fds))
    rv = [r for r in rows("FieldRva") if getattr(r, "Rva", 0)]
    out["field_rva_count"] = str(len(rv))
    out["has_field_rva"] = "true" if rv else "false"
    step("assembly_refs", lambda: js(nm(r.Name) for r in rows("AssemblyRef")))

    def us_heap():   # #US: [compressed len][UTF-16LE][1 trailing flag byte]; empty entries skipped
        h, p, got = bytes(getattr(net.user_strings, "__data__", b"") or b""), 1, []
        while p < len(h) and len(got) < 20000:
            n, q = h[p], p + 1
            if n & 0x80:
                n, q = (((n & 0x3F) << 8) | h[p + 1], p + 2) if not n & 0x40 else \
                    (((n & 0x1F) << 24) | int.from_bytes(h[p + 1:p + 4], "big"), p + 4)
            if n == 0 and h[p] == 0:
                break   # zero padding at the end of the heap
            if n > 1:
                got.append(h[q:q + n - 1].decode("utf-16-le", "replace"))
            p = q + n
        return js(got)
    step("user_strings", us_heap)

    def entry():
        tok = int(net.struct.EntryPointTokenOrRva or 0)
        if not tok or net.Flags.CLR_NATIVE_ENTRYPOINT:
            out["entry_point_token"] = "none" if not tok else f"0x{tok:08x}"
            return "none"
        out["entry_point_token"] = f"0x{tok:08x}"
        idx = tok & 0xFFFFFF
        if tok >> 24 != 6 or not 0 < idx <= len(mds):
            return "none"
        owner = None   # dnfile expands each TypeDef's MethodList run (ECMA-335 II.22.37)
        for i, r in enumerate(tds):
            if r.MethodList and any(x.row_index == idx for x in r.MethodList):
                owner = full[i]
                break
        return f"{owner}.{nm(mds[idx - 1].Name)}" if owner else nm(mds[idx - 1].Name)
    out["entry_point_token"] = "none"
    step("entry_point", entry)
    for k in _DN_ATTR_FACTS.values():
        out[k] = "none"
    try:
        for ca in rows("CustomAttribute"):
            par, ty = ca.Parent, ca.Type
            if not par or not ty or getattr(par.table, "name", "") != "Assembly":
                continue
            r = ty.row
            cls = getattr(r, "Class", None) if getattr(ty.table, "name", "") == "MemberRef" else None
            tn = nm(getattr(cls.row, "TypeName", None)) if cls is not None and cls.row is not None else ""
            key = _DN_ATTR_FACTS.get(tn)
            if key and out[key] == "none":
                v = _dn_serstr(bytes(ca.Value.value or b""))
                if v is not None:
                    out[key] = v
    except Exception:   # noqa: BLE001
        pass
    out["tfm"] = _dn_tfm(out["target_framework"])
    return out


_DN_FIELD_ALIASES = {"name": "assembly_name", "version": "assembly_version", "types": "typedefs",
                     "type_names": "typedefs", "typedef_names": "typedefs", "type_count": "typedef_count",
                     "method_names": "methods", "methoddef_names": "methods", "field_names": "fields",
                     "entry_point_token_hex": "entry_point_token", "entrypoint_token": "entry_point_token",
                     "target_framework_moniker": "tfm", "runtimeconfig_tfm": "tfm", "module_mvid": "mvid"}


def dotnet_meta_field(data, name):
    """One dotnet_meta_facts value by name (aliases: version, types, method_names, ...); "none" when the field is absent,
    None when `data` is not a CLI assembly or the name is unknown."""
    f = dotnet_meta_facts(data)
    if f is None:
        return None
    k = _DN_FIELD_ALIASES.get(name, name)
    if k not in f:   # P/Invoke bridge fields (pinvoke_count, native_modules, <method>_module, ...)
        return (dotnet_pinvoke_facts(data) or {}).get(k)
    return f[k]


_FS_CLOSURE = re.compile(r"@\d+(?:-\d+)*$")   # F# closure / inner-lambda class: main@10, main@10-3, fs@7
_DN_LANG_ALIASES = {"dotnet_language": "language", "lang": "language", "fsharp_core": "fsharp_core_version",
                    "fsharp_core_ref_version": "fsharp_core_version_ref", "closures_count": "closure_count",
                    "anonymous_type_count": "anon_type_count", "fsharp_resource_names": "fsharp_resources"}


def dotnet_language_of(data):
    """Source language of a .NET (CLI) assembly from its ECMA-335 metadata (dnfile) -> {language: csharp / fsharp /
    vbnet / cppcli, evidence [..], confidence "compiler" (compiler-emitted artifacts) / "reference" (AssemblyRef only) /
    "default", + language facts}. Compiler artifacts win over references (a C# app may reference FSharp.Core):
      F#   <StartupCode$asm> namespaces + `$Module` types, FSharpSignature*/FSharpOptimization*Data.<asm> resources,
           closures `name@<line>[-n]`, <PrivateImplementationDetails$asm>; ref FSharp.Core
      VB   _Closure$__ / VB$AnonymousType_ / VB$StateMachine_ types, $VB$Local_ / $VB$Me fields, _Lambda$__ methods,
           `My` namespace (MyProject / MyApplication); ref Microsoft.VisualBasic[.Core]
      C++/CLI  <CrtImplementationDetails> namespace, COR flags without ILONLY (mixed mode); ref Microsoft.VisualC
      C#   default; <>c / <>c__DisplayClass closures, <Main>$ top-level statements.
    facts: assembly_name, assembly_version, assembly_refs, fsharp_core_version_ref (FSharp.Core AssemblyRef a.b.c.d),
    fsharp_core_version_def (AssemblyDef version when the member IS FSharp.Core.dll), fsharp_core_version (ref, else
    def), fsharp_resources / fsharp_resource_count, startup_code (the <StartupCode$X> X), vb_runtime_ref / vb_runtime_version,
    vb_my_namespace, vb_local_fields, closures / closure_count, anon_types / anon_type_count, il_only, scripting_host
    (ironpython / powershell / none). Lists stay lists; absent -> "none". None when not a CLI assembly; never raises."""
    try:
        import dnfile
        pe = dnfile.dnPE(data=bytes(data), fast_load=True, clr_lazy_load=True)   # rows on demand: FSharp.Core 1.2 s -> ~0.1 s
        pe.parse_data_directories(directories=[14])
        net = pe.net
        if net is None or net.mdtables is None:
            return None
        t = net.mdtables
        rows = lambda tab: list(getattr(t, tab, None) or ())   # noqa: E731
        nm = lambda x: "" if x is None else str(x)   # noqa: E731
        ver = lambda r: f"{r.MajorVersion}.{r.MinorVersion}.{r.BuildNumber}.{r.RevisionNumber}"   # noqa: E731
        asm = rows("Assembly")
        aname = nm(asm[0].Name) if asm else "none"
        refs = {}
        for r in rows("AssemblyRef"):
            refs.setdefault(nm(r.Name), ver(r))
        types = [(nm(x.TypeNamespace), nm(x.TypeName)) for x in rows("TypeDef")]
        fields = [nm(f.Name) for f in rows("Field")]
        methods = [nm(m.Name) for m in rows("MethodDef")]
        res = [nm(r.Name) for r in rows("ManifestResource")]
        try:
            il_only = bool(int(net.struct.Flags) & 1)
        except Exception:   # noqa: BLE001
            il_only = True
        out = {"assembly_name": aname or "none", "assembly_version": ver(asm[0]) if asm else "none",
               "assembly_refs": list(refs)}
        fs_res = [r for r in res if r.startswith(("FSharpSignature", "FSharpOptimization"))]
        startup = sorted({ns.split(">", 1)[0][len("<StartupCode$"):] for ns, _ in types if ns.startswith("<StartupCode$")})
        fs_clo = [n for ns, n in types if _FS_CLOSURE.search(n)]
        vb_clo = [n for ns, n in types if n.startswith("_Closure$__")]
        cs_clo = [n for ns, n in types if n == "<>c" or n.startswith("<>c__DisplayClass")]
        vb_types = [n for ns, n in types if n.startswith(("VB$AnonymousType_", "VB$StateMachine_"))]
        vb_fields = [f for f in fields if f.startswith(("$VB$Local_", "$VB$Me", "$VB$NonLocal_", "$VB$ResumableLocal_"))]
        my_ns = any(ns == "My" or ns.endswith(".My") for ns, _ in types) and \
            any(n in ("MyProject", "MyApplication", "MySettings", "MyComputer") for _, n in types)
        crt = any(ns == "<CrtImplementationDetails>" or n.startswith("<CrtImplementationDetails>") for ns, n in types)
        fs_core = refs.get("FSharp.Core")
        is_fs_core = aname == "FSharp.Core"
        vb_ref = next((r for r in refs if r in ("Microsoft.VisualBasic", "Microsoft.VisualBasic.Core")), None)
        strong = {"fsharp": [], "vbnet": [], "cppcli": [], "csharp": []}
        if startup:
            strong["fsharp"].append("<StartupCode$%s> namespace" % startup[0])
        if fs_res:
            strong["fsharp"].append("resource " + fs_res[0])
        if fs_clo and (startup or fs_res):
            strong["fsharp"].append(f"{len(fs_clo)} closure types name@line ({fs_clo[0]})")
        if vb_clo:
            strong["vbnet"].append("type " + vb_clo[0])
        if vb_types:
            strong["vbnet"].append("type " + vb_types[0])
        if vb_fields:
            strong["vbnet"].append("field " + vb_fields[0])
        if any(m.startswith("_Lambda$__") for m in methods):
            strong["vbnet"].append("method _Lambda$__*")
        if my_ns:
            strong["vbnet"].append("My namespace (MyProject)")
        if crt:
            strong["cppcli"].append("<CrtImplementationDetails> types")
        if not il_only:
            strong["cppcli"].append("COR flags: mixed mode (no ILONLY)")
        if cs_clo:
            strong["csharp"].append("type " + cs_clo[0])
        if any(m == "<Main>$" for m in methods):
            strong["csharp"].append("top-level statements <Main>$")
        weak = {"fsharp": ["AssemblyRef FSharp.Core " + fs_core] if fs_core else [],
                "vbnet": [f"AssemblyRef {vb_ref} {refs[vb_ref]}"] if vb_ref else [],
                "cppcli": ["AssemblyRef Microsoft.VisualC"] if "Microsoft.VisualC" in refs else []}
        if is_fs_core:
            weak["fsharp"].append("AssemblyDef FSharp.Core " + out["assembly_version"])
        lang = next((k for k in ("cppcli", "fsharp", "vbnet") if strong[k]), None)
        if lang is None and strong["csharp"]:
            lang, conf = "csharp", "compiler"
        elif lang is None:
            lang = next((k for k in ("fsharp", "vbnet", "cppcli") if weak[k]), None)
            conf = "reference" if lang else "default"
            lang = lang or "csharp"
        else:
            conf = "compiler"
        ev = ["PE CLI header + metadata"] + strong.get(lang, []) + weak.get(lang, [])
        host = "ironpython" if "IronPython" in refs or "Microsoft.Scripting" in refs else \
            ("powershell" if "System.Management.Automation" in refs else "none")
        clo = {"fsharp": fs_clo, "vbnet": vb_clo, "csharp": cs_clo}.get(lang, cs_clo)
        anon = [n for _, n in types if n.startswith(("<>f__AnonymousType", "VB$AnonymousType_"))]
        out.update(language=lang, confidence=conf, evidence=ev,
                   fsharp_core_version_ref=fs_core or "none",
                   fsharp_core_version_def=out["assembly_version"] if is_fs_core else "none",
                   fsharp_core_version=fs_core or (out["assembly_version"] if is_fs_core else "none"),
                   fsharp_resources=fs_res, fsharp_resource_count=str(len(fs_res)),
                   startup_code=startup[0] if startup else "none",
                   vb_runtime_ref=vb_ref or "none", vb_runtime_version=refs[vb_ref] if vb_ref else "none",
                   vb_my_namespace="true" if my_ns else "false", vb_local_fields=str(len(vb_fields)),
                   closures=clo, closure_count=str(len(clo)), anon_types=anon, anon_type_count=str(len(anon)),
                   il_only="true" if il_only else "false", scripting_host=host)
        return out
    except Exception:   # noqa: BLE001 -- hostile/truncated PE: cannot answer
        return None


def dotnet_language_field(data, name="language"):
    """One dotnet_language_of value (lists as compact JSON); "none" when not a CLI assembly or the field is unknown."""
    try:
        f = dotnet_language_of(data)
        v = (f or {}).get(_DN_LANG_ALIASES.get(name, name), "none")
        return json.dumps(v, separators=(",", ":"), ensure_ascii=False) if isinstance(v, list) else v
    except Exception:   # noqa: BLE001
        return "none"


# ------------------------------------------------------------------ .NET P/Invoke bridge (D22 theme; labels SPECULATIVE)
_PINV_CC = {1: "winapi", 2: "cdecl", 3: "stdcall", 4: "thiscall", 5: "fastcall"}   # MappingFlags & 0x700 >> 8
_PINV_CS = {0: "none", 2: "ansi", 4: "unicode", 6: "auto"}                          # MappingFlags & 0x6
_PINV_TRI = {0: "default", 1: "true", 2: "false"}                                   # BestFit 0x30 / ThrowOnUnmappable 0x3000
_PINV_ET = {1: ("void", "void"), 2: ("bool", "bool"), 3: ("char", "char"), 4: ("sbyte", "int8"), 5: ("byte", "uint8"),
            6: ("short", "int16"), 7: ("ushort", "uint16"), 8: ("int", "int32"), 9: ("uint", "uint32"),
            0xA: ("long", "int64"), 0xB: ("ulong", "uint64"), 0xC: ("float", "float32"), 0xD: ("double", "float64"),
            0xE: ("string", "string"), 0x16: ("TypedReference", "typedref"), 0x18: ("IntPtr", "native int"),
            0x19: ("UIntPtr", "native uint"), 0x1C: ("object", "object")}
_PINV_FNPTR_CC = {1: "cdecl", 2: "stdcall", 3: "thiscall", 4: "fastcall", 9: "unmanaged"}
_PINV_NATIVE_APIS = {("NativeLibrary", "Load"), ("NativeLibrary", "TryLoad"), ("NativeLibrary", "GetExport"),
                     ("NativeLibrary", "TryGetExport"), ("NativeLibrary", "Free"), ("NativeLibrary", "GetMainProgramHandle"),
                     ("Marshal", "GetDelegateForFunctionPointer"), ("Marshal", "GetFunctionPointerForDelegate"),
                     ("NativeLibrary", "SetDllImportResolver")}
# UnmanagedType (ECMA-335 II.23.4 NATIVE_TYPE_*) by FieldMarshal blob byte 0 -> the C# enum name
_PINV_UT = {2: "Bool", 3: "I1", 4: "U1", 5: "I2", 6: "U2", 7: "I4", 8: "U4", 9: "I8", 10: "U8", 11: "R4", 12: "R8",
            15: "Currency", 19: "BStr", 20: "LPStr", 21: "LPWStr", 22: "LPTStr", 23: "ByValTStr", 25: "IUnknown",
            26: "IDispatch", 27: "Struct", 28: "Interface", 29: "SafeArray", 30: "ByValArray", 31: "SysInt",
            32: "SysUInt", 34: "VBByRefStr", 35: "AnsiBStr", 36: "TBStr", 37: "VariantBool", 38: "FunctionPtr",
            40: "AsAny", 42: "LPArray", 43: "LPStruct", 44: "CustomMarshaler", 45: "Error", 46: "IInspectable",
            47: "HString", 48: "LPUTF8Str"}


def _pinv_cu(b, p):
    """ECMA-335 II.23.2 compressed unsigned int -> (value, next)."""
    x = b[p]
    if not x & 0x80:
        return x, p + 1
    if not x & 0x40:
        return ((x & 0x3F) << 8) | b[p + 1], p + 2
    return ((x & 0x1F) << 24) | int.from_bytes(b[p + 1:p + 4], "big"), p + 4


def _pinv_type(b, p, tname, depth=0):
    """One sig Type at p -> ((csharp, il), next). tname(coded TypeDefOrRef) -> simple type name."""
    if depth > 16:
        raise ValueError("deep sig")
    e = b[p]
    p += 1
    if e in _PINV_ET:
        return _PINV_ET[e], p
    if e in (0x1F, 0x20):   # CMOD_REQD / CMOD_OPT: skip the modifier type
        _, p = _pinv_cu(b, p)
        return _pinv_type(b, p, tname, depth + 1)
    if e == 0x45:           # PINNED
        return _pinv_type(b, p, tname, depth + 1)
    if e in (0x0F, 0x10):   # PTR / BYREF
        (c, i), p = _pinv_type(b, p, tname, depth + 1)
        return ((c + "*", i + "*") if e == 0x0F else ("ref " + c, i + "&")), p
    if e in (0x11, 0x12):   # VALUETYPE / CLASS
        v, p = _pinv_cu(b, p)
        n = tname(v)
        return (n, n), p
    if e == 0x1D:           # SZARRAY
        (c, i), p = _pinv_type(b, p, tname, depth + 1)
        return (c + "[]", i + "[]"), p
    if e == 0x14:           # ARRAY: rank, sizes, lobounds
        (c, i), p = _pinv_type(b, p, tname, depth + 1)
        rank, p = _pinv_cu(b, p)
        for _ in range(2):
            n, p = _pinv_cu(b, p)
            for _ in range(n):
                _, p = _pinv_cu(b, p)
        s = "[" + "," * max(rank - 1, 0) + "]"
        return (c + s, i + s), p
    if e in (0x13, 0x1E):   # VAR / MVAR
        n, p = _pinv_cu(b, p)
        return (f"T{n}", ("!" if e == 0x13 else "!!") + str(n)), p
    if e == 0x15:           # GENERICINST (CLASS|VALUETYPE) Type GenArgCount Type*
        (c, i), p = _pinv_type(b, p, tname, depth + 1)
        n, p = _pinv_cu(b, p)
        args = []
        for _ in range(min(n, 32)):
            a, p = _pinv_type(b, p, tname, depth + 1)
            args.append(a)
        c = c.split("`")[0]
        i = i.split("`")[0]
        return (c + "<" + ",".join(x[0] for x in args) + ">", i + "<" + ",".join(x[1] for x in args) + ">"), p
    if e == 0x1B:           # FNPTR MethodDefSig/RefSig
        cc = b[p] & 0xF
        r, ps, p = _pinv_msig(b, p, tname, depth + 1)
        k = _PINV_FNPTR_CC.get(cc)
        head = f"delegate* unmanaged[{k.capitalize()}]" if k and k != "unmanaged" else (
            "delegate* unmanaged" if k else "delegate*")
        c = head + "<" + ",".join([x[0] for x in ps] + [r[0]]) + ">"
        return (c, "method " + (f"unmanaged {k} " if k else "") + r[1] + " *(" + ",".join(x[1] for x in ps) + ")"), p
    raise ValueError(f"element type 0x{e:x}")


def _pinv_msig(b, p, tname, depth=0):
    """MethodDefSig at p -> (ret, [params], next); each (csharp, il)."""
    cc = b[p]
    p += 1
    if cc & 0x10:
        _, p = _pinv_cu(b, p)
    n, p = _pinv_cu(b, p)
    ret, p = _pinv_type(b, p, tname, depth)
    ps = []
    for _ in range(min(n, 256)):
        if b[p] == 0x41:    # SENTINEL (vararg call site)
            p += 1
        t, p = _pinv_type(b, p, tname, depth)
        ps.append(t)
    return ret, ps, p


def _pinv_named(blob, want="EntryPoint"):
    """Named string arg `want` of a custom-attribute blob (after the fixed args, which must be 0 or 1 SerString)."""
    try:
        if blob[:2] != b"\x01\x00":
            return None
        p = 2
        for nfix in (1, 0):   # LibraryImport(string) has one fixed SerString, UnmanagedCallersOnly() none
            q = p
            try:
                if nfix:
                    if blob[q] == 0xFF:
                        q += 1
                    else:
                        n, q = _pinv_cu(blob, q)
                        q += n
                cnt = int.from_bytes(blob[q:q + 2], "little")
                q += 2
                got = None
                for _ in range(cnt):
                    kind, et = blob[q], blob[q + 1]
                    q += 2
                    if kind not in (0x53, 0x54):
                        raise ValueError
                    if et == 0x55:   # enum: type name SerString
                        n, q = _pinv_cu(blob, q)
                        q += n
                    n, q = _pinv_cu(blob, q)
                    name = blob[q:q + n].decode("utf-8", "replace")
                    q += n
                    if et in (0x0E, 0x50):
                        if blob[q] == 0xFF:
                            val, q = None, q + 1
                        else:
                            n, q = _pinv_cu(blob, q)
                            val, q = blob[q:q + n].decode("utf-8", "replace"), q + n
                    elif et in (0x02, 0x04, 0x05):
                        val, q = blob[q], q + 1
                    elif et in (0x06, 0x07):
                        val, q = None, q + 2
                    elif et in (0x08, 0x09, 0x0C, 0x55):
                        val, q = None, q + 4
                    elif et in (0x0A, 0x0B, 0x0D):
                        val, q = None, q + 8
                    else:
                        raise ValueError
                    if name == want and isinstance(val, str):
                        got = val
                if q == len(blob):
                    return got
            except (IndexError, ValueError):
                continue
    except Exception:   # noqa: BLE001
        pass
    return None


def dotnet_pinvoke_facts(data):
    """.NET P/Invoke bridge facts via dnfile (ECMA-335 ImplMap II.22.22 joined to ModuleRef + MethodDef, FieldMarshal):
    pinvoke_count, pinvoke_methods / pinvoke_entries (ImplMap = MethodDef order), pinvoke_imports (JSON
    [{"method","entry","module"}]), pinvoke_details (JSON, + type/token/callconv/charset/flags/return/params/marshal),
    native_modules (ModuleRef order, names as written: 'libc', 'kernel32.dll') / native_module_count / pinvoke_modules
    (distinct, first-use order), set_last_error_methods, library_import_methods (+ _count; methods carrying
    [LibraryImport]), unmanaged_callers_only (+ _entries, the EntryPoint= export names), unmanaged_fnptr_count /
    unmanaged_fnptr_callconvs (StandAloneSig blobs with an unmanaged calling convention: `delegate* unmanaged` calli),
    native_library_apis (NativeLibrary.Load/GetExport, Marshal.GetDelegateForFunctionPointer MemberRefs),
    native_library_strings (the ldstr feeding each such call, IL order); and per P/Invoke method m (managed name AND
    entry name): m_module, m_entry, m_callconv (winapi/cdecl/stdcall/thiscall/fastcall), m_charset
    (none/ansi/unicode/auto), m_set_last_error / m_exact_spelling / m_preserve_sig ("true"/"false"), m_best_fit /
    m_throw_on_unmappable (default/true/false), m_flags (0x...), m_token, m_return / m_params (C# keywords; IntPtr for
    native int), m_return_il / m_params_il (IL names), m_param_names, m_signature ('int getpid()'), m_return_marshal /
    m_param_marshal (UnmanagedType names, "none"). Lists are compact JSON. None when not a CLI assembly."""
    try:
        import dnfile
        pe = dnfile.dnPE(data=bytes(data), fast_load=False)
        net = pe.net
        if net is None or net.mdtables is None:
            return None
        t = net.mdtables
    except Exception:   # noqa: BLE001 -- hostile/truncated PE: cannot answer
        return None
    js = lambda xs: json.dumps(list(xs), separators=(",", ":"), ensure_ascii=False)   # noqa: E731
    rows = lambda tab: list(getattr(t, tab, None) or ())   # noqa: E731
    nm = lambda x: "" if x is None else str(x)   # noqa: E731
    blob = lambda x: bytes(getattr(x, "value", x) or b"")   # noqa: E731
    out = {}
    mds, prm, tds, trs = rows("MethodDef"), rows("Param"), rows("TypeDef"), rows("TypeRef")
    mrefs = rows("ModuleRef")
    out["native_modules"] = js(nm(r.Name) for r in mrefs)
    out["native_module_count"] = str(len(mrefs))

    def tname(coded):
        tag, i = coded & 3, coded >> 2
        tab = tds if tag == 0 else trs if tag == 1 else None
        return nm(tab[i - 1].TypeName) if tab and 0 < i <= len(tab) else "?"
    owner = {}   # MethodDef row -> declaring Namespace.Type (TypeDef MethodList runs)
    starts = [int(r.struct.MethodList_Index) for r in tds]
    for k, r in enumerate(tds):
        end = starts[k + 1] if k + 1 < len(starts) else len(mds) + 1
        full = (nm(r.TypeNamespace) + "." if nm(r.TypeNamespace) else "") + nm(r.TypeName)
        for i in range(starts[k], min(end, len(mds) + 1)):
            owner[i] = full
    pstart = [int(r.struct.ParamList_Index) for r in mds]
    marsh = {}   # Param row -> UnmanagedType name
    for r in rows("FieldMarshal"):
        c = int(r.struct.Parent_CodedIndex)
        nb = blob(r.NativeType)
        if c & 1 and nb:
            marsh[c >> 1] = _PINV_UT.get(nb[0], f"0x{nb[0]:x}")
    attrs = {}   # MethodDef row -> {attr type name: blob}
    for r in rows("CustomAttribute"):
        try:
            pc, tc = int(r.struct.Parent_CodedIndex), int(r.struct.Type_CodedIndex)
            if pc & 0x1F != 0:   # HasCustomAttribute tag 0 = MethodDef
                continue
            an = None
            if tc & 7 == 3:      # CustomAttributeType: MemberRef
                mr = t.MemberRef[(tc >> 3) - 1]
                an = tname({1: 1, 0: 0}.get(int(mr.struct.Class_CodedIndex) & 7, 9) | (int(mr.struct.Class_CodedIndex) >> 3 << 2)) \
                    if int(mr.struct.Class_CodedIndex) & 7 in (0, 1) else None
            elif tc & 7 == 2:    # MethodDef ctor
                an = owner.get(tc >> 3, "").rsplit(".", 1)[-1]
            if an:
                attrs.setdefault(pc >> 5, {})[an] = blob(r.Value)
        except Exception:   # noqa: BLE001
            continue
    imps, det = [], []
    for r in rows("ImplMap"):
        try:
            mf, sc, fw = int(r.struct.MappingFlags), int(r.struct.ImportScope_Index), int(r.struct.MemberForwarded_CodedIndex)
            if not fw & 1:   # MemberForwarded tag 0 = Field (not callable), 1 = MethodDef
                continue
            mi = fw >> 1
            if not 0 < mi <= len(mds):
                continue
            m = mds[mi - 1]
            name = nm(m.Name)
            entry = nm(r.ImportName) or name
            mod = nm(mrefs[sc - 1].Name) if 0 < sc <= len(mrefs) else "none"
            d = {"method": name, "entry": entry, "module": mod, "type": owner.get(mi, "none"),
                 "token": f"0x{0x06000000 | mi:08x}", "callconv": _PINV_CC.get((mf >> 8) & 7, "none"),
                 "charset": _PINV_CS[mf & 6], "set_last_error": "true" if mf & 0x40 else "false",
                 "exact_spelling": "true" if mf & 1 else "false", "best_fit": _PINV_TRI.get((mf >> 4) & 3, "default"),
                 "throw_on_unmappable": _PINV_TRI.get((mf >> 12) & 3, "default"),
                 "preserve_sig": "true" if int(m.struct.ImplFlags) & 0x80 else "false", "flags": f"0x{mf:04x}"}
            try:
                ret, ps, _ = _pinv_msig(blob(m.Signature), 0, tname)
            except Exception:   # noqa: BLE001 -- unknown element type: leave the signature unanswered
                ret, ps = ("none", "none"), []
            p0 = pstart[mi - 1]
            p1 = pstart[mi] if mi < len(pstart) else len(prm) + 1
            seq = {int(prm[j - 1].struct.Sequence): j for j in range(p0, min(p1, len(prm) + 1)) if j >= 1}
            pn = [nm(prm[seq[k] - 1].Name) if k in seq else f"arg{k - 1}" for k in range(1, len(ps) + 1)]
            d.update({"return": ret[0], "params": [x[0] for x in ps], "return_il": ret[1], "params_il": [x[1] for x in ps],
                      "param_names": pn, "return_marshal": marsh.get(seq.get(0), "none"),
                      "param_marshal": [marsh.get(seq.get(k), "none") for k in range(1, len(ps) + 1)],
                      "signature": f"{ret[0]} {name}(" + ", ".join(f"{a[0]} {b}" for a, b in zip(ps, pn)) + ")"})
            det.append(d)
            imps.append({"method": name, "entry": entry, "module": mod})
        except Exception:   # noqa: BLE001 -- one broken row must not hide the others
            continue
    out["pinvoke_count"] = str(len(det))
    out["pinvoke_methods"] = js(d["method"] for d in det)
    out["pinvoke_entries"] = js(d["entry"] for d in det)
    out["pinvoke_imports"] = js(imps)
    out["pinvoke_details"] = js(det)
    out["pinvoke_modules"] = js(dict.fromkeys(d["module"] for d in det))
    out["set_last_error_methods"] = js(d["method"] for d in det if d["set_last_error"] == "true")
    li = [nm(mds[i - 1].Name) for i in sorted(attrs) if "LibraryImportAttribute" in attrs[i] and 0 < i <= len(mds)]
    out["library_import_methods"], out["library_import_count"] = js(li), str(len(li))
    uco = [i for i in sorted(attrs) if "UnmanagedCallersOnlyAttribute" in attrs[i] and 0 < i <= len(mds)]
    out["unmanaged_callers_only"] = js(nm(mds[i - 1].Name) for i in uco)
    out["unmanaged_callers_only_entries"] = js(e for e in (_pinv_named(attrs[i]["UnmanagedCallersOnlyAttribute"]) for i in uco) if e)
    ccs = []
    for r in rows("StandAloneSig"):
        b = blob(r.Signature)
        if b and b[0] & 0xF in _PINV_FNPTR_CC and b[0] != 7:
            ccs.append(_PINV_FNPTR_CC[b[0] & 0xF])
    out["unmanaged_fnptr_count"] = str(len(ccs))
    out["unmanaged_fnptr_callconvs"] = js(dict.fromkeys(ccs))
    apis = {}   # MemberRef token -> "Type.Method"
    for k, r in enumerate(rows("MemberRef")):
        try:
            c = int(r.struct.Class_CodedIndex)
            if c & 7 != 1:
                continue
            key = (tname((c >> 3 << 2) | 1), nm(r.Name))
            if key in _PINV_NATIVE_APIS:
                apis[0x0A000001 + k] = ".".join(key)
        except Exception:   # noqa: BLE001
            continue
    out["native_library_apis"] = js(dict.fromkeys(apis.values()))
    strs = []
    if apis:
        try:
            us = bytes(getattr(net.user_strings, "__data__", b"") or b"")
            pat = re.compile(rb"\x72(...)\x70(?:[\x02-\x0e\x11\x06-\x09]|\x11.|\x0e.)?\x28(...)\x0a", re.S)
            for m in mds:
                rva = int(m.struct.Rva or 0)
                if not rva:
                    continue
                body = pe.get_data(rva, 1)
                if not body:
                    continue
                if body[0] & 3 == 2:
                    code = pe.get_data(rva + 1, body[0] >> 2)
                else:
                    hdr = pe.get_data(rva, 12)
                    code = pe.get_data(rva + (hdr[1] >> 4) * 4, int.from_bytes(hdr[4:8], "little"))
                for x in pat.finditer(code[:1 << 16]):
                    tok = 0x0A000000 | int.from_bytes(x.group(2), "little")
                    if tok in apis:
                        o = int.from_bytes(x.group(1), "little")
                        n, q = _pinv_cu(us, o)
                        strs.append(us[q:q + n - 1].decode("utf-16-le", "replace"))
        except Exception:   # noqa: BLE001
            pass
    out["native_library_strings"] = js(strs)
    for d in det:
        for key in (d["method"], d["entry"]):
            for f, v in d.items():
                if f in ("method",):
                    continue
                k = f"{key}_{f}"
                if k not in out:
                    out[k] = js(v) if isinstance(v, list) else v
    return out


def dotnet_pinvoke_field(data, name):
    """One dotnet_pinvoke_facts value: "none" when absent (no such P/Invoke / field), None when not a CLI assembly."""
    f = dotnet_pinvoke_facts(data)
    if f is None:
        return None
    return f.get(name, "none")

# ------------------------------------------------------------------ .NET COM interop (managed<->native bridge)
# ComImport is a pseudo-attribute (TypeDef flag tdImport 0x1000); Guid/InterfaceType/DispId/CoClass/ProgId/ComVisible are
# real custom attributes. Vtable slot of interface method i = i + base: IUnknown 3, dual/IDispatch 7, IInspectable 6.
_COM_ITYPE = {0: "dual", 1: "iunknown", 2: "idispatch", 3: "iinspectable"}
_COM_VT_BASE = {"dual": 7, "iunknown": 3, "idispatch": 7, "iinspectable": 6}
_COM_ATTRS = {"GuidAttribute", "InterfaceTypeAttribute", "DispIdAttribute", "CoClassAttribute", "ProgIdAttribute",
              "ComVisibleAttribute", "GeneratedComInterfaceAttribute", "GeneratedComClassAttribute",
              "ClassInterfaceAttribute", "ComDefaultInterfaceAttribute", "ComSourceInterfacesAttribute"}
_COM_APIS = {("Type", "GetTypeFromCLSID"), ("Type", "GetTypeFromProgID"), ("Marshal", "GetActiveObject"),
             ("Marshal", "BindToMoniker"), ("Marshal", "GetObjectForIUnknown"), ("Marshal", "GetIUnknownForObject"),
             ("Marshal", "QueryInterface"), ("Marshal", "ReleaseComObject"), ("Marshal", "FinalReleaseComObject"),
             ("Marshal", "GetComInterfaceForObject"), ("Marshal", "GetTypedObjectForIUnknown"), ("Marshal", "AddRef"),
             ("Marshal", "Release"), ("Marshal", "CreateWrapperOfType"), ("Activator", "CreateInstance"),
             ("ComWrappers", "GetOrCreateObjectForComInstance"), ("StrategyBasedComWrappers", "GetOrCreateObjectForComInstance"),
             ("ComWrappers", "GetOrCreateComInterfaceForObject")}
_COM_NATIVE = {"CoCreateInstance", "CoCreateInstanceEx", "CoGetClassObject", "CoInitialize", "CoInitializeEx",
               "CoUninitialize", "CLSIDFromProgID", "CLSIDFromString", "IIDFromString", "ProgIDFromCLSID",
               "GetActiveObject", "CoGetObject", "LoadTypeLib", "LoadTypeLibEx", "LoadRegTypeLib", "RegisterTypeLib",
               "CoRegisterClassObject", "DllGetClassObject", "CoTaskMemAlloc", "CoTaskMemFree", "OleInitialize"}
_GUID_RE = re.compile(r"^\{?([0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12})\}?$")


def _com_guid(s):
    m = _GUID_RE.match((s or "").strip())
    return m.group(1).lower() if m else None


def dotnet_com_facts(data):
    """COM-interop facts of a .NET (CLI) PE via dnfile (ECMA-335 TypeDef flags + CustomAttribute blobs + ImplMap + IL):
    com_interfaces / com_interfaces_full / com_interface_count / com_iids (lowercase dashed guids, aligned) -- interfaces
    flagged ComImport (tdImport) or [GeneratedComInterface], TypeDef order; com_classes / com_clsids ([ComImport]
    coclasses); com_exposed_classes (non-import classes carrying [Guid]); guid_attributes (JSON [{"target","guid"}], CA
    order, target 'assembly' or Namespace.Type); assembly_guid; com_activation_apis (MemberRef 'Type.Method', e.g.
    Type.GetTypeFromCLSID); com_pinvokes (JSON 'module!entry' of ole32/oleaut32/combase or a known COM entry);
    com_progids (ProgId attrs + ldstr fed to GetTypeFromProgID/GetActiveObject); guid_strings (GUID-shaped user strings,
    lowercase, #US order). Per COM type T (short name and Namespace.Name): T_guid (= T_iid / T_clsid), T_guid_upper,
    T_interface_type (dual default / iunknown / idispatch / iinspectable), T_vtable_base (3/6/7), T_methods (JSON, MethodDef
    = vtable order), T_method_count, T_vtable_slots (JSON {method: slot}), T_coclass, T_progid, T_generated; per method
    M of T: T_M_vtable_slot, T_M_vtable_offset (hex, slot*8 x64), T_M_vtable_offset_x86 (slot*4), T_M_dispid, and the
    same keys without T_ when M is unique. "none" when absent; None when not a CLI assembly."""
    try:
        import dnfile
        pe = dnfile.dnPE(data=bytes(data), fast_load=False)
        net = pe.net
        if net is None or net.mdtables is None:
            return None
        t = net.mdtables
    except Exception:   # noqa: BLE001 -- hostile/truncated PE: cannot answer
        return None
    js = lambda xs: json.dumps(list(xs), separators=(",", ":"), ensure_ascii=False)   # noqa: E731
    rows = lambda tab: list(getattr(t, tab, None) or ())   # noqa: E731
    nm = lambda x: "" if x is None else str(x)   # noqa: E731
    blob = lambda x: bytes(getattr(x, "value", x) or b"")   # noqa: E731
    tds, trs, mds, mrs = rows("TypeDef"), rows("TypeRef"), rows("MethodDef"), rows("MemberRef")
    full = [(nm(r.TypeNamespace) + "." if nm(r.TypeNamespace) else "") + nm(r.TypeName) for r in tds]
    starts = [int(r.struct.MethodList_Index) for r in tds]
    owner = {}   # MethodDef row -> TypeDef row
    for k in range(len(tds)):
        end = starts[k + 1] if k + 1 < len(starts) else len(mds) + 1
        for i in range(starts[k], min(end, len(mds) + 1)):
            owner[i] = k + 1

    def ca_type(tc):
        if tc & 7 == 3 and 0 < tc >> 3 <= len(mrs):
            c = int(mrs[(tc >> 3) - 1].struct.Class_CodedIndex)
            tab = trs if c & 7 == 1 else tds if c & 7 == 0 else None
            i = c >> 3
            return nm(tab[i - 1].TypeName) if tab and 0 < i <= len(tab) else None
        if tc & 7 == 2:
            k = owner.get(tc >> 3)
            return nm(tds[k - 1].TypeName) if k else None
        return None
    ca = {}   # (parent tag, row) -> {attr name: blob}
    gattr = []
    for r in rows("CustomAttribute"):
        try:
            pc, an = int(r.struct.Parent_CodedIndex), ca_type(int(r.struct.Type_CodedIndex))
            if an not in _COM_ATTRS:
                continue
            b = blob(r.Value)
            ca.setdefault((pc & 0x1F, pc >> 5), {})[an] = b
            if an == "GuidAttribute":
                g = _com_guid(_dn_serstr(b))
                tgt = "assembly" if pc & 0x1F == 14 else full[(pc >> 5) - 1] if pc & 0x1F == 3 and 0 < pc >> 5 <= len(tds) else None
                if g and tgt:
                    gattr.append({"target": tgt, "guid": g})
        except Exception:   # noqa: BLE001 -- one broken row must not hide the others
            continue
    dispid = {}   # MethodDef row -> dispid (method attr, or its property's attr via MethodSemantics)
    for (tag, i), a in ca.items():
        b = a.get("DispIdAttribute")
        if tag == 0 and b and len(b) >= 6:
            dispid[i] = int.from_bytes(b[2:6], "little", signed=True)
    for r in rows("MethodSemantics"):
        try:
            asc = int(r.struct.Association_CodedIndex)
            b = ca.get((9, asc >> 1), {}).get("DispIdAttribute") if asc & 1 else None
            if b and len(b) >= 6:
                dispid.setdefault(int(r.struct.Method_Index), int.from_bytes(b[2:6], "little", signed=True))
        except Exception:   # noqa: BLE001
            continue
    out, ifs, cls, exp = {}, [], [], []
    put = lambda k, v: out.setdefault(k, v)   # noqa: E731 -- first (TypeDef-order) owner of a short key wins
    for k, r in enumerate(tds, 1):
        fl, a = int(r.struct.Flags), ca.get((3, k), {})
        isif, imp, gen = bool(fl & 0x20), bool(fl & 0x1000), "GeneratedComInterfaceAttribute" in a
        if not (imp or gen or ("GuidAttribute" in a and not isif)):
            continue
        g = _com_guid(_dn_serstr(a.get("GuidAttribute", b""))) or "none"
        short, fn = nm(r.TypeName), full[k - 1]
        facts = {"guid": g, "guid_upper": g.upper() if g != "none" else "none", "generated": "true" if gen else "false"}
        if isif:
            ifs.append((short, fn, g))
            facts["iid"] = g
            it = a.get("InterfaceTypeAttribute", b"")
            ityp = "iunknown" if gen else _COM_ITYPE.get(
                int.from_bytes(it[2:6] if len(it) >= 8 else it[2:4], "little") if len(it) >= 6 else 0, "none")
            base = _COM_VT_BASE.get(ityp)
            end = starts[k] if k < len(starts) else len(mds) + 1
            ms = list(range(starts[k - 1], min(end, len(mds) + 1)))
            names = [nm(mds[i - 1].Name) for i in ms]
            facts.update({"interface_type": ityp, "vtable_base": str(base) if base is not None else "none",
                          "methods": js(names), "method_count": str(len(names)),
                          "vtable_slots": json.dumps({n: j + base for j, n in enumerate(names)} if base is not None else {},
                                                     separators=(",", ":"))})
            cc = _dn_serstr(a.get("CoClassAttribute", b""))
            facts["coclass"] = cc.rsplit(".", 1)[-1] if cc else "none"
            for j, (i, n) in enumerate(zip(ms, names)):
                mf = {"dispid": str(dispid[i]) if i in dispid else "none"}
                if base is not None:
                    mf.update({"vtable_slot": str(j + base), "vtable_offset": hex((j + base) * 8),
                               "vtable_offset_x86": hex((j + base) * 4)})
                for f, v in mf.items():
                    for key in (f"{short}_{n}_{f}", f"{fn}_{n}_{f}", f"{short}.{n}_{f}"):
                        put(key, v)
                    out.setdefault(f"_cand_{n}_{f}", set()).add(v)
        else:
            (cls if imp else exp).append((short, fn, g))
            facts["clsid"] = g
        pid = _dn_serstr(a.get("ProgIdAttribute", b""))
        facts["progid"] = pid or "none"
        for f, v in facts.items():
            put(f"{short}_{f}", v)
            put(f"{fn}_{f}", v)
    for key in [x for x in out if x.startswith("_cand_")]:
        vs = out.pop(key)
        if len(vs) == 1:
            out.setdefault(key[6:], next(iter(vs)))
    if not (ifs or cls or exp):
        return {}
    out["com_interfaces"], out["com_interfaces_full"] = js(x[0] for x in ifs), js(x[1] for x in ifs)
    out["com_interface_count"], out["com_iids"] = str(len(ifs)), js(x[2] for x in ifs)
    out["com_classes"], out["com_clsids"] = js(x[0] for x in cls), js(x[2] for x in cls)
    out["com_exposed_classes"], out["com_exposed_clsids"] = js(x[0] for x in exp), js(x[2] for x in exp)
    out["guid_attributes"] = js(gattr)
    out["assembly_guid"] = next((x["guid"] for x in gattr if x["target"] == "assembly"), "none")
    apis = {}   # MemberRef token -> "Type.Method"
    for k, r in enumerate(mrs):
        try:
            c = int(r.struct.Class_CodedIndex)
            if c & 7 == 1 and 0 < c >> 3 <= len(trs):
                key = (nm(trs[(c >> 3) - 1].TypeName), nm(r.Name))
                if key in _COM_APIS:
                    apis[0x0A000001 + k] = ".".join(key)
        except Exception:   # noqa: BLE001
            continue
    out["com_activation_apis"] = js(dict.fromkeys(apis.values()))
    mrefs, pinv = rows("ModuleRef"), []
    for r in rows("ImplMap"):
        try:
            fw, sc = int(r.struct.MemberForwarded_CodedIndex), int(r.struct.ImportScope_Index)
            if not fw & 1 or not 0 < fw >> 1 <= len(mds):
                continue
            entry = nm(r.ImportName) or nm(mds[(fw >> 1) - 1].Name)
            mod = nm(mrefs[sc - 1].Name) if 0 < sc <= len(mrefs) else "none"
            if mod.lower().rsplit(".", 1)[0] in ("ole32", "oleaut32", "combase") or entry in _COM_NATIVE:
                pinv.append(f"{mod}!{entry}")
        except Exception:   # noqa: BLE001
            continue
    out["com_pinvokes"] = js(pinv)
    us = b""
    try:
        us = bytes(getattr(net.user_strings, "__data__", b"") or b"")
    except Exception:   # noqa: BLE001
        pass
    gs, p = [], 1
    while p < len(us):   # #US heap walk: compressed length, UTF-16LE, trailing flag byte
        try:
            n, q = _pinv_cu(us, p)
        except IndexError:
            break
        if n == 0 and q == p + 1 and us[p] == 0:
            p = q
            continue
        g = _com_guid(us[q:q + n - 1].decode("utf-16-le", "replace")) if n > 1 else None
        if g:
            gs.append(g)
        p = q + n
    out["guid_strings"] = js(dict.fromkeys(gs))
    progs = [x for x in (_dn_serstr(a.get("ProgIdAttribute", b"")) for a in ca.values()) if x]
    want = {tk for tk, v in apis.items() if v in ("Type.GetTypeFromProgID", "Marshal.GetActiveObject", "Marshal.BindToMoniker")}
    if want and us:
        pat = re.compile(rb"\x72(...)\x70(?:\x16|\x17)?\x28(...)\x0a", re.S)
        for m in mds:
            try:
                rva = int(m.struct.Rva or 0)
                body = pe.get_data(rva, 1) if rva else b""
                if not body:
                    continue
                if body[0] & 3 == 2:
                    code = pe.get_data(rva + 1, body[0] >> 2)
                else:
                    hdr = pe.get_data(rva, 12)
                    code = pe.get_data(rva + (hdr[1] >> 4) * 4, int.from_bytes(hdr[4:8], "little"))
                for x in pat.finditer(code[:1 << 16]):
                    if 0x0A000000 | int.from_bytes(x.group(2), "little") in want:
                        n, q = _pinv_cu(us, int.from_bytes(x.group(1), "little"))
                        progs.append(us[q:q + n - 1].decode("utf-16-le", "replace"))
            except Exception:   # noqa: BLE001
                continue
    out["com_progids"] = js(dict.fromkeys(progs))
    return out


def dotnet_com_field(data, name):
    """One dotnet_com_facts value: "none" when absent (no COM interop / no such type or method / not a CLI assembly)."""
    try:
        f = dotnet_com_facts(data)
    except Exception:   # noqa: BLE001
        return None
    return "none" if not f else f.get(name, "none")

# ------------------------------------------------------------------ .NET protector artefacts (dotnet-anti-tamper-obfuscation)
# Marker attribute / injected type names -> protector family (de4dot-style detection; the attribute's first SerString arg
# is the version banner, e.g. ConfusedBy("ConfuserEx v1.6.0+447341964f")). de4dot itself needs mono: not in the toolbox.
_DN_PROTECTORS = {"ConfusedByAttribute": "ConfuserEx", "DotfuscatorAttribute": "Dotfuscator", "BabelAttribute": "Babel",
                  "BabelObfuscatorAttribute": "Babel", "PoweredByAttribute": "SmartAssembly",
                  "ObfuscatedByGoliath": "Goliath.NET", "YanoAttribute": "Yano", "ProcessedByXenocode": "Xenocode",
                  "CryptoObfuscatorAttribute": "Crypto Obfuscator", "NETGuardAttribute": "NETGuard",
                  "ObfuscatedByAgileDotNetAttribute": "Agile.NET", "NineRays.Obfuscator.Evaluation": "Spices.Net"}
DN_ANTITAMPER_REGION = 1 << 16   # bytes xor'd per FieldRVA / encrypted-body region in the hcfg_scan branch


def _il_len_ok(code):
    """True when `code` is a complete, valid IL stream (every opcode known, the last operand ends exactly at the end)."""
    if not code:
        return False   # a real body has at least `ret`; zero-length IL = a body the cctor fills in
    ins = il_decode(code)
    if not ins:
        return False
    at, op, arg = ins[-1]
    w = _IL_OPS2.get(op & 0xFF) if op > 0xFF else _IL_OPS.get(op)
    end = at + (2 if op > 0xFF else 1) + (4 + 4 * len(arg) if w == -2 else 4 if w == -1 else w)
    return end == len(code)


def _dn_protector_meta(data):
    """dnfile view shared by dotnet_protector_facts and the anti-tamper hcfg branch, or None when not a CLI PE."""
    try:
        import dnfile
        pe = dnfile.dnPE(data=bytes(data), fast_load=False)
        if pe.net is None or pe.net.mdtables is None:
            return None
    except Exception:   # noqa: BLE001 -- hostile/truncated PE: cannot answer
        return None
    t = pe.net.mdtables
    rows = lambda tab: list(getattr(t, tab, None) or ())   # noqa: E731
    tds, mds = rows("TypeDef"), rows("MethodDef")
    starts = [int(r.struct.MethodList_Index) for r in tds]
    owner = {}
    for k in range(len(tds)):
        for i in range(starts[k], min(starts[k + 1] if k + 1 < len(starts) else len(mds) + 1, len(mds) + 1)):
            owner[i] = k + 1
    bodies = {}   # MethodDef row -> (rva, body dict | None, valid)
    for i, r in enumerate(mds, 1):
        rva = int(r.struct.Rva or 0)
        if not rva:
            continue
        try:
            b = _il_body(pe, rva)
        except Exception:   # noqa: BLE001
            b = None
        ok = bool(b) and len(b["code"]) == b["code_size"] and (b["header"] == "tiny" or (
            b["header_size"] == 12 and b["local_sig"] >> 24 in (0, 0x11))) and _il_len_ok(b["code"])
        bodies[i] = (rva, b, ok)
    return pe, t, rows, tds, mds, owner, bodies


def dotnet_protector_facts(data):
    """.NET protector artefacts via dnfile: obfuscator (family from a marker attribute / injected type: ConfuserEx,
    Dotfuscator, Babel, SmartAssembly, ...), obfuscator_marker (the marker attribute's SerString, e.g. 'ConfuserEx
    v1.6.0+447341964f'; the family when it has no string), has_suppress_ildasm (SuppressIldasmAttribute applied),
    renamed_types (TypeDefs but <Module> whose name has a char outside printable ASCII: unprintable / unicode renaming),
    renamed_type_names (JSON), module_cctor (<Module>..cctor exists), encrypted_bodies (MethodDefs with an RVA whose
    body is unparseable: bad header, overrun, zero-length or invalid IL), cctor_decrypts_bodies (<Module>..cctor +
    encrypted bodies = runtime anti-tamper). "none" values when absent; None when not a CLI assembly."""
    m = _dn_protector_meta(data)
    if m is None:
        return None
    pe, t, rows, tds, mds, owner, bodies = m
    nm = lambda x: "" if x is None else str(x)   # noqa: E731
    trs, mrs = rows("TypeRef"), rows("MemberRef")

    def ca_type(tc):
        if tc & 7 == 3 and 0 < tc >> 3 <= len(mrs):
            c = int(mrs[(tc >> 3) - 1].struct.Class_CodedIndex)
            tab, i = (trs if c & 7 == 1 else tds if c & 7 == 0 else None), c >> 3
            return nm(tab[i - 1].TypeName) if tab and 0 < i <= len(tab) else None
        if tc & 7 == 2:
            k = owner.get(tc >> 3)
            return nm(tds[k - 1].TypeName) if k else None
        return None
    fam, marker, sup = "none", "none", False
    for r in rows("CustomAttribute"):
        try:
            an = ca_type(int(r.struct.Type_CodedIndex))
        except Exception:   # noqa: BLE001
            continue
        if an == "SuppressIldasmAttribute":
            sup = True
        elif an in _DN_PROTECTORS and fam == "none":
            fam = _DN_PROTECTORS[an]
            marker = _dn_serstr(bytes(getattr(r.Value, "value", r.Value) or b"")) or fam
    if fam == "none":   # injected marker type never applied (or applied through a stripped CA row)
        for r in tds + trs:
            if nm(r.TypeName) in _DN_PROTECTORS:
                fam = marker = _DN_PROTECTORS[nm(r.TypeName)]
                break
    renamed = [nm(r.TypeName) for k, r in enumerate(tds, 1)
               if k > 1 and any(not 0x20 <= ord(c) <= 0x7E for c in nm(r.TypeName))]
    cctor = any(owner.get(i) == 1 and nm(r.Name) == ".cctor" for i, r in enumerate(mds, 1))
    enc = sum(1 for _, _, ok in bodies.values() if not ok)
    return {"obfuscator": fam, "obfuscator_marker": marker, "has_suppress_ildasm": "true" if sup else "false",
            "renamed_types": str(len(renamed)),
            "renamed_type_names": json.dumps(renamed, separators=(",", ":"), ensure_ascii=False) if renamed else "none",
            "module_cctor": "true" if cctor else "false", "encrypted_bodies": str(enc),
            "cctor_decrypts_bodies": "true" if cctor and enc else "false"}


_DN_PROT_ALIASES = {"protector": "obfuscator", "packer": "obfuscator", "obfuscator_name": "obfuscator",
                    "marker": "obfuscator_marker", "obfuscator_version": "obfuscator_marker",
                    "suppress_ildasm": "has_suppress_ildasm", "suppressildasm": "has_suppress_ildasm",
                    "renamed": "renamed_types", "renamed_type_count": "renamed_types", "anti_tamper": "cctor_decrypts_bodies",
                    "antitamper": "cctor_decrypts_bodies", "encrypted_methods": "encrypted_bodies"}


def dotnet_protector_field(data, name):
    """One dotnet_protector_facts value: "none" when the field is unknown or `data` is not a CLI assembly."""
    try:
        f = dotnet_protector_facts(data)
    except Exception:   # noqa: BLE001
        return None
    if f is None:
        return "none"
    k = str(name).strip().lower()
    return f.get(_DN_PROT_ALIASES.get(k, k), "none")


def _antitamper_scan(data, emit, late):
    """hcfg_scan branch: a protector's <Module>..cctor (or a method it calls: C# [ModuleInitializer]) xors FieldRVA data
    / method bodies with a 32/64-bit constant at startup. Emulate it: every ldc.i4 (>= 0x100) / ldc.i8 constant of those
    bodies is a repeating little-endian key, phase 0 at the start of each FieldRVA blob and each encrypted body (<= 64
    KiB each); a magic in the xor'd bytes -> 'antitamper-raw' at the blob's first STORED byte, detail key=0x...."""
    m = _dn_protector_meta(data)
    if m is None:
        return
    pe, t, rows, tds, mds, owner, bodies = m
    todo = [i for i, r in enumerate(mds, 1) if owner.get(i) == 1 and str(r.Name) == ".cctor"]
    keys, done = [], set()
    while todo and len(done) < 8:
        i = todo.pop(0)
        if i in done or i not in bodies or not bodies[i][1]:
            continue
        done.add(i)
        for _, op, arg in il_decode(bodies[i][1]["code"]):
            if op == 0x28 and isinstance(arg, int) and arg >> 24 == 0x06:
                todo.append(arg & 0xFFFFFF)   # one call graph hop per callee: the module initializer
            elif op == 0x20 and 0x100 <= arg & 0xFFFFFFFF != 0xFFFFFFFF:
                keys.append((arg & 0xFFFFFFFF).to_bytes(4, "little"))
            elif op == 0x21 and arg & 0xFFFFFFFFFFFFFFFF > 0xFFFFFFFF:
                keys.append((arg & 0xFFFFFFFFFFFFFFFF).to_bytes(8, "little"))
    keys = list(dict.fromkeys(keys))[:16]
    if not keys:
        return
    starts = set()
    for r in rows("FieldRva"):
        try:
            starts.add(pe.get_offset_from_rva(int(r.struct.Rva)))
        except Exception:   # noqa: BLE001
            continue
    for rva, b, ok in bodies.values():
        if not ok:
            try:
                starts.add(pe.get_offset_from_rva(rva))
            except Exception:   # noqa: BLE001
                continue
    starts = sorted(o for o in starts if o is not None and 0 <= o < len(data))
    for n, o in enumerate(starts):
        e = min(len(data), o + DN_ANTITAMPER_REGION, starts[n + 1] if n + 1 < len(starts) else len(data))
        reg = data[o:e]
        if len(reg) < 12:
            continue
        for k in keys:
            if late():
                return
            ks = (k * (len(reg) // len(k) + 1))[:len(reg)]
            dec = (int.from_bytes(reg, "little") ^ int.from_bytes(ks, "little")).to_bytes(len(reg), "little")
            j = dec.find(HCFG_MAGIC)
            while 0 <= j and j + 12 <= len(dec):
                emit(o + j, "antitamper-raw", dec[j:j + _need(dec[j:j + 8])], f"key=0x{k[::-1].hex()} cctor")
                j = dec.find(HCFG_MAGIC, j + 1)


# ------------------------------------------------------------------ .NET IL bodies: call sites, ldstr, array init blobs
# ECMA-335 III opcode operand sizes: -1 = metadata token, -2 = switch table, n = n raw operand bytes; absent = invalid
_IL_OPS = {**{o: 0 for o in (*range(0x00, 0x0E), 0x14, *range(0x15, 0x1F), 0x25, 0x26, 0x2A, *range(0x46, 0x6F), 0x76,
                             0x7A, *range(0x82, 0x8C), 0x8E, *range(0x90, 0xA3), *range(0xB3, 0xBB), 0xC3,
                             *range(0xD1, 0xDD), 0xDF, 0xE0)},
           **{o: 1 for o in (*range(0x0E, 0x14), 0x1F, *range(0x2B, 0x38), 0xDE)},
           **{o: 4 for o in (0x20, 0x22, *range(0x38, 0x45), 0xDD)}, 0x21: 8, 0x23: 8, 0x45: -2,
           **{o: -1 for o in (0x27, 0x28, 0x29, 0x6F, 0x70, 0x71, 0x72, 0x73, 0x74, 0x75, 0x79, *range(0x7B, 0x82), 0x8C,
                              0x8D, 0x8F, 0xA3, 0xA4, 0xA5, 0xC2, 0xC6, 0xD0)}}
_IL_OPS2 = {**{o: 0 for o in (0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x0F, 0x11, 0x13, 0x14, 0x17, 0x18, 0x1A, 0x1D, 0x1E)},
            **{o: 2 for o in range(0x09, 0x0F)}, 0x12: 1, 0x19: 1,
            **{o: -1 for o in (0x06, 0x07, 0x15, 0x16, 0x1C)}}
_IL_CALL_OPS = {0x27: "jmp", 0x28: "call", 0x29: "calli", 0x6F: "callvirt", 0x73: "newobj", 0xFE06: "ldftn",
                0xFE07: "ldvirtftn"}
_IL_MAX_CODE = 1 << 20


def il_decode(code, limit=1 << 18):
    """Decode one IL code stream (ECMA-335 III, single-byte + 0xFE two-byte opcodes) -> [(il_offset, opcode, operand)];
    opcode is 0xFExx for two-byte ops, operand an int (token / immediate / branch delta) or a tuple (switch targets).
    Stops at an invalid opcode or truncated operand (the instructions decoded so far are returned)."""
    out, p, n = [], 0, min(len(code), _IL_MAX_CODE)
    while p < n and len(out) < limit:
        at, op = p, code[p]
        p += 1
        if op == 0xFE:
            if p >= n:
                break
            op = 0xFE00 | code[p]
            p += 1
            sz = _IL_OPS2.get(op & 0xFF)
        else:
            sz = _IL_OPS.get(op)
        if sz is None:
            break
        if sz == -2:
            if p + 4 > n:
                break
            k = int.from_bytes(code[p:p + 4], "little")
            if p + 4 + 4 * k > n:
                break
            arg = tuple(int.from_bytes(code[q:q + 4], "little", signed=True) for q in range(p + 4, p + 4 + 4 * k))
            p += 4 + 4 * k
        else:
            w = 4 if sz == -1 else sz
            if p + w > n:
                break
            arg = int.from_bytes(code[p:p + w], "little", signed=sz in (1, 2, 4, 8) and op not in (0x22, 0x23)) if w else None
            p += w
        out.append((at, op, arg))
    return out


def _il_body(pe, rva):
    """Method body at RVA (ECMA-335 II.25.4): {"header": "tiny"|"fat", "header_size", "code_size", "max_stack",
    "local_sig" (token or 0), "init_locals", "eh_clauses", "code"} or None when unreadable."""
    b0 = pe.get_data(rva, 1)
    if not b0:
        return None
    if b0[0] & 3 == 2:
        n = b0[0] >> 2
        code = pe.get_data(rva + 1, n) if n else b""
        return {"header": "tiny", "header_size": 1, "code_size": n, "max_stack": 8, "local_sig": 0,
                "init_locals": False, "eh_clauses": 0, "code": bytes(code)}
    if b0[0] & 3 != 3:
        return None
    h = pe.get_data(rva, 12)
    if len(h) < 12:
        return None
    fl, ms, n, ls = struct.unpack_from("<HHII", h)
    hs = (fl >> 12) * 4
    if hs < 12 or n > _IL_MAX_CODE:
        return None
    code = bytes(pe.get_data(rva + hs, n))
    eh, s, more = 0, (rva + hs + n + 3) & ~3, fl & 0x8
    for _ in range(16):   # extra data sections (II.25.4.5): EH tables, small (12-byte) or fat (24-byte) clauses
        if not more:
            break
        k = pe.get_data(s, 4)
        if len(k) < 4:
            break
        fat = k[0] & 0x40
        size = int.from_bytes(k[1:4], "little") if fat else k[1]
        if k[0] & 1 and size >= 4:
            eh += (size - 4) // (24 if fat else 12)
        more = k[0] & 0x80
        if size < 4:
            break
        s = (s + size + 3) & ~3
    return {"header": "fat", "header_size": hs, "code_size": n, "max_stack": ms, "local_sig": ls,
            "init_locals": bool(fl & 0x10), "eh_clauses": eh, "code": code}


def dotnet_il_facts(data):
    """IL call-site facts of a .NET (CLI) PE ("trace every crossing") via dnfile + an ECMA-335 III opcode decoder.
    Names are ilspy-style 'Namespace.Type::Method' (nested 'Outer/Inner', no generic args, no [scope]).
    il_methods / il_method_count (MethodDefs with a body, MethodDef order), il_bodies (JSON per body: method, token, rva,
    offset, header tiny|fat, header_size, code_size, max_stack, local_sig, eh_clauses, instructions); call_edges (JSON
    [{"caller","op","callee","kind","il"}] in method/IL order; op call|callvirt|newobj|calli|jmp|ldftn|ldvirtftn, kind
    managed (a MethodDef with a body) | native (an ImplMap P/Invoke) | external (MemberRef/abstract) | indirect (calli));
    managed_edges / native_edges / external_edges (distinct [caller, callee] pairs, first-use order; ldftn excluded --
    see ldftn_edges); pinvoke_callers (JSON {pinvoke method name: [callers]}, ImplMap order) and native_callers (all
    callers of any P/Invoke); user_strings (the whole #US heap in heap order) / user_string_count; ldstr_strings (IL
    order, repeats kept) and ldstr_sites ([{"method","il","string","us_offset"}]); static_field_loads (ldsfld/ldsflda/
    ldtoken field targets, distinct, IL order); array_inits (JSON [{"method","il","field","field_type","rva","offset",
    "size","hex"}] for each ldtoken <field> + RuntimeHelpers::InitializeArray|CreateSpan); field_rvas (every FieldRVA
    field: field, field_type, rva, offset, size -- the C# <PrivateImplementationDetails> / F# T<n>_<len>Bytes@ .text
    data); calli_count. Per-method lookups go through dotnet_il_field. None when not a CLI assembly."""
    try:
        return _dotnet_il_facts(data)
    except Exception:   # noqa: BLE001 -- hostile tables (rows past their targets, bad coded indexes): cannot answer
        return None


def _dotnet_il_facts(data):
    try:
        import dnfile
        pe = dnfile.dnPE(data=bytes(data), fast_load=False)
        net = pe.net
        if net is None or net.mdtables is None:
            return None
        t = net.mdtables
    except Exception:   # noqa: BLE001 -- hostile/truncated PE: cannot answer
        return None
    js = lambda xs: json.dumps(list(xs), separators=(",", ":"), ensure_ascii=False)   # noqa: E731
    rows = lambda tab: list(getattr(t, tab, None) or ())   # noqa: E731
    nm = lambda x: "" if x is None else str(x)   # noqa: E731
    blob = lambda x: bytes(getattr(x, "value", x) or b"")   # noqa: E731
    mds, tds, trs, flds = rows("MethodDef"), rows("TypeDef"), rows("TypeRef"), rows("Field")
    mrs, msp, tsp, sas = rows("MemberRef"), rows("MethodSpec"), rows("TypeSpec"), rows("StandAloneSig")
    enclosing = {}
    for r in rows("NestedClass"):
        try:
            enclosing[int(r.struct.NestedClass_Index)] = int(r.struct.EnclosingClass_Index)
        except Exception:   # noqa: BLE001
            continue
    tdn = {}

    def tdname(i, depth=0):
        if i in tdn:
            return tdn[i]
        if not 0 < i <= len(tds):
            return "?"
        r = tds[i - 1]
        if i in enclosing and depth < 16:
            s = tdname(enclosing[i], depth + 1) + "/" + nm(r.TypeName)
        else:
            s = (nm(r.TypeNamespace) + "." if nm(r.TypeNamespace) else "") + nm(r.TypeName)
        tdn[i] = s
        return s

    def trname(i, depth=0):
        if not 0 < i <= len(trs):
            return "?"
        r = trs[i - 1]
        rs = int(r.struct.ResolutionScope_CodedIndex)
        if rs & 3 == 3 and depth < 16:   # ResolutionScope TypeRef: nested reference
            return trname(rs >> 2, depth + 1) + "/" + nm(r.TypeName)
        return (nm(r.TypeNamespace) + "." if nm(r.TypeNamespace) else "") + nm(r.TypeName)

    def tdor(c):   # TypeDefOrRef coded index (2-bit tag)
        tag, i = c & 3, c >> 2
        return tdname(i) if tag == 0 else trname(i) if tag == 1 else tsname(i) if tag == 2 else "?"

    def tsname(i):
        if not 0 < i <= len(tsp):
            return "?"
        b = blob(tsp[i - 1].Signature)
        try:
            p = 1 if b[0] == 0x15 else 0   # GENERICINST (CLASS|VALUETYPE) TypeDefOrRef ...
            if b[p] in (0x11, 0x12):
                return tdor(_pinv_cu(b, p + 1)[0])
        except IndexError:
            pass
        return "?"
    mowner, starts = {}, [int(r.struct.MethodList_Index) for r in tds]
    fowner, fstarts = {}, [int(r.struct.FieldList_Index) for r in tds]
    for k in range(len(tds)):
        for own, st, total in ((mowner, starts, len(mds)), (fowner, fstarts, len(flds))):
            end = st[k + 1] if k + 1 < len(st) else total + 1
            for i in range(st[k], min(end, total + 1)):
                own[i] = k + 1
    mdname = lambda i: f"{tdname(mowner.get(i, 0))}::{nm(mds[i - 1].Name)}" if 0 < i <= len(mds) else "?"   # noqa: E731
    fdname = lambda i: f"{tdname(fowner.get(i, 0))}::{nm(flds[i - 1].Name)}" if 0 < i <= len(flds) else "?"   # noqa: E731

    def mrname(i):
        if not 0 < i <= len(mrs):
            return "?"
        r = mrs[i - 1]
        c = int(r.struct.Class_CodedIndex)   # MemberRefParent: TypeDef, TypeRef, ModuleRef, MethodDef, TypeSpec
        tag, j = c & 7, c >> 3
        own = {0: tdname, 1: trname, 4: tsname}.get(tag)
        if tag == 3:
            return mdname(j)
        return f"{own(j) if own else '?'}::{nm(r.Name)}"
    pinv = {}   # MethodDef row -> P/Invoke entry info
    mrefs = rows("ModuleRef")
    for r in rows("ImplMap"):
        try:
            fw, sc = int(r.struct.MemberForwarded_CodedIndex), int(r.struct.ImportScope_Index)
            if fw & 1 and 0 < fw >> 1 <= len(mds):
                mi = fw >> 1
                pinv[mi] = (nm(r.ImportName) or nm(mds[mi - 1].Name),
                            nm(mrefs[sc - 1].Name) if 0 < sc <= len(mrefs) else "none")
        except Exception:   # noqa: BLE001
            continue

    pinv_of = {mdname(mi): v for mi, v in pinv.items()}

    def resolve(tok):
        tab, i = tok >> 24, tok & 0xFFFFFF
        if tab == 0x06:
            if i in pinv:
                return mdname(i), "native"
            ok = 0 < i <= len(mds) and int(mds[i - 1].struct.Rva or 0)
            return mdname(i), "managed" if ok else "external"
        if tab == 0x0A:
            c = int(mrs[i - 1].struct.Class_CodedIndex) if 0 < i <= len(mrs) else 0
            if c & 7 == 3:
                return resolve(0x06000000 | c >> 3)
            return mrname(i), "external"
        if tab == 0x2B and 0 < i <= len(msp):
            c = int(msp[i - 1].struct.Method_CodedIndex)   # MethodDefOrRef
            return resolve((0x0A if c & 1 else 0x06) << 24 | c >> 1)
        if tab == 0x11:
            return "calli", "indirect"
        return f"0x{tok:08x}", "external"
    us = b""
    try:
        us = bytes(getattr(net.user_strings, "__data__", b"") or b"")
    except Exception:   # noqa: BLE001
        pass

    def us_at(o):
        try:
            n, q = _pinv_cu(us, o)
            return us[q:q + max(n - 1, 0)].decode("utf-16-le", "replace") if n else ""
        except IndexError:
            return None
    heap, o = [], 1
    while o < len(us) and len(heap) < 100000:
        try:
            n, q = _pinv_cu(us, o)
        except IndexError:
            break
        if n == 0 and q >= len(us):
            break
        if n:
            heap.append(us[q:q + n - 1].decode("utf-16-le", "replace"))
        o = q + n
    clay = {}
    for r in rows("ClassLayout"):
        try:
            clay[int(r.struct.Parent_Index)] = int(r.struct.ClassSize)
        except Exception:   # noqa: BLE001
            continue

    def ftype(i):
        """FieldDef -> (type name, byte size or None) from its signature (II.23.2.4) + ClassLayout."""
        b = blob(flds[i - 1].Signature) if 0 < i <= len(flds) else b""
        try:
            if len(b) > 1 and b[0] == 0x06 and b[1] in (0x11, 0x12):
                c = _pinv_cu(b, 2)[0]
                name = tdor(c)
                size = clay.get(c >> 2) if c & 3 == 0 else None
                if size is None:
                    m = re.search(r"(?:=|_)(\d+)(?:Bytes@)?$", name)
                    size = int(m.group(1)) if m else None
                return name, size
            prim = {0x02: ("bool", 1), 0x03: ("char", 2), 0x04: ("int8", 1), 0x05: ("uint8", 1), 0x06: ("int16", 2),
                    0x07: ("uint16", 2), 0x08: ("int32", 4), 0x09: ("uint32", 4), 0x0A: ("int64", 8), 0x0B: ("uint64", 8),
                    0x0C: ("float32", 4), 0x0D: ("float64", 8)}
            if len(b) > 1 and b[1] in prim:
                return prim[b[1]]
        except IndexError:
            pass
        return "?", None
    frva = {}
    for r in rows("FieldRva"):
        try:
            fi, rva = int(r.struct.Field_Index), int(r.struct.Rva)
            name, size = ftype(fi)
            try:
                off = pe.get_offset_from_rva(rva)
            except Exception:   # noqa: BLE001
                off = None
            frva[fi] = {"field": fdname(fi), "field_type": name, "rva": f"0x{rva:x}",
                        "offset": off, "size": size}
        except Exception:   # noqa: BLE001
            continue
    methods, bodies, edges, sites, sloads, arrays = [], [], [], [], [], []
    calli = 0
    for mi in range(1, len(mds) + 1):
        try:
            rva = int(mds[mi - 1].struct.Rva or 0)
            if not rva or mi in pinv:
                continue
            b = _il_body(pe, rva)
            if b is None:
                continue
            me = mdname(mi)
            ins = il_decode(b["code"])
            methods.append(me)
            try:
                off = pe.get_offset_from_rva(rva)
            except Exception:   # noqa: BLE001
                off = None
            bodies.append({"method": me, "token": f"0x{0x06000000 | mi:08x}", "rva": f"0x{rva:x}", "offset": off,
                           "header": b["header"], "header_size": b["header_size"], "code_size": b["code_size"],
                           "max_stack": b["max_stack"], "local_sig": f"0x{b['local_sig']:08x}" if b["local_sig"] else "none",
                           "eh_clauses": b["eh_clauses"], "instructions": len(ins)})
            for k, (at, op, arg) in enumerate(ins):
                if op in _IL_CALL_OPS:
                    callee, kind = resolve(arg)
                    calli += op == 0x29
                    edges.append({"caller": me, "op": _IL_CALL_OPS[op], "callee": callee, "kind": kind, "il": at})
                    if kind == "native":
                        edges[-1]["entry"], edges[-1]["module"] = pinv_of.get(callee, ("?", "?"))
                elif op == 0x72:
                    s = us_at(arg & 0xFFFFFF) if arg >> 24 == 0x70 else None
                    if s is not None:
                        sites.append({"method": me, "il": at, "string": s, "us_offset": arg & 0xFFFFFF})
                elif op in (0x7E, 0x7F, 0xD0) and arg >> 24 == 0x04:
                    fi = arg & 0xFFFFFF
                    sloads.append(fdname(fi))
                    if op == 0xD0 and k + 1 < len(ins) and ins[k + 1][1] == 0x28:
                        callee, _ = resolve(ins[k + 1][2])
                        if callee.startswith("System.Runtime.CompilerServices.RuntimeHelpers::") and \
                                callee.endswith(("InitializeArray", "CreateSpan")):
                            fr = frva.get(fi) or {"field": fdname(fi), "field_type": ftype(fi)[0], "rva": "none",
                                                  "offset": None, "size": ftype(fi)[1]}
                            hx = "none"
                            if fr["offset"] is not None and fr["size"]:
                                hx = bytes(data[fr["offset"]:fr["offset"] + min(fr["size"], 1 << 16)]).hex()
                            arrays.append({"method": me, "il": at, **fr, "hex": hx})
        except Exception:   # noqa: BLE001 -- one broken body must not hide the others
            continue
    pairs = lambda kinds, ops=("call", "callvirt", "newobj", "calli", "jmp"): list(dict.fromkeys(   # noqa: E731
        (e["caller"], e["callee"]) for e in edges if e["kind"] in kinds and e["op"] in ops))
    pc = {nm(mds[mi - 1].Name): [] for mi in sorted(pinv)}
    for c, callee in pairs(("native",)):
        pc.setdefault(callee.rsplit("::", 1)[-1], []).append(c)
    out = {"il_methods": js(methods), "il_method_count": str(len(methods)), "il_bodies": js(bodies),
           "call_edges": js(edges), "call_edge_count": str(len(edges)),
           "managed_edges": js(map(list, pairs(("managed",)))), "native_edges": js(map(list, pairs(("native",)))),
           "external_edges": js(map(list, pairs(("external",)))),
           "ldftn_edges": js(map(list, pairs(("managed", "external", "native"), ("ldftn", "ldvirtftn")))),
           "pinvoke_callers": json.dumps(pc, separators=(",", ":"), ensure_ascii=False),
           "native_callers": js(dict.fromkeys(c for c, _ in pairs(("native",)))),
           "user_strings": js(heap), "user_string_count": str(len(heap)),
           "ldstr_strings": js(s["string"] for s in sites), "ldstr_sites": js(sites),
           "static_field_loads": js(dict.fromkeys(sloads)), "array_inits": js(arrays),
           "array_init_count": str(len(arrays)), "field_rvas": js(frva[k] for k in sorted(frva)),
           "calli_count": str(calli)}
    return out


def _il_key(q):
    return re.sub(r"[^a-z0-9]", "", str(q).lower())


def dotnet_il_field(data, name):
    """One dotnet_il_facts value by name, plus per-method lookups where <m> is 'Method', 'Type::Method' or
    'Namespace.Type::Method': '<m>_callers' / 'callers:<m>' (distinct callers, any call op), '<m>_callees' / 'calls:<m>'
    (distinct callees), '<m>_strings' (ldstr in IL order), '<m>_array_inits'. "none" when absent; None when not a CLI
    assembly."""
    f = dotnet_il_facts(data)
    if f is None:
        return None
    if name in f:
        return f[name]
    m = re.match(r"^(callers|calls|callees|strings|array_inits):(.+)$", name) or \
        re.match(r"^(.+)_(callers|callees|calls|strings|array_inits)$", name)
    if not m:
        return "none"
    what, who = (m.group(1), m.group(2)) if ":" in name and m.re.pattern.startswith("^(callers") else (m.group(2), m.group(1))
    hit = lambda full: full == who or full.endswith("::" + who) or full.endswith("." + who) or full.endswith("/" + who)   # noqa: E731
    js = lambda xs: json.dumps(list(xs), separators=(",", ":"), ensure_ascii=False)   # noqa: E731
    edges = [e for e in json.loads(f["call_edges"]) if e["op"] not in ("ldftn", "ldvirtftn")]
    if what == "callers":
        got = [e["caller"] for e in edges if hit(e["callee"]) or e.get("entry") == who]
        known = any(hit(x) for x in json.loads(f["il_methods"])) or got or \
            any(hit(e["callee"]) for e in json.loads(f["call_edges"])) or who in json.loads(f["pinvoke_callers"])
        return js(dict.fromkeys(got)) if known else "none"
    if not any(hit(x) for x in json.loads(f["il_methods"])):
        return "none"
    if what in ("calls", "callees"):
        return js(dict.fromkeys(e["callee"] for e in edges if hit(e["caller"])))
    if what == "strings":
        return js(s["string"] for s in json.loads(f["ldstr_sites"]) if hit(s["method"]))
    return js(a for a in json.loads(f["array_inits"]) if hit(a["method"]))


# --- .NET twin patch diff (vulnerable/corrected CLI assemblies) ---------------------------------------------------
# Methods match by 'Namespace.Type::Method(sig)' (sig types resolved to names, so metadata-token renumbering, the MVID
# and the PE timestamp never count). IL bodies compare as decoded instructions with tokens resolved (calls/fields/
# types by name, ldstr by literal, branches by target instruction index) plus the exception clauses.
_MPD_OPN = dict((int(k, 16), v) for k, v in zip(*[iter((
    "00 nop 01 break 02 ldarg.0 03 ldarg.1 04 ldarg.2 05 ldarg.3 06 ldloc.0 07 ldloc.1 08 ldloc.2 09 ldloc.3 0a stloc.0 "
    "0b stloc.1 0c stloc.2 0d stloc.3 0e ldarg.s 0f ldarga.s 10 starg.s 11 ldloc.s 12 ldloca.s 13 stloc.s 14 ldnull "
    "15 ldc.i4.m1 16 ldc.i4.0 17 ldc.i4.1 18 ldc.i4.2 19 ldc.i4.3 1a ldc.i4.4 1b ldc.i4.5 1c ldc.i4.6 1d ldc.i4.7 "
    "1e ldc.i4.8 1f ldc.i4.s 20 ldc.i4 21 ldc.i8 22 ldc.r4 23 ldc.r8 25 dup 26 pop 27 jmp 28 call 29 calli 2a ret "
    "2b br.s 2c brfalse.s 2d brtrue.s 2e beq.s 2f bge.s 30 bgt.s 31 ble.s 32 blt.s 33 bne.un.s 34 bge.un.s 35 bgt.un.s "
    "36 ble.un.s 37 blt.un.s 38 br 39 brfalse 3a brtrue 3b beq 3c bge 3d bgt 3e ble 3f blt 40 bne.un 41 bge.un "
    "42 bgt.un 43 ble.un 44 blt.un 45 switch 46 ldind.i1 47 ldind.u1 48 ldind.i2 49 ldind.u2 4a ldind.i4 4b ldind.u4 "
    "4c ldind.i8 4d ldind.i 4e ldind.r4 4f ldind.r8 50 ldind.ref 51 stind.ref 52 stind.i1 53 stind.i2 54 stind.i4 "
    "55 stind.i8 56 stind.r4 57 stind.r8 58 add 59 sub 5a mul 5b div 5c div.un 5d rem 5e rem.un 5f and 60 or 61 xor "
    "62 shl 63 shr 64 shr.un 65 neg 66 not 67 conv.i1 68 conv.i2 69 conv.i4 6a conv.i8 6b conv.r4 6c conv.r8 6d conv.u4 "
    "6e conv.u8 6f callvirt 70 cpobj 71 ldobj 72 ldstr 73 newobj 74 castclass 75 isinst 76 conv.r.un 79 unbox 7a throw "
    "7b ldfld 7c ldflda 7d stfld 7e ldsfld 7f ldsflda 80 stsfld 81 stobj 82 conv.ovf.i1.un 83 conv.ovf.i2.un "
    "84 conv.ovf.i4.un 85 conv.ovf.i8.un 86 conv.ovf.u1.un 87 conv.ovf.u2.un 88 conv.ovf.u4.un 89 conv.ovf.u8.un "
    "8a conv.ovf.i.un 8b conv.ovf.u.un 8c box 8d newarr 8e ldlen 8f ldelema 90 ldelem.i1 91 ldelem.u1 92 ldelem.i2 "
    "93 ldelem.u2 94 ldelem.i4 95 ldelem.u4 96 ldelem.i8 97 ldelem.i 98 ldelem.r4 99 ldelem.r8 9a ldelem.ref "
    "9b stelem.i 9c stelem.i1 9d stelem.i2 9e stelem.i4 9f stelem.i8 a0 stelem.r4 a1 stelem.r8 a2 stelem.ref a3 ldelem "
    "a4 stelem a5 unbox.any b3 conv.ovf.i1 b4 conv.ovf.u1 b5 conv.ovf.i2 b6 conv.ovf.u2 b7 conv.ovf.i4 b8 conv.ovf.u4 "
    "b9 conv.ovf.i8 ba conv.ovf.u8 c2 refanyval c3 ckfinite c6 mkrefany d0 ldtoken d1 conv.u2 d2 conv.u1 d3 conv.i "
    "d4 conv.ovf.i d5 conv.ovf.u d6 add.ovf d7 add.ovf.un d8 mul.ovf d9 mul.ovf.un da sub.ovf db sub.ovf.un "
    "dc endfinally dd leave de leave.s df stind.i e0 conv.u fe00 arglist fe01 ceq fe02 cgt fe03 cgt.un fe04 clt "
    "fe05 clt.un fe06 ldftn fe07 ldvirtftn fe09 ldarg fe0a ldarga fe0b starg fe0c ldloc fe0d ldloca fe0e stloc "
    "fe0f localloc fe11 endfilter fe12 unaligned. fe13 volatile. fe14 tail. fe15 initobj fe16 constrained. fe17 cpblk "
    "fe18 initblk fe19 no. fe1a rethrow fe1c sizeof fe1d refanytype fe1e readonly.").split())] * 2))
_MPD_ET = {0x01: "void", 0x02: "bool", 0x03: "char", 0x04: "sbyte", 0x05: "byte", 0x06: "short", 0x07: "ushort",
           0x08: "int", 0x09: "uint", 0x0A: "long", 0x0B: "ulong", 0x0C: "float", 0x0D: "double", 0x0E: "string",
           0x16: "typedref", 0x18: "nint", 0x19: "nuint", 0x1C: "object"}
_MPD_REF_ET = (0x0E, 0x12, 0x14, 0x1C, 0x1D)   # string, class, array, object, szarray: a null-testable value
_MPD_OVF = ("add.ovf", "add.ovf.un", "sub.ovf", "sub.ovf.un", "mul.ovf", "mul.ovf.un")
_MPD_NULLCALL = re.compile(r"(ArgumentNullException(::\.ctor|::ThrowIfNull)|::IsNullOrEmpty|::IsNullOrWhiteSpace|"
                           r"::ReferenceEquals|Objects?::IsNull|ArgumentException::ThrowIfNullOr\w+)$")


def _mpd_sig_type(b, p, tdor, depth=0):
    """One ECMA-335 II.23.2.12 Type at p -> (text, next, is_reference)."""
    if depth > 24:
        raise ValueError("deep sig")
    e = b[p]
    p += 1
    if e in _MPD_ET:
        return _MPD_ET[e], p, e in _MPD_REF_ET
    if e in (0x1F, 0x20):   # cmod_reqd / cmod_opt TypeDefOrRef Type
        _, p = _pinv_cu(b, p)
        return _mpd_sig_type(b, p, tdor, depth + 1)
    if e in (0x0F, 0x10, 0x45, 0x1D):
        t, p, _ = _mpd_sig_type(b, p, tdor, depth + 1)
        return {0x0F: t + "*", 0x10: t + "&", 0x45: t, 0x1D: t + "[]"}[e], p, e == 0x1D
    if e in (0x11, 0x12):
        c, p = _pinv_cu(b, p)
        return tdor(c), p, e == 0x12
    if e in (0x13, 0x1E):
        n, p = _pinv_cu(b, p)
        return ("!" if e == 0x13 else "!!") + str(n), p, False
    if e == 0x15:
        k = b[p]
        c, p = _pinv_cu(b, p + 1)
        n, p = _pinv_cu(b, p)
        args = []
        for _ in range(min(n, 64)):
            t, p, _ = _mpd_sig_type(b, p, tdor, depth + 1)
            args.append(t)
        return f"{tdor(c)}<{','.join(args)}>", p, k == 0x12
    if e == 0x14:
        t, p, _ = _mpd_sig_type(b, p, tdor, depth + 1)
        rank, p = _pinv_cu(b, p)
        for _ in range(2):   # NumSizes Size*, NumLoBounds LoBound*
            n, p = _pinv_cu(b, p)
            for _ in range(min(n, 64)):
                _, p = _pinv_cu(b, p)
        return f"{t}[{',' * max(rank - 1, 0)}]", p, True
    if e == 0x1B:
        return "fnptr", len(b), False   # rare: the rest of the blob is the pointee method sig
    raise ValueError(f"element 0x{e:02x}")


def _mpd_method_sig(b, tdor):
    """MethodDefSig -> ("(params)ret", [param is_reference], ret is_reference); ("?", [], False) when unreadable."""
    try:
        p = 1 + (b[0] & 0x10 and 1)
        if b[0] & 0x10:
            _, p = _pinv_cu(b, 1)
        n, p = _pinv_cu(b, p)
        r, p, rref = _mpd_sig_type(b, p, tdor)
        ps, refs = [], []
        for _ in range(min(n, 256)):
            if b[p] == 0x41:   # SENTINEL (vararg)
                p += 1
            t, p, isref = _mpd_sig_type(b, p, tdor)
            ps.append(t)
            refs.append(isref)
        return f"({','.join(ps)}){r}", refs, rref
    except (IndexError, ValueError):
        return "?", [], False


def _mpd_assembly(data):
    """{method key: body facts} + meta for one CLI assembly; None when not one."""
    import dnfile
    pe = dnfile.dnPE(data=bytes(data), fast_load=False)
    net = pe.net
    if net is None or net.mdtables is None:
        return None
    t = net.mdtables
    rows = lambda tab: list(getattr(t, tab, None) or ())   # noqa: E731
    nm = lambda x: "" if x is None else str(x)   # noqa: E731
    blob = lambda x: bytes(getattr(x, "value", x) or b"")   # noqa: E731
    mds, tds, trs, flds = rows("MethodDef"), rows("TypeDef"), rows("TypeRef"), rows("Field")
    mrs, msp, tsp, sas = rows("MemberRef"), rows("MethodSpec"), rows("TypeSpec"), rows("StandAloneSig")
    if not mds:
        return None
    enclosing = {}
    for r in rows("NestedClass"):
        enclosing[int(r.struct.NestedClass_Index)] = int(r.struct.EnclosingClass_Index)

    def tdname(i, depth=0):
        if not 0 < i <= len(tds):
            return "?"
        r = tds[i - 1]
        if i in enclosing and depth < 16:
            return tdname(enclosing[i], depth + 1) + "/" + nm(r.TypeName)
        return (nm(r.TypeNamespace) + "." if nm(r.TypeNamespace) else "") + nm(r.TypeName)

    def trname(i, depth=0):
        if not 0 < i <= len(trs):
            return "?"
        r = trs[i - 1]
        rs = int(r.struct.ResolutionScope_CodedIndex)
        if rs & 3 == 3 and depth < 16:
            return trname(rs >> 2, depth + 1) + "/" + nm(r.TypeName)
        return (nm(r.TypeNamespace) + "." if nm(r.TypeNamespace) else "") + nm(r.TypeName)

    def tsname(i, depth=0):
        if not 0 < i <= len(tsp) or depth > 4:
            return "?"
        try:
            return _mpd_sig_type(blob(tsp[i - 1].Signature), 0, lambda c: tdor(c, depth + 1))[0]
        except (IndexError, ValueError):
            return "?"

    def tdor(c, depth=0):
        tag, i = c & 3, c >> 2
        return tdname(i) if tag == 0 else trname(i) if tag == 1 else tsname(i, depth) if tag == 2 else "?"
    mowner, fowner = {}, {}
    for own, attr, total in ((mowner, "MethodList_Index", len(mds)), (fowner, "FieldList_Index", len(flds))):
        st = [int(getattr(r.struct, attr)) for r in tds]
        for k in range(len(tds)):
            end = st[k + 1] if k + 1 < len(st) else total + 1
            for i in range(st[k], min(end, total + 1)):
                own[i] = k + 1
    msig = [_mpd_method_sig(blob(r.Signature), tdor) for r in mds]

    def fref(b):   # FieldSig: 0x06 Type
        try:
            return _mpd_sig_type(b, 1, tdor)[2] if b and b[0] == 0x06 else False
        except (IndexError, ValueError):
            return False

    def member(tok):
        """token -> (name, returns-a-reference?)"""
        tab, i = tok >> 24, tok & 0xFFFFFF
        if tab == 0x06 and 0 < i <= len(mds):
            return f"{tdname(mowner.get(i, 0))}::{nm(mds[i - 1].Name)}", msig[i - 1][2]
        if tab == 0x04 and 0 < i <= len(flds):
            return f"{tdname(fowner.get(i, 0))}::{nm(flds[i - 1].Name)}", fref(blob(flds[i - 1].Signature))
        if tab == 0x0A and 0 < i <= len(mrs):
            r = mrs[i - 1]
            c = int(r.struct.Class_CodedIndex)
            tag, j = c & 7, c >> 3
            own = mdname = None
            if tag == 3 and 0 < j <= len(mds):
                mdname = f"{tdname(mowner.get(j, 0))}::{nm(mds[j - 1].Name)}"
            own = {0: tdname, 1: trname, 4: tsname}.get(tag)
            sb = blob(r.Signature)
            isref = fref(sb) if sb[:1] == b"\x06" else _mpd_method_sig(sb, tdor)[2]
            name = mdname or f"{re.sub(r'<.*>$', '', own(j)) if own else '?'}::{nm(r.Name)}"
            return name, isref
        if tab == 0x2B and 0 < i <= len(msp):
            c = int(msp[i - 1].struct.Method_CodedIndex)
            return member((0x0A if c & 1 else 0x06) << 24 | c >> 1)
        if tab in (0x01, 0x02, 0x1B):
            return {0x01: trname, 0x02: tdname, 0x1B: tsname}[tab](i), False
        if tab == 0x11:
            return "sig", False
        return "?", False
    us = bytes(getattr(net.user_strings, "__data__", b"") or b"") if net.user_strings else b""

    def us_at(o):
        try:
            n, q = _pinv_cu(us, o)
            return us[q:q + max(n - 1, 0)].decode("utf-16-le", "replace")
        except IndexError:
            return "?"

    def locals_ref(tok):
        i = tok & 0xFFFFFF
        if tok >> 24 != 0x11 or not 0 < i <= len(sas):
            return []
        b = blob(sas[i - 1].Signature)
        try:
            if b[0] != 0x07:
                return []
            n, p = _pinv_cu(b, 1)
            out = []
            for _ in range(min(n, 1024)):
                if b[p] == 0x16:   # TYPEDBYREF local
                    out.append(False)
                    p += 1
                    continue
                _, p, isref = _mpd_sig_type(b, p, tdor)
                out.append(isref)
            return out
        except (IndexError, ValueError):
            return []
    methods, mvid = {}, ""
    try:
        mvid = str(rows("Module")[0].Mvid)
    except Exception:   # noqa: BLE001
        pass
    for i, r in enumerate(mds, 1):
        full = f"{tdname(mowner.get(i, 0))}::{nm(r.Name)}"
        sig, prefs, _ = msig[i - 1]
        key = full + sig
        k2, n = key, 1
        while k2 in methods:   # same name+sig twice (hostile/obfuscated): keep both, by MethodDef order
            n += 1
            k2 = f"{key}#{n}"
        rva = int(r.struct.Rva or 0)
        body = _mpd_body(pe, rva) if rva else None
        methods[k2] = {"name": full, "sig": sig, "flags": int(r.struct.Flags or 0),
                       "body": body and _mpd_norm(body, member, us_at, prefs, locals_ref(body["local_sig"]),
                                                  bool(int(r.struct.Flags or 0) & 0x10))}
    return {"methods": methods, "mvid": mvid, "size": len(data)}


def _mpd_body(pe, rva):
    """_il_body + the decoded exception clauses [(flags, try_off, try_len, h_off, h_len, class_token|filter_off)]."""
    b = _il_body(pe, rva)
    if not b:
        return None
    b["clauses"] = []
    if b["header"] != "fat":
        return b
    fl = int.from_bytes(pe.get_data(rva, 2), "little")
    s, more = (rva + b["header_size"] + b["code_size"] + 3) & ~3, fl & 0x8
    for _ in range(16):
        if not more:
            break
        k = pe.get_data(s, 4)
        if len(k) < 4:
            break
        fat = k[0] & 0x40
        size = int.from_bytes(k[1:4], "little") if fat else k[1]
        if size < 4:
            break
        if k[0] & 1:
            raw, w = pe.get_data(s + 4, size - 4), 24 if fat else 12
            for q in range(0, min(len(raw), size - 4) - w + 1, w):
                b["clauses"].append(struct.unpack_from("<IIIIII" if fat else "<HHBHBI", raw, q))
        more = k[0] & 0x80
        s = (s + size + 3) & ~3
    return b


def _mpd_norm(b, member, us_at, prefs, lrefs, static):
    ins = il_decode(b["code"])
    at = {o: n for n, (o, _, _) in enumerate(ins)}
    at[len(b["code"])] = len(ins)
    nxt = [ins[n + 1][0] if n + 1 < len(ins) else len(b["code"]) for n in range(len(ins))]
    toks, ops, calls, strs = [], [], [], []
    for n, (o, op, arg) in enumerate(ins):
        name = _MPD_OPN.get(op, f"0x{op:x}")
        ops.append(name)
        sz = _IL_OPS2.get(op & 0xFF) if op > 0xFF else _IL_OPS.get(op)
        if op == 0x72:
            v = "str:" + us_at(arg & 0xFFFFFF)
            strs.append(v[4:])
        elif sz == -1:
            v = member(arg)[0]
            if op in _IL_CALL_OPS:
                calls.append(v)
        elif op == 0x45:
            v = tuple(at.get(nxt[n] + d, -1) for d in arg)
        elif name.startswith(("b", "leave")) and name not in ("box", "break"):
            v = at.get(nxt[n] + arg, -1)
        else:
            v = arg
        toks.append((name, v))
    cl = []
    for c in b["clauses"]:
        kind = {0: "catch", 1: "filter", 2: "finally", 4: "fault"}.get(c[0] & 7, "?")
        cls = member(c[5])[0] if kind == "catch" else at.get(c[5], -1) if kind == "filter" else None
        cl.append((kind, at.get(c[1], -1), at.get(c[1] + c[2], -1), at.get(c[3], -1), at.get(c[3] + c[4], -1), cls))

    def isref(n):   # does instruction n push a null-testable reference?
        nm_, v = toks[n]
        op = ins[n][1]
        if nm_ in ("dup", "isinst", "ldnull"):
            return True
        a = {0x02: 0, 0x03: 1, 0x04: 2, 0x05: 3, 0x0E: -1, 0xFE09: -1}.get(op)
        if a is not None:
            j = (ins[n][2] if a < 0 else a) - (0 if static else 1)
            return j < 0 if not static and j == -1 else 0 <= j < len(prefs) and prefs[j]
        lo = {0x06: 0, 0x07: 1, 0x08: 2, 0x09: 3, 0x11: -1, 0xFE0C: -1}.get(op)
        if lo is not None:
            j = ins[n][2] if lo < 0 else lo
            return 0 <= j < len(lrefs) and lrefs[j]
        if op in (0x28, 0x6F, 0x7B, 0x7E):
            return member(ins[n][2])[1]
        return False
    cmp = re.compile(r"^(c(eq|gt|lt)(\.un)?|b(eq|ne|ge|gt|le|lt)(\.un)?(\.s)?)$")
    null = bounds = 0
    for n, (nm_, v) in enumerate(toks):
        if nm_ == "ldnull" and n + 1 < len(toks) and re.match(r"^(ceq|cgt\.un|beq|bne\.un)", toks[n + 1][0]):
            null += 1
        elif nm_.startswith(("brtrue", "brfalse")) and n and isref(n - 1):
            null += 1
        elif nm_ in ("call", "callvirt", "newobj") and _MPD_NULLCALL.search(str(v)):
            null += 1
        if nm_ == "ldlen" or (nm_ in ("call", "callvirt") and re.search(r"::get_(Length|Count)$", str(v))):
            for m in range(n + 1, min(n + 4, len(toks))):
                if cmp.match(toks[m][0]):
                    bounds += 1
                    break
                if not toks[m][0].startswith(("conv.", "ldarg", "ldloc", "ldc.")):
                    break
    return {"tokens": toks, "eh": cl, "ops": ops, "calls": calls, "strings": strs, "code_size": b["code_size"],
            "max_stack": b["max_stack"], "null": null, "bounds": bounds,
            "ovf": sum(o in _MPD_OVF for o in ops), "conv_ovf": sum(o.startswith("conv.ovf") for o in ops)}


def dotnet_patch_diff(dll_a, dll_b):
    """IL method-body diff of twin .NET (CLI) builds (A = before/vulnerable, B = after/corrected) -> {field: answer
    string}; None when either side is not a CLI assembly. Methods match by 'Namespace.Type::Method(sig)'; tokens are
    resolved to names / string literals, so token renumbering, MVID and timestamp never count. Fields: changed_methods /
    changed_method_names ('Namespace.Type::Method') / changed_method(_signature) / changed_method_count, changed_type(s),
    unchanged_method_count, added_/removed_methods, methods_compared, mvid_changed, code_size_ / instruction_count_ /
    max_stack_ / eh_clause_count_ / eh_kinds_ / catch_types_ / null_checks_ / bounds_checks_ / checked_ops_{a,b},
    added_/removed_calls, added_/removed_strings, added_/removed_opcodes, null_guard_added, bounds_check_added,
    checked_arithmetic_added, try_catch_added, exception_clauses_added, guard_added, fix_kind (null_guard |
    bounds_check | checked_arithmetic | exception_handling | constant_change | logic_change | method_added |
    method_removed | none). _before/_after and _vulnerable/_corrected alias every _a/_b field."""
    try:
        return _dotnet_patch_diff(dll_a, dll_b)
    except Exception:   # noqa: BLE001 -- malformed / decoy input: no answer
        return None


def _dotnet_patch_diff(dll_a, dll_b):
    if dll_a[:2] != b"MZ" or dll_b[:2] != b"MZ":
        return None
    A, B = _mpd_assembly(dll_a), _mpd_assembly(dll_b)
    if not A or not B:
        return None
    ma, mb = A["methods"], B["methods"]
    sig = lambda m: m["body"] and (m["body"]["tokens"], m["body"]["eh"])   # noqa: E731
    ch = [k for k in ma if k in mb and (sig(ma[k]) != sig(mb[k]) or ma[k]["flags"] != mb[k]["flags"])]
    added = [k for k in mb if k not in ma]
    removed = [k for k in ma if k not in mb]
    same = [k for k in ma if k in mb and k not in ch]
    tyname = lambda k: k.split("::")[0]   # noqa: E731
    types = list(dict.fromkeys(tyname(k) for k in ch + added + removed))
    f = {"methods_compared": str(len(same) + len(ch)), "changed_methods": _jv([ma[k]["name"] for k in ch]),
         "changed_method_names": _jv([ma[k]["name"].split("::", 1)[1] for k in ch]),
         "changed_method_signatures": _jv(ch), "changed_method_count": str(len(ch)),
         "unchanged_method_count": str(len(same)), "changed_types": _jv(types), "changed_type_count": str(len(types)),
         "changed_type": types[0] if types else "none",
         "added_methods": _jv([mb[k]["name"] for k in added]), "removed_methods": _jv([ma[k]["name"] for k in removed]),
         "added_method_count": str(len(added)), "removed_method_count": str(len(removed)),
         "mvid_a": A["mvid"] or "none", "mvid_b": B["mvid"] or "none",
         "mvid_changed": _jv(A["mvid"] != B["mvid"]), "assembly_size_a": str(A["size"]),
         "assembly_size_b": str(B["size"])}
    first = ch[0] if ch else None
    f["changed_method"] = ma[first]["name"] if first else "none"
    f["changed_method_short"] = ma[first]["name"].split("::", 1)[1] if first else "none"
    f["changed_method_signature"] = first or "none"
    xa = ma[first]["body"] if first else None
    xb = mb[first]["body"] if first else None
    for side, x in (("a", xa), ("b", xb)):
        f[f"code_size_{side}"] = str(x["code_size"]) if x else "none"
        f[f"instruction_count_{side}"] = str(len(x["ops"])) if x else "none"
        f[f"max_stack_{side}"] = str(x["max_stack"]) if x else "none"
        f[f"eh_clause_count_{side}"] = str(len(x["eh"])) if x else "none"
        f[f"eh_kinds_{side}"] = _jv([c[0] for c in x["eh"]]) if x else "none"
        f[f"catch_types_{side}"] = _jv(list(dict.fromkeys(c[5] for c in x["eh"] if c[0] == "catch"))) if x else "none"
        f[f"null_checks_{side}"] = str(x["null"]) if x else "none"
        f[f"bounds_checks_{side}"] = str(x["bounds"]) if x else "none"
        f[f"checked_ops_{side}"] = str(x["ovf"]) if x else "none"
    # whole-diff deltas: every changed method (a body that only exists on one side counts as empty)
    na = nb = 0
    ca, cb, sa, sb, oa, ob = [], [], [], [], [], []
    d = {"null": 0, "bounds": 0, "ovf": 0, "eh": 0}
    for k in ch:
        x, y = ma[k]["body"] or {}, mb[k]["body"] or {}
        ca += x.get("calls", [])
        cb += y.get("calls", [])
        sa += x.get("strings", [])
        sb += y.get("strings", [])
        oa += x.get("ops", [])
        ob += y.get("ops", [])
        for q in ("null", "bounds", "ovf"):
            d[q] += y.get(q, 0) - x.get(q, 0)
        d["eh"] += len(y.get("eh", ())) - len(x.get("eh", ()))
        na += len(x.get("eh", ()))
        nb += len(y.get("eh", ()))
    uniq = lambda xs: list(dict.fromkeys(xs))   # noqa: E731
    f["added_calls"] = _jv(uniq(x for x in cb if x not in ca))
    f["removed_calls"] = _jv(uniq(x for x in ca if x not in cb))
    f["added_strings"] = _jv(uniq(x for x in sb if x not in sa))
    f["removed_strings"] = _jv(uniq(x for x in sa if x not in sb))
    f["added_opcodes"] = _jv(sorted({o for o in ob if ob.count(o) > oa.count(o)}))
    f["removed_opcodes"] = _jv(sorted({o for o in oa if oa.count(o) > ob.count(o)}))
    f["null_guard_added"] = _jv(d["null"] > 0)
    f["bounds_check_added"] = _jv(d["bounds"] > 0)
    f["checked_arithmetic_added"] = _jv(d["ovf"] > 0)
    f["try_catch_added"] = _jv(d["eh"] > 0)
    f["exception_clauses_added"] = str(max(d["eh"], 0))
    f["guard_added"] = _jv(d["null"] > 0 or d["bounds"] > 0)
    if not ch:
        kind = "method_added" if added else "method_removed" if removed else "none"
    elif d["null"] > 0:
        kind = "null_guard"
    elif d["bounds"] > 0:
        kind = "bounds_check"
    elif d["ovf"] > 0:
        kind = "checked_arithmetic"
    elif d["eh"] > 0:
        kind = "exception_handling"
    elif all([n for n, _ in (ma[k]["body"] or {}).get("tokens", [])] == [n for n, _ in (mb[k]["body"] or {}).get(
            "tokens", [])] for k in ch):
        kind = "constant_change"
    else:
        kind = "logic_change"
    f["fix_kind"] = kind
    for k in [k for k in f if k.endswith(("_a", "_b"))]:
        base, s = k[:-2], k[-1]
        f[base + ("_before" if s == "a" else "_after")] = f[k]
        f[base + ("_vulnerable" if s == "a" else "_corrected")] = f[k]
    return f


def dotnet_patch_diff_field(dll_a, dll_b, field):
    """One dotnet_patch_diff fact as an answer string; "none" when absent, None when the inputs aren't CLI twins."""
    f = dotnet_patch_diff(dll_a, dll_b)
    return None if f is None else f.get(field, "none")


def dotnet_field_owner(data, offset):
    """Which FieldRVA field owns file offset `offset` (e.g. an HCFG hit inside .text of a .NET assembly): the
    field_rvas record + "delta" (offset - field data start) + "initialized_by" (methods that InitializeArray it), or
    None when no RVA field covers it / not a CLI assembly."""
    f = dotnet_il_facts(data)
    if f is None:
        return None
    for r in json.loads(f["field_rvas"]):
        if r["offset"] is not None and r["size"] and r["offset"] <= offset < r["offset"] + r["size"]:
            ini = [a["method"] for a in json.loads(f["array_inits"]) if a["field"] == r["field"]]
            return dict(r, delta=offset - r["offset"], initialized_by=list(dict.fromkeys(ini)))
    return None


_COR_FLAGS = ((0x1, "ILONLY"), (0x2, "32BITREQUIRED"), (0x4, "IL_LIBRARY"), (0x8, "STRONGNAMESIGNED"),
              (0x10, "NATIVE_ENTRYPOINT"), (0x10000, "TRACKDEBUGDATA"), (0x20000, "32BITPREFERRED"))
_VTF_FLAGS = ((0x1, "32BIT"), (0x2, "64BIT"), (0x4, "FROM_UNMANAGED"), (0x8, "FROM_UNMANAGED_RETAIN_APPDOMAIN"),
              (0x10, "CALL_MOST_DERIVED"))
_SC_ALLOC = {"virtualalloc", "virtualallocex", "virtualalloc2", "virtualallocexnuma", "virtualprotect",
             "virtualprotectex", "ntallocatevirtualmemory", "zwallocatevirtualmemory", "ntprotectvirtualmemory",
             "zwprotectvirtualmemory", "mmap", "mmap64", "mprotect", "heapcreate", "heapalloc"}
_SC_EXEC = ("Marshal::Copy", "Marshal::GetDelegateForFunctionPointer", "Marshal::WriteByte", "Marshal::WriteInt32",
            "Marshal::WriteInt64", "Buffer::MemoryCopy", "Unsafe::CopyBlock")


def _sc_emulate(code, mode):
    """Run a position-independent stub with unicorn until it returns to a sentinel: (return int32 signed, full
    return register) or None (fault / no ret within 100k instructions)."""
    try:
        import unicorn as U
        base, stk, sent = 0x10000000, 0x20000000, 0x30000000
        if mode == "AArch64":
            from unicorn import arm64_const as A
            mu = U.Uc(U.UC_ARCH_ARM64, U.UC_MODE_ARM)
            sp, lr, ret, pc = A.UC_ARM64_REG_SP, A.UC_ARM64_REG_LR, A.UC_ARM64_REG_X0, A.UC_ARM64_REG_PC
        else:
            from unicorn import x86_const as X
            b64 = mode == "x86-64"
            mu = U.Uc(U.UC_ARCH_X86, U.UC_MODE_64 if b64 else U.UC_MODE_32)
            sp, lr = (X.UC_X86_REG_RSP if b64 else X.UC_X86_REG_ESP), None
            ret, pc = (X.UC_X86_REG_RAX if b64 else X.UC_X86_REG_EAX), (X.UC_X86_REG_RIP if b64 else X.UC_X86_REG_EIP)
        mu.mem_map(base, (len(code) + 0xFFFF) & ~0xFFF)
        mu.mem_write(base, bytes(code))
        mu.mem_map(stk, 0x20000)
        top = stk + 0x10000
        if lr is None:
            mu.mem_write(top, sent.to_bytes(8 if mode == "x86-64" else 4, "little"))
        else:
            mu.reg_write(lr, sent)
        mu.reg_write(sp, top)
        mu.emu_start(base, sent, timeout=300_000, count=100_000)
        if mu.reg_read(pc) != sent:
            return None
        v = mu.reg_read(ret)
        lo = v & 0xFFFFFFFF
        return lo - (1 << 32) if lo >> 31 else lo, v
    except Exception:   # noqa: BLE001 -- faults, unmapped access, bad opcodes: no answer
        return None


def _sc_disasm(code, mode, limit=256):
    """[ 'mnemonic op_str' ] linear sweep with capstone, and whether it covered every byte."""
    try:
        import capstone as C
        if mode == "AArch64":
            md = C.Cs(C.CS_ARCH_ARM64, C.CS_MODE_ARM)
        else:
            md = C.Cs(C.CS_ARCH_X86, C.CS_MODE_64 if mode == "x86-64" else C.CS_MODE_32)
        ins, end = [], 0
        for i in md.disasm(bytes(code), 0):
            ins.append((i.mnemonic + " " + i.op_str).strip())
            end = i.address + i.size
            if len(ins) >= limit:
                break
        return ins, end >= len(code)
    except Exception:   # noqa: BLE001
        return [], False


def dotnet_native_facts(data):
    """Native code inside or carried by a .NET (CLI) assembly. COR20 header: cor20_flags ("0x%08x"), cor20_flag_names
    (JSON, ILONLY 32BITREQUIRED IL_LIBRARY STRONGNAMESIGNED NATIVE_ENTRYPOINT TRACKDEBUGDATA 32BITPREFERRED),
    cor20_version (major.minor), ilonly / mixed_mode (ILONLY clear and not R2R: C++/CLI) / 32bit_required / 32bit_preferred
    true|false, entry_point (MethodDef token "0x06......" or native RVA when NATIVE_ENTRYPOINT, "none"); machine (R2R
    OS cookie removed); vtfixup_rva / vtfixup_size / vtfixup_count (entries) / vtfixup_slots (sum of counts) /
    vtfixups (JSON [{"rva","count","type","kinds","tokens"}]); readytorun (ManagedNativeHeader 'RTR'); has_native_code
    (mixed mode, VTableFixups or R2R). Shellcode carried as data: a byte[] initialiser (ldtoken + InitializeArray) whose
    method -- or a method of the same type -- reaches an allocation P/Invoke (VirtualAlloc/VirtualProtect/
    NtAllocateVirtualMemory/mmap/mprotect...) through managed calls, disassembled with capstone in the PE's mode
    (x86-64 for AMD64 and AnyCPU, i386 when 32BITREQUIRED) and run with unicorn to its ret: shellcode_count,
    shellcodes (JSON [{"method","field","size","hex","mode","disasm","return","return_hex"}]), shellcode_hex /
    shellcode_size / shellcode_field / shellcode_method / shellcode_mode / shellcode_disasm (JSON) /
    shellcode_return (int32 decimal of eax/x0) / shellcode_return_hex for the first, shellcode_returns (JSON);
    alloc_apis (P/Invoke entries of that family, JSON), exec_apis (Marshal.Copy / GetDelegateForFunctionPointer ...
    called, JSON), alloc_callers. Absent single values are "none". None when not a CLI assembly / truncated."""
    try:
        return _dotnet_native_facts(bytes(data))
    except Exception:   # noqa: BLE001 -- hostile tables: cannot answer
        return None


def _dotnet_native_facts(data):
    lay = _pe_layout(data)
    if not lay or len(lay[2]) <= 14 or not lay[2][14][0]:
        return None
    secs = lay[1]
    co = _pe_rva(secs, lay[2][14][0])
    if co is None or co + 72 > len(data):
        return None
    cb, vmaj, vmin, _md, _mds, flags, ep = struct.unpack_from("<IHHIIII", data, co)
    vtr, vts = struct.unpack_from("<II", data, co + 48)
    mnh = struct.unpack_from("<I", data, co + 64)[0]
    mdo = _pe_rva(secs, _md) if _md else None
    if cb < 72 or mdo is None or mdo + _mds > len(data) or data[mdo:mdo + 4] != b"BSJB":   # metadata past EOF: truncated
        return None
    js = lambda xs: json.dumps(list(xs), separators=(",", ":"), ensure_ascii=False)   # noqa: E731
    tf = lambda b: "true" if b else "false"   # noqa: E731
    bf = dotnet_build_facts(data) or {}
    mf = machine_facts(data) or {}
    machine = bf.get("machine") or mf.get("machine") or "none"
    vtf = []
    vo = _pe_rva(secs, vtr) if vtr and vts else None
    for k in range(min(vts // 8, 256) if vo is not None else 0):
        if vo + 8 * k + 8 > len(data):
            break
        r, n, ty = struct.unpack_from("<IHH", data, vo + 8 * k)
        so, w = _pe_rva(secs, r) if r else None, 8 if ty & 2 else 4
        toks = []
        for j in range(min(n, 64) if so is not None else 0):
            if so + w * j + w <= len(data):
                toks.append("0x%08x" % (int.from_bytes(data[so + w * j:so + w * j + w], "little") & 0xFFFFFFFF))
        vtf.append({"rva": "0x%x" % r, "count": n, "type": "0x%04x" % ty,
                    "kinds": [s for b, s in _VTF_FLAGS if ty & b], "tokens": toks})
    mo = _pe_rva(secs, mnh) if mnh else None
    r2r = mo is not None and data[mo:mo + 4] == b"RTR\0"
    out = {"cor20_flags": "0x%08x" % flags, "cor20_flag_names": js(s for b, s in _COR_FLAGS if flags & b),
           "cor20_version": "%d.%d" % (vmaj, vmin), "ilonly": tf(flags & 1), "mixed_mode": tf(not flags & 1 and not r2r),
           "32bit_required": tf(flags & 2), "32bit_preferred": tf(flags & 0x20000),
           "entry_point": ("0x%x" % ep if flags & 0x10 else "0x%08x" % ep) if ep else "none", "machine": machine,
           "vtfixup_rva": "0x%x" % vtr if vtr else "none", "vtfixup_size": str(vts if vtr else 0),
           "vtfixup_count": str(len(vtf)), "vtfixup_slots": str(sum(v["count"] for v in vtf)), "vtfixups": js(vtf),
           "readytorun": tf(r2r), "has_native_code": tf(not flags & 1 or vtf or r2r)}
    # shellcode carried as an InitializeArray blob that reaches an allocation P/Invoke
    il = dotnet_il_facts(data) or {}
    edges = [e for e in json.loads(il.get("call_edges") or "[]")]
    alloc = [e for e in edges if e["kind"] == "native" and
             (str(e.get("entry", "")).lower() in _SC_ALLOC or e["callee"].rsplit("::", 1)[-1].lower() in _SC_ALLOC)]
    rev = {}
    for e in edges:
        if e["kind"] == "managed":
            rev.setdefault(e["callee"], set()).add(e["caller"])
    reach, todo = set(), [e["caller"] for e in alloc]
    while todo and len(reach) < 4096:
        m = todo.pop()
        if m not in reach:
            reach.add(m)
            todo.extend(rev.get(m, ()))
    rtypes = {m.rsplit("::", 1)[0] for m in reach}
    if alloc:
        mode = machine if machine in ("x86-64", "AArch64") else \
            "i386" if machine == "i386" and flags & 2 else "x86-64" if machine == "i386" else None
    else:
        mode = None
    scs = []
    for a in json.loads(il.get("array_inits") or "[]") if mode else ():
        if a.get("hex") in (None, "none") or not (a["method"] in reach or a["method"].rsplit("::", 1)[0] in rtypes):
            continue
        code = bytes.fromhex(a["hex"])
        modes = (mode, "i386") if mode == "x86-64" and machine == "i386" else (mode,)
        for md in modes:
            ins, full = _sc_disasm(code, md)
            rv = _sc_emulate(code, md)
            if rv is not None or full:
                break
        if rv is None and not full:
            continue
        scs.append({"method": a["method"], "field": a["field"], "size": len(code), "hex": a["hex"], "mode": md,
                    "disasm": ins, "return": str(rv[0]) if rv else "none",
                    "return_hex": "0x%x" % (rv[0] & 0xFFFFFFFF) if rv else "none"})
    first = scs[0] if scs else {}
    out.update({"shellcode_count": str(len(scs)), "shellcodes": js(scs),
                "shellcode_returns": js(s["return"] for s in scs),
                "alloc_apis": js(dict.fromkeys(str(e.get("entry") or e["callee"].rsplit("::", 1)[-1]) for e in alloc)),
                "alloc_callers": js(dict.fromkeys(e["caller"] for e in alloc)),
                "exec_apis": js(dict.fromkeys(e["callee"].rsplit(".", 1)[-1] for e in edges
                                              if e["callee"].endswith(_SC_EXEC)))})
    for k in ("hex", "size", "field", "method", "mode", "return", "return_hex"):
        out["shellcode_" + k] = str(first[k]) if first else "none"
    out["shellcode_disasm"] = js(first.get("disasm", ())) if first else "none"
    return out


_DN_NATIVE_ALIAS = {"corflags": "cor20_flags", "cor20flags": "cor20_flags", "clrflags": "cor20_flags",
                    "comimageflags": "cor20_flags", "corflagnames": "cor20_flag_names", "ismixedmode": "mixed_mode",
                    "mixedmode": "mixed_mode", "cppcli": "mixed_mode", "isilonly": "ilonly", "ilonlyflag": "ilonly",
                    "vtablefixups": "vtfixups", "vtablefixupcount": "vtfixup_count", "vtfixupentries": "vtfixup_count",
                    "numvtfixups": "vtfixup_count", "vtablefixupscount": "vtfixup_count", "vtfixupscount": "vtfixup_count",
                    "isreadytorun": "readytorun", "r2r": "readytorun",
                    "nativecode": "has_native_code", "containsnativecode": "has_native_code",
                    "shellcodereturnvalue": "shellcode_return", "returnvalue": "shellcode_return",
                    "shellcodelength": "shellcode_size", "shellcodebytes": "shellcode_hex",
                    "requires32bit": "32bit_required", "prefers32bit": "32bit_preferred"}


def dotnet_native_field(data, name):
    """One dotnet_native_facts value by name (case/punctuation-insensitive, a few aliases: cor_flags, is_mixed_mode,
    vtable_fixups, is_readytorun, return_value ...); shellcode<N>_<k> / shellcode_<N>_<k> picks the N-th (1-based)
    shellcode record. None when not a CLI assembly, "none" for an unknown name."""
    f = dotnet_native_facts(data)
    if f is None:
        return None
    k = _il_key(name)
    keys = {_il_key(x): x for x in f}
    if k in keys:
        return f[keys[k]]
    if k in _DN_NATIVE_ALIAS:
        return f[_DN_NATIVE_ALIAS[k]]
    m = re.fullmatch(r"shellcode(\d+)(\w+)", k)
    if m:
        scs = json.loads(f["shellcodes"])
        i, sub = int(m.group(1)) - 1, m.group(2)
        if not 0 <= i < len(scs):
            return "none"
        for kk, v in scs[i].items():
            if _il_key(kk) == sub:
                return json.dumps(v, separators=(",", ":")) if isinstance(v, list) else str(v)
    return "none"


# ------------------------------------------------------------------ container slots: PE/.NET resources, overlay
_PARSE_ERR = (struct.error, IndexError, OverflowError, ValueError, TypeError)   # hostile header fields
_RT_NAMES = {1: "CURSOR", 2: "BITMAP", 3: "ICON", 4: "MENU", 5: "DIALOG", 6: "STRING", 7: "FONTDIR", 8: "FONT",
             9: "ACCELERATOR", 10: "RCDATA", 11: "MESSAGETABLE", 12: "GROUP_CURSOR", 14: "GROUP_ICON", 16: "VERSION",
             17: "DLGINCLUDE", 19: "PLUGPLAY", 20: "VXD", 21: "ANICURSOR", 22: "ANIICON", 23: "HTML", 24: "MANIFEST"}


def _pe_layout(data):
    """(optional-header end, [(name, va, vsize, raw_ptr, raw_size)], [(rva, size)] data dirs) or None."""
    try:
        if data[:2] != b"MZ":
            return None
        pe = int.from_bytes(data[0x3c:0x40], "little")
        if data[pe:pe + 4] != b"PE\0\0":
            return None
        nsec, optsz = struct.unpack_from("<H12xH", data, pe + 6)
        opt = pe + 24
        magic = struct.unpack_from("<H", data, opt)[0]
        dd = opt + (112 if magic == 0x20b else 96)
        ndd = min(16, struct.unpack_from("<I", data, dd - 4)[0])
        dirs = [struct.unpack_from("<II", data, dd + 8 * k) for k in range(ndd) if dd + 8 * k + 8 <= opt + optsz]
        secs = []
        for k in range(min(nsec, 96)):
            o = opt + optsz + 40 * k
            name = data[o:o + 8].rstrip(b"\0").decode("latin-1")
            vsize, va, rsize, rptr = struct.unpack_from("<IIII", data, o + 8)
            secs.append((name, va, vsize, rptr, rsize))
        return opt + optsz, secs, dirs
    except _PARSE_ERR:
        return None


def _pe_rva(secs, rva):
    for _, va, vsize, rptr, rsize in secs:
        if va <= rva < va + max(vsize, rsize):
            return rva - va + rptr
    return rva if not secs or rva < min(s[1] for s in secs) else None


def _elf_layout(data):
    """(end of everything the headers describe, [(name, offset, size)] sections) or None."""
    try:
        if data[:4] != b"\x7fELF" or data[4] not in (1, 2) or data[5] not in (1, 2):
            return None
        e = "<" if data[5] == 1 else ">"
        if data[4] == 1:
            phoff, shoff = struct.unpack_from(e + "II", data, 28)
            ehsize, phes, phn, shes, shn, shstr = struct.unpack_from(e + "6H", data, 40)
            ph, sh = (e + "4xI4xI"), (e + "I4x4x4x4xII")   # p_offset, p_filesz ; sh_name .. sh_offset, sh_size
        else:
            phoff, shoff = struct.unpack_from(e + "QQ", data, 32)
            ehsize, phes, phn, shes, shn, shstr = struct.unpack_from(e + "6H", data, 52)
            ph, sh = (e + "8xQ8x8xQ"), (e + "I4x8x8xQQ")
        end = max(ehsize, phoff + phn * phes if phn else 0, shoff + shn * shes if shn else 0)
        for k in range(min(phn, 4096)):
            o, n = struct.unpack_from(ph, data, phoff + k * phes)
            end = max(end, o + n)
        raw = []
        for k in range(min(shn, 65535)):
            b = shoff + k * shes
            nm, o, n = struct.unpack_from(sh, data, b)
            if struct.unpack_from(e + "I", data, b + 4)[0] != 8:   # SHT_NOBITS occupies no file bytes
                end = max(end, o + n)
                raw.append((nm, o, n))
        names = b""
        if shn and shstr < shn:
            _, so, sn = struct.unpack_from(sh, data, shoff + shstr * shes)
            names = data[so:so + sn]
        secs = [(names[nm:names.find(b"\0", nm)].decode("latin-1") if nm < len(names) else "", o, n) for nm, o, n in raw]
        return end, secs
    except _PARSE_ERR:
        return None


def overlay_info(data):
    """{"has_overlay", "overlay_offset" (None when absent), "overlay_size"} for an ELF or PE, None for anything else.
    PE: bytes past every header-described region (optional header, section raw data, data directories other than the
    certificate table) = pefile's get_overlay_data_start_offset(). ELF: bytes past the ELF header, program/section
    header tables, every PT_* segment's file bytes and every non-NOBITS section (lief's Binary.overlay)."""
    data = bytes(data)
    pe = _pe_layout(data)
    if pe:
        hdr_end, secs, dirs = pe
        end = hdr_end
        for _, _, _, rptr, rsize in secs:
            if end < rptr + rsize <= len(data):
                end = rptr + rsize
        for k, (rva, size) in enumerate(dirs):
            o = _pe_rva(secs, rva) if k != 4 and (rva or size) else None
            if o is not None and end < o + size <= len(data):
                end = o + size
    else:
        el = _elf_layout(data)
        if not el:
            return None
        end = el[0]
    has = len(data) > end
    return {"has_overlay": has, "overlay_offset": end if has else None, "overlay_size": max(0, len(data) - end)}


def pe_resources(data, limit=4096):
    """[{type, type_name, name, lang, offset, size}] for every leaf of the PE resource tree (offset = file offset of
    the resource DATA start; ids are ints, named entries are str), [] when there is none / not a PE."""
    data = bytes(data)
    pe = _pe_layout(data)
    if not pe or len(pe[2]) < 3 or not pe[2][2][0]:
        return []
    secs = pe[1]
    base = _pe_rva(secs, pe[2][2][0])
    out = []
    if base is None:
        return out

    def ident(v):
        if v & 0x80000000:
            o = base + (v & 0x7fffffff)
            n = int.from_bytes(data[o:o + 2], "little")
            return data[o + 2:o + 2 + 2 * n].decode("utf-16-le", "replace")
        return v

    def walk(off, path, depth):
        try:
            nn, ni = struct.unpack_from("<HH", data, base + off + 12)
            for k in range(min(nn + ni, limit)):
                v, child = struct.unpack_from("<II", data, base + off + 16 + 8 * k)
                if len(out) >= limit:
                    return
                if child & 0x80000000:
                    if depth < 3:
                        walk(child & 0x7fffffff, path + [ident(v)], depth + 1)
                else:
                    rva, size = struct.unpack_from("<II", data, base + child)
                    p = path + [ident(v)] + [None] * 3
                    o = _pe_rva(secs, rva)
                    out.append({"type": p[0], "type_name": _RT_NAMES.get(p[0], p[0]), "name": p[1], "lang": p[2],
                                "offset": o, "size": size})
        except _PARSE_ERR:
            return

    walk(0, [], 0)
    return out


def dotnet_resources(data, limit=4096):
    """[{offset, size}] of the .NET manifest resources embedded in the CLI Resources blob (offset = first DATA byte,
    i.e. past each resource's u32 length prefix; Roslyn 8-aligns them), [] when there is none / not a .NET PE."""
    data = bytes(data)
    pe = _pe_layout(data)
    if not pe or len(pe[2]) < 15 or not pe[2][14][0]:
        return []
    cli = _pe_rva(pe[1], pe[2][14][0])
    try:
        rva, size = struct.unpack_from("<II", data, cli + 24)
    except _PARSE_ERR:
        return []
    lo = _pe_rva(pe[1], rva) if rva else None
    out = []
    if lo is None:
        return out
    p, end = lo, min(lo + size, len(data))
    while p + 4 <= end and len(out) < limit:
        n = int.from_bytes(data[p:p + 4], "little")
        if not n or p + 4 + n > end:
            if (p - lo) % 8 and not n:   # alignment padding between resources
                p += 8 - (p - lo) % 8
                continue
            break
        out.append({"offset": p + 4, "size": n})
        p += 4 + n
    return out


# --- reflection / dynamic loading of a second module (coverage atlas: reflection-dynamic-load) -----------------------
# A loader carries a second managed/JVM module as DATA and loads it at run time: .NET Assembly.Load(byte[]) of a manifest
# resource (Costura.Fody `costura.<name>.dll.compressed` = raw deflate via DeflateStream; also gzip/zlib/plain) or of a
# byte[] initializer (FieldRVA blob), AppDomain.AssemblyResolve, Activator.CreateInstance / MethodInfo.Invoke by string
# name; JVM ClassLoader.defineClass of a jar entry / blob stored xor'd (short repeating key, recovered from the class /
# DOS header known plaintext). embedded_modules finds them, decodes them, and recurses (provenance path " > ").
EMB_MAX_DEPTH = 3
EMB_MAX_BYTES = int(os.environ.get("HCTF_EMB_MAX", str(48 << 20)))   # decoded bytes over all candidates
_EMB_CLASS_KP = b"\xca\xfe\xba\xbe\x00\x00\x00"        # magic + minor 0 + major high byte
_EMB_MZ_KP = b"MZ\x90\x00\x03\x00\x00\x00\x04\x00\x00\x00\xff\xff"   # the DOS header every MSVC/Roslyn PE starts with
_EMB_DOS_STUB = b"This program cannot be run in DOS mode"
_EMB_DN_API = ("Load", "LoadFrom", "LoadFile", "UnsafeLoadFrom", "add_AssemblyResolve", "add_TypeResolve",
               "add_ResourceResolve", "CreateInstance", "CreateInstanceFrom", "GetType", "GetMethod", "GetMethods",
               "GetProperty", "GetField", "GetConstructor", "Invoke", "InvokeMember", "GetManifestResourceStream",
               "GetManifestResourceNames", "DefineDynamicAssembly", "CreateDelegate", "GetDelegateForFunctionPointer")
_EMB_DN_TYPES = ("Assembly", "AppDomain", "Activator", "Type", "MethodInfo", "MethodBase", "ConstructorInfo",
                 "PropertyInfo", "FieldInfo", "AssemblyLoadContext", "Delegate", "Marshal", "AssemblyBuilder")
_EMB_JVM_API = (b"defineClass", b"defineHiddenClass", b"loadClass", b"findClass", b"forName", b"getMethod",
                b"getDeclaredMethod", b"getConstructor", b"getDeclaredConstructor", b"newInstance", b"invoke",
                b"getResourceAsStream", b"URLClassLoader", b"InMemoryClassLoader", b"MethodHandles", b"findStatic",
                b"findVirtual", b"Unsafe")


def _emb_kind(b):
    """'dotnet' / 'pe' / 'class' / 'jar' / 'elf' for a decoded module's leading bytes, else None."""
    try:
        if b[:2] == b"MZ":
            e = int.from_bytes(b[60:64], "little")
            if b[e:e + 4] != b"PE\0\0":
                return None
            return "dotnet" if b.find(b"BSJB", 0, 1 << 22) > 0 else "pe"
        if b[:4] == b"\xca\xfe\xba\xbe":
            return "class" if classfile_parse(b) else None
        if b[:4] == b"PK\x03\x04":
            return "jar"
        if b[:4] == b"\x7fELF":
            return "elf"
    except _PARSE_ERR:
        return None
    return None


def _emb_xor(b, kp, maxk=8):
    """(key bytes, decoded) when `b` is `kp`-prefixed plaintext xor'd with a repeating key of 1..maxk bytes."""
    n = min(len(kp), len(b))
    for k in range(1, min(maxk, n) + 1):
        key = bytes(b[i] ^ kp[i] for i in range(k))
        if not any(key) or any(b[i] ^ key[i % k] != kp[i] for i in range(k, n)):
            continue
        if len(key) > 1 and len(set(key)) == 1:   # 'k' repeated: the 1-byte key already covered it
            continue
        ks = (key * (len(b) // k + 1))[:len(b)]
        return key, (int.from_bytes(b, "big") ^ int.from_bytes(ks, "big")).to_bytes(len(b), "big")
    return None


def _emb_head_ok(data, o):
    """Cheap test on the first bytes at data[o]: could a module (plain / deflated / short-xor'd) start here?"""
    h = bytes(data[o:o + 16])
    if h[:2] == b"MZ" or h[:4] in (b"\xca\xfe\xba\xbe", b"PK\x03\x04", b"\x7fELF") or h[:2] == b"\x1f\x8b":
        return True
    if any(_emb_xor(h, kp) for kp in (_EMB_CLASS_KP, _EMB_MZ_KP)):
        return True
    for wb in (-15, 15):
        try:
            r = zlib.decompressobj(wb).decompress(bytes(data[o:o + 4096]), 8)
        except zlib.error:
            continue
        if r[:2] == b"MZ" or r[:4] in (b"\xca\xfe\xba\xbe", b"PK\x03\x04"):
            return True
    return False


def _emb_decode(b):
    """[(encoding, decoded bytes)] of the module forms of blob `b` (plain, raw deflate / zlib / gzip, short xor)."""
    out = []
    if _emb_kind(b):
        return [("raw", b)]
    for enc, wb in (("deflate", -15), ("zlib", 15), ("gzip", 31)):
        try:
            d = zlib.decompressobj(wb)
            r = d.decompress(b, EMB_MAX_BYTES)
        except zlib.error:
            continue
        if len(r) >= 64 and _emb_kind(r):
            out.append((enc, r))
            return out
    for kp in (_EMB_CLASS_KP, _EMB_MZ_KP):
        r = _emb_xor(b, kp)
        if r and _emb_kind(r[1]):
            out.append(("xor:" + r[0].hex(), r[1]))
            return out
    return out


def _emb_trim(kind, b):
    """The module's own bytes (a class / PE stops where its structure ends; trailing data is dropped)."""
    try:
        if kind == "class":
            p = classfile_parse(b)
            return b[:len(b) - p["trailing"]] if p else b
        if kind in ("pe", "dotnet"):
            pe = _pe_layout(b)
            end = max((rp + rs for _, _, _, rp, rs in pe[1]), default=0) if pe else 0
            return b[:end] if end and end <= len(b) else b
    except _PARSE_ERR:
        pass
    return b


def _emb_dn_meta(data, refs=False):
    """dnfile view of a CLI PE: {name, resources [(name, file offset of data, size)], field_rvas [file offsets],
    us [#US strings], refs [(type, member) MemberRef names]} or None."""
    try:
        import dnfile
        pe = dnfile.dnPE(data=bytes(data), fast_load=True, clr_lazy_load=True)
        pe.parse_data_directories(directories=[14])
        net = pe.net
        if net is None or net.mdtables is None:
            return None
        t = net.mdtables
        rows = lambda tab: list(getattr(t, tab, None) or ())   # noqa: E731
        nm = lambda x: "" if x is None else str(x)   # noqa: E731
        asm = rows("Assembly")
        out = {"name": nm(asm[0].Name) if asm else "", "resources": [], "field_rvas": [], "us": [], "refs": []}
        lay = _pe_layout(data)
        cli = _pe_rva(lay[1], lay[2][14][0])
        rrva, rsize = struct.unpack_from("<II", data, cli + 24)
        lo = _pe_rva(lay[1], rrva) if rrva else None
        for r in rows("ManifestResource"):
            if int(getattr(r.struct, "Implementation_CodedIndex", 0) or 0) >> 2:
                continue   # lives in another file / assembly (raw coded index: r.Implementation full-loads, ~2 s)
            if lo is None:
                break
            p = lo + int(r.Offset or 0)
            n = int.from_bytes(data[p:p + 4], "little")
            if p + 4 + n <= len(data) and int(r.Offset or 0) + 4 + n <= rsize:
                out["resources"].append((nm(r.Name), p + 4, n))
        for r in rows("FieldRva"):
            o = _pe_rva(lay[1], int(getattr(r, "Rva", 0) or 0)) if getattr(r, "Rva", 0) else None
            if o is not None:
                out["field_rvas"].append(o)
        h, p = bytes(getattr(net.user_strings, "__data__", b"") or b""), 1
        while refs and p < len(h) and len(out["us"]) < 20000:
            n, q = h[p], p + 1
            if n & 0x80:
                n, q = (((n & 0x3F) << 8) | h[p + 1], p + 2) if not n & 0x40 else \
                    (((n & 0x1F) << 24) | int.from_bytes(h[p + 1:p + 4], "big"), p + 4)
            if n == 0 and h[p] == 0:
                break
            if n > 1:
                out["us"].append(h[q:q + n - 1].decode("utf-16-le", "replace"))
            p = q + n
        trs = rows("TypeRef") if refs else ()
        for r in rows("MemberRef") if refs else ():
            mn = nm(r.Name)   # MemberRefParent coded index: 3-bit tag (1 = TypeRef), row = ci >> 3 (decoded by hand:
            if mn not in _EMB_DN_API:   # dnfile's r.Class resolution full-loads every table, ~1.2 s on FSharp.Core)
                continue
            ci = int(getattr(r.struct, "Class_CodedIndex", 0) or 0)
            tn = nm(trs[(ci >> 3) - 1].TypeName) if ci & 7 == 1 and 0 < ci >> 3 <= len(trs) else ""
            out["refs"].append((tn, mn))
        return out
    except Exception:   # noqa: BLE001 -- hostile/truncated metadata: not a CLI PE we can walk
        return None


def _emb_jvm_strings(cls):
    """(api names, string constants) of one .class: CONSTANT_Utf8 entries naming loader/reflection APIs, + Strings."""
    p = classfile_parse(cls)
    if not p:
        return [], []
    utf = {e[1] for e in p["cp"] if e and e[0] == 1 and isinstance(e[1], str)}
    apis = [a.decode() for a in _EMB_JVM_API if any(a.decode() == s or ("/" + a.decode()) in s for s in utf)]
    strs = []
    for e in p["cp"]:
        if e and e[0] == 8:
            try:
                s = p["_u"](e[1])
            except Exception:   # noqa: BLE001
                s = None
            if s is not None:
                strs.append(s)
    return apis, strs


def reflection_calls(data):
    """Reflective / dynamic-load call evidence of one module: {"apis": ['Assembly.Load', 'Activator.CreateInstance',
    ...] (.NET MemberRef Type.Member) or ['defineClass', ...] (JVM constant-pool names, over every class of a jar),
    "strings": #US strings (.NET) / CONSTANT_String values (JVM) = the type/method/resource names passed by string}.
    None when `data` is neither a CLI PE, a class nor a jar."""
    data = bytes(data)
    kind = _emb_kind(data)
    if kind in ("dotnet", "pe"):
        m = _emb_dn_meta(data, refs=True)
        if m is None:
            return None
        apis = []
        for tn, mn in m["refs"]:
            if tn in _EMB_DN_TYPES and mn in _EMB_DN_API and f"{tn}.{mn}" not in apis:
                apis.append(f"{tn}.{mn}")
        return {"apis": apis, "strings": m["us"]}
    classes = []
    if kind == "class":
        classes = [data]
    elif kind == "jar" or data[:4] == b"PK\x03\x04":
        try:
            zf = zipfile.ZipFile(io.BytesIO(data))
            classes = [zf.read(i) for i in zf.infolist()[:4000] if i.filename.endswith(".class") and i.file_size < 1 << 22]
        except Exception:   # noqa: BLE001
            return None
    else:
        return None
    apis, strs = [], []
    for c in classes:
        a, s = _emb_jvm_strings(c)
        apis += [x for x in a if x not in apis]
        strs += [x for x in s if x not in strs]
    return {"apis": apis, "strings": strs}


def _emb_candidates(data, kind):
    """[(provenance, stored offset, blob bytes)] places a second module may hide in a module of `kind`."""
    out = []
    if kind in ("dotnet", "pe"):
        m = _emb_dn_meta(data) if kind == "dotnet" else None
        for name, o, n in (m or {}).get("resources", ()):
            if _emb_head_ok(data, o):
                out.append(("resource:" + name, o, data[o:o + n]))
        for o in (m or {}).get("field_rvas", ())[:4096]:
            if _emb_head_ok(data, o):
                out.append((f"field_rva@{o}", o, data[o:o + (16 << 20)]))
        i, k = data.find(_EMB_DOS_STUB, 0x80), 0   # a raw PE inside (array / overlay): DOS stub text at MZ+0x4e
        while i >= 0 and k < 64:
            o = i - 0x4e
            if data[o:o + 2] == b"MZ":
                lay = _pe_layout(data[o:o + 0x1000])
                n = max((rp + rs for _, _, _, rp, rs in lay[1]), default=0) if lay else 0
                if n:
                    out.append((f"raw@{o}", o, data[o:o + n]))
            i, k = data.find(_EMB_DOS_STUB, i + 1), k + 1
    elif kind == "jar" or data[:4] == b"PK\x03\x04":
        try:
            zf = zipfile.ZipFile(io.BytesIO(data))
            infos = zf.infolist()[:20000]
        except Exception:   # noqa: BLE001
            infos, zf = [], None
        for zi in infos:
            if zi.filename.endswith("/") or zi.file_size < 64 or zi.file_size > (16 << 20):
                continue
            if zi.filename.lower().endswith((".class", ".jar", ".so", ".dylib", ".jnilib")):
                continue   # an ordinary app class / bundled library under its own name, not a hidden payload
            p = zi.header_offset
            dstart = p + 30 + int.from_bytes(data[p + 26:p + 28], "little") + int.from_bytes(data[p + 28:p + 30], "little")
            try:
                out.append(("zip:" + zi.filename, dstart, zf.read(zi)))
            except Exception:   # noqa: BLE001 -- encrypted / unsupported entry
                continue
    if kind in ("dotnet", "pe", "elf", "class"):   # a raw class constant inside a native/managed blob
        i, k = data.find(b"\xca\xfe\xba\xbe", 1), 0
        while i >= 0 and k < 64:
            if 45 <= int.from_bytes(data[i + 6:i + 8], "big") <= 80:
                out.append((f"raw@{i}", i, data[i:i + (4 << 20)]))
            i, k = data.find(b"\xca\xfe\xba\xbe", i + 1), k + 1
    return out


def embedded_modules(data, *, max_depth=EMB_MAX_DEPTH, hcfg=True, deadline=None):
    """Every second module carried as data by `data` (a .NET PE, a jar/zip, a class, a native PE/ELF), recursively:
    [{path (provenance, ' > '-joined: 'resource:costura.payload.dll.compressed', 'zip:payload.bin', 'field_rva@N',
    'raw@N'), depth (1 = directly inside `data`), stored_offset (first stored byte in its container), encoding ('raw' /
    'deflate' / 'zlib' / 'gzip' / 'xor:<key hex>'), kind ('dotnet' / 'pe' / 'class' / 'jar' / 'elf'), name (assembly /
    class name), size, sha256, md5, reflection (reflection_calls of the module), hcfg ({offset (INSIDE the decoded
    module), encoding, config} of the first crc-valid blob, or None; hcfg="encoded": only modules whose stored form
    is not raw -- a raw one is already in the outer bytes)}]. [] when nothing is embedded; never raises."""
    import hashlib
    end = _ends(deadline)
    budget, out, seen = [EMB_MAX_BYTES], [], set()

    def walk(buf, kind, prefix, depth):
        if depth > max_depth or (end is not None and time.time() > end):
            return
        try:
            cands = _emb_candidates(buf, kind)
        except Exception:   # noqa: BLE001
            return
        for prov, off, blob in cands:
            if budget[0] <= 0 or (end is not None and time.time() > end):
                return
            try:
                forms = _emb_decode(blob)
            except Exception:   # noqa: BLE001
                continue
            for enc, mod in forms:
                k = _emb_kind(mod)
                mod = _emb_trim(k, mod)
                h = hashlib.sha256(mod).hexdigest()
                if h in seen or (enc == "raw" and len(mod) == len(buf)):
                    continue
                seen.add(h)
                budget[0] -= len(mod)
                if k in ("dotnet", "pe"):
                    name = (_emb_dn_meta(mod) or {}).get("name", "") if k == "dotnet" else ""
                else:
                    name = (classfile_parse(mod) or {}).get("this") or "" if k == "class" else ""
                rec = {"path": prefix + prov, "depth": depth, "stored_offset": off, "encoding": enc, "kind": k,
                       "name": name or "none", "size": len(mod), "sha256": h, "md5": hashlib.md5(mod).hexdigest(),
                       "reflection": None, "hcfg": None}
                try:
                    rec["reflection"] = reflection_calls(mod)
                except Exception:   # noqa: BLE001
                    pass
                if hcfg and (hcfg != "encoded" or enc != "raw"):
                    try:
                        hit = next((x for x in hcfg_scan(mod, deadline=deadline, stop_on_valid=True, _depth=2)
                                    if x.valid), None)
                    except Exception:   # noqa: BLE001
                        hit = None
                    if hit:
                        rec["hcfg"] = {"offset": hit.offset, "encoding": hit.encoding, "config": hit.config}
                        rec["_hit"] = hit   # the HcfgHit itself (hcfg_scan re-labels it module-<enc>)
                out.append(rec)
                walk(mod, k, rec["path"] + " > ", depth + 1)

    try:
        data = bytes(data)
        walk(data, _emb_kind(data) or ("jar" if data[:4] == b"PK\x03\x04" else None), "", 1)
    except Exception:   # noqa: BLE001
        pass
    return out


def embedded_module_field(data, name):
    """One answer string about the embedded modules: module_count, module_paths / module_names / module_kinds /
    module_encodings / module_sha256 (JSON lists, discovery order), first_module_<key> (path/name/kind/encoding/sha256/
    md5/size/stored_offset), loader_apis / loader_strings (reflection_calls of `data` itself, JSON list), module_apis /
    module_strings (of the first module), hcfg_path (module holding a valid HCFG), hcfg_offset (inside that module).
    "none" when absent (no module / empty), None when `data` is not a parsable container."""
    js = lambda xs: json.dumps(list(xs), separators=(",", ":"), ensure_ascii=False)   # noqa: E731
    try:
        data = bytes(data)
        if name in ("loader_apis", "loader_strings"):
            r = reflection_calls(data)
            if r is None:
                return None
            v = r["apis" if name == "loader_apis" else "strings"]
            return js(v) if v else "none"
        mods = embedded_modules(data)
        if name == "module_count":
            return str(len(mods))
        if not mods:
            return "none"
        if name.startswith("module_") and name[7:-1] in ("path", "name", "kind", "encoding") and name.endswith("s"):
            return js(m[name[7:-1]] for m in mods)
        if name == "module_sha256":
            return js(m["sha256"] for m in mods)
        if name.startswith("first_module_") and name[13:] in mods[0]:
            return str(mods[0][name[13:]])
        if name in ("module_apis", "module_strings"):
            r = mods[0]["reflection"] or {}
            v = r.get("apis" if name == "module_apis" else "strings") or []
            return js(v) if v else "none"
        h = next((m for m in mods if m["hcfg"]), None)
        if name == "hcfg_path":
            return h["path"] if h else "none"
        if name == "hcfg_offset":
            return str(h["hcfg"]["offset"]) if h else "none"
    except Exception:   # noqa: BLE001
        return None
    return None


def hcfg_locate(data, off):
    """Which container slot holds file offset `off` (a Hit.offset): {"container": "pe-resource" | "dotnet-resource" |
    "dotnet-bundle" | "overlay" | "section", "slot_offset" (resource data start / bundle entry start = the embedded
    dll's offset / overlay start / section start), "delta" (off - slot), + type_name/name/lang | path/file_type (+ inner
    = the slot inside a stored bundled dll) | section}, or None. For a resource/entry/overlay-relative offset question."""
    data = bytes(data)
    for r in pe_resources(data):
        if r["offset"] is not None and r["offset"] <= off < r["offset"] + r["size"]:
            return {"container": "pe-resource", "slot_offset": r["offset"], "delta": off - r["offset"],
                    "type_name": r["type_name"], "name": r["name"], "lang": r["lang"], "size": r["size"]}
    for r in dotnet_resources(data):
        if r["offset"] <= off < r["offset"] + r["size"]:
            return {"container": "dotnet-resource", "slot_offset": r["offset"], "delta": off - r["offset"],
                    "size": r["size"]}
    for f in (dotnet_bundle(data) or {}).get("files", ()):   # .NET single-file bundle entry (stored or compressed bytes)
        if f["offset"] <= off < f["offset"] + (f["compressed_size"] or f["size"]):
            r = {"container": "dotnet-bundle", "slot_offset": f["offset"], "delta": off - f["offset"], "path": f["path"],
                 "file_type": f["type"], "size": f["size"], "compressed_size": f["compressed_size"]}
            if not f["compressed_size"] and f["type"] == "assembly":   # resource/section inside the embedded dll
                inner = hcfg_locate(data[f["offset"]:f["offset"] + f["size"]], off - f["offset"])
                if inner:
                    r["inner"] = inner
            return r
    ov = overlay_info(data)
    if ov and ov["has_overlay"] and off >= ov["overlay_offset"]:
        return {"container": "overlay", "slot_offset": ov["overlay_offset"], "delta": off - ov["overlay_offset"],
                "size": ov["overlay_size"]}
    pe = _pe_layout(data)
    secs = [(n, rp, rs) for n, _, _, rp, rs in pe[1]] if pe else (_elf_layout(data) or (0, []))[1]
    for n, o, size in secs:
        if o <= off < o + size and n:
            return {"container": "section", "section": n, "slot_offset": o, "delta": off - o, "size": size}
    return None



# Day 17 `hcfg_storage` (kind enum): the GM's rule list, applied IN ORDER -- base64 (crc-valid HCFG only after decoding a
# printable base64 carrier; d08/d09/d11/d13, jars d06/d07) -> raw_hcfg_section (literal HCFG starts in a native section
# named exactly .hcfg; d14, also d02/d10/d15) -> wasm_data_segment (inside a wasm data segment; d16) -> raw_const_array
# (any OTHER native data section: d12 FPC .data, d04 Go .noptrdata, d05/d17 .rodata) -> raw. GM-confirmed: d08/d09/d11-d14.
HCFG_STORAGE_TOKENS = ("raw", "base64", "raw_const_array", "raw_hcfg_section", "wasm_data_segment")
_HCFG_B64_ENC = ("base64", "base64url")


def hcfg_section_of(data, off):
    """{container elf/pe/mach-o/wasm, section, data (bool: a native DATA section), flags} of the section holding file
    offset `off`; {container, section None} when the container parses but no section holds it; None for an unknown
    container. Data = ELF SHF_ALLOC && !SHF_EXECINSTR (not NOBITS); PE IMAGE_SCN_CNT_INITIALIZED_DATA && !MEM_EXECUTE;
    Mach-O no S_ATTR_*_INSTRUCTIONS and segment __DATA* or __TEXT,__const/__cstring/__literal*; wasm = data segment."""
    try:
        data = bytes(data)
        if data[:4] == b"\x7fELF":
            e, b64 = ("<" if data[5] == 1 else ">"), data[4] == 2
            shoff = struct.unpack_from(e + ("Q" if b64 else "I"), data, 40 if b64 else 32)[0]
            shes, shn, shstr = struct.unpack_from(e + "3H", data, 58 if b64 else 46)
            fmt = e + ("IIQQQQ" if b64 else "IIIIII")   # name, type, flags, addr, offset, size
            secs = [struct.unpack_from(fmt, data, shoff + k * shes) for k in range(min(shn, 65535))] if shoff else []
            names = b""
            if shstr < len(secs):
                names = data[secs[shstr][4]:secs[shstr][4] + secs[shstr][5]]
            for nm, t, fl, _, o, n in secs:
                if t != 8 and t != 0 and o <= off < o + n:   # SHT_NOBITS / SHT_NULL hold no file bytes
                    name = names[nm:names.find(b"\0", nm)].decode("latin-1") if nm < len(names) else ""
                    return {"container": "elf", "section": name, "flags": fl, "data": bool(fl & 2 and not fl & 4)}
            return {"container": "elf", "section": None}
        lay = _pe_layout(data)
        if lay:
            pe = int.from_bytes(data[0x3c:0x40], "little")
            first = pe + 24 + struct.unpack_from("<H", data, pe + 20)[0]
            for k, (name, _, _, rp, rs) in enumerate(lay[1]):
                if rs and rp <= off < rp + rs:
                    ch = struct.unpack_from("<I", data, first + 40 * k + 36)[0]
                    return {"container": "pe", "section": name, "flags": ch,
                            "data": bool(ch & 0x40 and not ch & 0x20000020)}
            return {"container": "pe", "section": None}
        mo = macho_layout(data)
        if mo:
            for x in (x for s in mo["slices"] for x in s["sections"]):
                if x["offset"] and x["offset"] <= off < x["offset"] + x["size"] and x["flags"] & 0xff not in (1, 0xc):
                    seg, sect, fl = x["segment"], x["section"], x["flags"]
                    dat = not fl & 0x80000400 and (seg.startswith("__DATA") or seg == "__TEXT" and (
                        sect in ("__const", "__cstring") or sect.startswith("__literal")))
                    return {"container": "mach-o", "section": sect, "segment": seg, "flags": fl, "data": bool(dat)}
            return {"container": "mach-o", "section": None}
        wl = wasm_layout(data)
        if wl:
            for sg in wl["data_segments"]:
                if sg["file_offset"] <= off < sg["file_offset"] + sg["size"]:
                    return {"container": "wasm", "section": "data", "segment_index": sg["index"], "data": True}
            return {"container": "wasm", "section": None}
    except _PARSE_ERR:
        return None
    return None


# --- file offset -> container location (likely next ids: hcfg_section, hcfg_va/hcfg_vaddr, hcfg_rva, hcfg_segment,
# hcfg_mem_offset). Spellings tried first: section name verbatim (".rodata"), addresses lowercase 0x hex (as
# entry_point). SPECULATIVE: ELF rva = vaddr - lowest PT_LOAD (p_vaddr - p_offset) base; Mach-O rva = vaddr - vmaddr
# of the segment mapping file offset 0 (__TEXT).
_ELF_SHF = ((1, "W"), (2, "A"), (4, "X"), (0x10, "M"), (0x20, "S"), (0x40, "I"), (0x80, "L"), (0x100, "O"),
            (0x200, "G"), (0x400, "T"), (0x800, "C"), (0x80000000, "E"))
LOCATE_KEYS = ("container", "section", "section_flags", "segment", "segment_index", "segment_flags", "vaddr", "rva",
               "wasm_data_index", "wasm_mem_offset")


def _hx(v):
    return "none" if v is None else f"0x{v:x}"


def _locate_elf(data, off, out):
    e, b64 = ("<" if data[5] == 1 else ">"), data[4] == 2
    if b64:
        phoff, shoff = struct.unpack_from(e + "QQ", data, 32)
        phes, phn, shes, shn, shstr = struct.unpack_from(e + "5H", data, 54)
    else:
        phoff, shoff = struct.unpack_from(e + "II", data, 28)
        phes, phn, shes, shn, shstr = struct.unpack_from(e + "5H", data, 42)
    loads, seg = [], None
    for k in range(min(phn, 4096) if phoff else 0):
        o = phoff + k * phes
        if o + (56 if b64 else 32) > len(data):
            break
        if b64:
            t, fl, po, va, _, fs = struct.unpack_from(e + "IIQQQQ", data, o)
        else:
            t, po, va, _, fs, _, fl = struct.unpack_from(e + "7I", data, o)
        if t != 1:   # PT_LOAD only: the mapping that gives a file byte its address
            continue
        loads.append(va - po)
        if seg is None and fs and po <= off < po + fs:
            seg = (k, fl, va + off - po)
    sec = None
    if shoff and shes >= (64 if b64 else 40):
        fmt = e + ("IIQQQQ" if b64 else "6I")   # name, type, flags, addr, offset, size
        rows = []
        for k in range(min(shn, 65535)):
            b = shoff + k * shes
            if b + shes > len(data):
                break
            rows.append(struct.unpack_from(fmt, data, b))
        names = b""
        if shstr < len(rows):
            names = bytes(data[rows[shstr][4]:rows[shstr][4] + rows[shstr][5]])
        for nm, t, fl, ad, o, n in rows:
            if t not in (0, 8) and o <= off < o + n:   # SHT_NULL / SHT_NOBITS hold no file bytes
                z = names.find(b"\0", nm)
                sec = (names[nm:z if z >= 0 else len(names)].decode("latin-1") if nm < len(names) else "", fl, ad, o)
                break
    out["container"] = "elf"
    if sec:
        out["section"] = sec[0]
        out["section_flags"] = "".join(c for bit, c in _ELF_SHF if sec[1] & bit)
    va = sec[2] + off - sec[3] if sec and sec[1] & 2 and sec[2] else (seg[2] if seg else None)
    if seg:
        out["segment"], out["segment_index"] = "LOAD", seg[0]
        out["segment_flags"] = "".join(c for bit, c in ((4, "R"), (2, "W"), (1, "E")) if seg[1] & bit)
    if va is not None:
        out["vaddr"] = _hx(va)
        out["rva"] = _hx(va - min(loads)) if loads and va >= min(loads) else "none"


def _locate_pe(data, off, lay, out):
    pe = int.from_bytes(data[0x3c:0x40], "little")
    opt = pe + 24
    base = struct.unpack_from("<Q" if struct.unpack_from("<H", data, opt)[0] == 0x20b else "<I", data,
                              opt + (24 if struct.unpack_from("<H", data, opt)[0] == 0x20b else 28))[0]
    first = opt + struct.unpack_from("<H", data, pe + 20)[0]
    out["container"] = "pe"
    for k, (name, va, vs, rp, rs) in enumerate(lay[1]):
        if rs and rp <= off < rp + rs:
            out["section"] = name
            out["section_flags"] = _hx(struct.unpack_from("<I", data, first + 40 * k + 36)[0])
            out["segment_index"] = k
            out["rva"], out["vaddr"] = _hx(va + off - rp), _hx(base + va + off - rp)
            return
    if off < lay[0] or (lay[1] and off < min((s[3] for s in lay[1] if s[4]), default=0)):
        out["rva"], out["vaddr"] = _hx(off), _hx(base + off)   # headers map 1:1 at the image base


def _locate_macho(data, off, out):
    mo = macho_layout(data)
    if not mo:
        return False
    out["container"] = "mach-o"
    sl = None
    for s in mo["slices"]:
        if s["slice_offset"] <= off:
            sl = s if sl is None or s["slice_offset"] >= sl["slice_offset"] else sl
    if sl is None:
        return True
    end, base = sl["endian"], sl["slice_offset"]
    u32 = lambda o: int.from_bytes(data[o:o + 4], end)   # noqa: E731
    p = base + (32 if sl["bits"] == 64 else 28)
    stop = min(len(data), p + u32(base + 20))
    text_va = None
    for _ in range(min(u32(base + 16), 4096)):
        if p + 8 > stop:
            break
        cmd, size = u32(p), u32(p + 4)
        if size < 8:
            break
        if cmd in (0x1, 0x19):
            w = 8 if cmd == 0x19 else 4
            uw = lambda o: int.from_bytes(data[o:o + w], end)   # noqa: E731
            segname = bytes(data[p + 8:p + 24]).split(b"\0")[0].decode("latin-1")
            vmaddr, fileoff, filesize = uw(p + 24), uw(p + 24 + 2 * w), uw(p + 24 + 3 * w)
            if fileoff == 0 and filesize:
                text_va = vmaddr if text_va is None else text_va
            if filesize and base + fileoff <= off < base + fileoff + filesize and out["segment"] == "none":
                out["segment"], out["vaddr"] = segname, _hx(vmaddr + off - base - fileoff)
                out["segment_flags"] = _hx(u32(p + 24 + 4 * w + 4))   # initprot
                nsects = u32(p + 24 + 4 * w + 8)
                q, ssz = p + 24 + 4 * w + 16, 80 if w == 8 else 68
                for _s in range(min(nsects, 1024)):
                    if q + ssz > min(stop, p + size):
                        break
                    addr, sz, so = uw(q + 32), uw(q + 32 + w), u32(q + 32 + 2 * w)
                    fl = u32(q + 48 + 2 * w)
                    if so and fl & 0xff not in (1, 0xc) and base + so <= off < base + so + sz:
                        out["section"] = bytes(data[q:q + 16]).split(b"\0")[0].decode("latin-1")
                        out["section_flags"] = _hx(fl)
                        if not segname:   # MH_OBJECT: one unnamed segment, the section names its own segname
                            out["segment"] = bytes(data[q + 16:q + 32]).split(b"\0")[0].decode("latin-1") or "none"
                        out["vaddr"] = _hx(addr + off - base - so)
                        break
                    q += ssz
        p += size
    if out["vaddr"] != "none" and text_va is not None:
        out["rva"] = _hx(int(out["vaddr"], 16) - text_va)
    return True


def locate_offset(data, off):
    """Map file offset `off` to its container location -> {container elf/pe/mach-o/wasm, section (name verbatim:
    ".rodata", PE ".data", Mach-O sectname "__const", wasm section name "data"/"code"/custom name), section_flags (ELF
    readelf letters "WA"/"AX"; PE characteristics / Mach-O section flags as 0x hex), segment (ELF "LOAD", Mach-O
    segment name "__DATA"), segment_index (ELF program-header index of the PT_LOAD holding it; PE section index),
    segment_flags (ELF "R"/"RW"/"RE"; Mach-O initprot hex), vaddr / rva (lowercase 0x hex), wasm_data_index,
    wasm_mem_offset (int: segment memory offset + delta, "none" for a passive / global-based segment)}. Absent fields
    are the literal "none". ELF works on sstripped files (no section headers -> program headers only). None for an
    unknown container or an offset outside the file. Pure struct parsing, never raises."""
    try:
        data = bytes(data) if not isinstance(data, (bytes, bytearray)) else data
        if not isinstance(off, int) or not 0 <= off < len(data):
            return None
        out = dict.fromkeys(LOCATE_KEYS, "none")
        if data[:4] == b"\x7fELF" and len(data) >= 52 and data[4] in (1, 2) and data[5] in (1, 2):
            _locate_elf(data, off, out)
            return out
        lay = _pe_layout(data)
        if lay:
            _locate_pe(data, off, lay, out)
            return out
        if _MO_MAGIC.get(bytes(data[:4])) or data[:4] in (b"\xca\xfe\xba\xbe", b"\xca\xfe\xba\xbf"):
            if _locate_macho(data, off, out):
                return out
        wl = wasm_layout(data) if data[:4] == b"\0asm" else None
        if wl:
            out["container"] = "wasm"
            for s in wl["sections"]:
                if s["offset"] <= off < s["offset"] + s["size"]:
                    out["section"] = s["name"]
            for sg in wl["data_segments"]:
                if sg["file_offset"] <= off < sg["file_offset"] + sg["size"]:
                    out["wasm_data_index"] = sg["index"]
                    mo = sg["mem_offset"]
                    out["wasm_mem_offset"] = "none" if mo is None else mo + off - sg["file_offset"]
            return out
    except _PARSE_ERR:
        return None
    return None


def hcfg_storage(data, hit=None):
    """GM `hcfg_storage` token (HCFG_STORAGE_TOKENS) for the validated HCFG `hit` (HcfgHit or a dict with offset +
    encoding; found with hcfg_find when omitted -- a zip/jar scans its application classes / entries). "none" when no
    crc-valid HCFG exists; None (not a guess) when the hit's encoding is outside the rule list (hex, xor, zlib, ...),
    or a literal HCFG lies in no section of a parsed native/wasm container (header, overlay, wasm code). A jar's
    literal HCFG (class constant pool, no native section) and a blob in an unknown container -> "raw". SPECULATIVE
    edges: d03 .NET FieldRVA in PE .text (code section) -> "raw" (alternative raw_const_array); Mach-O __hcfg counts as
    the .hcfg section."""
    try:
        data = bytes(data)
        if hit is None:
            if data[:2] == b"PK":
                for _, cls in jar_app_classes(data):
                    tok = hcfg_storage(cls)
                    if tok != "none":
                        return tok
                try:
                    zf = zipfile.ZipFile(io.BytesIO(data))
                    for i in zf.infolist()[:2000]:
                        if not i.filename.endswith(".class") and 0 < i.file_size <= HCFG_ZIP_MAX:
                            tok = hcfg_storage(zf.read(i))
                            if tok != "none":
                                return tok
                except (zipfile.BadZipFile, RuntimeError, NotImplementedError, OSError, EOFError, zlib.error):
                    pass
                return "none"
            hit = hcfg_find(data)
            if hit is None:
                return "none"
        g = hit.get if isinstance(hit, dict) else lambda k: getattr(hit, k, None)
        enc, off = g("encoding"), g("offset")
        if enc in _HCFG_B64_ENC:
            return "base64"
        if enc not in ("raw", "split-raw") or not isinstance(off, int) or data[off:off + 4] != HCFG_MAGIC:
            return None
        loc = hcfg_section_of(data, off)
        if loc is None:
            return "raw"
        if loc["section"] is None:
            return None
        if loc["container"] != "wasm" and loc["section"] in (".hcfg", "__hcfg"):
            return "raw_hcfg_section"
        if loc["container"] == "wasm":
            return "wasm_data_segment"
        return "raw_const_array" if loc["data"] else "raw"
    except _PARSE_ERR:
        return None


# --- same-source build pairs (D15 stripped/symbolized, D16 compact/direct; D17+ O0/O2, static/dynamic, pie/nopie,
# debug/release, packed/unpacked, plain/obfuscated). Ids are `dNN_analysis_<tag>_<field>`: the tag names ONE member.

def _elf_pair_facts(data):
    E = "<" if data[5] == 1 else ">"
    b64 = data[4] == 2
    u16 = lambda o: struct.unpack_from(E + "H", data, o)[0]
    u32 = lambda o: struct.unpack_from(E + "I", data, o)[0]
    uw = (lambda o: struct.unpack_from(E + "Q", data, o)[0]) if b64 else u32
    et, entry = u16(16), uw(24)
    phoff, shoff = (uw(32), uw(40)) if b64 else (u32(28), u32(32))
    p = 52 if b64 else 40
    phes, phn, shes, shn, shstr = u16(p + 2), u16(p + 4), u16(p + 6), u16(p + 8), u16(p + 10)
    ptypes, xseg = [], 0
    for k in range(min(phn, 256) if phoff else 0):
        o = phoff + k * phes
        if o + (56 if b64 else 32) > len(data):
            break
        t = u32(o)
        ptypes.append(t)
        flags, filesz = (u32(o + 4), uw(o + 32)) if b64 else (u32(o + 24), u32(o + 16))
        if t == 1 and flags & 1:   # PT_LOAD + PF_X
            xseg += filesz
    secs = []   # (name_off, type, flags, offset, size, link, entsize)
    if shoff and shes >= (64 if b64 else 40):
        for k in range(min(shn, 4096)):
            o = shoff + k * shes
            if o + shes > len(data):
                break
            if b64:
                secs.append((u32(o), u32(o + 4), uw(o + 8), uw(o + 24), uw(o + 32), u32(o + 40), uw(o + 56)))
            else:
                secs.append((u32(o), u32(o + 4), u32(o + 8), u32(o + 16), u32(o + 20), u32(o + 24), u32(o + 36)))

    def cstr(i, off):
        if not 0 <= i < len(secs):
            return ""
        s = secs[i][3] + off
        e = data.find(b"\0", s, s + 4096)
        return data[s:e].decode("utf-8", "replace") if s < len(data) and e >= s else ""

    names = [cstr(shstr, s[0]) if shstr < len(secs) else "" for s in secs]
    imports, needed = [], []
    for i, (_, t, _, off, size, link, ent) in enumerate(secs):
        if t == 11 and ent:   # .dynsym: undefined (SHN_UNDEF) named symbols = what the image imports
            for k in range(1, min(size // ent, 50000)):
                o = off + k * ent
                if o + ent > len(data):
                    break
                nm, shndx = (u32(o), u16(o + 6)) if b64 else (u32(o), u16(o + 14))
                n = cstr(link, nm) if shndx == 0 else ""
                if n:
                    imports.append(n)
        elif t == 6:   # .dynamic: DT_NEEDED (1)
            w = 16 if b64 else 8
            for o in range(off, min(off + size, len(data) - w + 1), w):
                tag = uw(o)
                if tag == 0:
                    break
                if tag == 1:
                    needed.append(cstr(link, uw(o + w // 2)))
    interp = 3 in ptypes
    code = sum(s[4] for s in secs if s[2] & 4 and s[1] != 8) or xseg   # SHF_EXECINSTR, else PF_X segments
    return {"format": "elf", "elf_type": ELF_TYPE_NAME.get(et, str(et)), "entry_point": hex(entry),
            "section_names": names, "has_symtab": "true" if any(s[1] == 2 for s in secs) else "false",
            "has_interp": "true" if interp else "false", "linking": "dynamic" if interp else "static",
            "is_static": "false" if interp else "true", "is_pie": "true" if et == 3 and interp else "false",
            "has_debug_info": "true" if {".debug_info", ".zdebug_info"} & set(names) else "false",
            "imports": imports, "needed": needed, "code_size": code}


def pair_member_facts(data):
    """Per-member facts that DIFFER inside a same-source build pair, pure header walk (no subprocess):
    ELF {format, elf_type ET_* (readelf constant), entry_point hex (e_entry), section_names (header-table order,
    index 0 = ""), has_symtab, has_interp, linking static/dynamic + is_static (no PT_INTERP), is_pie (ET_DYN +
    PT_INTERP), has_debug_info (.debug_info), imports (undefined named .dynsym symbols, .dynsym order, no @version),
    needed (DT_NEEDED order), code_size (SHF_EXECINSTR bytes, else PF_X filesz), is_packed (UPX)}
    + machine_facts {machine (label), machine_num (decimal e_machine / PE Machine), bits, endian} (ELF and PE).
    PE: {format, entry_point (ImageBase+AddressOfEntryPoint), section_names, code_size, is_packed}. Else None."""
    try:
        head = bytes(data[:4096])
        packed = b"UPX!" in head or b"UPX0" in head or b"UPX1" in head
        if data[:4] == b"\x7fELF" and data[4:5] in (b"\x01", b"\x02") and data[5:6] in (b"\x01", b"\x02") \
                and len(data) >= 52:
            if data[6] != 1:   # EI_VERSION: a garbage / impostor header, not a build
                return None
            f = _elf_pair_facts(data)
        else:
            lay = _pe_layout(data)
            if not lay:
                return None
            pe = int.from_bytes(data[0x3c:0x40], "little")
            opt = pe + 24
            magic, aep = struct.unpack_from("<H", data, opt)[0], struct.unpack_from("<I", data, opt + 16)[0]
            base = struct.unpack_from("<Q", data, opt + 24)[0] if magic == 0x20b else \
                struct.unpack_from("<I", data, opt + 28)[0]
            secs = lay[1]
            chars = [struct.unpack_from("<I", data, lay[0] + 40 * k + 36)[0] for k in range(len(secs))]
            f = {"format": "pe", "entry_point": hex(base + aep), "section_names": [s[0] for s in secs],
                 "code_size": sum(s[4] for s, c in zip(secs, chars) if c & 0x20000000)}
            packed = packed or any(s[0].startswith("UPX") for s in secs)
        f["is_packed"] = "true" if packed else "false"
        mf = machine_facts(data) or {}   # cross-arch pairs: machine label / e_machine decimal / bits / endian
        for k in ("machine", "machine_num", "bits", "endian"):
            if k in mf:
                f[k] = mf[k]
        return f
    except Exception:   # truncated / hostile headers: cannot answer
        return None


_PAIR_NEG = {"no", "non", "not", "un"}
_PAIR_SKIP = {"variant", "elf", "exe", "jar", "dll", "bin", "so", "config", "has", "hcfg", "analysis", "artifact",
              "is", "entry", "section"}
# tag (tokens joined) -> structural predicates tried in order until one picks exactly one member:
# (fact, value) = that fact equals value; ("code_size", "max"/"min") = the largest / smallest code.
_PAIR_FAMILY = {}
for _t, _p in (
        (("static", "statically", "staticlink"), [("is_static", "true")]),
        (("dynamic", "dynamically", "shared", "dyn"), [("is_static", "false")]),
        (("pie",), [("is_pie", "true")]),
        (("nopie", "nonpie", "notpie", "exec", "fixed"), [("is_pie", "false")]),
        (("packed", "upx", "upxed", "compressed", "packer"), [("is_packed", "true")]),
        (("unpacked", "original", "unpack"), [("is_packed", "false")]),
        (("debug", "g", "dbg", "debuginfo", "dwarf"), [("has_debug_info", "true"), ("has_symtab", "true")]),
        (("release", "nodebug", "rel"), [("has_debug_info", "false"), ("has_symtab", "false"), ("code_size", "min")]),
        (("stripped", "strip"), [("has_symtab", "false"), ("has_debug_info", "false")]),
        (("symbolized", "unstripped", "symbolic", "symbols", "nostrip"), [("has_symtab", "true")]),
        (("plain", "clean", "normal"), [("is_packed", "false"), ("code_size", "min")]),
        (("obfuscated", "obf", "obfus", "ollvm"), [("code_size", "max")]),
        (("o0", "unoptimized", "noopt", "o0g"), [("code_size", "max")]),
        (("o1", "o2", "o3", "os", "oz", "og", "optimized", "opt", "compact", "small", "size", "fast"),
         [("code_size", "min")]),
        # cross-arch pairs (tag tokens joined: `x86_64` -> x8664); an alias tag (`arm64` vs a `-aarch64` name) or a
        # renamed member falls through the name match to the e_machine number (62 / 183 / 243 / 40 / 3)
        (("x8664", "amd64", "x64", "x86x64"), [("machine_num", "62")]),
        (("aarch64", "arm64", "armv8", "a64"), [("machine_num", "183")]),
        (("riscv", "riscv64", "rv64", "riscv32", "rv32", "rv64gc", "rv64imac"), [("machine_num", "243")]),
        (("arm", "arm32", "armv7", "armv7a", "armhf", "armel", "aarch32", "thumb"), [("machine_num", "40")]),
        (("x86", "i386", "i686", "x8632", "ia32"), [("machine_num", "3")])):
    for _k in _t:
        _PAIR_FAMILY[_k] = _p
del _t, _p, _k


def _pair_tokens(name):
    stem = name.lower().replace("\\", "/").rsplit("/", 1)[-1]
    stem = re.sub(r"\.[a-z]{1,5}$", "", stem)   # extension never carries the tag (`-no-pie.elf` != `no_pie_elf`)
    return [t for t in re.split(r"[^a-z0-9]+", stem) if t]


def _pair_name_hit(want, toks):
    """True if `want` (tag tokens joined) equals whole adjacent name tokens joined, not after a negation token."""
    for s in range(len(toks)):
        acc = ""
        for e in range(s, len(toks)):
            acc += toks[e]
            if acc == want:
                if s and toks[s - 1] in _PAIR_NEG:
                    break
                return True
            if len(acc) >= len(want) or not want.startswith(acc):
                break
    return False


def pair_route(field, members):
    """Route `<tag>_<field>` (the part after `analysis_`) to ONE member of a build pair.
    members = [(name, bytes)] of the day's group. Returns (index, rest_field, how) or None (not a pair field).
    1) the LONGEST leading tag (1..n-1 tokens; `no_pie` == `nopie` == `no-pie`) found in exactly one member's file
       name as whole tokens (`pie` does not match `no-pie`); 2) renamed members: the tag family's structural
       predicate over pair_member_facts (no INTERP = static, ET_DYN+INTERP = pie, UPX = packed, .debug_info = debug,
       no .symtab = stripped, smaller code = O1-Os/compact/optimized, larger = O0/obfuscated)."""
    try:
        parts = [p for p in field.lower().split("_") if p]
        if len(members) < 2 or len(parts) < 2 or parts[0] in _PAIR_SKIP or parts[0].isdigit():
            return None
        toks = [_pair_tokens(n) for n, _ in members]
        for k in range(len(parts) - 1, 0, -1):
            if parts[k - 1] in _PAIR_SKIP:
                continue
            want = "".join(parts[:k])
            hit = [i for i, t in enumerate(toks) if _pair_name_hit(want, t)]
            if len(hit) == 1:
                return hit[0], "_".join(parts[k:]), "name"
            if hit:
                break   # a shorter tag can only hit more members
        for k in range(len(parts) - 1, 0, -1):
            preds = _PAIR_FAMILY.get("".join(parts[:k]))
            if not preds:
                continue
            fx = [pair_member_facts(b) if isinstance(b, (bytes, bytearray, memoryview)) else None for _, b in members]
            for fact, want in preds:
                vals = [f.get(fact) if f else None for f in fx]
                if fact == "code_size":
                    sizes = [v for v in vals if isinstance(v, int) and v > 0]
                    if len(sizes) < 2 or len(set(sizes)) < len(sizes):
                        continue
                    pick = (max if want == "max" else min)(sizes)
                    hit = [i for i, v in enumerate(vals) if v == pick]
                else:
                    hit = [i for i, v in enumerate(vals) if v == want]
                if len(hit) == 1:
                    return hit[0], "_".join(parts[k:]), "struct:" + fact
            return None
    except Exception:   # noqa: BLE001 -- never raise past the router
        pass
    return None


def zip_cd_sha256(data, pwd=None, prefix=None):
    """[(name, sha256 hex)] of the archive's file members in CENTRAL-DIRECTORY order (= `dNN_artifact_sha256_K`
    numbering, K 1-based), optionally only names starting with `prefix` (path-insensitive). AES zips via pyzipper.
    None if not a readable zip."""
    import hashlib
    try:
        try:
            import pyzipper
            z = pyzipper.AESZipFile(io.BytesIO(data))
        except ImportError:
            z = zipfile.ZipFile(io.BytesIO(data))
        if pwd:
            z.setpassword(pwd if isinstance(pwd, bytes) else pwd.encode())
        out = []
        for zi in z.infolist():
            base = zi.filename.rsplit("/", 1)[-1]
            if zi.is_dir() or (prefix and not base.lower().startswith(prefix.lower())):
                continue
            out.append((zi.filename, hashlib.sha256(z.read(zi)).hexdigest()))
        return out
    except Exception:   # noqa: BLE001
        return None


# --- per-language identity facts (D8-D17 groups: Swift / Nim / Zig / D / FPC / Crystal / ObjC / Ada / Go / Rust) ----
LANG_ORDER = ("swift", "objc", "nim", "zig", "d", "fpc", "crystal", "gnat", "go", "rust")
_LANG_BYTES = {   # one raw-byte marker per runtime (only scanned when sections/symbols did not already decide it)
    "swift": b"swift_retain", "objc": b"objc_msg", "nim": b"NimMain", "zig": b"ziglang", "d": b"_D4core",
    "fpc": b"FPC 3.", "crystal": b"Crystal::", "gnat": b"__gnat_", "go": b"\xff Go buildinf:", "rust": b"/rustc/",
}
_SWIFT_SYS = {"Swift", "Foundation", "FoundationEssentials", "FoundationInternationalization", "FoundationNetworking",
              "FoundationXML", "Dispatch", "Glibc", "Musl", "SwiftGlibc", "Synchronization", "Observation",
              "Distributed", "RegexBuilder", "CoreFoundation", "Darwin", "ObjectiveC", "SwiftShims", "XCTest",
              "Cxx", "CxxStdlib", "SwiftOnoneSupport", "os", "WinSDK", "Android", "Testing"}
_D_SYS = {"core", "std", "rt", "object", "gc", "etc", "ldc", "gcc", "TypeInfo"}
_ADA_SYS = ("ada", "system", "gnat", "interfaces", "_ada", "__gnat", "_gnat")
_SWIFT_KIND = {"V": "struct", "C": "class", "O": "enum", "P": "protocol"}
_D_ID = re.compile(r"(\d+)")
_NIM_SYM = re.compile(r"^(.+?)__([A-Za-z0-9]+)_u\d+$")
_RUST_LEGACY = re.compile(r"^_ZN.*17h[0-9a-f]{16}E$")
_SWIFT_MANGLED = re.compile(r"^_?\$[sS](?:s|[1-9])")   # `$Slice:0` (Crystal) is no Swift mangling
_SWIFT_MOD = re.compile(r"_?\$[sS]([1-9]\d*)")


def _elf_symbols(data, cap=400_000):
    """[(name, st_info type, defined)] from SHT_SYMTAB + SHT_DYNSYM (raw structs, capped); [] when absent."""
    b64, e = data[4] == 2, "<" if data[5] == 1 else ">"
    shoff = struct.unpack_from(e + ("Q" if b64 else "I"), data, 40 if b64 else 32)[0]
    shes, shn = struct.unpack_from(e + "HH", data, 58 if b64 else 46)
    sh = (e + "4xI8x8xQQIi8xQ") if b64 else (e + "4xI4x4xIIIi4xI")   # type, offset, size, link, -, entsize
    if not shoff or shes < (64 if b64 else 40) or shoff + shn * shes > len(data):
        return []
    secs = [struct.unpack_from(sh, data, shoff + k * shes) for k in range(min(shn, 65535))]
    out = []
    for ty, off, size, link, _, ent in secs:
        if ty not in (2, 11) or not 0 <= link < len(secs) or off + size > len(data):
            continue
        so, sn = secs[link][1], secs[link][2]
        ent = ent or (24 if b64 else 16)
        for k in range(min(size // ent, cap - len(out))):
            o = off + k * ent
            if b64:
                nm, info, shndx = struct.unpack_from(e + "IBxH", data, o)
            else:
                nm, info, shndx = struct.unpack_from(e + "I8xBxH", data, o)
            if not nm or nm >= sn:
                continue
            z = data.find(b"\0", so + nm, so + sn)
            out.append((bytes(data[so + nm:z if z >= 0 else so + sn]).decode("latin-1"), info & 0xF, shndx != 0))
    return out


def _swift_ids(s, p):
    """[(identifier, kind letter after it)] from offset p of a Swift `$s` mangling (plain <len><ident> runs only)."""
    out = []
    while p < len(s) and s[p].isdigit() and s[p] != "0":
        m = _D_ID.match(s, p)
        n, p = int(m.group(1)), m.end()
        if p + n > len(s):
            break
        out.append((s[p:p + n], s[p + n:p + n + 1]))
        p += n
    return out


def lang_facts(data, max_syms=400_000):
    """Language identity + theme facts of an ELF / PE / Mach-O / wasm image (bytes only, no subprocess).
    has_<lang>_runtime "true"/"false" for swift (swift5_* sections, `$s` symbols, Swift runtime strings), objc
    (__objc_* / .objc_* sections or symbols, objc_msg_lookup/objc_msgSend), nim (NimMain), zig (.comment zig / zig std
    paths), d (_D4core/_D2rt symbols, druntime), fpc (FPC banner, .fpcdata), crystal (Crystal:: symbols, crystal/src),
    gnat (+ alias has_ada_runtime: GNAT Version, __gnat_, adainit), go (buildinfo, runtime.goexit), rust (rust_panic,
    /rustc/ paths); has_wasm_module. has_<lang>_mangled_symbol: swift `$s`/`$S`/`_$s`, d `_D<digit>`, nim
    `<proc>__<mod>_u<N>`, rust legacy `_ZN..17h<hash>E` / v0 `_R`, cpp `_Z` (not rust). language = first runtime hit in
    LANG_ORDER ("c"/"wasm" fallback). User-module names (stdlib/runtime modules dropped, MANGLED forms kept alongside):
    swift_module, swift_types {name: struct/class/enum/protocol}, swift_protocols, swift_functions (+ _mangled);
    nim_module, nim_procs (+ _mangled); d_module, d_functions (qualified mod.name, + _mangled); objc_classes (defined
    ._OBJC_CLASS_ / _OBJC_CLASS_$_), objc_selectors (objc_sel_name_ / __objc_methname), objc_methods "-[C sel]";
    ada_subprograms (pkg__sub, + _mangled). Absent -> "none" / "false" / []; not an executable image -> None."""
    try:
        d = memoryview(data) if not isinstance(data, (bytes, bytearray)) else data
        d = bytes(d) if isinstance(d, memoryview) else d
        if d[:4] == b"\x7fELF" and len(d) >= 64 and d[4] in (1, 2) and d[5] in (1, 2):
            fmt = "elf"
        elif d[:2] == b"MZ" and len(d) >= 0x40 and d[int.from_bytes(d[0x3c:0x40], "little"):][:4] == b"PE\0\0":
            fmt = "pe"
        elif d[:4] in _MO_MAGIC or d[:4] in (b"\xca\xfe\xba\xbe", b"\xbe\xba\xfe\xca"):
            fmt = "macho"
        elif d[:4] == b"\0asm" and len(d) >= 8:
            fmt = "wasm"
        else:
            return None
        secnames, syms, comment = [], [], b""
        if fmt == "elf":
            lay = _elf_layout(d)
            if lay:
                for nm, o, n in lay[1]:
                    secnames.append(nm)
                    if nm == ".comment":
                        comment = bytes(d[o:o + min(n, 4096)])
            try:
                syms = _elf_symbols(d, max_syms)
            except _PARSE_ERR:
                syms = []
        elif fmt == "macho":
            try:
                secnames = [s.get("sectname", s.get("name", "")) for s in (macho_layout(d) or {}).get("sections", [])]
            except Exception:   # noqa: BLE001
                secnames = []
        elif fmt == "pe":
            try:
                secnames = [s[0] for s in (_pe_layout(d) or (0, []))[1]]
            except Exception:   # noqa: BLE001
                secnames = []
        names = [s[0] for s in syms]
        nset = set(names)
        hit = {k: False for k in LANG_ORDER}
        hit["swift"] = any(s.startswith("swift5_") or s.startswith("__swift5_") for s in secnames)
        hit["objc"] = any(s.startswith("__objc_") or s.startswith(".objc_") for s in secnames)
        hit["nim"] = "NimMain" in nset or "NimMainModule" in nset
        hit["zig"] = b"zig" in comment.lower()
        hit["fpc"] = ".fpcdata" in secnames
        hit["go"] = ".gopclntab" in secnames or ".go.buildinfo" in secnames or "runtime.goexit" in nset
        mang = {"swift": False, "d": False, "nim": False, "rust": False, "cpp": False}
        for n in names:
            c = n[:1]
            if c == "$" or c == "_" and n[1:2] == "$":
                if _SWIFT_MANGLED.match(n):
                    mang["swift"] = True
            elif c == "_":
                if n[1:2] == "D" and n[2:3].isdigit():
                    mang["d"] = True
                    if n.startswith(("_D4core", "_D2rt", "_D6object")):
                        hit["d"] = True
                elif n[1:2] == "R" and n[2:3].isupper() or n[1:3] == "ZN" and _RUST_LEGACY.match(n):
                    mang["rust"] = True
                elif n[1:2] == "Z":
                    mang["cpp"] = True
                elif n.startswith(("__objc_load", "_OBJC_CLASS_$_")):
                    hit["objc"] = True
                elif n.startswith("__gnat_"):
                    hit["gnat"] = True
            elif c == "." and n.startswith("._OBJC_") or c == "o" and n.startswith("objc_msg"):
                hit["objc"] = True
            elif c in "C*" and n.startswith(("Crystal::", "*Crystal::")):
                hit["crystal"] = True
            elif c in "Ff" and n.startswith(("FPC_", "fpc_")):
                hit["fpc"] = True
            elif c == "r" and n.startswith(("rust_panic", "rust_begin_unwind")):
                hit["rust"] = True
            elif c == "a" and n.startswith(("adainit", "ada__")):
                hit["gnat"] = True
            if not mang["nim"] and "_u" in n and _NIM_SYM.match(n):
                mang["nim"] = True
        hit["swift"] = hit["swift"] or mang["swift"]
        if fmt != "wasm":
            for lang in LANG_ORDER:
                if not hit[lang] and _LANG_BYTES[lang] in d:
                    hit[lang] = True
        lang = next((k for k in LANG_ORDER if hit[k]), "wasm" if fmt == "wasm" else ("cpp" if mang["cpp"] else "c"))
        tf = lambda b: "true" if b else "false"   # noqa: E731
        out = {"format": fmt, "language": lang, "has_wasm_module": tf(fmt == "wasm")}
        for k in LANG_ORDER:
            out[f"has_{k}_runtime"] = tf(hit[k])
        out["has_ada_runtime"] = out["has_gnat_runtime"]
        for k, v in mang.items():
            out[f"has_{k}_mangled_symbol"] = tf(v)
        # --- user-module names ---
        sw_t, sw_f, sw_fm, mods = {}, set(), set(), {}
        if mang["swift"]:
            for n, ty, dfn in syms:
                m = _SWIFT_MOD.match(n)
                if not m:
                    continue
                k = int(m.group(1))
                mod = n[m.end():m.end() + k]
                if mod in _SWIFT_SYS or mod[:1] == "_" or mod.startswith("Foundation") or len(mod) < k:
                    continue
                ids = _swift_ids(n, m.start(1))
                chain = []
                for ident, kind in ids[1:]:
                    if kind in _SWIFT_KIND:
                        sw_t.setdefault(ident, _SWIFT_KIND[kind])
                        chain.append(ident)
                        continue
                    if dfn and ty == 2 and ident[:1].isalpha():
                        sw_f.add(".".join(chain + [ident]))
                        sw_fm.add(n)
                        mods[mod] = mods.get(mod, 0) + 1
                    break
        out["swift_module"] = max(mods, key=mods.get) if mods else "none"
        out["swift_types"] = dict(sorted(sw_t.items()))
        out["swift_protocols"] = sorted(k for k, v in sw_t.items() if v == "protocol")
        out["swift_functions"], out["swift_functions_mangled"] = sorted(sw_f), sorted(sw_fm)
        nim_p, nim_m, nmods = set(), set(), {}
        dfun, dfm, dmods = set(), set(), {}
        ada_p, ada_m = set(), set()
        cls, sels, meth = set(), set(), []
        for n, ty, dfn in syms:
            if not dfn:
                continue
            m = _NIM_SYM.match(n) if "_u" in n else None
            if m and ty == 2 and m.group(2) != "system" and "Z" not in m.group(2) \
                    and not (m.group(1).startswith("eq") and m.group(1).endswith("_")):   # =destroy/=copy hooks
                nim_p.add(m.group(1))
                nim_m.add(n)
                nmods[m.group(2)] = nmods.get(m.group(2), 0) + 1
            if n[:2] == "_D" and n[2:3].isdigit():
                ids, p = [], 2
                while p < len(n) and n[p].isdigit() and n[p] != "0":
                    mm = _D_ID.match(n, p)
                    k, p = int(mm.group(1)), mm.end()
                    ids.append(n[p:p + k])
                    p += k
                if ty == 2 and len(ids) >= 2 and ids[0] not in _D_SYS and n[p:p + 1] in ("F", "M") \
                        and not ids[-1].startswith("__"):
                    dfun.add(".".join(ids))
                    dfm.add(n)
                    dmods[ids[0]] = dmods.get(ids[0], 0) + 1
            for pre in ("._OBJC_CLASS_", "_OBJC_CLASS_$_", "__objc_class_name_"):
                if n.startswith(pre):
                    cls.add(n[len(pre):])
            for pre in (".objc_sel_name_", "objc_sel_name_"):
                if n.startswith(pre):
                    sels.add(n[len(pre):])
            if n[:3] in ("_i_", "_c_") and "__" in n[3:]:
                meth.append(n)
            if hit["gnat"] and ty == 2 and "__" in n.strip("_") and n == n.lower() and not n.startswith(_ADA_SYS):
                pkg, _, sub = n.partition("__")
                if pkg and sub and not sub.startswith("_") and pkg.isidentifier():
                    ada_p.add(f"{pkg}.{sub.replace('__', '.')}")
                    ada_m.add(n)
        if fmt == "macho":
            try:
                for s in (macho_layout(d) or {}).get("sections", []):
                    if s.get("sectname", s.get("name")) == "__objc_methname":
                        o, z = s.get("offset", 0), s.get("size", 0)
                        sels.update(x.decode("latin-1") for x in bytes(d[o:o + z]).split(b"\0") if x)
            except Exception:   # noqa: BLE001
                pass
        omethods = set()
        for n in meth:
            c, _, rest = n[3:].partition("_")
            cat, _, sel = rest.partition("_")
            want = sel.replace("_", ":")
            sel = next((s for s in sels if s.replace(":", "_") == sel), want)
            omethods.add(f"{'-' if n[1] == 'i' else '+'}[{c}{'(' + cat + ')' if cat else ''} {sel}]")
        out["nim_module"] = max(nmods, key=nmods.get) if nmods else "none"
        out["nim_procs"], out["nim_procs_mangled"] = sorted(nim_p), sorted(nim_m)
        out["d_module"] = max(dmods, key=dmods.get) if dmods else "none"
        out["d_functions"], out["d_functions_mangled"] = sorted(dfun), sorted(dfm)
        out["objc_classes"] = sorted(c for c in cls if f"._OBJC_METACLASS_{c}" in nset or
                                     f"_OBJC_METACLASS_$_{c}" in nset or fmt != "elf")   # defined here, not imported
        out["objc_selectors"], out["objc_methods"] = sorted(sels), sorted(omethods)
        out["ada_subprograms"], out["ada_subprograms_mangled"] = sorted(ada_p), sorted(ada_m)
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def lang_field(data, name):
    """One lang_facts value (lists as JSON-able lists); "none" when the input is no executable image or the field is
    unknown, so a decoy never raises."""
    try:
        return (lang_facts(data) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- gnat_facts: Ada / GNAT deep facts (D17 ada_br17_main theme) ------------------------------------------------------
_DW_LANG = {0x01: "C89", 0x02: "C", 0x03: "Ada83", 0x04: "C_plus_plus", 0x0c: "C99", 0x0d: "Ada95", 0x1d: "C11",
            0x21: "C_plus_plus_14", 0x2c: "C17", 0x2e: "Ada2005", 0x2f: "Ada2012", 0x1c: "Rust", 0x16: "Go"}
_DW_FIXED = {0x01: -1, 0x05: 2, 0x06: 4, 0x07: 8, 0x0b: 1, 0x0c: 1, 0x0e: -2, 0x10: -2, 0x11: 1, 0x12: 2, 0x13: 4,
             0x14: 8, 0x17: -2, 0x19: 0, 0x1c: 4, 0x1d: -2, 0x1e: 16, 0x1f: -2, 0x20: 8, 0x21: 0, 0x24: 8, 0x25: 1,
             0x26: 2, 0x27: 3, 0x28: 4, 0x29: 1, 0x2a: 2, 0x2b: 3, 0x2c: 4}   # -1 = addr size, -2 = offset size
_ADA_STD_EXC = ("constraint_error", "program_error", "storage_error", "tasking_error", "numeric_error")
_ADA_EXC_SYS = ("ADA.", "SYSTEM.", "GNAT.", "INTERFACES.", "_ABORT_SIGNAL", "_STANDARD.")


def _dwarf_top_dies(d, secs, e, cap=4096):
    """[(producer, language code, name)] of each compile/partial unit's top DIE (raw .debug_info walk; strx forms and
    compressed sections -> None values)."""
    sec = {n: (o, z) for n, o, z in secs}
    if ".debug_info" not in sec or ".debug_abbrev" not in sec:
        return []
    io_, iz = sec[".debug_info"]
    ao, az = sec[".debug_abbrev"]
    strs = {k: sec.get(n) for k, n in ((0x0e, ".debug_str"), (0x1f, ".debug_line_str"))}

    def cstr(form, off):
        s = strs.get(form)
        if s is None or off >= s[1]:
            return None
        z = d.find(b"\0", s[0] + off, s[0] + s[1])
        return bytes(d[s[0] + off:z if z >= 0 else s[0] + s[1]]).decode("latin-1")
    out, p, end, abbr = [], io_, io_ + iz, {}
    while p + 11 <= end and len(out) < cap:
        ln, osz = struct.unpack_from(e + "I", d, p)[0], 4
        p += 4
        if ln == 0xffffffff:
            ln, osz = struct.unpack_from(e + "Q", d, p)[0], 8
            p += 8
        nxt = p + ln
        ver = struct.unpack_from(e + "H", d, p)[0]
        q = p + 2
        try:
            if ver >= 5:
                ut, asz = d[q], d[q + 1]
                aoff = int.from_bytes(d[q + 2:q + 2 + osz], "little" if e == "<" else "big")
                q += 2 + osz + (8 if ut in (4, 5) else 0)
                if ut not in (1, 3, 4, 5):
                    p = nxt
                    continue
            elif 2 <= ver <= 4:
                aoff = int.from_bytes(d[q:q + osz], "little" if e == "<" else "big")
                asz, q = d[q + osz], q + osz + 1
            else:
                break
            code, q = _leb(d, q)
            tab, a = abbr.get(aoff) or ({}, ao + aoff)
            if code not in tab:
                while a < ao + az and len(tab) < 4096:
                    c, a = _leb(d, a)
                    if not c:
                        break
                    _, a = _leb(d, a)
                    a += 1
                    specs = []
                    while True:
                        at, a = _leb(d, a)
                        fm, a = _leb(d, a)
                        ic = None
                        if fm == 0x21:
                            ic, a = _leb(d, a, True)
                        if not at and not fm:
                            break
                        specs.append((at, fm, ic))
                    tab[c] = specs
                    if c == code:
                        break
                abbr[aoff] = (tab, a)
            prod = lang = name = None
            for at, fm, ic in tab.get(code, ()):
                while fm == 0x16:
                    fm, q = _leb(d, q)
                val = None
                if fm == 0x08:
                    z = d.find(b"\0", q, nxt)
                    val, q = bytes(d[q:z]).decode("latin-1"), z + 1
                elif fm in (0x0f, 0x15, 0x1a, 0x1b, 0x22, 0x23, 0x0d):
                    val, q = _leb(d, q, fm == 0x0d)
                elif fm in (0x09, 0x18):
                    n, q = _leb(d, q)
                    q += n
                elif fm in (0x03, 0x04, 0x0a):
                    k = {0x03: 2, 0x04: 4, 0x0a: 1}[fm]
                    q += k + int.from_bytes(d[q:q + k], "little" if e == "<" else "big")
                elif fm == 0x21:
                    val = ic
                elif fm in _DW_FIXED:
                    k = _DW_FIXED[fm]
                    k = asz if k == -1 else osz if k == -2 else k
                    val, q = int.from_bytes(d[q:q + k], "little" if e == "<" else "big"), q + k
                else:
                    break
                if at in (0x25, 0x03):
                    s = val if isinstance(val, str) else cstr(fm, val) if fm in strs and val is not None else None
                    if at == 0x25:
                        prod = s
                    else:
                        name = s
                elif at == 0x13 and isinstance(val, int):
                    lang = val
            out.append((prod, lang, name))
        except (IndexError, ValueError, struct.error, KeyError):
            pass
        p = nxt
    return out


def _ada_name(sym):
    """GNAT-encoded symbol -> Ada name: `_ada_main` -> main, `pkg__sub__2` -> pkg.sub, `x.cold`/`x.0` suffix dropped."""
    s = re.sub(r"\.(cold|part|isra|constprop|\d+)(\.\d+)*$", "", sym)
    s = s[5:] if s.startswith("_ada_") else s
    s = re.sub(r"__\d+$", "", s)
    return s.replace("__", ".")


def gnat_facts(data, max_syms=400_000, decoder=True, hit=None):
    """Ada / GNAT deep facts of an ELF/PE/Mach-O image (bytes only): has_gnat_runtime (__gnat_ / ada__ / system__
    symbols or bytes, `GNAT Version:`, adainit+adafinal), gnat_version ("14.2.0" from the binder's `GNAT Version: 14.2.0`)
    + gnat_version_string; ada_main_symbol (`_ada_<main>`: FUNC symbol, else the binder's .rodata main-program-name
    string) + ada_main (Ada name); main_source (`<main>.adb`); has_adainit/has_adafinal/has_gnat_main, binder_symbols
    (defined adainit/adafinal/main/ada_main___elabb/...), elab_symbols (non-runtime `*___elab[bs]`);
    ada_subprograms (pkg.sub + the main, user units only) + _mangled; dwarf_producer ("GNU Ada 14.2.0"),
    dwarf_producer_full, dwarf_producer_version, dwarf_language ("DW_LANG_Ada95", Ada CUs preferred) + _code,
    dwarf_languages; ada_exceptions / user_exceptions (Exception_Data structs: Lang 'A' + Name_Length + Full_Name
    pointer -> "PKG.NAME"), standard_exceptions (defined constraint_error/...); decoder_function (+ _ada name), decoder_key
    (0x..), decoder_algorithm, decoder_key_equals_header (decoder_facts over `hit` or hcfg_find; decoder=False skips it,
    a 0.3 s scan deadline bounds a corrupted blob). Absent -> "none"/"false"/[]; not an executable image -> None."""
    try:
        d = bytes(data)
        if d[:4] == b"\x7fELF" and len(d) >= 64 and d[4] in (1, 2) and d[5] in (1, 2):
            fmt = "elf"
        elif d[:2] == b"MZ" and len(d) >= 0x40 and d[int.from_bytes(d[0x3c:0x40], "little"):][:4] == b"PE\0\0":
            fmt = "pe"
        elif d[:4] in _MO_MAGIC or d[:4] in (b"\xca\xfe\xba\xbe", b"\xbe\xba\xfe\xca"):
            fmt = "macho"
        else:
            return None
        tf = lambda b: "true" if b else "false"   # noqa: E731
        syms, secs, e = [], [], "<"
        if fmt == "elf":
            e = "<" if d[5] == 1 else ">"
            secs = (_elf_layout(d) or (0, []))[1]
            try:
                syms = _elf_symbols(d, max_syms)
            except _PARSE_ERR:
                syms = []
        dfn = {n for n, _, k in syms if k}
        funcs = {n for n, ty, k in syms if k and ty == 2}
        out = {"format": fmt}
        m = re.search(rb"GNAT Version: ([^\0\r\n]{1,80})", d)
        out["gnat_version_string"] = m.group(0).decode("latin-1").strip() if m else "none"
        vm = re.match(rb"\s*(\d+(?:\.\d+)*)", m.group(1)) if m else None
        out["gnat_version"] = vm.group(1).decode() if vm else (m.group(1).decode("latin-1").strip() if m else "none")
        rt = any(n.startswith(("__gnat_", "ada__", "system__")) for n in dfn) or \
            ("adainit" in dfn and "adafinal" in dfn) or m is not None or b"__gnat_" in d
        out["has_gnat_runtime"] = out["has_ada_runtime"] = tf(rt)
        # main program: `_ada_<unit>` FUNC symbol, else binder's main-program-name string (sits beside GNAT Version)
        mains = sorted(n for n in funcs if n.startswith("_ada_") and "." not in n)
        main = mains[0] if mains else None
        if main is None and rt:
            lo = max(0, m.start() - 512) if m else 0
            ms = list(re.finditer(rb"\0(_ada_[a-z][a-z0-9_]{0,120})\0", d[lo:m.end() + 512] if m else d))
            main = ms[-1].group(1).decode() if ms else None
        out["ada_main_symbol"] = main or "none"
        out["ada_main"] = _ada_name(main) if main else "none"
        src = None
        if main:
            src = f"{main[5:]}.adb" if f"{main[5:]}.adb".encode() in d else None
        out["main_source"] = src or "none"
        out["has_adainit"], out["has_adafinal"] = tf("adainit" in dfn), tf("adafinal" in dfn)
        out["has_gnat_main"] = tf("__gnat_main" in dfn)
        if not syms and rt and fmt != "elf":
            out["has_adainit"] = tf(b"adainit\0" in d)
            out["has_adafinal"] = tf(b"adafinal\0" in d)
        out["binder_symbols"] = sorted(n for n in dfn if n in ("adainit", "adafinal", "main", "__gnat_main",
                                                               "ada_main___elabb", "ada_main__finalize_library",
                                                               "__gnat_ada_main_program_name", "gnat_envp", "gnat_argv",
                                                               "gnat_argc", "gnat_exit_status")) if rt else []
        out["elab_symbols"] = sorted(n for n in dfn if re.search(r"___elab[bs]$", n) and
                                     not n.startswith(_ADA_SYS)) if rt else []
        ada_p, ada_m = set(), set()
        if rt:
            for n in funcs:
                if n == main:
                    ada_p.add(_ada_name(n))
                    ada_m.add(n)
                elif "__" in n.strip("_") and n == n.lower() and not n.startswith(_ADA_SYS) and \
                        not n.startswith("ada_main_") and "." not in n and not re.search(r"___elab[bs]$", n):
                    pkg, _, sub = n.partition("__")
                    if pkg and sub and not sub.startswith("_") and pkg.isidentifier():
                        ada_p.add(_ada_name(n))
                        ada_m.add(n)
        out["ada_subprograms"], out["ada_subprograms_mangled"] = sorted(ada_p), sorted(ada_m)
        # DWARF compile units
        cus = _dwarf_top_dies(d, secs, e) if fmt == "elf" else []
        langs = [c[1] for c in cus if c[1] is not None]
        ada = [c for c in cus if c[1] in (0x03, 0x0d, 0x2e, 0x2f)]
        prods = [c[0] for c in cus if c[0]]
        if not prods and fmt == "elf" and ".debug_str" in {s[0] for s in secs}:
            prods = [x.decode("latin-1") for x in re.findall(rb"GNU Ada [0-9][^\0]{0,400}", d)[:1]]
        mcu = next((c for c in ada if main and c[2] and c[2].startswith(main[5:] + ".")), None)
        pfull = (mcu and mcu[0]) or next((c[0] for c in ada if c[0]), None) or \
            next((p for p in prods if p.startswith("GNU Ada")), None) or (prods[0] if prods else None)
        out["dwarf_producer_full"] = pfull or "none"
        pm = re.match(r"(.*?\d+(?:\.\d+)+)", pfull or "")
        out["dwarf_producer"] = pm.group(1) if pm else (pfull or "none")
        vm2 = re.search(r"(\d+(?:\.\d+)+)", pfull or "")
        out["dwarf_producer_version"] = vm2.group(1) if vm2 else "none"
        lc = (mcu or (ada[0] if ada else None) or (None, max(set(langs), key=langs.count) if langs else None))[1]
        out["dwarf_language_code"] = lc if lc is not None else "none"
        out["dwarf_language"] = f"DW_LANG_{_DW_LANG.get(lc, hex(lc))}" if lc is not None else "none"
        out["dwarf_languages"] = sorted({f"DW_LANG_{_DW_LANG.get(x, hex(x))}" for x in langs})
        out["dwarf_compile_units"] = len(cus)
        # exception ids: Exception_Data = {Not_Handled_By_Others u8, Lang 'A', Name_Length u32, Full_Name ptr, ...}
        exc = set()
        if rt and fmt == "elf":
            mp = _exec_map(d) if d[18] in (3, 62) or d[19] in (3, 62) else None
            vsec = [(va, off, size) for nm, va, off, size, _ in (mp[1] if mp else []) if size]
            b64 = d[4] == 2
            for nm, va, off, size, _x in (mp[1] if mp else []):
                if nm not in (".data", ".rodata", ".data.rel.ro") or size > 32 << 20:
                    continue
                for mm in re.finditer(rb"[\0\1]A", d[off:off + size]):
                    q = off + mm.start()
                    if (q - off) % (8 if b64 else 4) or q + (16 if b64 else 12) > off + size:
                        continue
                    nl = struct.unpack_from(e + "I", d, q + 4)[0] if b64 else struct.unpack_from(e + "I", d, q + 4)[0]
                    ptr = struct.unpack_from(e + ("Q" if b64 else "I"), d, q + (8 if b64 else 8))[0]
                    if not 2 <= nl <= 256:
                        continue
                    po = next((o + ptr - v for v, o, z in vsec if v <= ptr < v + z), None)
                    if po is None:
                        continue
                    s = d[po:po + nl]
                    if s[-1:] == b"\0" and re.fullmatch(rb"[A-Z_][A-Z0-9_]*(\.[A-Z_][A-Z0-9_]*)*", s[:-1]):
                        exc.add(s[:-1].decode())
        out["ada_exceptions"] = sorted(exc)
        out["user_exceptions"] = sorted(x for x in exc if "." in x and not x.startswith(_ADA_EXC_SYS))
        out["standard_exceptions"] = sorted(n for n in _ADA_STD_EXC if n in dfn) if rt else []
        # decoder routine (the function whose code references the stored HCFG blob)
        df = None
        if rt and decoder:
            hit = hit or hcfg_find(d, deadline=time.time() + 0.3)
            df = decoder_facts(d, hit=hit) if hit is not None else None
        fn = (df or {}).get("function", "none")
        out["decoder_function"] = fn
        out["decoder_function_ada"] = _ada_name(fn) if fn != "none" else "none"
        out["decoder_function_va"] = hex(df["function_va"]) if df else "none"
        out["decoder_algorithm"] = (df or {}).get("algorithm", "none")
        k = (df or {}).get("key", "none")
        out["decoder_key"] = hex(k) if isinstance(k, int) else "none"
        out["decoder_key_equals_header"] = (df or {}).get("key_equals_header", "none")
        hk = (df or {}).get("header_key", "none")
        out["header_key"] = hex(hk) if isinstance(hk, int) else "none"
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def gnat_field(data, name):
    """One gnat_facts value; "none" when the input is no executable image or the field is unknown (never raises)."""
    try:
        return (gnat_facts(data, decoder=name.startswith(("decoder_", "header_key"))) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- gfortran_facts: Fortran / GNU Fortran identity + entity facts (next-day candidate after Ada) ---------------------
# gfortran mangling: module entity `__<mod>_MOD_<name>` (module procedure / module variable), COMMON block and external
# procedure `<name>_` (lowercase + one trailing underscore), blank COMMON `__BLNK__`, main program `MAIN__` (+ a libc
# `main` stub calling _gfortran_set_args/_gfortran_set_options), SAVE'd / DATA locals `<name>.<N>`, BLOCK DATA unit
# `<name>_` (8-byte .bss marker, absent from DWARF). Runtime: DT_NEEDED libgfortran.so.N, `_gfortran_*` imports.
_DW_LANG_F = {**_DW_LANG, 0x08: "Fortran77", 0x09: "Fortran90", 0x0e: "Fortran95", 0x22: "Fortran03",
              0x23: "Fortran08", 0x2d: "Fortran18", 0x30: "Fortran23"}
_DW_FORTRAN = (0x08, 0x09, 0x0e, 0x22, 0x23, 0x2d, 0x30)
_GF_EXT = re.compile(r"^[a-z][a-z0-9_$]{0,62}_$")


def _gf_elf(d):
    """([(name, sh_type, addr, offset, size)], [(name, type, bind, shndx, value, size)]) of an ELF (raw structs)."""
    b64, e = d[4] == 2, "<" if d[5] == 1 else ">"
    shoff = struct.unpack_from(e + ("Q" if b64 else "I"), d, 40 if b64 else 32)[0]
    shes, shn, shstr = struct.unpack_from(e + "HHH", d, 58 if b64 else 46)
    if not shoff or shes < (64 if b64 else 40) or shoff + shn * shes > len(d):
        return [], []
    f = (e + "II8xQQQI4x8xQ") if b64 else (e + "II4xIIII4x4xI")   # name type [flags] addr off size link .. entsize
    raw = [struct.unpack_from(f, d, shoff + k * shes) for k in range(min(shn, 65535))]
    so = raw[shstr][3] if shstr < len(raw) else 0

    def nm(base, lim, o):
        z = d.find(b"\0", base + o, lim)
        return bytes(d[base + o:z if z >= 0 else lim]).decode("latin-1")
    secs = [(nm(so, len(d), r[0]) if so else "", r[1], r[2], r[3], r[4]) for r in raw]
    syms = []
    for _, ty, _, off, size, link, ent in raw:
        if ty not in (2, 11) or not 0 <= link < len(raw) or off + size > len(d):
            continue
        sb, sz = raw[link][3], raw[link][4]
        ent = ent or (24 if b64 else 16)
        for k in range(min(size // ent, 400_000 - len(syms))):
            o = off + k * ent
            if b64:
                n, info, shndx, val, ssz = struct.unpack_from(e + "IBxHQQ", d, o)
            else:
                n, val, ssz, info, shndx = struct.unpack_from(e + "IIIBxH", d, o)
            if n and n < sz:
                syms.append((nm(sb, sb + sz, n), info & 0xF, info >> 4, shndx, val, ssz))
    return secs, syms


def _gf_name(sym):
    """gfortran symbol -> Fortran entity: `__m_MOD_x` -> m::x, `blk_` -> blk, `__BLNK__` -> blank, `buf.0` -> buf."""
    if sym == "__BLNK__":
        return "blank"
    if sym.startswith("__") and "_MOD_" in sym:
        mod, _, name = sym[2:].partition("_MOD_")
        return f"{mod}::{name}"
    if _GF_EXT.match(sym):
        return sym[:-1]
    return re.sub(r"\.\d+$", "", sym)


def gfortran_facts(data, hcfg=True):
    """Fortran / GNU Fortran facts of an ELF image (bytes only): format, architecture, has_gfortran_runtime (+ alias
    has_fortran_runtime; DT_NEEDED libgfortran / `_gfortran_*` or MAIN__ symbols; raw-byte cues only count when the
    image has no symbol table), has_libgfortran_needed, libgfortran_soname, needed, gfortran_imports (sorted
    `_gfortran_*` names), has_main_program (MAIN__ defined), program_name (DWARF DW_AT_main_subprogram), main_source (CU
    name); fortran_modules, module_procedures `mod::name` (+ _mangled `__mod_MOD_name`), module_variables (+ _mangled),
    common_blocks (`name_` / blank, + _mangled), block_data, external_procedures (`name_` FUNCs, + _mangled),
    save_variables (`name.N` locals); dwarf_producer ("GNU Fortran2008 15.2.0") + _full / _version, dwarf_language
    ("DW_LANG_Fortran08") + _code, dwarf_languages; flow (_gf_flow): source_file(s) (STT_FILE *.f90), main_program
    (MAIN__), procedures (+ _mangled `name.N`, symtab order) / procedures_by_address (+ _mangled), procedure_addresses,
    procedure_return_values, case_table [[case, case_no]] (incl. ["default", 0]) / case_values / case_map / case_count /
    has_case_default / case_table_symbol (the _gfortran_select_string table), case_procedures {case: procedure} +
    default_procedure, env_var(s) (_gfortran_get_environment_variable_i4 names), imports (= gfortran_imports),
    dynamic_imports, compiler_banner (.comment); hcfg_symbol / hcfg_entity / hcfg_entity_kind (module_variable,
    common_block, save_variable, symbol) / hcfg_section for the raw HCFG (hcfg=False skips the scan). Absent ->
    "none" / "false" / []; not an ELF -> None."""
    try:
        d = bytes(data)
        if not (d[:4] == b"\x7fELF" and len(d) >= 64 and d[4] in (1, 2) and d[5] in (1, 2)):
            return None
        tf = lambda b: "true" if b else "false"   # noqa: E731
        e = "<" if d[5] == 1 else ">"
        try:
            secs, syms = _gf_elf(d)
        except _PARSE_ERR:
            secs, syms = [], []
        try:
            needed = list(_elf_pair_facts(d).get("needed") or [])
        except Exception:   # noqa: BLE001
            needed = []
        out = {"format": "elf", "architecture": _arch_of(d) or "none", "needed": needed}
        gfso = next((n for n in needed if n.startswith("libgfortran.so")), None)
        out["has_libgfortran_needed"] = tf(gfso)
        out["libgfortran_soname"] = gfso or "none"
        names = {s[0] for s in syms}
        imps = sorted({n.split("@")[0] for n in names if n.startswith("_gfortran_")})
        out["gfortran_imports"] = imps
        dfn = [s for s in syms if s[3] != 0]
        out["has_main_program"] = tf(any(s[0] == "MAIN__" and s[1] == 2 for s in dfn))
        rt = bool(gfso or imps or out["has_main_program"] == "true" or any("_MOD_" in s[0] for s in dfn))
        if not syms and not rt:
            rt = b"libgfortran.so" in d and b"_gfortran_" in d
        out["has_gfortran_runtime"] = out["has_fortran_runtime"] = tf(rt)
        sec_type = {k: s[1] for k, s in enumerate(secs)}
        mods, mp, mpm, mv, mvm, cb, cbm, ext, extm, sav, bd = ({}, set(), set(), set(), set(), set(), set(), set(),
                                                               set(), set(), set())
        dstr = b""
        if rt:
            for s in secs:
                if s[0] == ".debug_str" and s[1] != 8:
                    dstr = d[s[3]:s[3] + s[4]]
            cand = []
            for n, ty, bind, shndx, val, sz in dfn:
                if n.startswith("__") and "_MOD_" in n:
                    mod, _, nm_ = n[2:].partition("_MOD_")
                    if not mod or not nm_ or nm_.startswith("_"):   # __vtab_ / __def_init_ / __copy_ internals
                        continue
                    mods[mod] = mods.get(mod, 0) + 1
                    if ty == 2:
                        mp.add(f"{mod}::{nm_}")
                        mpm.add(n)
                    elif ty == 1:
                        mv.add(f"{mod}::{nm_}")
                        mvm.add(n)
                elif n == "__BLNK__" and ty == 1:
                    cb.add("blank")
                    cbm.add(n)
                elif _GF_EXT.match(n) and bind in (1, 2):
                    if ty == 2:
                        ext.add(n[:-1])
                        extm.add(n)
                    elif ty == 1:
                        cand.append((n, shndx, sz))
                elif ty == 1 and bind == 0 and re.match(r"^[a-z][a-z0-9_]*\.\d+$", n) and \
                        not n.startswith(("options.", "completed.")):
                    sav.add(n.split(".")[0])
            # BLOCK DATA unit marker vs COMMON block: DWARF linkage names list the commons; else an 8-byte .bss
            # object beside an initialised (PROGBITS) common is the BLOCK DATA marker
            indw = [c for c in cand if b"\0" + c[0].encode() + b"\0" in dstr]
            init = any(sec_type.get(c[1]) == 1 for c in cand)
            for c in cand:
                is_bd = (c not in indw) if indw else (init and sec_type.get(c[1]) == 8 and c[2] == (8 if d[4] == 2 else 4))
                if is_bd:
                    bd.add(c[0][:-1])
                else:
                    cb.add(c[0][:-1])
                    cbm.add(c[0])
        out["fortran_modules"] = sorted(mods)
        out["module_procedures"], out["module_procedures_mangled"] = sorted(mp), sorted(mpm)
        out["module_variables"], out["module_variables_mangled"] = sorted(mv), sorted(mvm)
        out["common_blocks"], out["common_blocks_mangled"] = sorted(cb), sorted(cbm)
        out["block_data"] = sorted(bd)
        out["external_procedures"], out["external_procedures_mangled"] = sorted(ext), sorted(extm)
        out["save_variables"] = sorted(sav)
        # DWARF
        lay = [(s[0], s[3], s[4]) for s in secs if s[1] != 8]
        cus = _dwarf_top_dies(d, lay, e) if lay else []
        langs = [c[1] for c in cus if c[1] is not None]
        fcu = [c for c in cus if c[1] in _DW_FORTRAN]
        pfull = next((c[0] for c in fcu if c[0]), None) or next((c[0] for c in cus if c[0]), None)
        if not pfull and rt and dstr:
            m = re.search(rb"GNU Fortran[0-9]* [0-9][^\0]{0,400}", dstr)
            pfull = m.group(0).decode("latin-1") if m else None
        out["dwarf_producer_full"] = pfull or "none"
        pm = re.match(r"(.*?\d+(?:\.\d+)+)", pfull or "")
        out["dwarf_producer"] = pm.group(1) if pm else (pfull or "none")
        vm = re.search(r"(\d+(?:\.\d+)+)", pfull or "")
        out["dwarf_producer_version"] = vm.group(1) if vm else "none"
        lc = fcu[0][1] if fcu else (max(set(langs), key=langs.count) if langs else None)
        out["dwarf_language_code"] = lc if lc is not None else "none"
        out["dwarf_language"] = f"DW_LANG_{_DW_LANG_F.get(lc, hex(lc))}" if lc is not None else "none"
        out["dwarf_languages"] = sorted({f"DW_LANG_{_DW_LANG_F.get(x, hex(x))}" for x in langs})
        out["main_source"] = next((c[2] for c in fcu if c[2]), "none")
        out["program_name"] = _gf_program(d) if fcu else "none"
        out["imports"] = imps
        try:
            out.update(_gf_flow(d, secs, syms))
        except Exception:   # noqa: BLE001 -- flow facts are best effort; identity facts above still stand
            pass
        # HCFG holder
        hs = {"hcfg_symbol": "none", "hcfg_entity": "none", "hcfg_entity_kind": "none", "hcfg_section": "none"}
        if hcfg:
            hit = hcfg_find(d)
            off = getattr(hit, "offset", None) if hit is not None else None
            if isinstance(off, int) and d[off:off + 4] == HCFG_MAGIC:
                k = next((k for k, s in enumerate(secs) if s[1] != 8 and s[2] and s[3] <= off < s[3] + s[4]), None)
                if k is not None:
                    hs["hcfg_section"] = secs[k][0] or "none"
                    va = secs[k][2] + off - secs[k][3]
                    best = [s for s in dfn if s[1] in (0, 1) and s[3] == k and s[4] <= va < s[4] + max(s[5], 1)
                            and s[0] and not s[0].startswith(".")]
                    if best:
                        n = min(best, key=lambda s: (s[1] != 1, va - s[4]))[0]
                        hs["hcfg_symbol"], hs["hcfg_entity"] = n, _gf_name(n)
                        hs["hcfg_entity_kind"] = "module_variable" if "_MOD_" in n else (
                            "common_block" if n in cbm else ("save_variable" if re.search(r"\.\d+$", n)
                                                             else "symbol"))
        out.update(hs)
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def _gf_program(d):
    """Fortran main program name (DW_TAG_subprogram with DW_AT_main_subprogram) via pyelftools; "none" when absent
    or .debug_info is larger than 4 MB (bounded)."""
    try:
        from elftools.elf.elffile import ELFFile
        ef = ELFFile(io.BytesIO(d))
        s = ef.get_section_by_name(".debug_info")
        if s is None or s["sh_size"] > (4 << 20) or not ef.has_dwarf_info():
            return "none"
        for cu in ef.get_dwarf_info().iter_CUs():
            top = cu.get_top_DIE()
            lang = top.attributes.get("DW_AT_language")
            if lang is None or lang.value not in _DW_FORTRAN:
                continue
            for die in top.iter_children():
                if die.tag == "DW_TAG_subprogram" and "DW_AT_main_subprogram" in die.attributes:
                    nm = die.attributes.get("DW_AT_name")
                    if nm is not None:
                        v = nm.value
                        return v.decode("latin-1") if isinstance(v, bytes) else str(v)
        return "none"
    except Exception:  # noqa: BLE001
        return "none"


# D18 "Flow State" shape: internal procedures `name.N` (local FUNCs, CONTAINS order), STT_FILE `<src>.f90`, a SELECT CASE
# on a string compiled to `_gfortran_select_string(table, n, str, len)` over a select_struct array {low, low_len, high,
# high_len, case_no} (entry 0 = CASE DEFAULT: NULL/0), the selector read by `_gfortran_get_environment_variable_i4(name,
# value, length, status, trim, name_len)`.
_GF_SRC = re.compile(r"\.(?:f|for|ftn|fpp|f77|f90|f95|f03|f08|f18|f23)$", re.I)
_GF_PROC = re.compile(r"^[A-Za-z][A-Za-z0-9_$]*\.\d+$")
_GF_IDENT = re.compile(rb"[A-Za-z_][A-Za-z0-9_]{0,127}")


def _gf_flow(d, secs, syms):
    """Flow facts of a gfortran ELF (see gfortran_facts); every key present ("none" / [] / {} when absent)."""
    e, b64 = ("<" if d[5] == 1 else ">"), d[4] == 2
    P = 8 if b64 else 4
    out = {"source_file": "none", "source_files": [], "main_program": "none", "procedures": [],
           "procedures_mangled": [], "procedures_by_address": [], "procedures_by_address_mangled": [],
           "procedure_addresses": {}, "procedure_return_values": {}, "case_table": [], "case_values": [],
           "case_map": {}, "case_count": 0, "has_case_default": "false", "case_table_symbol": "none",
           "case_procedures": {}, "default_procedure": "none", "env_var": "none", "env_vars": [],
           "dynamic_imports": [], "compiler_banner": "none"}
    files = [s[0] for s in syms if s[1] == 4 and _GF_SRC.search(s[0])]
    out["source_files"] = list(dict.fromkeys(files))
    out["source_file"] = files[0] if files else "none"
    dfn = [s for s in syms if s[3] != 0]
    main = next((s for s in dfn if s[0] == "MAIN__" and s[1] == 2), None)
    out["main_program"] = "MAIN__" if main else "none"
    procs = [s for s in dfn if s[1] == 2 and s[2] == 0 and _GF_PROC.match(s[0])]
    procs = list({s[0]: s for s in procs}.values())
    strip_n = lambda n: re.sub(r"\.\d+$", "", n)   # noqa: E731
    out["procedures_mangled"] = [s[0] for s in procs]
    out["procedures"] = [strip_n(s[0]) for s in procs]
    byaddr = sorted(procs, key=lambda s: s[4])
    out["procedures_by_address_mangled"] = [s[0] for s in byaddr]
    out["procedures_by_address"] = [strip_n(s[0]) for s in byaddr]
    out["procedure_addresses"] = {strip_n(s[0]): hex(s[4]) for s in procs}
    load = [(s[2], s[3], s[4]) for s in secs if s[1] != 8 and s[2] and s[4]]

    def at(va, n):
        for a, o, sz in load:
            if a <= va and va + n <= a + sz:
                return d[o + va - a:o + va - a + n]
        return None
    for s in procs:   # `mov eax, imm32; ret` bodies (x86) -> the constant the procedure returns
        b = at(s[4], 6)
        if b and b[0] == 0xB8 and b[5] == 0xC3:
            out["procedure_return_values"][strip_n(s[0])] = struct.unpack_from("<i", b, 1)[0]
    cm = next((s for s in secs if s[0] == ".comment" and s[1] == 1), None)
    if cm:
        bn = [x.decode("latin-1") for x in d[cm[3]:cm[3] + min(cm[4], 4096)].split(b"\0") if x.strip()]
        out["compiler_banner"] = next((x for x in bn if x.startswith("GCC:")), bn[0] if bn else "none")
    # dynamic imports + PLT stub -> name (x86-64 `jmp [rip+disp]` stubs in .plt / .plt.sec)
    dsym = next((s for s in secs if s[0] == ".dynsym" and s[1] == 11), None)
    dstr = next((s for s in secs if s[0] == ".dynstr" and s[1] == 3), None)
    dnames = []
    if dsym and dstr:
        ent = 24 if b64 else 16
        for k in range(min(dsym[4] // ent, 20000)):
            o = dsym[3] + k * ent
            if b64:
                n, info, shndx = struct.unpack_from(e + "IBxH", d, o)
            else:
                n, info, shndx = struct.unpack_from(e + "I4x4xBxH", d, o)
            z = d.find(b"\0", dstr[3] + n, dstr[3] + dstr[4]) if n < dstr[4] else -1
            nm_ = d[dstr[3] + n:z].decode("latin-1") if z >= 0 else ""
            dnames.append(nm_)
            if nm_ and shndx == 0 and k:
                out["dynamic_imports"].append(nm_.split("@")[0])
        out["dynamic_imports"] = sorted(set(out["dynamic_imports"]))
    if not (b64 and d[5] == 1 and struct.unpack_from("<H", d, 18)[0] == 62 and dnames):
        return out
    got = {}
    for s in secs:
        if s[1] == 4 and s[0].startswith(".rela") and s[4] < (1 << 20):
            for k in range(s[4] // 24):
                r_off, r_info = struct.unpack_from("<QQ", d, s[3] + 24 * k)
                if 0 < r_info >> 32 < len(dnames):
                    got[r_off] = dnames[r_info >> 32].split("@")[0]
    stubs = {}
    for s in secs:
        if s[0] in (".plt", ".plt.sec", ".plt.got") and s[1] == 1 and s[4] < (1 << 20):
            blk = d[s[3]:s[3] + s[4]]
            for m in re.finditer(rb"\xff\x25", blk):
                if m.start() + 6 <= len(blk):
                    slot = s[2] + m.start() + 6 + struct.unpack_from("<i", blk, m.start() + 2)[0]
                    if slot in got:
                        st = m.start() - (1 if m.start() and blk[m.start() - 1] == 0xF2 else 0)
                        st -= 4 if st >= 4 and blk[st - 4:st] == b"\xf3\x0f\x1e\xfa" else 0
                        stubs.setdefault(got[slot], s[2] + st)
    want = {stubs[n]: n for n in ("_gfortran_select_string", "_gfortran_get_environment_variable_i4") if n in stubs}
    text = next((s for s in secs if s[0] == ".text" and s[1] == 1), None)
    if not want or not text:
        return out
    lo, hi = (main[4], main[4] + main[5]) if main and main[5] else (text[2], text[2] + min(text[4], 8 << 20))
    code = d[text[3] + lo - text[2]:text[3] + hi - text[2]]

    def arg(k, pats):   # last `mov reg, imm32` / `lea reg, [rip+d]` within 96 bytes before the call at code[k]
        best = None
        for p, kind in pats:
            j = code.rfind(p, max(0, k - 96), k)
            if j >= 0 and j + len(p) + 4 <= k and (best is None or j > best[0]):
                v = struct.unpack_from("<i" if kind == "rip" else "<I", code, j + len(p))[0]
                best = (j, lo + j + len(p) + 4 + v if kind == "rip" else v)
        return best[1] if best else None
    EDI = ((b"\xbf", "imm"), (b"\x48\xc7\xc7", "imm"), (b"\x48\x8d\x3d", "rip"))
    sel_after, tbl, cnt = None, None, None
    for m in re.finditer(rb"\xe8", code):
        k = m.start()
        if k + 5 > len(code):
            break
        tgt = lo + k + 5 + struct.unpack_from("<i", code, k + 1)[0]
        name = want.get(tgt)
        if name == "_gfortran_get_environment_variable_i4":
            va, ln = arg(k, EDI), arg(k, ((b"\x41\xb9", "imm"), (b"\x49\xc7\xc1", "imm")))
            raw = at(va, 128) if va else None
            mm = _GF_IDENT.match(raw or b"")
            if mm:
                ev = mm.group(0)[:ln] if ln and 0 < ln <= len(mm.group(0)) else mm.group(0)
                out["env_vars"].append(ev.decode())
        elif name == "_gfortran_select_string" and tbl is None:
            tbl, cnt, sel_after = arg(k, EDI), arg(k, ((b"\xbe", "imm"), (b"\x48\xc7\xc6", "imm"))), lo + k + 5
    out["env_vars"] = list(dict.fromkeys(out["env_vars"]))
    out["env_var"] = out["env_vars"][0] if out["env_vars"] else "none"
    if tbl is None:
        js = next((s for s in dfn if s[1] == 1 and s[0].startswith("jumptable.")), None)
        tbl, cnt = (js[4], js[5] // 40) if js else (None, None)
    if tbl is None or not cnt or cnt > 4096:
        return out
    ts = next((s for s in dfn if s[1] == 1 and s[4] == tbl), None)
    out["case_table_symbol"] = ts[0] if ts else "none"
    table = []
    for k in range(cnt):
        ent = at(tbl + 40 * k, 36)
        if ent is None:
            return out
        lp, ll, hp, hl, no = struct.unpack("<QQQQi", ent)
        if (lp and not 0 < ll <= 4096) or (hp and not 0 < hl <= 4096):
            return out
        low = at(lp, ll) if lp else b""
        high = at(hp, hl) if hp else b""
        if low is None or high is None:
            return out
        low, high = low.decode("latin-1"), high.decode("latin-1")
        if not lp and not hp:
            out["has_case_default"] = "true"
            table.append(["default", no])
            continue
        table.append([low if (lp and hp and low == high) else f"{low}:{high}", no])
    out["case_table"] = table
    out["case_count"] = sum(1 for t in table if t[0] != "default")
    out["case_values"] = [t[0] for t in table if t[0] != "default"]
    out["case_map"] = {t[0]: t[1] for t in table if t[0] != "default"}
    # case number -> internal procedure the branch reaches (unicorn from the instruction after the select call)
    if sel_after and procs:
        reach = _gf_case_reach(d, sel_after, {s[4]: strip_n(s[0]) for s in procs},
                               sorted({t[1] for t in table}), set(stubs.values()))
        out["case_procedures"] = {t[0]: reach[t[1]] for t in table if t[0] != "default" and t[1] in reach}
        dno = next((t[1] for t in table if t[0] == "default"), 0)
        out["default_procedure"] = reach.get(dno, "none")
    return out


def _gf_case_reach(d, start, procs, cases, stubs, max_insns=4000):
    """{case_no: procedure name} reached first when MAIN__ resumes at `start` with eax = case_no (x86-64 PT_LOADs)."""
    try:
        from unicorn import Uc, UC_ARCH_X86, UC_MODE_64, UC_HOOK_CODE
        from unicorn.x86_const import UC_X86_REG_RAX, UC_X86_REG_RSP, UC_X86_REG_RBP
    except ImportError:
        return {}
    phoff, phes, phn = struct.unpack_from("<Q", d, 32)[0], *struct.unpack_from("<HH", d, 54)
    segs = []
    for k in range(min(phn, 64)):
        pt, _, off, va, _, fsz, msz = struct.unpack_from("<IIQQQQQ", d, phoff + k * phes)
        if pt == 1 and msz and msz < (64 << 20):
            segs.append((va, off, fsz, msz))
    if not segs:
        return {}
    res = {}
    for c in cases:
        try:
            mu = Uc(UC_ARCH_X86, UC_MODE_64)
            for a, b_ in sorted({(va & ~0xFFF, (va + msz + 0xFFF) & ~0xFFF) for va, _, _, msz in segs}):
                try:
                    mu.mem_map(a, b_ - a)
                except Exception:   # noqa: BLE001 -- overlapping pages already mapped
                    pass
            for va, off, fsz, _ in segs:
                mu.mem_write(va, d[off:off + fsz])
            mu.mem_map(0x7ff00000, 0x100000)
            mu.reg_write(UC_X86_REG_RSP, 0x7ff80000)
            mu.reg_write(UC_X86_REG_RBP, 0x7ff80000)
            mu.reg_write(UC_X86_REG_RAX, c & 0xFFFFFFFF)
            hit = []

            def hook(u, addr, size, _ud, hit=hit):
                if addr in procs or addr in stubs:
                    hit.append(procs.get(addr))
                    u.emu_stop()
            mu.hook_add(UC_HOOK_CODE, hook)
            mu.emu_start(start, 0, timeout=100_000, count=max_insns)
            if hit and hit[0]:
                res[c] = hit[0]
        except Exception:   # noqa: BLE001 -- unmapped access / bad code: case unknown
            continue
    return res


def gfortran_field(data, name):
    """One gfortran_facts value; "none" when the input is no ELF or the field is unknown (never raises)."""
    try:
        return (gfortran_facts(data, hcfg=name.startswith("hcfg_")) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- cobol_facts: GnuCOBOL (cobc) identity facts (next-day candidate) -------------------------------------------------
# cobc emits one C module per PROGRAM-ID: cob_module.module_name -> "<PROGRAM-ID>\0" followed by the
# module_formatted_date "Mmm dd yyyy hh:mm:ss\0" in .rodata (kept by strip), local symbols PID / PID_ /
# PID_module_init, imports cob_init / cob_module_global_enter / cob_check_version ..., DT_NEEDED libcob.so.N.
_COB_MOD = re.compile(rb"\0([A-Za-z0-9][A-Za-z0-9_-]{0,62})\0([A-Z][a-z]{2} [ 0-3]\d \d{4} \d\d:\d\d:\d\d)\0")
_COB_SRC = re.compile(rb"\0([^\0/\\]{1,120}\.(?:cob|cbl|cobol|ccp|cpy|pco))\0", re.I)


def cobol_facts(data):
    """GnuCOBOL facts of an ELF image (bytes only): format, architecture, needed, has_libcob_needed, libcob_soname,
    cob_imports (sorted `cob_*` dynamic symbols), has_cobol_runtime (+ alias has_gnucobol_runtime; libcob NEEDED or
    cob_init / cob_module_* imports; raw-byte cues only when the image has no symbol table), program_id (first module
    name of the .rodata module-name/compile-date pair, else the `<PID>_module_init` symbol), program_ids (all, file
    order; + the cob_set_programid(module, "PID") argument of OpenCOBOL 1.1 images), compile_date ("Oct 18 2026
    12:23:53"), source_file (cob_check_version arg 1, else the cobc input name string), cobol_runtime_version (+ alias
    libcob_version; cob_check_version arg 2: "3.2", "1.5.2"), imports (every cob_* .dynsym name incl. copy-reloc'd
    data cob_initialized / cob_current_module, sorted). HCFG: hcfg_scan (split-raw /
    stack-built cover WORKING-STORAGE VALUE fields). Absent -> "none" / "false" / []; not an ELF -> None."""
    try:
        d = bytes(data)
        if not (d[:4] == b"\x7fELF" and len(d) >= 64 and d[4] in (1, 2) and d[5] in (1, 2)):
            return None
        tf = lambda b: "true" if b else "false"   # noqa: E731
        try:
            secs, syms = _gf_elf(d)
        except _PARSE_ERR:
            secs, syms = [], []
        try:
            needed = list(_elf_pair_facts(d).get("needed") or [])
        except Exception:   # noqa: BLE001
            needed = []
        out = {"format": "elf", "architecture": _arch_of(d) or "none", "needed": needed}
        so = next((n for n in needed if n.startswith("libcob.so")), None)
        out["has_libcob_needed"], out["libcob_soname"] = tf(so), so or "none"
        imps = sorted({s[0].split("@")[0] for s in syms if s[3] == 0 and s[0].startswith("cob_")})
        out["cob_imports"] = imps
        rt = bool(so or any(n in ("cob_init", "cob_module_enter", "cob_module_global_enter", "cob_check_version")
                            for n in imps))
        if not syms and not rt:
            rt = b"libcob.so" in d and b"cob_init\0" in d
        out["has_cobol_runtime"] = out["has_gnucobol_runtime"] = tf(rt)
        pids, date, src = [], "none", "none"
        if rt:
            ro = [(s[3], s[4]) for s in secs if s[0] == ".rodata" and s[1] == 1] or [(0, min(len(d), 64 << 20))]
            for off, sz in ro:
                blk = d[max(0, off - 1):off + sz]
                for m in _COB_MOD.finditer(blk):
                    if m.group(1).decode() not in pids:
                        pids.append(m.group(1).decode())
                    date = m.group(2).decode() if date == "none" else date
                ms = _COB_SRC.search(blk)
                if ms and src == "none":
                    src = ms.group(1).decode("latin-1")
            if not pids:
                pids = [s[0][:-12] for s in syms if s[0].endswith("_module_init") and s[3] != 0 and len(s[0]) > 12]
        try:
            dimps, args = _cob_dyn_args(d, secs) if rt else ([], {})
        except Exception:   # noqa: BLE001  (malformed dynsym / relocs: keep the struct facts)
            dimps, args = [], {}
        out["imports"] = dimps if rt else []   # every cob_* dynsym name, incl. copy-reloc'd data (cob_initialized ..)
        cv = next((a for a in args.get("cob_check_version", []) if a[1]), None)   # (source, version, patchlevel)
        out["cobol_runtime_version"] = out["libcob_version"] = cv[1] if cv else "none"
        src = cv[0] if cv and cv[0] else src
        sp = [a[1] for a in args.get("cob_set_programid", []) if a[1]]   # OpenCOBOL 1.1: cob_set_programid(mod, "PID")
        for v in sp:
            if v not in pids:
                pids.append(v)
        out["program_id"] = pids[0] if pids else "none"
        out["program_ids"] = pids
        out["compile_date"], out["source_file"] = date, src
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


_COB_ARGS = ("cob_check_version", "cob_set_programid")


def _cob_dyn_args(d, secs):
    """(sorted cob_* .dynsym names, {import: [(rdi, rsi, rdx) C strings at each call site]}) of an x86-64 ELF64 LE
    image: call/jmp rel32 -> PLT stub / call/jmp [rip+GOT] (-fno-plt) to cob_check_version / cob_set_programid; the argument
    registers are tracked over the <= 96 bytes before the call (capstone, synced to land on the call): mov r32, imm32
    (non-PIE), lea r64, [rip+d] (PIE), mov r64, r64 copies (-O0 `lea rax; mov rdi, rax`). Strings must be printable."""
    dsym = next((s for s in secs if s[0] == ".dynsym" and s[1] == 11), None)
    dstr = next((s for s in secs if s[0] == ".dynstr" and s[1] == 3), None)
    if not dsym or not dstr or d[4] != 2 or d[5] != 1:
        return [], {}
    dn = []
    for k in range(min(dsym[4] // 24, 20000)):
        n = struct.unpack_from("<I", d, dsym[3] + 24 * k)[0]
        z = d.find(b"\0", dstr[3] + n, dstr[3] + dstr[4]) if n < dstr[4] else -1
        dn.append(d[dstr[3] + n:z].decode("latin-1").split("@")[0] if z >= 0 else "")
    imps = sorted({n for n in dn if n.startswith("cob_")})
    args = {}
    if struct.unpack_from("<H", d, 18)[0] != 62 or not any(n in dn for n in _COB_ARGS):
        return imps, args
    got = {}
    for s in secs:
        if s[1] == 4 and s[0].startswith(".rela") and s[4] < (1 << 20):
            for k in range(s[4] // 24):
                r_off, r_info = struct.unpack_from("<QQ", d, s[3] + 24 * k)
                if 0 < r_info >> 32 < len(dn) and dn[r_info >> 32] in _COB_ARGS:
                    got[r_off] = dn[r_info >> 32]
    stubs = {}
    for s in secs:
        if s[0] in (".plt", ".plt.sec", ".plt.got") and s[1] == 1 and s[4] < (1 << 20):
            blk = d[s[3]:s[3] + s[4]]
            for m in re.finditer(rb"\xff\x25", blk):
                if m.start() + 6 <= len(blk):
                    slot = s[2] + m.start() + 6 + struct.unpack_from("<i", blk, m.start() + 2)[0]
                    if slot in got:
                        st = m.start() - (1 if m.start() and blk[m.start() - 1] == 0xF2 else 0)
                        st -= 4 if st >= 4 and blk[st - 4:st] == b"\xf3\x0f\x1e\xfa" else 0
                        stubs[s[2] + st] = got[slot]
    text = next((s for s in secs if s[0] == ".text" and s[1] == 1), None)
    if not (stubs or got) or not text:
        return imps, args
    load = [(s[2], s[3], s[4]) for s in secs if s[1] != 8 and s[2] and s[4]]

    def cstr(va):
        for a, o, sz in load if va else ():
            if a <= va < a + sz:
                z = d.find(b"\0", o + va - a, o + sz)
                v = d[o + va - a:z] if 0 <= z - (o + va - a) <= 256 else b""
                return v.decode("latin-1") if v and all(32 <= c < 127 for c in v) else None
        return None
    try:
        import capstone
        md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64)
    except Exception:  # noqa: BLE001
        return imps, args
    fam = lambda r: re.sub(r"[dwb]$", "", r) if r[1:2].isdigit() else r[-2:]   # noqa: E731  esi/rsi -> si, r8d -> r8
    to, ta = text[3], text[2]
    code = d[to:to + min(text[4], 8 << 20)]
    for m in re.finditer(rb"[\xe8\xe9]|\xff[\x15\x25]", code):   # call / tail-call jmp (gcc -O2)
        k = m.start()
        if k + 5 + (len(m.group()) == 2) > len(code):
            continue
        if len(m.group()) == 1:
            name, end = stubs.get(ta + k + 5 + struct.unpack_from("<i", code, k + 1)[0]), k + 5
        else:
            name, end = got.get(ta + k + 6 + struct.unpack_from("<i", code, k + 2)[0]), k + 6
        if not name or len(args.get(name, ())) >= 8:
            continue
        ins = None
        for st in range(max(0, k - 96), k):   # first start whose linear decode lands exactly on the call
            ii = list(md.disasm(code[st:k], ta + st))
            if ii and ii[-1].address + ii[-1].size == ta + k:
                ins = ii
                break
        reg = {}
        for i in ins or ():
            ops = [o.strip() for o in i.op_str.split(",", 1)]
            if i.mnemonic.startswith("call") or not ops[0]:
                reg.clear()
                continue
            dst = fam(ops[0]) if re.fullmatch(r"[a-z0-9]+", ops[0]) else None
            if dst is None:
                continue
            src = ops[1] if len(ops) > 1 else ""
            v = None
            mm = re.fullmatch(r"\[rip ([+-]) (0x[0-9a-f]+|\d+)\]", src)
            if i.mnemonic == "lea" and mm:
                v = i.address + i.size + int(mm.group(2), 0) * (1 if mm.group(1) == "+" else -1)
            elif i.mnemonic == "mov" and re.fullmatch(r"0x[0-9a-f]+|\d+", src):
                v = int(src, 0)
            elif i.mnemonic == "mov" and re.fullmatch(r"[a-z0-9]+", src):
                v = reg.get(fam(src))
            elif i.mnemonic == "xor" and src == ops[0]:
                v = 0
            reg[dst] = v
        args.setdefault(name, []).append(tuple(cstr(reg.get(r)) for r in ("di", "si")) + (reg.get("dx"),))
    return imps, args


def cobol_field(data, name):
    """One cobol_facts value; "none" when the input is no ELF or the field is unknown (never raises)."""
    try:
        return (cobol_facts(data) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- ghc_facts: Haskell / GHC identity + z-encoded closure facts (next-day candidate) ---------------------------------
# GHC symbol = [<unit>_]<Module>_<name>_<kind>, every part z-encoded (zi '.', zm '-', zd '$', ZC ':', zu '_', zh '#',
# z<hex>U code point, Z<n>T tuple ...); the `main` unit drops the prefix (Main_main_closure; ZCMain_main_closure is
# the :Main.main wrapper). Kinds: closure, info, con_info, entry, bytes (Addr# / ByteString literal: the HCFG holder),
# srt, ... rts: hs_main, hs_init_ghc, stg_* ; `+RTS --info` pairs ("GHC version", "<ver>"), ("RTS way", "rts_thr").
# Info tables keep con_desc strings "<unit>:<Module>.<Con>" even in strip'd images.
_Z_UP = {"L": "(", "R": ")", "M": "[", "N": "]", "C": ":", "Z": "Z"}
_Z_LO = {"z": "z", "a": "&", "b": "|", "c": "^", "d": "$", "e": "=", "g": ">", "h": "#", "i": ".", "l": "<", "m": "-",
         "n": "!", "p": "+", "q": "'", "r": "\\", "s": "/", "t": "*", "u": "_", "v": "%"}
_Z_TOK = re.compile(r"z([0-9a-f][0-9a-f]*)U|Z(\d+)([TH])|Z([LRMNCZ])|z([zabcdeghilmnpqrstuv])")
_GHC_SYM = re.compile(r"^(?:([a-z][A-Za-z0-9]*)_)?([A-Z][A-Za-z0-9]*)_(\w+?)_(closure|info|con_info|con_entry|"
                      r"static_info|entry|bytes|srt|slow|fast|str)$")
_GHC_MOD = re.compile(r"^[A-Z][\w']*(?:\.[A-Z][\w']*)*$")
_GHC_CONDESC = re.compile(rb":((?:[A-Z][\w']{0,80}\.){1,12})[^\0\s.][^\0\s]{0,63}\0")   # ':' prefix = fast search
_GHC_UNIT = re.compile(rb"(?:^|[^\w.:-])([a-z][A-Za-z0-9._-]{0,80})$")
_GHC_VER = re.compile(r"\d+\.\d+(?:\.\d+){0,2}")


def ghc_zdecode(s):
    """GHC z-decoding (compiler/GHC/Utils/Encoding.hs): 'ghczmprim' -> 'ghc-prim', 'GHCziBase' -> 'GHC.Base',
    'zdwmain' -> '$wmain', 'Z3T' -> '(,,)', 'z2192U' -> U+2192. Unknown escapes are kept verbatim."""
    def rep(m):
        if m.group(1):
            try:
                return chr(int(m.group(1), 16))
            except (ValueError, OverflowError):
                return m.group(0)
        if m.group(2):
            n = int(m.group(2))
            if m.group(3) == "T":
                return "(" + "," * max(n - 1, 0) + ")"
            return "(# #)" if n == 1 else "(#" + "," * (n - 1) + "#)"
        if m.group(4):
            return _Z_UP[m.group(4)]
        return _Z_LO[m.group(5)]
    return _Z_TOK.sub(rep, s)


def _ghc_sym(n):
    """(unit|None, Module, name, kind) of a z-encoded GHC closure symbol, else None."""
    m = _GHC_SYM.match(n)
    if not m:
        return None
    mod = ghc_zdecode(m.group(2))
    if not _GHC_MOD.match(mod):
        return None
    return (ghc_zdecode(m.group(1)) if m.group(1) else None), mod, ghc_zdecode(m.group(3)), m.group(4)


def ghc_facts(data, hcfg=True):
    """Haskell / GHC facts of an ELF image (bytes only): format, architecture, has_ghc_runtime (+ alias
    has_haskell_runtime; rts / z-encoded closure symbols in .symtab/.dynsym, or -- only when the image has no .symtab
    -- 2+ raw rts cues), has_hs_main, ghc_version (DWARF "Glorious Glasgow Haskell Compilation System <v>", the
    rts --info ("GHC version", "<v>") pair, a "GHC <v>" banner, a ghc-<v> libdir), rts_way ("rts_thr"...) +
    has_threaded_rts, haskell_modules (z-decoded, symbols + con_desc strings), user_modules (the `main` unit),
    haskell_packages (z-decoded unit ids, `main` excluded), main_module ("Main" when Main.main / :Main.main exist),
    closure_count, bytes_literals (z-decoded `<Mod>.<name>` of *_bytes literals); hcfg_symbol / hcfg_closure
    ("Config.hcfgBlob1") / hcfg_module / hcfg_unit / hcfg_kind / hcfg_section for the hcfg_find hit (hcfg=False skips
    the scan). Absent -> "none" / "false" / []; not an ELF -> None."""
    try:
        d = bytes(data)
        if not (d[:4] == b"\x7fELF" and len(d) >= 64 and d[4] in (1, 2) and d[5] in (1, 2)):
            return None
        tf = lambda b: "true" if b else "false"   # noqa: E731
        try:
            secs, syms = _gf_elf(d)
        except _PARSE_ERR:
            secs, syms = [], []
        out = {"format": "elf", "architecture": _arch_of(d) or "none"}
        names = {s[0] for s in syms}
        dfn = [s for s in syms if s[3] != 0]
        parsed = {}
        for s in syms:
            if s[0] not in parsed:
                p = _ghc_sym(s[0])
                if p:
                    parsed[s[0]] = p
        rts = names & {"hs_main", "hs_init_ghc", "hs_init", "hs_exit", "rts_evalLazyIO", "stg_ap_0_fast",
                       "stg_upd_frame_info", "ZCMain_main_closure"}
        wired = any(p[0] in ("ghc-prim", "base", "ghc-internal", "ghc-bignum") for p in parsed.values())
        rt = bool(rts or wired)
        if not rt and not any(s[1] == 2 for s in secs):   # strip'd (.dynsym holds libc imports only): raw cues
            cues = (b"GHC RTS\0", b"+RTS", b"ghc-prim:GHC.", b"Glasgow Haskell", b"base:GHC.", b"GHC version\0")
            rt = sum(c in d for c in cues) >= 2
        out["has_ghc_runtime"] = out["has_haskell_runtime"] = tf(rt)
        out["has_hs_main"] = tf(any(s[0] == "hs_main" for s in dfn))
        mods, user, pkgs, lits = set(), set(), set(), set()
        ver = way = None
        vers = {}
        if rt:
            for unit, mod, nm_, kind in parsed.values():
                mods.add(mod)
                if unit is None or unit == "main":
                    user.add(mod)
                else:
                    pkgs.add(unit)
                if kind == "bytes":
                    lits.add(f"{mod}.{nm_}")
            ro = [(s[3], s[4]) for s in secs if s[1] == 1 and s[4] and s[0] not in (".text", ".plt", ".init", ".fini")]
            area = [d[o:o + n] for o, n in ro] if ro else [d]
            budget = 96 << 20
            for blk in area:
                blk = blk[:budget]
                budget -= len(blk)
                for m in _GHC_CONDESC.finditer(blk):
                    u = _GHC_UNIT.search(blk, max(0, m.start() - 82), m.start())
                    if not u:
                        continue
                    unit, mod = u.group(1).decode("latin-1"), m.group(1)[:-1].decode("latin-1")
                    mods.add(mod)
                    if unit == "main":
                        user.add(mod)
                    else:
                        pkgs.add(unit)
                # version sources by trust, across ALL blocks (D20: an rts message "disallowed in GHC 6.10.2 and
                # later" sits before the real "9.12.2\0    (GHC version %s for %s)" banner operand)
                for k, rx in enumerate(_GHC_VER_RX):
                    if k in vers or (k == 3 and 2 in vers):
                        continue
                    m = next((x for x in re.finditer(rx, blk) if k < 2 or k == 2 or not x.start() or
                              (blk[x.start() - 1:x.start()] not in b".-_" and not blk[x.start() - 1:x.start()].isalnum()
                               and not _GHC_VER_LATER.match(blk, x.end()))), None)
                    if m:
                        vers[k] = m.group(1).decode("latin-1").rstrip(".")
                if way is None:
                    m = re.search(rb"RTS way\0{1,64}(rts[A-Za-z0-9_]{0,24})\0", blk)
                    way = m.group(1).decode("latin-1") if m else None
                if budget <= 0:
                    break
        link = _ghc_link_facts(d, secs, syms, parsed, rt)
        ver = min(vers.items())[1] if vers and min(vers) < 3 else None
        ver = ver or link.pop("_ghc_version_link", None) or (vers.get(3) or vers.get(4))
        link.pop("_ghc_version_link", None)
        out["ghc_version"] = ver or "none"
        out["rts_way"] = way or "none"
        out["has_threaded_rts"] = tf(way and "thr" in way)
        out["haskell_modules"] = sorted(mods)
        out["user_modules"] = sorted(user)
        out["haskell_packages"] = sorted(pkgs)
        out["main_module"] = "Main" if rt and names & {"ZCMain_main_closure", "Main_main_closure", "Main_main_info"} \
            else "none"
        out["closure_count"] = sum(1 for p in parsed.values() if p[3] == "closure") if rt else 0
        out["bytes_literals"] = sorted(lits)
        hs = {"hcfg_symbol": "none", "hcfg_closure": "none", "hcfg_module": "none", "hcfg_unit": "none",
              "hcfg_kind": "none", "hcfg_section": "none"}
        if hcfg:
            hit = hcfg_find(d)
            off = getattr(hit, "offset", None) if hit is not None else None
            if isinstance(off, int) and 0 <= off < len(d):
                k = next((k for k, s in enumerate(secs) if s[1] != 8 and s[2] and s[3] <= off < s[3] + s[4]), None)
                if k is not None:
                    hs["hcfg_section"] = secs[k][0] or "none"
                    va = secs[k][2] + off - secs[k][3]
                    cand = [s for s in dfn if s[1] in (0, 1) and s[3] == k and s[0] and not s[0].startswith(".")
                            and (s[4] <= va < s[4] + s[5] or (not s[5] and 0 <= va - s[4] < 4096))]
                    if cand:
                        n = min(cand, key=lambda s: (not s[5], s[0] not in parsed, va - s[4]))[0]
                        hs["hcfg_symbol"] = n
                        p = parsed.get(n)
                        if p:
                            hs["hcfg_closure"], hs["hcfg_module"] = f"{p[1]}.{p[2]}", p[1]
                            hs["hcfg_unit"], hs["hcfg_kind"] = p[0] or "main", p[3]
        out.update(hs)
        out.update(link)
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


_GHC_VER_RX = (rb"Glorious Glasgow Haskell Compilation System,? (?:[Vv]ersion )?(\d+\.\d+[\d.]*)",
               rb"GHC version\0{1,64}(\d+\.\d+(?:\.\d+){0,2})\0",
               rb"\0(\d+\.\d+\.\d+(?:\.\d+)?)\0{1,16}[ \t]*\(GHC version %s for %s\)",   # rts errorBelch banner
               rb"GHC (\d+\.\d+\.\d+(?:\.\d+)?)(?![\w.])", rb"ghc-(\d+\.\d+\.\d+(?:\.\d+)?)(?![\w.])")
_GHC_VER_LATER = re.compile(rb" (?:and|or) (?:later|earlier|newer|above|below)")
_GHC_LINK_HDR = b"(UnitLinkOpts {hsLibs = ["
_GHC_HSLIB = re.compile(r"^-lHS(.+?)-(\d+(?:\.\d+)*)(?:-[0-9a-f]{4,64})?$")


def _ghc_link_facts(d, secs, syms, parsed, rt):
    """GHC link-time facts (D20 group: GHC 9.12.2, gold): the `.debug-ghc-link-info` note GHC writes on every link
    (desc = show (UnitLinkOpts {hsLibs, extraLibs, otherFlags}, frameworks, -with-rtsopts Maybe, RtsOptsEnabled,
    no_hs_main, extra_ld_inputs, ldflags)) -> has_ghc_link_info / has_debug_ghc_link_info, hs_libs (as stored,
    "-lHSbase-4.21.0.0-8bb5"), extra_libs (as stored, duplicates kept), other_flags_count, haskell_package_versions
    {unit: version}, base_version, ghc_internal_version ("9.1202.0"), ghc_prim_version, ghc_bignum_version,
    rts_version, rts_opts / rts_opts_enabled ("RtsOptsSafeOnly"), with_rtsopts ("none" for Nothing), no_hs_main,
    link_ld_flags; ghc_version fallback from ghc-internal (<maj>.<min*100+patch>.0 -> "9.12.2"). Also needed
    (DT_NEEDED order), linker "gold" + gold_version ("gold 1.16") from .note.gnu.gold-version, symbol_count /
    closure_symbol_count / info_symbol_count (.symtab+.dynsym names ending _closure / _info), main_symbols
    (Main_* / ZCMain_* in table order) + main_closures, trace_family / trace_effects (dynamic_trace_facts).
    Absent -> "none" / "false" / [] / 0."""
    tf = lambda b: "true" if b else "false"   # noqa: E731
    out = {"has_ghc_link_info": "false", "hs_libs": [], "extra_libs": [], "other_flags_count": 0,
           "haskell_package_versions": {}, "base_version": "none", "ghc_internal_version": "none",
           "ghc_prim_version": "none", "ghc_bignum_version": "none", "rts_version": "none", "rts_opts": "none",
           "rts_opts_enabled": "none", "with_rtsopts": "none", "no_hs_main": "none", "link_ld_flags": []}
    sec = next((s for s in secs if s[0] == ".debug-ghc-link-info" and s[1] != 8), None)
    blob = d[sec[3]:sec[3] + sec[4]] if sec and sec[3] + sec[4] <= len(d) else b""
    i = blob.find(_GHC_LINK_HDR)
    if i < 0 and not sec:
        j = d.find(b"GHC link info\0")
        if j >= 0:
            blob = d[j:j + (1 << 20)]
            i = blob.find(_GHC_LINK_HDR)
    if i >= 0:
        txt = blob[i:].split(b"\0", 1)[0].decode("latin-1")
        lists, depth, cur, q, esc, rest = {}, 0, None, False, False, None
        sm = re.compile(r'"((?:[^"\\]|\\.)*)"')
        for key in ("hsLibs", "extraLibs", "otherFlags"):
            m = re.search(key + r" = \[((?:\s*\"(?:[^\"\\]|\\.)*\"\s*,?)*)\]", txt)
            lists[key] = sm.findall(m.group(1)) if m else []
        e = txt.find("]}")
        if e >= 0:   # top-level tuple tail after the UnitLinkOpts record, split on depth-0 commas
            parts, cur = [], ""
            for ch in txt[e + 3:]:
                if esc:
                    esc = False
                elif q and ch == "\\":
                    esc = True
                elif ch == '"':
                    q = not q
                elif not q and ch in "[(":
                    depth += 1
                elif not q and ch in "])":
                    if depth == 0:
                        parts.append(cur.strip())
                        break
                    depth -= 1
                if not q and depth == 0 and ch == ",":
                    parts.append(cur.strip())
                    cur = ""
                    continue
                cur += ch
            rest = parts
        hl = lists["hsLibs"]
        vers = {}
        for lib_ in hl:
            m = _GHC_HSLIB.match(lib_)
            if m:
                vers[m.group(1)] = m.group(2)
        out.update({"has_ghc_link_info": "true", "hs_libs": hl, "extra_libs": lists["extraLibs"],
                    "other_flags_count": len(lists["otherFlags"]), "haskell_package_versions": vers,
                    "base_version": vers.get("base", "none"), "ghc_internal_version": vers.get("ghc-internal", "none"),
                    "ghc_prim_version": vers.get("ghc-prim", "none"),
                    "ghc_bignum_version": vers.get("ghc-bignum", "none"), "rts_version": vers.get("rts", "none")})
        if rest and len(rest) >= 6:
            w = rest[1]
            out["with_rtsopts"] = "none" if w == "Nothing" else (sm.findall(w) or [w])[0]
            out["rts_opts"] = out["rts_opts_enabled"] = rest[2] if re.match(r"^RtsOpts\w+$", rest[2]) else "none"
            out["no_hs_main"] = rest[3].lower() if rest[3] in ("True", "False") else "none"
            out["link_ld_flags"] = sm.findall(rest[5])
        gi = re.match(r"^(\d+)\.(\d+?)(\d\d)\.\d+$", out["ghc_internal_version"])
        if gi:
            out["_ghc_version_link"] = f"{gi.group(1)}.{int(gi.group(2))}.{int(gi.group(3))}"
    out["has_debug_ghc_link_info"] = out["has_ghc_link_info"]
    try:
        out["needed"] = (elf_header_facts(d, hcfg=False) or {}).get("needed") or []
    except Exception:  # noqa: BLE001
        out["needed"] = []
    gv = "none"
    g = next((s for s in secs if s[0] == ".note.gnu.gold-version" and s[1] == 7), None)
    if g and g[3] + g[4] <= len(d) and g[4] >= 12:
        nsz, dsz, _ = struct.unpack_from("<III" if d[5] == 1 else ">III", d, g[3])
        o = g[3] + 12 + ((nsz + 3) & ~3)
        v = d[o:o + dsz].split(b"\0", 1)[0].decode("latin-1")
        gv = v if v.startswith("gold") else "none"
    out["has_gold_version_note"] = tf(gv != "none")
    out["gold_version"] = gv
    out["linker"] = "gold" if gv != "none" else "none"
    names = [s[0] for s in syms]
    out["symbol_count"] = len(names)
    out["closure_symbol_count"] = sum(1 for n in names if n.endswith("_closure"))
    out["info_symbol_count"] = sum(1 for n in names if n.endswith("_info"))
    ms = [n for n in names if n.startswith(("Main_", "ZCMain_"))] if rt else []
    out["main_symbols"] = ms
    out["main_closures"] = [n for n in ms if n.endswith("_closure")]
    out["main_symbol_count"] = len(ms)
    out["has_main_main_closure"] = tf("Main_main_closure" in ms)
    tr = {}
    if rt:
        try:
            tr = dynamic_trace_facts(d) or {}
        except Exception:  # noqa: BLE001
            tr = {}
    for k in ("family", "effects", "campaign"):
        v = tr.get("trace_" + k, "none")
        if v == "none" and tr.get("trace_schema", "none") != "none":
            # GHC splits the template: the `,"campaign":..,"family":..}` tail is its own literal near the schema
            i = d.find(DTRACE_SCHEMA)
            m = re.search(rb'"%s"\s*:\s*"([A-Za-z0-9_.:-]{1,80})"' % k.encode(), d[max(0, i - 4096):i + 4096])
            v = m.group(1).decode() if m else "none"
        out["trace_" + k] = v
    return out


def resource_overlay_facts(data, magic="RS20"):
    """Header facts of the D20 RS20 resource overlay (resource_overlay layout: magic +0..3, version u8 +4, pad +5..7,
    HCFG resource length u32le +8, scratch length u16le +12, pad +14..15, sha256(scratch) +16..47, resource +48,
    scratch after it, ending at EOF): overlay_magic, overlay_offset, overlay_size (EOF - offset), image_end /
    has_overlay (overlay_info), overlay_at_image_end, overlay_version / rs20_version, hcfg_resource_size (+ aliases
    hcfg_resource_length, resource_size, res_len), hcfg_resource_offset (48, relative) / hcfg_resource_start (file),
    hcfg_resource_sha256, scratch_size (+ scratch_length, scratch_len), scratch_offset (relative) / scratch_start,
    scratch_sha256 (stored = verified), scratch_text (latin-1), end_bounds_ok. "none" values when no hash-verified
    RS20 overlay; None for non-bytes."""
    import hashlib
    try:
        d = bytes(data)
    except (TypeError, ValueError):
        return None
    try:
        ov = overlay_info(d)
    except Exception:  # noqa: BLE001
        ov = None
    out = {"has_overlay": bool(ov and ov["has_overlay"]),
           "image_end": (ov["overlay_offset"] if ov["has_overlay"] else len(d)) if ov else "none"}
    keys = ("overlay_magic", "overlay_offset", "overlay_size", "overlay_at_image_end", "overlay_version",
            "rs20_version", "hcfg_resource_size", "hcfg_resource_length", "resource_size", "res_len",
            "hcfg_resource_offset", "hcfg_resource_start", "hcfg_resource_sha256", "scratch_size", "scratch_length",
            "scratch_len", "scratch_offset", "scratch_start", "scratch_sha256", "scratch_text", "end_bounds_ok")
    rs = resource_overlay(d, magic)
    if not rs:
        out.update(dict.fromkeys(keys, "none"))
        return out
    o, n, s = rs["offset"], rs["hcfg_resource_size"], rs["scratch_size"]
    out.update({"overlay_magic": magic if isinstance(magic, str) else bytes(magic).decode("latin-1"),
                "overlay_offset": o, "overlay_size": len(d) - o,
                "overlay_at_image_end": bool(ov) and o == out["image_end"], "overlay_version": d[o + 4],
                "rs20_version": d[o + 4], "hcfg_resource_size": n, "hcfg_resource_length": n, "resource_size": n,
                "res_len": n, "hcfg_resource_offset": 48, "hcfg_resource_start": o + 48,
                "hcfg_resource_sha256": hashlib.sha256(rs["hcfg"]).hexdigest(), "scratch_size": s,
                "scratch_length": s, "scratch_len": s, "scratch_offset": 48 + n, "scratch_start": o + 48 + n,
                "scratch_sha256": rs["scratch_sha256"], "scratch_text": rs["scratch"].decode("latin-1"),
                "end_bounds_ok": "true"})
    return out


def resource_overlay_field(data, name, magic="RS20"):
    """One resource_overlay_facts value: "none" when absent / unknown field, None when unanswerable."""
    f = resource_overlay_facts(data, magic)
    return None if f is None else f.get(name, "none")


def ghc_field(data, name):
    """One ghc_facts value; "none" when the input is no ELF or the field is unknown (never raises)."""
    try:
        return (ghc_facts(data, hcfg=name.startswith("hcfg_")) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- ocaml_facts: OCaml native (ocamlopt) identity + module / string-block facts (next-day candidate) -----------------
# Module M links caml<M><sep>{entry,code_begin,code_end,data_begin,data_end,frametable,gc_roots} + caml<M> (the module
# block) + functions caml<M><sep><fn>_<stamp>; sep is "__" up to 5.0, "." from 5.1 ("$" on targets without '.').
# dune executables wrap every module as Dune__exe__<M>; the stdlib is Stdlib / Stdlib__<M> / Camlinternal*.
# Runtime: caml_startup, caml_main, caml_program, caml_start_program; OCAMLRUNPARAM / CAMLRUNPARAM strings.
# Structured string constants are blocks: header word (wosize<<10 | color<<8 | 252 String_tag) then the payload; the
# data label (caml<M><sep><n>) sits AT the payload, whose last byte is the pad count (wosize*W-1-len, zero-filled).
# HCFG offset convention: the payload start (the 'H'), never the header word.
_OCAML_MODSYM = re.compile(r"^caml([A-Z][A-Za-z0-9_']*?)(__|\.|\$)(entry|code_begin|code_end|data_begin|data_end|"
                           r"frametable|gc_roots)$")
_OCAML_RT = {"caml_startup", "caml_main", "caml_program", "caml_start_program", "caml_startup_exn",
             "caml_startup_pooled", "caml_init_gc", "caml_alloc_shr", "caml_raise_exn", "caml_call_gc"}
_OCAML_VER = re.compile(rb"(?:\.opam/|/ocaml/|/ocaml-|ocaml-base-compiler\.|ocaml-variants\.|OCaml version |"
                        rb"The OCaml [a-z]+, version )(\d+\.\d{1,2}\.\d{1,2})(?![\d])")


def ocaml_string_block(d, off, word=8, little=True):
    """(header_offset, wosize, color, tag, pad) when `off` is the payload of a well-formed OCaml String_tag block
    (header word right before it, tag 252, last payload byte = pad count < word with zero padding before it), else None."""
    try:
        if off < word or off > len(d):
            return None
        hdr = int.from_bytes(d[off - word:off], "little" if little else "big")
        wo, tag = hdr >> 10, hdr & 0xFF
        if tag != 252 or not 0 < wo <= (len(d) - off) // word:
            return None
        end = off + wo * word
        pad = d[end - 1]
        if pad >= word or any(d[end - 1 - pad:end - 1]):
            return None
        return off - word, wo, (hdr >> 8) & 3, tag, pad
    except _PARSE_ERR:
        return None


def ocaml_facts(data, hcfg=True):
    """OCaml native (ocamlopt) facts of an ELF image (bytes only): format, architecture, has_ocaml_runtime (runtime /
    caml<M><sep>entry-family symbols in .symtab/.dynsym, or -- only without .symtab -- 2+ raw runtime cues),
    has_caml_main, ocaml_version (opam switch / libdir path), symbol_separator ("__" / "." / "$"), ocaml_modules (raw
    linked module names: Dune__exe__Main, Stdlib__Printf, ...), user_modules (no Stdlib / Camlinternal / Std_exit,
    Dune__exe__ prefix dropped), stdlib_modules, entry_symbols (caml<M><sep>entry), has_dune_exe, main_module ("Main"
    when linked, else the only user module), function_count; hcfg_symbol / hcfg_module / hcfg_section for the hcfg_find
    hit and its String_tag block (hcfg_in_ocaml_block, hcfg_block_header_offset = offset - word, hcfg_block_wosize,
    hcfg_block_tag, hcfg_block_pad; hcfg=False skips the scan). Absent -> "none" / "false" / [] / 0; not ELF -> None."""
    try:
        d = bytes(data)
        if not (d[:4] == b"\x7fELF" and len(d) >= 64 and d[4] in (1, 2) and d[5] in (1, 2)):
            return None
        tf = lambda b: "true" if b else "false"   # noqa: E731
        try:
            secs, syms = _gf_elf(d)
        except _PARSE_ERR:
            secs, syms = [], []
        out = {"format": "elf", "architecture": _arch_of(d) or "none"}
        dfn = [s for s in syms if s[3] != 0]
        names = {s[0] for s in dfn}
        mods, seps, entries = set(), [], set()
        for n in names:
            m = _OCAML_MODSYM.match(n) if n.startswith("caml") else None
            if m:
                mods.add(m.group(1))
                seps.append(m.group(2))
                if m.group(3) == "entry":
                    entries.add(n)
        rt = bool(names & _OCAML_RT) or len(mods) >= 2
        if not rt and not any(s[1] == 2 for s in secs):   # strip'd: raw runtime cues
            cues = (b"OCAMLRUNPARAM\0", b"CAMLRUNPARAM\0", b"Fatal error: exception ", b"caml_startup",
                    b"Stdlib.Exit", b"Out of memory\0")
            rt = sum(c in d for c in cues) >= 2
        if not rt:
            mods, seps, entries = set(), [], set()
        out["has_ocaml_runtime"] = tf(rt)
        out["has_caml_main"] = tf(rt and "caml_main" in names)
        ver = None
        if rt:
            ro = [(s[3], s[4]) for s in secs if s[1] == 1 and s[4] and s[0] not in (".text", ".plt", ".init", ".fini")]
            budget = 96 << 20
            for o, n in (ro or [(0, len(d))]):
                m = _OCAML_VER.search(d, o, o + min(n, max(budget, 0)))
                budget -= n
                if m:
                    ver = m.group(1).decode("latin-1")
                    break
        out["ocaml_version"] = ver or "none"
        out["symbol_separator"] = max(set(seps), key=seps.count) if seps else "none"
        std = {m for m in mods if m == "Stdlib" or m.startswith(("Stdlib__", "Camlinternal", "Std_exit"))}
        user = {m[11:] if m.startswith("Dune__exe__") else m for m in mods - std}
        out["ocaml_modules"] = sorted(mods)
        out["user_modules"] = sorted(user)
        out["stdlib_modules"] = sorted(std)
        out["entry_symbols"] = sorted(entries)
        out["has_dune_exe"] = tf(any(m.startswith("Dune__exe__") for m in mods))
        out["main_module"] = "Main" if "Main" in user else (next(iter(user)) if len(user) == 1 else "none")
        fn = 0
        if mods:
            pre = {"caml" + m + s for m in mods for s in set(seps)}
            fn = sum(1 for s in dfn if s[1] == 2 and s[0][:4] == "caml" and _OCAML_MODSYM.match(s[0]) is None
                     and re.search(r"_\d+$", s[0]) and any(s[0].startswith(p) for p in pre))
        out["function_count"] = fn
        hs = {"hcfg_symbol": "none", "hcfg_module": "none", "hcfg_section": "none", "hcfg_in_ocaml_block": "false",
              "hcfg_block_header_offset": "none", "hcfg_block_wosize": "none", "hcfg_block_tag": "none",
              "hcfg_block_pad": "none"}
        if hcfg:
            hit = hcfg_find(d)
            off = getattr(hit, "offset", None) if hit is not None else None
            if isinstance(off, int) and 0 <= off < len(d):
                blk = ocaml_string_block(d, off, 8 if d[4] == 2 else 4, d[5] == 1) if rt else None
                if blk:
                    hs["hcfg_in_ocaml_block"] = "true"
                    hs["hcfg_block_header_offset"], hs["hcfg_block_wosize"] = blk[0], blk[1]
                    hs["hcfg_block_tag"], hs["hcfg_block_pad"] = blk[3], blk[4]
                k = next((k for k, s in enumerate(secs) if s[1] != 8 and s[2] and s[3] <= off < s[3] + s[4]), None)
                if k is not None:
                    hs["hcfg_section"] = secs[k][0] or "none"
                    va = secs[k][2] + off - secs[k][3]
                    cand = [s for s in dfn if s[1] in (0, 1) and s[0] and not s[0].startswith(".")
                            and (s[3] == k or s[3] == 0xFFF1) and (s[4] == va or s[4] < va < s[4] + s[5])]
                    if cand:
                        n = min(cand, key=lambda s: (s[4] != va, not s[0].startswith("caml"), va - s[4]))[0]
                        hs["hcfg_symbol"] = n
                        ms = [m for m in mods if any(n.startswith("caml" + m + sp) for sp in ("__", ".", "$"))]
                        if ms:
                            hs["hcfg_module"] = max(ms, key=len)
        out.update(hs)
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def ocaml_field(data, name):
    """One ocaml_facts value; "none" when the input is no ELF or the field is unknown (never raises)."""
    try:
        return (ocaml_facts(data, hcfg=name.startswith("hcfg_")) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- lisp_facts: Lisp-family native images (SBCL / Chicken Scheme / ECL / Racket CS) (next-day candidate) -------------
# SBCL `save-lisp-and-die :executable t`: stripped runtime ELF + the core appended at a page boundary (header word
# "LCBS\0\0\0\0" = CORE_MAGIC, then a build-id entry: u64 len + chars) + 16-byte trailer <u64 core offset>"LCBS\0\0\0\0".
# Plain "..." literals are (simple-array character) = UTF-32LE in the core (hcfg_scan: stride4-*); #.(coerce ..
# 'simple-base-string) / (unsigned-byte 8) vectors are 1 byte per element. Runtime version: "--version\0<v>\0SBCL %s".
# Chicken 5 (csc): DT_NEEDED libchicken.so.N (or -static: C_* runtime symbols), C_toplevel; literals are serialized in
# C_decode_literal frames ("\xfeB" + u24 BE len + bytes; #u8 vectors raw). ECL: libecl.so.N / cl_boot. Racket CS
# `raco exe`: boot files + embedded .zo in a `.rackboot` section. HCFG offset = the first stored byte (the 'H' / 'S').
_SBCL_MAGIC = b"LCBS\0\0\0\0"
_LISP_RT = {"chicken": {"C_toplevel", "CHICKEN_main", "CHICKEN_run", "C_decode_literal", "C_initialize_lf"},
            "ecl": {"cl_boot", "ecl_init_module", "cl_shutdown", "ecl_make_symbol", "si_safe_eval"}}
_LISP_CUES = {"sbcl": (b"\0SBCL %s\n", b"--core\0", b"sbcl.core\0", b"SBCL_HOME\0"),
              "chicken": (b"libchicken.so", b"CHICKEN_main\0", b"C_decode_literal\0", b"chicken.base#"),
              "ecl": (b"libecl.so", b"cl_boot\0", b"ecl_init_module\0", b"ECL (Embeddable Common-Lisp)"),
              "racket": (b".rackboot\0", b"racket/base", b"racket/private/", b"PLT_CS_")}
_LISP_LANG = {"sbcl": "common-lisp", "ecl": "common-lisp", "chicken": "scheme", "racket": "racket"}


def _sbcl_core(d, secs):
    """Core start offset of an SBCL executable: the trailer, else CORE_MAGIC at the first page boundary(s) after the
    ELF's last section / section table (a cropped image keeps the header), else None."""
    if len(d) >= 16 and d[-8:] == _SBCL_MAGIC:
        off = int.from_bytes(d[-16:-8], "little")
        if 0 < off < len(d) - 16 and d[off:off + 8] == _SBCL_MAGIC:
            return off
    b64, e = d[4] == 2, "<" if d[5] == 1 else ">"
    shoff = struct.unpack_from(e + ("Q" if b64 else "I"), d, 40 if b64 else 32)[0]
    shes, shn = struct.unpack_from(e + "HH", d, 58 if b64 else 46)
    end = max([shoff + shes * shn] + [s[3] + s[4] for s in secs if s[1] != 8])
    for page in (4096, 65536, 32768, 16384, 8192):
        p = -(-end // page) * page
        for q in range(p, min(p + 8 * page, len(d) - 7), page):
            if d[q:q + 8] == _SBCL_MAGIC:
                return q
    return None


def lisp_facts(data, hcfg=True):
    """Lisp-family runtime facts of an ELF image (bytes only): format, architecture, lisp_runtime ("sbcl" / "chicken"
    / "ecl" / "racket" / "none") + lisp_language ("common-lisp" / "scheme" / "racket"), has_<rt>_runtime (symbols,
    DT_NEEDED, SBCL core, .rackboot section; raw string cues count only for images without .symtab, 2+ needed),
    has_sbcl_core, sbcl_core_offset, sbcl_build_id, sbcl_version, has_libchicken_needed / chicken_soname,
    has_c_toplevel, ecl_soname, has_rackboot_section, needed; hcfg_offset / hcfg_encoding / hcfg_section (ELF section,
    "sbcl_core" past the core start; hcfg=False skips the scan). Absent -> "none" / "false"; not an ELF -> None."""
    try:
        d = bytes(data)
        if not (d[:4] == b"\x7fELF" and len(d) >= 64 and d[4] in (1, 2) and d[5] in (1, 2)):
            return None
        tf = lambda b: "true" if b else "false"   # noqa: E731
        try:
            secs, syms = _gf_elf(d)
        except _PARSE_ERR:
            secs, syms = [], []
        try:
            needed = list(_elf_pair_facts(d).get("needed") or [])
        except Exception:   # noqa: BLE001
            needed = []
        names = {s[0] for s in syms}
        snames = {s[0] for s in secs}
        nosym = not any(s[1] == 2 for s in secs)
        out = {"format": "elf", "architecture": _arch_of(d) or "none", "needed": needed}
        try:
            core = _sbcl_core(d, secs)
        except _PARSE_ERR:
            core = None
        so = {k: next((n for n in needed if n.startswith(f"lib{k}.so")), None) for k in ("chicken", "ecl")}
        rt = {"sbcl": core is not None,
              "chicken": bool(so["chicken"] or names & _LISP_RT["chicken"]),
              "ecl": bool(so["ecl"] or names & _LISP_RT["ecl"]),
              "racket": ".rackboot" in snames}
        if nosym:
            for k, cues in _LISP_CUES.items():
                rt[k] = rt[k] or sum(c in d for c in cues) >= 2
        lang = next((k for k in ("sbcl", "chicken", "ecl", "racket") if rt[k]), None)
        out["lisp_runtime"] = lang or "none"
        out["lisp_language"] = _LISP_LANG.get(lang, "none")
        for k in ("sbcl", "chicken", "ecl", "racket"):
            out[f"has_{k}_runtime"] = tf(rt[k])
        out["has_sbcl_core"] = tf(core is not None)
        out["sbcl_core_offset"] = core if core is not None else "none"
        bid = ver = None
        if core is not None:
            h = d[core + 8:core + 256]
            for k in range(0, len(h) - 8, 8):
                n = int.from_bytes(h[k:k + 8], "little")
                s = h[k + 8:k + 8 + n]
                if 4 <= n <= 160 and len(s) == n and all(32 < c < 127 for c in s):
                    bid = s.decode("latin-1")
                    break
        if rt["sbcl"]:
            m = re.search(rb"\0(\d+\.\d+\.\d+(?:[.+-][\w.+-]{0,40})?)\0SBCL %s\n", d[:core or len(d)])
            ver = m.group(1).decode("latin-1") if m else None
        out["sbcl_build_id"] = bid or "none"
        out["sbcl_version"] = ver or "none"
        out["has_libchicken_needed"] = tf(so["chicken"])
        out["chicken_soname"] = so["chicken"] or "none"
        out["has_c_toplevel"] = tf(rt["chicken"] and "C_toplevel" in names)
        out["ecl_soname"] = so["ecl"] or "none"
        out["has_rackboot_section"] = tf(".rackboot" in snames)
        hs = {"hcfg_offset": "none", "hcfg_encoding": "none", "hcfg_section": "none"}
        if hcfg:
            hit = hcfg_find(d)
            off = getattr(hit, "offset", None) if hit is not None else None
            if isinstance(off, int) and 0 <= off < len(d):
                hs["hcfg_offset"], hs["hcfg_encoding"] = off, hit.encoding
                if core is not None and off >= core:
                    hs["hcfg_section"] = "sbcl_core"
                else:
                    hs["hcfg_section"] = next((s[0] for s in secs if s[1] != 8 and s[2] and s[0] and
                                               s[3] <= off < s[3] + s[4]), "none")
        out.update(hs)
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def lisp_field(data, name):
    """One lisp_facts value; "none" when the input is no ELF or the field is unknown (never raises)."""
    try:
        return (lisp_facts(data, hcfg=name.startswith("hcfg_")) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- dart_facts: Dart AOT (`dart compile exe`) snapshot identity + HCFG placement (next-day candidate) ---------------
# The AOT snapshot is an ELF whose .dynsym exports _kDartVmSnapshotData/Instructions, _kDartIsolateSnapshotData/
# Instructions (+ _kDart*SnapshotBss, _kDartSnapshotBuildId). Packaging: dart2native appends it to dartaotruntime
# (PE/ELF/Mach-O): runtime ++ pad to 4096 ++ snapshot ELF ++ uint64 LE snapshot offset ++ dc dc f6 f6 00 00 00 00; or
# the snapshot symbols sit in the image's own ELF (standalone). Each *SnapshotData opens with runtime/vm/snapshot.h's
# header: int32 magic 0xdcdcf5f5, int64 length, int64 kind (0 full, 1 full-core, 2 full-jit, 3 full-aot), the 32-char
# version hash, then the NUL-terminated features string ("product ... x64 compressed-pointers null-safety").
# String literals are OneByteString objects (latin-1 payload after a tags word + Smi length) -> hcfg_find's raw /
# base64 scan sees them; HCFG offset stays the payload start. Runtime cues: Dart_* API names, "<ver> (<channel>) (...)
# on \"<os>_<arch>\"". The version hash ties the image to an SDK build (provenance).
_DART_TRAILER = b"\xdc\xdc\xf6\xf6\0\0\0\0"
_DART_SNAP_MAGIC = b"\xf5\xf5\xdc\xdc"
_DART_SYMS = ("_kDartVmSnapshotData", "_kDartVmSnapshotInstructions", "_kDartIsolateSnapshotData",
              "_kDartIsolateSnapshotInstructions")
_DART_KIND = {0: "full", 1: "full-core", 2: "full-jit", 3: "full-aot"}
_DART_ARCH = ("x64", "ia32", "arm64", "arm", "riscv64", "riscv32", "simarm", "simarm64")
_DART_VER = re.compile(rb"(\d+\.\d+\.\d+(?:-[\w.]+)?) \((stable|beta|dev|main|be)\) \([^)]{0,80}\) on \"(\w{1,40})\"")


def _dart_snap_elf(d, base):
    """(symbols {name: file offset in d}, secs, syms, base) of an ELF at d[base:] exporting _kDart* symbols, else None."""
    sub = d[base:] if base else d
    if sub[:4] != b"\x7fELF" or len(sub) < 64 or sub[4] not in (1, 2) or sub[5] not in (1, 2):
        return None
    try:
        secs, syms = _gf_elf(sub)
    except _PARSE_ERR:
        return None
    out = {}
    for n, _ty, _b, shndx, val, _sz in syms:
        if n.startswith("_kDart") and n not in out and 0 < shndx < len(secs):
            s = secs[shndx]
            out[n] = base + s[3] + val - s[2] if s[1] != 8 and s[2] <= val <= s[2] + s[4] else None
    return (out, secs, syms, base) if any(k in out for k in _DART_SYMS) else None


def _dart_header(d, off):
    """(length, kind, hash, features) of a snapshot header at d[off], else None."""
    if not isinstance(off, int) or off < 0 or d[off:off + 4] != _DART_SNAP_MAGIC:
        return None
    ln, kind = struct.unpack_from("<qq", d, off + 4)
    h = bytes(d[off + 20:off + 52])
    if not re.fullmatch(rb"[0-9a-f]{32}", h):
        return None
    z = d.find(b"\0", off + 52, off + 52 + 2048)
    feat = bytes(d[off + 52:z]).decode("latin-1") if z > 0 else ""
    return ln, kind, h.decode(), feat if all(32 <= ord(c) < 127 for c in feat) else ""


def dart_facts(data, hcfg=True):
    """Dart AOT facts of an executable (bytes only): format, architecture, has_dart_runtime (Dart_* API strings or
    snapshot symbols), is_dart_aot (snapshot ELF exporting _kDart* found), packaging ("appended" dart2native trailer /
    "standalone" own .dynsym / "embedded" ELF inside / "none"), snapshot_offset + snapshot_size (embedded ELF; 0 +
    file size standalone), snapshot_symbols (sorted _kDart*), vm/isolate_snapshot_data/instructions_offset (file
    offsets), snapshot_build_id (GNU build-id note of the snapshot ELF, hex), snapshot_hash (32-hex version hash of the
    isolate -- else vm -- data header), snapshot_kind ("full-aot"), snapshot_features, snapshot_arch,
    compressed_pointers, null_safety, product_mode, dart_version / dart_channel / dart_target ("3.5.4" "stable"
    "linux_x64"); hcfg_symbol (_kDart* region holding the hcfg_find hit) / hcfg_section (snapshot ELF section) /
    hcfg_in_snapshot (hcfg=False skips the scan). Absent -> "none" / "false" / []; not PE/ELF/Mach-O -> None."""
    try:
        d = bytes(data)
        fmt = ("elf" if d[:4] == b"\x7fELF" else "pe" if d[:2] == b"MZ" else
               "macho" if d[:4] in (b"\xcf\xfa\xed\xfe", b"\xce\xfa\xed\xfe", b"\xca\xfe\xba\xbe") else None)
        if fmt is None or len(d) < 64:
            return None
        tf = lambda b: "true" if b else "false"   # noqa: E731
        out = {"format": fmt, "architecture": _arch_of(d) or "none"}
        snap, pack, size = None, "none", "none"
        if d[-8:] == _DART_TRAILER and len(d) >= 80:
            off = struct.unpack_from("<Q", d, len(d) - 16)[0]
            if 0 < off < len(d) - 16:
                snap = _dart_snap_elf(d[:len(d) - 16], off)
                if snap:
                    pack, size = "appended", len(d) - 16 - off
        if snap is None and fmt == "elf":
            snap = _dart_snap_elf(d, 0)
            if snap:
                pack, size = "standalone", len(d)
        if snap is None and b"_kDartIsolateSnapshotData" in d:
            p, tries = d.find(b"\x7fELF", 1), 0
            while 0 < p and tries < 64:
                tries += 1
                if p % 16 == 0:
                    snap = _dart_snap_elf(d, p)
                    if snap:
                        pack, size = "embedded", len(d) - p
                        break
                p = d.find(b"\x7fELF", p + 1)
        syms, secs, base = (snap[0], snap[1], snap[3]) if snap else ({}, [], 0)
        api = len(set(re.findall(rb"\bDart_(?:Initialize|CreateIsolateGroup\w*|RunLoop|ShutdownIsolate|Cleanup|"
                                 rb"IsolateMakeRunnable|InvokeMain\w*|NewStringFromCString|SetVMFlags)\b", d[:96 << 20])))
        out["is_dart_aot"] = tf(snap)
        out["packaging"] = pack
        out["snapshot_offset"] = base if snap else "none"
        out["snapshot_size"] = size
        out["snapshot_symbols"] = sorted(syms)
        for k, n in (("vm_snapshot_data_offset", "_kDartVmSnapshotData"),
                     ("vm_snapshot_instructions_offset", "_kDartVmSnapshotInstructions"),
                     ("isolate_snapshot_data_offset", "_kDartIsolateSnapshotData"),
                     ("isolate_snapshot_instructions_offset", "_kDartIsolateSnapshotInstructions")):
            out[k] = syms[n] if isinstance(syms.get(n), int) else "none"
        bid = "none"
        for nm_, ty, _a, so, sz in secs:
            if ty == 7 and nm_ == ".note.gnu.build-id" and sz >= 16:
                o = base + so
                nsz, dsz, nty = struct.unpack_from("<III", d, o)
                if nty == 3 and 0 < dsz <= 64:
                    bid = d[o + 12 + ((nsz + 3) & ~3):][:dsz].hex()
        out["snapshot_build_id"] = bid
        hdr = (_dart_header(d, out["isolate_snapshot_data_offset"]) or
               _dart_header(d, out["vm_snapshot_data_offset"]))
        if hdr is None and snap is None and api >= 2:   # symbols lost: one bounded header scan
            p, tries = d.find(_DART_SNAP_MAGIC), 0
            while p >= 0 and hdr is None and tries < 256:
                tries += 1
                hdr = _dart_header(d, p)
                p = d.find(_DART_SNAP_MAGIC, p + 1)
        out["has_dart_runtime"] = tf(snap or hdr)   # Dart_* strings alone (a literal) never decide
        out = {k: out[k] for k in ("format", "architecture", "has_dart_runtime")} | out
        feats = hdr[3].split() if hdr else []
        out["snapshot_hash"] = hdr[2] if hdr else "none"
        out["snapshot_kind"] = _DART_KIND.get(hdr[1], str(hdr[1])) if hdr else "none"
        out["snapshot_features"] = hdr[3] if hdr and hdr[3] else "none"
        out["snapshot_arch"] = next((t for t in feats if t in _DART_ARCH), "none")
        out["compressed_pointers"] = ("true" if "compressed-pointers" in feats else "false") if feats else "none"
        out["null_safety"] = ("true" if "null-safety" in feats else "false" if "no-null-safety" in feats else "none") \
            if feats else "none"
        out["product_mode"] = tf("product" in feats) if feats else "none"
        m = _DART_VER.search(d, 0, base if snap and base else min(len(d), 96 << 20)) if out["has_dart_runtime"] == \
            "true" else None
        out["dart_version"] = m.group(1).decode() if m else "none"
        out["dart_channel"] = m.group(2).decode() if m else "none"
        out["dart_target"] = m.group(3).decode() if m else "none"
        hs = {"hcfg_symbol": "none", "hcfg_section": "none", "hcfg_in_snapshot": "none"}
        if hcfg:
            hit = hcfg_find(d)
            off = getattr(hit, "offset", None) if hit is not None else None
            if isinstance(off, int) and 0 <= off < len(d):
                inside = bool(snap) and base <= off < base + (size if isinstance(size, int) else 0)
                hs["hcfg_in_snapshot"] = tf(inside)
                if inside:
                    rel = off - base
                    k = next((k for k, s in enumerate(secs) if s[1] != 8 and s[4] and s[3] <= rel < s[3] + s[4]), None)
                    if k is not None:
                        hs["hcfg_section"] = secs[k][0] or "none"
                        own = [(o, n) for n, o in syms.items() if isinstance(o, int) and o <= off and
                               any(s[0] == n and s[3] == k for s in snap[2])]
                        if own:
                            hs["hcfg_symbol"] = max(own)[1]
        out.update(hs)
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def dart_field(data, name):
    """One dart_facts value; "none" when the input is no executable or the field is unknown (never raises)."""
    try:
        return (dart_facts(data, hcfg=name.startswith("hcfg_")) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- kotlin_native_facts: Kotlin/Native (konanc) identity + kfun / KString facts (next-day candidate) -----------------
# konanc symbols: kfun:<owner>#<name>(<params>){}<ret> (owner = package or package.Class, "" at the root:
# kfun:#main(){}), kclass:<fq>, ktype:<fq> (TypeInfo), kvar:/kobjref:. Runtime: Konan_main / Konan_start /
# Kotlin_initRuntimeIfNeeded. String literals are static KString arrays: ArrayHeader {TypeInfo* (low bits = tags),
# uint32 count} (16 bytes on 64-bit, 8 on 32-bit) then count UTF-16 code units, no terminator -> an HCFG stored as text
# sits in a utf16le-* hit whose offset (= first stored byte) is the KString payload.
_KN_RT = {"Konan_main", "Konan_start", "Konan_run_start", "Kotlin_initRuntimeIfNeeded", "Kotlin_initRuntime",
          "Kotlin_deinitRuntimeIfNeeded", "Kotlin_main"}
_KN_CUES = (b"kotlin.native.internal", b"Kotlin_initRuntimeIfNeeded", b"Konan_main", b"Konan_start",
            b"kotlin.native.concurrent", b"kfun:")
_KN_STD = ("kotlin.", "kotlinx.", "kotlin#", "kotlinx#")


def _kn_fun(n):
    """'kfun:com.x.Cfg#decode(kotlin.String){}kotlin.Int' -> ('com.x.Cfg', 'decode') or None."""
    owner, sep, rest = n[5:].partition("#")
    name = re.match(r"[^(]*", rest).group(0) if sep else ""
    return (owner, name) if name else None


def kotlin_native_facts(data, hcfg=True):
    """Kotlin/Native (konanc) facts of an ELF image (bytes only): format, architecture, has_kotlin_native_runtime
    (Konan_main / Kotlin_initRuntimeIfNeeded / kfun:/kclass:/ktype: symbols in .symtab/.dynsym, or -- only without
    .symtab -- 2+ raw runtime cues, ASCII or UTF-16LE), has_konan_main, kfun_symbols (defined kfun: names, raw),
    user_kfun_symbols (no kotlin./kotlinx. owner), kotlin_functions (user owner.name, root -> name), kfun_owners,
    kclass_names / ktype_names (user, prefix dropped), main_function (the root `main` kfun symbol), function_count
    (user kfuns), stdlib_function_count; hcfg_encoding / hcfg_symbol / hcfg_section for the hcfg_find hit and its
    KString (hcfg_in_kstring when the uint32 count before the payload covers the UTF-16 text, hcfg_kstring_header_offset
    = offset - 16 (64-bit) / - 8, hcfg_kstring_length = count, hcfg_kstring_type = symbol the TypeInfo pointer & ~3
    names; hcfg=False skips the scan). Absent -> "none" / "false" / [] / 0; not ELF -> None."""
    try:
        d = bytes(data)
        if not (d[:4] == b"\x7fELF" and len(d) >= 64 and d[4] in (1, 2) and d[5] in (1, 2)):
            return None
        tf = lambda b: "true" if b else "false"   # noqa: E731
        try:
            secs, syms = _gf_elf(d)
        except _PARSE_ERR:
            secs, syms = [], []
        out = {"format": "elf", "architecture": _arch_of(d) or "none"}
        dfn = [s for s in syms if s[3] != 0]
        names = {s[0] for s in dfn}
        kfun = sorted(n for n in names if n.startswith("kfun:"))
        kcls = {n for n in names if n.startswith(("kclass:", "ktype:"))}
        rt = bool(names & _KN_RT) or bool(kfun) and bool(kcls or len(kfun) >= 2)
        if not rt and not any(s[1] == 2 for s in secs):   # strip'd: raw runtime cues (TypeInfo names are KStrings)
            rt = sum(c in d or _widen(c) in d for c in _KN_CUES) >= 2
        if not rt:
            kfun, kcls = [], set()
        out["has_kotlin_native_runtime"] = tf(rt)
        out["has_konan_main"] = tf(rt and "Konan_main" in names)
        user = [n for n in kfun if not n[5:].startswith(_KN_STD)]
        parsed = [p for p in map(_kn_fun, user) if p]
        out["kfun_symbols"], out["user_kfun_symbols"] = kfun, user
        out["kotlin_functions"] = sorted({f"{o}.{m}" if o else m for o, m in parsed})
        out["kfun_owners"] = sorted({o for o, _ in parsed if o})
        for pre, key in (("kclass:", "kclass_names"), ("ktype:", "ktype_names")):
            out[key] = sorted(n[len(pre):] for n in kcls if n.startswith(pre) and not n[len(pre):].startswith(_KN_STD))
        out["main_function"] = next((n for n in user if n.startswith("kfun:#main(")), "none")
        out["function_count"], out["stdlib_function_count"] = len(user), len(kfun) - len(user)
        hs = {"hcfg_encoding": "none", "hcfg_symbol": "none", "hcfg_section": "none", "hcfg_in_kstring": "false",
              "hcfg_kstring_header_offset": "none", "hcfg_kstring_length": "none", "hcfg_kstring_type": "none"}
        if hcfg:
            hit = hcfg_find(d)
            off = getattr(hit, "offset", None) if hit is not None else None
            if isinstance(off, int) and 0 <= off < len(d):
                hs["hcfg_encoding"] = hit.encoding
                w, e = (8, "<Q") if d[4] == 2 else (4, "<I")
                e = e if d[5] == 1 else ">" + e[1]
                ue = "<I" if d[5] == 1 else ">I"
                run = re.match(rb"(?:[\x09-\x7e]\x00)*", d[off:off + (2 << 20)]).group(0)
                # sizeof(ArrayHeader) = 2 words (count, then pad on 64-bit); packed 12-byte header as fallback
                for ho, co in ((off - 2 * w, off - w), (off - 12, off - 4)) if w == 8 else ((off - 8, off - 4),):
                    if not (rt and hit.encoding.startswith("utf16le-") and ho >= 0):
                        break
                    cnt = struct.unpack_from(ue, d, co)[0]
                    if 0 < cnt <= len(run) // 2 and not any(d[co + 4:off]):
                        hs["hcfg_in_kstring"] = "true"
                        hs["hcfg_kstring_header_offset"], hs["hcfg_kstring_length"] = ho, cnt
                        ti = struct.unpack_from(e, d, ho)[0] & ~3
                        tn = [s[0] for s in dfn if s[4] == ti and ti and s[1] in (0, 1) and s[0].startswith("ktype:")]
                        hs["hcfg_kstring_type"] = tn[0] if tn else "none"
                        break
                k = next((k for k, s in enumerate(secs) if s[1] != 8 and s[2] and s[3] <= off < s[3] + s[4]), None)
                if k is not None:
                    hs["hcfg_section"] = secs[k][0] or "none"
                    va = secs[k][2] + off - secs[k][3]
                    cand = [s for s in dfn if s[1] in (0, 1) and s[0] and not s[0].startswith(".")
                            and (s[3] == k or s[3] == 0xFFF1) and (s[4] == va or s[4] < va < s[4] + s[5])]
                    if cand:
                        hs["hcfg_symbol"] = min(cand, key=lambda s: (s[4] != va, va - s[4]))[0]
        out.update(hs)
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def kotlin_native_field(data, name):
    """One kotlin_native_facts value; "none" when the input is no ELF or the field is unknown (never raises)."""
    try:
        return (kotlin_native_facts(data, hcfg=name.startswith("hcfg_")) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- language_of: ONE consistent source-language / toolchain token per image (17 seen D1-D17 + next candidates) ----
# Seen (expected = the day's theme): d01/d15 c, d02 cpp, d03 csharp (.NET dll), d04 go, d05 rust, d06 java, d07 kotlin,
# d08 swift, d09 nim, d10 zig, d11 d, d12 pascal, d13 crystal, d14 objc, d16 wasm, d17 ada.
LANG_TOKEN = {"gnat": "ada", "fpc": "pascal"}            # lang_facts runtime keys -> language_of tokens
LANG_ALIASES = {"c": ["c"], "cpp": ["cpp", "c++"], "csharp": ["csharp", "c#", "dotnet", ".net"],
                "fsharp": ["fsharp", "f#", "dotnet"], "vbnet": ["vbnet", "vb.net", "dotnet"], "go": ["go", "golang"],
                "rust": ["rust"], "java": ["java", "jvm"], "kotlin": ["kotlin", "jvm"], "scala": ["scala", "jvm"],
                "groovy": ["groovy", "jvm"], "clojure": ["clojure", "jvm"], "swift": ["swift"], "nim": ["nim"],
                "zig": ["zig"], "d": ["d", "dlang"], "pascal": ["pascal", "fpc", "freepascal", "delphi", "objectpascal"],
                "crystal": ["crystal"], "objc": ["objc", "objective-c"], "wasm": ["wasm", "wat", "webassembly"],
                "ada": ["ada", "gnat"], "haskell": ["haskell", "ghc"], "ocaml": ["ocaml"], "fortran": ["fortran"],
                "cobol": ["cobol"], "odin": ["odin"], "v": ["v", "vlang"], "dart": ["dart"], "julia": ["julia"],
                "kotlin-native": ["kotlin-native", "kotlin", "konan"], "python": ["python"], "vb6": ["vb6", "visualbasic"],
                "autoit": ["autoit"], "modula2": ["modula2", "modula-2", "m2", "gm2"]}
# candidate runtimes lang_facts does not know: (token, toolchain, kind, cues). kind "sym" = a symbol-name cue: it only
# decides when found in .strtab/.dynstr (or the image has no symbol table); a hit elsewhere in the bytes (string
# literal) is logged under `ambiguous`. kind "str" = a runtime string / magic that is decisive anywhere.
_LANG_CUES = (
    ("kotlin-native", "konan", "sym", (b"kfun:", b"Konan_main", b"Kotlin_initRuntime")),
    ("haskell", "ghc", "sym", (b"ghczmprim_GHC", b"base_GHCziTopHandler", b"hs_init_ghc", b"stg_ap_0_fast")),
    ("ocaml", "ocamlopt", "sym", (b"caml_startup", b"caml_main", b"camlStdlib", b"caml_program")),
    ("fortran", "gfortran", "sym", (b"_gfortran_set_args", b"_gfortran_st_write", b"_gfortran_set_options")),
    # GCC front ends (plain dynamic ELF, gcc .comment): gm2 links libm2pim/libm2iso (+ libstdc++), gcobol libgcobol
    ("modula2", "gm2", "sym", (b"_M2RTS_ConstructModules", b"_M2RTS_RegisterModule", b"libm2pim.so", b"libm2iso.so")),
    ("cobol", "gcobol", "sym", (b"__gg__init_program_state", b"__gg__module_name_push", b"libgcobol.so")),
    ("cobol", "gnucobol", "sym", (b"cob_init", b"cob_module_enter", b"cob_resolve")),
    ("julia", "julia", "sym", (b"jl_init_with_image", b"jl_atexit_hook", b"libjulia")),
    ("dart", "dart", "sym", (b"_kDartVmSnapshotData", b"_kDartIsolateSnapshotInstructions")),
    ("odin", "odin", "sym", (b"__$startup_runtime", b"__$cleanup_runtime", b"runtime.default_allocator_proc")),
    ("v", "v", "sym", (b"_vinit", b"_vcleanup", b"builtin__panic")),
    ("python", "pyinstaller", "str", (b"MEI\x0c\x0b\x0a\x0b\x0e", b"_MEIPASS2", b"pyi-runtime-tmpdir")),
    ("python", "nuitka", "str", (b"__nuitka_", b"NUITKA_ONEFILE", b"nuitka-version")),
    ("python", "py2exe", "str", (b"PYTHONSCRIPT\0",)),
    ("csharp", "nativeaot", "sym", (b"S_P_CoreLib_System_", b"__managed__Main")),
    ("vb6", "msvbvm", "str", (b"MSVBVM60.DLL", b"MSVBVM50.DLL")),
    ("autoit", "autoit", "str", (b"AU3!EA06", b">>>AUTOIT SCRIPT<<<")),
    ("pascal", "delphi", "str", (b"Embarcadero Delphi", b"Borland Delphi", b"SOFTWARE\\Borland\\Delphi\\RTL")),
)
_TC_NATIVE = {"go": "gc", "rust": "rustc", "swift": "swiftc", "nim": "nim", "zig": "zig", "pascal": "fpc",
              "crystal": "crystal", "ada": "gnat"}
_WASM_PRODUCERS = ((b"rustc", "rustc", "rust"), (b"Emscripten", "emscripten", "c"), (b"TinyGo", "tinygo", "go"),
                   (b"AssemblyScript", "assemblyscript", "assemblyscript"), (b"clang", "clang", "c"),
                   (b"wit-component", "wit-component", "none"))


def _jvm_lang(names, read):
    """(language, evidence) for a jar's entry names / class-bytes reader (None, []) when no JVM content."""
    cls = [n for n in names if n.endswith(".class")]
    if not cls:
        return None, []
    for tok, pre in (("kotlin", "kotlin/"), ("scala", "scala/"), ("clojure", "clojure/"), ("groovy", "groovy/")):
        if any(n.startswith(pre) for n in names):
            return tok, [f"jar entries {pre}*"]
    if any(n.endswith(".kotlin_module") for n in names):
        return "kotlin", ["META-INF/*.kotlin_module"]
    for n in cls[:64]:
        b = read(n)
        for tok, cue in (("kotlin", b"Lkotlin/Metadata;"), ("scala", b"Lscala/reflect/ScalaSignature;"),
                         ("groovy", b"groovy/lang/GroovyObject"), ("clojure", b"clojure/lang/")):
            if cue in b:
                return tok, [f"{n}: {cue.decode()}"]
    for n in cls[:64]:   # niche JVM languages (jvm_niche_facts cues), only where plain "java" would be reported
        c = b"" if _NICHE_RT.match(n) else read(n)
        p = classfile_parse(c) if any(k in c for k in _NICHE_CUES) else None
        tok = _niche_lang_of(p) if p else None
        if tok:
            return tok, [f"{n}: niche JVM language cue ({tok})"]
    return "java", [f"{len(cls)} .class entries, no kotlin/scala/groovy/clojure marker"]


def language_of(data):
    """Source language + toolchain of a compiled member, with evidence (bytes only, no subprocess).
    -> {format, language, toolchain, aliases, evidence [..], candidates [every language with a cue], ambiguous
    "true"/"false", ambiguous_with [..], source_language (wasm producers / .NET flavour, else "none")}.
    language tokens: c cpp csharp fsharp vbnet go rust java kotlin scala groovy clojure swift nim zig d pascal crystal
    objc wasm ada + candidates haskell ocaml fortran cobol odin v dart julia kotlin-native python vb6 autoit modula2.
    Native images: lang_facts runtime hit (gnat->ada, fpc->pascal) wins; a candidate cue table refines c/cpp
    (C-runtime languages). .NET PE (CLI header + BSJB) -> csharp unless FSharp.Core / Microsoft.VisualBasic.
    jar / bare .class -> java unless kotlin/scala/groovy/clojure markers. wasm stays "wasm" (D16), its producers
    section only fills toolchain/source_language. None for anything that is not an executable image / jar / class."""
    try:
        d = bytes(data)
        ev, cands = [], []
        out = {"format": "none", "language": "none", "toolchain": "none", "source_language": "none"}
        if d[:4] == b"\xca\xfe\xba\xbe" and len(d) >= 10 and int.from_bytes(d[6:8], "big") >= 45 \
                and int.from_bytes(d[4:8], "big") >= 45:
            out["format"] = "class"
            lang, ev = _jvm_lang(["x.class"], lambda n: d)
        elif d[:2] == b"PK":
            import zipfile
            try:
                z = zipfile.ZipFile(io.BytesIO(d))
                names = z.namelist()
            except (zipfile.BadZipFile, OSError, EOFError, RuntimeError, ValueError, struct.error):
                return None

            def read(n):
                try:
                    zi = z.getinfo(n)
                    return z.read(n) if zi.file_size < (4 << 20) else b""
                except Exception:   # noqa: BLE001 -- encrypted / broken entry
                    return b""
            lang, ev = _jvm_lang(names, read)
            if lang is None:
                return None
            out["format"] = "jar"
        else:
            lang = None
            lay = _pe_layout(d) if d[:2] == b"MZ" else None
            if lay and len(lay[2]) > 14 and lay[2][14][0] and b"BSJB" in d:
                out["format"] = "pe"
                lang = "fsharp" if b"FSharp.Core" in d else ("vbnet" if b"Microsoft.VisualBasic" in d else "csharp")
                ev = ["PE CLI header (data dir 14) + BSJB metadata"] + \
                     ([f"assembly ref {'FSharp.Core' if lang == 'fsharp' else 'Microsoft.VisualBasic'}"]
                      if lang != "csharp" else [])
                out["toolchain"] = "dotnet"
                if b"<CrtImplementationDetails>" in d:
                    lang, ev = "cpp", ev + ["C++/CLI <CrtImplementationDetails>"]
                    out["toolchain"] = "msvc"
                out["source_language"] = lang
        if lang is not None:
            out["toolchain"] = out["toolchain"] if out["toolchain"] != "none" else \
                {"kotlin": "kotlinc", "scala": "scalac", "groovy": "groovyc", "clojure": "clojure"}.get(lang, "javac")
            cands = [lang]
        else:
            f = lang_facts(d)
            if not f:
                return None
            fmt = out["format"] = f["format"]
            hits = [LANG_TOKEN.get(k, k) for k in LANG_ORDER if f.get(f"has_{k}_runtime") == "true"]
            ev = [f"has_{k}_runtime" for k in LANG_ORDER if f.get(f"has_{k}_runtime") == "true"]
            ev += [k for k in ("has_cpp_mangled_symbol",) if f.get(k) == "true" and not hits]
            lang, cands = f["language"], list(hits)
            lang = LANG_TOKEN.get(lang, lang)
            # symbol-string region (where a "sym" cue is decisive) + .comment banner
            symtxt, comment, has_symtab = d, b"", fmt != "elf"
            if fmt == "elf":
                lay = _elf_layout(d)
                parts = []
                for nm, o, n in (lay[1] if lay else []):
                    if nm in (".strtab", ".dynstr"):
                        parts.append(d[o:o + n])
                        has_symtab = has_symtab or nm == ".strtab"
                    elif nm == ".comment":
                        comment = d[o:o + min(n, 4096)]
                symtxt = b"\0".join(parts)
            weak = []
            for tok, tc, kind, cues in (_LANG_CUES if lang in ("c", "cpp") else ()):   # C-runtime languages only
                hay = symtxt if kind == "sym" and has_symtab else d
                if tok == "dart" and d[-8:] == _DART_TRAILER:   # dart2native: the cue is the appended snapshot's .dynstr
                    hay = d
                cue = next((c for c in cues if c in hay), None)
                strong = cue is not None
                if cue is None and hay is not d and len(d) <= (8 << 20):   # bounded string-literal (decoy) pass
                    cue = next((c for c in cues if c in d), None)
                if cue is None:
                    continue
                (cands if strong else weak).append(tok)
                ev.append(f"{tok}: {cue.decode('latin-1')!r}" + ("" if strong else " (string literal only)"))
                if strong and lang in ("c", "cpp") and (lang == "c" or tok != "pascal"):
                    lang, out["toolchain"] = tok, tc
            if fmt == "wasm":
                sec = d.find(b"\x09producers")
                body = d[sec:sec + 512] if sec >= 0 else b""
                for cue, tc, src in _WASM_PRODUCERS:
                    if cue in body:
                        out["toolchain"], out["source_language"] = tc, src
                        ev.append(f"producers section: {cue.decode()}")
                        break
            elif out["toolchain"] == "none":
                low = comment.lower()
                if lang in _TC_NATIVE:
                    out["toolchain"] = _TC_NATIVE[lang]
                elif lang == "d":
                    out["toolchain"] = "ldc" if b"ldc" in low or b"_D3ldc" in d else ("gdc" if b"gdc" in low else "dmd")
                elif b"clang" in low:
                    out["toolchain"] = "clang"
                elif b"gcc:" in low:
                    out["toolchain"] = "gcc"
                elif fmt == "pe" and b"Rich" in d[:0x400]:
                    out["toolchain"] = "msvc"
                elif fmt == "pe" and b"GCC: (" in d:
                    out["toolchain"] = "mingw"
                if comment:
                    ev.append(".comment " + comment.split(b"\0")[0][:60].decode("latin-1"))
            for t in weak:
                if t not in cands and t != lang:
                    out.setdefault("_weak", []).append(t)
            if lang not in cands:
                cands.insert(0, lang)
        amb = sorted({c for c in cands if c != lang} | set(out.pop("_weak", [])))
        out.update(language=lang, aliases=LANG_ALIASES.get(lang, [lang]), evidence=ev, candidates=cands,
                   ambiguous="true" if amb else "false", ambiguous_with=amb)
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def language_field(data, name="language"):
    """One language_of value; "none" when the input is no executable image / jar / class or the field is unknown."""
    try:
        return (language_of(data) or {}).get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"


# --- build provenance (who/what/when built it): GNU build-id, .comment banners, DWARF CU producer/language/comp_dir,
# PE TimeDateStamp / CodeView RSDS pdb / Rich header / linker version, Go + Rust toolchain versions.
_GO_BUILDINF = re.compile(rb"\xff Go buildinf:.{8,24}?(go1\.\d+(?:\.\d+)?(?:[a-z]+\d*)?)", re.S)
_RUSTC_PATH = re.compile(rb"/rustc/([0-9a-f]{40})/")
_VER = re.compile(r"(\d+\.\d+(?:\.\d+)?)")


def _elf_notes(data, e, secs_raw):
    """[(name, type, desc)] from SHT_NOTE sections (else PT_NOTE segments) of an ELF; bounded."""
    out = []
    for o, n in secs_raw:
        p, end = o, min(o + n, len(data), o + 65536)
        while p + 12 <= end:
            nsz, dsz, typ = struct.unpack_from(e + "III", data, p)
            q = p + 12 + ((nsz + 3) & ~3)
            if q + dsz > end or nsz > 256:
                break
            out.append((bytes(data[p + 12:p + 12 + nsz]).rstrip(b"\0"), typ, bytes(data[q:q + dsz])))
            p = q + ((dsz + 3) & ~3)
    return out


def _elf_prov(d, out):
    e = "<" if d[5] == 1 else ">"
    lay = _elf_layout(d)
    secs = lay[1] if lay else []
    if d[4] == 1:
        phoff, shoff = struct.unpack_from(e + "II", d, 28)
        _, phes, phn, shes, shn, _ = struct.unpack_from(e + "6H", d, 40)
        shf, phf = (e + "4xI8xII"), (e + "II8xI")   # sh_type .. sh_offset, sh_size ; p_type, p_offset, p_filesz
    else:
        phoff, shoff = struct.unpack_from(e + "QQ", d, 32)
        _, phes, phn, shes, shn, _ = struct.unpack_from(e + "6H", d, 52)
        shf, phf = (e + "4xI16xQQ"), (e + "I4xQ16xQ")
    notes = [(o, n) for t, o, n in (struct.unpack_from(shf, d, shoff + k * shes) for k in range(min(shn, 4096)))
             if t == 7] if shn and shoff + shn * shes <= len(d) else []
    if not notes and phn and phoff + phn * phes <= len(d):
        notes = [(o, n) for t, o, n in (struct.unpack_from(phf, d, phoff + k * phes) for k in range(min(phn, 256)))
                 if t == 4]
    bid = gid = "none"
    for nm, typ, desc in _elf_notes(d, e, notes):
        if nm == b"GNU" and typ == 3 and bid == "none" and desc:
            bid = desc.hex()
        elif nm == b"Go" and typ == 4 and gid == "none" and desc:
            gid = desc.decode("latin-1")
    out["build_id"], out["go_build_id"] = bid, gid
    names = {nm: (o, n) for nm, o, n in secs}
    cm = []
    if ".comment" in names:
        o, n = names[".comment"]
        for s in bytes(d[o:o + min(n, 65536)]).split(b"\0"):
            s = s.decode("utf-8", "replace").strip()
            if s and s not in cm:
                cm.append(s)
    out["compiler"] = cm[0] if cm else "none"
    out["comment_strings"] = cm
    has_dwarf = ".debug_info" in names and names[".debug_info"][1] > 0
    out["has_dwarf"] = "true" if has_dwarf else "false"
    if has_dwarf:
        _dwarf_prov(d, out)


def _dwarf_prov(d, out, max_cus=4000, budget=0.6):
    """First-CU DW_AT_producer / language / comp_dir / name (+ the distinct producers / languages over <= max_cus
    CUs) via pyelftools. A DWARF the library cannot walk leaves the first-CU fields "none"."""
    try:
        from elftools.elf.elffile import ELFFile
        from elftools.dwarf.enums import ENUM_DW_LANG
    except ImportError:
        return
    lang_name = {v: k for k, v in ENUM_DW_LANG.items()}
    prods, langs, t0 = [], [], time.time()
    try:
        dw = ELFFile(io.BytesIO(d)).get_dwarf_info(relocate_dwarf_sections=False)
        for i, cu in enumerate(dw.iter_CUs()):
            if i >= max_cus or time.time() - t0 > budget:
                break
            at = cu.get_top_DIE().attributes
            g = lambda k: at[k].value if k in at else None   # noqa: E731
            s = lambda v: v.decode("utf-8", "replace") if isinstance(v, bytes) else \
                ("none" if v is None else str(v))  # noqa: E731
            pr, ln = s(g("DW_AT_producer")), g("DW_AT_language")
            ln = lang_name.get(ln, f"0x{ln:x}") if isinstance(ln, int) else "none"
            if i == 0:
                out["dwarf_producer"], out["dwarf_language"] = pr, ln
                out["dwarf_language_num"] = str(ENUM_DW_LANG.get(ln, "none")) if ln != "none" else "none"
                out["dwarf_language_short"] = ln[len("DW_LANG_"):] if ln.startswith("DW_LANG_") else ln
                out["dwarf_comp_dir"], out["dwarf_name"] = s(g("DW_AT_comp_dir")), s(g("DW_AT_name"))
                m = _VER.search(pr)
                out["dwarf_producer_version"] = m.group(1) if m else "none"
                out["dwarf_version"] = str(cu.header.get("version", "none"))
            if pr != "none" and pr not in prods:
                prods.append(pr)
            if ln != "none" and ln not in langs:
                langs.append(ln)
    except Exception:   # noqa: BLE001 -- odd / truncated DWARF: keep what the first CUs gave
        pass
    out["dwarf_producers"], out["dwarf_languages"] = prods, langs


def _pe_prov(d, out):
    lay = _pe_layout(d)
    pe = int.from_bytes(d[0x3c:0x40], "little")
    ts = struct.unpack_from("<I", d, pe + 8)[0]
    out["timestamp"], out["timestamp_hex"] = str(ts), f"0x{ts:08x}"
    out["timestamp_iso"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(ts))
    out["timestamp_utc"] = time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime(ts))
    opt = pe + 24
    out["linker_version"] = f"{d[opt + 2]}.{d[opt + 3]:02d}"
    pdb = {"pdb_path": "none", "pdb_name": "none", "pdb_guid": "none", "pdb_age": "none", "pdb_signature": "none"}
    if lay and len(lay[2]) > 6 and lay[2][6][0] and lay[2][6][1]:
        rva, size = lay[2][6]
        base = _pe_rva(lay[1], rva)
        for k in range(min(size // 28, 64) if base is not None else 0):
            typ, _, _, ptr = struct.unpack_from("<IIII", d, base + 28 * k + 12)
            if typ == 2 and d[ptr:ptr + 4] == b"RSDS":
                g = d[ptr + 4:ptr + 20]
                a, b, c = struct.unpack_from("<IHH", g)
                guid = f"{a:08x}-{b:04x}-{c:04x}-{g[8:10].hex()}-{g[10:16].hex()}"
                age = struct.unpack_from("<I", d, ptr + 20)[0]
                path = bytes(d[ptr + 24:ptr + 24 + 1024]).split(b"\0")[0].decode("utf-8", "replace")
                pdb = {"pdb_path": path, "pdb_name": re.split(r"[\\/]", path)[-1] or "none", "pdb_guid": guid,
                       "pdb_age": str(age), "pdb_signature": guid.replace("-", "").upper() + f"{age:X}"}
                break
    out.update(pdb)
    rich = []
    r = bytes(d[0x40:pe]).find(b"Rich")
    if r >= 0 and r % 4 == 0:
        r += 0x40
        key = struct.unpack_from("<I", d, r + 4)[0]
        p = r - 4
        while p >= 0x40 and struct.unpack_from("<I", d, p)[0] ^ key != 0x536e6144:   # "DanS"
            p -= 4
        if p >= 0x40:
            for q in range(p + 16, r, 8):
                cid, cnt = struct.unpack_from("<II", d, q)
                cid, cnt = cid ^ key, cnt ^ key
                rich.append([cid >> 16, cid & 0xffff, cnt])
            out["rich_xor_key"] = f"0x{key:08x}"
    out["has_rich"] = "true" if rich else "false"
    out.setdefault("rich_xor_key", "none")
    out["rich_entries"], out["rich_count"] = rich, str(len(rich))   # [prod_id, build, count] in header order


def provenance_facts(data):
    """Build-provenance facts of an ELF or PE image (bytes only; pyelftools for DWARF). Values are strings / lists;
    an absent field is "none" (not an ELF/PE at all -> None).
    ELF: build_id (lowercase hex of the NT_GNU_BUILD_ID desc, no 0x), go_build_id (Go note), compiler (first `.comment`
    string) + comment_strings, has_dwarf; first DWARF CU: dwarf_producer, dwarf_language (DW_LANG_* name),
    dwarf_language_short (C99/Ada95/..), dwarf_language_num, dwarf_comp_dir, dwarf_name, dwarf_version,
    dwarf_producer_version (first x.y[.z] of the producer), plus
    dwarf_producers / dwarf_languages (distinct, CU order).
    PE: timestamp (TimeDateStamp decimal) / timestamp_hex / timestamp_iso (UTC ...Z) / timestamp_utc, linker_version,
    CodeView RSDS pdb_path / pdb_name / pdb_guid / pdb_age / pdb_signature (symstore GUIDAGE), has_rich,
    rich_xor_key, rich_entries [[prod_id, build, count]], rich_count.
    Both: gcc_version, clang_version, rustc_version (+ rustc_commit from /rustc/<sha>/ paths), go_version
    (buildinfo), toolchain_version (go > rustc > clang > gcc > DWARF producer version)."""
    try:
        d = bytes(data) if not isinstance(data, (bytes, bytearray)) else data
        out = {}
        if d[:4] == b"\x7fELF" and len(d) >= 64 and d[4] in (1, 2) and d[5] in (1, 2):
            out["format"] = "elf"
            _elf_prov(d, out)
        elif d[:2] == b"MZ" and len(d) >= 0x40 and d[int.from_bytes(d[0x3c:0x40], "little"):][:4] == b"PE\0\0":
            out["format"] = "pe"
            _pe_prov(d, out)
        else:
            return None
        cm = out.get("comment_strings", [])
        gcc = next((s for s in cm if s.startswith("GCC:")), "")
        m = _VER.findall(gcc.rpartition(")")[2] or gcc)
        out["gcc_version"] = m[-1] if m else "none"
        m = next((_VER.search(s[s.find("clang version"):]) for s in cm if "clang version" in s), None)
        out["clang_version"] = m.group(1) if m else "none"
        m = next((_VER.search(s[s.find("rustc version"):]) for s in cm if "rustc version" in s), None)
        out["rustc_version"] = m.group(1) if m else "none"
        m = _RUSTC_PATH.search(d)
        out["rustc_commit"] = m.group(1).decode() if m else "none"
        m = _GO_BUILDINF.search(d)
        if not m and out.get("go_build_id", "none") != "none":
            m = re.search(rb"(go1\.\d+(?:\.\d+)?)", d)
        out["go_version"] = m.group(1).decode() if m else "none"
        out["toolchain_version"] = next((out[k] for k in ("go_version", "rustc_version", "clang_version",
                                                          "gcc_version", "dwarf_producer_version")
                                         if out.get(k, "none") != "none"), "none")
        for k in ("build_id", "go_build_id", "compiler", "dwarf_producer", "dwarf_language", "dwarf_language_short",
                  "dwarf_language_num", "dwarf_comp_dir", "dwarf_name", "dwarf_version", "dwarf_producer_version",
                  "timestamp", "timestamp_hex", "timestamp_iso", "timestamp_utc", "linker_version", "pdb_path",
                  "pdb_name", "pdb_guid", "pdb_age", "pdb_signature", "has_rich", "rich_xor_key", "rich_count",
                  "has_dwarf"):
            out.setdefault(k, "none")
        for k in ("comment_strings", "dwarf_producers", "dwarf_languages", "rich_entries"):
            out.setdefault(k, [])
        return out
    except Exception:   # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


_PROV_ALIASES = {"buildid": "build_id", "gnu_build_id": "build_id", "producer": "dwarf_producer",
                 "language": "dwarf_language", "comp_dir": "dwarf_comp_dir", "pdb": "pdb_path",
                 "time_date_stamp": "timestamp", "timedatestamp": "timestamp", "compile_time": "timestamp_iso",
                 "comment": "compiler", "rust_version": "rustc_version"}


def provenance_field(data, name):
    """One provenance_facts value; "none" when the input is no ELF/PE or the field is unknown (a decoy never raises)."""
    try:
        return (provenance_facts(data) or {}).get(_PROV_ALIASES.get(name, name), "none")
    except Exception:  # noqa: BLE001
        return "none"



# --- custom ELF notes (HCFG in a `.note.<vendor>` SHT_NOTE section / PT_NOTE segment). Raw walker, not pyelftools:
# iter_notes always pads name/desc to 4, but an 8-aligned note (sh_addralign / p_align 8, readelf's rule) pads
# 12 + namesz and the desc to 8 -- an owner of namesz 5 puts the desc at +24, not +20.
_STD_NOTE_OWNERS = {"GNU", "Go", "FreeBSD", "NetBSD", "NetBSD-CORE", "NetBSD-PaX", "OpenBSD", "Android", "stapsdt",
                    "LINUX", "CORE", "Xen", "FDO", "SUNW Solaris", "LLVMOMPOFFLOAD", "AMD", "AMDGPU", "QNX", "Crashpad"}


def _note_walk(d, e, o, n, align, src, out, cap=4096):
    al = 8 if align == 8 else 4
    p, end = o, min(o + n, len(d))
    while p + 12 <= end and len(out) < cap:
        nsz, dsz, typ = struct.unpack_from(e + "III", d, p)
        q = p + ((12 + nsz + al - 1) & -al)
        if nsz > 4096 or q + dsz > end:
            break
        out.append({"owner": bytes(d[p + 12:p + 12 + nsz]).split(b"\0")[0].decode("latin-1"), "type": typ,
                    "section": src, "offset": p, "desc_offset": q, "desc_size": dsz})
        p = (q + dsz + al - 1) & -al


def elf_notes(data):
    """[{owner, type, section, offset, desc_offset, desc_size}] of every ELF note in section-table order (SHT_NOTE
    sections; PT_NOTE segments only when there is no SHT_NOTE section -- section "none"), or None (not an ELF)."""
    d = data
    if d[:4] != b"\x7fELF" or len(d) < 52 or d[4] not in (1, 2) or d[5] not in (1, 2):
        return None
    e = "<" if d[5] == 1 else ">"
    if d[4] == 1:
        phoff, shoff = struct.unpack_from(e + "II", d, 28)
        _, phes, phn, shes, shn, shstr = struct.unpack_from(e + "6H", d, 40)
        shf, phf = e + "II8xIIIII", e + "II12xI4xI"   # name type . off size link info align ; type off . filesz . align
    else:
        if len(d) < 64:
            return None
        phoff, shoff = struct.unpack_from(e + "QQ", d, 32)
        _, phes, phn, shes, shn, shstr = struct.unpack_from(e + "6H", d, 52)
        shf, phf = e + "II16xQQIIQ", e + "I4xQ16xQ8xQ"
    out, secs = [], []
    if shn and shes >= struct.calcsize(shf) and shoff + shn * shes <= len(d):
        secs = [struct.unpack_from(shf, d, shoff + k * shes) for k in range(min(shn, 65535))]
    names = b""
    if secs and shstr < len(secs):
        names = d[secs[shstr][2]:secs[shstr][2] + secs[shstr][3]]
    for s in secs:
        if s[1] == 7:
            nm = names[s[0]:names.find(b"\0", s[0])].decode("latin-1") if s[0] < len(names) else ""
            _note_walk(d, e, s[2], s[3], s[6], nm or "none", out)
    if not any(s[1] == 7 for s in secs) and phn and phes >= struct.calcsize(phf) and phoff + phn * phes <= len(d):
        for k in range(min(phn, 4096)):
            t, o, n, al = struct.unpack_from(phf, d, phoff + k * phes)
            if t == 4:
                _note_walk(d, e, o, n, al, "none", out)
    return out


def elf_note_facts(data):
    """Note-table facts of an ELF (None: not an ELF). Values are strings / lists; absent -> "none".
    notes [{owner, type, section}] / note_owners / note_types (ints) / note_types_hex / note_sections (table order),
    note_count, custom_note_owners (owners outside the standard GNU/Go/BSD/Android/stapsdt/... set), and for the
    first note whose desc holds the HCFG magic: hcfg_note_offset (file offset of the `H`; decimal) +
    hcfg_note_offset_hex, hcfg_note_owner, hcfg_note_type (decimal) + hcfg_note_type_hex, hcfg_note_section,
    hcfg_note_desc_size. has_<owner>_note via elf_note_field (owner lowercased, non-alnum -> '_')."""
    d = bytes(data)
    ns = elf_notes(d)
    if ns is None:
        return None
    out = {"notes": [{"owner": x["owner"], "type": x["type"], "section": x["section"]} for x in ns],
           "note_owners": [x["owner"] for x in ns], "note_types": [x["type"] for x in ns],
           "note_types_hex": [hex(x["type"]) for x in ns], "note_count": str(len(ns))}
    out["note_sections"] = [s for i, s in enumerate(x["section"] for x in ns)
                            if s != "none" and s not in [y["section"] for y in ns[:i]]] or "none"
    cust = []
    for x in ns:
        if x["owner"] not in _STD_NOTE_OWNERS and x["owner"] not in cust:
            cust.append(x["owner"])
    out["custom_note_owners"] = cust or "none"
    for k in ("offset", "offset_hex", "owner", "type", "type_hex", "section", "desc_size"):
        out["hcfg_note_" + k] = "none"
    for x in ns:
        i = d.find(HCFG_MAGIC, x["desc_offset"], x["desc_offset"] + x["desc_size"])
        if i >= 0:
            out.update(hcfg_note_offset=str(i), hcfg_note_offset_hex=hex(i), hcfg_note_owner=x["owner"],
                       hcfg_note_type=str(x["type"]), hcfg_note_type_hex=hex(x["type"]),
                       hcfg_note_section=x["section"], hcfg_note_desc_size=str(x["desc_size"]))
            break
    out["has_hcfg_note"] = "true" if out["hcfg_note_offset"] != "none" else "false"
    return out


def _owner_key(s):
    return re.sub(r"[^0-9a-z]+", "_", s.lower()).strip("_")


def elf_note_field(data, name):
    """One elf_note_facts value; has_<owner>_note -> "true"/"false" (owner matched case-insensitively, non-alnum as
    '_'). "none" for a non-ELF / unknown field (never raises)."""
    try:
        f = elf_note_facts(data)
        if f is None:
            return "none"
        name = name.strip().lower()
        m = re.fullmatch(r"has_(.+)_note", name)
        if m and name != "has_hcfg_note":
            return "true" if _owner_key(m.group(1)) in {_owner_key(o) for o in f["note_owners"]} else "false"
        name = {"owners": "note_owners", "types": "note_types", "hcfg_offset": "hcfg_note_offset",
                "hcfg_desc_offset": "hcfg_note_offset", "note_owner": "hcfg_note_owner"}.get(name, name)
        return f.get(name, "none")
    except Exception:  # noqa: BLE001
        return "none"

# --- config DECODER locator (D17 "recover the reversible decoder"; speculative facts): from the HCFG hit's file offset
# -> blob VA -> code xrefs (RIP-relative disp32 / absolute imm32 to [VA, VA+stored len)) -> containing function (FUNC
# symbol, else the nearest endbr64 / push rbp;mov rbp,rsp) -> its loops (backward jcc) -> the data op between the
# loop's first byte load and its byte store: xor/add/sub/rol/ror imm (key), xor reg,reg + add imm (rolling-xor, key =
# start), xor reg,reg beside a 256-bound loop (rc4). loop_length = the cmp bound (+1 under jle/jbe). x86 / x86-64 only.

def _exec_map(data):
    """(bits, [(name, va, file_off, size, executable)], pie) for an x86/x86-64 ELF or PE, else None."""
    if data[:4] == b"\x7fELF" and data[5] == 1:
        b64 = data[4] == 2
        mach = struct.unpack_from("<H", data, 18)[0]
        if mach not in (3, 62):
            return None
        shoff = struct.unpack_from("<Q" if b64 else "<I", data, 40 if b64 else 32)[0]
        shes, shn, shstr = struct.unpack_from("<HHH", data, 58 if b64 else 46)
        fmt = "<IIQQQQ" if b64 else "<IIIIII"
        raw = [struct.unpack_from(fmt, data, shoff + k * shes) for k in range(min(shn, 4096))]
        names = b""
        if shstr < len(raw):
            names = data[raw[shstr][4]:raw[shstr][4] + raw[shstr][5]]
        secs = [(names[nm:names.find(b"\0", nm)].decode("latin-1"), va, off, size if ty != 8 else 0, bool(fl & 4))
                for nm, ty, fl, va, off, size in raw if va]
        return (64 if b64 else 32), secs, struct.unpack_from("<H", data, 16)[0] == 3
    pe = _pe_layout(data)
    if not pe:
        return None
    p = int.from_bytes(data[0x3c:0x40], "little")
    mach, opt = struct.unpack_from("<H", data, p + 4)[0], p + 24
    if mach not in (0x14c, 0x8664):
        return None
    b64 = struct.unpack_from("<H", data, opt)[0] == 0x20b
    base = struct.unpack_from("<Q", data, opt + 24)[0] if b64 else struct.unpack_from("<I", data, opt + 28)[0]
    nsec, optsz = struct.unpack_from("<H12xH", data, p + 6)
    secs = []
    for k, (n, va, vs, rp, rs) in enumerate(pe[1]):
        ch = struct.unpack_from("<I", data, opt + optsz + 40 * k + 36)[0]
        secs.append((n, base + va, rp, min(vs or rs, rs), bool(ch & 0x20000000)))
    return (64 if b64 else 32), secs, False


def _elf_funcs(data):
    """[(value, size, name)] FUNC symbols (symtab + dynsym), sorted; [] when stripped / not ELF."""
    if data[:4] != b"\x7fELF" or data[5] != 1:
        return []
    b64 = data[4] == 2
    shoff = struct.unpack_from("<Q" if b64 else "<I", data, 40 if b64 else 32)[0]
    shes, shn = struct.unpack_from("<HH", data, 58 if b64 else 46)
    sh = "<4xI8x8xQQIi8xQ" if b64 else "<4xI4x4xIIIi4xI"
    secs = [struct.unpack_from(sh, data, shoff + k * shes) for k in range(min(shn, 4096))]
    out = []
    for ty, off, size, link, _, ent in secs:
        if ty not in (2, 11) or not 0 <= link < len(secs):
            continue
        so, sn = secs[link][1], secs[link][2]
        ent = ent or (24 if b64 else 16)
        for k in range(min(size // ent, 400_000)):
            o = off + k * ent
            if b64:
                nm, info, val, sz = struct.unpack_from("<IB3xQQ", data, o)
            else:
                nm, val, sz, info = struct.unpack_from("<IIIB", data, o)
            if info & 0xF == 2 and val and nm < sn:
                z = data.find(b"\0", so + nm, so + sn)
                out.append((val, sz, bytes(data[so + nm:z if z >= 0 else so + sn]).decode("latin-1")))
    return sorted(set(out))


_JCC_LEN = {"jle": 1, "jbe": 1, "jng": 1, "jna": 1}   # bound + 1 (inclusive compare)


def _decoder_xrefs(data, bits, secs, pie, lo, hi, chunk=65536, cap=4096):
    """Code VAs (approximate instruction starts) whose RIP-relative disp32 (last in the instruction, mod=00 rm=101) /
    absolute imm32 lands in [lo, hi). Inside a 64 KB window of .text the disp's top 16 bits take 1-2 values, so the scan
    is a few bytes.find per window (no per-instruction Python loop over 15+ MB of code); capstone re-checks each."""
    out = []
    for _, va, off, size, ex in secs:
        if not ex or not size:
            continue
        end = min(off + size, len(data))
        if bits == 64:
            for a in range(off + 2, end - 4, chunk):
                b = min(a + chunk, end - 4)                 # disp starts p in [a, b)
                ea = va + (a - off) + 4                     # next-insn VA for a disp at file offset a
                dmin, dmax = lo - (ea + (b - a)), hi - 1 - ea
                for h in range(dmin >> 16, (dmax >> 16) + 1):
                    pat = (h & 0xFFFF).to_bytes(2, "little")
                    i = data.find(pat, a + 2, b + 2)
                    while i >= 0:
                        p = i - 2
                        if data[p - 1] & 0xC7 == 5:
                            t = va + (p - off) + 4 + int.from_bytes(data[p:p + 4], "little", signed=True)
                            if lo <= t < hi:
                                out.append(va + (p - off) - 3)
                        i = data.find(pat, i + 1, b + 2)
                if len(out) > cap:
                    break
        if not pie:
            for h in range(lo >> 8, ((hi - 1) >> 8) + 1):
                pat = (h & 0xFFFFFF).to_bytes(3, "little")
                i = data.find(pat, off + 1, end)
                while i >= 0 and len(out) < cap:
                    if lo <= int.from_bytes(data[i - 1:i + 3], "little") < hi:
                        out.append(va + i - 1 - off)
                    i = data.find(pat, i + 1, end)
    return sorted(set(out))


def _va_off(secs, va):
    for _, sva, off, size, _ in secs:
        if sva <= va < sva + size:
            return va - sva + off
    return None


def _guess_start(data, secs, va):
    """Nearest function prologue at/before code VA `va` (endbr64, else push rbp; mov rbp,rsp / push ebp; mov ebp,esp)."""
    o = _va_off(secs, va)
    if o is None:
        return None
    lo = max(0, o - 0x4000)
    win = data[lo:o + 1]
    cands = [win.rfind(b"\xf3\x0f\x1e\xfa"), win.rfind(b"\xf3\x0f\x1e\xfb"), win.rfind(b"\x55\x48\x89\xe5"),
             win.rfind(b"\x55\x89\xe5")]
    best = max(cands)
    if best < 0:
        return None
    if best >= 4 and win[best - 4:best] == b"\xf3\x0f\x1e\xfa":   # endbr64 heads the push rbp frame
        best -= 4
    return va - (o - (lo + best))


def _rfam(name):
    """x86 register family: al/ax/eax/rax -> ax, sil/esi/rsi -> si, r8b/r8d/r8 -> r8 ("" for none)."""
    name = name or ""
    if name[:1] == "r" and name[1:2].isdigit():
        return name.rstrip("bwd")
    n = name[1:] if len(name) == 3 and name[0] in "re" else name
    return {"al": "ax", "ah": "ax", "bl": "bx", "bh": "bx", "cl": "cx", "ch": "cx", "dl": "dx", "dh": "dx",
            "sil": "si", "dil": "di", "bpl": "bp", "spl": "sp"}.get(n, n)


def _decoder_loop(insns, start, end, refs):
    """(algorithm, key, immediates, loop_length) from the function's loops; None when no loop does a byte op."""
    import capstone
    import capstone.x86 as X
    byaddr = [i.address for i in insns]
    loops = []
    for k, i in enumerate(insns):
        if i.group(capstone.CS_GRP_JUMP) and i.operands and i.operands[0].type == X.X86_OP_IMM:
            t = i.operands[0].imm
            if start <= t <= i.address and i.mnemonic != "jmp":
                loops.append((t, k, i))
    bound256 = False
    best = None
    rank = {"rol": 0, "ror": 0, "xor": 1, "rolling-xor": 2, "add": 3, "sub": 3, "not": 4}
    for t, kj, jcc in loops:
        body = insns[bisect.bisect_left(byaddr, t):kj + 1]
        cmp_imm = None
        for i in body:   # the cmp/test feeding the backward jcc (an earlier `cmp x, 0xff` is no bound)
            if i.mnemonic in ("cmp", "test"):
                cmp_imm = i.operands[1].imm if i.mnemonic == "cmp" and len(i.operands) == 2 and \
                    i.operands[1].type == X.X86_OP_IMM else None
        if cmp_imm is not None and cmp_imm + _JCC_LEN.get(jcc.mnemonic, 0) == 256 and \
                jcc.mnemonic in ("jne", "jnz", "jb", "jl", "jbe", "jle", "jna", "jng") and \
                sum(len(i.operands) == 2 and i.operands[0].type == X.X86_OP_MEM and i.operands[0].size == 1
                    for i in body if i.mnemonic == "mov") >= 2:   # the KSA swap stores S[i] and S[j]
            bound256 = True
        # the data window: first byte-sized memory load .. the next byte-sized memory store
        win, st = [], None
        for i in body:
            ops = i.operands
            if st is None:
                if len(ops) == 2 and ops[1].type == X.X86_OP_MEM and ops[1].size == 1 and \
                        i.mnemonic in ("movzx", "movsx", "mov"):
                    st = i
                continue
            if len(ops) == 2 and ops[0].type == X.X86_OP_MEM and ops[0].size == 1 and i.mnemonic == "mov":
                break
            win.append(i)
        if st is None:
            continue
        found, imms = None, []
        xvar = add = kadd = None
        data_r = {_rfam(st.reg_name(st.operands[0].reg))}   # registers holding the loaded byte (simple data flow)
        for i in win:
            ops, m = i.operands, i.mnemonic
            d0 = _rfam(i.reg_name(ops[0].reg)) if ops and ops[0].type == X.X86_OP_REG else None
            r1 = _rfam(i.reg_name(ops[1].reg)) if len(ops) == 2 and ops[1].type == X.X86_OP_REG else None
            if d0 is None:
                continue
            if m in ("mov", "movzx", "movsx", "lea") and len(ops) == 2:
                if r1 in data_r or (m == "lea" and _rfam(i.reg_name(ops[1].mem.base)) in data_r):
                    data_r.add(d0)
                else:
                    data_r.discard(d0)
            if d0 not in data_r:
                if m in ("add", "sub") and len(ops) == 2 and ops[1].type == X.X86_OP_IMM:
                    kadd = kadd or (m, ops[1].imm)   # key-register update (rolling key start)
                continue
            if m in ("rol", "ror") and len(ops) == 2 and ops[1].type == X.X86_OP_IMM:
                found = found or (m, ops[1].imm & 7)
                imms.append(ops[1].imm)
            elif m == "xor" and len(ops) == 2 and ops[1].type == X.X86_OP_IMM and ops[1].imm & 0xFF:
                found = found if found and rank[found[0]] <= 1 else ("xor", ops[1].imm & 0xFF)
                imms.append(ops[1].imm & 0xFFFFFFFF)
            elif m == "xor" and len(ops) == 2 and ops[1].type in (X.X86_OP_REG, X.X86_OP_MEM) and r1 != d0:
                xvar = True
                if kadd:
                    imms.append(kadd[1] & 0xFFFFFFFF)
            elif m in ("add", "sub") and len(ops) == 2 and ops[1].type == X.X86_OP_IMM:
                add = add or (m, ops[1].imm)
                imms.append(ops[1].imm & 0xFFFFFFFF)
            elif m == "lea" and ops[1].type == X.X86_OP_MEM and ops[1].mem.index == 0 and ops[1].mem.disp and \
                    _rfam(i.reg_name(ops[1].mem.base)) in data_r:
                d = ops[1].mem.disp
                add = add or (("sub", -d) if d < 0 else ("add", d))
                imms.append(abs(d))
            elif m == "not":
                found = found or ("not", 0xFF)
        if not found and xvar:
            found = ("rolling-xor", kadd[1] & 0xFF) if kadd else ("xor-var", None)
        if not found and add:
            found = (add[0], add[1] & 0xFF)
        if not found:
            continue
        n = None
        if cmp_imm is not None and 0 < cmp_imm < 1 << 24:
            n = cmp_imm + _JCC_LEN.get(jcc.mnemonic, 0)
        cand = (rank.get(found[0], 5), found[0], found[1], imms, n)
        if best is None or cand[0] < best[0]:
            best = cand
    if best is None:
        return None
    alg = best[1]
    if alg == "xor-var":   # xor with a register / memory key (the header key byte, a key table): `xor` speculative
        alg = "rc4" if bound256 else "xor"
    return alg, best[2], best[3], best[4]


def decoder_facts(data, offset=None, hit=None):
    """Speculative facts about the routine that decodes the stored HCFG blob: {blob_va, xrefs (code VAs), function
    (FUNC symbol, "none" when stripped), function_va, algorithm (xor/add/sub/rol/ror/not/rolling-xor/rc4 or
    "none" = referenced but no decode loop), key (the loop's immediate), immediates, loop_length, header_key,
    key_equals_header ("true"/"false"/"none")}. `hit` (an HcfgHit) or `offset` (file offset of the stored blob) --
    default hcfg_find(data). None when not an x86 ELF/PE, no blob, or no code reference."""
    try:
        import capstone
        import capstone.x86 as X
        data = bytes(data)
        mp = _exec_map(data)
        if not mp:
            return None
        bits, secs, pie = mp
        if hit is None and offset is None:
            hit = hcfg_find(data)
        if hit is not None:
            offset = hit.offset
        if offset is None:
            return None
        bva = next((va + offset - off for _, va, off, size, _ in secs if off <= offset < off + size and size), None)
        if bva is None:
            return None
        hi = bva + (12 + hit.length if hit is not None else 64)
        lo = bva - 32   # Swift large-string objects point 0x20 before the bytes (lea rsi,[blob-0x10] + flags)
        md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64 if bits == 64 else capstone.CS_MODE_32)
        md.detail = True
        funcs = _elf_funcs(data)
        fstarts = [f[0] for f in funcs]
        seen, refs, out = set(), [], None
        for xva in _decoder_xrefs(data, bits, secs, pie, lo, hi):
            k = bisect.bisect_right(fstarts, xva) - 1
            if k >= 0 and funcs[k][0] <= xva < funcs[k][0] + max(funcs[k][1], 1):
                start, size, name = funcs[k]
            else:
                start, size, name = _guess_start(data, secs, xva), 0x2000, "none"
                if start is None:
                    continue
            if start in seen:
                continue
            o = _va_off(secs, start)
            if o is None:
                continue
            insns, real, fwd = [], [], start
            for i in md.disasm(data[o:o + min(size, 0x4000)], start):
                insns.append(i)
                for op in i.operands:
                    t = None
                    if op.type == X.X86_OP_MEM:
                        t = op.mem.disp + (i.address + i.size if op.mem.base == X.X86_REG_RIP else 0)
                    elif op.type == X.X86_OP_IMM:
                        t = op.imm
                        if i.group(capstone.CS_GRP_JUMP) and t > fwd:
                            fwd = t
                    if t is not None and lo <= t < hi and not i.group(capstone.CS_GRP_JUMP):
                        real.append(i.address)
                if name == "none" and i.mnemonic in ("ret", "jmp") and i.address >= max(xva, fwd) and \
                        (i.mnemonic == "ret" or i.operands[0].type != X.X86_OP_IMM or
                         not start <= i.operands[0].imm < i.address):
                    break
                if len(insns) > 8000:
                    break
            if not real:
                continue
            seen.add(start)
            refs += real
            lp = _decoder_loop(insns, start, insns[-1].address + 1, real) if out is None or \
                out["algorithm"] == "none" else None
            if out is None or lp:
                out = {"blob_va": bva, "function": name, "function_va": start, "algorithm": "none", "key": "none",
                       "immediates": [], "loop_length": "none"}
                if lp:
                    out.update(algorithm=lp[0], key=lp[1] if lp[1] is not None else "none", immediates=lp[2],
                               loop_length=lp[3] if lp[3] is not None else "none")
            if len(seen) > 64:
                break
        if out is None:
            return None
        out["xrefs"] = sorted(set(refs))
        out["header_key"] = hit.key if hit is not None else "none"
        out["key_equals_header"] = ("true" if out["key"] == hit.key else "false") \
            if hit is not None and isinstance(out["key"], int) else "none"
        out["speculative"] = True
        return out
    except Exception:  # noqa: BLE001 -- untrusted bytes: cannot answer
        return None


def decoder_field(data, name, **kw):
    """One decoder_facts value as an answer string (VAs / key as 0x-hex, loop_length decimal); "none" when absent."""
    try:
        f = decoder_facts(data, **kw)
        v = (f or {}).get(name, "none")
        if isinstance(v, bool):
            return str(v).lower()
        if isinstance(v, int) and name != "loop_length":
            return hex(v)
        return v if isinstance(v, (str, list)) else str(v)
    except Exception:  # noqa: BLE001
        return "none"


# --- API HASHING resolver (speculative facts): imports resolved by a 32-bit name hash instead of by name. Precomputed
# tables of common libc / kernel32 / ntdll / user32 / advapi32 / ws2_32 / wininet export names under the usual shellcode
# / loader algorithms; hits are imm32s in executable sections (x86: capstone-confirmed instruction immediates, any
# other arch: raw LE dwords) plus 4-aligned dwords of the read-only / data sections (hash tables). The algorithm is the
# variant with the most distinct names hit; resolved_apis = its names in file (code) order, first occurrence.

